window.__BOOK__['p09'].push([{"id":"b216-1","bab":"الجزء 17","sec":"ذكر الكميت ونسبه وخبره","page":"ج17 ص3","text":"هو الكميت بن زيد بن خنيس بن مجالد بن وهيب بن عمرو بن سبيع وقيل الكميت بن زيد بن خنيس بن مجالد بن ذؤيبة بن قيس بن عمرو بن سبيع بن مالك بن سعد بن ثعلبة بن دودان بن أسد بن خزيمة بن مدركة بن إلياس بن مضر بن نزار شاعر مقدم عالم بلغات العرب خبير بأيامها من شعراء مضر وألسنتها والمتعصبين على القحطانية المقارنين المقارعين لشعرائهم العلماء بالمثالب والأيام المفاخرين بها وكان في أيام بني أمية ولم يدرك الدولة العباسية ومات قبلها وكان معروفا بالتشيع لبني هاشم مشهورا بذلك وقصائده الهاشميات من جيد شعره ومختاره ولم تزل عصبيته للعدنانية ومهاجاته شعراء اليمن متصلة والمناقضة بينه وبينهم شائعة في حياته وبعد وفاته حتى ناقض دعبل وابن أبي عيينة قصيدته المذهبة بعد وفاته\nوأجابهما أبو البلقاء البصري مولى بني هاشم عنها وذلك يذكر في موضع آخر يصلح له من هذا الكتاب إن شاء الله أخبرني محمد بن الحسن بن دريد عن أبي حاتم عن الأصمعي عن خلف الأحمر أنه رأى الكميت يعلم الصبيان في مسجد بالكوفة قال ابن قتيبة في خبره خاصة وكانت بينه وبين الطرماح خلطة ومودة وصفاء لم يكن بين اثنين قال فحدثني بعض أصحابه عن محمد بن سهل راوية الكميت قال أنشدت الكميت قول الطرماح\n(إذا قبضت نفس الطرماح أخلقت ... عرا المجد واسترخى عنان القصائد)\nال إي والله وعنان الخطابة والرواية قال وهذه الأحوال بينهما على تفاوت المذاهب والعصبية والديانة كان الكميت شيعيا عصبيا عدنانيا من شعراء مضر متعصبا لأهل الكوفة والطرماح خارجي صفري قحطاني عصبي لقحطان من شعراء اليمن متعصب لأهل الشام فقيل لهما ففيم اتفقتما هذا الاتفاق مع اختلاف سائر الأهواء قالا اتفقنا على بغض العامة أخبرني عمي قال حدثني محمد بن سعد الكراني قال حدثنا أبو عمر العمري عن لقيط قال","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":0,"spl":"ذكر الكميت ونسبه وخبره — الكميت عالم بأيام العرب وأشعارها","tags":["الكميت","اللهو والمزاح","الوصف والطبيعة"],"loc":2966},
{"id":"b216-2","bab":"الجزء 17","sec":"الكميت عالم بأيام العرب وأشعارها","page":"ج17 ص5","text":"اجتمع الكميت بن زيد وحماد الراوية في مسجد الكوفة فتذاكرا أشعار العرب وأيامها فخالفه حماد في شيء ونازعه فقال له الكميت أتظن أنك أعلم مني بأيام العرب وأشعارها\nقال وما هو إلا الظن هذا والله هو اليقين فغضب الكميت ثم قال له لكم شاعر بصير يقال له عمرو ابن فلان تروي ولكم شاعر أعور أو أعمى اسمه فلان ابن عمرو تروي فقال حماد قولا لم يحفظه فجعل الكميت يذكر رجلا رجلا من صنف صنف ويسأل حمادا هل يعرفه فإذا قال لا أنشده جزءا منه حتى ضجرنا ثم قال له الكميت فإني سائلك عن شيء من الشعر فسأله عن قول الشاعر\n(طرحوا أصحابهم في ورطة ... قذفك المقلة شطر المعترك)\nلم يعلم حماد تفسيره فسأله عن قول الآخر\n(تدريننا بالقول حتى كأنما ... تدرين ولدانا تصيد الرهادنا)\nأفحم حماد فقال له قد أجلتك إلى الجمعة الأخرى فجاء حماد ولم يأت بتفسيرهما وسأل الكميت أن يفسرهما له فقال المقلة حصاة أو نواة من نوى المقل يحملها القوم معهم إذا سافروا وتوضع في الإناء ويصب عليها الماء حتى يغمرها فيكون ذلك علامة يقتسمون بها الماء والشطر النصيب والمعترك الموضع الذي يختصمون فيه في الماء فيلقونها هناك عند الشر وقوله تدريننا يعني النساء أي ختلننا فرميننا والرهادن طير بمكة كالعصافير","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":0,"spl":"ذكر الكميت ونسبه وخبره — الكميت عالم بأيام العرب وأشعارها","tags":["الكميت","السفر والحج"],"loc":2967},
{"id":"b216-3","bab":"الجزء 17","sec":"الكميت يحبس في المخيس","page":"ج17 ص6","text":"وكان خالد بن عبد الله القسري - فيما حدثني به عيسى بن الحسين الوراق قال أخبرنا أحمد بن الحارث الفزاري عن ابن الأعرابي وذكره محمد بن أنس السلامي عن المستهل بن الكميت وذكره ابن كناسة عن جماعة من بني أسد - قد بلغه أن الكميت أنشد قصيدته التي يهجو فيها اليمن وهي\n(ألا حييت عنا يا مدينا ... )\nأحفظته عليه فروى جارية حسناء قصائده الهاشميات وأعدها ليهديها إلى هشام وكتب إليه بأخبار الكميت وهجائه بني أمية وأنفذ إليه قصيدته التي يقول فيها\n(فيا رب هل إلا بك النصر يبتغى ... ويا رب هل إلا عليك المعول !)\nهي طويلة يرثي فيها زيد بن علي وابنه الحسين بن زيد ويمدح بني هاشم فلما قرأها أكبرها وعظمت عليه واستنكرها وكتب إلى خالد يقسم عليه أن يقطع لسان الكميت ويده فلم يشعر الكميت إلا والخيل محدقة بداره فأخذ وحبس في\nالمخيس وكان أبان بن الوليد عاملا على واسط وكان الكميت صديقه فبعث إليه بغلام على بغل وقال له أنت حر إن لحقته والبغل لك وكتب إليه قد بلغني ما صرت إليه وهو القتل إلا أن يدفع الله عز و جل وأرى لك أن تبعث إلى حبى - يعني زوجة الكميت وهي بنت نكيف بن عبد الواحد وهي ممن يتشيع أيضا - فإذا دخلت إليك تنقبت نقابها ولبست ثيابها وخرجت فإني أرجو ألا يؤبه لك فأرسل الكميت إلى أبي وضاح حبيب بن بديل وإلى فتيان من بني عمه من مالك بن سعيد فدخل عليه حبيب فأخبره الخبر وشاوره فيه فسدد رأيه ثم بعث إلى حبى امرأته فقص عليها القصة\nوقال لها أي ابنة عم إن الوالي لا يقدم عليك ولا يسلمك قومك ولو خفته عليك لما عرضتك له فألبسته ثيابها وإزارها وخمرته وقالت له أقبل وأدبر ففعل فقالت ما أنكر منك شيئا إلا يبسا في كتفك فاخرج على اسم الله وأخرجت معه جارية لها فخرج وعلى باب السجن أبو وضاح ومعه فتيان من أسد فلم يؤبه له ومشى والفتيان بين يديه إلى سكة شبيب بناحية الكناسة فمر بمجلس من مجالس بني تميم فقال بعضهم رجل ورب الكعبة وأمر\nغلامه فاتبعه فصاح به أبو الوضاح يا كذا وكذا لا أراك تتبع هذه المرأة منذ اليوم وأومأ إليه بنعله فولى العبد مدبرا وأدخله أبو الوضاح منزله ولما طال على السجان الأمر نادى الكميت فلم يجبه فدخل ليعرف خبره فصاحت به المرأة وراءك لا أم لك فشق ثوبه ومضى صارخا إلى باب خالد فأخبره الخبر فأحضر حبى فقال لها يا عدوة الله احتلت على أمير المؤمنين وأخرجت عدوه لأمثلن بك ولأصنعن ولأفعلن فاجتمعت بنو أسد إليه وقالوا ما سبيلك على امرأة منا خدعت فخافهم فخلى سبيلها\nقال وسقط غراب على الحائط فنعب فقال الكميت لأبي وضاح إني لمأخوذ وإن حائطك لساقط فقال سبحان الله هذا ما لا يكون إن شاء الله فقال له لا بد من أن تحولني فخرج به إلى بني علقمة - وكانوا يتشيعون - فأقام فيهم ولم يصبح حتى سقط الحائط الذي سقط عليه الغراب","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":1,"spl":"الكميت يحبس في المخيس","tags":["الكميت","الهجاء"],"loc":2968,"partial":1},
{"id":"b216-5","bab":"الجزء 17","sec":"خروجه إلى الشام — مدائحه في بني أمية","page":"ج17 ص8 – ج17 ص10","text":"قال ابن الأعرابي قال المستهل وأقام الكميت مدة متواريا حتى إذا أيقن أن الطلب قد خف عنه خرج ليلا في جماعة من بني أسد على خوف ووجل وفيمن معه صاعد غلامه قال وأخذ الطريق على القطقطانة - وكان عالما بالنجوم مهتديا بها - فلما صار سحير صاح بنا هوموا يا فتيان فهومنا وقام يصلي قال المستهل فرأيت شخصا فتضعضعت له فقال مالك قلت أرى\nشيئا مقبلا فنظر إليه فقال هذا ذئب قد جاء يستطعمكم فجاء الذئب فربض ناحية فأطعمناه يد جزور فتعرقها ثم أهوينا له بإناء فيه ماء فشرب منه وارتحلنا فجعل الذئب يعوي فقال الكميت ما له ويله ألم نطعمه ونسقه وما أعرفني بما يريد هو يعلمنا أنا لسنا على الطريق تيامنوا يا فتيان فتيامنا فسكن عواؤه فلم نزل نسير حتى جئنا الشام فتوارى في بني أسد وبني تميم وأرسل إلى أشراف قريش - وكان سيدهم يومئذ عنبسة بن سعيد بن العاص - فمشت رجالات قريش بعضها إلى بعض وأتوا عنبسة فقالوا يا أبا خالد هذه مكرمة قد أتاك الله بها هذا الكميت بن زيد لسان مضر وكان أمير المؤمنين كتب في قتله فنجا حتى تخلص إليك وإلينا\nقال فمروه أن يعوذ بقبر معاوية ابن هشام بدير حنيناء فمضى الكميت فضرب فسطاطه عند قبره ومضى عنبسة فأتى مسلمة بن هشام فقال له يا أبا شاكر مكرمة أتيتك بها تبلغ الثريا إن اعتقدتها فإن علمت أنك تفي بها وإلا كتمتها\nقال وما هي فأخبره الخبر وقال إنه قد مدحكم عامة وإياك خاصة بما لم يسمع بمثله فقال علي خلاصه فدخل على أبيه هشام وهو عند أمه في غير وقت دخول فقال هشام أجئت لحاجة\nقال نعم قال هي مقضية إلا أن يكون الكميت فقال ما أحب أن تستثني علي في حاجتي وما أنا والكميت فقالت أمه والله لتقضين حاجته كائنة ما كانت\nقال قد قضيتها ولو أحاطت بما بين قطريها قال هي الكميت يا أمير المؤمنين وهو آمن بأمان الله عز و جل وأماني وهو شاعر مضر وقد قال فينا قولا لم يقل مثله قال قد أمنته وأجزت أمانك له فاجلس له مجلسا ينشدك فيه ما قال فينا\nفعقد له وعنده الأبرش الكلبي فتكلم بخطبة ارتجلها ما سمع بمثلها قط وامتدحه بقصيدته الرائية ويقال إنه قالها ارتجالا وهي قوله\n(قف بالديار وقوف زائر ... )\nمضى فيها حتى انتهى إلى قوله\n(ماذا عليك من الوقوف ... بها وأنك غير صاغر)\n(درجت عليها الغاديات ... الرائحات من الأعاصر)\nفيها يقول\n(فالآن صرت إلى أمية ... والأمور إلى المصاير)\nجعل هشام يغمز مسلمة بقضيب في يده فيقول اسمع اسمع ثم استأذنه في مرثية ابنه معاوية فأذن له فأنشده قوله\n(سأبكيك للدنيا وللدين إنني ... رأيت يد المعروف بعدك شلت)\n(فدامت عليك بالسلام تحية ... ملائكة الله الكرام وصلت)\nبكى هشام بكاء شديدا فوثب الحاجب فسكته ثم جاء الكميت إلى منزله آمنا فحشدت له المضرية بالهدايا وأمر له مسلمة بعشرين ألف درهم وأمر له هشام بأربعين ألف درهم وكتب إلى خالد بأمانه وأمان أهل بيته وأنه لا سلطان له عليهم قال وجمعت له بنو أمية بينها مالا كثيرا قال ولم يجمع من قصيدته تلك يومئذ إلا ما حفظه الناس منها فألف وسئل عنها فقال ما أحفظ منها شيئا إنما هو كلام ارتجلته فقال وودع هشاما وأنشده قوله فيه\nذكر القلب إلفه المذكورا\nقال محمد بن كناسة وكان الكميت يقول سبقت الناس في هذه القصيدة من أهل الجاهلية والإسلام إلى معنى ما سبقت إليه في صفة الفرس حين أقول\n(يبحث الترب عن كواسر في المشرب ... لا يجشم السقاة الصفيرا)\nذه رواية ابن عمار وقد روى فيه غير هذا","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":2,"spl":"خروجه إلى الشام — مدائحه في بني أمية","tags":["الكميت"],"loc":2969,"partial":1},
{"id":"b216-6","bab":"الجزء 17","sec":"سبب المنافرة بين الكميت وخالد","page":"ج17 ص11","text":"وقيل في سبب المنافرة بين خالد والكميت غير هذا نسخته من كتاب محمد بن يحيى الخراز قال حدثني أحمد بن إبراهيم الحاسب قال حدثني عبد الرحمن بن داود بن أبي أمية البلخي\nقال كان حكيم بن عياش الأعور الكلبي ولعا بهجاء مضر فكانت شعراء مضر تهجوه ويجيبهم وكان الكميت يقول هو والله أشعر منكم قالوا فأجب الرجل\nقال إن خالد بن عبد الله القسري محسن إلي فلا أقدر أن أرد عليه قالوا فاسمع بأذنك ما يقول في بنات عمك وبنات خالك من الهجاء وأنشدوه ذلك فحمى الكميت لعشيرته فقال المذهبة\n(ألا حييت عنا يا مدينا ... )\nأحسن فيها وبلغ خالدا خبرها فقال لا أبالي ما لم يجر لعشيرتي ذكر فأنشدوه قوله\n(ومن عجب علي لعمر أم ... غذتك وغير هاتيا يمينا)\n(تجاوزت المياه بلا دليل ... ولا علم تعسف مخطئينا)\nإنك والتحول من معد ... كهيلة قبلنا والحالبينا\n(تخطت خيرهم حلبا ونسئا ... إلى المولى المغادر هاربينا)\n(كعنز السوء تنطح عالفيها ... وترميها عصي الذابحينا)\nبلغ ذلك خالدا فقال فعلها والله لأقتلنه ثم اشترى ثلاثين جارية بأغلى ثمن وتخيرهن نهاية في حسن الوجوه والكمال والأدب فرواهن الهاشميات ودسهن مع نخاس إلى هشام بن عبد الملك فاشتراهن جميعا فلما أنس بهن استنطقهن فرأى فصاحة وأدبا فاستقرأهن القرآن فقرأن واستنشدهن الشعر فأنشدنه قصائد الكيمت الهاشميات فقال ويلكن من قائل هذا الشعر قلن الكميت بن زيد الأسدي\nقال وفي أي بلد هو قلن في العراق ثم بالكوفة فكتب إلى خالد وهو عامله على العراق ابعث إلي برأس الكميت بن زيد فبعث خالد إلى الكميت في الليل فأخذه وأودعه السجن ولما كان من الغد أقرأ من حضره من مضر كتاب هشام واعتذر إليهم من قتله وآذنهم في إنفاذ الأمر فيه في غد فقال لأبان بن الوليد البجلي - وكان صديقا للكميت - انظر ما ورد في صديقك فقال عز علي والله ما به ثم قام أبان فبعث إلى الكميت فأنذره فوجه إلى امرأته","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":3,"spl":"سبب المنافرة بين الكميت وخالد","tags":["الكميت"],"loc":2970,"partialRef":{"sid":"b216-3","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b216-7","bab":"الجزء 17","sec":"الكميت وهشام بن عبد الملك","page":"ج17 ص12","text":"ثم ذكر الخبر في خروجه ومقامها مكانه كما ذكر من تقدمه وقال فيه فأتى\nمسملة بن عبد الملك فاستجار به فقال إني أخشى ألا ينفعك جواري عنده ولكن استجر بابنه مسلمة بن هشام فقال كن أنت السفير بيني وبينه في ذلك ففعل مسلمة\nوقال لابن أخيه قد أتيتك بشرف الدهر واعتقاد الصنيعة في مضر وأخبره الخبر فأجاره مسلمة بن هشام وبلغ ذلك هشاما فدعا به ثم قال أتجير على أمير المؤمنين بغير أمره فقال كلا ولكني انتظرت سكون غضبه\nقال أحضرنيه الساعة فإنه لا جوار لك فقال مسلمة للكميت يا أبا المستهل إن أمير المؤمنين أمرني بإحضارك قال أتسلمني يا أبا شاكر قال كلا ولكني أحتال لك ثم\nقال له إن معاوية بن هشام مات قريبا وقد جزع عليه جزعا شديدا فإذا كان من الليل فاضرب رواقك على قبره وأنا أبعث إليك بنيه يكونون معك في الرواق فإذا دعا بك تقدمت إليهم أن يربطوا ثيابهم بثيابك ويقولوا هذا استجار بقبر أبينا ونحن أحق من أجاره فأصبح هشام على عادته متطلعا من قصره إلى القبر فقال من هذا فقالوا لعله مستجير بالقبر فقال يجار من كان إلا الكميت فإنه لا جوار له فقيل فإنه الكميت\nقال يحضر أعنف إحضار فلما دعي به ربط الصبيان ثيابهم بثيابه فلما نظر هشام إليهم اغرورقت عيناه واستعبر وهم يقولون يا أمير المؤمنين استجار بقبر أبينا وقد مات ومات حظه من الدنيا فاجعله هبة له ولنا ولا تفضحنا فيمن استجار به فبكى هشام حتى انتحب ثم أقبل على الكميت فقال له يا كميت أنت القائل\n(وإلا تقولوا غيرها تتعرفوا ... نواصيها تردي بنا وهي شزب)\nقال لا والله ولا أتان من أتن الحجاز وحشية فحمد الله وأثنى عليه وصلى على نبيه ثم قال أما بعد فإني كنت أتدهدى في غمرة وأعوم في بحر غواية أخنى علي خطلها واستفزني وهلها فتحيرت في الضلالة وتسكعت في الجهالة مهرعا عن الحق جائرا عن القصد أقول الباطل ضلالا وأفوه بالبهتان وبالا وهذا مقام العائذ مبصر الهدى ورافض العمى فاغسل عني يا أمير المؤمنين الحوبة بالتوبة واصفح عن الزلة واعف عن الجرمة ثم قال\n(كم قال قائلكم لعالك ... عند عثرته لعاثر)\n(وغفرتم لذوي الذنوب ... من الأكابر والأصاغر)\n(أبني أمية إنكم ... أهل الوسائل والأوامر)\n(ثقتي لكل ملمة ... وعشيرتي دون العشائر)\n(أنتم معادن للخلافة ... فة كابرا من بعد كابر)\n(بالتسعة المتتابعين ... خلائفا وبخير عاشر)\n(وإلى القيامة لا تزال ... لشافع منكم وواتر)\nثم قطع الإنشاد وعاد إلى خطبته فقال إغضاء أمير المؤمنين وسماحته وصباحته ومناط المنتجعين بحبله من لا تحل حبوته لإساءة المذنبين فضلا عن استشاطة غضبه بجهل الجاهلين فقال له ويلك يا كميت من زين لك الغواية ودلاك في العماية قال الذي أخرج أبانا من الجنة وأنساه العهد فلم يجد له عزما فقال إيه أنت القائل\n(فيا موقدا نارا لغيرك ضوؤها ... ويا حاطبا في غير حبلك تحطب)\nقال بل أنا القائل\n(إلى آل بيت أبي مالك ... مناخ هو الأرحب الأسهل)\n(نمت بأرحامنا الداخلات ... من حيث لا ينكر المدخل)\n(ببرة والنضر والمالكين ... رهط هم الأنبل الأنبل)\n(وبابنى ] خزيمة بدر السماء ... والشمس مفتاح ما نأمل)\n(وجدنا قريشا قريش البطاح ... على ما بنى الأول الأول)\n(بهم صلح الناس بعد الفساد ... وحيص من الفتق ما رعبلوا)\nال له وأنت القائل\n(لا كعبد المليك أو كوليد ... أو سليمان بعد أو كهشام)\n(من يمت لا يمت فقيدا ومن يحيى ... فلا ذو إل ولا ذو ذمام)\nيلك يا كميت جعلتنا ممن لا يرقب في مؤمن إلا ولا ذمة فقال بل أنا القائل يا أمير المؤمنين\n(فالآن صرت إلى أمية ... والأمور إلى المصاير)\n(والآن صرت بها المصيب ... كمهتد بالأمس حائر)\n(يابن العقائل للعقائل ... والجحاجحة الأخاير)\n(من عبد شمس والأكابر ... من أمية فالأكابر)\n(إن الخلافة والإلاف ... برغم ذي حسد وواغر)\n(دلفا من الشرف التليد ... إليك بالرفد الموافر)\n(فحللت معتلج البطاح ... وحل غيرك بالظواهر)\nال له إيه فأنت القائل\n(فقل لبني أمية حيث حلوا ... وإن خفت المهند والقطيعا)\n(أجاع الله من أشبعتموه ... وأشبع من بجوركم أجيعا)\n(بمرضي السياسة هاشمي ... يكون حيا لأمته ربيعا)\nفقال لا تثريب يا أمير المؤمنين إن رأيت أن تمحو عني قولي الكاذب قال بماذا قال بقولي الصادق\n(أورثته الحصان أم هشام ... حسبا ثاقبا ووجها نضيرا)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":4,"spl":"الكميت وهشام بن عبد الملك","tags":["الكميت","المديح"],"loc":2971},
{"id":"b216-8","bab":"الجزء 17","sec":"الكميت وهشام بن عبد الملك","page":"ج17 ص12","text":"(وتعاطى به ابن عائشة البدر ... فأمسى له رقيبا نظيرا)\n(وكساه أبو الخلائف مروان ... سني المكارم المأثورا)\n(لم تجهم له البطاح ولكن ... وجدتها له مغارا ودورا)\nكان هشام متكئا فاستوى جالسا وقال هكذا فليكن الشعر - يقولها لسالم بن عبد الله بن عمر وكان إلى جانبه - ثم قال قد رضيت عنك يا كميت فقبل يده وقال يا أمير المؤمنين إن رأيت أن تزيد في تشريفي ولا تجعل لخالد علي إمارة قال قد فعلت وكتب له بذلك وأمر له بأربعين ألف درهم وثلاثين ثوبا هشامية وكتب إلى خالد أن يخلي سبيل امرأته ويعطيها عشرين ألفا وثلاثين ثوبا ففعل ذلك","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":5,"spl":"الكميت وهشام بن عبد الملك","tags":["الكميت"],"loc":2972},
{"id":"b216-9","bab":"الجزء 17","sec":"الكميت وخالد بن عبد الله","page":"ج17 ص17","text":"وله مع خالد أخبار بعد قدومه الكوفة بالعهد الذي كتب له منها أنه مر به خالد يوما وقد تحدث الناس بعزله عن العراق فلما جاز تمثل الكميت\n(أراها - وإن كانت تحب - كأنها ... سحابة صيف عن قليل تقشع)\nسمعه خالد فرجع وقال أما والله لا تنقشع حتى يغشاك منها شؤبوب برد ثم أمر به فجرد فضربه مائة سوط ثم خلى عنه ومضى هذه رواية ابن حبيب\nوقد أخبرني أحمد بن عبيد الله بن عمار قال حدثنا النوفلي علي بن محمد ابن سليمان أبو الحسن قال حدثني أبي قال كان هشام بن عبد الملك قد اتهم خالد بن عبد الله - وكان يقال إنه يريد خلعك - فوجد بباب هشام يوما رقعة فيها شعر فدخل بها على هشام فقرئت عليه وهي\n(تألق برق عندنا وتقابلت ... أثاف لقدر الحرب أخشى اقتبالها)\n(فدونك قدر الحرب وهي مقرة ... لكفيك واجعل دون قدر جعالها)\n(ولن تنتهي أو يبلغ الأمر حده ... فنلها برسل قبل ألا تنالها)\n(فتجشم منها ما جشمت من التي ... بسوراء هرت نحو حالك حالها)\n(تلاف أمور الناس قبل تفاقم ... بعقدة حزم لا تخاف انحلالها)\n(فما أبرم الأقوام يوما لحيلة ... من الأمر إلا قلدوك احتيالها)\n(وقد تخبر الحرب العوان بسرها ... - وإن لم تبح - من لا يريد سؤالها)\nأمر هشام أن يجمع له من بحضرته من الرواة فجمعوا فأمر بالأبيات فقرئت عليهم فقال شعر من تشبه هذه الأبيات فأجمعوا جميعا من ساعتهم أنه كلام الكميت بن زيد الأسدي فقال هشام نعم هذا الكميت ينذرني بخالد بن عبد الله ثم كتب إلى خالد بخبره وكتب إليه بالأبيات وخالد يومئذ بواسط\nفكتب خالد إلى واليه بالكوفة يأمره بأخذ الكميت وحبسه وقال لأصحابه إنه بلغني أن هذا يمدح بني هاشم ويهجو بني أمية فأتوني من شعره هذا بشيء فأتي بقصيدته اللامية التي أولها\n(ألا هل عم في رأيه متأمل ... وهل مدبر بعد الإساءة مقبل !)\nكتبها وأدرجها في كتاب إلى هشام يقول هذا شعر الكميت فإن كان قد صدق في هذا فقد صدق في ذاك فلما قرئت على هشام اغتاظ فلما قال\n(فيا ساسة هاتوا لنا من جوابكم ... ففيكم لعمري ذو أفانين مقول)\nشتد غيظه فكتب إلى خالد يأمره أن يقطع يدي الكميت ورجليه ويضرب عنقه ويهدم داره ويصلبه على ترابها فلما قرأ خالد الكتاب كره أن يستفسد عشيرته وأعلن الأمر رجاء أن يتخلص الكميت فقال لقد كتب إلي أمير المؤمنين وإني لأكره أن أستفسد عشيرته وسماه فعرف عبد الرحمن بن عنبسة بن سعيد ما أراد فأخرج غلاما له مولدا ظريفا فأعطاه بغلة له شقراء فارهة من بغال الخليفة\nوقال إن أنت وردت الكوفة فأنذرت الكميت لعله أن يتخلص من الحبس فأنت حر لوجه الله والبغلة لك ولك علي بعد ذلك إكرامك والإحسان إليك فركب البغلة وسار بقية يومه وليلته من واسط إلى الكوفة فصبحها فدخل الحبس متنكرا فخبر الكميت بالقصة فأرسل إلى امرأته وهي ابنة عمه يأمرها أن تجيئه ومعها ثياب من لباسها وخفان ففعلت فقال ألبسيني لبسة النساء\nففعلت ثم قالت له أقبل فأقبل وأدبر فأدبر فقالت ما أرى إلا يبسا في منكبيك اذهب في حفظ الله فخرج فمر بالسجان فظن أنه المرأة فلم يعرض له فنجا وأنشأ يقول\n(خرجت خروج القدح قدح ابن مقبل ... على الرغم من تلك النوابح والمشلي)\n(علي ثياب الغانيات وتحتها ... عزيمة أمر أشبهت سلة النصل)\nورد كتاب خالد على والي الكوفة يأمره فيه بما كتب به إليه هشام فأرسل إلى الكميت ليؤتى به من الحبس فينفذ فيه أمر خالد فدنا من باب البيت فكلمتهم المرأة وخبرتهم أنها في البيت وأن الكميت قد خرج فكتب بذلك إلى خالد فأجابه حرة كريمة آست ابن عمها بنفسها وأمر بتخليتها فبلغ الخبر الأعور الكلبي بالشام فقال قصديته التي يرمي فيها امرأة الكميت بأهل الحبس ويقول أسودين وأحمرينا فهاج الكميت ذلك حتى قال\n(ألا حييت عنا يا مدينا ... )\nهي ثلاثمائة بيت لم يترك فيها حيا من أحياء اليمن إلا هجاهم وتوارى وطلب فمضى إلى الشام فقال شعره الذي يقول فيه\n(قف بالديار وقوف زائر ... )\nي مسلمة بن عبد الملك ويقول\n(يا مسلم ابن أبي الوليد ... لميت إن شئت ناشر)\n(اليوم صرت إلى أمية ... والأمور إلى المصاير)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":6,"spl":"الكميت وخالد بن عبد الله","tags":["الكميت","الحب والغزل"],"loc":2973,"partialRef":{"sid":"b216-5","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b216-10","bab":"الجزء 17","sec":"الكميت وخالد بن عبد الله","page":"ج17 ص17","text":"ال أبو الحسن قال أبي إنما أراد اليوم صرت إلى أمية والأمور إلى مصايرها أي بني هاشم وبذلك احتج ابنه المستهل على أبي العباس حين عيره بقول أبيه هذا الشعر فأذن له ليلا فسأله أن يجيره على هشام فقال إني قد أجرت على أمير المؤمنين فأخفر جواري وقبيح برجل مثلي أن يخفر في كل يوم ولكني أدلك فاستجر بمسلمة بن هشام وبأمه أم الحكم بنت يحيى بن الحكم فإن أمير المؤمنين قد رشحه لولاية العهد فقال الكميت بئس الرأي أضيع دمي بين صبي وامرأة فهل غير هذا\nقال نعم مات معاوية ابن أمير المؤمنين وكان يحبه وقد جعل أمير المؤمنين على نفسه أن يزور قبره في كل أسبوع يوما - وسمى يوما بعينه - وهو يزوره في ذلك اليوم فامض فاضرب بناءك عند قبره واستجر به فإني سأحضر معه وأكلمه بأكثر من الجوار ففعل ذلك الكميت في اليوم الذي يأتيه فيه أبوه فجاء هشام ومعه مسلمة فنظر إلى البناء فقال لبعض أعوانه انظر ما هذا فرجع فقال الكميت بن زيد مستجير بقبر معاوية ابن أمير المؤمنين فأمر بقتله فكلمه مسلمة\nوقال يا أمير المؤمنين إن إخفار الأموات عار على الأحياء فلم يزل يعظم عليه الأمر حتى أجاره فحدثنا محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ\nقال حدثنا حجر بن عبد الجبار قال خرجت الجعفرية على خالد بن عبد الله القسري وهو يخطب على المنبر وهو لا يعلم بهم فخرجوا في التبابين ينادون لبيك جعفر لبيك جعفر وعرف خالد خبرهم وهو يخطب على المنبر فدهش فلم يعلم ما يقول فزعا فقال أطعموني ماء ثم خرج الناس إليهم فأخذوا فجعل يجيء بهم إلى المسجد ويؤخذ طن قصب فيطلى بالنفط ويقال للرجل احتضنه ويضرب حتى يفعل ثم يحرق فحرقهم جميعا فلما قدم يوسف بن عمر دخل عليه الكميت وقد مدحه بعد قتله زيد بن علي فأنشده قوله فيه\n(خرجت لهم تمشي البراح ولم تكن ... كمن حصنه فيه الرتاج المضبب)\n(وما خالد يستطعم الماء فاغرا ... بعدلك والداعي إلى الموت ينعب)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":7,"spl":"الكميت وخالد بن عبد الله","tags":["الكميت"],"loc":2974},
{"id":"b216-11","bab":"الجزء 17","sec":"موت الكميت","page":"ج17 ص22","text":"قال والجند قيام على رأس يوسف بن عمر وهم يمانية فتعصبوا لخالد فوضعوا ذباب سيوفهم في بطن الكميت فوجئوه بها وقالوا أتنشد\nالأمير ولم تستأمره فلم يزل ينزفه الدم حتى مات وأخبرني عمي قال حدثنا يعقوب بن إسرائيل قال حدثنا إبراهيم بن عبدالله الطلحي عن محمد بن سلمة بن أرتبيل\nقال لما دخل الكميت بن زيد على هشام سلم ثم قال يا أمير المؤمنين غائب آب ومذنب تاب محا بالإنابة ذنبه وبالصدق كذبه والتوبة تذهب الحوبة ومثلك حلم عن ذي الجريمة وصفح عن ذي الريبة فقال له هشام ما الذي نجاك من القسري\nقال صدق النية في التوبة قال ومن سن لك الغي وأورطك فيه قال الذي أغوى آدم فنسي ولم يجد له عزما فإن رأيت يا أمير المؤمنين فدتك نفسي إن تأذن لي بمحو الباطل بالحق بالاستماع لما قلته فأنشده\n(ذكر القلب إلفه المذكورا ... وتلافى من الشباب أخيرا)\nدثني أحمد بن عبيد الله بن عمار قال حدثنا الحسن بن عليل العنزي قال حدثني أحمد بن بكير الأسدي قال حدثني محمد بن أنس قال حدثني محمد بن سهل الأسدي قال دخل المستهل بن الكميت على عبد الصمد بن علي فقال له من\nأنت فأخبره فقال لا حياك الله ولا حيا أباك وهو الذي يقول\n(فالآن صرت إلى أمية ... والأمور إلى المصاير)\nال فأطرقت استحياء مما قال وعرفت البيت قال ثم قال لي ارفع رأسك فلئن كان قال هذا فلقد قال\n(بخاتمكم كرها تجوز أمورهم ... فلم أر غصبا مثله حين يغصب)\nقال فسلى بعض ما كان بي وحادثني ساعة ثم قال ما يعجبك من النساء يا مستهل قلت\n(غراء تسحب من قيام فرعها ... جثلا يزينه سواد أسحم)\n(فكأنها فيه نهار مشرق ... وكأنه ليل عليها مظلم)\nال يا بني هذه لا تصاب إلا في الفردوس وأمر له بجائزة أخبرني عمي قال حدثنا يعقوب بن إسرائيل قال حدثني إبراهيم بن عبد الله الخصاف الطلحي عن محمد بن أنس السلامي\nقال كان هشام بن عبد الملك مشغوفا بجارية له يقال لها صدوف مدنية اشتريت له بمال جزيل فعتب عليها ذات يوم في شيء وهجرها وحلف ألا يبدأها بكلام فدخل عليه الكميت وهو مغموم بذلك فقال مالي أراك مغموما يا أمير المؤمنين لا غمك الله فأخبره هشام بالقصة فأطرق الكميت ساعة ثم أنشأ يقول\n(أعتبت أم عتبت عليك صدوف ... وعتاب مثلك مثلها تشريف)\n(لا تقعدن تلوم نفسك دائبا ... فيها وأنت بحبها مشغوف)\n(إن الصريمة لا يقوم بثقلها ... إلا القوي بها وأنت ضعيف)\nقال هشام صدقت والله ونهض من مجلسه فدخل إليها ونهضت إليه فاعتنقته وانصرف الكميت فبعث إليه هشام بألف دينار وبعثت إليه بمثلها قال الطلحي أخبرني حبيش بن الكميت أخو المستهل بن الكميت بن زيد قال","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":8,"spl":"موت الكميت","tags":["الكميت","الجواري والنساء"],"loc":2975},
{"id":"b216-12","bab":"الجزء 17","sec":"الكميت ويزيد بن عبد الملك","page":"ج17 ص25","text":"وفد الكميت بن زيد على يزيد بن عبد الملك فدخل عليه يوما وقد اشتريت له سلامة القس فأدخلها إليه والكميت حاضر فقال له يا أبا المستهل هذه جارية تباع أفترى أن نبتاعها قال إي والله يا أمير المؤمنين وما أرى أن لها مثلا في الدنيا فلا تفوتنك قال فصفها لي في شعر حتى أقبل رأيك فقال الكميت\n(هي شمس النهار في الحسن إلا ... أنها فضلت بقتل الظراف)\n(غضة بضة رخيم لعوب ... وعثة المتن شختة الأطراف)\n(زانها دلها وثغر نقي ... وحديث مرتل غير جافي)\n(خلقت فوق منية المتمني ... فأقبل النصح يابن عبد مناف)\nضحك يزيد وقال قد قبلنا نصحك يا أبا المستهل وأمر له بجائزة سنية أخبرني هاشم بن محمد الخزاعي قال أخبرني إبراهيم بن أيوب عن ابن قتيبة\nقال مر الفرزدق بالكميت وهو ينشد - والكميت يومئذ صبي - فقال له الفرزدق يا غلام أيسرك أني أبوك فقال لا ولكن يسرني أن تكون أمي فحصر الفرزدق فأقبل على جلسائه\nوقال ما مر بي مثل هذا قط أخبرني أحمد بن محمد بن سعيد الهمداني بن عقدة قال أخبرنا علي بن محمد الحسيني قال حدثنا جعفر بن محمد بن عيسى الحمال\nقال حدثنا مصبح بن الهلقام قال حدثنا محمد بن سهل صاحب الكميت قال دخلت مع الكميت على أبي عبد الله جعفر بن محمد عليهما السلام فقال له جعلت فداك ألا أنشدك قال إنها أيام عظام قال إنها فيكم قال هات - وبعث أبو عبد الله إلى بعض أهله فقرب - فأنشده فكثر البكاء حين أتى على هذا البيت\n(يصيب به الرامون عن قوس غيرهم ... فيا آخرا سدى له الغي أول)\nرفع أبو عبد الله - عليه السلام - يديه فقال اللهم اغفر للكميت ما قدم وما أخر وما أسر وما أعلن وأعطه حتى يرضى\nأخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال قال محمد بن كناسة حدثني صاعد مولى الكميت قال دخلنا على أبي جعفر محمد بن علي - عليهما السلام - فأنشده الكميت قصيدته التي أولها\n(من لقلب متيم مستهام ... )\nقال اللهم اغفر للكميت اللهم اغفر للكميت قال ودخلنا يوما على أبي جعفر محمد بن علي فأعطانا ألف دينار وكسوة فقال له الكميت والله ما أحببتكم للدنيا ولو أردت الدنيا لأتيت من هي في يديه ولكني أحببتكم للآخرة فأما الثياب التي أصابت أجسامكم فأنا أقبلها لبركاتها وأما المال فلا أقبله فرده وقبل الثياب\nقال ودخلنا على فاطمة بنت الحسين - عليهما السلام - فقالت هذا شاعرنا أهل البيت وجاءت بقدح فيه سويق فحركته بيدها وسقت الكميت فشربه ثم أمرت له بثلاثين دينارا ومركب فهملت عيناه وقال لا والله لا أقبلها إني لم أحبكم للدنيا أخبرني محمد بن العباس اليزيدي قال أخبرني عمي عن عبيد الله بن\nمحمد بن حبيب عن ابن كناسة قال لما جاءت المسودة سخروا بالمستهل بن الكميت وحملوا عليه حملا ثقيلا وضربوه فمر ببني أسد فقال أترضون أن يفعل بي هذا الفعل قالوا له هؤلاء الذين يقول أبوك فيهم\n(والمصيبون باب ما أخطأ الناس ... ومرسو قواعد الإسلام)\nد أصابوا فيك فلا نكذب أباك قال ودخل المستهل على أبي مسلم فقال له أبوك الذي كفر بعد إسلامه فقال كيف وهو الذي يقول\n(بخاتمكم كرها تجوز أمورهم ... فلم أر غصبا مثله حين يغصب)\nأطرق أبو مسلم مستحييا منه أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا الحسن بن بشر السعدي قال أخذ العسس المستهل بن الكميت في أيام أبي جعفر وكان الأمر صعبا فحبس فكتب إلى أبي جعفر يشكو حاله وكتب في آخر الرقعة\n(لئن نحن خفنا في زمان عدوكم ... وخفناكم إن البلاء لراكد)\nلما قرأها أبو جعفر قال صدق المستهل وأمر بتخليته حدثني علي بن محمد بن علي إمام مسجد الكوفة قال أخبرنا إسماعيل ابن علي الخزاعي - ابن أخي دعبل - قال حدثني عمي دعبل بن علي قال رأيت النبي في النوم فقال فقال لي مالك وللكميت بن زيد فقلت\nيا رسول الله ما بيني وبينه إلا كما بين الشعراء فقال لا تفعل أليس هو القائل\n(فلا زلت فيهم حيث يتهمونني ... ولا زلت في أشياعهم أتقلب)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":9,"spl":"الكميت ويزيد بن عبد الملك","tags":["الكميت"],"loc":2976,"partial":1},
{"id":"b216-13","bab":"الجزء 17","sec":"الكميت ويزيد بن عبد الملك","page":"ج17 ص25","text":"إن الله قد غفر له بهذا البيت قال فانتهيت عن الكميت بعدها حدثني علي بن محمد قال حدثني إسماعيل بن علي قال حدثني إبراهيم بن سعد الأسدي قال سمعت أبي يقول رأيت رسول الله في المنام فقال من أي الناس أنت قلت من العرب قال أعلم فمن أي العرب قلت من بني أسد قال من أسد بن خزيمة قلت نعم قال لي أهلالي أنت قلت نعم قال أتعرف الكميت بن زيد قلت يا رسول الله عمي ومن قبيلتي قال أتحفظ من شعره شيئا قلت نعم قال أنشدني\n(طربت وما شوقا إلى البيض أطرب ... )\nال فأنشدته حتى بلغت إلى قوله\n(فما لي إلا آل أحمد شيعة ... وما لي إلا مشعب الحق مشعب)\nقال لي إذا أصبحت فاقرأ عليه السلام وقل له قد غفر الله لك بهذه القصيدة وجدت في كتاب بخط المرهبي الكوفي حدثني سليمان بن الربيع بن هشام النهدي الخراز قال حدثني نصر بن مزاحم المنقري أنه رأى النبي في النوم وبين يديه رجل ينشده\n(من لقلب متيم مستهام ... )\nقال فسألت عنه فقيل لي هذا الكميت بن زيد الأسدي قال فجعل النبي يقول له جزاك الله خيرا وأثنى عليه أخبرني الحسن بن علي الخفاف قال حدثنا الحسن بن عليل العنزي قال حدثني أحمد بن بكير الأسدي قال حدثني محمد بن أنس السلامي قال حدثني محمد بن سهل راوية الكميت قال","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":10,"spl":"الكميت ويزيد بن عبد الملك","tags":["الكميت","المديح"],"loc":2977,"partialRef":{"sid":"b216-12","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b216-14","bab":"الجزء 17","sec":"الكميت والفرزدق","page":"ج17 ص30","text":"جاء الكميت إلى الفرزدق لما قدم الكوفة فقال له إني قد قلت شيئا فاسمعه مني يا أبا فراس قال هاته فأنشده قوله\n(طربت وما شوقا إلى البيض أطرب ... ولا لعبا مني وذو الشيب يلعب)\n(ولكن إلى أهل الفضائل والنهى ... وخير بني حواء والخير يطلب)\nقال له قد طربت إلى شيء ما طرب إليه أحد قبلك فأما نحن فما نطرب ولا طرب من كان قبلنا إلا إلى ما تركت أنت الطرب إليه أخبرني أحمد بن عبد العزيز الجوهري\nقال حدثنا محمد بن علي النوفلي قال سمعت أبي يقول لما قال الكميت بن زيد الشعر كان أول ما قال الهاشميات فسترها ثم أتى الفرزدق بن غالب فقال له يا أبا فراس إنك شيخ مضر وشاعرها وأنا ابن أخيك الكميت بن زيد الأسدي\nقال له صدقت أنت ابن أخي فما حاجتك قال نفث على لساني فقلت شعرا فأحببت أن أعرضه عليك فإن كان حسنا أمرتني بإذاعته وإن كان قبيحا أمرتني بستره وكنت أولى من ستره علي فقال له الفرزدق أما عقلك فحسن وإني لأرجو أن يكون شعرك على قدر عقلك\nفأنشدني ما قلت فأنشده\n(طربت وما شوقا إلى البيض أطرب ... )\nال فقال لي فيم تطرب يابن أخي فقال\n(ولا لعبا مني وذو الشيب يلعب ... )\nقال بلى يابن أخي فالعب فإنك في أوان اللعب فقال\n(ولم يلهني دار ولا رسم منزل ... ولم يتطربني بنان مخضب)\nقال ما يطربك يا بن أخي فقال\n(ولا السانحات البارحات عشية ... أمر سليم القرن أم مر أعضب)\nفقال أجل لا تتطير فقال\n(ولكن إلى أهل الفضائل والنهى ... وخير بني حواء والخير يطلب)\nقال ومن هؤلاء ويحك فقال\n(إلى النفر البيض الذين بحبهم ... إلى الله فيما نابني أتقرب)\nال أرحني ويحك من هؤلاء قال\n(بني هاشم رهط النبي فإنني ... بهم ولهم أرضى مرارا وأغضب)\n(خفضت لهم مني جناحي مودة ... إلى كنف عطفاه أهل ومرحب)\n(وكنت لهم من هؤلاء وهؤلا ... محبا على أني أذم وأقصب)\n(وأرمى وأرمي بالعداوة أهلها ... وإني لأوذى فيهم وأؤنب)\nفقال له الفرزدق يا بن أخي أذع ثم أذع فأنت والله أشعر من مضى وأشعر من بقي أخبرني الحسن قال حدثنا الحسن بن عليل العنزي قال حدثني\nأحمد بن بكير قال حدثني محمد بن أنس قال حدثني محمد بن سهل راوية الكميت عن الكميت قال لما قدم ذو الرمة أتيته فقلت له إني قلت قصيدة عارضت بها قصيدتك\n(ما بال عينك منها الماء ينسكب ... )\nقال لي وأي شيء قلت قال قلت\n(هل أنت عن طلب الأيفاع منقلب ... أم كيف يحسن من ذي الشيبة اللعب)\nحتى أنشدته إياها فقال لي ويحك إنك لتقول قولا ما يقدر إنسان أن يقول لك أصبت ولا أخطأت وذلك أنك تصف الشيء فلا تجيء به ولا تقع بعيدا منه بل تقع قريبا\nقلت له أو تدري لم ذلك قال لا قلت لأنك تصف شيئا رأيته بعينك وأنا أصف شيئا وصف لي وليست المعاينة كالوصف قال فسكت أخبرني أحمد بن عبيد الله بن عمار\nقال حدثنا يعقوب بن إسرائيل قال حدثني إسماعيل بن عبد الله الطلحي عن محمد بن سلمة بن أرتبيل عن حماد الراوية قال كانت للكميت جدتان أدركتا الجاهلية فكانتا تصفان له البادية وأمورها وتخبرانه بأخبار الناس في الجاهلية فإذا شك في شعر أو خبر عرضه عليهما فيخبرانه عنه فمن هناك كان علمه\nأخبرني الحسن بن القاسم البجلي الكوفي قال حدثنا علي بن إبراهيم ابن المعلى قال حدثنا محمد بن فضيل - يعني الصيرفي - عن أبي بكر الحضرمي\nقال استأذنت للكميت على أبي جعفر محمد بن علي - عليهما السلام - في أيام التشريق بمنى فأذن له فقال له الكميت جعلت فداك إني قلت فيكم شعرا أحب أن أنشدكه فقال يا كميت اذكر الله في هذه الأيام المعلومات وفي هذه الأيام المعدودات فأعاد عليه الكميت القول فرق له أبو جعفر عليه السلام فقال هات فأنشده قصيدته حتى بلغ\n(يصيب به الرامون عن قوس غيرهم ... فيا آخرا سدى له الغي أول)\nرفع أبو جعفر يديه إلى السماء وقال اللهم اغفر للكميت أخبرني جعفر بن محمد بن مروان الغزال الكوفي قال حدثني أبي قال حدثنا أرطأة بن حبيب عن فضيل الرسان عن ورد بن زيد أخي الكميت\nقال أرسلني الكميت إلى أبي جعفر فقلت له إن الكميت أرسلني إليك وقد صنع بنفسه ما صنع فتأذن له أن يمدح بني أمية قال نعم هو في حل فليقل ما شاء","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":11,"spl":"الكميت والفرزدق","tags":["الكميت"],"loc":2978,"partialRef":{"sid":"b129-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b216-16","bab":"الجزء 17","sec":"الكميت والفرزدق — الكميت وروايته للحديث والتفسير","page":"ج17 ص30 – ج17 ص34","text":"أخبرني محمد بن العباس قال أخبرني عمي عن عبيد الله بن محمد بن حبيب عن ابن كناسة قال مات ورد أخو الكميت فقيل للكميت ألا ترثي أخاك فقال مرثيته ومرزيته عندي سواء وإني لا أطيق أن أرثيه جزعا عليه\nوقد روى الكميت بن زيد الحديث وروي عنه أخبرني جعفر بن محمد بن عبيد بن عتبة في كتابه إلي قال حدثني الحسين بن محمد بن علي الأزدي قال\nحدثني الوليد بن صالح قال حدثني محمد بن سعيد بن عمير الصيداوي عن أبيه عن الكميت بن زيد قال حدثني عكرمة أن عبد الله بن عباس بعثه مع الحسين بن علي - عليهما السلام - فجعل يهل حتى رمى جمرة العقبة أو حين رمى جمرة العقبة فسألته عن ذلك فأخبرني أن أباه فعله فحدثت به ابن عباس فقال لي لا أم لك أتسألني عن شيء أخبرك به الحسين بن علي عن أبيه والله إنها لسنة أخبرنا أبو الحسن بن سراج الجاحظ\nقال حدثنا مسروق بن عبد الرحمن أبو صالح عن الحسن بن محمد بن أعين عن حفص بن محمد الأسدي قال حدثنا الكميت بن زيد عن مذكور مولى زينب عن زينب قالت دخل علي النبي وأنا فضل قالت فقلت بيدي هكذا - واستترت - قالت فقال لي إن الله عز و جل زوجنيك\nحدثني أبو العباس أحمد بن محمد بن سعيد بن عقدة قال حدثني أحمد بن سراج قال حدثني الحسن بن أيوب الخثعمي قال حدثنا فرات ابن حبيب الأسدي قال حدثني أبي حبيب بن أبي سليمان قال حدثني الكميت بن زيد قال سألت أبا جعفر عن قول الله عز و جل ( إن\nالذي فرض عليك القرآن لرادك إلى معاد\nقال دخلت أنا وأبي إلى أبي سعيد الخدري فسأله أبي عنها فقال معاد آخرته الموت أخبرني محمد بن خلف وكيع قال حدثني إسحاق بن محمد بن أبان قال حدثني محمد بن عبد الله بن مهران قال حدثني ربعي بن عبد الله بن الجارود بن أبي سبرة عن أبيه قال دخل الكميت بن زيد الأسدي على أبي جعفر محمد بن علي عليهما السلام فقال له يا كميت أنت القائل\n(فالآن صرت إلى أمية ... والأمور إلى المصاير)\nال نعم قد قلت ولا والله ما أردت به إلا الدنيا ولقد عرفت فضلكم قال أما أن قلت ذلك فإن التقية لتحل أخبرني محمد بن القاسم الأنباري قال حدثني أبي قال حدثنا الحسن ابن عبد الرحمن الربعي قال حدثنا أحمد بن بكير الأسدي قال حدثنا محمد بن أنس السلامي الأسدي قال سئل معاذ الهراء من أشعر الناس قال أمن الجاهليين أم من الإسلاميين قال بل من الجاهليين قال امرؤ القيس وزهير وعبيد بن\nالأبرص قالوا فمن الإسلاميين قال الفرزدق وجرير والأخطل والراعي قال فقيل له يا أبا محمد ما رأيناك ذكرت الكميت فيمن ذكرت قال ذاك أشعر الأولين والآخرين أخبرني الحسن بن علي قال حدثنا محمد بن زكريا الغلابي قال حدثنا العباس بن بكار قال حدثنا أبو بكر الهذلي قال لما خرج زيد بن علي كتب إلى الكميت اخرج معنا يا أعيمش ألست القائل\n(ما أبالي - إذا حفظت أبا القاسم ... - فيكم ملامة اللوام)\nكتب إليه الكميت\n(تجود لكم نفسي بما دون وثبة ... تظل لها الغربان حولي تحجل)\nخبرني محمد بن العباس اليزيدي قال حدثني عمي عن عبيد الله بن محمد بن حبيب عن محمد بن كناسة قال لما أنشد هشام بن عبد الملك قول الكميت\n(فبهم صرت للبعيد ابن عم ... واتهمت القريب أي اتهام)\n(مبديا صفحتي على الموقف المعلم ... بالله قوتي واعتصامي)\nقال استقتل المرائي","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":12,"spl":"الكميت والفرزدق — الكميت وروايته للحديث والتفسير","tags":["الكميت"],"loc":2979},
{"id":"b216-17","bab":"الجزء 17","sec":"الكميت يمدح خالد القسري","page":"ج17 ص37","text":"قال ودخل الكميت على خالد القسري فأنشده قوله فيه\n(لو قيل للجود من حليفك ما ... إن كان إلا إليك ينتسب)\n(أنت أخوه وأنت صورته ... والرأس منه وغيرك الذنب)\n(أحرزت فضل النضال في مهل ... فكل يوم بكفك القصب)\n(لو أن كعبا وحاتما نشرا ... كانا جميعا من بعض ما تهب)\n(لا تخلف الوعد إن وعدت ولا ... أنت عن المعتفين تحتجب)\n(ما دونك اليوم من نوال ولا ... خلفك للراغبين منقلب)\nأمر له بمائة ألف درهم قال وحضر المستهل بن الكميت باب عيسى بن موسى - وكان يكرمه - فبلغه أنه قد غلب عليه الشراب فاستخف به وكان آخر من يدخل إلى عيسى بن موسى قوم يقال لهم الراشدون يؤذن لهم في القعود فأدخل المستهل معهم فقال\n(ألم تر أني لما حضرت ... دعيت فكنت مع الراشدينا)\n(ففزت بأحسن أسمائهم ... وأقبح منزلة الداخلينا)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال\nدخل الكميت على مخلد بن يزيد بن المهلب فأنشده\n(قاد الجيوش لخمس عشرة حجة ... ولداته عن ذاك في أشغال)\n(قعدت بهم هماتهم وسمت به ... همم الملوك وسورة الأبطال)\nال وقدام مخلد دراهم يقال لها الرويجة فقال خذ وقرك منها فقال له البغلة بالباب وهي أجلد مني فقال خذ وقرها فأخذ أربعة وعشرين ألف درهم فقيل لأبيه في ذلك فقال لا أرد مكرمة فعلها ابني\nأخبرني محمد بن خلف وكيع قال حدثني أبو بكر الأموي قال حدثنا ابن فضيل قال سمعت ابن شبرمة قال قلت للكميت إنك قلت في بني هاشم فأحسنت وقلت في بني أمية أفضل\nقال إني إذا قلت أحببت أن أحسن وأخبرني الحسن بن علي ومحمد بن عمران الصيرفي قالا حدثنا الحسن ابن عليل العنزي قال حدثنا محمد بن معاوية عن ابن كناسة قال كان الكميت بن زيد طويلا أصم ولم يكن حسن الصوت ولا جيد الإنشاد فكان إذا استنشد أمر ابنه المستهل فأنشد وكان فصيحا حسن الإنشاد","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":13,"spl":"الكميت يمدح خالد القسري","tags":["الكميت","الخمر"],"loc":2980},
{"id":"b216-18","bab":"الجزء 17","sec":"سبب هجائه أهل اليمن","page":"ج17 ص38","text":"أخبرني عمي وابن عمار قالا حدثنا يعقوب بن إسرائيل قال حدثنا\nإبراهيم بن عبد الله الطلحي عن محمد بن سلمة بن أرتبيل أن سبب هجاء الكميت أهل اليمن أن شاعرا من أهل الشام يقال له حكيم ابن عياش الكلبي كان يهجو علي بن أبي طالب - عليه السلام - وبني هاشم جميعا وكان منقطعا إلى بني أمية فانتدب له الكميت فهجاه وسبه فأجابه ولج الهجاء بينهما وكان الكميت يخاف أن يفتضح في شعره عن علي - عليه السلام - لما وقع بينه وبين هشام وكان يظهر أن هجاءه إياه في العصبية التي بين عدنان وقحطان فكان ولد إسماعيل بن الصباح بن الأشعث بن قيس وولد علقمة بن وائل الحضرمي يروون شعر الكلبي فهجا أهل اليمن جميعا إلا هذين فإنه قال في آل علقمة\n(ولولا آل علقمة اجتدعنا ... بقايا من أنوف مصلمينا)\nوقال في إسماعيل\n(فإن لإسماعيل حقا وإننا ... له شاعبو الصدع المقارب للشعب)\nكانت لآل علقمة عنده يد لأن علقمة آواه ليلة خرج إلى الشام وأم إسماعيل من بني أسد فكف عنهما لذلك قال الطلحي قال أبو سلمة حدثني محمد بن سهل قال قال الكلبي\n(ما سرني أن أمي من بني أسد ... وأن ربي نجاني من النار)\n(وأنهم زوجوني من بناتهم ... وأن لي كل يوم ألف دينار)\nأجابه الكميت\n(يا كلب مالك أم من بني أسد ... معروفة فاحترق يا كلب بالنار)\n(لكن أمك من قوم شنئت بهم ... قد قنعوك قناع الخزي والعار)\nقال فقال له الكلبي\n(لن يبرح اللؤم هذا الحي من أسد ... حتى يفرق بين السبت والأحد)\nال محمد بن أنس حدثني المستهل بن الكميت قال قلت لأبي يا أبت إنك هجوت الكلبي فقلت\n(ألا يا سلم يا تربي ... أفي أسماء من ترب)\nغمزت عليه فيها ففخرت ببني أمية وأنت تشهد عليها بالكفر فألا فخرت بعلي وبني هاشم الذين تتولاهم فقال يا بني أنت تعلم انقطاع الكلبي إلى بني أمية وهم أعداء علي عليه السلام فلو ذكرت عليا لترك ذكري وأقبل على هجائه فأكون قد عرضت عليا له ولا أجد له ناصرا من بني أمية ففخرت عليه ببني أمية وقلت إن نقضها علي قتلوه وإن أمسك عن ذكرهم قتلته غما وغلبته فكان كما قال أمسك الكلبي عن جوابه فغلب عليه وأفحم الكلبي وفي أول هذه القصيدة غناء نسبته\n(ألا يا سلم يا تربي ... أفي أسماء من ترب)\n(ألا يا سلم حييت ... سلي عني وعن صحبي)\n(ألا يا سلم غنينا ... وإن هيجتما حبي)\n(على حادثة الأيام ... لي نصبا من النصب)\nالغناء لابن سريج ثقيل أول بالبنصر عن عمرو أخبرني علي بن سليمان الأخفش قال أخبرني أبو سعيد السكري عن محمد بن حبيب عن إبراهيم بن عبد الله الطلحي قال قال محمد بن سلمة كان الكميت مداحا لأبان بن الوليد البجلي وكان أبان له محبا وإليه محسنا فمدح الكميت الحكم بن الصلت وهو يومئذ يخلف يوسف بن عمر بقصيدته التي أولها\n(طربت وهاجك الشوق الحثيث ... )\nلما أنشده إياها وفرغ دعا الحكم بخازنه ليعطيه الجائزة ثم دعا بأبان بن الوليد فأدخل إليه وهو مكبل بالحديد فطالبه بالمال فالتفت الكميت فرآه فدمعت عيناه وأقبل على الحكم فقال أصلح الله الأمير اجعل جائزتي لأبان واحتسب بها له من هذا النجم فقال له الحكم قد فعلت ردوه إلى السجن فقال له أبان يا أبا المستهل ما حل له علي شيء بعد فقال الكميت للحكم أبي تسخر أصلح الله الأمير فقال الحكم كذب قد حل عليه المال ولو لم يحل لاحتسبنا له مما يحل فقال له حوشب بن يزيد الشيباني - وكان خليفة الحكم - أصلح الله الأمير أتشفع حمار بني أسد في عبد بجيلة فقال له\nالكميت لئن قلت ذاك فوالله ما فررنا عن آبائنا حتى قتلوا ولا نكحنا حلائل آبائنا بعد أن ماتوا - وكان يقال إن حوشبا فر عن أبيه في بعض الحروب فقتل أبوه ونجا هو ويقال إنه وطىء جارية لأبيه بعد وفاته - فسكت حوشب مفحما خجلا فقال له الحكم ما كان تعرضك للسان الكميت قال وفي حوشب يقول الشاعر\n(نجى حشاشته وأسلم شيخه ... لما رأى وقع الأسنة حوشب)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":14,"spl":"سبب هجائه أهل اليمن","tags":["الكميت"],"song":1,"loc":2981,"partial":1},
{"id":"b216-20","bab":"الجزء 17","sec":"سبب هجائه أهل اليمن — مولد الكميت وموته ووصيته","page":"ج17 ص38 – ج17 ص42","text":"ال الطلحي في هذا الخبر وحدثني إبراهيم بن علي الأسدي قال التقت ريا بنت الكميت بن زيد وفاطمة بنت أبان بن الوليد بمكة وهما حاجتان فتساءلتا حتى تعارفتا فدفعت بنت أبان إلى بنت الكميت خلخالي ذهب كانا عليها فقالت لها بنت الكميت جزاكم الله خيرا يا آل أبان فما تتركون بركم بنا قديما ولا حديثا فقالت لها بنت أبان بل أنتم فجزاكم الله خيرا فإنا أعطيناكم ما يبيد ويفنى وأعطيتمونا من المجد والشرف ما يبقى أبدا ولا يبيد يتناشده الناس في المحافل فيحيي ميت الذكر ويرفع بقية العقب أخبرني عمي وابن عمار قالا حدثنا يعقوب بن نعيم قال حدثنا إبراهيم بن عبد الله بن زيد الخصاف الطلحي قال قال محمد بن سلمة بن أرتبيل\nولد الكميت أيام مقتل الحسين بن علي سنة ستين ومات في سنة ست وعشرين ومائة في خلافة مروان بن محمد وكان مبلغ شعره حين مات خمسة\nآلاف ومائتين وتسعة وثمانين بيتا وقال يعقوب بن إسرائيل في رواية عمي خاصة عنه حدثت عن المستهل ابن الكميت أنه قال حضرت أبي عند الموت وهو يجود بنفسه ثم أفاق ففتح عينيه ثم قال اللهم آل محمد اللهم آل محمد اللهم آل محمد - ثلاثا ثم قال لي يا بني وددت أني لم أكن هجوت نساء بني كلب بهذا البيت\n(مع العضروط والعسفاء ألقوا ... برادعهن غير محصنينا)\nفعممتهن قذفا بالفجور والله ما خرجت بليل قط إلا خشيت أن أرمى بنجوم السماء لذلك ثم قال يا بني إنه بلغني في الروايات أنه يحفر بظهر الكوفة خندق يخرج فيه الموتى من قبورهم وينبشون منها فيحولون إلى قبور غير قبورهم فلا تدفني في الظهر ولكن إذا مت فامض بي إلى موضع يقال له مكران فادفني فيه فدفن في ذلك الموضع وكان أول من دفن فيه وهي مقبرة بني أسد إلى الساعة قال المستهل ومات أبي في خلافة مروان بن محمد سنة ست وعشرين ومائة\n\n(أستعين الذي بكفيه نفعي ... ورجائي على التي قتلتني)\n(ولقد كنت قد عرفت وأبصرت ... أمورا لو أنها نفعتني)\n(قلت إني أهوى شفا ما ألاقي ... من خطوب تتابعت فدحتني)\nروضه من السريع يقال إن الشعر لعمر والغناء لابن سريج ثقيل أول بالوسطى عن حماد عن أبيه وفيه لحن للهذلي وقيل بل لحن ابن سريج للهذلي ذكر ذلك حبش وقيل بل هو مما نسب من غناء ابن سريج إلى الهذلي","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":15,"spl":"سبب هجائه أهل اليمن — مولد الكميت وموته ووصيته — خبر ابن سريج مع سكينة بنت الحسين عليهما ا","tags":["الكميت"],"song":1,"loc":2982},
{"id":"b216-21","bab":"الجزء 17","sec":"خبر ابن سريج مع سكينة بنت الحسين عليهما السلام","page":"ج17 ص45","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن مصعب الزبيري قال حدثني شيخ من المكيين ووجدت هذا الخبر أيضا في بعض الكتب مرويا عن محمد بن سعد كاتب الواقدي عن مصعب عن شيخ من المكيين والرواية عنهما متفقة\nقال كان ابن سريج قد أصابته الريح الخبيثة وآلى يمينا ألا يغني ونسك ولزم المسجد الحرام حتى عوفي ثم خرج وفيه بقية من العلة فأتى قبر النبي وموضع مصلاه فلما قدم المدينة نزل على بعض إخوانه من أهل النسك والقراءة فكان أهل الغناء يأتونه مسلمين عليه فلا يأذن لهم في الجلوس والمحادثة فأقام بالمدينة حولا حتى لم يحس من علته بشيء وأراد الشخوص إلى مكة\nوبلغ ذلك سكينة بنت الحسين فاغتمت اغتماما شديدا وضاق به ذرعها وكان أشعب يخدمها وكانت تأنس بمضاحكته ونوادره وقالت لأشعب ويلك إن ابن سريج شاخص وقد دخل المدينة منذ حول ولم أسمع من غنائه قليلا ولا كثيرا ويعز ذلك علي فكيف الحيلة في الاستماع منه ولو صوتا واحدا فقال لها أشعب جعلت فداك وأنى لك بذلك والرجل اليوم زاهد ولا حيلة فيه فارفعي طمعك والحسي تورك تنفعك حلاوة فمك فأمرت بعض جواريها فوطئن بطنه حتى كادت أن تخرج أمعاؤه وخنقنه حتى كادت نفسه أن تتلف ثم أمرت به فسحب على وجهه حتى أخرج من الدار إخراجا عنيفا فخرج على أسوأ الحالات واغتم أشعب غما شديدا وندم على ممازحتها في وقت لم ينبغ له ذلك فأتى منزل ابن سريج ليلا فطرقه فقيل من هذا فقال أشعب ففتحوا له فرأى على وجهه ولحيته التراب والدم سائلا من أنفه وجبهته على لحيته وثيابه ممزقة وبطنه وصدره وحلقه قد عصرها الدوس والخنق ومات الدم فيها فنظر ابن سريج إلى منظر فظيع هاله وراعه فقال له ما هذا ويحك فقص عليه القصة","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":15,"spl":"سبب هجائه أهل اليمن — مولد الكميت وموته ووصيته — خبر ابن سريج مع سكينة بنت الحسين عليهما ا","tags":["الكميت","الجواري والنساء"],"loc":2983},
{"id":"b216-22","bab":"الجزء 17","sec":"امتناعه من الذهاب إليها وحيلة أشعب لإرغامه","page":"ج17 ص46","text":"فقال ابن سريج إنا لله وإنا إليه راجعون ماذا نزل بك والحمد لله الذي\nسلم نفسك لا تعودن إلى هذه أبدا قال أشعب فديتك هي مولاتي ولا بد لي منها ولكن هل لك حيلة في أن تصير إليها وتغنيها فيكون ذلك سببا لرضاها عني\nقال ابن سريج كلا والله لا يكون ذلك أبدا بعد أن تركته قال أشعب قد قطعت أملي ورفعت رزقي وتركتني حيران بالمدينة لا يقبلني أحد وهي ساخطة علي فالله الله في وأنا أنشدك الله إلا تحملت هذا الإثم في فأبى عليه فلما رأى أشعب أن عزم ابن سريج قد تم على الامتناع\nقال في نفسه لا حيلة لي وهذا خارج وإن خرج هلكت فصرخ صرخة آذن أهل المدينة لها ونبه الجيران من رقادهم وأقام الناس من فرشهم ثم سكت فلم يدر الناس ما القصة عند خفوت الصوت بعد أن قد راعهم فقال له ابن سريج ويلك ما هذا\nقال لئن لم تصر معي إليها لأصرخن صرخة أخرى لا يبقى بالمدينة أحد إلا صار بالباب ثم لأفتحنه ولأرينهم ما بي ولأعلمنهم أنك أردت تفعل كذا وكذا بفلان - يعني غلاما كان ابن سريج مشهورا به - فمنعتك وخلصت الغلام من يدك حتى فتح الباب ومضى ففعلت بي هذا غيظا وتأسفا وأنك إنما أظهرت النسك والقراءة لتظفر بحاجتك منه وكان أهل مكة والمدينة يعلمون حاله معه فقال ابن سريج اغرب أخزاك الله\nقال أشعب والله الذي لا إله إلا هو وإلا فما أملك صدقة وامرأته طالق ثلاثا وهو نحير في مقام إبراهيم والكعبة وبيت النار والقبر قبر أبي رغال إن أنت لم\nتنهض معي في ليلتي هذه لأفعلن","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":16,"spl":"امتناعه من الذهاب إليها وحيلة أشعب لإرغامه","tags":["الكميت","السفر والحج"],"loc":2984},
{"id":"b216-24","bab":"الجزء 17","sec":"نجاح حيلة أشعب — مجلس غناء بوجود عزة الميلاء","page":"ج17 ص48 – ج17 ص49","text":"فلما رأى ابن سريج الجد منه قال لصاحبه ويحك أما ترى ما وقعنا فيه وكان صاحبه الذي نزل عنده ناسكا فقال لا أدري ما أقول فيما نزل بنا من هذا الخبيث وتذمم ابن سريج من الرجل صاحب المنزل فقال لأشعب اخرج من منزل الرجل فقال رجلي مع رجلك فخرجا فلما صارا في بعض الطريق\nقال ابن سريج لأشعب امض عني قال والله لئن لم تفعل ما قلت لأصيحن الساعة حتى يجتمع الناس ولأقولن إنك أخذت مني سوارا من ذهب لسكينة على أن تجيئها فتغنيها سرا وإنك كابرتني عليه وجحدتني وفعلت بي هذا الفعل فوقع ابن سريج فيما حيلة له فيه فقال أمضي لا بارك الله فيك فمضى معه فلما صار إلى باب سكينة قرع الباب فقيل من هذا فقال أشعب قد جاء بابن سريج ففتح الباب لهما ودخلا إلى حجرة خارجة عن دار سكينة فجلسا ساعة ثم أذن لهما فدخلا إلى سكينة فقالت يا عبيد ما هذا الجفاء\nقال قد علمت بأبي أنت ما كان مني قالت أجل فتحدثا ساعة وقص عليها ما صنع به أشعب فضحكت وقالت لقد أذهب ما كان في قلبي عليه وأمرت لأشعب بعشرين دينارا وكسوة ثم\nقال لها ابن سريج أتأذنين بأبي أنت قالت وأين قال المنزل قالت برئت من جدي إن برحت داري ثلاثا وبرئت من جدي إن أنت لم تغن إن خرجت من داري شهرا وبرئت من جدي إن أقمت في داري شهرا إن لم أضربك لكل يوم تقيم فيه عشرا وبرئت من جدي إن حنثت في يميني أو\nشفعت فيك أحدا\nفقال عبيد وا سخنة عيناه وا ذهاب دنياه وا فضيحتاه ثم اندفع يغني\n(أستعين الذي بكفيه نفعي ... ورجائي على التي قتلتني)\nلصوت المذكور آنفا فقالت له سكينة فهل عندك يا عبيد من صبر ثم أخرجت دملجا من ذهب كان في عضدها وزنه أربعون مثقالا فرمت به إليه ثم قالت أقسمت عليك لما أدخلته في يدك ففعل ذلك ثم قالت لأشعب اذهب إلى عزة فأقرئها مني السلام وأعلمها أن عبيدا عندنا فلتأتنا متفضلة بالزيارة فأتاها أشعب فأعلمها فأسرعت المجيء فتحدثوا باقي ليلتهم ثم أمرت عبيدا وأشعب فخرجا فناما في حجرة مواليها فلما أصبحت هيىء لهم غداؤهم وأذنت لابن سريج فدخل فتغدى قريبا منها مع أشعب ومواليها وقعدت هي مع عزة وخاصة جواريها فلما فرغوا من الغداء قالت يا عز إن رأيت أن تغنينا فافعلي قالت إي وعيشك فتغنت لحنها في شعر عنترة العبسي\n(حييت من طلل تقادم عهده ... أقوى وأقفر بعد أم الهيثم)\n(إن كنت أزمعت الفراق فإنما ... زمت ركابكم بليل مظلم)\nفقال ابن سريج أحسنت والله يا عزة وأخرجت سكينة الدملج الآخر من يدها فرمته إلى عزة وقالت صيري هذا في يدك ففعلت ثم قالت لعبيد هات غننا فقال حسبك ما سمعت البارحة فقالت لا بد أن تغنينا في كل يوم لحنا فلما رأى ابن سريج أنه لا يقدر على الامتناع مما تسأله غنى\n(قالت من أنت على ذكر - فقلت لها ... أنا الذي ساقه للحين مقدار)\n(قد حان منك - فلا تبعد بك الدار - ... بين وفي البين للمتبول إضرار)\nم قالت لعزة في اليوم الثاني غني فغنت لحنها في شعر الحارث بن خالد - ولابن محرز فيه لحن - ولحن عزة أحسنهما\n(وقرت بها عيني وقد كنت قبلها ... كثير البكاء مشفقا من صدودها)\n(وبشرة خود مثل تمثال بيعة ... تظل النصارى حوله يوم عيدها)\nال ابن سريج والله ما سمعت مثل هذا قط حسنا ولا طيبا ثم قالت لابن سريج هات فاندفع يغني\n(أرقت فلم أنم طربا ... وبت مسهدا نصبا)\n(لطيف أحب خلق الله ... إنسانا وإن غضبا)\n(فلم أردد مقالتها ... ولم أك عاتبا عتبا)\n(ولكن صرمت حبلي ... فأمسى الحبل منقضيا)\nفقالت سكينة قد علمت ما أردت بهذا وقد شفعناك ولم نردك وإنما كانت يميني على ثلاثة أيام فاذهب في حفظ الله وكلاءته ثم قالت لعزة إذا شئت ودعت لها بحلة ولابن سريج بمثلها فانصرفت عزة وأقام ابن سريج حتى انقضت ليلته وانصرف فمضى من وجهه إلى مكة راجعا","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":17,"spl":"نجاح حيلة أشعب — مجلس غناء بوجود عزة الميلاء","tags":["الكميت","الحب والغزل"],"loc":2985},
{"id":"b216-25","bab":"الجزء 17","sec":"نسبة الأصوات التي في هذا الخبر","page":"ج17 ص51","text":"منها\n(حييت من طلل تقادم عهده ... أقوى وأقفر بعد أم الهيثم)\nلشعر لعنترة بن شداد العبسي والغناء لعزة الميلاء وقد كتب ذلك في أول هذه القصيدة وسائر ما يغنى فيها ومنها\n(أرقت فلم أنم طربا ... وبت مسهدا نصبا)\n(لطيف أحب خلق الله ... إنسانا وإن غضبا)\n(إلى نفسي وأوجههم ... وإن أمسى قد احتجبا)\n(وصرم حبلنا ظلما ... لبلغة كاشح كذبا)\nروضه من الوافر الشعر لعمر بن أبي ربيعة والغناء لابن سريج ثقيل أول بالسبابة في مجرى البنصر ومنها قوله\n\n(قد حان منك - فلا تبعد بك الدار ... بين وفي البين للمتبول إضرار)\n(قالت من أنت على ذكر - فقلت لها ... أنا الذي ساقني للحين مقدار)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بالسبابة في مجرى الوسطى ومنها الصوت الذي أوله\n(وقرت بها عيني وقد كنت قبلها ... )\nول قوله\n(لبشرة أسرى الطيف والخبت دونها ... وما بيننا من حزن أرض وبيدها)\n(وقرت بها عيني وقد كنت قبلها ... كثيرا بكائي مشفقا من صدودها)\n(وبشرة خود مثل تمثال بيعة ... تظل النصارى حولها يوم عيدها)\nلشعر للحارث بن خالد المخزومي والغناء لمعبد خفيف ثقيل أول بالخنصر في مجرى الوسطى وذكر إسحاق هذه الطريقة في هذا الصوت ولم ينسبها إلى أحد ولابن\n! محرز في هذه الأبيات ثقيل أول بالخنصر في مجرى الوسطى وفيها لعزة الميلاء خفيف رمل وبشرة هذه - التي ذكرها الحارث بن خالد - أمة كانت لعائشة بنت طلحة وكان الحارث يكنى عن ذكر عائشة بها وله فيها أشعار كثيرة منها مما يغني فيه قوله\n(يا ربع بشرة بالجناب تكلم ... وأبن لنا خبرا ولا تستعجم)\n(ما لي رأيتك بعد أهلك موحشا ... خلقا كحوض الباقر المتهدم)\n(تسقي الضجيع إذا النجوم تغورت ... طوع الضجيع وغاية المتوسم)\n(قب البطون أوانس شبه الدمى ... يخلطن ذاك بعفة وتكرم)\nروضه من الكامل والشعر للحارث بن خالد والغناء لمعبد ولحنه\nمن خفيف الرمل بالسبابة في مجرى البنصر عن إسحاق وفيه أيضا ثقيل أول بالوسطى على مذهب إسحاق في رواية عمرو ومنها\n(يا ربع بشرة إن أضر بك البلى ... فلقد عهدتك آهلا معمورا)\n(عقب الرذاذ خلافه فكأنما ... بسط الشواطب بينهن حصيرا)\nناه ابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وفيه لحن لمالك وقيل بل هو لابن محرز وعروضه من الكامل وقوله عقب الرذاذ خلافه يقول جاء الرذاذ بعده ومنه يقال عقب لفلان غنى بعد فقر وعقب الرجل أباه إذا قام بعده مقامه وعواقب الأمور مأخوذة منه واحدتها عاقبة والرذاذ صغار المطر وقوله خلافه أي بعده قال متمم بن نويرة\n(وفقدي بني أم تداعوا فلم أكن ... خلافهم أن أستكين وأضرعا)\nي بعدهم والشواطب النساء اللواتي يشطبن لحاء السعف يعملن منه\nالحصر ومنه السيف المشطب والشطيبة الشعبة من الشيء ويقال بعثنا إلى فلان شطيبة من خيلنا أي قطعة أخبرني الحسين بن يحيى عن حماد عن أبيه قال كانت مغنية تختلف إلى صديق لها فأتته يوما فوجدته مريضا لا حراك به فدعت بالعود وغنت\n(يا ربع بشرة إن أضر بك البلى ... فلقد عهدتك آهلا معمورا)\nمما يغنى به فيه من هذه الأبيات الرائية\n(أعرفت أطلال الرسوم تنكرت ... بعدي وغير ايهن دثورا)\n(وتبدلت بعد الأنيس بأهلها ... عفر البواقر يرتعين وعورا)\n(من كل مصبية الحديث ترى لها ... كفلا كرابية الكثيب وثيرا)\nالأطلال ما شخص من آثار الديار الرسوم البقايا من الديار وهي دون الأطلال وأخفى منها وتنكرت تغيرت والداثر الدارس والعفر الظباء واحدها أعفر والوعور المواضع التي لا أنيس فيها والرابية الأرض المشرفة وهي دون الجبل والكثيب القطعة العالية المرتفعة من الرمل جمعها كثب والوثير التام المرتفع يقال فراش وثير إذا كان مرتفعا عن الأرض لإسحاق الموصلي في البيتين الأولين ثاني ثقيل بالبنصر ولإبراهيم فيهما\nخفيف ثقيل بالسبابة في مجرى الوسطى ولطويس فيهما خفيف ثقيل وقيل إنه ليس له ولابن سريج في الثالث ثم الأول خفيف رمل وقيل بل هو لخليدة المكية وفي البيت الأول والثاني لمالك رمل بالوسطى وقيل الرمل لطويس وخفيف الثقيل لمالك ولمعبد في هذا الصوت لحنان أحدهما ثقيل أول مطلق في مجرى الوسطى والآخر خفيف ثقيل أول ومنها\n(يا دار حسرها البلى تحسيرا ... وسفت عليها الريح بعدك مورا)\n(دق التراب بخيلها فمخيم ... بعراصها ومسير تسييرا)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":18,"spl":"نسبة الأصوات التي في هذا الخبر","tags":["الكميت"],"song":8,"loc":2986,"partialRef":{"sid":"b216-24","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b216-26","bab":"الجزء 17","sec":"نسبة الأصوات التي في هذا الخبر","page":"ج17 ص51","text":"غنى في هذين البيتين ابن مسجح خفيف ثقيل الأول بالسبابة في مجرى الوسطى وللغريض في ( أعرفت أطلال الرسوم ...\nوما بعده ثقيل أول\nبالبنصر وللغريض أيضا ثاني ثقيل مطلق في مجرى الوسطى حسرها أذهب معالمها ومنه حسر الرجل عن ذراعه وعن رأسه إذا كشفهما وحسر الصلع شعر الرأس إذا حصه والمور التراب والمخيم المقيم ومنها صوت أوله\n(من كل مصبية الحديث ترى لها ... كفلا كرابية الكثيب وثيرا)\n(يفتن - لا يألون - كل مغفل ... يملأنه بحديثهن سرورا)\nمنها\n(دع ذا ولكن هل رأيت ظعائنا ... قربن أجمالا لهن قحورا)\n(قربن كل مخيس متحمل ... بزلا تشبه هامهن قبورا)\nلقحور واحدها قحر وهو المسن والمخيس المحبوس للرحلة والمتحمل معتاد الحمل وفي هذه الأربعة الأبيات الأربعة للغريض اللحن الذي ذكرناه ولابن جامع في\n(دع ذا ولكن هل رأيت ظعائنا ... )\nالذي بعده ثاني ثقيل بالوسطى ومنها\n(إن يمس حبلك بعد طول تواصل ... خلقا ويصبح بيتكم مهجورا)\n(فلقد أراني - والجديد إلى بلى - ... زمنا بوصلك راضيا مسرورا)\n(جذلا بمالي عندكم لا أبتغي ... للنفس بعدك خلة وعشيرا)\n(كنت الهوى وأعز من وطيء الحصا ... عندي وكنت بذاك منك جديرا)\nإبراهيم الموصلي ويحيى المكي في هذه الأبيات لحنان كلاهما من الثقيل الثاني فلحن إبراهيم بالوسطى ولحن يحيى بالبنصر ولإسحاق فيهما رمل وقيل إن لابن سريج فيهما أيضا لحنا آخر أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني رجل من أهل البصرة قال اشتريت جارية مغنية فأقامت عندي زمنا وهويتني وكرهت أن يراها أهلي فعرضتها للبيع فجزعت وقالت لقد اشتريتني وأنا لك كارهة وإنك لتبيعني وأنا لذلك كارهة فقال أخ لي أرنيها\nفقلت هي عند فلانة فانظر إليها فأتاها فنظر إليها وأنا حاضر فلما اعترضها وفرغ من ذلك غنت\n(إن يمس حبلك بعد طول تواصل ... خلقا ويصبح بيتكم مهجورا)\n(فلقد أراني - والجديد إلى بلى - ... زمنا بوصلك راضيا مسرورا)\nثم بكت وضربت بالعود الأرض فكسرته فخيرتها بين أن أعتقها أو أبيعها ممن شاءت فاختارت البيع وطلبت موضعا ترضاه حتى أصابته فصيرتها إليه أخبرني يحيى بن علي قال حدثني أبو أيوب المدائني قال حدثني إبراهيم بن علي بن هشام قال حدثتني جارية يقال لها طباع - جارية محمد بن سهل بن فرخند - قالت غنيت إسحاق في لحنه\n(أعرفت أطلال الرسوم تنكرت ... بعدي . . . .)\nأنكر علي في مقاطعة شيئا وقال ممن أخذته فقلت من مخارق فقال لي تعثر الجواد بل هو كما أقول لك ورده علي فهو يقال كما يقول مخارق وكما غيره إسحاق\n(أخشى على أربد الحتوف ولا ... أرهب نوء السماك والأسد)\n(فجعني الرعد والصواعق بالفارس ... يوم الكريهة النجد)\n(يا عين هلا بكيت أربد إذ ... قمنا وقام الخصوم في كبد)\n(إن يشغبوا لا يبال شغبهم ... أو يقصدوا في الخصام يقتصد)\nروضه من المنسرح النجد البطل ذو النجدة وقال الأصمعي في النجد مثل ذلك وقال النجد - بكسر الجيم - الذي قد عرق جدا والكبد الثبات والقيام الشعر للبيد بن ربيعة والغناء للأبجر رمل بالبنصر عن عمرو بن بانه ولإبراهيم فيها رمل آخر بالوسطى في مجراها عن إسحاق أوله الثالث والرابع ثم الأول والثاني وذكرت بذل أن في الثالث والرابع لحنا لحنين بن محرز","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":19,"spl":"نسبة الأصوات التي في هذا الخبر","tags":["الكميت"],"song":3,"loc":2987,"partialRef":{"sid":"b30-21","gi":1,"vi":3,"side":0},"partial":1},
{"id":"b216-28","bab":"الجزء 17","sec":"خبر لبيد في مرثية أخيه — وفد بني عامر بن صعصعة","page":"ج17 ص60 – ج17 ص61","text":"وقد تقدم من خبر لبيد ونسبه ما فيه كفاية يرثي أخاه لأمه أربد بن قيس بن جزء بن خالد بن جعفر بن كلاب وكانت أصابته صاعقة فأحرقته أخبرنا بالسبب في ذلك محمد بن جرير الطبري قال حدثنا محمد بن حميد قال حدثنا سلمة عن ابن إسحاق عن عاصم عن عمرو بن قتادة قال\nقدم على رسول الله وفد بني عامر بن صعصعة فيهم عامر بن\nالطفيل وأربد بن قيس وجبار بن سلمى بن مالك بن جعفر بن كلاب وكان هؤلاء الثلاثة رؤوس القوم وشياطينهم فهم عامر بن الطفيل بالغدر برسول الله وقد\nقال له قومه يا عامر إن الناس قد أسلموا فأسلم فقال والله لقد كنت آليت ألا أنتهي حتى تتبع العرب عقبي فأتبع أنا عقب هذا الفتى من قريش ثم\nقال لأربد إذا أقبلنا على الرجل فإني شاغل عنك وجهه فإذا فعلت ذلك فاعله أنت بالسيف فلما قدموا على رسول الله قال له عامر يا محمد خالني\nقال لا والله حتى تؤمن بالله وحده قال يا محمد خالني وجعل يكلمه وينتظر من أربد ما كان أمره فجعل أربد لا يحير شيئا فلما رأى عامر ما يصنع أربد\nقال يا محمد خالني قال لا والله حتى تؤمن بالله وحده لا تشرك به فلما أبى عليه رسول الله قال أما والله لأملأنها عليك خيلا حمرا ورجالا سمرا فلما ولى قال رسول الله اللهم اكفني عامر بن الطفيل فلما خرجوا من عند رسول الله قال عامر لأربد ويلك يا أربد أين ما كنت أوصيتك به والله ما كان على ظهر الأرض رجل هو أخوف عندي على نفسي منك وآيم الله لا أخافك بعد اليوم أبدا قال لا تعجل علي لا أبا لك والله ما هممت بالذي أمرتني به من مرة إلا دخلت بيني وبين الرجل حتى ما أرى غيرك أفأضربك بالسيف فقال عامر\n(بعث الرسول بما ترى فكأنما ... عمدا أشد على المقانب غارا)\n(ولقد وردن بنا المدينة شزبا ... ولقد قتلن بجوها الأنصارا)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":20,"spl":"خبر لبيد في مرثية أخيه — وفد بني عامر بن صعصعة","tags":["الكميت","السفر والحج"],"loc":2988},
{"id":"b216-30","bab":"الجزء 17","sec":"موت عامر — وفود لبيد إلى الرسول","page":"ج17 ص62 – ج17 ص63","text":"وخرجوا راجعين إلى بلادهم حتى إذا كانوا ببعض الطريق بعث الله على عامر الطاعون في عنقه فقتله الله وإنه لفي بيت امرأة من بني سلول فجعل يقول يا بني عامر أغدة كغدة البكر وموت في بيت امرأة من بني سلول فمات ثم خرج أصحابه حين واروه حتى قدموا أرض بني عامر فلما قدموا أتاهم قومهم فقالوا ما وراءك يا أربد فقال لقد دعانا إلى عبادة شيء لوددت أنه عندي الآن فأرميه بنبلي هذه حتى أقتله فخرج بعد مقالته هذه بيوم أو يومين معه جمل له يبيعه فأرسل الله عليه وعلى جمله صاعقة فأحرقتهما وكان أربد بن قيس أخا لبيد بن ربيعة لأمه نسخت من كتاب يحيى بن حازم قال حدثنا علي بن صالح صاحب المصلى قال حدثنا ابن دأب قال\nكان أبو براء عامر بن مالك قد أصابته دبيلة فبعث لبيد بن ربيعة إلى\nرسول الله وأهدى له رواحل فقدم بها لبيد وأمره أن يستشفيه من وجعه فقال له رسول الله لو قبلت من مشرك لقبلت منه وتناول من الأرض مدرة فتفل عليها ثم أعطاها لبيدا وقال دفها له بماء ثم إسقه إياه وأقام عندهم لبيد يقرأ القرآن وكتب منهم ( الرحمن علم القرآن\nفخرج بها ولقيه أخوه أربد على ليلة من الحي فقال له انزل فنزل فقال يا أخي أخبرني عن هذا الرجل فإنه لم يأته رجل أوثق عندي فيه قولا منك فقال يا أخي ما رأيت مثله وجعل يذكر صدقه وبره وحسن حديثه فقال له هل معك من قوله شيء\nقال نعم فأخرجها له فقرأها عليه فلما فرغ منها قال له أربد لوددت أني ألقى الرحمن بتلك البرقة فإن لم أضربه بسيفي فعلي وعلي قال ونشأت سحابة وقد خليا عن بعيريهما فخرج أربد يريد البعيرين حتى إذا كان عند تلك البرقة غشيته صاعقة فمات وقدم لبيد على أبي براء فأخبره خبر رسول الله وأمره\nقال فما فعل فيما استشفيته قال تالله ما رأيت منه شيئا كان أضعف عندي من ذلك وأخبره بالخبر قال فأين هي قال ها هي ذه معي قال هاتها فأخرجها له فدافها ثم شربها فبرأ\nقال ابن دأب فحدثني حنظلة بن قطرب بن إياد أحد بني أبي بكر بن كلاب قال لما أصاب عامر بن الطفيل ما أصابه بعث بنو عامر لبيدا وقالوا له\nاقدم لنا على هذا الرجل فاعلم لنا علمه فقدم عليه فأسلم وأصابه وجع هناك شديد من حمى فرجع إلى قومه بفضل تلك الحمى وجاءهم بذكر البعث والجنة والنار فقال سراقة بن عوف بن الأحوص\n(لعمر لبيد إنه لابن أمه ... ولكن أبوه مسه قدم العهد)\n(دفعناك في أرض الحجاز كأنما ... دفعناك فحلا فوقه قزع اللبد)\n(فعالجت حماه وداء ضلوعه ... وترنيق عيش مسه طرف الجهد)\n(وجئت بدين الصابئين تشوبه ... بألواح نجد بعد عهدك من عهد)\n(وإن لنا دارا - زعمت - ومرجعا ... وثم إياب القارظين وذي البرد)\nال فكان عمر يقول وايم الله إياب القارظين وذي البرد أخبرني عبد العزيز بن أحمد عم أبي وحبيب بن نصر المهلبي وغيرهما قالوا حدثنا الزبير بن بكار قال حدثتني ظمياء بنت عبد العزيز بن مولة قالت","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":21,"spl":"موت عامر — وفود لبيد إلى الرسول","tags":["الكميت","الجواري والنساء"],"loc":2989},
{"id":"b216-31","bab":"الجزء 17","sec":"وفود عامر بن الطفيل على الرسول","page":"ج17 ص65","text":"حدثني أبي عن جدي مولة بن كثيف أن عامر بن الطفيل أتى رسول\nالله فوسده وسادة ثم قال أسلم يا عامر قال على أن لي الوبر ولك المدر فأبى رسول الله فقام عامر مغضبا فولى وقال لأملأنها عليك خيلا جردا ورجالا مردا ولأربطن بكل نخلة فرسا فسألته عائشة من هذا فقال هذا عامر بن الطفيل والذي نفسي بيده لو أسلم فأسلمت بنو عامر معه لزاحموا قريشا على منابرهم\nقال ثم دعا رسول الله وقال يا فوم إذا دعوت فأمنوا فقال اللهم اهد بني عامر واشغل عني عامر بن الطفيل بما شئت وكيف شئت وأنى شئت فخرج فأخذته غدة مثل غدة البكر فجعل يثب وينزو في السماء ويقول يا موت ابرز لي ويقول غدة مثل غدة البكر وموت في بيت سلولية ومات\nأخبرني محمد بن الحسن بن دريد إجازة عن أبي حاتم عن أبي عبيدة قال أخبرني أسعد بن عمرو الجعفي قال أخبرني خالد بن قطن الحارثي قال لما مات عامر بن الطفيل خرجت امرأة من بني سلول كأنها نخلة حاسرا وهي تقول\n(أنعى عامر بن الطفيل وأبقى ... وهل يموت عامر من حقا)\n(وما أرى عامرا مات حقا ! ... )\nال فما رئي يوم أكثر باكيا وباكية وخمش وجوه وشق جيوب من ذلك اليوم وقال أبو عبيدة عن الحرمازي قال لما مات عامر بن الطفيل بعد منصرفه عن النبي نصبت عليه بنو عامر أنصابا ميلا في ميل حمى على قبره لا تنشر فيه ماشية ولا يرعى ولا يسلكه\nراكب ولا ماش وكان جبار بن سلمى بن عامر بن مالك بن جعفر بن كلاب غائبا فلما قدم قال ما هذه الأنصاب قالوا نصبناها حمى لقبر عامر بن الطفيل فقال ضيقتم علي أبي علي إن أبا علي بان من الناس بثلاث كان لا يعطش حتى يعطش الجمل وكان لا يضل حتى يضل النجم وكان لا يجبن حتى يجبن السيل قال أبو عبيدة وقدم عامر على النبي وهو ابن بضع وثمانين سنة","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":22,"spl":"وفود عامر بن الطفيل على الرسول","tags":["الكميت","الجواري والنساء","الموت"],"loc":2990,"partial":1},
{"id":"b216-32","bab":"الجزء 17","sec":"لبيد يرثي أخاه","page":"ج17 ص67","text":"ومما رثى به لبيد أخاه أربد قوله\n(ألا ذهب المحافظ والمحامي ... ودافع ضيمنا يوم الخصام)\n(وأيقنت التفرق يوم قالوا ... تقسم مال أربد بالسهام)\n(وأربد فارس الهيجا إذا ما ... تقعرت المشاجر بالفئام)\nهي طويلة يقول فيها\n(فودع بالسلام أبا حزيز ... وقل وداع أربد بالسلام)\nال وكانت كنية أربد أبا حزاز فصغره ضرورة وقال فيه أيضا\n(ما إن تعدى المنون من أحد ... لا والد مشفق ولا ولد)\n(أخشى على أربد الحتوف ولا ... أرهب نوء السماك والأسد)\n(فجعني الرعد والصواعق بالفارس ... يوم الكريهة النجد)\n(الحارب الجابر الحريب إذا ... جاء نكيبا وإن يعد يعد)\n(يعفو على الجهد والسؤال كما ... أنزل صوب الربيع ذي الرصد)\n(لم تبلغ العين كل نهمتها ... ليلة تمسي الجياد كالقدد)\n(كل بني حرة مصيرهم ... قل وإن أكثرت من العدد)\n(إن يغبطوا يهبطوا وإن أمروا ... يوما يصيروا للهلك والنفد)\n(يا عين هلا بكيت أربد إذ ... قمنا وقام الخصوم في كبد)\n(يا عين هلا بكيت أربد إذ ... ألوت رياح الشتاء بالعضد)\n(وأصبحت لاقحا مصرمة ... حين تقضت غوابر المدد)\n(إن يشغبوا لا يبال شغبهم ... أو يقصدوا في الخصام يقتصد)\n(حلو كريم وفي حلاوته ... مر لطيف الأحشاء والكبد)\nسخت من كتاب ابن النطاح عن المدائني عن علي بن مجاهد قال أنشد أبو بكر الصديق رضي الله عنه قول لبيد في أخيه أربد\n(لعمري لئن كان المخبر صادقا ... لقد رزئت في حادث الدهر جعفر)\n(أخ لي أما كل شيء سألته ... فيعطي وأما كل ذنب فيغفر)\nفقال أبو بكر رضوان الله عليه ذلك رسول الله لا أربد بن قيس وقد رثاه بعد ذلك بقصائد يطول الخبر بذكرها ومما رثاه به وفيه غناء قوله\n(بلينا وما تبلى النجوم الطوالع ... وتبقى الجبال بعدنا والمصانع)\n(وقد كنت في أكناف دار مضنة ... ففارقني جار بأربد نافع)\n(فلا جزع إن فرق الدهر بيننا ... فكل فتى يوما به الدهر فاجع)\n(وما المرء إلا كالشهاب وضوئه ... يحور رمادا بعد إذ هو ساطع)\n(أليس ورائي إن تراخت منيتي ... لزوم العصا تحنى عليها الأصابع)\n(أخبر أخبار القرون التي مضت ... أدب كأني كلما قمت راكع)\n(فأصبحت مثل السيف أخلق جفنه ... تقادم عهد القين والنصل قاطع)\n(فلا تبعدن إن المنية موعد ... علينا فدان للطلوع وطالع)\n(أعاذل ما يدريك إلا تظنيا ... إذا رحل السفار من هو راجع)\n(أتجزع مما أحدث الدهر للفتى ... وأي كريم لم تصبه القوارع !)\nنى في الأول والخامس والسادس والسابع حنين الحيري خفيف ثقيل أول بالبنصر عن الهشامي وابن المكي وحماد وفيها ثقيل أول بالوسطى يقال إنه لحنين أيضا ويقال إنه لأحمد النصبي ويقال إنه منحول ومما رثاه به قوله وهي من مختار مراثيه\n(طرب الفؤاد وليته لم يطرب ... وعناه ذكرى خلة لم تصقب)\n(سفها ولو أني أطعت عواذلي ... فيما يشرن به بسفح المذنب)\n(لزجرت قلبا لا يريع لزاجر ... إن الغوي إذا نهي لم يعتب)\n(فتعز عن هذا وقل في غيره ... واذكر شمائل من أخيك المنجب)\n(يا أربد الخير الكريم جدوده ... أفردتني أمشي بقرن أعضب)\n(إن الرزية لا رزية مثلها ... فقدان كل أخ كضوء الكوكب)\n(ذهب الذين يعاش في أكنافهم ... وبقيت في خلف كجلد الأجرب)\n(يتأكلون مغالة وخيانة ... ويعاب قائلهم وإن لم يشغب)\n(ولقد أراني تارة من جعفر ... في مثل غيث الوابل المتحلب)\n(من كل كهل كالسنان وسيد ... صعب المقادة كالفنيق المصعب)\n(من معشر سنت لهم آباؤهم ... والعز قد يأتي بغير تطلب)\n(فبرى عظامي بعد لحمي فقدهم ... والدهر إن عاتبت ليس بمعتب)\nدثنا محمد بن جرير الطبري قال حدثنا أبو السائب سالم بن جنادة قال حدثنا وكيع عن هشام بن عروة عن أبيه عن عائشة أنها كانت تنشد بيت لبيد\n(ذهب الذين يعاش في أكنافهم ... وبقيت في خلف كجلد الأجرب)\nثم تقول رحم الله لبيدا فكيف لو أدرك من نحن بين ظهرانيهم قال عروة رحم الله عائشة فكيف بها لو أدركت من نحن بين ظهرانيهم قال هشام رحم الله أبي فكيف لو أدرك من نحن بين ظهرانيهم\nوقال وكيع رحم الله هشاما فكيف لو أدرك من نحن بين ظهرانيهم قال أبو السائب رحم الله وكيعا فكيف لو أدرك من نحن بين ظهرانيهم قال أبو جعفر رحم الله أبا السائب فكيف لو أدرك من نحن بين ظهرانيهم قال أبو الفرج الأصبهاني ونحن نقول الله المستعان فالقصة أعظم من أن توصف","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":23,"spl":"لبيد يرثي أخاه","tags":["الكميت","السفر والحج"],"song":2,"loc":2991},
{"id":"b216-33","bab":"الجزء 17","sec":"لبيد يرثي أخاه","page":"ج17 ص67","text":"(فإن كان حقا ما زعمت أتيته ... إليك فقام النائحات على قبري)\n(وإن كان ما بلغته كان باطلا ... فلا مت حتى تسهري الليل من ذكري)\nروضه من الطويل والشعر للعباس بن الأحنف يقوله في فوز وخبرهما يأتي هاهنا والغناء لبذل خفيف رمل بالبنصر وفيه لبنان بن عمرو ثاني ثقيل بالبنصر وفيه لحن لابن جامع من كتاب إبراهيم وزعم أبو العباس أن لمعبد اليقطيني فيه خفيف رمل وذكر حبش أن لإبراهيم خفيف الرمل بالوسطى\nوذكر علي بن يحيى المنجم أنه لعلية وقيل إن خفيف الرمل بالبنصر للقاسم بن زنقطة والصحيح أنه لبذل","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":24,"spl":"لبيد يرثي أخاه — ذكر خبر العباس وفوز","tags":["الكميت"],"loc":2992},
{"id":"b216-34","bab":"الجزء 17","sec":"ذكر خبر العباس وفوز","page":"ج17 ص73","text":"أخبرني محمد بن يحيى قال حدثنا محمد بن إسحاق الخراساني قال حدثنا محمد بن النضر قال كانت فوز جارية لمحمد بن منصور وكان يلقب فتى العسكر ثم اشتراها بعض شباب البرامكة فدبرها وحج بها فلما قدمت قال العباس\n(ألا قد قدمت فوز ... فقرت عين عباس)\n(لمن بشرني البشرى ... على العينين والراس)\n(أيا ديباجة الحسن ... ويا رامشنة الآس)\n(يلوموني على الحب ... وما بالحب من باس)\nخبرني محمد قال حدثنا محمد بن أحمد بن جعفر الأنباري - وهو أبو عاصم بن محمد الكاتب - قال حدثني علي بن محمد النوفلي قال كانت فوز لرجل جليل من أسباب السلطان وكان العباس يتشبه في أشعاره وذكر فوز بما قاله أبو العتاهية في عتبة فحج بها مولاها فقال العباس\n(يا رب رد علينا ... من كان أنسا وزينا)\n(من لا نسر بعيش ... حتى يكون لدينا)\n(يا من أتاح لقلبي ... هواه شؤما وحينا)\n(ما زلت مذ غبت عني ... من أسخن الناس عينا)\n(ما كان حجك عندي ... إلا بلاء علينا)\nلما قدمت قال\n(ألا قد قدمت فوز ... فقرت عين عباس)\nذكر الأبيات المتقدمة أخبرنا محمد بن العباس اليزيدي قال حدثنا عبد الرحمن بن أخي الأصمعي عن عمه أنه دخل على الفضل بن الربيع يوما والعباس بن الأحنف بين يديه فقال العباس للفضل دعني أعابث الأصمعي قال لا تفعل فليس المزاح من شأنه قال إن رأى الأمير أن يفعل قال ذاك إليك قال فلما دخلت قال لي العباس يا أبا سعيد من الذي يقول\n(إذا أحببت أن تصنع ... شيئا يعجب الناسا)\n(فصور هاهنا فوزا ... وصور ثم عباسا)\n(فإن لم يدنوا حتى ... ترى رأسيهما راسا)\n(فكذبها بما قاست ... وكذبه بما قاسى)\nفقال لي ابن أبي السعلاء الشاعر إنه أراد العبث بك وهو نبطي فأجبه على هذا قال فقلت له لا أعرف هذا ولكني أعرف الذي يقول\n(إذا أحببت أن تبصر ... شيئا يعجب الخلقا)\n(فصور هاهنا زورا ... وصور ههنا فلقا)\n(فإن لم يدنوا حتى ... ترى خلقيهما خلقا)\n(فكذبها بما لاقت ... وكذبه بما يلقى)\nعرض بالعباس أنه نبطي فضحك الفضل فوجم العباس فقال له الفضل قد كنت نهيتك عنه فلم تقبل أخبرني محمد بن يحيى قال حدثني محمد بن الفضل الهاشمي قال حدثني أبو توبة الحنفي قال","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":24,"spl":"لبيد يرثي أخاه — ذكر خبر العباس وفوز","tags":["الكميت"],"loc":2993},
{"id":"b216-35","bab":"الجزء 17","sec":"العباس بن الأحنف والجارية فوز","page":"ج17 ص75","text":"وجه العباس بن الأحنف رسولا إلى فوز فعاد فأخبره أنها تجد صداعا وأنه رآها معصوبة الرأس فقال العباس\n(عصبت رأسها فليت صداعا ... قد شكته إلي كان براسي)\n(ثم لا تشتكي وكان لها الأجر ... وكنت السقام عنها أقاسي)\n(ذاك حتى يقول لي من رآني ... هكذا يفعل المحب المواسي)\nال فبرئت ثم نكست فقال\n(إن التي هامت بها النفس ... عاودها من عارض نكس)\n(كانت إذا ما جاءها المبتلى ... أبرأه من كفها اللمس)\n(وابأبي الوجه المليح الذي ... قد عشقته الجن والإنس)\n(إن تكن الحمى أضرت به ... فربما تنكسف الشمس)\nأخبرني محمد بن يحيى قال حدثني أبو العباس الخلنجي قال حدثني أبو عبد كان الكاتب قال حدثني أبو توبة الحنفي قال لما قال العباس بن الأحنف\n(أما والذي أبلى المحب وزادني ... بلاء لقد أسرفت في الظلم والهجر)\n(فإن كان حقا ما زعمت أتيته ... إليك فقام النائحات على قبري)\n(وإن كان عدوانا علي وباطلا ... فلا مت حتى تسهري الليل من ذكري)\nعثت إليه فوز أظننا ظلمناك يا أبا الفضل فاستجيب لك فينا ما زلت البارحة ساهرة ذاكرة لك أخبرني جحظة البرمكي قال حدثني أبو عبد الله بن حمدون عن أحمد بن إبراهيم قال حدثني محمد بن سلام قال كان في خلق العباس بن الأحنف شدة فضرب غلاما له وحلف أنه يبيعه فمضى الغلام إلى فوز فاستشفع بها عليه فكتبت إليه فيه فقال\n(يا من أتانا بالشفاعات ... من عند من فيه لجاجاتي)\n(إن كنت مولاك فإن التي ... قد شفعت فيك لمولاتي)\n(إرسالها فيك إلينا لنا ... كرامة فوق الكرامات)\nرضي عنه ووصله وأعتقه أخبرني جحظة قال حدثنا أبو عبد الله بن حمدون عن أبيه حمدون بن إسماعيل عن أخيه إبراهيم بن إسماعيل قال\nجاءنا العباس بن الأحنف يوما وهو كئيب فنشطناه فأبى أن ينشط فقلنا ما دهاك فقال لقيتني فوز اليوم فقالت لي يا شيخ وما قالت ذلك إلا من حادث ملال فقلنا له هون عليك فإنها امرأة لا تثبت على حال وما أرادت إلا العبث بك والمزاح معك فقال إني والله قد قلت أقبح مما قالت ثم أنشدنا\n(هزئت إذ رأت كئيبا معنى ... أقصدته الخطوب فهو حزين)\n(هزئت بي ونلت ما شئت منها ... يا لقومي فأينا المغبون)\nقلت له لقد انتصفت وزدت أخبرني محمد بن يحيى قال حدثنا علي بن الصباح قال حدثنا أبو ذكوان قال كانت لفوز جارية يقال لها يمن وكانت تجيء إلى العباس برسالتها فمضت إلى فوز وقد طلبت من العباس شيئا فمنعها إياه وزعمت أنه أرادها ودعاها إلى نفسه فغضبت فوز من ذلك فكتب إليها\n(لقد زعمت يمن بأني أردتها ... على نفسها تبا لذلك من فعل)\n(سلوا عن قميصي مثل شاهد يوسف ... فإن قميصي لم يكن قد من قبل)\nخبرني محمد قال حدثنا أحمد بن إسماعيل قال حدثني سعيد بن حميد قال\nكانت فوز قد مالت إلى بعض أولاد الجند وبلغ ذلك العباس فتركها ولم ترض هي البديل بعد ذلك فعادت إلى العباس وكتبت إليه تعاتبه في جفائه فكتب إليها\n(كتبت تلوم وتستريب زيارتي ... وتقول لست لنا كعهد العاهد)\n(فأجبتها ودموع عيني جمة ... تجري على الخدين غير جوامد)\n(يا فوز لم أهجركم لملالة ... مني ولا لمقال واش حاسد)\n(لكنني جربتكم فوجدتكم ... لا تصبرون على طعام واحد)\nقد أنشدني علي بن سليمان الأخفش هذه الأبيات وقال سرقها من أبي نواس حيث يقول\n(ومظهرة لخلق الله ودا ... وتلقى بالتحية والسلام)\n(أتيت فؤادها أشكو إليه ... فلم أخلص إليه من الزحام)\n(فيا من ليس يكفيه محب ... ولا ألفا محب كل عام)\n(أظنك من بقية قوم موسى ... فهم لا يصبرون على طعام)\nنت فيه عريب لحنا ذكره ابن المعتز ولم يذكر طريقته\nومما يغنى فيه من شعر العباس في فوز قوله\n(يا فوز ما ضر من يمسي وأنت له ... ألا يفوز بدنيا آل عباس)\n(أبصرت شيبا بمولاها فواعجبا ... منه يراها ويبدو الشيب في الراس)\nناه سليم رمل مطلق في مجرى الوسطى عن ابن المكي وأخبرني محمد بن يحيى قال حدثنا محمد بن الفضل بن الأسود قال قرأت على أحمد بن أبي فنن شعر العباس بن الأحنف وكان مشغوفا به فسمعته يقول وددت أن أبياته التي يقول فيها\n(يا فوز ما ضر من يمسي وأنت له ... )\nي بكل شعري وفي بذل يقول عبد الله بن العباس الربيعي يخاطب عمرا في بذل بقوله\n(تسمع بحق الله يا عمرو من بذل ... فقد أحسنت والله واعتمدت قتلي)\n(كأني أرى حبيك يرجح كلما ... تغنت لإعجابي وأفقد من عقلي)","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":25,"spl":"العباس بن الأحنف والجارية فوز","tags":["الكميت"],"song":3,"loc":2994,"partial":1},
{"id":"b216-36","bab":"الجزء 17","sec":"العباس بن الأحنف والجارية فوز","page":"ج17 ص75","text":"ناه عبد الله بن العباس الربيعي ثاني ثقيل بالوسطى عن عمرو وغنى فيه عمرو بن بانة خفيف رمل بالبنصر عن حبش","topic":"ذكر الكميت ونسبه وخبره","topicNo":216,"sp":26,"spl":"العباس بن الأحنف والجارية فوز","tags":["الكميت","اللهو والمزاح"],"loc":2995},
{"id":"b217-1","bab":"الجزء 17","sec":"ذكر بذل وأخبارها","page":"ج17 ص80","text":"كانت بذل صفراء مولدة من مولدات المدينة وربيت بالبصرة وهي إحدى المحسنات المتقدمات الموصوفات بكثرة الرواية يقال إنها كانت تغني ثلاثين ألف صوت ولها كتاب في الأغاني منسوب الأصوات غير مجنس يشتمل على اثني عشر ألف صوت يقال إنها عملته لعلي بن هشام وكانت حلوة الوجه ظريفة ضاربة متقدمة وابتاعها جعفر بن موسى الهادي فأخذها منه محمد الأمين وأعطاه مالا جزيلا فولدهما جميعا يدعون ولاءها فأخذت بذل عن أبي سعيد مولى فائد ودحمان وفليح وابن جامع وإبراهيم وطبقتهم وقرأت على جحظة عن أبي حشيشة في كتابه الذي جمعه من أخباره وما شاهده\nقال كانت بذل من أحسن الناس غناء في دهرها وكانت أستاذة كل محسن ومحسنة وكانت صفراء مدنية وكانت أروى خلق الله تعالى للغناء ولم يكن لها معرفة\nوكانت لجعفر بن موسى الهادي فوصفت لمحمد بن زبيدة فبعث إلى جعفر يسأله أن يريه إياها فأبى فزاره محمد إلى منزله فسمع شيئا لم يسمع مثله فقال لجعفر يا أخي بعني هذه الجارية فقال يا سيدي مثلي لا يبيع جارية\nقال فهبها لي قال هي مدبرة فاحتال عليه محمد حتى أسكره وأمر ببذل فحملت معه إلى الحراقة وانصرف بها فلما انتبه سأل عنها فأخبر بخبرها فسكت فبعث إليه محمد من الغد فجاءه وبذل جالسة فلم يقل شيئا فلما أراد جعفر أن ينصرف\nقال أوقروا حراقة ابن عمي دراهم فأوقرت قال فحدثني عبد الله بن الحنيني - وكان أبوه على بيت مال جعفر بن موسى - أن مبلغ ذلك المال كان عشرين ألف ألف درهم\nقال وبقيت بذل في دار محمد إلى أن قتل ثم خرجت فكان ولد جعفر وولد محمد يدعون ولاءها فلما ماتت ورثها ولد عبد الله بن محمد بن زبيدة وقد\nروى محمد بن الحسن الكاتب هذا الخبر عن ابن المكي عن أبيه وقال فيه إن محمدا وهب لها من الجوهر شيئا لم يملك أحد مثله فسلم لها فكانت تخرج منه الشيء بعد الشيء فتبيعه بالمال العظيم فكان ذلك معتمدها مع ما يصل إليها من الخلفاء إلى أن ماتت وعندها منه بقية عظيمة قال ورغب إليها وجوه القواد والكتاب والهاشميين في التزويج فأبت وأقامت على حالها حتى ماتت","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":0,"spl":"ذكر بذل وأخبارها","tags":["الجواري والنساء"],"loc":2996},
{"id":"b217-2","bab":"الجزء 17","sec":"بذل وعلي بن هشام","page":"ج17 ص81","text":"قال أبو حشيشة في خبره وكنت عند بذل يوما وأنا غلام وذلك في أيام\nالمأمون ببغداد وهي في طارمة لها تمتشط ثم خرجت إلى الباب فرأيت الموكب فظننت أن الخليفة يمر في ذلك الموضع فرجعت إليها فقلت يا ستي الخليفة يمر على بابك فقالت انظروا أي شيء هذا إذ دخل بوابها فقال علي بن هشام بالباب فقالت وما أصنع به فقامت إليها وشيكة جاريتها - وكانت ترسلها إلى الخليفة وغيره في حوائجها - فأكبت على رجلها وقالت الله الله أتحجبين علي بن هشام فدعت بمنديل فطرحته على رأسها ولم تقم إليه فقال إني جئتك بأمر سيدي أمير المؤمنين وذلك أنه سألني عنك فقلت لم أرها منذ أيام فقال هي عليك غضبى فبحياتي لا تدخل منزلك حتى تذهب إليها فتسترضيها فقالت إن كنت جئت بأمر الخليفة فأنا أقوم فقامت فقبلت رأسه ويديه وقعد ساعة وانصرف فساعة خرج قالت يا وشيكة هاتي دواة وقرطاسا فجعلت تكتب فيه يومها وليلتها حتى كتبت اثني عشر ألف صوت - وفي بعض النسخ رؤوس سبعة آلاف صوت - ثم كتبت إليه يا علي بن هشام تقول قد استغنيت عن بذل بأربعة آلاف صوت أخذناها منها وقد كتبت هذا وأنا ضجرة فكيف لو فرغت لك قلبي كله وختمت الكتاب وقالت لها امضي به إليه فما كان أسرع من أن جاء رسوله خادم أسود يقال له مخارق - بالجواب يقول فيه يا ستي لا والله ما\nقلت الذي بلغك ولقد كذب علي عندك إنما قلت لا ينبغي أن يكون في الدنيا غناء أكثر من أربعة آلاف صوت وقد بعثت إلي بديوان لا أؤدي شكرك عليه أبدا وبعث إليها عشرة آلاف درهم وتخوتا فيها خز ووشي وملح وتختا مطبقا فيه ألوان الطيب\nأنشدني علي بن سليمان الأخفش لعلي بن هشام يعاتب بذلا في جفوة نالته منها\n(تغيرت بعدي والزمان مغير ... وخست بعهدي والملوك تخيس)\n(وأظهرت لي هجرا وأخفيت بغضة ... وقربت وعدا واللسان عبوس)\n(ومما شجاني أنني يوم زرتكم ... حجبت وأعدائي لديك جلوس)\n(وفي دون ذا ما يستدل به الفتى ... على الغدر من أحبابه ويقيس)\n(كفرت بدين الحب إن طرت بابكم ... وتلك يمين - ما علمت - غموس)\n(فإن ذهبت نفسي عليكم تشوقا ... فقد ذهبت للعاشقين نفوس)\n(ولو كان نجمي في السعود وصلتم ... ولكن نجوم العاشقين نحوس)\nوأخبرني أبو العباس الهشامي المشك عن أهله أن علي بن هشام كان يهوى بذلا ويكتم ذلك وأنها هجرته مدة فكتب إليها بهذه الأبيات وذكر محمد بن الحسن أن أبا حارثة حدثه عن أخيه أن معاوية قال قالت لي بذل كنت أروي ثلاثين ألف صوت فلما تركت الدرس أنسيت نصفها فذكرت قولها لزرزر الكبير فقال كذبت الزانية","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":1,"spl":"بذل وعلي بن هشام — إجادتها صنعة الغناء","tags":["الحب والغزل"],"loc":2997},
{"id":"b217-3","bab":"الجزء 17","sec":"إجادتها صنعة الغناء","page":"ج17 ص83","text":"قال وحدثني أحمد بن محمد بن الفيزران عن بعض أصحابه - أن\nإبراهيم بن المهدي كان يعظمها ويتوافى لها ثم تغير بعد ذلك استغناء عند نفسه عنها فصارت إليه فدعا بعود فغنت - في طريقة واحدة وإيقاع واحد وإصبع واحدة - مائة صوت لم يعرف إبراهيم منها صوتا واحدا ووضعت العود وانصرفت فلم تدخل داره حتى طال طلبه لها وتضرعه إليها في الرجوع إليه\nوقال محمد بن الحسن وذكر أحمد بن سعيد المالكي أن إسحاق بن إبراهيم الموصلي خالف بذلا في نسبة صوت غنته بحضرة المأمون فأمسكت عنه ساعة ثم غنت ثلاثة أصوات في الثقيل الثاني واحدا بعد واحد وسألت إسحاق عن صانعها فلم يعرفه فقالت للمأمون يا أمير المؤمنين هي والله لأبيه أخذتها من فيه فإذا كان هذا لا يعرف غناء أبيه فكيف يعرف غناء غيره فاشتد ذلك على إسحاق حتى رئي ذلك فيه أخبرني أبو الحسن الأسدي قال حدثني حماد بن إسحاق قال غنت بذل يوما بين يدي أبي\n(إن تريني ناحل البدن ... فلطول الهم والحزن)\n(كان ما أخشى بواحدتي ... ليته والله لم يكن)\nطرب أبي والله طربا شديدا وشرب رطلا وقال لها أحسنت يا بنتي والله لا تغنين صوتا إلا شربت عليه رطلا قال أبو الفرج والغناء في هذا الشعر لبذل خفيف رمل بالوسطى وذكر أحمد بن أبي طاهر أن محمد بن علي بن طاهر بن الحسين حدثه أن المأمون كان يوما قاعدا يشرب وبيده قدح إذ غنت بذل\n(ألا لا أرى شيئا ألذ من الوعد ... )\nفجعلته\n(ألا لا أرى شيئا ألذ من السحق ... )\nوضع المأمون القدح من يده والتفت إليها وقال بلى يا بذل النيك ألذ من السحق فتشورت وخافت غضبه فأخذ قدحه ثم قال أتمي صوتك وزيدي فيه\n(ومن غفلة الواشي إذا ما أتيتها ... ومن زورتي أبياتها خاليا وحدي)\n(ومن صيحة في الملتقى ثم سكتة ... وكلتاهما عندي ألذ من الخلد)","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":1,"spl":"بذل وعلي بن هشام — إجادتها صنعة الغناء","tags":[],"loc":2998,"partial":1},
{"id":"b217-4","bab":"الجزء 17","sec":"نسبة هذا الصوت","page":"ج17 ص85","text":"(ألا لا أرى شيئا ألذ من الوعد ... ومن أملي فيه وإن كان لا يجدي)\nلغناء لإبراهيم خفيف رمل بالبنصر في رواية عمرو بن بانة\n(بانت سعاد فقلبي اليوم متبول ... متيم عندها لم يجز مكبول)\n(وما سعاد غداة البين إذ رحلوا ... إلا أغن غضيض الطرف مكحول)\nلشعر لكعب بن زهير بن أبي سلمى المزني والغناء لابن محرز ثاني ثقيل بالبنصر عن عمرو بن بانة والهشامي","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":2,"spl":"نسبة هذا الصوت — أخبار كعب بن زهير","tags":["السفر والحج"],"song":1,"loc":2999},
{"id":"b217-5","bab":"الجزء 17","sec":"أخبار كعب بن زهير","page":"ج17 ص87","text":"كعب بن زهير بن أبي سلمى المزني وقد تقدم خبر أبيه ونسبه وأم كعب امرأة من بني عبد الله بن غطفان يقال لها كبشة بنت عمار بن عدي بن سحيم وهي أم سائر أولاد زهير وهو من المخضرمين ومن فحول الشعراء وسأله الحطيئة أن يقول شعرا يقدم فيه نفسه ثم يثني به بعده ففعل أخبرنا أبو خليفة عن محمد بن سلام\nوأخبرني محمد بن الحسن بن دريد عن أبي حاتم عن أبي عبيدة قالا أتى الحطيئة كعب بن زهير - وكان الحطيئة راوية زهير وآل زهير - فقال له يا كعب قد علمت روايتي لكم أهل البيت وانقطاعي إليكم وقد ذهب الفحول غيري وغيرك فلو\nقلت شعرا تذكر فيه نفسك وتضعني موضعا بعدك وقال أبو عبيدة في خبره تبدأ بنفسك فيه وتثني بي فإن الناس لأشعاركم أروى وإليها أسرع فقال كعب\n(فمن للقوافي شانها من يحوكها ... إذا ما ثوى كعب وفوز جرول)\n(يقول فلا تعيا بشيء يقوله ... ومن قائليها من يسيء ويعمل)\n(كفيتك لا تلقى من الناس واحدا ... تنخل منها مثل ما يتنخل)\n(يثقفها حتى تلين متونها ... فيقصر عنها كل ما يتمثل)\nخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا علي بن الصباح عن هشام عن إسحاق بن الجصاص قال قال زهير بيتا ونصفا ثم أكدى فمر به النابغة فقال له أبا أمامة أجز فقال وما قلت قال قلت\n(تزيد الأرض إما مت خفا ... وتحيا إن حييت بها ثقيلا)\n(نزلت بمستقر العرض منها ... )\nجز قال فأكدى والله النابغة وأقبل كعب بن زهير وإنه لغلام فقال أبوه أجز يا بني فقال وما أجيز فأنشده فأجاز النصف بيت فقال\n(وتمنع جانبيها أن يزولا ... )\nضمه زهير إليه وقال أشهد أنك ابني","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":2,"spl":"نسبة هذا الصوت — أخبار كعب بن زهير","tags":["الجواري والنساء","الرواية والكتابة"],"loc":3000,"partial":1},
{"id":"b217-6","bab":"الجزء 17","sec":"زهير ينهاه عن الشعر ثم يأذن له","page":"ج17 ص88","text":"وقال ابن الأعرابي قال حماد الراوية\nتحرك كعب بن زهير وهو يتكلم بالشعر فكان زهير ينهاه مخافة أن يكون لم يستحكم شعره فيروى له ما لا خير فيه فكان يضربه في ذلك فكلما ضربه يزيد فيه فغلبه فطال عليه ذلك فأخذه فحبسه فقال والذي أحلف به لا تتكلم ببيت شعر إلا ضربتك ضربا ينكلك عن ذلك فمكث محبوسا عدة أيام ثم أخبر أنه يتكلم به فدعاه فضربه ضربا شديدا ثم أطلقه وسرحه في بهمة وهو غليم صغير فانطلق فرعى ثم راح عشية وهو يرتجز\n(كأنما أحدو ببهمي عيرا ... من القرى موقرة شعيرا)\nفخرج إليه زهير وهو غضبان فدعا بناقته فكفلها بكسائه ثم قعد عليها حتى انتهى إلى ابنه كعب فأخذ بيده فأردفه خلفه ثم خرج فضرب ناقته وهو يريد أن يبعث ابنه كعبا ويعلم ما عنده من الشعر فقال زهير حين برز إلى الحي\n(إني لتعديني على الحي جسرة ... تخب بوصال صروم وتعنق)\nم ضرب كعبا وقال له أجز يا لكع فقال كعب\n(كبنيانة القرئي موضع رحلها ... وآثار نسعيها من الدف أبلق)\nقال زهير\n(على لاحب مثل المجرة خلته ... إذا ما علا نشزا من الأرض مهرق)\nجزيا لكع فقال كعب\n(منير هداه ليله كنهاره ... جميع إذا يعلو الحزونة أفرق)\nال فتبدى زهير في نعت النعام وترك الإبل يتعسفه عمدا ليعلم ما عنده قال\n(وظل بوعساء الكثيب كأنه ... خباء على صقبي بوان مروق)\nقبي عمودي بوان عمود من أعمدة البيت فقال كعب\n(تراخى به حب الضحاء وقد رأى ... سماوة قشراء الوظيفين عوهق)\nقال زهير\n(تحن إلى مثل الحبابير جثم ... لدى منتج من قيضها المتفلق)\nلحبابير جمع حبارى وتجمع أيضا حباريات فقال كعب\n(تحطم عنها قيضها عن خراطم ... وعن حدق كالنبخ لم يتفتق)\nالخراطم هاهنا المناقير والنبخ الجدري شبه أعين ولد النعامة به\nقال فأخذ زهير بيد ابنه كعب ثم قال له قد أذنت لك في الشعر يا بني فلما نزل كعب وانتهى إلى أهله - وهو صغير يومئذ - قال\n(أبيت فلا أهجو الصديق ومن يبع ... بعرض أبيه في المعاشر ينفق)\nال وهي أول قصيدة قالها أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني إبراهيم بن المنذر الحزامي\nقال حدثني الحجاج بن ذي الرقيبة بن عبد الرحمن بن مضرب بن كعب بن زهير بن أبي سلمى عن أبيه عن جده قال خرج كعب وبجير ابنا زهير بن أبي سلمى إلى رسول الله حتى بلغا أبرق العزاف فقال كعب لبجير الحق الرجل وأنا مقيم هاهنا فانظر ما يقول لك فقدم بجير على رسول الله فسمع منه وأسلم وبلغ ذلك كعبا فقال\n(ألا أبلغا عني بجيرا رسالة ... على أي شيء - ويب غيرك - دلكا)\n(على خلق لم تلف أما ولا أبا ... عليه ولم تدرك عليه أخا لكا)\n(سقاك أبو بكر بكأس روية ... فأنهلك المأمون منها وعلكا)","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":3,"spl":"زهير ينهاه عن الشعر ثم يأذن له","tags":["الحب والغزل"],"loc":3001},
{"id":"b217-7","bab":"الجزء 17","sec":"الرسول يهدر دمه","page":"ج17 ص92","text":"ويروى المأمور قال فبلغت أبياته هذه رسول الله فأهدر دمه وقال من لقي منكم كعب بن زهير فليقتله فكتب إليه أخوه بجير يخبره وقال له انجه وما أراك بمفلت وكتب إليه بعد ذلك يأمره أن يسلم ويقبل إلى رسول الله ويقول له إن من شهد أن لا إله إلا الله وأن محمدا رسوله قبل منه وأسقط ما كان قبل ذلك فأسلم كعب وقال القصيدة التي اعتذر فيها إلى رسول الله\n(بانت سعاد فقلبي اليوم متبول ... متيم عندها لم يجز مكبول)\nال ثم أقبل حتى أناخ راحلته بباب مسجد رسول الله وكان مجلسه من أصحابه مكان المائدة من القوم حلقة ثم حلقة ثم حلقة وهو وسطهم فيقبل على هؤلاء يحدثهم ثم على هؤلاء ثم على هؤلاء فأقبل كعب حتى دخل المسجد فتخطى حتى جلس إلى رسول الله فقال يا رسول الله الأمان قال ومن أنت قال كعب بن زهير قال أنت الذي يقول . . كيف قال يا أبا بكر فأنشده حتى بلغ إلى قوله\n(سقاك أبو بكر بكأس روية ... وأنهلك المأمون منها وعلكا)\nقال رسول الله مأمون والله ثم أنشده - يعني كعبا -\n(بانت سعاد فقلبي اليوم متبول ... )\nال عمر بن شبة فحدثني الحزامي قال حدثني محمد بن فليح عن موسى بن عقبة وأخبرني بمثل ذلك أحمد بن الجعد قال حدثنا محمد بن إسحاق المسيبي قال حدثنا محمد بن فليح عن موسى بن عقبة قال أنشدها رسول الله في مسجده فلما بلغ إلى قوله\n(إن الرسول لسيف يستضاء به ... مهند من سيوف الله مسلول)\n(في فتية من قريش قال قائلهم ... ببطن مكة لما أسلموا زولوا)\n(زالوا فما زال أنكاس ولا كشف ... عند اللقاء ولا خور معازيل)\nشار رسول الله إلى الحلق أن يسمعوا شعر كعب بن زهير قال الحزامي قال علي بن المديني لم أسمع قط في خبر كعب بن زهير حديثا قط أتم ولا أحسن من هذا ولا أبالي ألا أسمع من خبره غير هذا","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":4,"spl":"الرسول يهدر دمه","tags":["السفر والحج"],"loc":3002,"partialRef":{"sid":"b217-4","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b217-8","bab":"الجزء 17","sec":"إسلام بجير وكعب","page":"ج17 ص93","text":"قال أبو زيد عمر بن شبة ومما يروى من خبره أن زهيرا كان نظارا متوقيا وأنه رأى في منامه آتيا أتاه فحمله إلى السماء حتى كاد يمسها بيده ثم تركه فهوى إلى الأرض فلما احتضر قص رؤياه على ولده\nوقال إني لا أشك أنه كائن من خبر السماء بعدي شيء فإن كان فتمسكوا به وسارعوا إليه فلما بعث النبي خرج إليه بجير بن زهير فأسلم ثم رجع إلى بلاد قومه فلما هاجر رسول الله أتاه بجير بالمدينة - وكان من خيار المسلمين وشهد يوم الفتح مع رسول الله ويوم خيبر ويوم حنين وقال في ذلك\n(صبحناهم بألف من سليم ... وألف من بني عثمان واف)\n(فرحنا والجياد تجول فيهم ... بأرماح مثقفة خفاف)\n(وفي أكتافهم طعن وضرب ... ورشق بالمريشة اللطاف)\nم ذكر خبره وخبر أخيه كعب مثل ما ذكر الحزامي وزاد في الأبيات التي كتب بها كعب إليه\n(فخالفت أسباب الهدى وتبعته ... فهل لك فيما قلت بالخيف هل لكا)\nم قال في خبره أيضا إن كعبا نزل برجل من جهينة فلما أصبح أتى النبي عليه السلام فقال يا رسول الله أرأيت إن أتيتك بكعب بن زهير مسلما أتؤمنه قال نعم قال فأنا كعب بن زهير فتواثبت الأنصار تقول يا رسول الله ائذن لنا فيه فقال وكيف وقد أتاني مسلما وكف عنه المهاجرون ولم يقولوا شيئا فأنشد رسول الله قصيدته\n(بانت سعاد فقلبي اليوم متبول ... )\nحتى انتهى إلى قوله\n(لا يقع الطعن إلا في نحورهم ... وما بهم عن حياض الموت تهليل)\nكذا في رواية عمر بن شبة ورواية غيره تعليل فعند ذلك أومأ رسول الله إلى الحلق حوله أن تسمع منه قال وعرض بالأنصار في قصيدته في عدة مواضع منها قوله\n(كانت مواعيد عرقوب لها مثلا ... وما مواعيدها إلا الأباطيل)\nوعرقوب رجل من الأوس فلما سمع المهاجرون بذلك قالوا ما مدحنا من هجا الأنصار فأنكروا قوله وعوتب على ذلك فقال\n(من سره كرم الحياة فلا يزل ... في مقنب من صالحي الأنصار)\n(الباذلين نفوسهم لنبيهم ... عند الهياج وسطوة الجبار)\n(والناظرين بأعين محمرة ... كالجمر غير كليلة الإبصار)\n(والضاربين الناس عن أديانهم ... بالمشرفي وبالقنا الخطار)\n(يتطهرون يرونه نسكا لهم ... بدماء من علقوا من الكفار)\n(صدموا الكتيبة يوم بدر صدمة ... ذلت لوقعتها رقاب نزار)\nال أبو زيد الذي عناه كعب رجل من الأوس كان وعد رجلا ثمر نخلة فلما أطلعت أتاه فقال دعها حتى تلقح فلما لقحت قال دعها حتى تزهي فلما أزهت أتاه فقال دعها حتى ترطب ثم أتاه فقال دعها حتى تتمر فلما أتمرت عدا عليها ليلا فجدها فضرب به في الخلف المثل وذلك قول الشماخ\n(وواعدني ما لا أحاول نفعه ... مواعيد عرقوب أخاه بيترب)\nوقال المتلمس لعمرو بن هند\n(من كان خلف الوعد شيمته ... والغدر عرقوب له مثل)\nما قالته الشعراء في ذكر عرقوب يكثر قال إبراهيم بن المنذر حدثني معن بن عيسى قال حدثني الأوقص محمد بن عبد الرحمن المخزومي قال حدثني علي بن زيد أن كعب بن زهير أنشد رسول الله هذه القصيدة في المسجد الحرام لا في مسجد المدينة قال إبراهيم حدثني محمد بن الضحاك بن عثمان عن أبيه قال عنى كعب بن زهير بقوله\n(في فتية من قريش قال قائلهم ... )\nمر بن الخطاب رضي الله عنه\n(أبيني أفي يمنى يديك جعلتني ... فأفرح أم صيرتني في شمالك)\n(أبيت كأني بين شقين من عصا ... حذار الردى أو خيفة من زيالك)\n(تعاللت كي أشجى وما بك علة ... تريدين قتلي قد ظفرت بذلك)\nعروضه من الطويل الشعر لابن الدمينة بعضه وبعضه ألحقه المغنون به وهو لغيره والغناء لابن جامع ثاني ثقيل بالوسطى وفيه لإبراهيم ثقيل أول بالبنصر","topic":"ذكر بذل وأخبارها","topicNo":217,"sp":5,"spl":"إسلام بجير وكعب","tags":[],"song":1,"loc":3003,"partialRef":{"sid":"b217-7","gi":3,"vi":1,"side":0},"partial":1},
{"id":"b218-2","bab":"الجزء 17","sec":"أخبار ابن الدمينة ونسبه — مزاحم بن عمرو يرمى بامرأته ويشهر به","page":"ج17 ص98 – ج17 ص99","text":"الدمينة أمه وهي الدمينة بنت حذيفة السلولية واسم ابن الدمينة عبد الله بن عبيد الله أحد بني عامر بن تيم الله بن مبشر بن أكلب بن ربيعة بن عفرس بن حلف بن أفتل وهو خثعم بن أنمار بن إراش بن عمرو بن الغوث بن نبت بن مالك\nوقيل إن أكلب هو ابن ربيعة بن نزار ليس ابن ربيعة بن عفرس وإنهم حالفوا خثعم ونزلوا فيهم فنسبوا إليهم ويكنى ابن الدمينة أبا السري وكان بلغه أن رجلا من أخواله من سلول يأتي امرأته ليلا فرصده حتى أتاها فقتله ثم قتلها بعده ثم اغتالته سلول بعد ذلك فقتلته\nأخبرني بخبره علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري عن محمد بن حبيب عن أبي عبيدة وابن الأعرابي وأضفت إلى ذلك ما رواه الزبير بن بكار عن أصحابه وما اتفقت الروايتان فيه فإذا اختلفتا نسبت كل خبر إلى راويه\nقال الزبير حدثني موهوب بن رشيد الكلابي وإبراهيم بن سعد السلمي وعمر بن إبراهيم السعدي عن ميناس بن عبد الصمد عن مصعب بن عمرو السلولي أخي مزاحم بن عمرو قالوا جميعا إن رجلا من سلول يقال له مزاحم بن عمرو كان يرمى بامرأة ابن الدمينة وكان اسمها حماء قال السكري كان اسمها حمادة فكان يأتيها ويتحدث إليها حتى اشتهر ذلك فمنعه ابن الدمينة من إتيانها واشتد عليها فقال مزاحم يذكر ذلك - وهذا من رواية ابن حبيب وهي أتم وأصح -\n(يا بن الدمينة والأخبار يرفعها ... وخد النجائب والمحقور يخفيها)\n(يا بن الدمينة إن تغضب لما فعلت ... فطال خزيك أو تغضب مواليها)\n(أو تبغضوني فكم من طعنة نفذ ... يغذو خلال اختلاج الجوف غاذيها)\n(جاهدت فيها لكم إني لكم أبدا ... أبغي معايبكم عمدا فآتيها)\n(فذاك عندي لكم حتى تغيبني ... غبراء مظلمة هار نواحيها)\n(أغشى نساء بني تيم إذا هجعت ... عني العيون ولا أبغي مقاريها)\n(كم كاعب من بني تيم قعدت لها ... وعانس حين ذاق النوم حاميها)\n(كقعدة الأعسر العلفوف منتحيا ... متينة من متون النبل ينحيها)\n(وشهقة عند حس الماء تشهقها ... وقول ركبتها قض حين تثنيها)\n(علامة كية ما بين عانتها ... وبين سبتها لا شل كاويها)\n(وتعدل الأير إن زاغت فتبعثه ... حتى يقيم برفق صدره فيها)\n(بين الصفوقين في مستهدف ومد ... ذي حرة ذاق طعم الموت صاليها)\n(ماذا ترى ابن عبيد الله في امرأة ... ليست بمحصنة عذراء حاويها)\n(أيام أنت طريد لا تقاربها ... وصادف القوس في الغرات باريها)\n(ترى عجوز بني تيم ملفعة ... شمطا عوارضها ربدا دواهيها)\n(إذ تجعل الدفنس الورهاء عذرتها ... قشارة من أديم ثم تفريها)\n(حتى يظل هدان القوم يحسبها ... بكرا وقبل هوى في الدار هاويها)\nال الزبير عن رجاله وابن حبيب عن ابن الأعرابي لما بلغ ابن الدمينة شعر مزاحم أتى امرأته فقال لها قد قال فيك هذا الرجل ما قال وقد بلغك قالت والله ما أرى ذلك مني قط\nقال فمن أين له العلامات قالت وصفهن له النساء قال هيهات والله أن يكون ذلك كذلك ثم أمسك مدة وصبر حتى ظن أن مزاحما قد نسي القصة ثم أعاد عليها القول وأعادت الحلف أن ذلك مما وصفه له النساء فقال لها والله لئن لم تمكنيني منه لأقتلنك فعلمت أنه سيفعل ذلك فبعثت إليه وواعدته ليلا وقعد له ابن الدمينة وصاحب\nله فجاءها للموعد فجعل يكلمها وهي مكانها فلم تكلمه فقال لها يا حماء ما هذا الجفاء الليلة قال فتقول له هي بصوت ضعيف ادخل فدخل فأهوى بيده ليضعها عليها فوضعها على ابن الدمينة فوثب عليه هو وصاحبه وقد جعل له حصى في ثوب فضرب بها كبده حتى قتله وأخرجه فطرحه ميتا فجاء أهله فاحتملوه ولم يجدوا به أثر السلاح فعلموا أن ابن الدمينة قتله قال الزبير في حديثه وقد قال ابن الدمينة في تحقيق ذلك\n(قالوا هجتك سلول اللؤم مخفية ... فاليوم أهجو سلولا لا أخافيها)\n(قالوا هجاك سلولي فقلت لهم ... قد أنصف الصخرة الصماء راميها)\n(رجالهم شر من يمشي ونسوتهم ... شر البرية واست ذل حاميها)\n(يحككن بالصخر أستاها بها نقب ... كما يحك نقاب الجرب طاليها)\nقال وقال أيضا يذكر دخول مزاحم ووضعه يده عليه\n(لك الخير إن واعدت حماء فالقها ... نهارا ولا تدلج إذا الليل أظلما)\n(فإنك لا تدري أبيضاء طفلة ... تعانق أم ليثا من القوم قشعما)\n(فلما سرى عن ساعدي ولحيتي ... وأيقن أني لست حماء جمجما)","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":0,"spl":"أخبار ابن الدمينة ونسبه — مزاحم بن عمرو يرمى بامرأته ويشهر به","tags":["الهجاء","الجواري والنساء"],"loc":3004},
{"id":"b218-3","bab":"الجزء 17","sec":"ابن الدمينة يقتل امرأته","page":"ج17 ص101","text":"قالوا جميعا ثم أتى ابن الدمينة امرأته فطرح على وجهها قطيفة ثم جلس عليها حتى قتلها فلما ماتت قال\n(إذا قعدت على عرنين جارية ... فوق القطيفة فادعوا لي بحفار)\nفبكت بنية له منها فضرب بها الأرض فقتلها وقال متمثلا لا تتخذن من كلب سوء جروا قال الزبير في خبره عن عمه مصعب عن حميد بن أنيف قال فخرج جناح أخو المقتول إلى أحمد بن إسماعيل فاستعداه على ابن الدمينة فبعث إليه فحبسه وقالوا جميعا قالت أم أبان والدة مزاحم بن عمرو المقتول وهي من خثعم ترثي ابنها وتحضض مصعبا وجناحا أخويه\n(بأهلي ومالي بل بجل عشيرتي ... قتيل بني تيم بغير سلاح)\n(فهلا قتلتم بالسلاح ابن أختكم ... فتظهر فيه للشهود جراح)\n(فلا تطمعوا في الصلح ما دمت حية ... وما دام حيا مصعب وجناح)\n(ألم تعلموا أن الدوائر بيننا ... تدور وأن الطالبين شحاح)\nقالوا فلما طال حبسه ولم يجد عليه أحمد بن إسماعيل سبيلا ولا حجة خلاه وقتلت بنو سلول رجلا من خثعم مكان المقتول وقتلت خثعم بعد ذلك نفرا من سلول ولهم في ذلك قصص وأشعار كثيرة","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":1,"spl":"ابن الدمينة يقتل امرأته — رواية مقتله","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3005},
{"id":"b218-4","bab":"الجزء 17","sec":"رواية مقتله","page":"ج17 ص102","text":"قالوا وأقبل ابن الدمينة حاجا بعد مدة طويلة فنزل بتبالة فعدا عليه مصعب أخو المقتول لما رآه وقد كانت أمه حرضته عليه وقالت اقتل ابن الدمينة فإنه قتل أخاك وهجا قومك وذم أختك وقد كنت أعذرك قبل هذا\nلأنك كنت صغيرا وقد كبرت الآن فلما أكثرت عليه خرج من عندها وبصر بابن الدمينة واقفا ينشد الناس فغدا إلى جزار فأخذ شفرته وعدا على ابن الدمينة فجرحه جراحتين فقيل إنه مات لوقته\nوقيل بل سلم تلك الدفعة ومر به مصعب بعد ذلك وهو في سوق العبلاء ينشد فعلاه بسيفه حتى قتله وعدا وتبعه الناس حتى اقتحم دارا وأغلقها على نفسه فجاءه رجل من قومه فصاح به يا مصعب إن لم تضع يدك في يد السلطان قتلتك العامة فاخرج فلما عرفه\nقال له أنا في ذمتك حتى تسلمني إلى السلطان قال نعم فخرج إليه ووضع يده في يده فسلمه إلى السلطان فقذفه في سجن تبالة قال السكري في خبره ومكث ابن الدمينة جريحا ليلته ومات في غد فقال في تلك الليلة يحرض قومه ويوبخهم\n(هتفت بأكلب ودعوت قيسا ... فلا خذلا دعوت ولا قليلا)\n(ثأرت مزاحما وسررت قيسا ... وكنت لما هممت به فعولا)\n(فلا تشلل يداك ولا تزالا ... تفيدان الغنائم والجزيلا)\n(فلو كان ابن عبد الله حيا ... لصبح في منازلها سلولا)\nال وبلغ مصعبا أن قوم ابن الدمينة يريدون أن يقتحموا عليه سجن تبالة فيقتلوه به غيلة فقال يحرض قومه\n(لقيت أبا السري وقد تكالا ... له حق العداوة في فؤادي)\n(فكاد الغيظ يفرطني إليه ... بطعن دونه طعن السداد)\n(إذا نبحت كلاب السجن حولي ... طمعت هشاشة وهفا فؤادي)\n(طماعة أن يدق السجن قومي ... وخوفا أن يبيتني الأعادي)\n(فما ظني بقومي شر ظن ... ولا أن يسلموني في البلاد)\n(وقد جدلت قاتلهم فأمسى ... يمج دم الوتين على الوساد)\nجاءت بنو عقيل إليه ليلا فكسروا السجن وأخرجوه منه","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":1,"spl":"ابن الدمينة يقتل امرأته — رواية مقتله","tags":["الهجاء","اللهو والمزاح"],"loc":3006},
{"id":"b218-5","bab":"الجزء 17","sec":"مصعب السلولي يهرب إلى صنعاء","page":"ج17 ص104","text":"قال مصعب فلما أفلت من السجن هرب إلى صنعاء فقدم علينا وأبى بها يومئذ وال فنزل على كاتب لأبي كان مولى لهم فرأيته حينئذ ولم يكن جلدا من الرجال ومما يغنى به من شعر ابن الدمينة قوله من قصيدة أولها\n(أقمت على زمان يوما وليلة ... لأنظر ما واشي أميمة صانع)\n(فقصرك مني كل عام قصيدة ... تخب بها خوص المطي النزائع)\nهذه القصيدة ذكر أحمد بن يحيى ثعلب أن عبد الله بن شبيب أنشده إياها عن محمد بن عبد الله الكراني لابن الدمينة والذي يغني به منها قوله\n\n(أقضي نهاري بالحديث وبالمنى ... ويجمعني والهم بالليل جامع)\n(نهاري نهار الناس حتى إذا بدا ... لي الليل شاقتني إليك المضاجع)\n(لقد ثبتت في القلب منك محبة ... كما ثبتت في الراحتين الأصابع)\nغناه إبراهيم رملا بالوسطى عن عمرو بن بانة نسخت من كتاب أبي سعيد قال حدثنا ابن أبي السري عن هشام قال هوي ابن الدمينة امرأة من قومه يقال لها أميمة فهام بها مدة فلما وصلته تجنى عليها وجعل ينقطع عنها ثم زارها ذات يوم فتعاتبا طويلا ثم أقبلت عليه فقالت\n(وأنت الذي أخلفتني ما وعدتني ... وأشمت بي من كان فيك يلوم)\n(وأبرزتني للناس ثم تركتني ... لهم غرضا أرمى وأنت سليم)\n(فلولا أن قولا يكلم الجسم قد بدا ... بجسمي من قول الوشاة كلوم)\nلشعر لأميمة امرأة ابن الدمينة والغناء لإبراهيم الموصلي خفيف رمل بالوسطى عن عمرو والهشامي وذكر حبش أن لإبراهيم أيضا فيه لحنا من الثقيل الأول بالوسطى وذكر حكم الوادي أن هذا اللحن ليعقوب الوادي وفيه لعريب\nخفيف ثقيل قال فأجابها ابن الدمينة فقال\n(وأنت التي قطعت قلبي حزازة ... ومزقت قرح القلب فهو كليم)\n(وأنت التي كلفتني دلج السرى ... وجون القطا بالجلهتين جثوم)\n(وأنت التي أحفظت قومي فكلهم ... بعيد الرضا داني الصدود كظيم)\nال ثم تزوجها بعد ذلك وقتل وهي عنده","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":2,"spl":"مصعب السلولي يهرب إلى صنعاء","tags":[],"song":2,"loc":3007},
{"id":"b218-6","bab":"الجزء 17","sec":"قصة عاشقين","page":"ج17 ص106","text":"فأخبرني الحسين بن يحيى قال قال حماد بن إسحاق حدثني أبي قال حدثنا سعيد بن سلم عن أبي الحسن الينبعي قال بينا أنا وصديق لي من قريش نمشي بالبلاط ليلا إذا بظل نسوة في القمر فالتفتنا فإذا بجماعة نسوة فسمعت واحدة منهن وهي تقول أهو هو فقالت الأخرى نعم والله إنه لهو هو فدنت مني ثم قالت يا كهل قل لهذا الذي معك\n(ليست لياليك في خاخ بعائدة ... كما عهدت ولا أيام ذي سلم)\nفقلت له أجب فقد سمعت فقال قد والله قطع بي وأرتج علي فأجب عني فالتفت إليها ثم قلت\n(فقلت لها يا عز كل مصيبة ... إذا وطنت يوما لها النفس ذلت)\nقالت المرأة أوه ثم مضت ومضينا حتى إذا كنا بمفرق طريقين مضى الفتى إلى منزله ومضيت أنا إلى منزلي فإذا أنا بجويرية تجذب ردائي فالتفت إليها فقالت المرأة التي كلمتك تدعوك فمضيت معها حتى دخلت دارا ثم صرت إلى بيت فيه حصير وثنيت لي وسادة فجلست عليها ثم جاءت جارية بوسادة مثنية فطرحتها وجاءت المرأة فجلست عليها وقالت أنت المجيب\nقلت نعم قالت ما كان أفظ جوابك وأغلظه قلت والله ما حضرني غيره فبكت ثم قالت لي والله ما خلق الله خلقا أحب إلي من إنسان كان معك قلت أنا الضامن لك عنه ما تحبين قالت أو تفعل\nقلت نعم فوعدتها أن آتيها به في الليلة القابلة وانصرفت فإذا الفتى ببابي فقلت ما جاء بك قال علمت أنها سترسل إليك وسألت عنك فلم أجدك فعلمت أنك عندها فجلست أنتظرك فقلت فقد كان كل ما ظننت ووعدتها أن آتيها بك في الليلة القابلة فمضى ثم أصبحنا فتهيأنا ورحنا فإذا الجارية تنتظرنا فمضت أمامنا حتى دخلنا الدار فإذا برائحة الطيب وجاءت فجلست مليا ثم أقبلت عليه فعاتبته طويلا ثم قالت\n(وأنت الذي أخلفتني ما وعدتني ... وأشمت بي من كان فيك يلوم)\n(وأبرزتني للناس ثم تركتني ... لهم غرضا أرمى وأنت سليم)\n(فلو أن قولا يكلم الجسم قد بدا ... بجسمي من قول الوشاة كلوم)\nثم سكتت فسكت الفتى هنيهة ثم قال\n(غدرت ولم أغدر وخنت ولم أخن ... وفي دون هذا للمحب عزاء)\n(جزيتك ضعف الود ثم صرمتني ... فحبك في قلبي إليك أداء)\nالتفتت إلي وقالت ألا تسمع ما يقول قد أخبرتك قال فغمزته فكف ثم قالت\n(تجاهلت وصلي حين لجت عمايتي ... وهلا صرمت الحبل إذ أنا مبصرا)\n(ولي من قوى الحبل الذي قد قطعته ... نصيب وإذ رأيي جميع موفر)\n(ولكنما آذنت بالصرم بغتة ... ولست على مثل الذي جئت أقدر)\nنى في هذه الأبيات إبراهيم الموصلي ثقيل أول بالوسطى عن عمرو وذكر حبش أن فيها ثاني ثقيل بالبنصر قال فقال الفتى مجيبا لها\n(لقد جعلت نفسي - وأنت اجترمته ... وكنت أحب الناس - عنك تطيب)\nبكت ثم قالت أو قد طابت نفسك لا والله ما فيك خير بعدها فعليك السلام ثم قامت والتفتت إلي وقالت قد علمت أنك لا تفي بضمانك عنه وانصرفنا أخبرني يحيى بن علي بن يحيى قال حدثنا حماد بن إسحاق قال حدثني أبي قال كان العباس بن الأحنف إذا سمع شيئا يستحسنه أطرفني به وأفعل مثل ذلك فجاءني يوما فوقف بين البابين وأنشد لابن الدمينة\n\n(ألا يا صبا نجد متى هجت من نجد ... فقد زادني مسراك وجدا على وجد)\n(أإن هتفت ورقاء في رونق الضحى ... على فنن غض النبات من الرند)\n(بكيت كما يبكي الحزين صبابة ... وذبت من الشوق المبرح والصد)\n(بكيت كما يبكي الوليد ولم تكن ... جزوعا وأبديت الذي لم تكن تبدي)\n(وقد زعموا أن المحب إذا دنا ... يمل وأن النأي يشفي من الوجد)\n(بكل تداوينا فلم يشف ما بنا ... على أن قرب الدار خير من البعد)\nزيد على ذلك بيت وهو\n(ولكن قرب الدار ليس بنافع ... إذا كان من تهواه ليس بذي ود)\nم ترنح ساعة وترجح أخرى ثم قال أنطح العمود برأسي من حسن هذا فقلت لا ارفق بنفسك الغناء في هذه الأبيات لإبراهيم له فيه لحنان أحدهما ما خوري بالبنصر أوله البيت الثاني والآخر خفيف ثقيل بالوسطى أوله البيت الأول أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الله بن إبراهيم الجمحي قال حدثني أحمد بن سعيد عن ابن زبنج راوية ابن هرمة قال لقي ابن هرمة بعض أصدقائه بالبلاط فقال له من أين أقبلت قال من","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":3,"spl":"قصة عاشقين","tags":["الحب والغزل"],"song":3,"loc":3008},
{"id":"b218-7","bab":"الجزء 17","sec":"قصة عاشقين","page":"ج17 ص106","text":"المسجد قال فأي شيء صنعت هناك قال كنت جالسا مع إبراهيم بن الوليد المخزومي قال فأي شيء قال لك قال أمرني أن أطلق امرأتي قال فأي شيء قلت له قال ما قلت له شيئا قال فوالله ما قال لك ذلك إلا لأمر أظهرته عليه وكتمتنيه أفرأيت إن أمرته بطلاق امرأته أيطلقها قال لا والله قال فابن الدمينة كان أنصف منك كان يهوى امرأة من قومه فأرسلت إليه إن أهلي قد نهوني عن لقائك ومراسلتك فأرسل إليها\n(أطعت الآمريك بقطع حبلي ... مريهم في أحبتهم بذاك)\n(فإن هم طاوعوك فطاوعيهم ... وإن عاصوك فاعصي من عصاك)\n(أما والراقصات بكل فج ... ومن صلى بنعمان الأراك)\n(لقد أضمرت حبك في فؤادي ... وما أضمرت حبا من سواك)\nي هذه الأبيات لإسحاق رمل وفيها لشارية خفيف رمل بالوسطى ولعريب خفيف ثقيل ابتداؤه ينشد في الثالث والرابع ثم الثاني والأول وفيه لمتيم خفيف رمل آخر\nوحدثني بعض أصدقائنا عن أبي بكر بن دريد - ولم أسمعه منه - قال حدثنا عبد الرحمن بن أخي الأصمعي عن عمه ووجدته أيضا في بعض الكتب بغير هذا الإسناد عن الأصمعي فجمعت الحكايتين\nقال مررت بالكوفة وإذا أنا بجارية تطلع من جدار إلى الطريق وفتى واقف وظهره إلي وهو يقول لها أسهر فيك وتنامين عني وتضحكين مني وأبكي وتستريحين وأتعب وأمحضك المودة وتمذقينها لي وأصدقك وتنافقيني ويأمرك عدوي بهجري فتطيعينه ويأمرني نصيحي بذلك فأعصيه ثم تنفس وأجهش باكيا فقالت له إن أهلي يمنعونني منك وينهونني عنك فكيف أصنع فقال لها\n(أطعت الآمريك بصرم حبلي ... مريهم في أحبتهم بذاك)\n(فإن هم طاوعوك فطاوعيهم ... وإن عاصوك فاعصي من عصاك)\nم التفت فرآني فقال يا فتى ما تقول أنت فيما قلت فقلت له والله لو عاش ابن أبي ليلى ما حكم إلا بمثل حكمك تمت أخبار ابن الدمينة\n(وإن الذي بيني وبين بني أبي ... وبين بني عمي لمختلف جدا)\n(فما أحمل الحقد القديم عليهم ... وليس رئيس القوم من يحمل الحقدا)\n(وليسوا إلى نصري سراعا وإن هم ... دعوني إلى نصر أتيتهم شدا)\n(إذا أكلوا لحمي وفرت لحومهم ... وإن هدموا مجدي بنيت لهم مجدا)\n(يعاتبني في الدين قومي وإنما ... تدينت في أشياء تكسبهم حمدا)\nعروضه من الطويل الشعر للمقنع الكندي والغناء لابن سريج رمل بالوسطى عن عمرو وفيه من روايته أيضا لمالك خفيف رمل بالوسطى وذكر علي بن يحيى أن لحن ابن سريج خفيف ثقيل وذكر إبراهيم أن فيه لقفا النجار لحنا لم يذكر طريقته وأظنه من خفيف الثقيل","topic":"أخبار ابن الدمينة ونسبه","topicNo":218,"sp":4,"spl":"قصة عاشقين","tags":["الجواري والنساء"],"song":2,"loc":3009},
{"id":"b219-2","bab":"الجزء 17","sec":"نسب المقنع الكندي وأخباره — المقنع متخرق في عطاياه سمح اليد","page":"ج17 ص113 – ج17 ص114","text":"المقنع لقب غلب عليه لأنه كان أجمل الناس وجها وكان إذا سفر اللثام عن وجهه أصابته العين قال الهيثم كان المقنع أحسن الناس وجها وأمدهم قامة وأكملهم خلقا فكان إذا سفر لقع - أي أصابته أعين الناس - فيمرض ويلحقه عنت فكان لا يمشي إلا مقنعا واسمه محمد بن ظفر بن عمير بن أبي شمر بن فرعان بن قيس بن الأسود ابن عبد الله بن الحارث الولادة - سمي بذلك لكثرة ولده - بن عمرو بن معاوية ابن كندة بن عفير بن عدي بن الحارث بن مرة بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب قحطان شاعر مقل من شعراء الدولة الأموية وكان له محل كبير وشرف ومروءة وسؤدد في عشيرته قال الهيثم بن عدي أن عمير جده سيد كندة وكان عمه عمرو بن أبي شمر ينازع أباه الرياسة ويساجله فيها فيقصر عنه\nونشأ محمد بن عمير المقنع فكان متخرقا في عطاياه سمح اليد بماله لا يرد سائلا عن شيء حتى أتلف كل ما خلفه أبوه من مال فاستعلاه بنو عمه عمرو بن أبي شمر بأموالهم وجاههم وهوي بنت عمه عمرو فخطبها إلى إخوتها فردوه وعيروه بتخرقه وفقره وما عليه من الدين فقال هذه الأبيات المذكورة\nوأخبرني محمد بن يحيى الصولي قال حدثني محمد بن زكريا الغلابي عن العتبي قال حدثني أبو خالد من ولد أمية بن خلف قال قال عبد الملك بن مروان - وكان أول خليفة ظهر منه بخل - أي الشعراء أفضل فقال له كثير بن هراسة يعرض ببخل عبد الملك أفضلهم المقنع الكندي حيث يقول\n(إني أحرض أهل البخل كلهم ... لو كان ينفع أهل البخل تحريضي)\n(ما قل مالي إلا زادني كرما ... حتى يكون برزق الله تعويضي)\n(والمال يرفع من لولا دراهمه ... أمسى يقلب فينا طرف مخفوض)\n(لن تخرج البيض عفوا من أكفهم ... إلا على وجع منهم وتمريض)\n(كأنها من جلود الباخلين بها ... عند النوائب تحذى بالمقاريض)\nقال عبد الملك - وعرف ما أراد - الله أصدق من المقنع حيث يقول ( والذين إذا أنفقوا لم يسرفوا ولم يقتروا\n\n(يا بن هشام يا علي الندى ... فدتك نفسي ووقتك الردى)\n(نسيت عهدي أو تناسيتني ... لما عداني عنك صرف النوى)\nلشعر والغناء لإسحاق الموصلي رمل بالبنصر","topic":"نسب المقنع الكندي وأخباره","topicNo":219,"sp":0,"spl":"نسب المقنع الكندي وأخباره — المقنع متخرق في عطاياه سمح اليد","tags":[],"song":1,"loc":3010},
{"id":"b219-3","bab":"الجزء 17","sec":"خبر لإسحاق وابن هشام","page":"ج17 ص116","text":"وهذا الشعر يقوله في علي بن هشام أيام كان إسحاق بالبصرة وله إليه رسالة حسنة هذا موضع ذكرها أخبرنا بها علي بن يحيى المنجم عن أبيه ووقعت إلينا من عدة وجوه أن إسحاق كتب إلى علي بن هشام جعلت فداك بعث إلي أبو نصر مولاك بكتاب منك إلي يرتفع عن قدري ويقصر عنه شكري فلولا ما أعرف من معانيه لظننت أن الرسول غلط بي فيه فما لنا ولك يا عبد الله تدعنا حتى إذا أنسينا الدنيا وأبغضناها ورجونا السلامة من شرها أفسدت قلوبنا وعلقت أنفسنا فلا أنت تريدنا ولا أنت تتركنا فبأي شيء تستحل هذا فأما ما ذكرته من شوقك إلي فلولا أنك حلفت عليه لقلت\n(يا من شكا عبثا إلينا شوقه ... شكوى المحب وليس بالمشتاق)\n(لو كنت مشتاقا إلي تريدني ... ما طبت نفسا ساعة بفراقي)\n(وحفظتني حفظ الخليل خليله ... ووفيت لي بالعهد والميثاق)\n(هيهات قد حدثت أمور بعدنا ... وشغلت باللذات عن إسحاق)\nقد تركت - جعلت فداك - ما كرهت من العتاب في الشعر وغيره وقلت أبياتا لا أزال أخرج بها إلى ظهر المربد وأستقبل الشمال وأتنسم أرواحكم\nفيها ثم يكون ما الله أعلم به وإن كنت تكرهها تركتها إن شاء الله\n(ألا قد أرى أن الثواء قليل ... وأن ليس يبقى للخليل خليل)\n(وإني وإن مكنت في العيش حقبة ... كذي سفر قد حان منه رحيل)\n(فهل لي إلى أن تنظر العين مرة ... الى ابن هشام في الحياة سبيل !)\n(فقد خفت أن ألقى المنايا بحسرة ... وفي النفس منه حاجة وغليل)\nوأما بعد فإني أعلم أنك - وإن لم تسل عن حالي - تحب أن تعلمها وأن تأتيك عني سلامة فأنا يوم كتبت إليك سالم البدن مريض القلب وبعد فأنا - جعلت فداك - في صنعة كتاب مليح ظريف فيه تسمية القوم ونسبهم وبلادهم وأسبابهم وأزمنتهم وما اختلفوا فيه من غنائهم وبعض أحاديثهم وأحاديث قيان الحجاز والكوفة والبصرة المعروفات والمذكورات وما\nقيل فيهن من الأشعار ولمن كن وإلى من صرن ومن كان يغشاهن ومن كان يرخص في السماع من الفقهاء والأشراف فأعلمني رأيك فيما تشتهي لأعمل على قدر ذلك إن شاء الله وقد بعثت إليك بأنموذج فإن كان كما\nقال القائل قبح الله كل دن أوله دردي لم نتجشم إتمامه وربحنا العناء فيه وإن كان كما قال العربي إن الجواد عينه فراره أعلمتنا فأتممناه مسرورين بحسن رأيك فيه إن شاء الله وهذا مما يدل على أن كتاب الأغاني المنسوب إلى إسحاق ليس له وإنما ألف ما رواه حماد ابنه عنه من دواوين القدماء غير مختلط بعضها ببعض\nوكان إسحاق يألف عليا وأحمد ابني هشام وسائر أهلهما إلفا شديدا ثم وقعت بينهم نبوة ووحشة في أمر لم يقع إلينا إلا لمعا غير مشروحة فهجاهم هجاء كثيرا وانفرجت الحال بينه وبينهم","topic":"نسب المقنع الكندي وأخباره","topicNo":219,"sp":1,"spl":"خبر لإسحاق وابن هشام","tags":["الهجاء","السفر والحج"],"loc":3011},
{"id":"b219-4","bab":"الجزء 17","sec":"نماذج من شعره","page":"ج17 ص118","text":"فأخبرني محمد بن خلف وكيع ويحيى بن علي بن يحيى وغيرهما عن أبي أيوب سليمان المديني عن مصعب قال قال لي أحمد بن هشام أما تستحي أنت وصباح بن خاقان وأنتما شيخان من مشايخ المروءة والعلم والأدب أن شبب بذكركما إسحاق في الشعر وهو مغن مذكور فيقول\n(قد نهانا مصعب وصباح ... فعصينا مصعبا وصباحا)\n(عذلا ما عذلا أم ملاما ... فاسترحنا منهما فاستراحا)\nيروى\n(علما في العذل أم قد ألاما ... )\nيروى\n(عذلا عذلهما ثم أناما ... )\nقلت إن كان فعل فما قال إلا خيرا إنما ذكر أنا نهيناه عن خمر شربها وامرأة عشقها وقد أشاد باسمك في الشعر بأشد من هذا قال وما هو قلت قوله\n(وصافية تغشى العيون رقيقة ... رهينة عام في الدنان وعام)\n(أدرنا بها الكأس الروية موهنا ... من الليل حتى انجاب كل ظلام)\n(فما ذر قرن الشمس حتى كأننا ... من العي نحكي أحمد بن هشام)\nال أو قد فعل العاض بظر أمه قلت إي والله لقد فعل إلى هاهنا رواية مصعب ووجدت هذا الخبر في غير روايته وفيه زيادة قد ذكرتها قال فآلى أحمد بن هشام أن يبلغ فيه كل مبلغ يقدر عليه وأن يجتهد في اغتياله\nقال إسحاق حضرت بدار الخليفة وحضر علي بن هشام فقال لي أتهجو أخي وتذكره بما بلغني من القبيح فقلت أو يتعرض أخوك لي ويتوعدني فوالله ما أبالي بما يكون منه لأني أعلم أنه لا يقدر لي على ضر والنفع فلا أريده منه وأنا شاعر مغن والله لأهجونه بما أفري به جلده وأهتك مروءته ثم لأغنين في أقبح ما أقوله فيه غناء تسري به الركبان فقال لي أو تهب لي عرضه وأصلح بينكما فقلت ذاك إليك وإن فعلته فلك لا له ففعل ذلك وفعلته به\nأخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد النحوي قال كان صباح بن خاقان المنقري نديما لمصعب الزبيري فقال عبد الرحمن ابن أبي عبد الرحمن بن عائشة - وكان خليعا من أهل البصرة -\n(من يكن إبطه كآباط ذا الخلق ... فإبطاي في عداد الفقاح)\n(لي إبطان يرميان جليسي ... بشبيه السلاح بل بالسلاح)\n(فكأني من نتن هذا وهذا ... جالس بين مصعب وصباح)\nأخبرني علي بن يحيى المنجم قال حدثني أبي قال حدثني إسحاق قال دخلت على الفضل بن الربيع يوما فقال ما عندك قلت بيتان أرجو أن يكونا فيما يستطرف وأنشدته\n(سنغضي عن المكروه من كل ظالم ... ونصبر حتى يصنع الله بالفضل)\n(فتنتصر الأحرار ممن يضيمها ... وتدرك أقصى ما تطالب من ذحل)\nال فدمعت عينه وقال من آذاك لعنه الله فقلت بنو هاشم وأخبرته الخبر قال يحيى بن علي ولم يذكر بأي شيء أخبره\n(قد حصت البيضة رأسي فما ... أطعم نوما غير تهجاع)\n(أسعى على جل بني مالك ... كل امرىء في شأنه ساع)\n(من يذق الحرب يجد طعمها ... مرا وتتركه بجعجاع)\n(لا نألم القتل ونجزي به الأعداء ... كيل الصاع بالصاع)\nالشعر لأبي قيس بن الأسلت والغناء لإبراهيم خفيف ثقيل أول وقيل بل هو لمعبد","topic":"نسب المقنع الكندي وأخباره","topicNo":219,"sp":2,"spl":"نماذج من شعره","tags":[],"song":1,"loc":3012,"partial":1},
{"id":"b220-1","bab":"الجزء 17","sec":"نسب أبي قيس بن الأسلت وأخباره","page":"ج17 ص121","text":"أبو قيس لم يقع إلي اسمه غير ابن الأسلت والأسلت لقب أبيه واسمه عامر بن جشم بن وائل بن زيد بن قيس بن عمارة بن مرة بن مالك بن الأوس بن حارثة بن ثعلبة بن عمرو بن عامر وهو شاعر من شعراء الجاهلية وكانت الأوس قد أسندت إليه حربها وجعلته رئيسا عليها فكفى وساد وأسلم ابنه عقبة بن أبي قيس واستشهد يوم القادسية وكان يزيد بن مرداس السلمي أخو عباس بن مرداس الشاعر قتل قيس بن أبي قيس بن الأسلت في بعض حروبهم فطلبه بثأره هارون بن النعمان بن الأسلت حتى تمكن من يزيد بن مرداس فقتله بقيس بن أبي قيس وهو ابن عمه ولقيس يقول أبوه أبو قيس بن الأسلت\n(أقيس إن هلكت وأنت حي ... فلا تعدم مواصلة الفقير)\nهذا الشعر الذي فيه الغناء يقوله أبو قيس في حرب بعاث","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":0,"spl":"نسب أبي قيس بن الأسلت وأخباره — ابن الأسلت قائد الأوس في حربها — يوم بعاث","tags":["أبي قيس بن الأسلت"],"loc":3013},
{"id":"b220-3","bab":"الجزء 17","sec":"ابن الأسلت قائد الأوس في حربها — يوم بعاث","page":"ج17 ص121 – ج17 ص121","text":"قال هشام بن الكلبي كانت الأوس قد أسندوا أمرهم في\nإلى أبي قيس بن الأسلت الوائلي فقام في حربهم وآثرها على كل أمر حتى شحب وتغير ولبث أشهرا لا يقرب امرأة ثم إنه جاء ليلة فدق على امرأته وهي كبشة بنت ضمرة بن مالك بن عدي بن عمرو بن عوف ففتحت له فأهوى إليها بيده فدفعته وأنكرته فقال أنا أبو قيس فقالت والله ما عرفتك حتى تكلمت فقال في ذلك أبو قيس هذه القصيدة وأولها\n(قالت ولم تقصد لقيل الخنا ... مهلا فقد أبلغت أسماعي)\n(استنكرت لونا له شاحبا ... والحرب غول ذات أوجاع)\n(من يذق الحرب يجد طعمها ... مرا وتتركه بجعجاع)\nوم بعاث","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":0,"spl":"نسب أبي قيس بن الأسلت وأخباره — ابن الأسلت قائد الأوس في حربها — يوم بعاث","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3014},
{"id":"b220-4","bab":"الجزء 17","sec":"سبب يوم بعاث","page":"ج17 ص122","text":"فأما السبب في هذا اليوم وهو يوم بعاث فيما أخبرني به محمد بن\nجرير الطبري قال حدثنا محمد بن حميد الرازي قال حدثنا سلمة بن الفضل عن محمد بن إسحاق وأضفت إليه ما ذكره ابن الكلبي عن أبيه عن أبي صالح عن أبي عبيدة عن محمد بن عمار بن ياسر\nوعن عبد الرحمن بن سليمان بن عبد الله بن حنظلة الغسيل ابن أبي عامر الراهب أن الأوس كانت استعانت ببني قريظة والنضير في حروبهم التي كانت بينهم وبين الخزرج وبلغ ذلك الخزرج فبعثت إليهم إن الأوس فيما بلغنا قد استعانت بكم علينا ولن يعجزنا أن نستعين بأعدادكم وأكثر منكم من العرب فإن ظفرنا بكم فذاك ما تكرهون وإن ظفرتم لم ننم عن الطلب أبدا فتصيروا إلى ما تكرهون ويشغلكم من شأننا ما أنتم الآن منه خالون وأسلم لكم من ذلك أن تدعونا وتخلوا بيننا وبين إخواننا فلما سمعوا ذلك علموا أنه الحق فأرسلوا إلى الخزرج إنه قد كان الذي بلغكم والتمست الأوس نصرنا وما كنا لننصرهم عليكم أبدا فقالت لهم الخزرج فإن كان ذلك كذلك فابعثوا إلينا برهائن تكون في أيدينا فبعثوا إليهم أربعين غلاما منهم ففرقهم الخزرج في دورهم فمكثوا بذلك مدة ثم إن عمرو بن النعمان البياضي\nقال لقومه بياضة إن عامرا أنزلكم منزل سوء بين سبخة ومفازة وإنه والله لا يمس رأسي غسل حتى أنزلكم منازل بني قريظة والنضير على عذب الماء وكريم النخل ثم راسهلم إما أن تخلوا بيننا وبين دياركم نسكنها وإما أن نقتل رهنكم فهموا أن يخرجوا من ديارهم فقال لهم كعب بن أسد القرظي يا قوم امنعوا دياركم وخلوه يقتل الرهن والله ما هي إلا ليلة يصيب فيها أحدكم امرأته حتى يولد له غلام مثل أحد الرهن\nفاجتمع رأيهم على ذلك فأرسلوا إلى عمرو بألا نسلم لكم دورنا وانظروا الذي عاهدتمونا عليه في رهننا فقوموا لنا به فعدا عمرو بن النعمان على رهنهم هو ومن أطاعه من الخزرج فقتلوهم وأبى عبد الله بن أبي وكان سيدا حليما\nوقال هذا عقوق ومأثم وبغي فلست معينا عليه ولا أحد من قومي أطاعني وكان عنده في الرهن سليم بن أسد القرظي - وهو جد محمد بن كعب القرظي - فخلى عنه وأطلق ناس من الخزرج نفرا فلحقوا بأهليهم فناوشت الأوس الخزرج يوم قتل الرهن شيئا من قتال غير كبير واجتمعت قريظة والنضير إلى كعب بن أسد أخي بني عمرو بن قريظة ثم توامروا أن يعينوا الأوس على الخزرج فبعث إلى الأوس بذلك ثم أجمعوا عليه على أن ينزل كل أهل بيت من النبيت على بيت من قريظة والنضير فنزلوا معهم في دورهم وأرسلوا إلى النبيت يأمرونهم بإتيانهم وتعاهدوا ألا يسلموهم أبدا وأن يقاتلوا معهم حتى لا يبقى منهم أحد فجاءتهم النبيت فنزلوا مع قريظة والنضير في بيوتهم ثم أرسلوا إلى سائر الأوس في الحرب والقيام معهم على الخزرج فأجابوهم إلى ذلك فاجتمع الملأ منهم واستحكم أمرهم وجدوا في حربهم ودخلت معهم قبائل من أهل المدينة منهم بنو ثعلبة - وهم من غسان - وبنو زعوراء وهم من غسان فلما سمعت بذلك الخزرج اجتمعوا ثم خرجوا وفيهم عمرو بن النعمان البياضي وعمرو بن الجموح السلمي حتى جاؤوا عبد الله بن أبي وقالوا له قد كان الذي بلغك من أمر الأوس وأمر قريظة والنضير واجتماعهم على حربنا وإنا نرى أن نقاتلهم فإن هزمناهم لم يحرز أحد منهم معقله ولا ملجأه حتى لا يبقى منهم أحد فلما فرغوا من مقالتهم قام عبد الله بن أبي خطيبا وقال إن هذا بغي منكم","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":1,"spl":"سبب يوم بعاث","tags":["أبي قيس بن الأسلت","السفر والحج"],"loc":3015},
{"id":"b220-5","bab":"الجزء 17","sec":"سبب يوم بعاث","page":"ج17 ص122","text":"على قومكم وعقوق ووالله ما أحب أن رجلا من جراد لقيناهم وقد بلغني أنهم يقولون هؤلاء قومنا منعونا الحياة أفيمنعوننا الموت والله إني أرى قوما لا ينتهون أو يهلكوا عامتكم وإني لأخاف إن قاتلوكم أن ينصروا عليكم لبغيكم عليهم فقاتلوا قومكم كما كنتم تقاتلونهم فإذا ولوا فخلوا عنهم فإذا هزموكم فدخلتم أدنى البيوت خلوا عنكم فقال له عمرو بن النعمان انتفخ والله سحرك يا أبا الحارث حين بلغك حلف الأوس قريظة والنضير فقال عبد الله والله لا حضرتكم أبدا ولا أحد أطاعني أبدا ولكأني أنظر إليك قتيلا تحملك أربعة في عباءة وتابع عبد الله بن أبي رجال من الخزرج منهم عمرو بن الجموح الحرامي واجتمع كلام الخزرج على أن رأسوا عليهم عمرو بن النعمان البياضي وولوه أمر حربهم ولبثت الأوس والخزرج أربعين ليلة يتصنعون للحرب ويجمع بعضهم لبعض ويرسلون إلى حلفائهم من قبائل العرب فأرسلت الخزرج إلى جهينة وأشجع فكان الذي ذهب إلى أشجع ثابت بن قيس بن شماس فأجابوه وأقبلوا إليهم وأقبلت جهينة إليهم أيضا وأرسلت الأوس إلى مزينة وذهب حضير الكتائب الأشهلي إلى أبي قيس بن الأسلت فأمره أن يجمع له أوس الله فجمعهم له أبو قيس فقام حضير فاعتمد على قوسه وعليه نمرة تشف عن عورته فحرضهم وأمرهم بالجد في حربهم\nوذكر ما صنعت بهم الخزرج من إخراج النبيت وإذلال من تخلف من سائر الأوس في كلام كثير فجعل كلما ذكر ما صنعت بهم الخزرج وما ركبوه منهم يستشيط ويحمى وتقلص خصيتاه حتى تغيبا فإذا كلموه بما يحب تدلتا حتى ترجعا إلى حالهما\nفأجابته أوس الله بالذي يحب من النصرة والموازرة والجد في الحرب قال هشام فحدثني عبد المجيد بن أبي عيسى عن خير عن أشياخ من قومه أن الأوس اجتمعت يومئذ إلى حضير بموضع يقال له الجباة فأجالوا الرأي فقالت الأوس إن ظفرنا بالخزرج لم نبق منهم أحدا ولم نقاتلهم كما كنا نقاتلهم فقال حضير يا معشر الأوس ما سميتم الأوس إلا لأنكم تؤوسون الأمور الواسعة ثم قال\n(يا قوم قد أصبحتم دوارا ... لمعشر قد قتلوا الخيارا)\n(يوشك أن يستأصلوا الديارا ... )\nال ولما اجتمعوا بالجباة طرحوا بين أيديهم تمرا وجعلوا يأكلون وحضير الكتائب جالس وعليه بردة له قد اشتمل بها الصماء وما يأكل معهم ولا يدنو إلى التمر غضبا وحنقا فقال يا قوم اعقدوا لأبي قيس بن الأسلت فقال لهم أبو قيس لا أقبل ذلك فإني لم أرأس على قوم في حرب قط إلا هزموا وتشاءموا برياستي وجعلوا ينظرون إلى حضير واعتزاله أكلهم واشتغاله بما هم فيه من أمر الحرب وقد بدت خصيتاه من تحت البرد فإذا رأى منهم ما يكره من الفتور والتخاذل تقلصتا غيظا وغضبا وإذا رأى منهم ما يحب من الجد والتشمير في الحرب عادتا لحالهما\nوأجابت إلى ذلك أوس مناة وجدوا في الموازرة والمظاهرة وقدمت مزينة على الأوس فانطلق حضير وأبو عامر الراهب بن صيفي إلى أبي قيس بن الأسلت فقالا قد جاءتنا مزينة واجتمع إلينا من أهل يثرب ما لا قبل للخزرج به فما الرأي إن نحن ظهرنا عليهم الإنجاز أم البقية فقال أبو قيس بل البقية فقال أبو عامر والله لوددت أن مكانهم ثعلبا ضباحا فقال أبو قيس اقتلوهم حتى يقولوا بزا بزا - كلمة كانوا يقولونها إذا غلبوا - فتشاجروا في ذلك وأقسم حضير ألا يشرب الخمر أو يظهر ويهدم مزاحما أطم عبد الله بن أبي فلبثوا شهرين يعدون ويستعدون ثم التقوا ببعاث وتخلف عن الأوس بنو حارثة بن الحارث فبعثوا إلى الخزرج إنا والله ما نريد قتالكم فبعثوا إليهم أن ابعثوا إلينا برهن منكم يكونون في أيدينا فبعثوا إليهم اثني عشر رجلا منهم خديج أبو رافع بن خديج وبعاث من أموال بني قريظة فيها مزرعة يقال لها قورى فلذلك تدعى بعاث الحرب","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":2,"spl":"سبب يوم بعاث","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3016,"partial":1},
{"id":"b220-6","bab":"الجزء 17","sec":"حشد القوات","page":"ج17 ص127","text":"وحشد الحيان فلم يتخلف عنهم إلا من لا ذكر له ولم يكونوا حشدوا قبل ذلك في يوم التقوا فيه فلما رأت الأوس الخزرج أعظموهم وقالوا لحضير يا أبا أسيد لو حاجزت القوم وبعثت إلى من تخلف من حلفائك من مزينة فطرح قوسا كانت في يده ثم قال أنتظر مزينة وقد نظر إلي القوم ونظرت إليهم الموت قبل ذلك ثم حمل وحملوا فاقتتلوا قتالا شديدا فانهزمت الأوس حين\nوجدوا مس السلاح فولوا مصعدين في حرة قورى نحو العريض وذلك وجه طريق نجد فنزل حضير وصاحت بهم الخزرج أين الفرار ألا إن نجدا سنة - أي مجدب - يعيرونهم فلما سمع حضير طعن بسنان رمحه فخذه ونزل وصاح واعقراه والله لا أريم حتى أقتل فإن شئتم يا معشر الأوس أن تسلموني فافعلوا فتعطفت عليه الأوس وقام على رأسه غلامان من بني عبد الأشهل يقال لهما محمود ولبيد - ابنا خليفة بن ثعلبة - وهما يومئذ معرسان ذوا بطش فجعلا يرتجزان ويقولان\n(أي غلامي ملك ترانا ... في الحرب إذ دارت بنا رحانا)\n(وعدد الناس لنا مكانا ... )\nقتل عمرو بن النعمان وانهزام الخزرج فقاتلا حتى قتلا وأقبل سهم حتى أصاب عمرو بن النعمان رأس الخزرج فقتله لا يدرى من رمى به إلا أن بني قريظة تزعم أنه سهم رجل يقال له أبو لبابة فقتله\nفبينا عبد الله بن أبي يتردد على بغلة له قريبا من بعاث يتحسس أخبار القوم إذ طلع عليه بعمرو بن النعمان ميتا في عباءة يحمله أربعة إلى داره فلما رآه عبد الله بن أبي\nقال من هذا قالوا عمرو بن النعمان قال ذق وبال العقوق وانهزمت الخزرج ووضعت الأوس فيهم السلاح وصاح صائح يا معشر الأوس أسجحوا ولا تهلكوا إخوتكم فجوارهم خير من جوار الثعالب فتناهت الأوس وكفت عن سلبهم بعد إثخان فيهم وسلبتهم قريظة والنضير وحملت الأوس حضيرا من الجراح التي به وهم يرتجزون حوله ويقولون\n(كتيبة زينها مولاها ... لا كهلها هد ولا فتاها)\nجعلت الأوس تحرق على الخزرج نخلها ودورها فخرج سعد بن معاذ الأشهلي حتى وقف على باب بني سلمة وأجارهم وأموالهم جزاء لهم بيوم الرعل وكان للخزرج على الأوس يوم يقال له يوم مغلس ومضرس وكان سعد بن معاذ حمل يومئذ جريحا إلى عمرو بن الجموح الحرامي فمن عليه\nوأجاره وأخاه يوم رعل وهو على الأوس من القطع والحرق فكافأه سعد بمثل ذلك في يوم بعاث وأقسم كعب بن أسد القرظي ليذلن عبد الله بن أبي وليحلقن رأسه تحت مزاحم فناداه كعب انزل يا عدو الله فقال له عبد الله أنشدك الله وما خذلت عنكم فسأل عما\nقال فوجده حقا فرجع عنه وأجمعت الأوس على أن تهدم مزاحما أطم عبد الله بن أبي وحلف حضير ليهدمنه فكلم فيه فأمرهم أن يريثوا فيه فحفروا فيه كوة وأفلت يومئذ الزبير بن إياس بن باطا ثابت بن قيس بن شماس أخا بني الحارث بن الخزرج وهي النعمة التي كافأه بها ثابت في الإسلام يوم بني قريظة وخرج حضير الكتائب وأبو عامر الراهب حتى أتيا أبا قيس بن الأسلت بعد الهزيمة فقال له حضير يا أبا قيس إن رأيت أن تأتي الخزرج قصرا قصرا ودارا دارا نقتل ونهدم حتى لا يبقى منهم أحد فقال أبو قيس والله لا نفعل ذلك فغضب حضير\nوقال ما سميتم الأوس إلا لأنكم تووسون الأمر أوسا ولو ظفرت منا الخزرج بمثلها ما أقالوناها ثم انصرف إلى الأوس فأمرهم بالرجوع إلى ديارهم","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":3,"spl":"حشد القوات","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3017,"partial":1},
{"id":"b220-7","bab":"الجزء 17","sec":"موت حضير الكتائب الأشهلي","page":"ج17 ص130","text":"وكان حضير جرح يومئذ جراحة شديدة فذهب به كليب بن صيفي بن عبد الأشهل إلى منزله في بني أمية بن زيد فلبث عنده أياما ثم مات من الجراحة التي كانت به فقبره اليوم في بني أمية بن زيد قال وكان يهودي أعمى من بني قريظة يومئذ في أطم من آطامهم فقال لابنة له أشرفي على الأطم فانظري ما فعل القوم فأشرفت فقالت أسمع\nالصوت قد ارتفع في أعلى قورى وأسمع قائلا يقول اضربوا يا آل الخزرج فقال الدولة إذا على الأوس لا خير في البقاء ثم قال ماذا تسمعين قالت أسمع رجالا يقولون يا آل الأوس ورجالا يقولون يا آل الخزرج قال الآن حمي القتال ثم لبث ساعة ثم قال أشرفي فاسمعي فأشرفت فقالت أسمع قوما يقولون\n(نحن بنو صخرة أصحاب الرعل ... )\nال تلك بنو عبد الأشهل ظفرت والله الأوس - وصخرة أمهم بنت مرة بن ظفر أم بني عبد الأشهل - ثم وثب فرحا نحو باب الأطم فضرب رأسه بحلق بابه وكان من حجارة فسقط فمات وكان أبو عامر قد حلف ليركزن رمحه في أصل مزاحم أطم عبد الله بن أبي فخرجت جماعة من الأوس حتى أحاطوا به وكانت تحت أبي عامر جميلة بنت عبد الله بن أبي وهي أم حنظلة الغسيل بن أبي عامر فأشرف عليهم عبد الله فقال إني والله ما رضيت هذا الأمر ولا كان عن رأيي وقد عرفتم كراهتي له فانصرفوا عني فقال أبو عامر لا والله لا أنصرف حتى أركز لوائي في أصل أطمك فلما رأى حنظلة أنه لا ينصرف\nقال لهم إن أبي شديد الوجد بي فأشرفوا بي عليه ثم قولوا والله لئن لم تنصرف عنا لنرمين برأسه إليك فقالوا ذلك له فركز رمحه في أصل الأطم ليمينه ثم انصرف فذلك قول قيس بن الخطيم\n(صبحنا به الآطام حول مزاحم ... قوانس أولى بيضنا كالكواكب)\nأسر أبو قيس بن الأسلت يومئذ مخلد بن الصامت الساعدي أبا مسلمة بن مخلد اجتمع إليه ناس من قومه من مزينة ومن يهود فقالوا اقتله فأبى وخلى سبيله وأنشأ يقول\n(أسرت مخلدا فعفوت عنه ... وعند الله صالح ما أتيت)\n(مزينة عنده ويهود قورى ... وقومي كل ذلكم كفيت)\nثاء حضير\nوقال خفاف بن ندبة يرثي حضير الكتائب وكان نديمه وصديقه\n(لو ان المنايا حدن عن ذي مهابة ... لهبن حضيرا يوم أغلق واقما)\n(أطاف به حتى إذا الليل جنه ... تبوأ منه منزلا متناعما)\nوقال أيضا يرثيه\n(أتاني حديث فكذبته ... وقيل خليلك في المرمس)\n(فيا عين بكي حضير الندى ... حضير الكتائب والمجلس)\n(ويوم شديد أوار الحديد ... تقطع منه عرى الأنفس)\n(صليت به وعليك الحديد ... ما بين سلع إلى الأعرس)\n(فأودى بنفسك يوم الوغى ... ونقى ثيابك لم تدنس)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني داود بن محمد بن جميل عن ابن الأعرابي قال قال لي الهيثم بن عدي كنا جلوسا عند صالح بن حسان فقال لنا وأخبرني عمي عن الكراني عن النوشجاني عن العمري عن الهيثم بن عدي قال قال لنا صالح بن حسان وأخبرني به الأخفش عن المبرد قال قال لي صالح بن حسان أنشدوني بيتا خفرا في امرأة خفرة شريفة فقلنا قول حاتم\n(يضيء لها البيت الظليل خصاصه ... إذا هي يوما حاولت أن تبسما)\nقال هذه من الأصنام أريد أحسن من هذا قلنا قول الأعشى\n(كأن مشيتها من بيت جارتها ... مر السحابة لا ريث ولا عجل)\nقال هذه خراجة ولاجة كثيرة الاختلاف قلنا بيت ذي الرمة\n(تنوء بأخراها فلأيا قيامها ... وتمشي الهوينا من قريب فتبهر)\nقال هذا ليس ما أردت إنما وصف هذه بالسمن وثقل البدن فقلنا ما عندنا شيء فقال قول أبي قيس بن الأسلت\n(ويكرمها جاراتها فيزرنها ... وتعتل عن إتيانهن فتعذر)\n(وليس لها أن تستهين بجارة ... ولكنها منهن تحيا وتخفر)\nثم قال أنشدوني أحسن بيت وصفت به الثريا قلنا بيت ابن الزبير الأسدي\n(وقد لاح في القور الثريا كأنما ... به راية بيضاء تخفق للطعن)\nال أريد أحسن من هذا قلنا بيت امرىء القيس\n(إذا ما الثريا في السماء تعرضت ... تعرض أثناء الوشاح المفصل)\nال أريد أحسن من هذا قلنا بيت ابن الظثرية\n(إذا ما الثريا في السماء كأنها ... جمان وهى من سلكه فتسرعا)\nقال أريد أحسن من هذا قلنا ما عندنا شيء قال قول أبي قيس بن الأسلت\n(وقد لاح في الصبح الثريا لمن رأى ... كعنقود ملاحية حين نورا)\nال فحكم له عليهم في هذين المعنيين بالتقدم","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":4,"spl":"موت حضير الكتائب الأشهلي","tags":["أبي قيس بن الأسلت","المديح"],"loc":3018,"partial":1},
{"id":"b220-8","bab":"الجزء 17","sec":"استشهاد عبد الملك بشعر ابن الأسلت","page":"ج17 ص134","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الحسين بن أحمد بن طالب الديناري قال حدثني أبو عدنان قال حدثني الهيثم بن عدي قال حدثني الضحاك بن زميل السكسكي قال\nلما قتل عبد الملك بن مروان مصعب بن الزبير خطب الناس بالنخيلة فقال في خطبته أيها الناس دعوا الأهواء المضلة والآراء المتشتتة ولا تكلفونا أعمال المهاجرين وأنتم لا تعملون بها فقد جاريتمونا إلى السيف فرأيتم كيف صنع الله بكم ولا أعرفنكم بعد الموعظة تزدادون جراءة فإني لا أزداد بعدها إلا عقوبة وما مثلي ومثلكم إلا كما قال أبو قيس بن الأسلت\n(من يصل ناري بلا ذنب ولا ترة ... يصل بنار كريم غير غدار)\n(أنا النذير لكم مني مجاهرة ... كي لا ألام على نهي وإعذار)\n(فإن عصيتم مقالي اليوم فاعترفوا ... أن سوف تلقون خزيا ظاهر العار)\n(لتتركن أحاديثا ملعنة ... عند المقيم وعند المدلج الساري)\n(وصاحب الوتر ليس الدهر مدركه ... عندي وإني لطلاب لأوتار)\n(أقيم عوجته إن كان ذا عوج ... كما يقوم قدح النبعة الباري)\n\n(ترفع أيها القمر المنير ... لعلك أن ترى حجرا يسير)\n(يسير إلى معاوية بن حرب ... ليقتله كما زعم الأمير)\n(ألا يا حجر حجر بني عدي ... تلقتك السلامة والسرور)\n(تنعمت الجبابر بعد حجر ... وطاب لها الخورنق والسدير)\nلشعر لامرأة من كندة ترثي حجر بن عدي صاحب أمير المؤمنين علي بن أبي طالب صلوات الله عليه والغناء لحكم الوادي رمل بالوسطى وفيه لحنين هزج خفيف بالوسطى عن ابن المكي والهشامي","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":5,"spl":"استشهاد عبد الملك بشعر ابن الأسلت — خبر مقتل حجر بن عدي","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3019},
{"id":"b220-9","bab":"الجزء 17","sec":"خبر مقتل حجر بن عدي","page":"ج17 ص136","text":"حدثني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم قال حدثنا أبو مخنف قال حدثنا خالد بن قطن عن المجالد بن سعيد الهمداني والصقعب بن زهير وفضيل بن خديج والحسن بن عقبة المرادي وقد اختصرت جملا من ذلك يسيرة تحرزا من الإطالة","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":5,"spl":"استشهاد عبد الملك بشعر ابن الأسلت — خبر مقتل حجر بن عدي","tags":["أبي قيس بن الأسلت","الرواية والكتابة"],"loc":3020},
{"id":"b220-11","bab":"الجزء 17","sec":"استنكاره ذم علي ولعنه — زياد يحذره وينذره","page":"ج17 ص137 – ج17 ص138","text":"أن المغيرة بن شعبة لما ولي الكوفة كان يقوم على المنبر فيذم علي بن أبي طالب وشيعته وينال منهم ويلعن قتلة عثمان ويستغفر لعثمان ويزكيه فيقوم حجر بن عدي فيقول يأيها الذين آمنوا كونوا قوامين بالقسط شهداء لله ولو\nعلى أنفسكم\nوإني أشهد أن من تذمون أحق بالفضل ممن تطرون ومن تزكون أحق بالذم ممن تعيبون فيقول له المغيرة يا حجر ويحك أكفف من هذا واتق غضبة السلطان وسطوته فإنها كثيرا ما تقتل مثلك ثم يكف عنه فلم يزل كذلك حتى كان المغيرة يوما في آخر أيامه يخطب على المنبر فنال من علي بن أبي طالب عليه السلام ولعنه ولعن شيعته فوثب حجر فنعر نعرة أسمعت كل من كان في المسجد وخارجه فقال له إنك لا تدري أيها الإنسان بمن تولع أو هرمت مر لنا بأعطياتنا وأرزاقنا فإنك قد حبستها عنا ولم يكن ذلك لك ولا لمن كان قبلك وقد أصبحت مولعا بذم أمير المؤمنين وتقريظ المجرمين فقام معه أكثر من ثلاثين رجلا يقولون صدق والله حجر مر لنا بأعطياتنا فإنا لا ننتفع بقولك هذا ولا يجدي علينا وأكثروا في ذلك فنزل المغيرة ودخل القصر فاستأذن عليه قومه ودخلوا ولاموه في احتماله حجرا فقال لهم إني قد قتلته قالوا وكيف ذلك\nقال إنه سيأتي أمير بعدي فيحسبه مثلي فيصنع به شبيها بما ترونه فيأخذه عند أول وهلة فيقتله شر قتلة إنه قد اقترب أجلي وضعف عملي وما أحب أن أبتدىء أهل هذا المصر بقتل خيارهم وسفك دمائهم فيسعدوا بذلك وأشقى ويعز معاوية في الدنيا ويذل المغيرة في الآخرة سيذكرونني لو قد جربوا العمال قال الحسن بن عقبة فسمعت شيخا من الحي يقول قد والله جربناهم فوجدناه خيرهم\nقال ثم هلك المغيرة سنة خمسين فجمعت الكوفة والبصرة لزياد\nفدخلها ووجه إلى حجر فجاءه وكان له قبل ذلك صديقا فقال له قد بلغني ما كنت تفعله بالمغيرة فيحتمله منك وإني والله لا أحتملك على مثل ذلك أبدا أرأيت ما كنت تعرفني به من حب علي ووده فإن الله قد سلخه من صدري فصيره بغضا وعداوة وما كنت تعرفني به من بغض معاوية وعداوته فإن الله قد سلخه من صدري وحوله حبا ومودة وإني أخوك الذي تعهد إذا أتيتني وأنا جالس للناس فاجلس معي على مجلسي وإذا أتيت ولم أجلس للناس فاجلس حتى أخرج إليك ولك عندي في كل يوم حاجتان حاجة غدوة وحاجة عشية إنك إن تستقم تسلم لك دنياك ودينك وإن تأخذ يمينا وشمالا تهلك نفسك وتشط عندي دمك إني لا أحب التنكيل قبل التقدمة ولا آخذ بغير حجة اللهم اشهد فقال حجر لن يرى الأمير مني إلا ما يحب وقد نصح وأنا قابل نصيحته ثم خرج من عنده فكان يتقيه ويهابه وكان زياد يدنيه ويكرمه ويفضله والشيعة تختلف إلى حجر وتسمع منه وكان زياد يشتو بالبصرة ويصيف بالكوفة ويستخلف على البصرة سمرة بن جندب وعلى الكوفة عمرو بن حريث فقال له عمارة بن عقبة\nإن الشيعة تختلف إلى حجر وتسمع منه ولا أراه عند خروجك إلا ثائرا فدعاه زياد فحذره ووعظه وخرج إلى البصرة واستعمل عمرو بن حريث فجعلت الشيعة تختلف إلى حجر ويجيء حتى يجلس في المسجد فتجتمع إليه الشيعة حتى يأخذوا ثلث المسجد أو نصفه وتطيف بهم النظارة ثم يمتلىء المسجد ثم كثروا وكثر لغطهم وارتفعت أصواتهم بذم معاوية وشتمه ونقص زياد وبلغ ذلك عمرو بن حريث فصعد المنبر واجتمع إليه أشراف أهل المصر فحثهم على الطاعة والجماعة وحذرهم الخلاف فوثب إليه عنق من أصحاب حجر يكبرون ويشتمون حتى دنوا منه فحصبوه وشتموه حتى نزل ودخل القصر وأغلق عليه بابه وكتب إلى زياد بالخبر فلما أتاه أنشد يتمثل بقول كعب بن مالك\n(فلما غدوا بالعرض قال سراتنا ... علام إذا لم نمنع العرض نزرع)\nا أنا بشيء إن لم أمنع الكوفة من حجر وأدعه نكالا لمن بعده ويل أمك حجر لقد سقط بك العشاء على سرحان","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":6,"spl":"استنكاره ذم علي ولعنه — زياد يحذره وينذره","tags":["أبي قيس بن الأسلت"],"loc":3021},
{"id":"b220-12","bab":"الجزء 17","sec":"زياد يعود إلى الكوفة ويأمر بإحضاره","page":"ج17 ص140","text":"ثم أقبل حتى أتى الكوفة فدخل القصر ثم خرج وعليه قباء سندس ومطرف خز أخضر وحجر جالس في المسجد وحوله أصحابه ما كانوا فصعد المنبر فخطب وحذر الناس ثم قال لشداد بن الهيثم الهلالي أمير الشرط اذهب\nفائتني بحجر فذهب إليه فدعاه فقال أصحابه لا يأتيه ولا كرامة فسبوا الشرط فرجعوا إلى زياد فأخبروه فقال يا أشراف أهل الكوفة أتشجون بيد وتأسون بأخرى أبدانكم عندي وأهواؤكم مع هذا الهجاجة المذبوب أنتم معي وإخوتكم وأبناؤكم وعشيرتكم مع حجر فوثبوا إلى زياد فقالوا معاذ الله أن يكون لنا فيما ها هنا رأي إلا طاعتك وطاعة أمير المؤمنين وكل ما ظننت أن يكون فيه رضاك فمرنا به\nقال ليقم كل امرىء منكم إلى هذه الجماعة التي حول حجر فليدع الرجل أخاه وابنه وذا قرابته ومن يطيعه من عشيرته حتى تقيموا عنه كل من استطعتم ففعلوا وجعلوا يقيمون عنه أصحابه حتى تفرق أكثرهم وبقي أقلهم فلما رأى زياد خفة أصحابه\nقال لصاحب شرطته اذهب فائتني بحجر فإن تبعك وإلا فمر من معك أن ينتزعوا عمد السيوف ثم يشدوا عليه حتى يأتوا به ويضربوا من حال دونه فلما أتاه شداد\nقال له أجب الأمير فقال أصحاب حجر لا والله ولا نعمة عين لا يجيبه فقال لأصحابه علي بعمد السيوف فاشتدوا إليها فأقبلوا بها فقال عمير بن زيد الكلبي أبو العمرطة إنه ليس معك رجل معه سيف غيري فما يغني سيفي\nقال فما ترى قال قم من هذا المكان فالحق بأهلك يمنعك قومك فقام وزياد ينظر على المنبر إليهم فغشوا حجرا بالعمد فضرب رجل من الحمراء يقال له بكر بن عبيد رأس عمرو بن الحمق بعمود فوقع وأتاه أبو\nسفيان بن العويمر والعجلان بن ربيعة - وهما رجلان من الأزد - فحملاه فأتيا به دار رجل من الأزد يقال له عبيد الله بن موعد فلم يزل بها متواريا حتى خرج منها\nقال أبو مخنف فحدثني يوسف بن زياد عن عبيد الله بن عوف قال لما انصرفنا عن عروة باجميرى قبل قتل عبد الملك مصعبا بعام فإذا أنا بالأحمري الذي ضرب عمرو بن الحمق يسايرني ولا والله ما رأيته منذ ذلك اليوم وما كنت أرى لو رأيته أن أعرفه فلما رأيته ظننته هو هو وذلك حين نظرنا إلى أبيات الكوفة فكرهت أن أسأله أنت ضارب عمرو بن الحمق فيكابرني فقلت له ما رأيتك منذ اليوم الذي ضربت فيه رأس عمرو بن الحمق بالعمود في المسجد فصرعته حتى يومي ولقد عرفتك الآن حين رأيتك فقال لي لا تعدم بصرك ما أثبت نظرك كان ذلك أمر السلطان أما والله لقد بلغني أنه قد كان امرأ صالحا ولقد ندمت على تلك الضربة فأستغفر الله فقلت له الآن ترى لا والله لا أفترق أنا وأنت حتى أضربك في رأسك مثل الضربة التي ضربتها عمرو بن الحمق وأموت أو تموت\nقال فناشدني وسألني بالله فأبيت عليه ودعوت غلاما يدعى رشيدا من سبي أصبهان معه قناة له صلبة فأخذتها منه ثم أحمل عليه فنزل عن دابته فألحقه حين استوت قدماه على الأرض فأصفق بها هامته فخر لوجهه وتركته ومضيت فبرأ بعد ذلك فلقيته مرتين من دهري كل ذلك يقول لي الله بيني وبينك فأقول له الله بينك وبين عمرو بن الحمق","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":7,"spl":"زياد يعود إلى الكوفة ويأمر بإحضاره — رجع الحديث إلى سياقه الأول","tags":["أبي قيس بن الأسلت","الحب والغزل"],"loc":3022},
{"id":"b220-13","bab":"الجزء 17","sec":"رجع الحديث إلى سياقه الأول","page":"ج17 ص143","text":"قال فقال زياد - وهو على المنبر - لتقم همدان وتميم وهوازن وأبناء بغيض ومذحج وأسد وغطفان فليأتوا جبانة كندة وليمضوا من ثم إلى حجر فليأتوني به ثم كره أن تسير مضر مع اليمن فيقع شغب واختلاف أو تنشب الحمية فيما بينهم فقال لتقم تميم وهوازن وأبناء بغيض وأسد وغطفان ولتمض مذحج وهمدان إلى جبانة كندة ثم ليمضوا إلى حجر فليأتوني به وليسير أهل اليمن حتى ينزلوا جبانة الصيداويين وليمضوا إلى صاحبهم فليأتوني به فخرجت الأزد وبجيلة وخثعم والأنصار وقضاعة وخزاعة فنزلوا جبانة الصيداويين ولم تخرج حضرموت مع اليمن لمكانهم من كندة\nقال أبو مخنف فحدثني سعيد بن يحيى بن مخنف عن محمد بن مخنف قال فإني لمع أهل اليمن وهم يتشاورون في أمر حجر فقال لهم عبد الرحمن بن مخنف أنا مشير عليكم برأي فإن قبلتموه رجوت أن تسلموا من اللائمة والإثم أن تلبثوا قليلا حتى تكفيكم عجلة في شباب مذحج وهمدان ما تكرهون أن يكون من مساءة قومكم في صاحبكم فأجمع رأيهم على ذلك فلا والله ما كان إلا كلا ولا حتى أتينا فقيل لنا\nإن شباب مذحج وهمدان قد دخلوا فأخذوا كل ما وجدوا في بني بجيلة","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":7,"spl":"زياد يعود إلى الكوفة ويأمر بإحضاره — رجع الحديث إلى سياقه الأول","tags":["أبي قيس بن الأسلت"],"loc":3023},
{"id":"b220-14","bab":"الجزء 17","sec":"حجر الهارب لا يحب الهلاك لأصحابه","page":"ج17 ص144","text":"قال فمر أهل اليمن على نواحي دور كندة معذرين فبلغ ذلك زيادا فأثنى على مذحج وهمدان وذم أهل اليمن فلما انتهى حجر إلى داره ورأى قلة من معه\nقال لأصحابه انصرفوا فوالله ما لكم طاقة بمن اجتمع عليكم من قومكم وما أحب أن أعرضكم للهلاك فذهبوا لينصرفوا فلحقتهم أوائل خيل مذحج وهمدان فعطف عليهم عمير بن يزيد وقيس بن يزيد وعبيدة بن عمرو وجماعة فتقاتلوا معهم فقاتلوا عنه ساعة فجرحوا وأسر قيس بن يزيد وأفلت سائر القوم فقال لهم حجر لا أبا لكم تفرقوا لا تقتلوا فإني آخذ في بعض هذه الطرق ثم أخذ نحو طريق بني حرب من كندة حتى أتى دار رجل منهم يقال له سليمان بن يزيد فدخل داره وجاء القوم في طلبه ثم انتهوا إلى تلك الدار فأخذ سليمان بن يزيد سيفه ثم ذهب ليخرج إليهم فبكت بناته فقال له حجر ما تريد لا أبا لك فقال له أريد والله أن ينصرفوا عنك فإن فعلوا وإلا ضاربتهم بسيفي هذا ما ثبت قائمه في يدي دونك فقال له حجر بئس والله إذن ما دخلت به على بناتك أما في دارك هذه حائط أقتحمه أو خوخة أخرج منها\nعسى الله أن يسلمني منهم ويسلمك فإن القوم إن لم يقدروا علي في دارك لم يضرك أمرهم قال بلى هذه خوخة تخرجك إلى دور بني العنبر من كندة فخرج معه فتية من الحي يقصون له الطريق ويسلكون به الأزقة حتى أفضى إلى النخع فقال عند ذلك انصرفوا رحمكم الله فانصرفوا عنه وأقبل إلى دار عبد الله بن الحارث أخي الأشتر فدخلها فإنه لكذلك قد ألقى له عبد الله الفرش وبسط له البسط وتلقاه ببسط الوجه وحسن البشر إذ أتي فقيل له إن الشرط تسأل عنك في النخع وذلك أن أمة سوداء يقال لها أدماء لقيتهم فقالت لهم من تطلبون قالوا نطلب حجرا فقالت هو ذا قد رأيته في النخع فانصرفوا نحو النخع فخرج متنكرا وركب معه عبد الله ليلا حتى أتى دار ربيعة بن ناجذ الأزدي فنزل بها فمكث يوما وليلة فلما أعجزهم أن يقدروا عليه دعا زياد محمد بن الأشعث فقال أما والله لتأتيني بحجر أو لا أدع لك نخلة إلا قطعتها ولا دارا إلا هدمتها ثم لا تسلم مني بذلك حتى أقطعك إربا إربا فقال له أمهلني أطلبه\nقال قد أمهلتك ثلاثا فإن جئت به وإلا فاعدد نفسك من الهلكى وأخرج محمد نحو السجن وهو منتقع اللون يتل تلا عنيفا فقال حجر بن يزيد الكندي من بني مرة لزياد ضمنيه وخل سبيله ليطلب صاحبه فإنه مخلى سربه أحرى أن يقدر عليه منه إذا كان محبوسا قال أتضمنه لي قال نعم قال أما والله لئن حاص عنك لأوردنك شعوب وإن كنت الآن علي كريما قال إنه لا يفعل فخلى سبيله\nثم إن حجر بن يزيد كلمه في قيس بن يزيد وقد أتي به أسيرا فقال ما عليه من بأس قد عرفنا رأيه في عثمان رضي الله عنه وبلاءه مع أمير المؤمنين بصفين ثم أرسل إليه فأتي به فقال قد علمت أنك لم تقاتل مع حجر أنك ترى رأيه ولكن قاتلت معه حمية وقد غفرنا لك لما نعلمه من حسن رأيك ولكن لا أدعك حتى تأتيني بأخيك عمير\nقال آتيك به إن شاء الله قال هات من يضمنه معك قال هذا حجر بن يزيد قال حجر نعم على أن تؤمنه على ماله ودمه قال ذلك لك فانطلقا فأتيا به فأمر به فأوقر حديدا ثم أخذته الرجال ترفعه حتى إذا بلغ سررها ألقوه فوقع على الأرض ثم رفعوه فألقوه ففعل به ذلك مرارا فقام إليه حجر بن يزيد فقال أولم تؤمنه\nقال بلى لست أهريق له دما ولا آخذ له مالا فقال هذا يشفي به على الموت وقام كل من كان عنده من أهل اليمن فكلموه فيه فقال أتضمنونه لي بنفسه متى أحدث حدثا أتيتموني به قالوا نعم فخلى سبيله ومكث حجر في منزل ربيعة بن ناجذ يوما وليلة ثم بعث إلى ابن الأشعث غلاما رشيدا من سبي أصبهان فقال له إنه قد بلغني ما استقبلك به هذا الجبار العنيد فلا يهولنك شيء من أمره فإني خارج إليك فاجمع نفرا من قومك وادخل عليه واسأله أن يؤمنني حتى يبعثني إلى معاوية فيرى في رأيه","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":8,"spl":"حجر الهارب لا يحب الهلاك لأصحابه","tags":["أبي قيس بن الأسلت","المديح"],"loc":3024},
{"id":"b220-15","bab":"الجزء 17","sec":"زياد يأمر بحبسه ويطلب رؤوس أصحابه","page":"ج17 ص146","text":"فخرج محمد إلى حجر بن يزيد وجرير بن عبد الله وعبد الله أخي الأشتر فدخلوا إلى زياد فطلبوا إليه فيما سأله حجر فأجاب فبعثوا إليه رسولا\nيعلمونه بذلك فأقبل حتى دخل على زياد فقال له مرحبا يا أبا عبد الرحمن حرب في أيام الحرب وحرب وقد سالم الناس على نفسها تجني براقش فقال له ما خلعت يدا عن طاعة ولا فارقت جماعة وإني لعلى بيعتي فقال هيهات يا حجر أتشج بيد وتأسو بأخرى وتريد إذا أمكننا الله منك أن نرضى هيهات والله فقال ألم تؤمنني حتى آتي معاوية فيرى في رأيه\nقال بلى انطلقوا به إلى السجن فلما مضي به قال أما والله لولا أمانة ما برح حتى يلقط عصبه فأخرج وعليه برنس في غداة باردة فحبس عشر ليال وزياد ماله عمل غير الطلب لرؤوس أصحاب حجر فخرج عمرو بن الحمق ورفاعة بن شداد حتى نزلا المدائن ثم ارتحلا حتى أتيا الموصل فأتيا جبلا فكمنا فيه وبلغ عامل ذلك الرستاق - وهو رجل من همدان يقال له عبيد الله بن بلتعة - خبرهما فسار إليهما في الخيل ومعه أهل البلد فلما انتهى إليهما خرجا فأما عمرو فكان بطنه قد استسقى فلم يكن عنده امتناع وأما رفاعة فكان شابا قويا فوثب على فرس له جواد\nوقال لعمرو أقاتل عنك قال وما ينفعني أن تقتل انج بنفسك فحمل عليهم فأفرجوا له حتى أخرجه فرسه وخرجت الخيل في طلبه وكان راميا فلم يلحقه فارس إلا رماه فجرحه أو عقره فانصرفوا عنه فأخذ عمرو بن الحمق فسألوه من أنت فقال من إن تركتموه كان أسلم لكم وإن قتلتموه كان أضر عليكم\nفسألوه فأبى أن يخبرهم فبعثوا به إلى عبد الرحمن بن عثمان وهو ابن أم الحكم الثقفي فلما رأى عمرا عرفه فكتب إلى معاوية بخبره فكتب إليه معاوية إنه زعم أنه طعن عثمان تسع طعنات وإنه لا يتعدى عليه فاطعنه تسع طعنات كما طعن عثمان فأخرج فطعن تسع طعنات فمات في الأولى منهن أو في الثانية وبعث برأسه إلى معاوية فكان رأسه أول رأس حمل في الإسلام وجد زياد في طلب أصحاب حجر وهم يهربون منه ويأخذ من قدر عليه منهم فجاء قيس بن عباد الشيباني إلى زياد فقال له إن امرأ منا يقال له صيفي ابن فسيل من رؤوس أصحاب حجر وهو أشد الناس عليك فبعث إليه فأتي به فقال له زياد يا عدو الله ما تقول في أبي تراب فقال ما أعرف أبا تراب\nقال ما أعرفك به أما تعرف علي بن أبي طالب قال بلى قال فذاك أبو تراب قال كلا فذاك أبو الحسن والحسين فقال له صاحب الشرطة أيقول لك الأمير هو أبو تراب وتقول أنت لا\nقال أفإن كذب الأمير أردت أن أكذب وأشهد له بالباطل كما شهد قال له زياد وهذا أيضا مع ذنبك علي بالعصي فأتي بها فقال ما قولك في علي قال أحسن قول أنا قائله في عبد من عبيد الله أقوله في أمير المؤمنين\nقال اضربوا عاتقه بالعصي حتى يلصق بالأرض فضرب حتى لصق بالأرض ثم قال أقلعوا عنه ما قولك فيه قال والله لو شرحتني بالمدى والمواسي ما زلت عما سمعت قال لتلعننه أو لأضربن عنقك قال إذا والله تضربها قبل ذلك فأسعد وتشقى إن شاء الله قال أوقروه حديدا واطرحوه في السجن","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":9,"spl":"زياد يأمر بحبسه ويطلب رؤوس أصحابه","tags":["أبي قيس بن الأسلت"],"loc":3025},
{"id":"b220-16","bab":"الجزء 17","sec":"زياد يأمر رؤوس الأرباع أن يشهدوا على حجر","page":"ج17 ص148","text":"وجمع زياد من أصحاب حجر بن عدي اثني عشر رجلا في السجن\nوبعث إلى رؤوس الأرباع فأشخصهم فحضروا وقال اشهدوا على حجر بما رأيتموه وهم عمرو بن حريث وخالد بن عرفطة وقيس بن الوليد بن عبد شمس بن المغيرة وأبو بردة بن أبي موسى فشهدوا أن حجرا جمع إليه الجموع وأظهر شتم الخليفة وعيب زياد وأظهر عذر أبي تراب والترحم عليه والبراءة من عدوه وأهل حربه وأن هؤلاء الذين معه رؤوس أصحابه وعلى مثل رأيه فنظر زياد في الشهادة فقال ما أظن هذه شهادة قاطعة وأحب أن يكون الشهود أكثر من أربعة فكتب أبو بردة بن أبي موسى بسم الله الرحمن الرحيم هذا ما شهد عليه أبو بردة بن أبي موسى لله رب العالمين شهد أن حجر بن عدي خلع الطاعة وفارق الجماعة ولعن الخليفة ودعا إلى الحرب والفتنة وجمع إليه الجموع يدعوهم إلى نكث البيعة وخلع أمير المؤمنين معاوية وكفر بالله كفرة صلعاء فقال زياد على مثل هذه الشهادة فاشهدوا والله لأجهدن في قطع عنق الخائن الأحمق فشهد رؤوس الأرباع الثلاثة الآخرون على مثل ذلك ثم دعا الناس فقال اشهدوا على مثل ما شهد عليه رؤوس الأرباع فقام عثمان بن شرحبيل التيمي أول الناس فقال اكتبوا اسمي فقال زياد ابدأوا بقريش ثم اكتبوا اسم من نعرفه ويعرفه أمير المؤمنين بالصحة والاستقامة فشهد إسحاق وموسى وإسماعيل بنو طلحة بن عبيد الله\nوالمنذر بن الزبير وعمارة بن عقبة وعبد الرحمن بن هبار وعمر بن سعد ابن أبي وقاص وشهد عنان ووائل بن حجر الحضرمي وضرار بن هبيرة وشداد بن المنذر أخو الحضين بن المنذر وكان يدعى ابن بزيعة فكتب شداد بن بزيعة فقال أما لهذا أب ينسب إليه ألغوا هذا من الشهود فقيل له إنه أخو الحضين بن المنذر فقال انسبوه إلى أبيه فنسب فبلغ ذلك شدادا فقال والهفاه على ابن الزانية أوليست أمه أعرف من أبيه فوالله ما ينسب إلا إلى أمه سمية وشهد حجار بن أبجر العجلي وعمرو بن الحجاج ولبيد بن عطارد ومحمد بن عمير بن عطارد وأسماء بن خارجة وشمر بن ذي الجوشن وزحر ابن قيس الجعفي وشبث بن ربعي وسماك بن مخرمة الأسدي صاحب مسجد سماك ودعا المختار بن أبي عبيد وعروة بن المغيرة بن شعبة إلى الشهادة فراغا وشهد سبعون رجلا ودفع ذلك إلى وائل بن حجر وكثير بن شهاب\nوبعثهما عليهم وأمرهما أن يخرجوهم وكتب في الشهود شريح بن الحارث وشريح بن هانىء فأما شريح بن الحارث فقال سألني عنه فقلت أما إنه كان صواما قواما وأما شريح ابن هانىء فقال بلغني أن شهادتي كتبت فأكذبته ولمته وجاء وائل بن حجر وكثير بن شهاب فأخرجا القوم عشية وسار معهم أصحاب الشرط حتى أخرجوهم فلما انتهوا إلى جبانة عرزم نظر قبيصة بن ضبيعة العبسي إلى داره في جبانة عرزم فإذا بناته مشرفات فقال لوائل وكثير أدنياني أوص أهلي فأدنياه فلما دنا منهن بكين فسكت عنهن ساعة ثم\nقال اسكتن فسكتن فقال اتقين الله واصبرن فإني أرجو من ربي في وجهي هذا خيرا إحدى الحسنيين إما الشهادة فنعم سعادة وإما الانصراف إليكن في عافية فإن الذي كان يرزقكن ويكفيني مؤنتكن هو الله تبارك وتعالى وهو حي لا\nيموت وأرجو ألا يضيعكن وأن يحفظني فيكن ثم انصرف فجعل قومه يدعون له بالعافية وجاء شريح بن هانيء بكتاب فقال بلغوا هذا عني أمير المؤمنين فتحمله وائل بن حجر ومضوا بهم حتى انتهوا إلى مرج عذراء فحبسوا به وهم على أميال من دمشق وهم حجر بن عدي الكندي والأرقم بن عبد الله الكندي وشريك بن شداد الحضرمي وصيفي بن فسيل الشيباني وقبيصة بن ضبيعة العبسي وكريم بن عفيف الخثعمي وعاصم بن عوف البجلي وورقاء بن سمي البجلي وكدام بن حيان وعبد الرحمن بن حسان العنزيان ومحرز بن شهاب المنقري وعبد الله بن جؤية التميمي وأتبعهم زياد برجلين وهما عتبة بن الأخنس السعدي وسعيد بن نمران الهمداني الناعطي فكانوا أربعة عشر","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":10,"spl":"زياد يأمر رؤوس الأرباع أن يشهدوا على حجر","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3026},
{"id":"b220-17","bab":"الجزء 17","sec":"كتاب زياد إلى معاوية","page":"ج17 ص152","text":"فبعث معاوية إلى وائل بن حجر وكثير فأدخلهما وفض كتابهما وقرأه\nعلى أهل الشام بسم الله الرحمن الرحيم لعبد الله معاوية بن أبي سفيان أمير المؤمنين من زياد بن أبي سفيان أما بعد فإن الله قد أحسن عند أمير المؤمنين البلاء فأداله من عدوه وكفاه مؤونة من بغى عليه إن طواغيت الترابية السابة رأسهم حجر بن عدي خلعوا أمير المؤمنين وفارقوا جماعة المسلمين ونصبوا لنا حربا فأطفأها الله عليهم وأمكننا منهم وقد دعوت خيار أهل المصر وأشرافهم وذوي النهى والدين فشهدوا عليهم بما رأوا وعلموا وقد بعثت إلى أمير المؤمنين وكتبت شهادة صلحاء أهل المصر وخيارهم في أسفل كتابي هذا فلما قرأ الكتاب قال ما ترون في هؤلاء فقال يزيد بن أسد البجلي أرى أن تفرقهم في قرى الشام فتكفيكهم طواغيتها","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":11,"spl":"كتاب زياد إلى معاوية — كتاب شريح بن هانىء إلى معاوية","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3027},
{"id":"b220-18","bab":"الجزء 17","sec":"كتاب شريح بن هانىء إلى معاوية","page":"ج17 ص153","text":"ودفع وائل كتاب شريح إليه فقرأه وهو بسم الله الرحمن الرحيم لعبد الله معاوية أمير المؤمنين من شريح بن هانىء أما بعد فقد بلغني أن زيادا كتب إليك بشهادتي على حجر وإن شهادتي على حجر أنه ممن يقيم الصلاة ويؤتى الزكاة ويأمر بالمعروف وينهى عن المنكر حرام المال والدم فإن شئت فاقتله وإن شئت فدعه فقرأ كتابه على وائل\nوقال ما أرى هذا إلا قد أخرج نفسه من شهادتكم فحبس القوم بعد هذا وكتب إلى زياد فهمت ما اقتصصت من أمر حجر وأصحابه والشهادة عليهم فأحيانا أرى\nأن قتلهم أفضل وأحيانا أرى أن العفو أفضل من قتلهم فكتب زياد إليه مع يزيد بن حجية التيمي قد عجبت لاشتباه الأمر عليك فيهم مع شهادة أهل مصرهم عليهم وهم أعلم بهم فإن كانت لك حاجة في هذا المصر فلا تردن حجرا وأصحابه إليه فمر يزيد بحجر وأصحابه فأخبرهم بما كتب به زياد فقال له حجر أبلغ أمير المؤمنين أنا على بيعته لا نقيلها ولا نستقيلها وإنما شهد علينا الأعداء والأظناء فقدم يزيد بن حجية على معاوية بالكتاب وأخبره يقول حجر فقال معاوية زياد أصدق عندنا من حجر وكتب جرير بن عبد الله في أمر الرجلين اللذين من بجيلة فوهبهما له وليزيد بن أسد وطلب وائل بن حجر في الأرقم الكندي فتركه وطلب أبو الأعور في عتبة بن الأخنس فوهبه له وطلب حمزة بن مالك الهمداني في سعيد ابن نمران فوهبه له وطلب حبيب بن مسلمة في عبد الله بن جؤية التميمي فخلى سبيله فقام مالك بن هبيرة فسأله في حجر فلم يشفعه فغضب وجلس في بيته وبعث معاوية هدبة بن فياض القضاعي والحصين بن عبد الله الكلابي وآخر معهما يقال له أبو صريف البدري فأتوهم عند المساء فقال الخثعمي حين رأى الأعور يقتل نصفنا وينجو نصفنا فقال سعيد بن نمران اللهم اجعلني ممن ينجو وأنت عني راض فقال عبد الرحمن بن حسان العنزي اللهم اجعلني ممن يكرم بهوانهم وأنت عني راض فطالما عرضت نفسي للقتل فأبى الله إلا ما أراد","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":11,"spl":"كتاب زياد إلى معاوية — كتاب شريح بن هانىء إلى معاوية","tags":["أبي قيس بن الأسلت"],"loc":3028},
{"id":"b220-19","bab":"الجزء 17","sec":"رسول معاوية إلى أصحاب حجر","page":"ج17 ص155","text":"فجاء رسول معاوية إليهم فإنه لمعهم إذ جاء رسول بتخلية ستة منهم وبقي ثمانية فقال لهم رسول معاوية إنا قد أمرنا أن نعرض عليكم البراءة من علي واللعن له فإن فعلتم هذا تركناكم وإن أبيتم قتلناكم وأمير المؤمنين يزعم أن دماءكم قد حلت بشهادة أهل مصركم عليكم غير أنه قد عفا عن ذلك فابرأوا من هذا الرجل يخل سبيلكم قالوا لسنا فاعلين فأمر بقيودهم فحلت وأتي بأكفانهم فقاموا الليل كله يصلون فلما أصبحوا\nقال أصحاب معاوية يا هؤلاء قد رأيناكم البارحة أطلتم الصلاة وأحسنتم الدعاء فأخبرونا ما قولكم في عثمان قالوا هو أول من جار في الحكم وعمل بغير الحق فقالوا أمير المؤمنين كان أعرف بكم ثم قاموا إليهم وقالوا تبرأون من هذا الرجل قالوا بل نتولاه فأخذ كل رجل منهم رجلا يقتله فوقع قبيصة في يدي أبي صريف البدري فقال له قبيصة إن الشر بين قومي وقومك أمين أي آمن فليقتلني غيرك فقال برتك رحم فأخذه الحضرمي فقتله وقتل القضاعي صاحبه ثم\nقال لهم حجر دعوني أصلي ركعتين فإني والله ما توضأت قط إلا صليت فقالوا له صل فصلى ثم انصرف فقال والله ما صليت صلاة قط أقصر منها ولولا أن يروا أن ما بي جزع من الموت لأحببت أن أستكثر منها ثم\nقال اللهم إنا نستعديك على أمتنا فإن أهل الكوفة قد شهدوا علينا وإن أهل الشام يقتلوننا أما والله لئن قتلتمونا فإني أول فارس من المسلمين سلك في واديها وأول رجل من المسلمين نبحته كلابها فمشى إليه هدبة بن الفياض الأعور بالسيف فأرعدت خصائله فقال كلا زعمت أنك لا تجزع من الموت فإنا ندعك فابرأ من صاحبك فقال ما لي لا أجزع وأنا أرى قبرا\nمحفورا وكفنا منشورا وسيفا مشهورا وإني والله إن جزعت لا أقول ما يسخط الرب فقتله وأقبلوا يقتلونهم واحدا واحدا حتى قتلوا ستة نفر فقال عبد الرحمن بن حسان وكريم بن عفيف ابعثوا بنا إلى أمير المؤمنين فنحن نقول في هذا الرجل مثل مقالته فبعثوا إلى معاوية فأخبروه فبعث ائتوني بهما فالتفتا إلى حجر فقال له العنزي لا تبعد يا حجر ولا يبعد مثواك فنعم أخو الإسلام كنت وقال الخثعمي نحو ذلك ثم مضى بهما فالتفت العنزي فقال متمثلا\n(كفى بشفاة القبر بعدا لهالك ... وبالموت قطاعا لحبل القرائن)\nلما دخل عليه الخثعمي قال له الله الله يا معاوية إنك منقول من هذه الدار الزائلة إلى الدار الآخرة الدائمة ومسؤول عما أردت بقتلنا وفيما سفكت دماءنا فقال ما تقول في علي\nقال أقول فيه قولك أتبرأ من دين علي الذي كان يدين الله به وقام شمر بن عبد الله الخثعمي فاستوهبه فقال هو لك غير أني حابسه شهرا فحبسه ثم أطلقه على ألا يدخل الكوفة ما دام له سلطان فنزل الموصل فكان ينتظر موت معاوية ليعود إلى الكوفة فمات قبل معاوية بشهر وأقبل على عبد الرحمن بن حسان فقال له يا أخا ربيعة ما تقول في علي\nقال أشهد أنه من الذاكرين الله كثيرا والآمرين بالمعروف والناهين عن المنكر والعافين عن الناس قال فما تقول في عثمان قال هو أول من فتح أبواب الظلم وأرتج أبواب الحق قال قتلت نفسك قال بل إياك قتلت لا\nربيعة بالوادي يعني أنه ليس ثم أحد من قومه فيتكلم فيه فبعث به معاوية إلى زياد وكتب إليه إن هذا شر من بعثت به فعاقبه بالعقوبة التي هو أهلها واقتله شر قتلة فلما قدم به على زياد بعث به إلى قس الناطف فدفنه حيا\nقال أبو مخنف عن رجاله فكان من قتل منهم سبعة نفر حجر بن عدي وشريك بن شداد الحضرمي وصيفي بن فسيل الشيباني وقبيصة بن ضبيعة العبسي ومحرز بن شهاب المنقري وكدام بن حيان العنزي وعبد الرحمن بن حسان العنزي ونجا منهم سبعة كريم بن عفيف الخثعمي وعبد الله بن جؤية التميمي وعاصم بن عوف البجلي وورقاء بن سمي البجلي وأرقم بن عبد الله الكندي وعتبة بن الأخنس السعدي من هوازن وسعيد بن نمران الهمداني وبعث معاوية إلى مالك بن هبيرة لما غضب بسبب حجر مائة ألف درهم فرضي قال أبو مخنف فحدثني ابن أبي زائدة عن أبي إسحاق قال أدركت الناس يقولون أول ذل دخل الكوفة قتل حجر ودعوة زياد وقتل الحسين\nقال وجعل معاوية يقول عند موته أي يوم لي من ابن الأدبر طويل","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":12,"spl":"رسول معاوية إلى أصحاب حجر","tags":["أبي قيس بن الأسلت"],"loc":3029},
{"id":"b220-20","bab":"الجزء 17","sec":"رسول عائشة إلى معاوية في أمر حجر","page":"ج17 ص158","text":"قال أبو مخنف وحدثني عبد الملك بن نوفل بن مساحق من بني عامر بن لؤي أن عائشة بعثت عبد الرحمن بن الحارث بن هشام إلى معاوية في حجر وأصحابه فقدم عليه وقد قتلهم فقال له أين غاب عنك حلم أبي سفيان فقال حين غاب عني مثلك من حلماء قومي وحملني ابن سمية فاحتملت\nقال وكانت عائشة رضي الله عنها تقول لولا أنا لم نغير شيئا قط إلا آلت بنا الأمور إلى أشد مما كنا فيه لغيرنا قتل حجر أما والله إن كان لمسلما ما علمته حاجا معتمرا وقالت امرأة من كندة ترثي حجرا\n(ترفع أيها القمر المنر ... لعلك أن ترى حجرا يسير)\n(يسير إلى معاوية بن حرب ... ليقتله كما زعم الأمير)\n(ألا يا ليت حجرا مات موتا ... ولم ينحر كما نحر البعير)\n(ترفعت الجبابر بعد حجر ... وطاب لها الخورنق والسدير)\n(وأصبحت البلاد له محولا ... كأن لم يحيها مزن مطير)\n(ألا يا حجر حجر بني عدي ... تلقتك السلامة والسرور)\n(أخاف عليك سطوة آل حرب ... وشيخا في دمشق له زئير)\n(يرى قتل الخيار عليه حقا ... له من شر أمته وزير)\n(فإن تهلك فكل زعيم قوم ... إلى هلك من الدنيا يصير)\n\n(أحن إذا رأيت جمال سعدى ... وأبكي إن رأيت لها قرينا)\n(وقد أفد الرحيل فقل لسعدى ... لعمرك خبري ما تأمرينا)\nلشعر لعمر بن أبي ربيعة يقوله في سعدى بنت عبد الرحمن بن عوف والغناء لابن سريج رمل بالوسطى عن حبش وقد قيل إن عمر قال هذا البيت مع بيت آخر في ليلى بنت الحارث بن عوف المري وفيه أيضا غناء وهو\n(ألا يا ليل إن شفاء نفسي ... نوالك إن بخلت فزودينا)\n(وقد أفد الرحيل وحان منا ... فراقك فانظري ما تأمرينا)\nغنى به الغريض ثقيلا أول بالبنصر عن عمرو وحبش وفيه خفيف ثقيل يقال إنه أيضا للغريض ومن الناس من ينسبه إلى ابن سريج","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":13,"spl":"رسول عائشة إلى معاوية في أمر حجر","tags":["أبي قيس بن الأسلت"],"song":2,"loc":3030},
{"id":"b220-21","bab":"الجزء 17","sec":"أخبار لعمر بن أبي ربيعة","page":"ج17 ص160","text":"أخبرني حرمي عن الزبير عن طارق بن عبد الواحد قال قال عبد الرحمن المخزومي كانت سعدى بنت عبد الرحمن بن عوف جالسة في المسجد فرأت عمر ابن أبي ربيعة في الطواف فأرسلت إليه إذا قضيت طوافك فائتنا فلما قضى طوافه أتاها فحادثها وأنشدها فقالت ويحك يابن أبي ربيعة ما تزال سادرا في حرم الله منتهكا تتناول بلسانك ربات الحجال من قريش فقال دعي هذا عنك أما سمعت ما قلت فيك قالت وما قلت في فأنشدها\n(أحن إذا رأيت جمال سعدى ... وأبكي إن رأيت لها قرينا)\n(أسعدى إن أهلك قد أجدوا ... رحيلا فانظري ما تأمرينا)\nفقالت آمرك بتقوى الله وترك ما أنت عليه قال الزبير وحدثني عبد الله بن مسلم قال أنشد عمر بن أبي ربيعة ابن أبي عتيق قوله\n(أحن إذا رأيت جمال سعدى ... )\nقال فركب ابن أبي عتيق فأتى سعدى بالجناب من أرض بني فزارة فأنشدها قول عمر وقال لها ما تأمرين فقالت آمره بتقوى الله يا بن الصديق قال الزبير وحدثني طارق بن عبد الواحد عن أبي عبيدة عن عبد الرحمن المخزومي قال لقي عمر بن أبي ربيعة ليلى بنت الحارث بن عوف المري وهو يسير على بغلة فقال لها قفي أسمعك بعض ما قلت فيك فوقفت فقال\n(ألا يا ليل إن شفاء نفسي ... نوالك إن بخلت فنولينا)\nقال فما بلغنا أنها ردت عليه شيئا ومضت وقد روى هذا الخبر إبراهيم بن المنذر عن محمد بن معن فذكر أن ابن أبي عتيق إنما مضى إلى ليلى بنت الحارث بن عوف فأنشدها هذا البيت وهو الصحيح لأن حلولها بالجناب من أرض فزارة أشبه بها منه بسعدى بنت عبد الرحمن بن عوف ورواية الزبير فيما أروي وهم لاختلاط الشعرين في سعدى وليلى\nأخبرني حرمي عن الزبير عن محمد بن سلام قال كانت سعدى بنت عبد الرحمن بن عوف جالسة في المسجد الحرام فرأت عمر بن أبي ربيعة يطوف بالبيت فأرسلت إليه إذا فرغت من طوافك فائتنا فأتاها فقالت ألا أراك يابن أبي ربيعة إلا سادرا في حرم الله أما تخاف الله ويحك إلى متى هذا السفه قال أي هذه دعي عنك هذا من القول أما سمعت ما قلت فيك قالت لا فما قلت فأنشدها قوله\n(قالت سعيدة والدموع ذوارف ... منها على الخدين والجلباب)\n(ليت المغيري الذي لم أجزه ... فيما أطال تصيدي وطلابي)\n(كانت ترد لنا المنى أيامنا ... إذ لا نلام على هوى وتصابي)\n(أسعيد ما ماء الفرات وطيبه ... مني على ظمأ وحب شراب)\n(بألذ منك وإن نأيت وقلما ... يرعى النساء أمانة الغياب)\nروضه من الكامل غناه الهذلي رملا بالوسطى عن الهشامي وغناه الغريض خفيف ثقيل بالوسطى عن عمرو فقالت أخزاك الله يا فاسق ما علم الله أني قلت مما قلت حرفا ولكنك إنسان بهوت وهذا الشعر تغني فيه\nقالت سكينة والدموع ذوارف\nفي موضع\n(أسعيد ما ماء الفرات وبرده ... )\nسكين وإنما غيره المغنون ولفظ عمر ما ذكر فيه في الخبر وقد أخبرني إسماعيل بن يونس عن ابن شبة عن إسحاق قال غنيت الرشيد يوما بقوله\n(قالت سكينة والدموع ذوارف ... منها على الخدين والجلباب)\nوضع القدح من يده وغضب غضبا شديدا وقال لعنه الله الفاسق ولعنك معه فسقط في يدي وعرف ما بي فسكن ثم قال ويحك أتغنيني بأحاديث الفاسق ابن أبي ربيعة في بنت عمي وبنت رسول الله ألا تتحفظ في غنائك\nوتدري ما يخرج من رأسك عد إلى غنائك الآن وانظر بين يديك فتركت هذا الصوت حتى أنسيته فما سمعه مني أحد بعده والله أعلم\n(فلا زال قبر بين تبنى وجاسم ... عليه من الوسمي جود ووابل)\n(فينبت حوذانا وعوفا منورا ... سأتبعه من خير ما قال قائل)\nروضه من الطويل والشعر لحسان بن ثابت الأنصاري وهذا القبر الذي ذكره حسان فيما يقال قبر الأيهم بن جبلة بن الأيهم الغساني وقيل إنه قبر الحارث بن مارية الجفني وهو منهم أيضا والغناء لعزة الميلاء خفيف ثقيل أول بالوسطى مما لا يشك فيه من غنائها وقد نسبه قوم إلى ابن عائشة وذلك خطأ","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":14,"spl":"أخبار لعمر بن أبي ربيعة","tags":["أبي قيس بن الأسلت"],"song":2,"loc":3031,"partialRef":{"sid":"b220-20","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b220-23","bab":"الجزء 17","sec":"أخبار عزة الميلاء — آراء في عزة وغنائها","page":"ج17 ص163 – ج17 ص164","text":"كانت عزة مولاة للأنصار ومسكنها المدينة وهي أقدم من غنى الغناء الموقع من النساء بالحجاز وماتت قبل جميلة وكانت من أجمل النساء وجها وأحسنهن جسما وسميت الميلاء لتمايلها في مشيها وقيل بل كانت تلبس الملاء وتشبه بالرجال فسميت بذلك وقيل بل كانت مغرمة بالشراب وكانت تقول خذ ملئا واردد فارغا - ذكر ذلك حماد بن إسحاق عن أبيه والصحيح أنها سميت الميلاء لميلها في مشيتها\nقال إسحاق ذكر لي ابن جامع عن يونس الكاتب عن معبد قال كانت عزة الميلاء ممن أحسن ضربا بعود وكانت مطبوعة على الغناء لا يعيبها أداؤه ولا صنعته ولا تأليفه وكانت تغني أغاني القيان من القدائم مثل سيرين\nوزرنب وخولة والرباب وسلمى ورائقة وكانت رائقة أستاذتها فلما قدم نشيط وسائب خاثر المدينة غنيا أغاني بالفارسية فلقنت عزة عنهما نغما وألفت عليها ألحانا عجيبة فهي أول من فتن أهل المدينة بالغناء وحرض نساءهم ورجالهم عليه\nقال إسحاق وقال الزبير إنه وجد مشايخ أهل المدينة إذا ذكروا عزة قالوا لله درها ما كان أحسن غناءها ومد صوتها وأندى حلقها وأحسن ضربها بالمزاهر والمعازف وسائر الملاهي وأجمل وجهها وأظرف لسانها وأقرب مجلسها وأكرم خلقها وأسخى نفسها وأحسن مساعدتها\nقال إسحاق وحدثني أبي عن سياط عن معبد عن جميلة بمثل ذلك من القول فيها قال إسحاق وحدثني أبي عن يونس قال كان ابن سريج في حداثة سنه يأتي المدينة فيسمع من عزة ويتعلم غناءها\nويأخذ عنها وكان بها معجبا وكان إذا سئل من أحسن الناس غناء قال مولاة الأنصار المفضلة على كل من غنى وضرب بالمعازف والعيدان من الرجال والنساء\nقال وحدثني هشام بن المرية أن ابن محرز كان يقيم بمكة ثلاثة أشهر ويأتي المدينة فيقيم بها ثلاثة أشهر من أجل عزة وكان يأخذ عنها قال إسحاق\nوحدثني الجمحي عن جرير المغني المديني أن طويسا كان أكثر ما يأوي إلى منزل عزة الميلاء وكان في جوارها وكان إذا ذكرها يقول هي سيدة من غنى من النساء مع جمال بارع وخلق فاضل وإسلام لا يشوبه دنس تأمر بالخير وهي من أهله وتنهى عن السوء وهي مجانبة له فناهيك ما كان أنبلها وأنبل مجلسها ثم\nقال كانت إذا جلست جلوسا عاما فكأن الطير على رؤوس أهل مجلسها من تكلم أو تحرك نقر رأسه قال ابن سلام فما ظنك بمن يقول فيه طويس هذا القول ومن ذلك الذي سلم من طويس قال إسحاق وحدثني أبو عبد الله الأسلمي عن معبد أنه أتى عزة يوما وهي عند جميلة وقد أسنت وهي تغني على معزفة في شعر ابن الإطنابة قال\n(عللاني وعللا صاحبيا ... واسقياني من المروق ريا)\nقال فما سمع السامعون قط بشيء أحسن من ذلك قال معبد هذا غناؤها وقد أسنت فكيف بها وهي شابة قال إسحاق وذكر لي عن صالح بن حسان الأنصاري\nقال كانت عزة مولاة لنا وكانت عفيفة جميلة وكان عبد الله بن جعفر وابن أبي عتيق وعمر بن أبي ربيعة يغشونها في منزلها فتغنيهم وغنت يوما عمر بن أبي ربيعة لحنا لها في شيء من شعره فشق ثيابه وصاح صيحة عظيمة صعق معها فلما أفاق\nقال له القوم لغيرك الجهل يا أبا الخطاب قال إني سمعت والله ما لم أملك معه نفسي ولا عقلي وقال إسحاق وحدثني أبو عبد الله الأسلمي المدني قال كان حسان بن ثابت معجبا بعزة الميلاء وكان يقدمها على سائر قيان المدينة","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":15,"spl":"أخبار عزة الميلاء — آراء في عزة وغنائها","tags":["أبي قيس بن الأسلت","السفر والحج"],"loc":3032},
{"id":"b220-24","bab":"الجزء 17","sec":"عزة تغني شعرا لحسان فيبكي","page":"ج17 ص167","text":"أخبرني حرمي عن الزبير عن محمد بن الحسن المخزومي عن محرز ابن جعفر قال ختن زيد بن ثابت الأنصاري بنته فأولم فاجتمع إليه المهاجرون\nوالأنصار وعامة أهل المدينة وحضر حسان بن ثابت وقد كف بصره يومئذ وثقل سمعه وكان يقول إذا دعي أعرس أم عذار فحضر ووضع بين يديه خوان ليس عليه إلا عبد الرحمن ابنه فكان يسأله أطعام يد أم يدين فلم يزل يأكل حتى جاؤوا بالشواء فقال طعام يدين فأمسك يده حتى إذا فرغ من الطعام ثنيت وسادة وأقبلت الميلاء وهي يومئذ شابة فوضع في حجرها مزهر فضربت به ثم تغنت فكان أول ما ابتدأت به شعر حسان قال\n(فلا زال قبر بين بصرى وجلق ... عليه من الوسمي جود ووابل)\nطرب حسان وجعلت عيناه تنضحان وهو مصغ لها أخبرني ابن عبد العزيز الجوهري عن ابن شبة عن الأصمعي عن أبي الزناد قال قلت لخارجة بن زيد أكان يكون هذا الغناء عندكم قال كان يكون في العرسات ولم يكن يشهد بما يشهد به اليوم من السعة وكان في إخواننا بني نبيط مأدبة فدعينا وثم قينة أو قينتان تنشدان شعر حسان بن ثابت قال\n(انظر خليلي بباب جلق هل ... تبصر دون البلقاء من أحد)\nال وحسان يبكي وابنه يومىء إليهما أن زيدا فإذا زادتا بكى حسان فأعجبني ما يعجبه من أن تبكيا أباه وقد كف بصر حسان بن ثابت يومئذ أخبرنا وكيع عن حماد بن إسحاق عن أبيه عن الواقدي عن عبد الرحمن بن أبي الزناد عن أبيه\nقال سمعت خارجة بن زيد يقول دعينا إلى مأدبة في آل نبيط قال خارجة فحضرتها وحسان بن ثابت قد حضرها فجلسنا جميعا على مائدة واحدة وهو يومئذ قد ذهب بصره ومعه ابنه عبد الرحمن فكان إذا أتى طعام سأل ابنه أطعام يد أم يدين يعني باليد الثريد وباليدين الشواء لأنه ينهش نهشا فإذا\nقال طعام يدين أمسك يده فلما فرغوا من الطعام أتوا بجاريتين إحداهما رائقة والأخرى عزة فجلستا وأخذتا مزهريهما وضربتا ضربا عجيبا وغنتا بقول حسان\n(انظر خليلي بباب جلق هل ... تبصر دون البلقاء من أحد)\nأسمع حسانا يقول\n(قد أراني بها سميعا بصيرا ... )\nعيناه تدمعان فإذا سكتتا سكت عنه البكاء وإذا غنتا بكى فكنت أرى ابنه عبد الرحمن إذا سكتتا يشير إليهما أن تغنيا فيبكي أبوه فأقول ما حاجته إلى إبكاء أبيه قال الواقدي فحدثت بهذا الحديث يعقوب بن محمد الظفري فقال سمعت سعيد بن عبد الرحمن بن حسان يقول لما انقلب حسان من مأدبة بني\nنبيط إلى منزله استلقى على فراشه ووضع إحدى رجليه على الأخرى وقال لقد أذكرتني رائقة وصاحبتها أمرا ما سمعته أذناي بعيد ليالي جاهليتنا مع جبلة بن الأيهم فقلت يا أبا الوليد أكان القيان يكن عند جبلة فتبسم ثم جلس فقال لقد رأيت عشر قيان خمس روميات يغنين بالرومية بالبرابط وخمس يغنين غناء أهل الحيرة وأهداهن إليه إياس بن قبيصة وكان يفد إليه من يغنيه من العرب من مكة وغيرها وكان إذا جلس للشرب فرش تحته الآس والياسمين وأصناف الرياحين وضرب له العنبر والمسك في صحاف الفضة والذهب وأتي بالمسك الصحيح في صحاف الفضة وأوقد له العود المندى إن كان شاتيا وإن كان صائفا بطن بالثلج وأتي هو وأصحابه بكسا صيفية يتفضل هو وأصحابه بها في الصيف وفي الشتاء الفراء الفنك وما أشبهه ولا والله ما جلست معه يوما قط إلا خلع علي ثيابه التي عليه في ذلك اليوم وعلى غيري من جلسائه هذا مع حلم عمن جهل وضحك وبذل من غير مسألة مع حسن وجه وحسن حديث ما رأيت منه خنى قط ولا عربدة ونحن يومئذ على الشرك فجاء الله بالإسلام فمحا به كل كفر وتركنا الخمرة وما كره وأنتم اليوم مسلمون تشربون هذا النبيذ من التمر والفضيخ من الزهر والرطب فلا يشرب أحدكم ثلاثة أقداح حتى\nيصاحب صاحبته ويفارقها وتضربون فيه كما تضرب غرائب الإبل فلا تنتهون أخبرني أحمد بن عبد العزيز الجوهري عن أبي أيوب المديني عن مصعب الزبيري عن الضحاك عن عثمان بن أبي الزناد عن أبيه عن خارجة بن زيد مثله وزاد فيه فلما فرغنا من الطعام ثقل علينا جلوس حسان فأومأ ابنه إلى عزة الميلاء فغنت\n(انظر خليلي بباب جلق هل ... تبصر دون البلقاء من أحد)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":16,"spl":"عزة تغني شعرا لحسان فيبكي","tags":["أبي قيس بن الأسلت"],"loc":3033,"partial":1},
{"id":"b220-26","bab":"الجزء 17","sec":"عزة تغني شعرا لحسان فيبكي — نسبة هذا الصوت","page":"ج17 ص167 – ج17 ص171","text":"بكى حسان حتى سدر ثم قال هذا عمل الفاسق أما لقد كرهتم مجالستي فقبح الله مجلسكم سائر اليوم وقام فانصرف أخبرني حرمي عن الزبير عن عمه مصعب قال ذكر هشام بن عروة عن أبيه أنه دعي إلى مأدبة في زمن عثمان ودعي حسان ومعه ابنه عبد الرحمن ثم ذكر نحو ما ذكره عمر بن شبة عن الأصمعي في الحديث الأول قال\n(انظر خليلي بباب جلق هل ... تؤنس دون البلقاء من أحد)\n(أجمال شعثا إن هبطن من المحبس ... بين الكثبان فالسند)\n(يملن حورا حور المدامع في الريط ... وبيض الوجوه كالبرد)\n(من دون بصرى ودونها جبل الثلج ... عليه السحاب كالقرد)\n(إني وأيدي المخيسات وما ... يقطعن من كل سربخ جدد)\n(أهوى حديث الندمان في فلق الصبح ... وصوت المسامر الغرد)\n(تقول شعثا بعدما هبطت ... بصور حسنى من احتدى بلدي)\n(لا أخدش الخدش بالحبيب ولا ... يخشى نديمي إذا انتشيت يدي)\nالشعر لحسان بن ثابت والغناء لعزة الميلاء رمل بالبنصر وفيه خفيف ثقيل ينسب إلى ابن محرز وإلى عزة الميلاء وإلى الهذلي في\n(تقول شعثاء بعدما هبطت ... )\nما بعده من الأبيات ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيها لعبد الرحيم ثاني ثقيل بالوسطى عن عمرو","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":17,"spl":"عزة تغني شعرا لحسان فيبكي — نسبة هذا الصوت","tags":["أبي قيس بن الأسلت"],"loc":3034,"partial":1},
{"id":"b220-27","bab":"الجزء 17","sec":"حسان بن ثابت وشعثاء","page":"ج17 ص172","text":"وشعثاء هذه التي شبب بها حسان - فيما ذكر الواقدي ومصعب الزبيري - امرأة من أسلم تزوجها حسان وولدت منه بنتا يقال لها أم فراس تزوجها عبد الرحمن بن أم الحكم وذكر أبو عمرو الشيباني مثل ما ذكره في نسبها ووصف له أنه خطبها إلى قومها من أسلم فردوه فقال يهجوهم\n(لقد أتى عن بني الجرباء قولهم ... ودونهم قف جمدان فموضوع)\n(قد علمت أسلم الأرذال أن لها ... جارا سيقتله في داره الجوع)\n(وأن سيمنعهم ما نووا حسب ... - لن يبلغ المجد والعلياء - مقطوع)\n(وقد علوا - زعموا - عني بأختهم ... وفي الذرا حسبي والمجد مرفوع)\n(ويل أم شعثاء شيئا تستغيث به ... إذا تجللها النعظ الأفاقيع)\n(كأنه في صلاها وهي باركة ... ذراع بكر من النياط منزوع)\nخبرني حرمي عن الزبير عن إبراهيم بن المنذر عن أبي القاسم بن أبي الزناد عن أخيه عبد الرحمن عن أبيه عن خارجة بن زيد قال شعثاء هذه بنت عمرو من بني ماسكة من يهود وكانت مساكن بني ماسكة بناحية القف وكان أبو الشعثاء قد رأس اليهود التي تلي بيت الدراسة للتوراة وكان ذا قدر فيهم فقال حسان يذكر ذلك\n(هل في تصابي الكريم من فند ... أم هل لمدى الأيام من نفد)\n(تقول شعثاء لو أفقت عن الكاس ... لألفيت مثري العدد)\n(يأبى لي السيف واللسان وقوم ... لم يضاموا كلبدة الأسد)\nذكر باقي الأبيات التي فيها الغناء ومما قاله حسان بن ثابت في شعثاء وغني به قوله\n(ما هاج حسان رسوم المقام ... ومظعن الحي ومبنى الخيام)\n(والنؤي قد هدم أعضاده ... تقادم العهد بوادي تهام)\n(قد أدرك الواشون ما حاولوا ... والحبل من شعثاء رث رمام)\n(جنية أرقني طيفها ... يذهب صبحا ويرى في المنام)\n(هل هي إلا ظبية مطفل ... مألفها السدر بنعفي برام)\n(ترعى غزالا فاترا طرفه ... مقارب الخطو ضعيف البغام)\n(كأن فاها ثغب بارد ... في رصف تحت ظلال الغمام)\n(شج بصهباء لها سورة ... من بنت كرم عتقت في الخيام)\n(تدب في الكأس دبيبا كما ... دب دبى وسط رفاق هيام)\n(من خمر بيسان تخيرتها ... درياقة توشك فتر العظام)\n(يسعى بها أحمر ذو برنس ... محتلق الذفرى شديد الحزام)\nيقول فيها\n(قومي بنو النجار إذ أقبلت ... شهباء ترمي أهلها بالقتام)\n(لا تخذل الجار ولا تسلم المولى ... ولا تخصم يوم الخصام)\nلشعر لحسان والغناء لمعبد خفيف رمل بإطلاق الوتر في مجرى الوسطى في البيت الأول من الأبيات والرابع والتاسع والحادي عشر وذكر الهشامي أن فيه لحنا لابن سريج من الرمل بالوسطى وهذه الأبيات يقولها حسان في حرب كانت بينهم وبين الأوس تعرف بحرب مزاحم وهو حصن من حصونهم\nأخبرني بخبره حرمي عن الزبير عن عمه مصعب قال جمعت الأوس وحشدت بأحلافها ورأسوا عليهم أبا قيس بن الأسلت يومئذ فسار بهم حتى كان قريبا من مزاحم وبلغ ذلك الخزرج فخرجوا يومئذ عليهم سعد بن عبادة وذلك أن عبد الله بن أبي كان مريضا أو متمارضا\nفاقتتلوا قتالا شديدا وقتلت بينهم قتلى كثيرة وكان الطول يومئذ للأوس فقال حسان في ذلك\n(ما هاج حسان رسوم المقام ... ومظعن الحي ومبنى الخيام)\nذكر الأبيات كلها أخبرني أحمد بن عبد العزيز عن عمر بن القاسم بن الحسن عن محمد ابن سعد عن الواقدي عن عثمان بن إبراهيم الحاطبي قال قال رجل من أهل المدينة ما ذكر بيت حسان بن ثابت\n(أهوى حديث الندمان في فلق الصبح ... وصوت المسامر الغرد)\nلا عدت في الفتوة كما كنت قال وهذا البيت من قصيدته التي يقول فيها\n(انظر خليلي بباب جلق هل ... تؤنس دون البلقاء من أحد)\nوقد روي أيضا في هذا الخبر غير الروايتين اللتين ذكرتهما أخبرني بذلك حرمي عن الزبير عن وهب بن جرير عن جويرية بن أسماء عن عبد الوهاب بن يحيى عن عباد بن عبد الله بن الزبير عن شيخ من قريش قال إني وفتية من قريش عند قينة من قيان المدينة ومعنا عبد الرحمن بن حسان بن ثابت إذ استأذن حسان فكرهنا دخوله وشق ذلك علينا فقال لنا عبد الرحمن أيسركم ألا يجلس قلنا نعم قال فمروها إذا نظرت إليه أن ترفع عقيرتها وتغني\n(أولاد جفنة عند قبر أبيهم ... قبر ابن مارية الكريم المفضل)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\nال فوالله لقد بكى حتى ظننا أنه سقطت نفسه ثم قال أفيكم الفاسق لعمري لقد كرهتم مجلسي سائر اليوم وقام فانصرف والله تعالى أعلم نسبة هذا الصوت وسائر ما يغنى فيه من القصيدة التي هو منها","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":18,"spl":"حسان بن ثابت وشعثاء","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3035},
{"id":"b220-28","bab":"الجزء 17","sec":"حسان بن ثابت وشعثاء","page":"ج17 ص172","text":"(أولاد جفنة عند قبر أبيهم ... قبر ابن مارية الجواد المفضل)\n(يسقون من ورد البريص عليهم ... كأسا تصفق بالرحيق السلسل)\nلبريص موضع بدمشق\n(بيض الوجوه كريمة أحسابهم ... شم الأنوف من الطراز الأول)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\nكر حبش أن فيه لسيرين قينة حسان بن ثابت لحنا ثقيلا أول ابتداؤه نشيد وفيه لعريب ثقيل أول لا يشك فيه ومما يغنى فيه من هذه القصيدة قوله\n(كلتاهما حلب العصير فعاطني ... بزجاجة أرخاهما للمفصل)\n(بزجاجة رقصت بما في قعرها ... رقص القلوص براكب مستعجل)\nغناه إبراهيم الموصلي رملا مطلقا في مجرى الوسطى عن إسحاق وعمرو وغيرهما ويروى كلتاهما حلب العصير بجعل الفعل للعصير ويروى للمفصل بكسر الميم وفتح الصاد وللمفصل بفتح الميم وكسر الصاد وهو اللسان أخبرنا بذلك علي بن سليمان الأخفش عن المبرد حكاية عن أصحابه عن الأصمعي","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":19,"spl":"حسان بن ثابت وشعثاء — نسبة هذا الصوت","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3036},
{"id":"b220-29","bab":"الجزء 17","sec":"رجع الحديث إلى أخبار عزة الميلاء","page":"ج17 ص178","text":"قال إسحاق حدثني مصعب الزبيري عن محمد بن عبيد الله بن عبد الله بن أبي مليكة عن أبيه عن جده قال كان بالمدينة رجل ناسك من أهل العلم والفقه وكان يغشى عبد الله بن جعفر فسمع جارية مغنية لبعض النخاسين تغني\n(بانت سعاد وأمسى حبلها انقطعا ... )\nاستهتر بها وهام وترك ما كان عليه حتى مشى إليه عطاء وطاوس فلاماه فكان جوابه لهما أن تمثل بقول الشاعر\n(بلومني فيك أقوام أجالسهم ... فما أبالي أطار اللوم أم وقعا)\nوبلغ عبد الله بن جعفر خبره فبعث إلى النخاس فاعترض الجارية وسمع غناءها بهذا الصوت وقال لها ممن أخذته قالت من عزة الميلاء فابتاعها بأربعين ألف درهم ثم بعث إلى الرجل فسأله عن خبره فأعلمه إياه وصدقه عنه فقال له أتحب أن تسمع هذا الصوت ممن أخذته عنه تلك الجارية\nقال نعم فدعا بعزة وقال لها غنيه إياه فغنته فصعق الرجل وخر مغشيا عليه فقال ابن جعفر أثمنا فيه الماء الماء فنضح على وجهه فلما أفاق قال له أكل هذا بلغ بك عشقها\nقال وما خفي عنك أكثر قال أفتحب أن تسمعه منها قال قد رأيت ما نالني حين سمعته من غيرها وأنا لا أحبها فكيف يكون حالي إن سمعته منها وأنا لا أقدر على ملكها\nقال أفتعرفها إن رأيتها قال أو أعرف غيرها فأمر بها فأخرجت وقال خذها فهي لك والله ما نظرت إليها إلا عن عرض فقبل الرجل يديه ورجليه وقال أنمت عيني وأحييت نفسي وتركتني أعيش بين قومي ورددت إلي عقلي ودعا له دعاء كثيرا فقال ما أرضى أن أعطيكها هكذا يا غلام احمل معها مثل ثمنها لكيلا تهتم به ويهتم بها","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":19,"spl":"حسان بن ثابت وشعثاء — نسبة هذا الصوت","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3037,"partialRef":{"sid":"b78-15","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b220-30","bab":"الجزء 17","sec":"نسبة هذا الصوت","page":"ج17 ص179","text":"\n(بانت سعاد وأمسى حبلها انقطعا ... واحتلت الغور فالجدين فالفرعا)\n(وأنكرتني وما كان الذي نكرت ... من الحوادث إلا الشيب والصلعا)\nروضه من البسيط والشعر للأعشى أعشى بني قيس بن ثعلبة\nوزعم الأصمعي أن البيت الثاني هو صنعه ونحله الأعشى أخبرنا محمد بن العباس اليزيدي عن عمه عن عبد الرحمن بن أخي الأصمعي عن عمه قال ما نحلت أحدا من الشعراء شيئا قط لم يقله إلا بيتا واحدا نحلته الأعشى وهو\n(وأنكرتني وما كان الذي نكرت ... من الحوادث إلا الشيب والصلعا)\nلغناء لعزة الميلاء خفيف ثقيل أول بالوسطى وذكر عمرو بن بانة أنه لمعبد وأنكر إسحاق ذلك ودفعه وفيه للغريض ثقيل أول بالبنصر وقيل إنه لجميلة","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":19,"spl":"حسان بن ثابت وشعثاء — نسبة هذا الصوت","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3038},
{"id":"b220-31","bab":"الجزء 17","sec":"عزة تغني في المدينة","page":"ج17 ص180","text":"قال إسحاق وحدثني ابن سلام عن ابن جعدبة قال كان ابن أبي عتيق معجبا بعزة الميلاء فأتى يوما عند عبد الله بن جعفر فقال له بأبي أنت وأمي هل لك في عزة فقد اشتقت إليها\nقال لا أنا اليوم مشغول فقال بأبي أنت وأمي إنها لا تنشط إلا بحضورك فأقسمت عليك إلا ساعدتني وتركت شغلك ففعل فأتياها ورسول الأمير على بابها يقول لها دعي الغناء فقد ضج أهل المدينة منك وذكروا أنك قد فتنت رجالهم ونساءهم فقال له ابن جعفر ارجع إلى صاحبك فقل له عني أقسم عليك إلا ناديت في المدينة أيما رجل فسد أو امرأة فتنت بسبب عزة إلا كشف نفسه بذلك لنعرفه ويظهر لنا ولك أمره فنادى الرسول بذلك فما أظهر أحد نفسه ودخل ابن جعفر إليها وابن أبي عتيق معه فقال لها لا يهولنك ما سمعت وهاتي فغنينا فغنته\nبشعر القطامي\n(إنا محيوك فاسلم أيها الطلل ... وإن بليت وإن طالت بك الطيل)\nاهتز ابن أبي عتيق طربا فقال عبد الله بن جعفر ما أراني أدرك ركابك بعد أن سمعت هذا الصوت من عزة وقد مضت نسبة ما في هذه الأخبار من الأغاني في مواضع أخر\n(من كان مسرورا بمقتل مالك ... فليأت نسوتنا بوجه نهار)\n(يجد النساء حواسرا يندبنه ... قد قمن قبل تبلج الأسحار)\nروضه من الكامل قوله\n(قد قمن قبل تبلج الأسحار ... )\nعني أنهن يندبنه في ذلك الوقت وإنما خصه بالندبة لأنه وقت الغارة يقول فهن يذكرنه حينئذ لأنه كان من الأوقات التي ينهض فيها للحرب والغارات قال الله تبارك وتعالى ( فالمغيرات صبحا\nوأما قول الخنساء\n(يذكرني طلوع الشمس صخرا ... وأذكره لكل غروب شمس)\nإنما ذكرته عند طلوع الشمس للغارة وعند غروبها للضيف الشعر للربيع بن زياد العبسي والغناء لابن سريج رمل بالخنصر في مجرى البنصر عن إسحاق والله أعلم","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":20,"spl":"عزة تغني في المدينة — ذكر نسب الربيع بن زياد وبعض أخباره وقصة هذا الشعر والسبب الذي قتل من","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3039,"partial":1},
{"id":"b220-32","bab":"الجزء 17","sec":"ذكر نسب الربيع بن زياد وبعض أخباره وقصة هذا الشعر والسبب الذي قتل من","page":"ج17 ص182","text":"أجله هو الربيع بن زياد بن عبد الله بن سفيان بن ناشب بن هدم بن عوذ بن غالب بن قطيعة بن عبس بن بغيض بن ريث بن غطفان بن سعد بن قيس بن عيلان بن مضر بن نزار وأمه فاطمة بنت الخرشب واسم الخرشب عمرو بن النضر بن حارثة ابن طريف بن أنمار بن بغيض بن ريث بن غطفان وهي إحدى المنجبات كان يقال لبنيها الكملة وهم الربيع وعمارة وأنس","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":20,"spl":"عزة تغني في المدينة — ذكر نسب الربيع بن زياد وبعض أخباره وقصة هذا الشعر والسبب الذي قتل من","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3040},
{"id":"b220-34","bab":"الجزء 17","sec":"أم الربيع إحدى المنجبات — ذكاء الربيع","page":"ج17 ص183 – ج17 ص185","text":"ولما سأل معاوية علماء العرب عن البيوتات والمنجبات وحظر عليهم أن يتجاوزوا في البيوتات ثلاثة وفي المنجبات ثلاثا عدوا فاطمة بنت الخرشب فيمن عدوا وقبلها حيية بنت رياح الغنوية أم الأحوص وخالد ومالك وربيعة بني جعفر بن كلاب وماوية بنت عبد مناة بن مالك بن زيد بن عبد الله بن دارم بن\nعمرو بن تميم وهي أم لقيط وحاجب وعلقمة بني زرارة بن عدس بن زيد بن عبد الله بن دارم أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثني محمد بن موسى اليزيدي\nقال حدثني محمد بن صالح بن النطاح واللفظ له وخبره أتم وأخبرني به أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال ولدت فاطمة بنت الخرشب من زياد بن عبد الله العبسي سبعة فعدت العرب المنجبين منهم ثلاثة وهم خيارهم\nقال محمد بن موسى قال محمد بن صالح وحدثني موسى بن طلحة والوليد بن هشام القحذمي بمثل ذلك قال فمنهم الربيع ويقال له الكامل وعمارة وهو الوهاب وأنس وهو أنس الفوارس وهو الواقعة وقيس وهو البرد والحارث وهو الحرون ومالك وهو لاحق وعمرو وهو الدراك\nقال محمد بن موسى قال ابن النطاح وحدثني أبو عثمان العمري أن عبد الله بن جدعان لقي فاطمة بنت الخرشب وهي تطوف بالكعبة فقال لها نشدتك برب هذه البنية أي بنيك أفضل قالت الربيع لا بل\nعمارة لا بل أنس ثكلتهم إن كنت أدري أيهم أفضل قال ابن النطاح وحدثني أبو اليقظان سحيم بن حفص العجيفي قال حدثني أبو الخنساء قال سئلت فاطمة عن بنيها أيهم أفضل فقالت الربيع لا بل عمارة لا بل أنس لا بل قيس وعيشي ما أدري أما والله ما حملت واحدا منهما تضعا ولا ولدته يتنا ولا أرضعته غيلا ولا منعته قيلا ولا أبته على ماقة\nقال أبو اليقظان أما قولها ما حملت واحدا منهم تضعا فتقول لم أحمله في دبر الطهر وقبل الحيض وقولها ولا ولدته يتنا وهو أن تخرج رجلاه قبل رأسه ولا أرضعته غيلا أي ما أرضعته قبل أن أحلب ثديي ولا منعته قيلا أي لم أمنعه اللبن عند القائلة ولا أبته على ماقة أي وهو يبكي\nقال ابن النطاح وحدثني أبو اليقظان قال حدثني أبو صالح الأسدي قال سئلت فاطمة بنت الخرشب عن بنيها فوصفتهم وقالت في عمارة لا ينام ليلة يخاف ولا يشبع ليلة يضاف وقالت في الربيع لا تعد مآثره ولا تخشى في الجهل بوادره وقالت في أنس إذا عزم أمضى وإذا سئل أرضى وإذا قدر أغضى وقالت في الآخرين أشياء لم يحفظها أبو اليقظان وقال ابن النطاح وحدثني القحذمي قال حدثني أبي قال حدثني ابن عياش عن رجل من بني عبس قال\nضاف فاطمة ضيف فطرحت عليه شملة من خز وهي مسك كما هي فلما وجد رائحتها وأعتم دنا منها فصاحت به فكف عنها ثم إنه تحرك\nأيضا فأرادها عن نفسها فصاحت فكف ثم إنه لم يصبر فواثبها فبطشت به فإذا هي من أشد الناس فقبضت عليه ثم صاحت يا قيس فأتاها فقالت إن هذا أرادني عن نفسي فما ترى فيه فقال أخي أكبر منك فعليك فه فنادت يا أنس فأتاها فقالت إن هذا أرادني عن نفسي فما ترى فيه فقال لها أخي أكبر مني فسليه فنادت يا عمارة فأتاها فذكرت ذلك له فقال لها السيف وأراد قتله فقالت له يا بني لو دعونا أخاك فهو أكبر منك فدعت الربيع فذكرت ذلك له فقال أفتطيعونني يا بني زياد قالوا نعم\nقال فلا تزنوا أمكم ولا تقتلوا ضيفكم وخلوه يذهب فذهب قال ابن النطاح وقال بعض الشعراء يمدح بني زياد من فاطمة يقال إنه قيس بن زهير ويقال حاتم طيىء\n(بنو جنية ولدت سيوفا ... قواطع كلهم ذكر صنيع)\n(وجارتهم حصان لم تزنى ... وطاعمة الشتاء فما تجوع)\n(شرى ودي ومكرمتي جميعا ... طوال زمانه مني الربيع)\nقال سلمة بن الخرشب خالهم فيهم يخاطب قوما منهم أرادوا حربه\n(أتيتم إلينا ترجفون جماعة ... فأين أبو قيس وأين ربيع)\n(وذاك ابن أخت زانه ثوب خاله ... وأعمامه الأعمام وهو نزيع)\n(رفيق بداء الحرب طب بصعبها ... إذا شت رأي القوم فهو جميع)\n(عطوف على المولى ثقيل على العدا ... أصم عن العوراء وهو سميع)\nوقال رجل من طيىء ويقال له الربيع بن عمارة\n(فإن تكن الحوادث أفظعتني ... فلم أر هالكا كابني زياد)\n(هما رمحان خطيان كانا ... من السمر المثقفة الجياد)\n(تهاب الأرض أن يطأ عليها ... بمثلهما تسالم أو تعادي)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":21,"spl":"أم الربيع إحدى المنجبات — ذكاء الربيع","tags":["أبي قيس بن الأسلت"],"loc":3041},
{"id":"b220-35","bab":"الجزء 17","sec":"وأمه تقتل نفسها خوفا من النار","page":"ج17 ص186","text":"وقال الأثرم حدثني أبو عمرو الشيباني قال أغار حمل بن بدر أخو حذيفة بن بدر الفزاري على بني عبس فظفر بفاطمة بنت الخرشب أم الربيع بن زياد إخوته راكبة على جمل لها فقادها بجملها فقالت له أي رجل ضل حلمك والله لئن أخذتني فصارت هذه الأكمة بي وبك التي أمامنا وراءنا لا يكون بينك وبين بني زياد صلح أبدا لأن الناس يقولون في هذه الحال ما شاؤوه وحسبك من شر سماعه\nقال فإني أذهب بك حتى ترعى علي إبلي فلما أيقنت أنه ذاهب بها رمت بنفسها على رأسها من البعير فماتت خوفا من أن يحلق بنيها عار فيها وحدثني محمد بن العباس اليزيدي قال حدثني عمي عبد الله بن محمد قال أخبرنا محمد بن حبيب عن ابن الأعرابي قال","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":22,"spl":"وأمه تقتل نفسها خوفا من النار","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3042},
{"id":"b220-36","bab":"الجزء 17","sec":"لبيد يحاول الإيقاع بينه وبين النعمان","page":"ج17 ص187","text":"وفد أبو براء ملاعب الأسنة - وهو عامر بن مالك بن جعفر بن كلاب - وإخوته طفيل ومعاوية وعبيدة ومعهم لبيد بن ربيعة بن مالك بن جعفر وهو غلام على النعمان بن المنذر فوجدوا عنده الربيع بن زياد العبسي وكان\nالربيع ينادم النعمان مع رجل من أهل الشام تاجر يقال له سرجون بن توفل وكان حريفا للنعمان - يعني سرجون - يبايعه وكان أديبا حسن الحديث والمنادمة فاستخفه النعمان وكان إذا أراد أن يخلو على شرابه بعث إليه وإلى النطاسي - متطبب كان له - وإلى الربيع بن زياد وكان يدعى الكامل فلما قدم الجعفريون كانوا يحضرون النعمان لحاجتهم فإذا خلا الربيع بالنعمان طعن فيهم\nوذكر معايبهم ففعل ذلك بهم مرارا وكانت بنو جعفر له أعداء فصده عنهم فدخلوا عليه يوما فرأوا منه تغيرا وجفاء وقد كان يكرمهم قبل ذلك ويقرب مجلسهم فخرجوا من عنده غضابا ولبيد في رحالهم يحفظ أمتعتهم ويغدوا بإبلهم كل صباح فيرعاها فإذا أمسى انصرف بإبلهم فأتاهم ذات ليلة فألفاهم يتذاكرون أمر الربيع وما يلقون منه فسألهم فكتموه فقال لهم والله لا أحفظ لكم متاعا ولا أسرح لكم بعيرا أو تخبروني وكانت أم لبيد امرأة من بني عبس وكانت يتيمة في حجر الربيع فقالوا خالك قد غلبنا على الملك وصد عنا وجهه فقال لهم لبيد هل تقدرون على أن تجمعوا بينه وبيني فأزجره عنكم بقول ممض ثم لا يلتفت النعمان إليه بعده أبدا فقالوا وهل عندك من ذلك شيء\nقال نعم قالوا فإنا نبلوك بشتم هذه البقلة - لبقلة قدامهم دقيقة القضبان قليلة الورق لاصقة فروعها بالأرض تدعى التربة - فقال هذه التربة التي لا تذكي نارا ولا تؤهل دارا ولا تسر جارا عودها ضئيل وفرعها كليل وخيرها قليل بلدها شاسع ونبتها خاشع وآكلها جائع والمقيم عليها ضائع أقصر البقول فرعا وأخبثها مرعى وأشدها قلعا فتعسا لها وجدعا ألقوا بي أخا بني عبس أرجعه عنكم بتعس ونكس وأتركه من أمره في لبس فقالوا نصبح فنرى فيك رأينا فقال لهم عامر انظروا غلامكم فإن\nرأيتموه نائما فليس أمره بشيء وإنما يتكلم بما جاء على لسانه ويهذي بما يهجس في خاطره وإذا رأيتموه ساهرا فهو صاحبكم فرمقوه بأبصارهم فوجدوه قد ركب رحلا فهو يكدم بأوسطه حتى أصبح فلما أصبحوا قالوا أنت والله صاحبنا فحلقوا رأسه وتركوا ذؤابتين وألبسوه حلة ثم غدوا به معهم على النعمان فوجدوه يتغدى ومعه الربيع وهما يأكلان ليس معه غيره والدار والمجالس مملوءة من الوفود فلما فرغ من الغداء أذن للجعفريين فدخلوا عليه وقد كان تقارب أمرهم فذكروا للنعمان الذي قدموا له من حاجتهم فاعترض الربيع في كلامهم فقام لبيد يرتجز ويقول\n(يا رب هيجا هي خير من دعه ... أكل يوم هامتي مقزعه)\n(نحن بنو أم البنين الأربعه ... ومن خيار عامر بن صعصعه)\n(المطعمون الجفنة المدعدعه ... والضاربون الهام تحت الخيضعه)\n(يا واهب الخير الكثير من سعه ... إليك جاوزنا بلادا مسبعه)\n(يخبر عن هذا خبير فاسمعه ... مهلا - أبيت اللعن - لا تأكل معه)\n(إن استه من برص ملمعه ... وإنه يدخل فيها إصبعه)\n(يدخلها حتى يواري أشجعه ... كأنما يطلب شيئا أطمعه)\nلما فرغ من إنشاده التفت النعمان إلى الربيع شزرا يرمقه فقال أكذا\nأنت قال لا والله لقد كذب علي ابن الحمق اللئيم فقال النعمان أف لهذا الغلام لقد خبث علي طعامي فقال أبيت اللعن أما إني لقد فعلت بأمه فقال لبيد أنت لهذا الكلام أهل وهي من نساء غير فعل وأنت المرء فعل هذا بيتيمة في حجره فأمر النعمان ببني جعفر فأخرجوا وقام الربيع فانصرف إلى منزله فبعث إليه النعمان بضعف ما كان يحبوه به وأمره بالانصراف إلى أهله وكتب إليه الربيع إني قد تخوفت أن يكون قد وقر في صدرك ما قاله لبيد ولست برائم حتى تبعث من يجردني فيعلم من حضرك من الناس أني لست كما قال فأرسل إليه إنك لست صانعا بانتفائك مما قال لبيد شيئا ولا قادرا على ما زلت به الألسن فالحق بأهلك فقال الربيع\n(لئن رحلت جمالي إن لي سعة ... ما مثلها سعة عرضا ولا طولا)\n(بحيث لو وزنت لخم بأجمعها ... لم يعدلوا ريشة من ريش سمويلا)\n(ترعى الروائم أحرار البقول بها ... لا مثل رعيكم ملحا وغسويلا)\n(فابرق بأرضك يا نعمان متكئا ... مع النطاسي يوما وابن توفيلا)\nكتب إليه النعمان\n(شرد برحلك عني حيث شئت ولا ... تكثر علي ودع عنك الأباطيلا)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":23,"spl":"لبيد يحاول الإيقاع بينه وبين النعمان","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3043},
{"id":"b220-37","bab":"الجزء 17","sec":"لبيد يحاول الإيقاع بينه وبين النعمان","page":"ج17 ص187","text":"(فقد ذكرت به والركب حامله ... وردا يعلل أهل الشام والنيلا)\n(فما انتفاؤك منه بعدما جزعت ... هوج المطي به إبراق شمليلا)\n(قد قيل ذلك إن حقا وإن كذبا ... فما اعتذارك من شيء إذا قيلا)\n(فالحق بحيث رأيت الأرض واسعة ... وانشر بها الطرف إن عرضا وإن طولا)\nأما الشعر الذي فيه الغناء فإن الربيع بن زياد يقوله في مقتل مالك بن زهير وكان قتله في بعض تلك الوقائع التي يعرف مبدؤها بداحس والغبراء","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":24,"spl":"لبيد يحاول الإيقاع بينه وبين النعمان","tags":["أبي قيس بن الأسلت"],"loc":3044},
{"id":"b220-38","bab":"الجزء 17","sec":"حرب داحس والغبراء سبب الحرب","page":"ج17 ص191","text":"وكان السبب في ذلك فيما أخبرني به علي بن سليمان الأخفش ومحمد بن العباس اليزيدي قالا حدثنا أبو سعيد السكري عن محمد بن حبيب وأبي غسان دماذ عن أبي عبيدة وإبراهيم بن سعدان عن أبيه\nقال كان من حديث داحس أن أمه فرس كانت لقرواش بن عوف بن عاصم بن عبيد بن ثعلبة بن يربوع يقال لها جلوى وكان أبوه يسمى ذا العقال وكان لحوط بن أبي جابر بن أوس بن حميري بن رياح وإنما سمي داحسا لأن بني يربوع احتملوا ذات يوم سائرين في نجعه وكان ذو العقال مع ابنتي حوط بن أبي جابر بن أوس تجنبانه فمرتا به على جلوى فرس قرواش وديقا فلما\nرآها الفرس ودى وصهل فضحك شبان من الحي رأوه فاستحيت الفتاتان فأرسلتاه فنزا على جلوى فوافق قبولها فأقصت ثم أخذه لهما بعض الحي فلحق بهما حوط وكان رجلا شريرا سيىء الخلق فلما نظر إلى عين الفرس\nقال والله لقد نزا فرسي فأخبراني ما شأنه فأخبرتاه الخبر فقال يا آل رياح لا والله لا أرضى أبدا حتى أخرج ماء فرسي فقال له بنو ثعلبة والله ما استكرهنا فرسك إنما كان منفلتا فلم يزل الشر بينهما حتى عظم فلما رأى ذلك بنو ثعلبة قالوا دونكم ماء فرسكم فسطا عليها وأدخل يده في ماء وتراب ثم أدخلها في رحمها حتى ظن أنه قد أخرج الماء واشتملت الرحم على ما كان فيها فنتجها قرواش مهرا فسماه داحسا لذلك وخرج كأنه أبو ذو العقال وفيه يقول جرير\n(إن الجياد يبتن حول خبائنا ... من آل أعوج أو لذي العقال)\nأعوج فرس لبني هلال فلما تحرك المهر سام مع أمه وهو فلو يتبعها وبنو ثعلبة سائرون فرآه حوط فأخذه فقالت بنو ثعلبة يا بني رياح ألم تفعلوا فيه أول مرة ما فعلتم ثم هذا الآن فقالوا هو فرسنا ولن نترككم أو نقاتلكم عنه أو تدفعوه إلينا فلما رأى ذلك بنو ثعلبة قالوا إذا لا نقاتلكم عنه أنتم أعز علينا هو فداؤكم ودفعوه إليهم فلما رأى ذلك بنو رياح قالوا والله لقد ظلمنا إخوتنا مرتين ولقد حلموا\nوكرموا فأرسلوا به إليهم مع لقوحين فمكث عند قرواش ما شاء الله وخرج أجود خيول العرب ثم إن زهير بن قيس بن جذيمة العبسي أغار على بني يربوع فلم يصب أحدا غير ابنتي قرواش بن عوف ومائة من الإبل لقرواش وأصاب الحي وهم خلوف ولم يشهد من رجالهم غير غلامين من بني أزنم بن عبيد بن ثعلبة بن يربوع فجالا في متن الفرس مرتدفيه وهو مقيد بقيد من حديد فأعجلهما القوم عن حل قيده واتبعهما القوم فضبر بالغلامين ضبرا حتى نجوا به ونادتهما إحدى الجاريتين إن مفتاح القيد مدفون في مذود الفرس بمكان كذا وكذا أي بجنب مذود وهو مكان أي لا تنزلا عنه إلا في ذلك المكان فسبقا إليه حتى أطلقاه ثم كرا راجعين فلما رأى ذلك قيس بن زهير رغب في الفرس فقال لهما لكما حكمكما وادفعا إلي الفرس فقالا أو فاعل أنت\nقال نعم فاستوثقا منه على أن يرد ما أصاب من قليل وكثير ثم يرجع عوده على بدئه ويطلق الفتاتين ويخلي عن الإبل وينصرف عنهم راجعا فقل ذلك قيس فدفعا إليه الفرس فلما رأى ذلك أصحاب قيس قالوا لا نصالحك أبدا أصبنا مائة من الإبل وامرأتين فعمدت إلى غنيمتنا فجعلتها في فرس لك تذهب به دوننا فعظم في ذلك الشر حتى اشترى منهم غنيمتهم بمائة من الإبل فلما جاء قرواش قال للغلامين الأزنميين أين فرسي فأخبراه فأبى أن\nيرضى إلا أن يدفع إليه فرسه فعظم في ذلك الشر حتى تنافروا فيه فقضي بينهم أن ترد الفتاتان والإبل إلى قيس بن زهير ويرد عليه الفرس فلما رأى ذلك قرواش رضي بعد شر وانصرف قيس بن زهير ومعه داحس فمكث ما شاء الله وزعم بعضهم أن الرهان إنما هاجه بين قيس بن زهير وحذيفة بن بدر ابن عمرو بن جوية بن لوذان بن عدي بن فزارة بن ذبيان بن بغيض بن ريث بن غطفان بن سعد بن قيس بن عيلان بن مضر بن نزار - أن قيسا دخل على بعض الملوك وعنده قينة لحذيفة بن بدر تغنيه بقول امرىء القيس\n(دار لهند والرباب وفرتنى ... ولميس قبل حوادث الأيام)\nهن - فيما يذكر - نسوة من بني عبس فغضب قيس بن زهير وشق رداءها وشتمها فغضب حذيفة فبلغ ذلك قيسا فأتاه يسترضيه فوقف عليه فجعل يكلمه وهو لا يعرفه من الغضب وعنده أفراس له فعابها","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":25,"spl":"حرب داحس والغبراء سبب الحرب","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3045},
{"id":"b220-39","bab":"الجزء 17","sec":"حرب داحس والغبراء سبب الحرب","page":"ج17 ص191","text":"وقال ما يرتبط مثلك مثل هذه يا أبا مسهر فقال حذيفة أتعيبها قال نعم فتجاريا حتى تراهنا وقال بعض الرواة إن الذي هاج الرهان أن رجلا من بني عبد الله بن غطفان ثم أحد بني جوشن - وهم أهل بيت شؤم أتى حذيفة زائرا - ويقال إن الذي أتاه الورد العبسي أبو عروة بن الورد - قال فعرض عليه حذيفة خيله فقال ما أرى فيها جوادا مبرا والمبر الغالب قال ذو الرمة\n(أبر على الخصوم فليس خصم ... ولا خصمان يغلبه جدالا)\nفقال له حذيفة فعند من الجواد المبر فقال عند قيس بن زهير فقال له هل لك أن تراهنني عنه قال نعم قد فعلت فراهنه على ذكر من خيله وأنثى ثم إن العبدي أتى قيس بن زهير\nوقال إني قد راهنت عنك على فرسين من خيلك ذكر وأنثى وأوجبت الرهان فقال قيس ما أبالي من راهنت غير حذيفة فقال ما راهنت غيره فقال له قيس إنك ما علمت لأنكد ثم ركب قيس حتى أتى حذيفة فوقف عليه فقال له ما غدا بك\nقال غدوت لأواضعك الرهان قال بل غدوت لتغلقه قال ما أردت ذلك فأبى حذيفة إلا الرهان فقال قيس أخيرك ثلاث خلال فإن بدأت فاخترت قبلي فلي خلتان ولك الأولى وإن بدأت فاخترت قبلك فلك خلتان ولي الأولى\nقال حذيفة فابدأ قال قيس الغاية من مائة غلوة - والغلوة الرمية بالنشابة - قال حذيفة فالمضمار أربعون ليلة والمجرى من ذات الإصاد ففعلا ووضعا السبق على يدي غلاق او ابن غلاق أحد بني ثعلبة بن سعد بن ثعلبة فأما بنو عبس فزعموا أنه أجرى الخطار والحنفاء وزعمت بنو فزارة أنه أجرى قرزلا والحنفاء وأجرى قيس داحسا والغبراء ويزعم بعضهم أن الذي هاج الرهان أن رجلا من بني المعتمر بن قطيعة بن\nعبس يقال له سراقة راهن شابا من بني بدر - وقيس غائب - على أربع جزائر من خمسين غلوة فلما جاء قيس كره ذلك وقال له لم ينته رهان قط إلا إلى شر ثم أتى بني بدر فسألهم المواضعة فقالوا لا حتى نعرف سبقنا فإن أخذنا فحقنا وإن تركنا فحقنا فغضب قيس ومحك\nوقال أما إذ فعلتم فأعظموا الخطر وأبعدوا الغاية قالوا فذلك لك فجعلوا الغاية من واردات إلى ذات الإصاد وذلك مائة غلوة والثنية فيما بينهما وجعلوا القصبة في يدي رجل من بني ثعلبة بن سعد يقال له حصين ويقال رجل من بني العشراء من بني فزارة وهو ابن أخت لبني عبس وملؤوا البركة ماء وجعلوا السابق أول الخيل يكرع فيها ثم إن حذيفة بن بدر وقيس بن زهير أتيا المدى الذي أرسلن منه ينظران إلى الخيل كيف خروجها منه فلما أرسلت عارضاها فقال حذيفة خدعتك يا قيس\nقال ترك الخداع من أجرى من مائة فأرسلها مثلا ثم ركضا ساعة فجعلت خيل حذيفة تبر وخيل قيس تقصر فقال حذيفة سبقتك يا قيس فقال جري المذكيات غلاب فأرسلها مثلا ثم ركضا ساعة فقال حذيفة إنك لا تركض مركضا فأرسلها مثلا\nوقال سبقت خيلك يا قيس فقال قيس رويدا يعلون الجدد فأرسلها مثلا قال وقد جعل بنو فزارة كمينا بالثنية فاستقبلوا داحسا فعرفوه فأمسكوه وهو السابق ولم يعرفوا الغبراء وهي خلفه مصلية حتى مضت الخيل واستهلت من","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":26,"spl":"حرب داحس والغبراء سبب الحرب","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3046},
{"id":"b220-40","bab":"الجزء 17","sec":"حرب داحس والغبراء سبب الحرب","page":"ج17 ص191","text":"الثنية ثم أرسلوه فتمطر في آثارها أي أسرع فجعل يبدرها فرسا فرسا حتى سبقها إلى الغاية مصليا وقد طرح الخيل غير الغبراء ولو تباعدت الغاية لسبقها فاستقبلها بنو فزارة فلطموها ثم حلؤوها عن البركة ثم لطموا داحسا وقد جاءا متواليين وكان الذي لطمه عمير بن نضلة فجسأت يده فسمي جاسئا فجاء قيس وحذيفة في آخر الناس وقد دفعتهم بنو فزارة عن سبقهم ولطموا أفراسهم ولم تطقهم بنو عبس يقاتلونهم وإنما كان من شهد ذلك من بني عبس أبياتا غير كثيرة فقال قيس بن زهير يا قوم إنه لا يأتي قوم إلى قومهم شرا من الظلم فأعطونا حسنا فأبت بنو فزارة أن يعطوهم شيئا - وكان الخطر - عشرين من الإبل - فقالت بنو عبس أعطونا بعض سبقنا فأبوا فقالوا أعطونا جزورا ننحرها نطعمها أهل الماء فإنا نكره القالة في العرب فقال رجل من بني فزارة مائة جزور وجزور واحد سواء والله ما كنا لنقر لكم بالسبق علينا ولم نسبق فقام رجل من بني مازن بن فزارة فقال يا قوم إن قيسا كان كارها لأول هذا الرهان وقد أحسن في آخره وإن الظلم لا ينتهي إلا إلى الشر فأعطوه جزورا من نعمكم فأبوا فقام إلى جزور من إبله فعقلها ليعطيها قيسا ويرضيه فقام ابنه فقال إنك لكثير الخطأ أتريد أن تخالف قومك وتلحق بهم خزاية بما ليس عليهم فأطلق الغلام عقالها فلحقت بالنعم فلما رأى ذلك قيس بن زهير احتمل عنهم هو ومن معه من بني عبس فأتى على ذلك ما شاء الله","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":27,"spl":"حرب داحس والغبراء سبب الحرب","tags":["أبي قيس بن الأسلت"],"loc":3047},
{"id":"b220-41","bab":"الجزء 17","sec":"مقتل عوف بن بدر ومالك بن زهير","page":"ج17 ص198","text":"ثم إن قيسا أغار عليهم فلقي عوف بن بدر فقتله وأخذ إبله فبلغ ذلك بني فزارة فهموا بالقتال وغضبوا فحمل الربيع بن زياد أحد بني عوذ بن غالب بن قطيعة بن عبس دية عوف بن بدر مائة عشراء متلية العشراء التي أتى عليها من حملها عشرة أشهر من ملقحها والمتالي التي نتج بعضها والباقي يتلوها في النتاج وأم عوف وأم حذيفة ابنة نضلة بن جوية بن لوذان بن ثعلبة بن عدي بن فزارة واصطلح الناس فمكثوا ما شاء الله ثم إن مالك بن زهير أتى امرأة يقال لها مليكة بنت حارثة من بني عوذ بن فزارة فابتنى بها باللقاطة قريبا من الحاجر فبلغ ذلك حذيفة بن بدر فدس له فرسانا على أفراس من مسان خيله\nوقال لا تنظروا مالكا إن وجدتموه أن تقتلوه والربيع بن زياد بن عبد الله بن سفيان بن ناشب العبسي مجاور حذيفة بن بدر وكانت تحت الربيع بن زياد معاذة ابنة بدر فانطلق القوم فلقوا مالكا فقتلوه ثم انصرفوا عنه فجاؤوا عشية وقد جهدوا أفراسهم فوقفوا على حذيفة ومعه الربيع بن زياد فقال حذيفة أقدرتم على حماركم قالوا نعم وعقرناه فقال الربيع ما رأيت كاليوم قط أهلكت أفراسك من أجل حمار فقال حذيفة لما أكثر عليه من الملامة وهو يحسب أن الذي أصابوا حمارا إنا لم نقتل\nحمارا ولكنا قتلنا مالك بن زهير بعوف بن بدر فقال الربيع بئس لعمر الله القتيل قتلت أما والله إني لأظنه سيبلغ ما نكره فتراجعا شيئا من كلام ثم تفرقا فقام الربيع يطأ الأرض وطأ شديدا وأخذ يومئذ حمل بن بدر ذا النون سيف مالك بن زهير\nقال أبو عبيدة فزعموا أن حذيفة لما قام الربيع بن زياد أرسل إليه بمولدة له فقال لها اذهبي إلى معاذة بنت بدر امرأة الربيع فانظري ما ترين الربيع يصنع فانطلقت الجارية حتى دخلت البيت فاندست بين الكفاء والنضد - والكفاء شقة في آخر البيت والنضد متاع يجعل على حمار من خشب - فجاء الربيع فنفذ البيت حتى أتى فرسه فقبض بمعرفته ثم مسح متنه حتى قبض بعكوة ذنبه - العكوة أصل الذنب - ثم رجع إلى البيت ورمحه مركوز بفنائه فهزه هزا شديدا ثم ركزه كما كان ثم قال لامرأته اطرحي لي شيئا فطرحت له شيئا فاضطجع عليه وكانت قد طهرت تلك الليلة فدنت منه فقال إليك قد حدث أمر ثم تغنى وقال\n(نام الخلي وما أغمض حار ... من سيىء النبأ الجليل الساري)\n(من مثله تمسي النساء حواسرا ... وتقوم معولة مع الأسحار)\n(من كان مسرورا بمقتل مالك ... فليأت نسوتنا بوجه نهار)\n(يجد النساء حواسرا يندبنه ... يبكين قبل تبلج الأسحار)\n(قد كن يخبأن الوجوه تسترا ... فاليوم حين بدون للنظار)\n(يخمشن حرات الوجوه على امرىء ... سهل الخليقة طيب الأخبار)\n(أفبعد مقتل مالك بن زهير ... ترجو النساء عواقب الأطهار)\n(ما إن أرى في قتله لذوي الحجا ... إلا المطي تشد بالأكوار)\n(ومجنبات ما يذقن عذوفة ... يقذفن بالمهرات والأمهار)\nلعذوف والعدوف واحد وهو ما أكلته\n(ومساعرا صدأ الحديد عليهم فكأنما ... طلي الوجوه بقار)\n(يا رب مسرور بمقتل مالك ... ولسوف نصرفه بشر محار)\nرجعت المرأة فأخبرت حذيفة الخبر فقال هذا حين اجتمع أمر إخوتكم ووقعت الحرب وقال الربيع لحذيفة وهو يومئذ جاره سيرني فإني جاركم فسيره ثلاث ليال ومع الربيع فضلة من خمر فلما سار الربيع دس حذيفة في أثره فوارس فقال اتبعوه فإذا مضت ثلاث ليال فإن معه فضلة من خمر فإن وجدتموه قد أهراقها فهو جاد وقد مضى فانصرفوا وإن لم تجدوه قد أراقها فاتبعوه فإنكم تجدونه قد مال لأدنى منزل فرتع وشرب فاقتلوه فتبعوه فوجدوه قد شق الزق ومضى فانصرفوا فلما أتى الربيع قومه وقد كان بينه وبين قيس بن زهير شحناء وذلك أن الربيع ساوم قيس بن زهير في درع كانت عنده فلما نظر إليها وهو راكب وضعها بين يديه ثم ركض بها فلم يردها على قيس فعرض قيس لفاطمة ابنة الخرشب الأنمارية - من أنمار من بغيض وهي إحدى منجبات قيس وهي أم الربيع - وهي تسير في ظعائن من عبس فاقتاد جملها يريد أن يرتهنها بالدرع حتى يرد","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":28,"spl":"مقتل عوف بن بدر ومالك بن زهير","tags":["أبي قيس بن الأسلت"],"loc":3048},
{"id":"b220-42","bab":"الجزء 17","sec":"مقتل عوف بن بدر ومالك بن زهير","page":"ج17 ص198","text":"عليه فقالت ما رأيت كاليوم فعل رجل أي قيس ضل حلمك أترجو أن تصطلح أنت وبنو زياد وقد أخذت أمهم فذهبت بها يمينا وشمالا فقال الناس في ذلك ما شاؤوا وحسبك من شر سماعه فأرسلتها مثلا فعرف قيس بن زهير ما قالت له فخلى سبيلها وأطرد إبلا لبني زياد فقدم بها مكة فباعها من عبد الله بن جدعان بن عمرو بن كعب بن سعد بن تيم بن مرة القرشي وقال في ذلك قيس بن زهير\n(ألم يبلغك والأنباء تنمي ... بما لاقت لبون بني زياد)\n(ومحبسها على القرشي تشرى ... بأدراع وأسياف حداد)\n(كما لاقيت من حمل بن بدر ... وإخوته على ذات الإصاد)\n(هم فخروا علي بغير فخر ... وذادوا دون غايته جوادي)\n(وكنت إذا منيت بخصم سوء ... دلفت له بداهية نآدا)\n(بداهية تدق الصلب منه ... فتقصم أو تجوب عن الفؤاد)\n(وكنت إذا أتاني الدهر ربق ... بداهية شددت لها نجادي)\nلربق ما يتقلده\n(ألم تعلم بنو الميقاب أني ... كريم غير منغلث الزناد)\nلوقب الأحمق والميقاب التي تلد الحمقى والمنغلث الذي ليس بمنتقى\n(أطوف ما أطوف ثم آوي ... الى جار كجار أبي دواد)\nاره يعني ربيعة الخير بن قرط بن سلمة بن قشير وجار أبي دواد يقال له الحارث بن همام بن مرة بن ذهل بن شيبان وكان أبو دواد في جواره فخرج صبيان الحي يلعبون في غدير فغمس الصبيان ابن أبي دواد فيه فقتلوه فخرج الحارث فقال لا يبقى صبي في الحي إلا غرق في الغدير أو يرضى أبو دواد فودي ابن أبي دواد عشر ديات فرضي وهو قول أبي دواد\n(إبلي الإبل لا يحوزها الراعون ... ومج الندى عليها المدام)\nقال أبو سعيد حفظي لا يحوزها الراعي ومج الندى\n(إليك ربيعة الخير بن قرط وهوبا للطريف وللتلاد ... )\n(كفاني ما أخاف أبو هلال ... ربيعة فانتهت عني الأعادي)\n(تظل جياده يحدين حولي ... بذات الرمث كالحدإ الغوادي)\n(كأني إذ أنخت إلى ابن قرط ... عقلت إلى يلملم أو نضاد)\nوقال أيضا قيس بن زهير\n(إن تك حرب فلم أجنها ... جنتها خيارهم أو هم)\n(حذار الردى إذ رأوا خيلنا ... مقدمها سابح أدهم)\n(عليه كمي وسرباله ... مضاعفة نسجها محكم)\n(فإن شمرت لك عن ساقها ... فويها ربيع ولم يسأموا)\n(نهيت ربيعا فلم يزدجر ... كما انزجر الحارث الأضجم)\nال أبو عبد الله الحارث الأضجم رجل من بني ضبيعة بن ربيعة بن نزار وهو صاحب المرباع قال فكانت تلك الشحناء بين بني زياد وبين بني زهير فكان قيس يخاف خذلانهم إياه فزعموا أن قيسا دس غلاما له مولدا فقال انطلق كأنك تطلب إبلا فإنهم سيسألونك فذكر مقتل مالك ثم احفظ ما يقولون فأتاهم العبد فسمع الربيع يتغنى بقوله\n(أفبعد مقتل مالك بن زهير ... ترجو النساء عواقب الأطهار)\nلما رجع العبد إلى قيس فأخبره بما سمع من الربيع بن زياد عرف قيس أن قد غضب فاجتمعت بنو عبس على قتال بني فزارة فأرسلوا إليهم أن ردوا علينا إبلنا التي ودينا بها عوفا أخا حذيفة بن بدر لأمه فقال لا أعطيكم دية ابن أمي وإنما قتل صاحبكم حمل بن بدر وهو ابن الأسدية وأنتم وهو أعلم\nفزعم بعض الناس أنهم كانوا ودوا عوف بن بدر بمائة من الإبل متلية أي قد دنا نتاجها وأنه أتى على تلك الإبل أربع سنين وأن حذيفة بن بدر أراد أن يردها بأعيانها فقال له سنان بن خارجة المري أتريد أن تلحق بنا خزاية فنعطيهم أكثر مما أعطونا فتسبنا العرب بذلك فأمسكها حذيفة وأبى بنو عبس أن يقبلوا إلا إبلهم بعينها فمكث القوم ما شاء الله أن يمكثوا","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":29,"spl":"مقتل عوف بن بدر ومالك بن زهير","tags":["أبي قيس بن الأسلت"],"loc":3049,"partial":1},
{"id":"b220-43","bab":"الجزء 17","sec":"مقتل مالك بن بدر","page":"ج17 ص204","text":"ثم إن مالك بن بدر خرج يطلب إبلا له فمر على بني رواحة فرماه جندب - أحد بني رواحة - بسهم فقتله فقالت ابنة مالك بن بدر في ذلك\n(لله عينا من رأى مثل مالك ... عقيرة قوم أن جرى فرسان)\n(فليتهما لم يشربا قط قطرة ... وليتهما لم يرسلا لرهان)\n(أحل به من جندب أمس نذره ... فأي قتيل كان في غطفان)\n(إذا سجعت بالرقمتين حمامة ... أو الرس تبكي فارس الكتفان)\nفرس له كانت تسمى الكتفان ثم إن الأسلع بن عبد الله بن ناشب بن زيد بن هدم بن أد بن عوذ بن غالب بن قطيعة بن عبس مشى في الصلح ورهن بني ذبيان ثلاثة من بنيه وأربعة من بني أخيه حتى يصطلحوا جعلهم على يدي سبيع بن عمرو من بني ثعلبة بن سعد بن ذبيان فمات سبيع وهم عنده فلما حضرته الوفاة\nقال لابنه مالك بن سبيع إن عندك مكرمة لا تبيد إن أنت احتفظت بهؤلاء الأغيلمة وكأني بك لو قدمت قد أتاك حذيفة خالك - وكانت أم مالك هذا ابنة بدر - فعصر عينيه وقال هلك سيدنا ثم خدعك عنهم حتى\nتدفعهم إليه فيقتلهم فلا شرف بعدها فإن خفت ذلك فاذهب بهم إلى قومهم فلما ثقل جعل حذيفة يبكي ويقول هلك سيدنا فوقع ذلك له في قلب مالك فلما هلك سبيع أطاف بابنه مالك فأعظمه ثم\nقال له يا مالك إني خالك وإني أسن منك فادفع إلي هؤلاء الصبيان ليكونوا عندي إلى أن ننظر في أمرنا ولم يزل به حتى دفعهم إلى حذيفة باليعمرية واليعمرية ماء بواد من بطن نخل من الشربة لبني ثعلبة فلما دفع مالك إلى حذيفة الرهن جعل كل يوم يبرز غلاما فينصبه غرضا ويرمي بالنبل ثم يقول ناد أباك فينادي أباه حتى يمزقه النبل ويقول لواقد بن جنيدب ناد أباك فجعل ينادي يا عماه خلافا عليهم ويكره أن يأبس أباه بذلك - والأبس القهر والحمل على المكروه -\nوقال لابن جنيدب بن عمرو بن عبد الأسلع ناد جنيبة - وكان جنيبة لقب أبيه - فجعل ينادي يا عمراه باسم أبيه حتى قتل وقتل عتبة بن قيس بن زهير ثم إن بني فزارة اجتمعوا هم وبنو ثعلبة وبنو مرة فالتقوا هم وبنو عبس فقتلوا منهم مالك بن سبيع بن عمرو الثعلبي - قتله مروان بن زنباع العبسي - وعبد العزى بن حذار الثعلبي والحارث بن بدر الفزاري وهرم بن ضمضم المري - قتله ورد بن حابس العبسي ولم يشهد ذلك اليوم حذيفة بن بدر فقالت ناجية أخت هرم بن ضمضم المري\n(يا لهف نفسي لهفة المفجوع ... ألا أرى هرما على مودوع)\n(من أجل سيدنا ومصرع جنبه ... علق الفؤاد بحنظل مجدوع)\nودوع فرسه","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":30,"spl":"مقتل مالك بن بدر","tags":["أبي قيس بن الأسلت","اللهو والمزاح"],"loc":3050},
{"id":"b220-44","bab":"الجزء 17","sec":"بين ذبيان وعبس","page":"ج17 ص206","text":"ثم إن حذيفة بن بدر جمع وتأهب واجتمع معه بنو ذبيان بن بغيض فبلغ بني عبس أنهم قد ساروا إليهم فقال قيس أطيعوني فوالله لئن لم تفعلوا لأتكئن على سيفي حتى يخرج من ظهري قالوا فإنا نطيعك فأمرهم فسرحوا السوام والضعاف بليل وهم يريدون أن يظعنوا من منزلهم ذلك ثم ارتحلوا في الصبح وأصبحوا على ظهر العقبة وقد مضى سوامهم وضعفاؤهم فلما أصبحوا طلعت عليهم الخيل من الثنايا فقال قيس خذوا غير طريق المال فإنه لا حاجة للقوم أن يقعوا في شوكتكم ولا يريدون بكم في أنفسكم شرا من ذهاب أموالكم فأخذوا غير طريق المال فلما أدرك حذيفة الأثر ورآه\nقال أبعدهم الله وما خيرهم بعد ذهاب أموالهم فاتبع المال وسارت ظعن بني عبس والمقاتلة من ورائهم وتبع حذيفة وبنو ذبيان المال فلما أدركوه ردوه أوله على آخره ولم يفلت منهم شيء وجعل الرجل يطرد ما قدر عليه من الإبل فيذهب بها وتفرقوا واشتد الحرب فقال قيس بن زهير يا قوم إن القوم قد فرق بينهم المغنم فاعطفوا الخيل في آثارهم فلم تشعر بنو ذبيان إلا والخيل دوائس فلم يقاتلهم كبير أحد وجعل بنو ذبيان إنما همة الرجل في غنيمته أن يحوزها ويمضي بها\nفوضعت بنو عبس فيهم السلاح حتى ناشدتهم بنو ذبيان البقية ولم يكن لهم هم غير حذيفة فأرسلوا خيلهم مجتهدين في أثره وأرسلوا خيلا تقص الناس ويسألونهم حتى سقط خبر حذيفة من الجانب الأيسر على شداد بن معاوية العبسي وعمرو بن ذهل بن مرة بن مخزوم بن مالك بن غالب بن قطيعة العبسي وعمرو بن الأسلع والحارث بن زهير وقرواش بن هني بن أسيد بن جذيمة وجنيدب وكان حذيفة قد استرخى حزام فرسه فنزل عنه فوضع رجله على حجر مخافة أن يقتص أثره ثم شد الحزام فوقع صدر قدمه على الأرض فعرفوه وعرفوا حنف نفسه - والحنف أن تقبل إحدى اليدين على الأخرى وفي الناس أن تقبل إحدى الرجلين على الأخرى وأن يطأ الرجل وحشيهما وجمع الأحنف حنف - فاتبعوه ومضى حتى استغاث بجفر الهباءة وقد اشتد الحر فرمى بنفسه ومعه حمل بن بدر وحنش بن عمرو وورقاء بن بلال وأخوه - وهما من بني عدي بن فزارة - وقد نزعوا سروجهم وطرحوا سلاحهم ووقعوا في الماء وتمعكت دوابهم وقد بعثوا ربيئة فجعل يطلع فينظر فإذا لم ير شيئا رجع فنظر نظرة فقال إني قد رأيت شخصا كالنعامة أو كالطائر فوق القتادة من قبل مجيئنا فقال حذيفة هنا وهنا هذا شداد على جروة وجروة فرس شداد والمعنى دع ذكر شداد عن يمينك وعن شمالك واذكر غيره لما كان يخاف من شداد\nفبينا هم يتكلمون إذا هم بشداد بن معاوية واقفا عليهم فحال بينهم وبين الخيل ثم جاء عمرو بن الأسلع ثم جاء قرواش حتى تناموا خمسة فحمل جنيدب على خيلهم فاطردها وحمل عمرو بن الأسلع فاقتحم هو وشداد عليهم في الجفر فقال حذيفة يا بني عبس فأين العقول والأحلام فضربه أخوه حمل بن بدر بين كتفيه\nوقال اتق مأثور القول بعد اليوم فأرسلها مثلا وقتل قرواش بن هني حذيفة وقتل الحارث بن زهير حمل بن بدر وأخذ منه ذا النون سيف مالك بن زهير وكان حمل أخذه من مالك بن زهير يوم قتله فقال الحارث بن زهير في ذلك\n(تركت على الهباءة غير فخر ... حذيفة حوله قصد العوالي)\n(سيخبر عنهم حنش بن عمرو ... إذا لاقاهم وابنا بلال)\n(ويخبرهم مكان النون مني ... وما أعطيته عرق الخلال)\nلعرق المكافأة والخلال المودة يقول لم يعطوني السيف عن مكافأة ومودة ولكني قتلت وأخذت فأجابه حنش بن عمرو أخو بني ثعلبة بن سعد بن ذبيان\n(سيخبرك الحديث به خبير ... يجاهرك العداوة غير آلي)\n(بداءتها لقرواش وعمرو ... وأنت تجول جوبك في الشمال)\nلجوب الترس يقول بداءة الأمر لقرواش وعمرو بن الأسلع وهما اقتحما الجفر وقتلا من قتلا وأنت ترسك في يدك يجول لم تغن شيئا ويقال لك البداءة ولفلان العودة وقال قيس بن زهير\n(تعلم أن خير الناس ميت ... على جفر الهباءة ما يريم)\n(ولولا ظلمه ما زلت أبكي ... عليه الدهر ما طلع النجوم)\n(ولكن الفتى حمل بن بدر ... بغى والبغي مرتعه وخيم)\n(أظن الحلم دل علي قومي ... وقد يستجهل الرجل الحليم)\n(فلا تغش المظالم لن تراه ... يمتع بالغنى الرجل الظلوم)\n(ولا تعجل بأمرك واستدمه ... فما صلى عصاك كمستديم)\n(ألاقي من رجال منكرات ... فأنكرها وما أنا بالغشوم)\n(ولا يعييك عرقوب بلأي ... إذا لم يعطك النصف الخصيم)\n(ومارست الرجال ومارسوني ... فمعوج علي ومستقيم)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":31,"spl":"بين ذبيان وعبس","tags":["أبي قيس بن الأسلت"],"loc":3051},
{"id":"b220-45","bab":"الجزء 17","sec":"بين ذبيان وعبس","page":"ج17 ص206","text":"وله فما صلى عصاك كمستديم يقول عليك بالتأني والرفق وإياك والعجلة فإن العجول لا يبرم أمر أبدا كما أن الذي يثقف العود إذا لم يجد تصليته على النار لم يستقم له وقال في ذلك شداد بن معاوية العبسي\n(من يك سائلا عني فإني ... وجروة لا نرود ولا نعار)\n(مقربة النساء ولا تراها ... أمام الحي يتبعها المهار)\n(لها في الصيف آصرة وجل ... وست من كرائمها غزار)\nصرة حشيش وست أي ست أينق تسقى لبنها\n(ألا أبلغ بني العشراء عني ... علانية وما يغني السرار)\n(قتلت سراتكم وحسلت منكم ... حسيلا مثل ما حسل الوبار)\nسالة الناس وحفالتهم ورعاعهم وخمانهم وشرطهم وحثالتهم وخشارتهم وغثاؤهم واحد وهم السفلة يقول قتلت سراتكم وجعلتكم بعدهم حسالة كما خلقت الوبار حسالة وكان ذلك اليوم يوم ذي حسا ويزعم بعض بني فزارة أن حذيفة كان أصاب يومئذ فيمن أصاب من بني عبس تماضر ابنة الشريد السلمية أم قيس فقتلها وكانت في المال وقال\n(ولم أقتلكم سرا ولكن ... علانية وقد سطع الغبار)\n\n(جاء البريد بقرطاس يخب به ... فأوجس القلب من قرطاسه فزعا)\n(قلنا لك الويل ماذا في صحيفتكم ... قال الخليفة أمسى مثبتا وجعا)\nروضه من الكامل الشعر ليزيد بن معاوية والغناء لابن محرز هزج بالوسطى عن عمرو وهذا الشعر يقوله يزيد في علة أبيه التي مات فيها وكان يزيد يومئذ غازيا غزاة الصائفة","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":32,"spl":"بين ذبيان وعبس — يزيد وعنبسة في حضرة معاوية وهو يحتضر","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3052},
{"id":"b220-46","bab":"الجزء 17","sec":"خبر ليزيد بن معاوية","page":"ج17 ص211","text":"أخبرني علي بن سليمان الأخفش قال حدثني السكري والمبرد عن دماذ أبي غسان - واسمه رفيع بن سلمة - عن أبي عبيدة أن معاوية وجه جيشا إلى بلد الروم ليغزو الصائفة فأصابهم جدري فمات أكثر المسلمين وكان ابنه يزيد مصطبحا بدير مران مع زوجته أم كلثوم فبلغه خبرهم فقال\n(إذا ارتفقت على الأنماط مصطبحا ... بدير مران عندي أم كلثوم)\n(فما أبالي بما لاقت جنودهم ... بالغذقذونة من حمى ومن موم)\nبلغ شعره أباه فقال أجل والله ليلحقن بهم فليصيبنه ما أصابهم فخرج حتى لحق بهم وغزا حتى بلغ القسطنطينية فنظر إلى قبتين مبنيتين عليهما ثياب الديباج فإذا كانت الحملة للمسلمين ارتفع من إحداهما أصوات الدفوف والطبول والمزامير وإذا كانت الحملة للروم ارتفع من الأخرى فسأل يزيد عنهما فقيل له هذه بنت ملك الروم وتلك بنت جبلة بن الأيهم وكل واحدة منهما تظهر السرور بما تفعله عشيرتها فقال أما والله لأسرنها ثم صف العسكر وحمل حتى هزم الروم فأحجرهم في المدينة وضرب باب القسطنطينية بعمود حديد كان في يده فهشمه حتى انخرق فضرب عليه لوح من ذهب فهو عليه إلى اليوم نسخت من كتاب محمد بن موسى اليزيدي\nحدثني العباس بن ميمون طابع قال حدثني ابن عائشة عن أبيه وحدثني القحذمي أن ميسون بنت بحدل الكلبية كانت تزين يزيد بن معاوية وترجل جمته قال فإذا نظر إليه معاوية قال\n(فإن مات لم تفلح مزينة بعده ... فنوطي عليه يا مزين التمائما)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":32,"spl":"بين ذبيان وعبس — يزيد وعنبسة في حضرة معاوية وهو يحتضر","tags":["أبي قيس بن الأسلت","الجواري والنساء"],"loc":3053},
{"id":"b220-47","bab":"الجزء 17","sec":"يزيد وعنبسة في حضرة معاوية وهو يحتضر","page":"ج17 ص212","text":"فلما احتضر معاوية حضره يزيد بن معاوية وعنبسة بن أبي سفيان\nفبكى يزيد إلى عنبسة وقال\n(لو فات شيء يرى لفات أبو ... حيان لا عاجز ولا وكل)\n(الحول القلب الأريب ولن ... يدفع زوء المنية الحيل)\nفسمعهما معاوية بعد أن رددهما مرارا فقال يا بني إن أخوف ما أخاف على نفسي شيء صنعته قبل ذلك إني كنت أوضىء رسول الله فكساني قميصا وأخذت شعرا من شعره فإذا أنا مت فكفني قميصه واجعل الشعر في منخري وأذني وفمي وخل بيني وبين ربي لعل ذلك ينفعني شيئا\nقال العباس بن ميمون فقلت للقحذمي هذا غلط والدليل على ذلك أن أبا عدنان حدثني - وها هو حي فاسأله - عن الهيثم بن عدي عن ابن عياش عن الشعبي أن معاوية مات ويزيد بالصائفة فأتاه البريد بنعيه فأنشأ يقول\n(جاء البريد بقرطاس يخب به ... فأوجس القلب من قرطاسه فزعا)\n(قلنا لك الويل ماذا في صحيفتكم ... قال الخليفة أمسى مثبتا وجعا)\n(مادت بنا الأرض أو كادت تميد بنا ... كأن ما عز من أركانها انقلعا)\n(من لم تزل نفسه توفي على وجل ... توشك مقادير تلك النفس أن تقعا)\n(لما وردت وباب القصر منطبق ... لصوت رملة هد القلب فانصدعا)","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":32,"spl":"بين ذبيان وعبس — يزيد وعنبسة في حضرة معاوية وهو يحتضر","tags":["أبي قيس بن الأسلت"],"loc":3054},
{"id":"b220-48","bab":"الجزء 17","sec":"الضحاك بن قيس يتولى دفن معاوية","page":"ج17 ص213","text":"وكان الذي تولى غسله ودفنه الضحاك بن قيس فخطب الناس فقال\nإن ابن هند قد توفي وهذه أكفانه على المنبر ونحن مدرجوه فيها ومخلون بينه وبين ربه ثم هو البرزخ إلى يوم القيامة ولو كان يزيد حاضرا لم يكن للضحاك ولا غيره أن يفعل من هذا شيئا\nقال العباس فسكت القحذمي وما رد علي شيئا أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني عمي عن جدي عن هشام بن عروة عن أبيه\nقال صلى بنا عبد الله بن الزبير يوما ثم انفتل من الصلاة فنشج وكان قد نعي له معاوية ثم قال رحم الله معاوية إن كنا لنخدعه فيتخادع لنا وما ابن أنثى بأكرم منه وإن كنا لنعرفه يتفاوق لنا وما الليث المحرب بأجرأ منه كان والله كما قال بطحاء العذري\n(ركوب المنابر وثابها ... معن بخطبته يجهر)\n(تريع إليه عيون الكلام ... إذا حصر الهذر المهمر)\nكان والله كما قالت رقيقة أو قال بنت رقيقة\n(ألا أبكيه ألا أبكيه ... ألا كل الفتى فيه)\nالله لودي أنه بقي بقاء أبي قبيس لا يتخون له عقل ولا تنقص له قوة\nقال فعرفنا أن الرجل قد استوجس أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا ابن أبي سعد قال قال محمد بن إسحاق المسيبي حدثني جماعة من أصحابنا أن ابن عباس أتاه نعي معاوية وولاية يزيد وهو يعشي أصحابه ويأكل معهم وقد رفع إلى فيه لقمة فألقاها وأطرق هنيهة ثم\nقال جبل تدكدك ثم مال بجميعه في البحر واشتملت عليه الأبحر لله در ابن هند ما كان أجمل وجهه وأكرم خلقه وأعظم حلمه فقطع عليه الكلام رجل من أصحابه وقال أتقول هذا فيه فقال ويحك إنك لا تدري من مضى عنك ومن بقي عليك وستعلم ثم قطع الكلام\n(إذا زينب زارها أهلها ... حشدت وأكرمت زوارها)\n(وإن هي زارتهم زرتهم ... وإن لم أجد لي هوى دارها)\n(فسلمي لمن سالمت زينب ... وحربي لمن أشعلت نارها)\n(وما زلت أرعى لها عهدها ... ولم أتبع ساعة عارها)\nروضه من المتقارب الشعر لشريح القاضي في زوجته زينب بنت حدير التميمية والغناء لعمرو بن بانة ثاني ثقيل بالبنصر عنه على مذهب إسحاق وذكر إسحاق في كتاب الأغاني المنسوب إليه أنه لابن محرز","topic":"نسب أبي قيس بن الأسلت وأخباره","topicNo":220,"sp":33,"spl":"الضحاك بن قيس يتولى دفن معاوية","tags":["أبي قيس بن الأسلت"],"song":1,"loc":3055},
{"id":"b221-1","bab":"الجزء 17","sec":"ذكر شريح ونسبه وخبره","page":"ج17 ص216","text":"هو فيما أخبرني به الحسن بن علي الخفاف قال حدثنا الحارث بن أبي أسامة قال حدثنا أبو سعيد عن هشام بن السائب وأخبرني محمد بن خلف وكيع\nقال حدثني علي بن عبد الله بن معاوية بن ميسرة بن شريح كلاهما اتفق في الرواية لنسبه أنه شريح بن الحارث بن قيس بن الجهم بن معاوية بن عامر بن الرائش بن الحارث بن معاوية بن ثور بن مرتع الكندي\nقال هشام في خبره خاصة وليس بالكوفة من بني الرائش غيرهم وسائرهم من هجر وحضرموت وقد اختلف الرواة بعد هذا في نسبه فقال بعضهم شريح بن هانىء - وهذا غلط - ذاك شريح بن هانىء الحارثي واعتل من\nقال هذا بخبر روي عن مجالد عن الشعبي أنه قرأ كتابا من عمر إلى شريح من عبد الله عمر أمير المؤمنين إلى شريح بن هانىء وقد يجوز أن يكون كتب عمر رضي الله عنه هذا الكتاب إلى شريح بن هانىء الحارثي وقرأه الشعبي وكلا هذين الرجلين معروف والفرق بينهما النسب والقضاء فإن شريح بن هانىء لم يقض وشريح بن الحارث قد قضى لعمر بن الخطاب وعلي بن أبي طالب عليه السلام\nوقيل شريح بن عبد الله وشريح بن شراحيل والصحيح ابن الحارث وابنه أعلم به وقد أخبرنا وكيع قال حدثنا أحمد بن عمر بن بكير قال حدثني أبي\nعن الهيثم بن عدي عن أبي ليلى أن خاتم شريح كان نقشه شريح بن الحارث وقيل إنه من أولاد الفرس الذين قدموا اليمن مع سيف بن ذي يزن وعداده في كندة وقد روي عنه شبيه بذلك أخبرنا وكيع\nقال حدثنا عبد الله بن محمد الحنفي قال حدثنا عبدان قال حدثنا عبد الله بن المبارك قال حدثنا سفيان الثوري عن ابن أبي السفر عن الشعبي\nقال جاء أعرابي إلى شريح فقال ممن أنت قال أنا من الذين أنعم الله عليهم وعدادي في كندة قال وكيع وقال أبو حسان عن أيوب بن جابر عن أبي حصين\nقال كان شريح إذا قيل له ممن أنت قال ممن أنعم الله عليه بالإسلام عديد كندة قال وكيع وقيل إنما خرج إلى المدينة ثم إلى العراق لأن أمه تزوجت بعد أبيه فاستحيا وقد اختلف أيضا في سنه فقيل مائة وعشرون سنة\nوقيل مائة وعشر وقيل أقل من ذلك وأكثر فمن ذكر أنه عمر مائة وعشرين سنة أشعث بن سوار روى ذلك يحيى بن معين عن المحاربي عن أشعث وأبو سعيد الجعفي روى ذلك عنه أبو إبراهيم الزهري وممن قال أقل من ذلك أبو نعيم أخبرنا الحسن بن علي عن الحارث عن ابن سعد عن أبي نعيم قال بلغ شريح مائة وثمانين سنة","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":0,"spl":"ذكر شريح ونسبه وخبره — سنة وفاته — عمر بن الخطاب يستقضي شريحا","tags":["السفر والحج"],"loc":3056},
{"id":"b221-3","bab":"الجزء 17","sec":"سنة وفاته — عمر بن الخطاب يستقضي شريحا","page":"ج17 ص217 – ج17 ص218","text":"قال الحارث وأخبرني ابن سعد عن الواقدي عن أبي سبرة عن عيسى عن الشعبي قال توفي شريح في سنة ثمانين أو تسع وسبعين\nقال أبو سعيد وقال إبراهيم في سنة ست وسبعين وقال أبو إبراهيم الزهري عن أبي سعيد الجعفي إن شريحا مات في زمن عبد الملك بن مروان أخبرني وكيع قال حدثنا الكراني عن سهل عن الأصمعي قال ولد لشريح وهو ابن مائة سنة وروى إسماعيل بن أبان الوراق عن علي بن صالح قال قيل لشريح كيف أصبحت قال أصبحت ابن ست ومائة قضيت منها ستين سنة\nوأخبرني وكيع بخبر عمر حين استقضاه قال حدثنا عبد الله بن محمد بن أيوب قال حدثنا روح بن عبادة قال حدثنا شعبة قال سمعت سيارا قال سمعت الشعبي يقول إن عمر بن الخطاب رضي الله عنه أخذ من رجل فرسا على سوم فحمل عليه رجلا فعطب الفرس فقال عمر اجعل بيني وبينك رجلا فقال له الرجل اجعل بيني وبينك شريحا العراقي فقال يا أمير المؤمنين أخذته صحيحا سليما على سوم فعليك أن ترده كما أخذته\nقال فأعجبه ما قال وبعث به قاضيا ثم قال ما وجدته في كتاب الله فلا تسأل عنه أحدا وما لم تستبن في كتاب فالزم السنة فإن لم يكن في السنة فاجتهد رأيك\nأخبرني وكيع قال أخبرني عبد الله بن الحسن عن النميري عن حاتم بن قبيصة المهلبي عن شيخ من كنانة قال قال عمر لشريح حين استقضاه لا تشار ولا تضار ولا تشتر ولا تبع\nفقال عمرو بن العاص يا أمير المؤمنين\n(إن القضاة إن أرادوا عدلا ... وفصلوا بين الخصوم فصلا)\n(وزحزحوا بالحكم منهم جهلا ... كانوا كمثل الغيث صاب محلا)\nوله أخبار في قضايا كثيرة يطول ذكرها وفيها ما لا يستغنى عن ذكره منها محاكمة أمير المؤمنين علي عليه السلام إليه في الدرع","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":0,"spl":"ذكر شريح ونسبه وخبره — سنة وفاته — عمر بن الخطاب يستقضي شريحا","tags":["الموت"],"loc":3057},
{"id":"b221-4","bab":"الجزء 17","sec":"شريح يقضي بين علي ويهودي أخذ درعه","page":"ج17 ص219","text":"حدثني به عبد الله بن محمد بن إسحاق ابن أخت داهر بن نوح بالأهواز قال حدثنا أبو الأشعث أحمد بن المقدام العجلي قال حدثني حكيم بن حزام عن الأعمش عن إبراهيم التيمي\nقال عرف علي صلوات الله عليه درعا مع يهودي فقال يا يهودي درعي سقطت مني يوم كذا وكذا فقال اليهودي ما أدري ما تقول درعي وفي يدي بيني وبينك قاضي المسلمين فانطلقا إلى شريح فلما رآه شريح قام له عن مجلسه فقال له علي اجلس فجلس شريح ثم\nقال إن خصمي لو كان مسلما لجلست معه بين يديك ولكني سمعت رسول الله يقول لا تساووهم في المجلس ولا تعودوا مرضاهم ولا تشيعوا جنائزهم واضطروهم إلى أضيق الطرق وإن سبوكم فاضربوهم وإن ضربوكم فاقتلوهم ثم\nقال درعي عرفتها مع هذا اليهودي فقال شريح لليهودي ما تقول قال درعي وفي يدي قال شريح صدقت والله يا أمير المؤمنين إنها لدرعك كما قلت ولكن لا بد من شاهد فدعا قنبرا فشهد له ودعا الحسن بن علي فشهد له فقال أما شهادة مولاك فقد قبلتها وأما شهادة ابنك لك فلا فقال علي سمعت عمر بن الخطاب يقول سمعت رسول الله يقول إن الحسن والحسين سيدا شباب\nأهل الجنة قال اللهم نعم قال أفلا تجيز شهادة أحد سيدي شباب أهل الجنة والله لتخرجن إلى بانقيا فلتقضين بين أهلها أربعين يوما ثم سلم الدرع إلى اليهودي فقال اليهودي أمير المؤمنين مشى معي إلى قاضيه فقضى عليه فرضي به صدقت إنها لدرعك سقطت منك يوم كذا وكذا عن جمل أورق فالتقطتها وأنا أشهد أن لا إله إلا الله وأن محمدا رسول الله فقال علي عليه السلام هذه الدرع لك وهذه الفرس لك وفرض له في تسعمائة فلم يزل معه حتى قتل يوم صفين","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":1,"spl":"شريح يقضي بين علي ويهودي أخذ درعه","tags":["الرواية والكتابة"],"loc":3058},
{"id":"b221-5","bab":"الجزء 17","sec":"خبر زينب بنت حدير وتزويج شريح إياها","page":"ج17 ص221","text":"أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن زهير بن حرب قال حدثنا أبو همام الوليد بن شجاع قال حدثنا ابن أبي زائدة وأبو محمد رجل ثقة\nقال حدثنا مجالد عن الشعبي قال قال لي شريح يا شعبي عليكم بنساء بني تميم فإنهن النساء قال قلت وكيف ذاك قال انصرفت من جنازة ذات يوم مظهرا فمررت بدور بني تميم فإذا امرأة جالسة في سقيفة على وسادة وتجاهها جارية رؤد - يعني التي قد بلغت - ولها ذؤابة على ظهرها جالسة على وسادة فاستسقيت فقالت لي أي الشراب أعجب إليك النبيذ أم اللبن أم الماء\nقلت أي ذلك يتيسر عليكم قالت اسقوا الرجل لبنا فإني إخاله غريبا فلما شربت نظرت إلى الجارية فأعجبتني فقلت من هذه قالت ابنتي قلت وممن قالت زينب بنت حدير إحدى نساء بني تميم ثم إحدى نساء بني حنظلة ثم إحدى نساء بني طهية قلت أفارغة أم مشغولة قالت بل فارغة قلت أتزوجينيها قالت نعم إن كنت كفيا ولها عم فاقصده\nفانصرفت فامتنعت من القائلة فأرسلت إلى إخواني القراء الأشراف مسروق بن الأجدع والمسيب بن نجبة وسليمان بن صرد الخزاعي وخالد بن عرفطة العذري وعروة بن المغيرة بن شعبة وأبي بردة بن أبي موسى فوافيت معهم صلاة العصر فإذا عمها جالس فقال أبا أمية حاجتك\nقلت إليك قال وما هي قلت ذكرت لي بنت أخيك زينب بنت حدير قال ما بها عنك رغبة ولا بك عنها مقصر وإنك لنهزة فتكلمت فحمدت الله جل ذكره وصليت على النبي وذكرت حاجتي فرد الرجل علي وزوجني وبارك القوم لي ثم نهضنا فما بلغت منزلي حتى ندمت فقلت تزوجت إلى أغلظ العرب وأجفاها فهممت بطلاقها ثم\nقلت أجمعها إلي فإن رأيت ما أحب وإلا طلقتها فأقمت أياما ثم أقبل نساؤها يهادينها فلما أجلست في البيت أخذت بناصيتها فبركت وأخلى لي البيت فقلت يا هذه إن من السنة إذا دخلت المرأة على الرجل أن يصلي ركعتين وتصلي ركعتين ويسألا الله خير ليلتهما ويتعوذا\nبالله من شرها فقمت أصلي ثم التفت فإذا هي خلفي فصليت ثم التفت فإذا هي على فراشها فمددت يدي فقالت لي على رسلك فقلت إحدى الدواهي منيت بها فقالت إن الحمد لله أحمده وأستعينه إني امرأة غريبة ولا والله ما سرت مسيرا قط أشد علي منه وأنت رجل غريب لا أعرف أخلاقك فحدثني بما تحب فآتيه وما تكره فأنزجر عنه فقلت الحمد لله وصلى الله على محمد قدمت خير مقدم قدمت على أهل دار زوجك سيد رجالهم وأنت سيدة نسائهم أحب كذا وأكره كذا قالت\nأخبرني عن أختانك أتحب أن يزوروك فقلت إني رجل قاض وما أحب أن تملوني قال فبت بأنعم ليلة وأقمت عندها ثلاثا ثم خرجت إلى مجلس القضاء فكنت لا أرى يوما إلا هو أفضل من الذي قبله حتى إذا كان عند رأس الحول دخلت منزلي فإذا عجوز تأمر وتنهى\nقلت يا زينب من هذه فقالت أمي فلانة قلت حياك الله بالسلام قالت أبا أمية كيف أنت وحالك قلت بخير أحمد الله قالت أبا أمية كيف زوجك قلت كخير امرأة قالت إن المرأة لا ترى في حال أسوأ خلقا منها في حالين إذا حظيت عند زوجها وإذا ولدت غلاما فإن رابك منها ريب فالسوط فإن الرجال والله ما حازت إلى بيوتها شرا من الورهاء المتدللة قلت أشهد أنها ابنتك قد كفيتنا الرياضة وأحسنت الأدب قال فكانت في كل حول تأتينا فتذكر هذا ثم تنصرف","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":2,"spl":"خبر زينب بنت حدير وتزويج شريح إياها","tags":["الجواري والنساء","الخمر","الرواية والكتابة"],"loc":3059},
{"id":"b221-6","bab":"الجزء 17","sec":"شريح يعالج زينب","page":"ج17 ص223","text":"قال شريح فما غضبت عليها قط إلا مرة كنت لها ظالما فيها وذاك أني\nكنت أمام قومي فسمعت الإقامة وقد ركعت ركعتي الفجر فأبصرت عقربا فعجلت عن قتلها فأكفأت عليها الإناء فلما كنت عند الباب قلت يا زينب لا تحركي الإناء حتى أجيء فعجلت فحركت الإناء فضربتها العقرب فجئت فإذا هي تلوى فقلت مالك قالت لسعتني العقرب فلو رأيتني يا شعبي وأنا أعرك أصبعها بالماء والملح وأقرأ عليها المعوذتين وفاتحة الكتاب وكان لي يا شعبي جار يقال له ميسرة بن عرير من الحي فكان لا يزال يضرب امرأته فقلت\n(رأيت رجالا يضربون نساءهم ... فشلت يميني يوم أضرب زينبا)\nا شعبي فوددت أني قاسمتها عيشي ومما يغنى فيه من الأشعار التي قالها شريح في امرأته زينب\n(رأيت رجالا يضربون نساءهم ... فشلت يميني يوم أضرب زينبا)\n(أأضربها في غير جرم أتت به ... إلي فما عذري إذا كنت مذنبا)\n(فتاة تزين الحلي إن هي حليت ... كأن بفيها المسك خالط محلبا)\nالغناء ليونس الكاتب من كتابه غير مجنس\n(أمن رسم دار مربع ومصيف ... لعينك من ماء الشؤون وكيف)\n(تذكرت فيها الجهل حتى تبادرت ... دموعي وأصحابي علي وقوف)\nعروضه من مصرع الطويل الشعر للحطيئة من قصيدة يمدح بها سعيد ابن العاص لما ولي الكوفة لعثمان والغناء لابن سريج رمل بالوسطى عن عمرو","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":3,"spl":"شريح يعالج زينب","tags":[],"song":2,"loc":3060},
{"id":"b221-7","bab":"الجزء 17","sec":"أخبار الحطيئة مع سعيد بن العاص","page":"ج17 ص226","text":"أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد عن أبيه قال لقيني إياس بن الحطيئة فقال لي يا أبا عثمان مات أبي وفي كسر بيته عشرون ألفا أعطاه إياها أبوك وقال فيه خمس قصائد فذهب والله ما أعطيتمونا وبقي ما أعطيناكم فقلت صدقت والله قال أبو زيد فمما قال فيه قوله\n(أمن رسم دار مربع ومصيف ... لعينك من ماء الشؤون وكيف)\n(إليك سعيد الخير جبت مهامها ... يقابلني آل بها وتنوف)\n(ولولا أصيل اللب غض شبابه ... كريم لأيام المنون عروف)\n(إذا هم بالأعداء لم يثن همه ... كعاب عليها لؤلؤ وشنوف)\n(حصان لها في البيت زي وبهجة ... ومشي كما تمشي القطاة قطوف)\n(ولو شاء وارى الشمس من دون وجهه ... حجاب ومطوي السراة منيف)\nخبرنا محمد بن العباس اليزيدي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم الطائي عن خالد بن سعيد بن العاص عن أبيه\nقال كان سعيد بن العاص في المدينة زمن معاوية وكان يعشي الناس فإذا فرغ من العشاء قال الآذن أجيزوا إلا من كان من أهل سمرة قال فدخل الحطيئة فتعشى مع الناس ثم أقبل فقال الآذن أجيزوا حتى انتهى إلى الحطيئة فقال أجز فأبى فأعاد عليه فأبى فلما رأى سعيد إباءه\nقال دعه وأخذ في الشعر والحطيئة مطرق لا ينطق فقال الحطيئة والله ما أصبتم جيد الشعر ولا شاعر الشعراء قال سعيد من أشعر العرب يا هذا فقال الذي يقول\n(لا أعد الإقتار عدما ولكن ... فقد من قد رزئته الإعدام)\n(من رجال من الأقارب بانوا ... من جذام هم الرؤوس الكرام)\n(سلط الموت والمنون عليهم ... فلهم في صوى المقابر هام)\n(وكذاكم سبيل كل أناس ... سوف حقا تبليهم الأيام)\nقال ويحك من يقول هذا الشعر قال أبو دواد الإيادي قال أو ترويه قال نعم قال فأنشدنيه فأنشدته الشعر كله قال ومن الثاني قال الذي يقول\n(أفلح بما شئت فقد يبلغ بالضعف ... وقد يخدع الأريب)\nال ومن يقول هذا قال عبيد قال أو ترويه قال نعم قال فأنشدنيه فأنشده ثم قال له ثم من قال والله لحسبك بي عند رهبة أو رغبة إذا وضعت إحدى رجلي على الأخرى ثم رفعت عقيرتي بالشعر ثم عويت على أثر القوافي عواء الفصيل الصادر عن الماء\nقال ومن أنت قال الحطيئة قال ويحك قد علمت تشوقنا إلى مجلسك وأنت تكتمنا نفسك منذ الليلة قال نعم لمكان هذين الكلبين عندك وكان عنده كعب بن جعيل وأخوه وكان عنده سويد بن مشنوء النهدي حليف بني عدي بن جناب الكلبيين فأنشده الحطيئة قوله\n(ألست بجاعلي كابني جعيل ... هداك الله أو كابني جناب)\n(أدب فلا أقدر أن تراني ... ودونك بالمدينة ألف باب)\n(وأحبس بالعراء المحل بيتي ... ودونك عازب ضخم الذباب)\nالعازب الكلأ الذي لم يرع وقد التف نبته فقال له سعيد لعمر الله لأنت أشعر عندي منهم فأنشدني فأنشده\n(سعيد وما يفعل سعيد فإنه ... نجيب فلاه في الرباط نجيب)\n(سعيد فلا يغررك قلة لحمه ... تخدد عنه اللحم فهو صليب)\nيروى خفة لحمه\n(إذا غاب عنا غاب عنا ربيعنا ... ونسقى الغمام الغر حين يؤوب)\n(فنعم الفتى تعشو إلى ضوء ناره ... إذا الريح هبت والمكان جديب)\nفأمر له بعشرة آلاف درهم ثم عاد فأنشده قصيدته التي يقول فيها\n(أمن رسم دار مربع ومصيف ... )\nقول فيها\n(إذا هم بالأعداء لم يثن عزمه ... كعاب عليها لؤلؤ وشنوف)\nأعطاه عشرة آلاف أخرى أخبرني محمد بن الحسن بن دريد قال أخبرنا أبو حاتم عن أبي عبيدة بهذا الحديث نحو ما رواه خالد بن سعيد وزاد فيه فانتهى الشرط إلى الحطيئة فرأوه أعرابيا قبيح الوجه كبير السن سيىء الحال رث الهيئة فأرادوا أن يقيموه فأبى أن يقوم وحانت من سعيد التفاتة فقال دعوا الرجل وباقي الخبر مثله","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":4,"spl":"أخبار الحطيئة مع سعيد بن العاص","tags":["اللهو والمزاح"],"loc":3061,"partialRef":{"sid":"b221-6","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b221-8","bab":"الجزء 17","sec":"الحطيئة وخالد بن سعيد بن العاص","page":"ج17 ص229","text":"قال أبو عبيدة في هذا الخبر وأخبرني رجل من بني كنانة قال أقبل الحطيئة في ركب من بني عبس حتى قدم المدينة فأقام مدة ثم قال له من في رفقته إنا قد أرذينا وأخلينا فلو تقدمت إلى رجل شريف من أهل هذه القرية فقرانا وحملنا فأتى خالد بن سعيد بن العاص فسأله فاعتذر إليه وقال ما\nعندي شيء فلم يعد عليه الكلام وخرج من عنده فارتاب به خالد فبعث يسأل عنه فأخبر أنه الحطيئة فرده فأقبل الحطيئة فقعد لا يتكلم فأراد خالد أن يستفتحه الكلام فقال من أشعر الناس فقال الذي يقول\n(ومن يجعل المعروف من دون عرضه ... يفره ومن لا يتق الشتم يشتم)\nقال خالد لبعض جلسائه هذه بعض عقاربه وأمر بكسوة وحملان فخرج بذلك من عنده\n(حبذا ليلتي بتل بونى ... حين نسقى شرابنا ونغنى)\n(إذ رأينا جواريا عطرات ... وغناء وقرقفا فنزلنا)\n(ما لهم لا يبارك الله فيهم ... إذ يسألون ويحنا ما فعلنا)\nروضه الضرب الأول من الخفيف الشعر لمالك بن أسماء بن خارجة والغناء لحنين رمل مطلق في مجرى البنصر عن إسحاق","topic":"ذكر شريح ونسبه وخبره","topicNo":221,"sp":5,"spl":"الحطيئة وخالد بن سعيد بن العاص","tags":["الجواري والنساء"],"song":1,"loc":3062},
{"id":"b222-2","bab":"الجزء 17","sec":"أخبار مالك بن أسماء بن خارجة ونسبه — مالك يكتب لأبيه يسأله شفاعة الحجاج","page":"ج17 ص231 – ج17 ص233","text":"هو مالك بن أسماء بن خارجة بن حصن بن حذيفة بن بدر الفزاري وقد مضى هذا النسب في أخبار عويف القوافي وقد مضت أخباره وذكر هذا البيت من فزارة وشرفه فيها وسائر قصصه هناك وكان الحجاج بن يوسف ولى مالك بن أسماء بعد أن تزوج أخته هندا بأصبهان بعد حبس طويل في خيانة ظهرت عليه ثم خلاه بعد ذلك وطالت أيامه بأصبهان فظهرت عليه خيانة أخرى فحبسه وناله بكل مكروه\nأخبرني بخبره أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن عبد الرحمن بن عيسى بن موسى قال حدثني هشام بن محمد الهلالي\nقال اختلف الحجاج وهند بنت أسماء زوجته في وقعة بنات قين فبعث إلى مالك بن أسماء بن خارجة فأخرجه من السجن وكان محبوسا بمال عليه للحجاج فسأله عن الحديث فحدثه به ثم أقبل على هند فقال قومي إلى أخيك فقالت لا أقوم إليه وأنت ساخط عليه فأقبل الحجاج عليه فقال إنك والله ما علمت للخائن أمانته اللئيم حسبه الزاني فرجه فقال إن أذن لي الأمير تكلمت\nقال قل قال أما قول الأمير الزاني فرجه فوالله لأنا أحقر عند الله عز و جل وأصغر في عين الأمير من أن يجب لله علي حد فلا يقيمه وأما قوله اللئيم حسبه فوالله لو علم الأمير مكان رجل أشرف مني لم يصاهرني وأما قوله إني خؤون فلقد ائتمنني فوفرت فأخذني بما أخذني به فبعت ما كان وراء ظهري ولو ملكت الدنيا بأسرها لافتديت بها من مثل هذا الكلام\nقال فنهض الحجاج وقال شأنك يا هند بأخيك قال مالك بن أسماء فوثبت هند إلي فأكبت علي ودعت بالجواري ونزعن عني حديدي وأمرت بي إلى الحمام وكستني وانصرفت فلبثت أياما ثم دخلت على الحجاج وبين يديه عهود وفيها عهدي على أصبهان\nقال خذ هذا العهد وامض إلى عملك فأخذته ونهضت قال وهي ولايته التي عزله عنها وبلغ به ما بلغ من الشر قال أبو زيد ويقال إنه كان في الحبس في الدفعة الثانية مضيقا عليه في كل أحواله حتى كان يشاب له الماء الذي كان يشربه بالرماد والملح فاشتاق الحجاج\nإلى حديثه يوما فأرسل إليه فأحضر فبينا هو يحدثه إذا استسقى ماء فأتي به فلما نظر إليه الحجاج قال لا هات ماء السجن فأتي به وقد خلط بالملح والرماد فسقيه قال ويقال إنه هرب من الحبس فلم يزل متواريا حتى مات الحجاج قال وكتب إليه بعض أهله أن يمضي إلى الشام فيستجير ببعض بني أمية حتى يأمن ثم يعود إلى مصره\nوقد كان خالد بن عتاب الرياحي فعل ذلك واستجار بزفر بن الحارث الكلابي فأجاره فراجعه عبد الملك في أمره ثم أجاره فكتب مالك إلى أبيه يسأله أن يدخل إلى الحجاج ويسأله في أمره فقال أسماء في ذلك\n(أبني فزارة لا تعنوا شيخكم ... ما لي وما لزيارة الحجاج)\n(شبهته شبلا غداة لقيته ... يلقي الرؤوس شواخب الأوداج)\n(تجري الدماء على النطاع كأنها ... راح شمول غير ذات مزاج)\n(لا تطلبوا حاجا إليه فإنه ... بئس المؤمل في طلاب الحاج)\n(يا ليت هندا أصبحت مرموسة ... أوليتها جلست عن الأزواج)\nال أبو زيد فأما خبر خالد بن عتاب الرياحي فإن الحجاج كان استعمله على الري وكانت أمه أم ولد فكتب إليه الحجاج يلخن أمه ويقول يابن اللخناء أنت الذي هربت عن أبيك حتى قتل وقد كان حلف ألا يسب أحد أمه إلا أجابه كائنا من كان فكتب إليه خالد كتبت إلي تلخنني وتزعم أني فررت عن أبي حتى قتل ولعمري لقد فررت عنه ولكن بعد أن قتل وحين لم أجد لي مقاتلا ولكن\nأخبرني عنك يا بن اللخناء المستفرمة بعجم زبيب الطائف حين فررت أنت وأبوك يوم الحرة على جمل ثفال أيكما كان أمام صاحبه فقرأ الحجاج الكتاب وقال صدق\n(أنا الذي فررت يوم الحره ... ثم ثنيت كرة بفره)\n(والشيخ لا يفر إلا مره ... )\nم طلبه وهرب إلى الشام وسلم بيت المال ولم يأخذ منه شيئا","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":0,"spl":"أخبار مالك بن أسماء بن خارجة ونسبه — مالك يكتب لأبيه يسأله شفاعة الحجاج","tags":["الحب والغزل","الجواري والنساء"],"loc":3063,"partial":1},
{"id":"b222-3","bab":"الجزء 17","sec":"زفر بن الحارث يجير خالد بن عتاب","page":"ج17 ص235","text":"وكتب الحجاج إلى عبد الملك بما كان منه وقدم خالد الشام فسأل عن خاصة عبد الملك فقيل له روح بن زنباع فأتاه حين طلعت الشمس فقال إني جئتك مستجيرا فقال إنني قد أجرتك إلا أن تكون خالدا\nقال فإني خالد فتغير وقال أنشدك الله إلا خرجت عني فإني لا آمن عبد الملك فقال أنظرني حتى تغرب الشمس فجعل روح يراعيها حتى خرج خالد فأتى زفر بن الحارث الكلابي فقال إني جئتك مستجيرا\nقال قد أجرتك قال أنا خالد بن عتاب قال وإن كنت خالدا فلما أصبح دعا بنين له فتهادى بينهما وقد أسن فدخل على عبد الملك وقد أذن للناس فلما رآه دعا له بكرسي فجعل عند فراشه فجلس ثم\nقال يا أمير المؤمنين إني قد أجرت عليك رجلا فأجره قال قد أجرته إلا أن يكون خالدا قال فهو خالد قال لا ولا كرامة فقال زفر لابنيه أنهضاني فلما ولى\nقال يا عبد الملك أما والله لو كنت تعلم أن يدي تطيق حمل القناة ورأس الجواد لأجرت من أجرت فضحك وقال يا أبا الهذيل قد أجرناه فلا أرينه وأرسل إلى خالد بألفي درهم فأخذها ودفع إلى رسوله أربعة آلاف درهم","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":1,"spl":"زفر بن الحارث يجير خالد بن عتاب","tags":["اللهو والمزاح","السفر والحج"],"loc":3064},
{"id":"b222-4","bab":"الجزء 17","sec":"رجع الخبر إلى حديث مالك بن أسماء","page":"ج17 ص236","text":"أخبرني علي بن سليمان الأخفش قال أخبرنا محمد بن يزيد النحوي وأخبرنا إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قالا عشق مالك بن أسماء جارية لأخته هند وعشقها أخوه عيينة بن أسماء بن خارجة فاستعان بأخيها مالك وهو لا يعلم ما يجد بها يشكو إليه حبها فقال مالك\n(أعيين هلا إذ كلفت بها ... كنت استغثت بفارغ العقل)\n(أرسلت تبغي الغوث من قبلي ... والمستغاث إليه في شغل)\nال ابن قتيبة خاصة وهوي مالك بن أسماء جارية من بني أسد وكانت تنزل دارا من قصب وكانت دار مالك في بني أسد دارا سرية مبنية بالجص والآجر فقال\n(يا ليت لي خصا يجاورها ... بدلا بداري في بني أسد)\n(الخص فيه تقر أعيننا ... خير من الآجر والكمد)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي ويعقوب بن عيسى وأخبرني علي بن صالح بن الهيثم قال حدثنا أبو هفان عن إسحاق الموصلي عن الزبير أن عمر بن أبي ربيعة رأى مالك بن أسماء قال أبو هفان في خبره وهو يطوف بالبيت وقد بهر الناس جماله وكماله فأعجب عمر ما رأى منه فسأل عنه فعرفه فعانقه وسلم عليه وقال له أنت أخي حقا فقال له مالك ومن أنا ومن أنت فقال أما أنا فستعرفني وأما أنت فالذي تقول\n(إن لي عند كل نفحة بستان ... من الورد أو من الياسمينا)\n(نظرا والتفاتة أترجى ... أن تكوني حللت فيما يلينا)\nنت فيه علية بنت المهدي خفيف رمل بالوسطى وقال أبو هفان في حديثه قال له عمر ما زلت أحبك منذ سمعت هذا الشعر لك فقال له مالك أنت عمر بن أبي ربيعة قال نعم قال الزبير في خبره خاصة وحدثني ابن أبي كناسة أن عمر لما لقي مالكا استنشده فأنشده مالك شيئا من شعره فقال له عمر ما أحسن شعرك لولا أسماء القرى التي تذكرها فيه قال مثل ماذا قال مثل قولك\n(إن في الرفقة التي شيعتنا ... بجوير سما لزين الرفاق)\nمثل قولك\n(أشهدتنا أم كنت غائبة ... عن ليلتي بحديثة القسب)\nمثل قولك\n(حبذا ليلتي بتل بونى ... حين نسقى شرابنا ونغنى)\nقال له مالك هي قرى البلد الذي أنا فيه وهو مثل ما تذكره في شعرك من أرض بلادك قال مثل ماذا قال مثل قولك\n(حي المنازل قد دثرن خرابا ... بين الجوين وبين ركن كسابا)\nمثل قولك\n(ما على الرسم بالبليين لو بين ... رجع السلام أو لو أجابا)\nأمسك عنه عمر بن أبي ربيعة ومالك بن أسماء الذي يقول\n(وحديث ألذه هو مما ... ينعت الناعتون يوزن وزنا)\n(منطق صائب وتلحن أحيانا ... وأحلى الحديث ما كان لحنا)\nأخبرني يحيى بن علي بن يحيى المنجم قال حدثني أبي قال قلت للجاحظ إني قرأت في فصل من كتابك المسمى بكتاب البيان والتبيين إنما يستحسن من النساء اللحن في الكلام واستشهدت ببيتي مالك بن أسماء - يعني هذين البيتين -\nقال هو كذاك فقال أما سمعت بخبر هند ابنة أسماء بن خارجة مع الحجاج حين لحنت في كلامه فعاب ذلك عليها فاحتجت ببيتي أخيها فقال لها إن أخاك أراد أن المرأة فطنة فهي تلحن بالكلام إلى غير الظاهر بالمعنى لتستر معناه وتوري عنه وتفهمه من أرادت بالتعريض كما قال الله عز و جل ( ولتعرفنهم في لحن القول\nولم يرد الخطأ من الكلام والخطأ لا يستحسن من أحد فوجم الجاحظ ساعة ثم قال\nلو سقط إلي هذا الخبر أولا لما قلت ما تقدم فقلت له فأصلحه فقال الآن وقد سار به الكتاب في الآفاق وهذا لا يصلح أو كلاما نحو ما ذكرنا فإن أبا أحمد أخبرنا به على سبيل المذاكرة فحفظته عنه","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":2,"spl":"رجع الخبر إلى حديث مالك بن أسماء","tags":[],"loc":3065},
{"id":"b222-5","bab":"الجزء 17","sec":"المتوكل يبتاع تل بونى","page":"ج17 ص239","text":"أخبرني الحسين بن يحيى وجعفر بن قدامة قالا قال حماد حدثني أحمد بن داود السدي قال ورد علي كتاب أمير المؤمنين المتوكل وأنا على سواد الكوفة أن ابتع لي تل بونى بما بلغت فابتعتها له فإذا قرية صغيرة على تل قد خرب ما حواليها من الضياع فابتعتها له بعشرة آلاف درهم قال فظننته حركه على طلبها أنه غني\n(حبذا ليلتي بتل بونى ... )\nسألت عن ذلك فعرفت أن جاريته مكتومة غنته هذا الصوت قال حماد ومكتومة هذه جارية أهداها أبي إليه لما ولي الخلافة فإنه سأل عنه فعرف أنه قد كف بصره فكتب له بمائة ألف درهم وأمر بإشخاصه إليه مكرما فأشخص إليه وأهدى إليه عدة جوار هذه فيهن وروي الهيثم بن عدي عن ابن عياش أن الحجاج دعا يوما بمالك بن أسماء فعاتبه عتابا طويلا ثم قال له أنت والله كما قال أخو بني جعدة\n(إذا ما سوأة غراء ماتت ... أتيت بسوءة أخرى بهيم)\n(وما تنفك ترحض كل يوم ... من السوءات كالطفل النهيم)\n(أكل الدهر سعيك في تباب ... تناغي كل مومسة أثيم)\nفقال له لست كما قال الجعدي ولكني كما قلت\n(لكل جواد عثرة يستقيلها ... وعثرة مثلي لا تقال مدى الدهر)\n(فهبني يا حجاج أخطأت مرة ... وجرت عن المثلى وغنيت بالشعر)\n(فهل لي إذا ما تبت عندك توبة ... تدارك ما قد فات في سالف العمر)\nقال له الحجاج بلى والله لئن تبت لأقبلن توبتك ولأعفين على ما كان من ذنبك ومن لي بذلك يا مالك قال له لك والله به قال حسبي الله ونعم الوكيل فانظر ما تقول قال الحق أصلحك الله لا يخفى على أحد قال فترك مالك الشراب ووفى بعهده وأظهر النسك ثم طما به الشعر وطال عليه ترك اللذات والشراب فقال","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":3,"spl":"المتوكل يبتاع تل بونى — مالك يشرب ولا يقبل العذل","tags":["الجواري والنساء"],"loc":3066,"partialRef":{"sid":"b221-8","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b222-6","bab":"الجزء 17","sec":"مالك يشرب ولا يقبل العذل","page":"ج17 ص240","text":"(وندمان صدق قال لي بعد هدأة ... من الليل قم نشرب فقلت له مهلا)\n(فقال أبخلا يابن أسماء هاكها ... كميتا كريح المسك تزدهف العقلا)\n(فتابعته فيما أراد ولم أكن ... بخيلا على الندمان أو شكسا وغلا)\n(ولكنني جلد القوى أبذل الندى ... وأشرب ما أعطى ولا أقبل العذلا)\n(ضحوك إذا ما دبت الكأس في الفتى ... وغيره سكر وإن أكثر الجهلا)\nال فبلغ الحجاج أن مالكا قد راجع الشراب فقال لا يأتي مالك بخير\nسجيس الأوجس قاتل الله أيمن بن خريم حيث يقول\n(إذا المرء وفى الأربعين ولم يكن ... له دون ما يأتي حجاب ولا ستر)\n(فدعه وما يأتي ولا تعذلنه ... وإن مد أسباب الحياة له العمر)\nوأنشدنا علي بن سليمان الأخفش أبيات أيمن هذه الرائية وقال أخذ معناها من قول ابن عباس إذا بلغ المرء أربعين سنة ولم يتب أخذ إبليس بناصيته وقال حبذا من لا يفلح أبدا وأول الأبيات هذه\n(وصهباء جرجانية لم يطف بها ... حنيف ولم تنغر بها ساعة قدر)\n(ولم يشهد القس المهينم نارها ... طروقا ولا صلى على طبخها حبر)\n(أتاني بها يحيى وقد نمت نومة ... وقد غابت الجوزاء وانحدر النسر)\n(فقلت اصطبحها أو لغيري سقها ... فما أنا بعد الشيب ويحك والخمر)\n(إذا المرء وفى الأربعين ولم يكن ... له دون ما يأتي حجاب ولا ستر)\n(فدعه ولا تنفس عليه الذي أتى ... ولو مد أسباب الحياة له العمر)\n\n(تلك عرسي تروم هجري سفاها ... وجفتني فما توافي عناقي)\n(زعمت أنها تواتي مع المال ... وأني محالف إملاقي)\n(وتناست رزية بدمشق ... أشخصت مهجتي فويق التراقي)\n(يوم نلقى نعش ابن عروة محمولا ... بأيدي الرجال والأعناق)\n(مستحثا به سباقا إلى القبر ... وما إن لحثهم من سباق)\n(ثم وليت موجعا قد شجاني ... قرب عهد بهم وبعد تلاق)\nروضه من الخفيف الشعر لإسماعيل بن يسار النسائي يرثي محمد بن عروة بن الزبير والغناء لدحمان خفيف ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لابن محرز ثقيل أول بالبنصر عن حبش","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":3,"spl":"المتوكل يبتاع تل بونى — مالك يشرب ولا يقبل العذل","tags":["السفر والحج"],"song":1,"loc":3067},
{"id":"b222-8","bab":"الجزء 17","sec":"من أخبار عروة بن الزبير — قدومه على الوليد بن عبد الملك","page":"ج17 ص242 – ج17 ص243","text":"أخبرنا الطوسي والحرمي بن أبي العلاء قالا حدثنا الزبير قال حدثنا مصعب بن عثمان عن عامر بن صالح عن هشام بن عروة قال قدم عروة بن الزبير على عبد الملك بن مروان فدخل فأجلسه معه على السرير فجاء قوم فوقعوا في عبد الله بن الزبير فخرج عروة فقال للآذن إن عبد الله بن الزبير ابن أمي وأبي فإذا أردتم أن تقعوا فيه فلا تأذنوا لي عليكم فذكر ذلك لعبد الملك بن مروان فقال له عبد الملك قد\nأخبرني في الآذن بما قلت وإن أخاك لم يكن قتلنا إياه لعداوة ولكنه طلب أمرا وطلبناه فقتل دونه وإن الشام قوم من أخلاقهم ألا يقتلوا أحدا إلا شتموه فإذا أذنا لأحد قبلك فقد جاء من يشتمه فلا تدخل وإذا أذنا لأحد وأنت جالس فانصرف\nثم قدم عروة على الوليد بن عبد الملك حين شلت رجله فقيل له\nاقطعها قال إني لأكره أن أقطع مني طابقا فارتفعت إلى الركبة فقيل له إنها إن وقعت في الركبة قتلتك فقطعت ولم يقبض وجهه وقيل له قبل أن يقطعها نسقيك دواء لا تجد معه ألما فقال ما يسعني أن هذا الحائط وقاني أذاها\nقال الزبير وحدثني مصعب بن عثمان بن عامر عن صالح عن هشام ابن عروة قال سقط محمد بن عروة بن الزبير وأمه بنت الحكم بن أبي العاص بن أمية من سطح في اصطبل دواب الوليد بن عبد الملك فضربته بقوائمها حتى قتلته فأتى عروة رجل يعزيه فقال عروة إن كنت تعزيني برجلي فقد احتسبتها فقال بل أعزيك بمحمد قال وماله فخبره بشأنه فقال\n(وكنت إذا الأيام أحدثن نكبة ... أقول شوى ما لم يصبن صميمي)\nللهم أخذت عضوا وتركت أعضاء وأخذت ابنا وتركت أبناء فإنك إن كنت أخذت لقد أبقيت وإن كنت ابتليت لقد عافيت فلما قدم المدينة نزل قصره بالعقيق فأتاه ابن المنكدر وقال كيف\nكنت فقال ( لقد لقينا من سفرنا هذا نصبا\nال الزبير وحدثني عبد الملك بن عبد العزيز عن ابن الماجشون أن عيسى بن طلحة جاء إلى عروة بن الزبير حين قدم من عند الوليد بن عبد الملك وقد قطعت رجله فقال عروة لبعض بنيه اكشف لعمك عن رجلي ينظر إليها ففعل فقال له عيسى إنا لله وإنا إليه راجعون يا أبا عبد الله ما أعددناك للصراع ولا للسباق ولقد أبقى الله لنا منك ما كنا نحتاج إليه منك رأيك وعلمك فقال عروة ما عزاني أحد عن رجلي مثلك قال الزبير وحدثني مصعب بن عثمان عن عامر بن صالح عن هشام ابن عروة","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":4,"spl":"من أخبار عروة بن الزبير — قدومه على الوليد بن عبد الملك","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3068},
{"id":"b222-9","bab":"الجزء 17","sec":"الوليد يبعث إليه من هو أعظم بلاء منه","page":"ج17 ص245","text":"أنه قدم على الوليد رجل من عبس ضرير محطوم الوجه فسأله عن سبب ذلك فقال بت ليلة في بطن واد ولا أعلم في الأرض عبسيا يزيد ماله على مالي فطرقنا سيل فذهب بما كان لي من أهل ومال وولد إلا صبيا مولودا وبعيرا ضعيفا فند البعير والصبي معي فوضعته واتبعت البعير فما جاوزت ابني قليلا إلا ورأس الذئب في بطنه فتركته واتبعت البعير فرمحني رمحة حطم بها وجهي وأذهب عيني فأصبحت لا ذا مال ولا ذا ولد ولا ذا بصر فقال الوليد بن عبد الملك اذهبوا به إلى عروة ليعلم أن في الناس من هو أعظم بلاء منه\nأخبرني حبيب بن نصر المهلبي وعمر بن عبد العزيز بن أحمد ومحمد ابن العباس اليزيدي وجماعة أخبروني قالوا حدثنا الزبير بن بكار قال حدثني عمي عن جدي عن هشام بن عروة قال\nخرجت مع أبي عروة بن الزبير حاجا ومعنا أخي محمد بن عروة وكان من أحسن الناس وجها فلما كنا في بعض الطريق إذا نحن بعمر بن أبي ربيعة يكلم بعضنا فقلنا هذا أبو الخطاب لو سايرناه فرآنا عروة فقال فيم أنتم قلنا هذا عمر بن أبي ربيعة فضرب عروة إليه راحلته فلما رآها عمر عدل إليه فسلم عليه ثم\nقال وأين زين المواكب يعني محمد بن عروة فقال قد تقدم فعدل عن عروة واتبع محمدا فقال له عروة نحن أكفى لك وأولى أن تسايرنا فقال إني رجل موكل بالجمال أتبعه حيث كان وضرب راحلته ومضى\n(يا بني الصيداء ردوا فرسي ... إنما يفعل هذا بالذليل)\n(عودوا مهري الذي عودته ... دلج الليل وإيطاء القتيل)\n(واستباء الزق من حاناته ... شائل الرجلين معصوبا يميل)\nروضه من ثاني الرمل بنو الصيداء بطن من بني اسد والدلج السير في آخر الليل يقال دلج يدلج مخففة إذا سار من آخر الليل وادلج يدلج إذا سار الليل كله واستباء الزق أراد استباء الخمر فيه أي ابتاعها من حاناتها والحانات جمع حانة وهي الموضع الذي تباع فيه الخمر وشائل الرجلين رافعهما وروى الأصمعي وأبو عمرو\n(أحمل الزق على منسجه ... فيظل الضيف نشوانا يميل)\nلشعر لزيد الخيل الطائي والغناء لابن محرز خفيف رمل بإطلاق الوتر في مجرى الوسطى عن يحيى المكي وذكره إسحاق في هذه الطريقة ولم ينسبه إلى أحد وفيه لعاذل لحن من كتاب إبراهيم غير مجنس وذكر حبش أن فيه لنبيه لحنا من الثقيل الثاني بالوسطى","topic":"أخبار مالك بن أسماء بن خارجة ونسبه","topicNo":222,"sp":5,"spl":"الوليد يبعث إليه من هو أعظم بلاء منه","tags":["اللهو والمزاح"],"song":1,"loc":3069},
{"id":"b223-2","bab":"الجزء 17","sec":"أخبار زيد الخيل ونسبه — النبي يسميه زيد الخير","page":"ج17 ص247 – ج17 ص248","text":"هو زيد بن مهلهل بن يزيد بن منهب بن عبد رضا ورضا صنم كان لطيئ ابن محلس بن ثور بن عدي بن كنانة بن مالك بن نائل بن نبهان وهو أسود بن عمرو بن الغوث بن جلهمة وهو طيئ سمي بذلك لأنه كان يطوي المناهل في غزواته ابن أدد بن مذحج بن زيد بن يشجب الأصفر بن عريب بن مالك بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان بن عابر وهو هود النبي كذا نسبه النسابون والله أعلم وأم طيئ مدلة بنت ذي منحسان بن عريب بن الغوث بن زهير بن وائل بن الهميسع بن حمير بن سبأ بن يشجب بن يعرب بن قحطان ومدلة هذه هي مذحج وهو لقبها وهي أم مالك بن أدد وكانت مدلة عند أدد أيضا فولدت له الأشعر واسمه نبت ومرة ابني أدد ومن الناس من يقول مذحج ظرب صغير اجتمعوا عليه وليس بأم ولا أب والله أعلم\nوكان زيد الخيل فارسا مغوارا مظفرا شجاعا بعيد الصيت في الجاهلية وأدرك الإسلام ووفد إلى النبي ولقيه وسر به وقرظه وسماه زيد الخير وهو شاعر مقل مخضرم معدود في الشعراء الفرسان وإنما كان يقول الشعر في غاراته ومفاخراته ومغازيه وأياديه عند من مر عليه وأحسن في قراه إليه وإنما سمي زيد الخيل لكثرة خيله وأنه لم يكن لأحد من قومه ولا لكثير من العرب إلا الفرس والفرسان وكانت له خيل كثيرة منها المسماة المعروفة التي ذكرها في شعره وهي ستة وهي الهطال والكميت والورد وكامل ودؤول ولاحق وفي الهطال يقول\n(أقرب مربط الهطال إني ... أرى حربا ستلقح عن حيال)\nفي الورد يقول\n(أبت عادة للورد أن يكره القنا ... وحاجة نفسي في نمير وعامر)\nفي دؤول يقول\n(فأقسم لا يفارقني دؤول ... أجول به إذا كثر الضراب)\nذا ما حضرني في تسمية خيله في شعره وقد ذكرها وكان لزيد الخيل ثلاثة بنين كلهم يقول الشعر وهم عروة وحريث ومهلهل ومن الناس من ينكر أن يكون له من الولد إلا عروة وحريث وهذا الشعر الذي فيه الغناء يقوله في فرس من خيله ظلع في بعض غزواته بني أسد فلم يتبع الخيل ووقف فأخذته بنو الصيداء فصلح عندهم واستقل\nوقيل بل أغزى عليه بعض بني نبهان فنكس عنه وأخذ وقيل إنه خلفه في بعض أحياء العرب ظالعا ليستقل فأغارت عليهم بنو أسد فأخذوا الفرس فيما استاقوه لهم فقال في ذلك زيد الخيل\n(يا بني الصيداء ردوا فرسي ... إنما يفعل هذا بالذليل)\n(لا تذيلوه فإني لم أكن ... يا بني الصيداء لمهري بالمذيل)\n(عودوه كالذي عودته ... دلج الليل وإيطاء القتيل)\n(أحمل الزق على منسجه ... فيظل الضيف نشوانا يميل)\nال أبو عمرو الشيباني وكان زيد الخيل ملحا على بني أسد بغاراته ثم على بني الصيداء منهم ففيهم يقول\n(ضجت بنو الصيداء من حربنا ... والحرب من يحلل بها يضجر)\n(بتنا نزجي نحوهم ضمرا ... معروفة الأنساب من منسر)\n(حتى صبحناهم بها غدوة ... نقتلهم قسرا على ضمر)\n(يدعون بالويل وقد مسهم ... منا غداة الشعب ذي الهيشر)\n(ضرب يزيل الهام ذو مصدق ... يعلو على البيضة والمغفر)\nالهيشر شجر كثير الشوك تأكله الإبل نسخت من كتاب لأبي المحلم قال حدثني أضبط بن الملوح قال لي أبي أنشد حبيب بن خالد بن نضلة الفقعسي قول زيد الخيل\n(عودوا مهري الذي عودته ... )\nضحك ثم قال قولوا له إن عودناه ما عودته دفعناه إلى أول من يلقانا وهربنا","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":0,"spl":"أخبار زيد الخيل ونسبه — النبي يسميه زيد الخير","tags":[],"loc":3070,"partialRef":{"sid":"b222-9","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b223-4","bab":"الجزء 17","sec":"وفوده على النبي وإسلامه — مات بالحمى","page":"ج17 ص250 – ج17 ص251","text":"أخبرني الحسين بن القاسم الكوكبي إجازة قال حدثني علي بن حرب قال أنبأني هشام بن الكلبي أبو المنذر قال حدثني عباد بن عبد الله النبهاني عن أبيه عن جده وأضفت إلى ذلك ما رواه أبو عمرو الشيباني قالا وفد زيد الخيل بن مهلهل على رسول الله ومعه وزر بن سدوس النبهاني وقبيصة بن الأسود بن عامر بن جوين الجرمي ومالك بن جبير المغني وقعين بن خليل الطريفي في عدة من طيىء فأناخوا ركابهم بباب المسجد ودخلوا ورسول الله يخطب الناس فلما رآهم\nقال إني خير لكم من العزى ومما حازت مناع من كل ضار غير يفاع ومن الجبل الأسود الذي تعبدونه من دون الله عز و جل قال أبو المنذر يعني بمناع جبل طيىء\nفقام زيد وكان من أجمل الرجال وأتمهم وكان يركب الفرس المشرف ورجلاه تخطان الأرض كأنه على حمار فقال أشهد أن لا إله إلا الله وأنك محمد رسول الله قال ومن أنت قال أنا زيد الخيل بن مهلهل فقال رسول الله بل أنت زيد الخير وقال الحمد لله الذي جاء بك من سهلك وجبلك ورقق قلبك على الإسلام يا زيد ما وصف لي رجل قط فرأيته إلا كان دون ما وصف به إلا أنت فإنك فوق ما قيل فيك\nفلما ولى قال النبي أي رجل إن سلم من آطام المدينة فأخذته الحمى فأنشأ يقول\n(أنخت بآطام المدينة أربعا ... وخمسا يغني فوقها الليل طائر)\n(شددت عليها رحلها وشليلها ... من الدرس والشعراء والبطن ضامر)\nمكث سبعا ثم اشتدت الحمى به فخرج فقال لأصحابه جنبوني بلاد قيس فقد كانت بيننا حماسات في الجاهلية ولا والله لا أقاتل مسلما حتى ألقى الله فنزل بماء لحي من طيىء يقال له فردة واشتدت به الحمى فأنشأ يقول\n(أمرتحل صحبي المشارق غدوة ... وأترك في بيت بفردة منجد)\n(سقى الله ما بين القفيل فطابة ... فما دون أرمام فما فوق منشد)\n(هنالك لو أني مرضت لعادني ... عوائد من لم يشف منهن يجهد)\n(فليت اللواتي عدنني لم يعدنني ... وليت اللواتي غبن عني عودي)\nقال وكتب معه رسول الله لبني نبهان بفيدك كتابا مفردا وقال له أنت زيد الخير فمكث بالفردة سبعة أيام ثم مات فأقام عليه قبيصة بن الأسود المناحة سبعا ثم بعث راحلته ورحله وفيه كتاب رسول الله فلما نظرت امرأته وكانت على الشرك إلى الراحلة ليس عليها زيد ضربتها بالنار وقالت\n(ألا إنما زيد لكل عظيمة ... إذا أقبلت أوب الجراد رعالها)\n(لقاهم فما طاشت يداه بضربهم ... ولا طعنهم حتى تولى سجالها)\nال فبلغني أن رسول الله وآله لما بلغه ضرب امرأة زيد الراحلة بالنار واحتراق الكتاب قال بؤسا لبني نبهان وقال أبو عمرو الشيباني لما وفد زيد الخيل على رسول الله فدخل إليه طرح له متكأ فأعظم أن يتكئ بين يدي رسول الله وآله فرد المتكأ فأعاده عليه ثلاثا وعلمه دعوات كان يدعو بها فيعرف الإجابة ويستسقي فيسقى وقال يا رسول الله أعطني ثلاثمائة فارس أغير بهم على قصور الروم فقال له أي\nرجل أنت يا زيد ولكن أم الكلبة تقتلك يعني الحمى فلم يلبث زيد بعد انصرافه إلا قليلا حتى حم ومات قال أبو عمرو وأسلموا جميعا إلا وزر فإنه\nقال لما رأى النبي وآله إني لأرى رجلا ليملكن رقاب العرب ووالله لا يملك رقبتي أبدا فلحق بالشام فتنصر وحلق رأسه فمات على ذلك أخبرني محمد بن الحسن بن دريد\nقال حدثني السكن بن سعيد عن محمد بن عباد عن ابن الكلبي قال أقبل زيد الخيل الطائي حتى أتى النبي وكان زيد رجلا جسيما طويلا جميلا فقال له النبي من أنت\nقال أنا زيد الخيل قال بل أنت زيد الخير أما إني لم أخبر عن رجل خبرا إلا وجدته دون ما أخبرت به عنه غيرك إن فيك لخصلتين يحبهما الله عز و جل ورسوله قال وما هما يا رسول الله قال الأناة والحلم فقال زيد الحمد لله الذي جبلني على ما يحب الله ورسوله","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":1,"spl":"وفوده على النبي وإسلامه — مات بالحمى","tags":["الجواري والنساء"],"loc":3071},
{"id":"b223-5","bab":"الجزء 17","sec":"عمر يسأله عن ملوك طيئ وأصحاب مرابعها","page":"ج17 ص253","text":"قال ودخل زيد على رسول الله وعنده عمر رضي الله عنه فقال عمر لزيد أخبرنا يا ابا مكنف عن طيئ وملوكها نجدتها وأصحاب مرابعها فقال زيد في كل يا عمر نجدة وبأس وسيادة ولكل رجل من حيه مرباع أما بنو حية فملوكنا وملوك غيرنا وهم القداميس القادة والحماة الذادة والأنجاد السادة\nأعظمنا خميسا وأكرمنا رئيسا وأجملنا مجالس وأنجدنا فوارس فقال له عمر رضي الله عنه ما تركت لمن بقي من طيىء شيئا فقال بلى والله أما بنو ثعل وبنو نبهان وجرم ففوارس العدوة وطلاعو كل نجوة ولا تحل لهم حبوة ولا تراع لهم ندوة ولا تدرك لهم نبوة عمود البلاد وحية كل واد وأهل الأسل الحداد والخيل الجياد والطارف والتلاد وأما بنو جديلة فأسهلنا قرارا وأعظمنا أخطارا وأطلبنا للأوتار وأحمانا للذمار وأطعمنا للجار فقال له عمر سم لنا هؤلاء الملوك\nقال نعم منهم عفير المجير على الملوك وعمرو المفاخر ويزيد شارب الدماء والغمر ذو الجود ومجير الجراد وسراج كل ظلام ولامة وملحم بن حنظلة هؤلاء كلهم من بني حية وأما حاتم بن عبد الله الثعلي الجواد فلا يجارى والسمح فلا يبارى والليث الضرغامة قراع كل هامة جوده في الناس علامة لا يقر على ظلامة فاعترض رجل من بني ثعل لما مدح زيد حاتما فقال ومنا زيد بن مهلهل النبهاني رئيس قومه وسيد الشيب والشبان وسم الفرسان وآفة الأقران والمهيب بكل مكان أسرع إلى الإيمان وآمن بالفرقان رئيس قومه في الجاهلية وقائدهم إلى أعدائهم على شحط المزار وطموس الآثار وفي الإسلام رائدنا إلى رسول الله ومجيبه من غير تلعثم ولا تلبث ومنا زيد بن سدوس النبهاني عصمة الجيران والغيث بكل أوان ومضرم النيران ومطعم الندمان وفخر كل يمان\nومنا الأسد الرهيص سيد بني جديلة ومدوخ كل قبيلة قاتل عنترة فارس بني عبس ومكشف كل لبس فقال عمر لزيد الخيل لله درك يا أبا مكنف فلو لم يكن لطيىء غيرك وغير عدي بن حاتم لقهرت بكما العرب\nأخبرني ابن دريد قال أخبرني عمي عن أبيه عن ابن الكلبي عن أبيه قال أخبرني شيخ من بني نبهان قال أصابت بني شيبان سنة ذهبت بالأموال فخرج رجل منهم بعياله حتى أنزلهم الحيرة فقال لهم كونوا قريبا من الملك يصبكن من خيره حتى أرجع إليكن وآلى ألية لا يرجع حتى يكسبهن خيرا أو يموت فتزود زادا ثم مشى يوما إلى الليل فإذا هو بمهر مقيد يدور حول خباء فقال هذا أول الغنيمة فذهب يحله ويركبه فنودي خل عنه واغنم بنفسك فتركه ومضى سبعة أيام حتى انتهى إلى عطن إبل مع تطفيل الشمس فإذا خباء عظيم وقبة من أدم فقال في نفسه ما لهذا الخباء بد من أهل وما لهذه القبة بد من رب وما لهذا العطن بد من إبل فنظر في الخباء فإذا شيخ كبير قد اختلفت ترقوتاه كأنه نسر\nقال فجلست خلفه فلما وجبت الشمس إذا فارس قد أقبل لم أر فارسا قط أعظم منه ولا أجسم على فرس مشرف ومعه أسودان يمشيان جنبيه وإذا مائة من الإبل مع فحلها فبرك الفحل وبركت حوله ونزل الفارس فقال لأحد عبديه احلب فلانة ثم اسق الشيخ فحلب في عس حتى ملأه ووضعه بين يدي الشيخ وتنحى فكرع منه الشيخ مرة أو مرتين ثم نزع فثرت إليه فشربته فرجع إليه العبد فقال يا مولاي قد أتى على آخره ففرح بذلك\nوقال احلب فلانة فحلبها ثم وضع العس بين يدي الشيخ فكرع منه واحدة ثم نزع فثرت إليه فشربت نصفه وكرهت أن آتي على آخره فأتهم فجاء العبد فأخذه\nوقال لمولاه قد شرب وروي فقال دعه ثم أمر بشاة فذبحت وشوى للشيخ منها ثم أكل هو وعبداه فأمهلت حتى إذا ناموا وسمعت الغطيط ثرت إلى الفحل فحللت عقاله وركبته فاندفع بي وتبعته الإبل فمشيت ليلتي حتى الصباح فلما أصبحت نظرت فلم أر أحدا فشللتها إذا شلا عنيفا حتى تعالى النهار ثم التفت التفاتة فإذا أنا بشيء كأنه طائر فما زال يدنو حتى تبينته فإذا هو فارس على فرس وإذا هو صاحبي بالأمس فعقلت الفحل ونثلت كنانني ووقفت بينه وبين الإبل فقال احلل عقال الفحل فقلت كلا والله لقد خلفت نسيات بالحيرة وآليت ألية لا أرجع حتى أفيدهن خيرا أو أموت\nقال فإنك لميت حل عقاله لا أم لك فقلت ما هو إلا ما قلت لك فقال إنك لمغرور انصب لي خطامه واجعل فيه خمس عجر ففعلت فقال أين تريد أن أضع سهمي فقلت في هذا الموضع فكأنما وضعه بيده ثم أقبل يرمي حتى أصاب الخمسة بخمسة أسهم فرددت نبلي وحططت قوسي ووقفت مستسلما فدنا مني وأخذ السيف","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":2,"spl":"عمر يسأله عن ملوك طيئ وأصحاب مرابعها","tags":["المديح","اللهو والمزاح"],"loc":3072},
{"id":"b223-6","bab":"الجزء 17","sec":"عمر يسأله عن ملوك طيئ وأصحاب مرابعها","page":"ج17 ص253","text":"والقوس ثم قال ارتدف خلفي وعرف أني الرجل الذي شربت اللبن عنده فقال كيف ظنك بي قلت أسوأ ظن قال وكيف قلت لما قليت من تعب ليلتك وقد أظفرك الله بي فقال أترانا كنا نهيجك وقد بت تنادم مهلهلا\nقلت أزيد الخيل أنت قال نعم أنا زيد الخيل فقلت كن خير آخذ فقال ليس عليك بأس فمضى إلى موضعه الذي كان فيه ثم قال أما لو كانت هذه الإبل لي لسلمتها إليك ولكنها ليست مهلهل فأقم علي فإني على شرف غارة فأقمت أياما ثم أغار على بني نمير بالملح فأصاب مائة بعير فقال هذه أحب إليك أم تلك\nقلت هذه قال دونكها وبعث معي خفراء من ماء إلى ماء حتى وردوا بي الحيرة فلقيني نبطي فقال لي يا أعرابي أيسرك أن لك بإبلك بستانا من هذه البساتين\nقلت وكيف ذاك قال هذا قرب مخرج نبي يخرج فيملك هذه الأرض ويحول بين أربابها وبينها حتى إن أحدهم ليبتاع البستان من هذه البساتين بثمن بعير\nقال فاحتملت بأهلي حتى انتهيت إلى موضع الشيطين فبينما نحن في الشيطين على ماء لنا وقد كان الحوفزان بن شريك أغار على بني تميم فجاءنا رسول الله فأسلمنا وما مضت الأيام حتى شريت بثمن بعير من إبلي بستانا بالحيرة فقال في يوم الملح زيد الخيل\n(ويوم الملح ملح بني نمير ... أصابتكم بأظفار وناب)\nخبرني محمد بن الحسن بن دريد قال أخبرني عمي عن ابن الكلبي\nعن أبيه والشرقي أن زيد الخيل قال للنبي إن في الحي رجلين لهما كلاب مضريات تصيد الوحش أفنأكل مما أمسكته ولم تدرك ذكاته فقال ( إذا أرسلت كلبك فاذكر اسم الله عليه وكل مما أمسك\nأو كما قال عليه السلام أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه إسحاق عن الهيثم بن عدي عن حماد الراوية عن ابن أبي ليلى قال أنشدتني ليلى بنت عروة بن زيد الخيل الطائي شعر أبيها في يوم محجر\n(بني عامر هل تعرفون إذا غدا ... أبو مكنف قد شد عقد الدوابر)\n(بجيش تضل البلق في حجراته ... ترى الأكم فيه سجدا للحوافر)\n(وجمع كمثل الليل مرتجز الوغى ... كثير حواشيه سريع البوادر)\nالت ليلى فقلت لأبي يا أبه أشهدت ذلك اليوم مع أبيك قال إي والله يا بنية لقد شهدته قلت كم كانت خيل أبيك هذه التي وصفت قال ثلاثة أفراس","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":3,"spl":"عمر يسأله عن ملوك طيئ وأصحاب مرابعها","tags":["الجواري والنساء","الوصف والطبيعة","الرواية والكتابة"],"loc":3073},
{"id":"b223-7","bab":"الجزء 17","sec":"زيد الخيل يغزو بني عامر","page":"ج17 ص258","text":"نسخت من كتاب عمرو بن أبي عمرو الشيباني بخطه عن أبيه أن زيد الخيل بن مهلهل جمع طيئا وأخلاطا لهم وجموعا من شذاذ العرب فغزا بهم بني عامر ومن جاورهم من قبائل العرب من قيس وسار إليهم فصبحهم من طلوع الشمس فنذروا به وفزعوا به إلى الخيل وركبوها وكان أول\nمن نذر بهم فلقي جمعهم غني بن أعصر وإخوتهم الحارث وهو الطفاوة واسمه مالك بن سعد بن قيس بن عيلان فاقتتلوا قتالا شديدا ثم انهزمت بنو عامر فاستحر القتل بغني وفيهم يومئذ فرسان وشعراء فملأت طيىء أيديهم من غنائمهم وأسر زيد الخيل يومئذ الحطيئة الشاعر فجز ناصيته وأطلقه ثم إن غنيا تجمعت بعد ذلك مع لف من بني عامر فغزوا طيئا في أرضهم فغنموا وقتلوا وأدركوا ثأرهم منهم وقد كان زيد الخيل قال في وقعته لبني عامر قصيدته التي يقول فيها\n(وخيبة من يخيب على غني ... وباهلة بن أعصر والكلاب)\nلما أدركوا ثارهم أجابه طفيل الغنوي فقال\n(سمونا بالجياد إلى أعاد ... مغاورة بجد واعتصاب)\n(نؤمهم على وعث وشحط ... بقود يطلعن من النقاب)\nهي طويلة يقول فيها\n(أخذنا بالمخطم من أتاهم ... من السود المزنمة الرغاب)\n(وقتلنا سراتهم جهارا ... وجئنا بالسبايا والنهاب)\n(سبايا طيىء أبرزن قسرا ... وأبدلن القصور من الشعاب)\n(سبايا طيىء من كل حي ... نما في الفرع منها والنصاب)\n(وما كانت بناتهم سبيا ... ولا رغبا يعد من الرغاب)\n(ولا كانت دماؤهم وفاء ... لنا فيما يعد من العقاب)\nخبرني الحسن بن يحيى قال حدثنا حماد بن إسحاق عن أبيه قال كان لزيد الخيل ابن يقال له عروة وكان فارسا شاعرا فشهد القادسية فحسن فيها بلاؤه وقال في ذلك يذكر حسن بلائه\n(برزت لأهل القادسية معلما ... وما كل من يغشى الكريهة يعلم)\n(ويوم بأكناف النخيلة قبلها ... شهدت فلم أبرح أدمي وأكلم)\n(وأقعصت منهم فارسا بعد فارس ... وما كل من يلقى الفوارس يسلم)\n(ونجاني الله الأجل وجيرتي ... وسيف لأطراف المرازب مخذم)\n(وأيقنت يوم الديلميين أنني ... متى ينصرف وجهي عن القوم يهزموا)\n(فما رمت حتى مزقوا برماحهم ... ثيابي وحتى بل أخمصي الدم)\n(محافظة إني امرء ذو حفيظة ... إذا لم أجد مستأخرا أتقدم)\nقال وشهد مع علي بن أبي طالب رضي الله عنه صفين وعاش إلى إمارة\nمعاوية فأراده على البراءة من علي عليه السلام فامتنع عليه وقال\n(يحاولني معاوية بن حرب ... وليس إلى الذي يهوى سبيل)\n(على جحدي أبا حسن عليا ... وحظي من أبي حسن جليل)\nال وله أشعار كثيرة قال أبو عمرو كان لتغلب رئيس يقال له الجرار وأدرك النبي وأبى الإسلام وامتنع منه فيقال إن رسول الله بعث إليه زيد الخيل وأمره بقتاله فمضى زيد فقاتله فقتله لما أبى الإسلام وقال في ذلك\n(صبحت حي بني الجرار داهية ... ما إن لتغلب بعد اليوم جرار)\n(نحوى النهاب ونحوي كل جارية ... كأن نقبتها في الخد دينار)\nال مؤرج خرج رجل من طيىء يقال له ذؤاب بن عبد الله إلى صهر له من هوازن فأصيب الرجل - وكان شريفا ذا رياسة في حيه - فبلغ ذلك زيدا فركب في نبهان ومن تبعه من ولد الغوث وأغار على بني عامر وجعل كلما أخذ أسيرا\nقال له ألك علم بالطائي المقتول فإن قال نعم قتله وإن قال لا خلى سبيله ومن عليه وأصاب رجالا من بني الوحيد والضباب وبني نفيل ثم رجع زيد إلى قومه فقالوا ما صنعت فقال ما أصبت بثأر ذؤاب ولا يبوء به إلا عامر ابن مالك ملاعب الأسنة فأما ابن الطفيل فلا يبوء به وأنشأ زيد يقول\n(لا أرى أن بالقتيل قتيلا ... عامريا يفي بقتل ذؤاب)\n(ليس من لاعب الأسنة في النقع ... وسمي ملاعبا بأراب)\n(عامر ليس عامر بن طفيل ... لكن العمر رأس حي كلاب)\n(ذاك إن ألقه أنال به الوتر ... وقرت به عيون الصحاب)\n(أو يفتني فقد سبقت بوتر ... مذحجي وجد قومي كابي)\n(قد تقنصت للضباب رجالا ... وتكرمت عن دماء الضباب)\n(وأصبنا من الوحيد رجالا ... ونفيل فما أساغوا شرابي)\nبلغ عامر بن الطفيل قول زيد الخيل وشعره فأغضبه وقال مجيبا له\n(قل لزيد قد كنت تؤثر بالحلم ... إذا سفهت حلوم الرجال)\n(ليس هذا القتيل من سلف الحي ... كلاع ويحصب وكلال)\n(أو بني آكل المرار ولا صيد ... بني جفنة الملوك الطوال)\n(وابن ماء السماء قد علم الناس ... ولا خير في مقالة غالي)\n(إن في قتل عامر بن طفيل ... لبواء لطيىء الأجبال)\n(إنني والذي يحج له الناس ... قليل في عامر الأمثال)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":4,"spl":"زيد الخيل يغزو بني عامر","tags":[],"loc":3074},
{"id":"b223-8","bab":"الجزء 17","sec":"زيد الخيل يغزو بني عامر","page":"ج17 ص258","text":"(يوم لا مال للمحارب في الحرب ... سوى نصل أسمر عسال)\n(ولجام في رأس أجرد كالجذع ... طوال وأبيض قصال)\n(ودلاص كالنهي ذات فضول ... ذاك في حلبة الحوادث مالي)\n(ولعمي فضل الرياسة والسن ... وجد على هوازن عالي)\n(غير أني أولي هوازن في الحرب ... بضرب المتوج المختال)\n(وبطعن الكمي في حمس النقع ... على متن هيكل جوال)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":5,"spl":"زيد الخيل يغزو بني عامر — زيد الخيل وعامر بن الطفيل","tags":[],"loc":3075},
{"id":"b223-9","bab":"الجزء 17","sec":"زيد الخيل يغير على بني مرة وبني فزارة","page":"ج17 ص263","text":"قال أبو عمرو الشيباني لما بلغ زيد الخيل ما كان من الحارث بن ظالم وعمرو بن الإطنابة الخزرجي وهجائه إياه غضب زيد لذلك فأغار على بني مرة بن غطفان فأسر الحارث بن ظالم وامرأته في غارته ثم من عليهما وقال يذكر ذلك\n(ألا هل أتى غوثا ورومان أننا ... صبحنا بني ذبيان إحدى العظائم)\n(وسقنا نساء الحي مرة بالقنا ... وبالخيل تردي قد حوينا ابن ظالم)\n(جنيبا لأعضاد النواجي يقدنه ... على تعب بين النواجي الرواسم)\n(يقول اقبلوا مني الفداء وأنعموا ... علي وجزوني مكان القوادم)\n(وقد مس حد الرمح قوارة استه ... فصارت كشدق الأعلم المتضاجم)\n(وسائل بنا جار ابن عوف فقد رأى ... حليلته جالت عليها مقاسمي)\n(تلاعب وحدان العضاريط بعدما ... جلاها بسهميه لقيط بن حازم)\n(أغرك أن قيل ابن عوف ولا أرى ... عزيمك إلا واهيا في العزائم)\n(غداة سبينا من خفاجة سبيها ... ومرت لهم منا نحوس الأشائم)\n(فمن مبلغ عني الخزارج غارة ... على حي عوف موجفا غير نائم)\nقال أبو عمرو أغار زيد على بني فزارة وبني عبد الله بن غطفان ورئيسهم يومئذ أبو ضب ومع زيد الخيل من بني نبهان بطنان يقال لهما بنو نصر وبنو مالك فأصاب وغنم وساقوا الغنيمة وانتهى إلى العلم فاقتسموا النهاب فقال لهم زيد أعطوني حق الرياسة فأعطاه بنو نصر وأبى بنو مالك فغضب زيد وانحدر إلى بني نصر فبينما بنو مالك يقتسمون إذ غشيتهم فزارة وغطفان وهم حلفاء فاستنقذوا ما بأيديهم فلما رأى زيد ذلك شد على القوم فقتل رئيسهم أبا ضب وأخذ ما في أيديهم فدفعه إلى بني مالك وكانوا نادوه يومئذ يا زيداه أغثنا فكر على القوم حتى استنقذ ما في أيديهم ورده وقال يذكر ذلك\n(كررت على أبطال سعد ومالك ... ومن يدع الداعي إذا هو نددا)\n(فلأيا كررت الورد حتى رأيتهم ... يكبون في الصحراء مثنى وموحدا)\n(وحتى نبذتم بالصعيد رماحكم ... وقد ظهرت دعوى زنيم وأسعدا)\n(فما زلت أرميهم بغرة وجهه ... وبالسيف حتى كل تحتي وبلدا)\n(إذا شك أطراف العوالي لبانه ... أقدمه حتى يرى الموت أسودا)\n(علالتها بالأمس ما قد علمتم ... وعل الجواري بيننا أن تسهدا)\n(لقد علمت نبهان أني حميتها ... وأني منعت السبي أن يتبددا)\n(عشية غادرت ابن ضب كأنما ... هوى عن عقاب من شماريخ صنددا)\n(بذي شطب أغشي الكتيبة سلهبا ... أقب كسرحان الظلام معودا)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":5,"spl":"زيد الخيل يغزو بني عامر — زيد الخيل وعامر بن الطفيل","tags":["الهجاء","الجواري والنساء"],"loc":3076}]);
window.__BOOK__['p09'].push([{"id":"b223-10","bab":"الجزء 17","sec":"زيد الخيل وعامر بن الطفيل","page":"ج17 ص265","text":"قال أبو عمرو وخرج زيد الخيل يطلب نعما له من بني بدر وأغار عامر بن الطفيل على بني فزارة فأخذ امرأة يقال لها هند واستاق نعما لهم فقالت بنو بدر لزيد ما كنا قط إلى نعمك أحوج منا اليوم فتبعه زيد الخيل وقد مضى وعامر يقول يا هند ما ظنك بالقوم فقالت ظني بهم أنهم سيطلبونك وليسوا نياما عنك\nقال فحطأ عجزها ثم قال لا تقول استها شيئا فذهبت مثلا فأدركه زيد الخيل فنظر إلى عامر فأنكره لعظمه وجماله وغشيه زيد فبرز له عامر فقال يا عامر خل سبيل الظعينة والنعم فقال عامر من أنت قال\nفزاري أنا قال عامر والله ما أنت من القلح أفواها فقال زيد خل عنها قال لا أوتخبرني من أنت قال أسدي قال لا والله ما أنت من المتكورين على ظهور الخيل\nقال خل سبيلها قال لا والله أوتخبرني فأصدقني قال أنا زيد الخيل قال صدقت فما تريد من قتالي فوالله لئن قتلتني لتطلبنك بنو عامر ولتذهبن فزارة بالذكر فقال له زيد خل عنها قال تخلى عني وأدعك والظعينة والنعم قال فاستأسر قال أفعل فجز ناصيته وأخذ رمحه وأخذ هندا والنعم فردها إلى بني بدر وقال في ذلك\n(إنا لنكثر في قيس وقائعنا ... وفي تميم وهذا الحي من أسد)\n(وعامر بن طفيل قد نحوت له ... صدر القناة بماضي الحد مطرد)\n(لما أحس بأن الورد مدركه ... وصارما وربيط الجأش ذا لبد)\n(نادى إلي بسلم بعدما أخذت ... منه المنية بالحيزوم واللغد)\n(ولو تصبر لي حتى أخالطه ... أسعرته طعنة تكتار بالزبد)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":5,"spl":"زيد الخيل يغزو بني عامر — زيد الخيل وعامر بن الطفيل","tags":["الجواري والنساء"],"loc":3077},
{"id":"b223-11","bab":"الجزء 17","sec":"زيد الخيل يأسر الحطيئة وكعب بن زهير","page":"ج17 ص266","text":"قال فانطلق عامر إلى قومه مجزوزا وأخبرهم الخبر فغضبوا لذلك وقالوا لا ترأسنا أبدا وتجهزوا ليغيروا على طيىء ورأسوا عليهم علقمة بن علاثة فخرجوا ومعهم الحطيئة وكعب بن زهير\nفبعث عامر إلى زيد الخيل دسيسا ينذره فجمع زيد قومه فلقيهم بالمضيق فقاتلهم فأسر الحطيئة وكعب بن زهير قوما منهم فحبسهم فلما طال عليهم الأسر قالوا يا زيد فادنا قال الأمر إلى عامر بن الطفيل فأبوا ذلك عليه فوهبهم لعامر إلا الحطيئة وكعبا فأعطاه كعب فرسه الكميت وشكا الحطيئة الحاجة فمن عليه فقال زيد\n(أقول لعبدي جرول إذ أسرته ... أثبني ولا يغررك أنك شاعر)\n(أنا الفارس الحامي الحقيقة والذي ... له المكرمات واللهى والمآثر)\n(وقومي رؤوس الناس والرأس قائد ... إذا الحرب شبتها الأكف المساعر)\n(فلست إذا ما الموت حوذر ورده ... وأترع حوضاه وحمج ناظر)\n(بوقافة يخشى الحتوف تهيبا ... يباعدني عنها من القب ضامر)\n(ولكنني أغشى الحتوف بصعدتي ... مجاهرة إن الكريم يجاهر)\n(وأروي سناني من دماء عزيزة ... على أهلها إذ لا ترجى الأياصر)\nقال الحطيئة لزيد\n(إن لم يكن مالي بآت فإنني ... سيأتي ثنائي زيدا بن مهلهل)\n(فأعطيت منا الود يوم لقيتنا ... ومن آل بدر شدة لم تهلل)\n(فما نلتنا غدرا ولكن صبحتنا ... غداة التقينا في المضيق بأخيل)\n(تفادى حماة القوم من وقع رمحه ... تفادي ضعاف الطير من وقع أجدل)\nقال فيه الحطيئة أيضا\n(وقعت بعبس ثم أنعمت فيهم ... ومن آل بدر قد أصبت الأخايرا)\n(فإن يشكروا فالشكر أدنى إلى التقى ... وإن يكفروا لا ألف يا زيد كافرا)\n(تركت المياه من تميم بلاقعا ... بما قد ترى منهم حلولا كراكرا)\n(وحي سليم قد أثرت شريدهم ... وبالأمس ما قتلت يا زيد عامرا)\nفرضي عنه زيد ومن عليه لما قال هذا فيه وعد ذلك ثوابا من الحطيئة وقبله","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":6,"spl":"زيد الخيل يأسر الحطيئة وكعب بن زهير — الحطيئة يمتنع عن هجاء زيد الخيل","tags":["اللهو والمزاح","الموت"],"loc":3078},
{"id":"b223-12","bab":"الجزء 17","sec":"الحطيئة يمتنع عن هجاء زيد الخيل","page":"ج17 ص268","text":"فلما رجع الحطيئة إلى قومه قام فيهم حامدا لزيد شاكرا لنعمته حتى أسرت طيىء بني بدر فطلبت فزارة وأفناء قيس إلى شعراء العرب أن يهجوا بني لأم وزيدا فتحامتهم شعراء العرب وامتنعت عن هجائهم فصاروا إلى الحطيئة فأبى عليهم وقال اطلبوا غيري فقد حقن دمي وأطلقني بغير فداء فلست بكافر نعمته أبدا قالوا فإنا نعطيك مائة ناقة قال والله لو جعلتموها ألفا ما فعلت ذلك وقال الحطيئة\n(كيف الهجاء وما تنفك صالحة ... من آل لأم بظهر الغيب تأتينا)\n(المنعمين أقام العز وسطهم ... بيض الوجوه وفي الهيجا مطاعينا)\nقد أخبرنا أبو خليفة عن محمد بن سلام قال خرج بجير بن زهير والحطيئة ورجل من فزارة يتقنصون الوحش فلقيهم زيد الخيل فافتدى بجير نفسه بفرس كان لكعب أخيه وكعب يومئذ مجاور في بني ملقط من وطيىء وشكا إليه الحطيئة الفاقة فأطلقه\nوقال أبو عمرو غزت بنو نبهان فزارة وهم متساندون ومعهم زيد الخيل فاقتتلوا قتالا شديدا ثم انهزمت فزارة وساقت بنو نبهان الغنائم من النساء والصبيان ثم إن فزارة حشدت واستعانت بأحياء من قيس وفيهم رجل من سليم شديد البأس سيد يقال له عباس بن أنس الرعلي كانت بنو سليم قد أرادوا عقد التاج على رأسه في الجاهلية فحسده ابن عم له فلطم عينه فخرج عباس من أعمال بني سليم في عدة من أهل بيته وقومه فنزل في بني فزارة وكان معهم يومئذ ولم يكن لزيد المرباع حينئذ وأدركت فزارة بني نبهان فاقتتلوا قتالا شديدا فلما رأى زيد ما لقيت بنو نبهان نادى يا بني نبهان أأحمل ولي المرباع قالوا نعم فشد على بني سليم فهزمهم وأخذ أم الأسود امرأة عباس بن أنس ثم شد على فزارة والأخلاط فهزمهم وقال في ذلك\n(ألا ودعت جيرانها أم أسودا ... وضنت على ذي حاجة أن يزودا)\n(وأبغض أخلاق النساء أشده ... إلي فلا تولن أهلي تشددا)\n(وسائل بني نبهان عنا وعندهم ... بلاء كحد السيف إذ قطع اليدا)\n(دعوا مالكا ثم اتصلنا بمالك ... فكل ذكا مصباحه فتوقدا)\n(وبشر بن عمرو قد تركنا مجندلا ... ينوء بخطار هناك ومعبدا)\n(تمطت به قوداء ذات علالة ... إذا الصلدم الخنذيذ أعيا وبلدا)\n(لقيناهم نستنقذ الخيل كالقنا ... ويستسلبون السمهري المقصدا)\n(فيا رب قدر قد كفأنا وجفنة ... بذي الرمث إذ يدعون مثنى وموحدا)\n(على أنني أثوي سناني وصعدتي ... - بساقين - زيدا أن يبوء ومعبدا)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":6,"spl":"زيد الخيل يأسر الحطيئة وكعب بن زهير — الحطيئة يمتنع عن هجاء زيد الخيل","tags":["الهجاء","الجواري والنساء","الرواية والكتابة"],"loc":3079},
{"id":"b223-13","bab":"الجزء 17","sec":"زيد الخيل وقيس بن عاصم","page":"ج17 ص270","text":"قال أبو عمرو وقعت حرب بين أخلاط طيىء فنهاهم زيد عن ذلك وكرهه فلم ينتهوا فاعتزل وجاور بني تميم ونزل على قيس بن عاصم فغزت بنو تميم بكر بن وائل وعليهم قيس وزيد معه فاقتتلوا قتالا شديدا وزيد كاف فلما رأى ما لقيت تميم ركب فرسه وحمل على القوم وجعل يدعو يا لتميم ويتكنى بكنية قيس إذا قتل رجلا أو أذراه عن فرسه أو هزم ناحية حتى هزمت بكر وظفرت تميم فصارت فخرا لهم في العرب وافتخر بها قيس فلما قدموا قال له زيد أقسم لي يا قيس نصيبي فقال وأي نصيب فوالله ما ولي القتال غيري وغير أصحابي فقال زيد\n(ألا هل أتاها والأحاديث جمة ... مغلغلة أنباء جيش اللهازم)\n(فلست بوقاف إذا الخيل أحجمت ... ولست بكذاب كقيس بن عاصم)\n(تخبر من لاقيت أن قد هزمتهم ... ولم تدر ما سيماهم والعمائم)\n(بل الفارس الطائي فض جموعهم ... ومكة والبيت الذي عند هاشم)\n(إذا ما دعوا عجلا عجلنا عليهم ... بمأثورة تشفي صداع الجماجم)\nفبلغ المكشر بن حنظلة العجلي أحد بني سنان قول زيد فخرج في ناس من عجل حتى أغار على بني نبهان فأخذ من نعمهم ما شاء وبلغ ذلك زيد الخيل فخرج على فرسه في فوارس من نبهان حتى اعترض القوم فقال ما لي ولك يا مكشر فقال قولك\n(إذا ما دعوا عجلا عجلنا عليهم ... )\nقاتلهم زيد حتى استنقذ بعض ما كان في أيديهم ورجع المكشر ببقية ما أصاب فأغار زيد على بني تيم الله بن ثعلبة فغنم وسبى وقال في ذلك\n(إذا عركت عجل بنا ذنب غيرنا ... عركنا بتيم اللات ذنب بني عجل)\nقال أبو عمرو كان حريث بن زيد الخيل شاعرا فبعث عمر بن الخطاب رجلا من قريش يقال له أبو سفيان يستقرىء أهل البادية فمن لم يقرأ شيئا من القرآن عاقبه فأقبل حتى نزل بمحلة بني نبهان فاستقرأ ابن عم لزيد الخيل يقال له أوس بن خالد بن زيد بن منهب فلم يقرأ شيئا فضربه فمات فأقامت بنته أم أوس تندبه وأقبل حريث بن زيد الخيل فأخبرته فأخذ الرمح فشد على أبي سفيان فطعنه فقتله وقتل ناسا من أصحابه ثم هرب إلى الشام وقال في ذلك\n(ألا بكر الناعي بأوس بن خالد ... أخي الشتوة الغبراء والزمن المحل)\n(فلا تجزعي يا أم أوس فإنه ... يلاقي المنايا كل حاف وذي نعل)\n(فإن يقتلوا أوسا عزيزا فإنني ... تركت أبا سفيان ملتزم الرحل)\n(ولولا الأسى ما عشت في الناس بعده ... ولكن إذا ما شئت جاوبني مثلي)\n(أصبنا به من خيرة القوم سبعة ... كراما ولم نأكل به حشف النخل)\n\n(بشر الظبي والغراب بسعدى ... مرحبا بالذي يقول الغراب)\n(اذهبي فاقرئي السلام عليهم ... ثم ردي جوابنا يا رباب)\nروضه من الخفيف الشعر لعبيد الله بن قيس الرقيات والغناء لفند المخنث - مولى عائشة بنت سعد بن أبي وقاص - خفيف رمل بالبنصر وذكر حبش أن هذا اللحن ليحيى المكي وليس ممن يحصل قوله","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":7,"spl":"زيد الخيل وقيس بن عاصم — خبر لابن قيس الرقيات","tags":[],"song":1,"loc":3080,"partial":1},
{"id":"b223-14","bab":"الجزء 17","sec":"خبر لابن قيس الرقيات","page":"ج17 ص272","text":"أخبرني بالسبب الذي قال فيه ابن قيس هذا الشعر الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن محمد بن أبي الحارث الكاتب مولى بني عامر بن لؤي وأبو الحارث هذا هو الذي يقول فيه عمر بن أبي ربيعة\n(يا أبا الحارث قلبي طائر ... فائتمر أمر رشيد مؤتمن)\nال حدثني عمرو بن عبد الرحمن بن عمرو بن سهل قال حدثني سليمان بن نوفل بن مساحق عن أبيه عن جده قال","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":7,"spl":"زيد الخيل وقيس بن عاصم — خبر لابن قيس الرقيات","tags":["الرواية والكتابة"],"loc":3081},
{"id":"b223-15","bab":"الجزء 17","sec":"عبد العزيز بن مروان وابن قيس الرقيات","page":"ج17 ص273","text":"أراد عبد الملك بن مروان البيعة لابنه الوليد بعد عبد العزيز بن مروان\nوكتب إلى عبد العزيز يسأله ذلك فامتنع عليه وكتب إليه يقول له لي ابن ليس ابنك أحب إلي منه فإن استطعت ألا يفرق بيننا الموت وأنت لي قاطع فافعل فرق له عبد الملك وكف عن ذلك فقال عبيد الله بن قيس في ذلك - وكان عند عبد العزيز -\n(يخلفك البيض من بنيك كما ... يخلف عود النضار في شعبه)\n(ليسوا من الخروع الضعاف ولا ... أشباه عيدانه ولا غربه)\n(نحن على بيعة الرسول التي ... أعطيت في عجمه وفي عربه)\n(نأتي إذا ما دعوت في الزغف المسرود ... أبدانه وفي جنبه)\n(نهدي رعيلا أمام أرعن لا ... يعرف وجه البلقاء في لجبه)\nقال عبد الملك لقد دخل ابن قيس الرقيات مدخلا ضيقا وتهدده وشتمه وقال أليس هو القائل\n(كيف نومي على الفراش ولما ... تشمل الشأم غارة شعواء)\n(تذهل الشيخ عن بنيه وتبدي ... عن خدام العقيلة العذراء)\nهو القائل أيضا\n(على بيعة الإسلام بايعن مصعبا ... كراديس من خيل وجمعا مباركا)\n(تدارك أخرانا ويمضي أمامنا ... ويتبع ميمون النقيبة ناسكا)\n(إذا فرغت أظفاره من كتيبة ... أمال على أخرى السيوف البواتكا)\nال فلما بلغ عبيد الله قول عبد الملك وشتمه إياه قال\n(بشر الظبي والغراب بسعدى ... مرحبا بالذي يقول الغراب)\n(قال لي إن خير سعدى قريب ... قد أنى أن يكون عنه اقتراب)\n(قلت أنى تكون سعدى قريبا ... وعليها الحصون والأبواب)\n(حبذا الريم ذو الوشاحين والخصر ... الذي لا يناله الأثواب)\n(إن في القصر لو دخلت غزالا ... مصفقا موصدا عليه الحجاب)\n(أرسلت أن فدتك نفسي فاحذر ... هاهنا شرطة عليك غضاب)\n(أقسموا إن رأوك لا تطعم الماء ... وهم حين يقدرون ذئاب)\n(قلت قد يغفل الرقيب ويغفي ... شرطة أو يحين منه انقلاب)\n(أو عسى أن يور الله أمرا ... ليس في غيبه علينا ارتقاب)\n(اذهبي فاقرئي السلام عليها ... ثم ردي يورى جوابنا يا رباب)\n(حدثيها ما قد لقيت وقولي ... حق للعاشق الكريم ثواب)\n(رجل أنت همه حين يمسي ... خامرته من أجلك الأوصاب)\n(لا أشم الريحان إلا بعيني ... كرما إنما يشم الكلاب)\n(رب زار علي لم ير مني ... عثرة وهو مومس كذاب)\n(خادع الله حين جلله الشيب ... فأضحى قد بان منه الشباب)\n(يأمر الناس أن يبروا ويمسي ... وعليه من عيبه جلباب)\n(لا تعبني فليس عندك علم ... لا تنامن أيها المغتاب)\n(تختل الناس بالكتاب فهلا ... حين تغتابني نهاك الكتاب)\n(لست بالمخبت التقي ولا المحضيه ... ج من مقالتي الاحتساب)\n(إنني والتي رمت بك كرها ... ساقطا ملصقا عليك التراب)\n(لتذوقن غب رأيك فينا ... حين تبدو بعرضك الأنداب)\nال الزبير معنى قوله\n(لا أشم الريحان إلا بعيني ... كرما إنما يشم الكلاب)\nعرض بعبد الملك لأنه كان متغير الفم يؤذيه رائحته فكان في يده أبدا ريحان أو تفاحة أو طيب يشمه أخبرني الحرمي قال حدثنا الزبير عن عمه أن ابن قيس قال في عبد العزيز بن مروان\n(يلتفت الناس عند منبره ... إذا عمود البرية انهدما)\nعني إذا مات عبد الملك لأن العهد كان إليه بعده قال الزبير فأخبرني مصعب بن عثمان قال لما بلغ عبد الملك هذا البيت أحفظه وقال بفيه الحجر وحينئذ قال لقد دخل ابن قيس مدخلا ضيقا أخبرني الحرمي قال حدثنا الزبير قال حدثني كثير بن جعفر عن أبيه قال قال الحجاج يوما لأهل ثقته من جلسائه ما من أحد من بني أمية أشد\nنصبا لي من عبد العزيز بن مروان وليس يوم من الأيام إلا وأنا أتخوف أن تأتيني منه قارعة فهل من رجل تدلوني عليه له لسان وشعر وجلد قالوا نعم عمران بن عصام العنزي فدعاه فأخلاه ثم\nقال اخرج بكتابي هذا إلى أمير المؤمنين فاقدح في قلبه من ابنه شيئا من الولاية فقال له عمران دس أيها الأمير إلي دسا فقال له الحجاج إن العوان لا تعلم الخمرة فخرج بكتاب الحجاج فلما دخل على عبد الملك دفع إليه الكتاب وسأله عن الحجاج وأمر العراق فاندفع يقول\n(أمير المؤمنين إليك أهدي ... على الشحط التحية والسلاما)\n(أمير من بنيك يكن جوابي ... لهم أكرومة ولنا نظاما)\n(فلو أن الوليد أطاع فيه ... جعلت له الإمامة والذماما)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":8,"spl":"عبد العزيز بن مروان وابن قيس الرقيات","tags":["السفر والحج","الوصف والطبيعة"],"loc":3082},
{"id":"b223-16","bab":"الجزء 17","sec":"عبد العزيز بن مروان وابن قيس الرقيات","page":"ج17 ص273","text":"كتب عبد الملك إلى عبد العزيز في ذلك ثم ذكر من خبرهما في المكاتبة مثل الخبر الذي قبله وقال فيه فرق عبد الملك رقة شديدة وقال لا يكون إلى الصلة أسرع مني فكف عن ذلك وما لبث عبد العزيز إلا ستة أشهر حتى مات فلما كان زمان ابن الأشعث خرج عمران بن عصام معه على الحجاج فأتى به\nحين قتل ابن الأشعث فقتله فبلغ ذلك عبد الملك فقال قطع الله يدي الحجاج أقتله وهو الذي يقول\n(وبعثت من ولد الأغر معتب ... صقرا يلوذ حمامه بالعوسج)\n(وإذا طبخت بناره أنضجتها ... وإذا طبخت بغيرها لم تنضج)","topic":"أخبار زيد الخيل ونسبه","topicNo":223,"sp":9,"spl":"عبد العزيز بن مروان وابن قيس الرقيات","tags":["السفر والحج","الموت"],"loc":3083},
{"id":"b224-1","bab":"الجزء 17","sec":"ذكر فند وأخباره","page":"ج17 ص279","text":"هو فند أبو زيد مولى عائشة بنت سعد بن أبي وقاص ومنشؤه المدينة وكان خليعا متهتكا يجمع بين الرجال والنساء في منزله ولذلك يقول فيه ابن قيس الرقيات\n(قل لفند يشيع الأظعانا ... طالما سر عيشنا وكفانا)\n(صادرات عشية من قديد ... واردات مع الضحى عسفانا)\n(زودتنا رقية الأحزانا ... يوم جازت حمولها السكرانا)\nعروضه من الخفيف غناه مالك بن أبي السمح من روايتي إسحاق وعمرو بن بانة ولحنه من خفيف الثقيل بالسبابة في مجرى الوسطى وقد اختلف في اسمه فقيل قند بالقاف وفند بالفاء أصح وبه ضرب المثل في الإبطاء فيقال تعست العجلة","topic":"ذكر فند وأخباره","topicNo":224,"sp":0,"spl":"ذكر فند وأخباره — مروان بن الحكم يتهدده","tags":["الجواري والنساء","السفر والحج"],"song":1,"loc":3084},
{"id":"b224-2","bab":"الجزء 17","sec":"عائشة طلبت نارا فجاءها بها بعد سنة","page":"ج17 ص280","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال كانت عائشة بنت سعد أرسلته ليجيئها بنار فخرج لذلك فلقي عيرا خارجا إلى مصر فخرج معهم فلما كان بعد سنة رجع فأخذ نارا ودخل على عائشة وهو يعدو فسقط وقد قرب منها فقال تعست العجلة فقال بعض الشعراء في رجل ذكر بمثل هذه الحال\n(ما رأينا لعبيد مثلا ... إذ بعثناه يجي بالمسله)\n(غير فند بعثوه قابسا ... فثوى حولا وسب العجله)\nخبرني الحسين قال قال حماد قرأت على أبي الهيثم بن عدي قال كان فند أبو زيد مولى لسعد بن أبي وقاص فضربه سعد بن إبراهيم ضربا مبرحا فحلفت عائشة بنت سعد أنها لا تكلمه أبدا أو يرضى عنه - وكانت خالته - فصار إليه سعد طاعة لخالته فوجده وجعا من ضربه فسلم عليه فحول وجهه عنه إلى الحائط ولم يكلمه فقال له أبا زيد إن خالتي حلفت ألا تكلمني حتى ترضى ولست ببارح حتى ترضى عني فقال أما أنا فأشهد أنك مقيت سمج مبغض وقد رضيت عنك على هذه الحال لتقوم عني وتريحني من وجهك ومن\nالنظر إليك فقام من عنده فدخل على عائشة وأخبرها بما قال له فند فقالت قد صدق وأنت كذلك ورضيت عنه قال وكان سعد مضطر الخلق سمجا","topic":"ذكر فند وأخباره","topicNo":224,"sp":0,"spl":"ذكر فند وأخباره — مروان بن الحكم يتهدده","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3085},
{"id":"b224-3","bab":"الجزء 17","sec":"مروان بن الحكم يتهدده","page":"ج17 ص281","text":"أخبرني الحسين قال قال حماد قرأت على أبي بكر وذكر عوانة أن معاوية كان يستعمل مروان بن الحكم على المدينة سنة ويستعمل سعيد بن العاص سنة فكانت ولاية مروان شديدة يهرب فيها أهل الدعارة والفسوق وولاية سعيد لينة يرجعون إليها فبينا مروان يأتي المسجد وفي يده عكازة له وهو يومئذ معزول إذا هو بفند يمسي بين يديه فوكزه بالعكازة وقال له ويلك هيه\n(قل لفند يشيع الأظعانا ... )\nتشيع الأظعان للفساد - لا أم لك - إلى أهل الريبة ستعلم ما يحل بك مني فالتفت إليه فند وقال أنا ذلك وسبحان الله ما أسمجك واليا ومعزولا فضحك مروان وقال له تمتع إنما هي أيام قلائل ثم تعلم ما يمر بك مني\n(حي الدويرة إذ نأت ... منا على عدوائها)\n(لا بالفراق تنيلنا ... شيئا ولا بلقائها)\nروضه من الكامل الشعر لنبيه بن الحجاج السهمي والغناء لابن سريج رمل بالوسطى عن عمرو","topic":"ذكر فند وأخباره","topicNo":224,"sp":0,"spl":"ذكر فند وأخباره — مروان بن الحكم يتهدده","tags":[],"song":1,"loc":3086,"partialRef":{"sid":"b224-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b225-1","bab":"الجزء 17","sec":"أخبار نبيه ونسبه","page":"ج17 ص282","text":"هو نبيه بن الحجاج بن عامر بن حذيفة بن سعد بن سهم بن عمرو بن هصيص بن كعب بن لؤي بن غالب وأمه وأم أخيه منبه أروى بنت عميلة بن السباق بن عبد الدار بن قصي وكان نبيه بن الحجاج وأخوه من وجوه قريش وذوي النباهة فيهم وقتلا جميعا يوم بدر مشركين ولهما يقول أعشى بني تميم - وهو ابن النباش بن زرارة وكان أخوه أبو هالة بن النباش زوج خديجة أم المؤمنين في الجاهلية ولها منه أولاد لهم عقب إلى الآن - وكان الأعشى مداحا لهم وفيهم يقول وهي قصيدة طويلة\n(لله در بني الحجاج إذ ندبوا ... لا يشتكي فعلهم ضيف ولا جار)\n(إن يكسبوا يطعموا من فضل كسبهم ... وأوفياء بعقد الجار أحرار)\nفي نبيه يقول أيضا\n(إن نبيها أبا الرزام أفضلهم ... حلما وأجودهم والجود تفضيل)\n(ليس لفعل نبيه إن مضى خلف ... ولا لقول أبي الرزام تبديل)\n(ثقف كلقمان عدل في حكومته ... سيف إذا قام وسط القوم مسلول)\n(وإن بيت نبيه منهج فلج ... مخضر بالندى ما عاش مأهول)\n(من لا يعر ولا يؤذي عشيرته ... ولا نداه عن المعتر معدول)\nله أيضا فيهما مراث قالها فيهما لما قتلا ببدر لم أستجز ذكرها لأنهما قتلا مشركين محاربين لله ورسوله","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":0,"spl":"أخبار نبيه ونسبه","tags":["الجواري والنساء"],"loc":3087},
{"id":"b225-2","bab":"الجزء 17","sec":"نماذج من شعره","page":"ج17 ص283","text":"وكان نبيه من شعراء قريش وهو القائل وقد سألته زوجتاه الطلاق ذكر ذلك الزبير بن بكار\n(تلك عرساي تنطقان بهجر ... وتقولان قول زور وهتر)\n(تسألاني الطلاق أن رأتاني ... قل مالي قد جئتماني بنكر)\n(فلعلي أن يكثر المال عندي ... ويخلى من المغارم ظهري)\n(ويرى أعبد لنا وجياد ... ومناصيف من ولائد عشر)\n(ويكأن من يكن له نشب يحبب ... ومن يفتقر يعش عيش ضر)\n(ويجنب يسر الأمور ولكن ... ذوي المال حضر كل يسر)\nخبرني الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني علي بن صالح أن عامر بن صالح أنشده لنبيه بن الحجاج\n(قصر العدم بي ولو كنت ذا مال ... كثير لأجلب الناس حولي)\n(ولقالوا أنت الكريم علينا ... ولحطوا إلى هواي وميلي)\n(ولكلت المعروف كيلا هنيا ... يعجز الناس أن يكيلوا ككيلي)\nال الزبير قال علي بن صالح وأنشدني عامر بن صالح لنبيه بن الحجاج أيضا\n(قالت سليمى إذ طرقت أزورها ... لا أبتغي إلا امرأ ذا مال)\n(لا أبتغي إلا امرأ ذا ثروة ... كيما يسد مفاقري وخلالي)\n(فلأحرصن على اكتساب محبب ... ولأكسبن في عفة وجمال)\nأخبرني الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني عمي مصعب قال نزل نبيه بن الحجاج قديدا يريد الشام فغيب بعض بني بكر ناقته يريد أخذ الجعالة عليها منه فقال نبيه في ذلك\n(وردت قديدا فالتوى بذراعها ... ذؤبان بكر كل أطلس أفحج)\n(رجل صديق ما بدت لك عينه ... فإذا تغيب فاحتفظ من دعلج)\nال الزبير الدعلج الكلب والذئب وكل مختلس من السباع فهو دعلج ويقال لاختلاسه الدعلجة وأنشد\n(باتت كلاب الحي تسري بيننا ... يأكلن دعلجة ويشبع من ثوى)\nعني بالدعلجة السرقة قال الزبير ولا عقب للحجاج أبي نبيه ومنبه إلا من ولد نبيه فإن العقب من ولد أبي سلمة إبراهيم بن عبد الله بن عفيف بن نبيه وفي ريطة بنت منبه فإن عمرو بن العاص تزوجها فولدت له عبد الله بن عمرو وهذا الشعر الذي فيه الغناء يقوله في امرأة كان غلب أباها عليها فاستغاث أبوها بالحلفاء من قريش والحلف المعروف بحلف الفضول فانتزعوها من نبيه وردوها على أبيها\nأخبرني الطوسي قال حدثني الزبير بن بكار قال حدثني غير واحد من قريش منهم عبد العزيز بن عمر العنبسي عن مغن واسمه عيينة بن عبد الله بن عنبسة أن رجلا من خثعم قدم مكة تاجرا ومعه ابنة له يقال لها القتول أوضأ نساء العالمين وجها فعلقها نبيه بن الحجاج بن عامر بن حذيفة بن سعد بن سهم فلم يبرح حتى نقلها إليه وغلب أباها عليها فقيل لأبيها عليك بحلف الفضول فأتاهم فشكا ذلك إليهم فأتوا نبيه بن الحجاج فقالوا أخرج ابنة هذا الرجل وهو يومئذ متبد بناحية مكة وهي معه فقال لا أفعل قالوا فإنا من قد عرفت فقال يا قوم متعوني بها الليلة فقالوا قبحك الله ما أجهلك لا والله\nولا شخب لقحة وهي أوسع أحابيك من السائل فأخرجها إليهم فأعطوها أباها وركبوا وركب معهم الخثعمي فلذلك يقول نبيه بن الحجاج\n(راح صحبي ولم أحي القتولا ... لم أودعهم وداعا جميلا)\n(إذ أجد الفضول أن يمنعوها ... قد أراني ولا أخاف الفضولا)\n(لا تخالي أني عشية راح الركب هنتم علي ألا أقولا ... )\n(إنني والذي تحج له شمط ... إياد وهللوا تهليلا)\n(لا تبرأت من قتيلة بالناس ... وهل تبتغون إلا القتولا)\n(لم أخبر عن الحديث ولا أبدأ ... رس الحديث والتقبيلا)\n(ومبيتا بذي المجاز ثلاثا ... ومتى كان حجنا تحليلا)\n(لن أذيع الحديث عنها ولا أنقاد ... لو أبيت فيها فتيلا)\n(أتلوى بها كما تتلوى ... حية الماء بالأباء طويلا)\n(ثم عدوا عداء نخلة ما يدرك ... منهم أدنى رعيل رعيلا)\n(وبنو غالب أولئك قومي ... ومتى يفزعوا تراهم قبيلا)\n(وندامى بيض الوجوه كهول ... وشباب أسهرت ليلا طويلا)\n(غير هجن ولا لئام ولا تعرف ... منهم إلا فتى بهلولا)\nوفي ذلك يقول نبيه بن الحجاج\n(حي الدويرة إذ نأت ... منا على عدوائها)\n(لا بالفراق تنيلنا ... شيئا ولا بلقائها)\n(أخذت حشاشة قلبه ... ونأت فكيف بنائها)\n(حلت تهامة خلة ... من بيتها ووطائها)\n(ولهما بمكة منزل ... من سهلها وحرائها)\n(رفعوا المحلة فوقها ... واستعذبوا من مائها)\n(تدعو شهابا حولها ... وتعم في حلفائها)\n(لولا الفضول وأنه ... لا أمن من عدوائها)\n(لدنوت من أبياتها ... ولطفت حول خبائها)\n(ولجئتها أمشي بلا ... هاد لدى ظلمائها)\n(فشربت فضلة ريقها ... ولبت في أحشائها)","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":1,"spl":"نماذج من شعره","tags":[],"loc":3088,"partial":1},
{"id":"b225-3","bab":"الجزء 17","sec":"نماذج من شعره","page":"ج17 ص283","text":"(فسلي بمكة تخبري ... أنا من أهل وفائها)\n(قدما وأفضل أهلها ... منا على أكفائها)\n(نمشي بألوية الوغى ... ونموت في أودائها)","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":2,"spl":"نماذج من شعره — الحلف ينعقد بوجود رسول الله","tags":["السفر والحج"],"loc":3089},
{"id":"b225-4","bab":"الجزء 17","sec":"حلف الفضول","page":"ج17 ص288","text":"أخبرنا به الطوسي قال حدثنا الزبير بن بكار قال حدثني أبو الحسن الأثرم عن أبي عبيدة قال كان سبب حلف الفضول أن رجلا من أهل اليمن قدم مكة ببضاعة فاشتراها رجل من بني سهم فلوى الرجل بحقه فسأله متاعه فأبى عليه فقام في الحجر فقال\n(يال قصي لمظلوم بضاعته ... ببطن مكة نائي الدار والنفر)\n(وأشعث محرم لم يقض حرمته ... بين المقام وبين الركن والحجر)\nوروى بعض الثقات تماما لهذين البيتين وهو\n(أقائم من بني سهم بذمتهم ... أم ذاهب في ضلال مال معتمر)\n(إن الحرام لمن تمت حرامته ... ولا حرام لثوب الفاجر الغدر)\nال وقال بعض العلماء إن قيس بن شيبة السلمي باع متاعا من أبي بن خلف فلواه وذهب بحقه فاستجار برجل من بني جمح فلم يقم بجواره فقال\n(يال قصي كيف هذا في الحرم ... وحرمة البيت وأعلاق الكرم)\n(أظلم لا يمنع مني من ظلم ... )\nال وبلغ الخبر العباس بن مرداس السلمي فقال\n(إن كان جارك لم تنفعك ذمته ... وقد شربت بكأس الغل أنفاسا)\n(فائت البيوت وكن من أهلها صددا ... لا تلف ناديهم فحشا ولا باسا)\n(وثم كن بفناء البيت معتصما ... تلق ابن حرب وتلق المرء عباسا)\n(قرمى قريش وحلا في ذؤابتها ... بالمجد والحزم ما حازا وما ساسا)\n(ساقي الحجيج وهذا ياسر فلج ... والمجد يورث أخماسا وأسداسا)\nقام العباس وأبو سفيان حتى ردا عليه واجتمعت بطون قريش فتحالفوا على رد الظلم بمكة وألا يظلم رجل بمكة إلا منعوه وأخذوا له بحقه وكان حلفهم في دار ابن جدعان فكان رسول الله يقول ( لقد شهدت حلفا في دار ابن جدعان ما أحب أن لي به حمر النعم ولو دعيت به لأجبت\nقال قوم من قريش هذا والله فضل من الحلف فسمي حلف الفضول قال وقال آخرون تحالفوا على مثل حلف تحالف عليه قوم من جرهم في هذا الأمر ألا يقروا ظلما ببطن مكة إلا غيروه وأسماؤهم الفضل بن شراعة والفضل بن قضاعة والفضل بن سماعة\nقال وحدثني محمد بن فضالة عن عبد الله بن سمعان عن ابن شهاب قال كان شأن حلف الفضول أن بدء ذلك أن رجلا من بني زبيد قدم مكة معتمرا في الجاهلية ومعه تجارة له فاشتراها منه رجل من بني سهم فأواها إلى بيته ثم تغيب فابتغى متاعه الزبيدي فلم يقدر عليه فجاء إلى بني سهم يستعديهم عليه فأغلظوا عليه فعرف أن لا سبيل إلى ماله فطوف في قبائل قريش يستعين\nبهم فتخاذلت القبائل عنه فلما رأى ذلك أشرف على أبي قبيس حتى أخذت قريش مجالسها في المسجد ثم قال\n(يا آل فهر لمظلوم بضاعته ... ببطن مكة نائي الدار والنفر)\n(ومحرم شعث لم يقض عمرته ... يا آل فهر وبين الحجر والحجر)\n(أقائم من بني سهم بخفرتهم ... فعادل أم ضلال مال معتمر)","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":2,"spl":"نماذج من شعره — الحلف ينعقد بوجود رسول الله","tags":["اللهو والمزاح","السفر والحج","الرواية والكتابة"],"loc":3090,"partial":1},
{"id":"b225-5","bab":"الجزء 17","sec":"الحلف ينعقد بوجود رسول الله","page":"ج17 ص290","text":"فلما نزل أعظمت قريش ذلك فتكلموا فيه فقال المطيبون والله لئن قمنا في هذا ليغضبن الأحلاف وقال الأحلاف والله لئن تكلمنا في هذا ليغضبن المطيبون\nوقال ناس من قريش تعالوا فليكن حلفا فضولا دون المطيبين ودون الأحلاف فاجتمعوا في دار عبد الله بن جدعان وصنع لهما طعاما يومئذ كثيرا وكان رسول الله يومئذ معهم قبل أن يوحي الله إليه وهو ابن خمس وعشرين سنة فاجتمعت بنو هاشم وأسد وزهرة وتيم وكان الذي تعاقد عليه القوم تحالفوا على ألا يظلم بمكة غريب ولا قريب ولا حر ولا عبد إلا كانوا معه حتى يأخذوا له بحقه ويؤدوا إليه مظلمته من أنفسهم ومن غيرهم ثم عمدوا إلى ماء من زمزم فجعلوه في جفنة ثم بعثوا به إلى البيت فغسلت به أركانه ثم أتوا به فشربوه\nقال فحدثنا هشام بن عروة عن أبيه عن عائشة أم المؤمنين رضي الله عنها أنها سمعت رسول الله يقول ( لقد شهدت في دار عبد الله بن جدعان حلف الفضول أما لو دعيت إليه اليوم لأجبت وما أحب أن لي به حمر النعم وأني نقضته","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":2,"spl":"نماذج من شعره — الحلف ينعقد بوجود رسول الله","tags":["السفر والحج","الرواية والكتابة"],"loc":3091},
{"id":"b225-6","bab":"الجزء 17","sec":"مبادىء أهل الحلف","page":"ج17 ص291","text":"قال وحدثني عمر بن عبد العزيز العنبسي أن الذي اشترى من الزبيدي المتاع العاص بن وائل السهمي وقال أهل حلف الفضول بنو هاشم وبنو المطلب وبنو أسد بن عبد العزى وبنو زهرة وبنو تيم تحالفوا بينهم ألا يظلم بمكة أحد إلا كنا جميعا مع المظلوم على الظالم حتى نأخذ له مظلمته ممن ظلمه شريفا أو وضيعا منا أو من غيرنا ثم انطلقوا إلى العاص بن وائل ثم قالوا والله لا نفارقك حتى تؤدي إليه حقه فأعطى الرجل حقه فمكثوا كذلك لا يظلم أحد حقه بمكة إلا أخذوه له وكان عتبة بن ربيعة بن عبد شمس يقول لو أن رجلا وحده خرج من قومه لخرجت من عبد شمس حتى أدخل في حلف الفضول وليس عبد شمس في حلف الفضول وحدثني محمد بن حسن عن محمد بن طلحة عن موسى بن عبد الله بن إبراهيم عن أبيه وعن محمد بن فضالة عن هشام بن عروة عن أبيه وعن\nإبراهيم بن محمد وعن أبي عبد الله بن الهاد أن بني هاشم وبني المطلب وبني أسد بن عبد العزى وتيم بن مرة اختلفوا على ألا يدعوا بمكة كلها ولا في الأحابيش مظلوما يدعوهم إلى نصرته إلا أنجدوه حتى يردوا عليه مظلمته أو يبلوا في ذلك عذرا أو على ألا يتركوا لأحد عند أحد فضلا إلا أخذوه وعلى الأمر بالمعروف والنهي عن المنكر - وبذلك سمي حلف الفضول - بالله الغالب أن اليد على الظالم حتى يأخذوا للمظلوم حقه ما بل بحر صوفه وعلى التأسي في المعاش\nقال محمد بن الحسن قال محمد بن طلحة في حديثه عن موسى بن محمد عن أبيه وعن محمد بن فضالة عن أبيه قال لم يكن بنو أسد بن عبد العزى في حلف الفضول\nقال وكان بعد عبد المطلب قال وحدثني محمد بن الحسن عن عيسى بن يزيد بن دأب قال أهل حلف الفضول هاشم وزهرة وتيم قال وقيل له فهل لذلك شاهد من الشعر قال نعم قال أنشدني بعض أهل العلم قول بعض الشعراء\n(تيم بن مرة إن سألت وهاشم ... وزهرة الخير في دار ابن جدعان)\n(متحالفون على الندى ما غردت ... ورقاء في فنن من جزع كتمان)\nفقيل له وأين كتمان فقال واد بنجران فجاء ببيتين مضطربين مختلفي النصفين وحدثني أبو الحسن الأثرم عن أبي عبيدة قال تداعى بنو هاشم وبنو المطلب وبنو أسد بن عبد العزى وبنو زهرة بن كلاب وتيم بن مرة إلى حلف الفضول فاجتمعوا في دار عبد الله بن جدعان فتحالفوا عنده وتعاقدوا ألا يجدوا بمكة مظلوما من أهلها ولا من غيرهم إلا قدموا معه على من ظلمه حتى يردوا مظلمته وشهد النبي هذا الحلف قبل أن يبعث فهذا حلف الفضول\nقال وحدثني إبراهيم بن حمزة عن جدي عبد الله بن مصعب عن أبيه قال إنما سمي حلف الفضول لأنه كان في جرهم رجال يردون المظالم يقال لهم فضيل وفضال وفضل ومفضل\nقال فلذلك سمي حلف الفضول تعاقدوا أن يردوا المظالم قال فتحالفوا بالله الغالب لنأخذن للمظلوم من الظالم وللمقهور من القاهر ما بل بحر صوفه قال وقال أبي قال رسول الله\n(فشهدت حلفا في دار عبد الله بن جدعان لم يزده الإسلام إلا شدة ولهو أحب إلي من حمر النعم ... )\nقال وقال غيره ( لو دعيت إليه لأجبت\nماذا سمي حلف الفضول قال وحدثني محمد بن حسن عن نوفل بن عمارة عن إسحاق بن الفضل قال إنما سمت قريش في هذا الحلف حلف الفضول لأن نفرا من جرهم يقال لهم الفضل وفضال والفضيل تحالفوا على مثل ما تحالفت عليه هذه القبائل قال وحدثني رجل عن محمد بن حسن عن محمد بن فضالة عن هشام\nابن عروة عن أبيه عن عائشة أنها قالت سمعت رسول الله يقول ( لقد شهدت في دار ابن جدعان حلف الفضول أما لو دعيت إليه لأجبت وما أحب أني نقضته وأن لي حمر النعم\nقال الزبير وحدثني علي بن صالح عن جدي عبد الله بن مصعب عن أبيه أن رسول الله قال ( والذي نفسي بيده لقد شهدت في الجاهلية حلفا - يعني حلف الفضول - أما لو دعيت إليه اليوم لأجبت لهو أحب إلي من حمر النعم لا يزيده الإسلام إلا شدة\nال وحدثني أبو الحسن الأثرم عن أبي عبيدة قال حدثني رجل عن محمد بن يزيد الليثي قال سمعت طلحة بن عبد الله بن عوف الزبيري يقول قال رسول الله\nلقد شهدت في دار عبد الله بن جدعان حلفا ما أحب أن لي به حمر النعم ولو أدعى إليه في الإسلام لأجبت","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":3,"spl":"مبادىء أهل الحلف","tags":["السفر والحج"],"loc":3092,"partial":1},
{"id":"b225-7","bab":"الجزء 17","sec":"مبادىء أهل الحلف","page":"ج17 ص291","text":"ال وحدثني محمد بن حسن عن نصر بن مزاحم عن معروف بن خربوذ قال تداعت بنو هاشم وبنو المطلب وأسد وتيم فاحتلفوا على ألا يدعوا بمكة كلها ولا في الأحابيش مظلوما يدعوهم إلى نصرته إلا أنجدوه حتى يردوا إليه مظلمته أو يبلوا في ذلك عذرا وكره ذلك سائر المطيبين والأحلاف من أمره وسموه حلف الفضول عيبا له وقالوا هذا من فضول القوم فسموه حلف الفضول قال وحدثني محمد بن حسن عن إبراهيم بن محمد عن يزيد بن عبد الله بن الهاد عن محمد بن إبراهيم قال\nكان حلف الفضول بين بني هاشم وبني أسد وبني زهرة وبني تيم قال فحدثني أبو خيثمة زهير بن حرب قال حدثني إسماعيل بن إبراهيم عن عبد الرحمن بن إسحاق عن الزهري عن محمد بن حبيب عن أبيه عن عبد الرحمن بن عوف\nقال قال رسول الله شهدت مع عمومتي حلف المكيين فما أحب أن لي حمر النعم وأني أنكثه قال وحدثني محمد بن الحسن عن محمد بن طلحة عن عثمان بن عبد الرحمن بن عثمان بن عبيد الله التيمي أنه بلغه أن الذي بدأ بحلف الفضول من هذه القبائل أمر الغزال الذي سرق من الكعبة\nحدثني محمد بن الحسن قال حدثنا محمد بن طلحة عن موسى بن محمد بن إبراهيم بن الحارث التيمي عن أبيه قال قدم ابن جبير بن مطعم على عبد الملك بن مروان وكان من حلفاء قريش فقال له عبد الملك يا أبا سعيد لم يكن بنو عبد شمس وأنتم يعني بني نوفل في حلف الفضول\nقال وأنتم أعلم يا أمير المؤمنين قال لتحدثني بالحق من ذلك قال لا والله يا أمير المؤمنين لقد خرجنا نحن وأنتم منه ولم تكن يدنا ويدكم إلا جميعا في الجاهلية والإسلام","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":4,"spl":"مبادىء أهل الحلف","tags":["اللهو والمزاح","السفر والحج"],"loc":3093},
{"id":"b225-8","bab":"الجزء 17","sec":"أخبار الحسين بن علي","page":"ج17 ص295","text":"قال وحدثني محمد بن حسن عن إبراهيم بن محمد بن يزيد بن عبد الله بن الهاد الليثي أن محمد بن الحارث التيمي أخبره أنه كان بين الحسين بن علي عليهما السلام وبين الوليد بن عتبة بن أبي\nسفيان كلام والوليد يومئذ أمير المدينة في زمن معاوية بن أبي سفيان في مال كان بينهما بذي المروة فقال الحسين بن علي عليهما السلام استطال علي الوليد بن عتبة في حقي بسلطانه فقلت أقسم بالله لتنصفني في حقي أو لآخذن سيفي ثم لأقومن في مسجد رسول الله ثم لأدعون بحلف الفضول\nقال فقال عبد الله بن الزبير وكان عند الوليد لما قال الحسين ما قال وأنا أحلف بالله لئن دعا به لآخذن سيفي ثم لأقومن معه حتى ينصف من حقه أو نموت جميعا فبلغت المسور بن مخرمة بن نوفل الزهري فقال مثل ذلك فبلغت عبد الرحمن بن عثمان بن عبيد الله التيمي فقال مثل ذلك فلما بلغ الوليد بن عتبة أنصف الحسين من حقه حتى رضي\nقال وحدثني أبو الحسن الأثرم علي بن المغيرة عن أبي عبيدة قال حدثني رجل عن يزيد بن عبد الله بن أسامة الليثي أن محمد بن إبراهيم التيمي حدثه مثل حديث محمد بن حسن الذي قبل هذا\nقال وحدثني إبراهيم بن حمزة عن جدي عبد الله بن مصعب عن أبيه أن الحسين بن علي عليهما السلام كان بينه وبين معاوية كلام في أرض له فقال له الحسين عليه السلام اختر خصلة من ثلاث خصال إما أن تشتري مني حقي\nوإما أن ترده علي أو تجعل بيني وبينك ابن الزبير وابن عمر والرابعة الصيلم قال وما الصيلم قال أن أهتف بحلف الفضول قال فلا حاجة لنا بالصيلم\nقال فخرج وهو مغضب فمر بعبد الله بن الزبير فأخبره فقال والله لئن لم ينصفني لأهتفن بحلف الفضول فقال عبد الله بن الزبير والله لئن هتفت به وأنا مضطجع لأقعدن أو قاعد لأقومن ولئن هتفت به وأنا ماش لأسعين ثم لينفدن روحي مع روحك أو لينصفنك\nقال فخرج عبد الله بن الزبير فدخل على معاوية فباعه منه وخرج عبد الله فجاء إلى الحسين عليه السلام فقال أرسل فانتقد مالك فقد بعته لك\nقال وحدثني علي بن صالح عن جدي عبد الله بن مصعب عن أبيه قال خرج الحسين عليه السلام من عند معاوية فلقي عبد الله بن الزبير والحسين مغضب فذكر الحسين أن معاوية ظلمه في حق له فقال الحسين أخيره في ثلاث خصال والرابعة الصيلم أن يجعلك أو ابن عمر بيني وبينه أو يقر بحقي ثم يسألني فأهبه له أو يشتريه مني فإن لم يفعل فوالذي نفسي بيده لأهتفن بحلف الفضول\nقال ابن الزبير والذي نفسي بيده لئن هتفت به وأنا قاعد لأقومن أو قائم لأمشين أو ماش لأشتدن حتى تفنى روحي مع روحك أو ينصفك قال ثم ذهب ابن الزبير إلى معاوية فقال لقيني الحسين فخيرك في ثلاث خصال والرابعة الصيلم قال معاوية لا حاجة لنا بالصيلم إنك لقيته مغضبا فهات الثلاث قال تجعلني أو ابن عمر بينك وبينه قال فقد جعلتك بيني وبينه أو ابن عمر أو جعلتكما قال أو تقر له بحقه وتسأله إياه قال أنا أقر له بحقه وأسأله إياه قال أو تشتريه منه قال وأنا أشتريه منه قال فلما انتهى إلى الرابعة قال لمعاوية كما قال للحسين عليه السلام إن دعاني إلى حلف الفضول لأجبته فقال معاوية لا حاجة لنا بهذا","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":5,"spl":"أخبار الحسين بن علي","tags":["السفر والحج"],"loc":3094},
{"id":"b225-9","bab":"الجزء 17","sec":"أهل الحلف موضع ثقة","page":"ج17 ص298","text":"قال وبلغني أن عبد الرحمن بن أبي بكرة والمسور بن مخرمة قالا للحسين بن علي عليهما السلام مثل ما قال ابن الزبير فبلغ ذلك معاوية وعنده جبير بن مطعم فقال له معاوية يا أبا محمد أكنا في حلف الفضول\nقال لا قال فكيف كان قال قدم رجل من ثمالة فباع سلعة له من أبي بن خلف بن وهب بن حذافة بن جمح فظلمه وكان يسيء المخالطة فأتى الثمالي إلى أهل حلف الفضول فأخبرهم فقالوا اذهب فأخبره أنك أتينا فإن أعطاك حقك وإلا فارجع إلينا فأتاه فأخبره بما قال له أهل حلف الفضول قال فأخرج إليه ماله وأعطاه إياه بعينه وقال\n(أيأخذني في بطن مكة ظالما ... أبي ولا قومي لدي ولا صحبي)\n(وناديت قومي صارخا ليجيبني ... وكم دون قومي من فياف ومن سهب)\n(ويأبى لكم حلف الفضول ظلامتي ... بني جمح والحق يؤخذ بالغصب)\nقد روى إبراهيم بن المنذر الحزامي في أمر حلف الفضول غير ما رواه الزبير قال إبراهيم حدثني عبد العزيز بن عمران قال قدم أبو الطمحان القيني الشاعر واسمه حنظلة بن الشرقي فاستجار عبد\nالله بن جدعان التيمي ومعه مال له من الإبل فعدا عليه قوم من بني سهم فانتحروا ثلاثة من إبله وبلغه ذلك فأتاهم بمثلها فقال أنتم لها ولأكثر منها أهل فأخذوها فانتحروها ثم أمسكوا عنه زمانا ثم جلسوا على شراب لهم فلما انتشوا غدوا على إبله فاستاقوها كلها فأتى عبد الله بن جدعان يستصرخه فلم يكن فيه ولا في قومه قوة ببني سهم فأمسك عنهم ولم ينصره فقال أبو الطمحان\n(ألا حنت المرقال واشتاق ربها ... تذكر أرماما وأذكر معشري)\n(ولو علمت صرف البيوع لسرها ... بمكة أن تبتاع حمضا بإذخر)\n(أجد بني الشرقي أن أخاهم ... متى يعتلق جارا وإن عز يغدر)\n(إذا قلت واف أدركته دروكه ... فيا موزع الجيران بالغي أقصر)\nم ارتحل عنهم ووفد لميس بن سعد البارقي مكة فاشترى منه أبي بن خلف سلعة فظلمه إياها فمشى في قريش فلم يجره أحد فقال\n(أيظلمني مالي أبي سفاهة ... وبغيا ولا قومي لدي ولا صحبي)\n(وناديت قومي بارقا لتجيبني ... وكم دون قومي من فياف ومن سهب)\nم قدم رجل من بني زبيد فاشترى منه رجل من بني سهم يقال له حذيفة سلعة وظلمه حقه فصعد الزبيدي على أبي قبيس ثم نادى بأعلى صوته\n(يا آل فهر لمظلوم بضاعته ... ببطن مكة نائي الحي والنفر)\n(يا آل فهر لمظلوم ومضطهد ... بين المقام وبين الركن والحجر)\n(إن الحرام لمن تمت حرامته ... ولا حرام لثوب الفاجر الغدر)\nفأعظم الزبير بن عبد المطلب ذلك وقال يا قوم إني والله لأخشى أن يصيبنا ما أصاب الأمم السالفة من ساكني مكة فمشى إلى ابن جدعان وهو يومئذ شيخ قريش فقال له في ذلك وأخبره بظلم بني سهم وبغيهم وقد كان أصاب بني سهم أمران لا يشك أنهما للبغي احتراق المقاييس منهم وهم قيس ومقيس وعبد قيس بصاعقة وأقبل منهم ركب من الشام فنزلوا بماء يقال له القطيعة فصبوا فضلة خمر لهم في إناء وشربوا ثم ناموا وقد بقيت منهم بقية فكرع منها حية أسود ثم تقيأ في الإناء فهب القوم فشربوا منه فماتوا عن آخرهم فأذكره هذا ومثله فتحالف بنو هاشم وبنو المطلب وبنو زهرة وبنو تيم بالله الغالب إنا ليد واحدة على الظالم حتى يرد الحق وخرج سائر قريش من هذا الحلف إلا أن ابن الزبير ادعاه لبني أسد في الإسلام\nقال فأخبرني الواقدي وغيره أن محمد بن جبير بن مطعم دخل على عبد الملك بن مروان فسأله عن حلف الفضول فقال أما أنا وأنت يا أمير المؤمنين فلسنا فيه فقال صدقت والله إني لأعرفك بالصدق\nقال فإن ابن الزبير يدعيه فقال ذاك هو الباطل قال وكان عتبة بن ربيعة يقول لو أن رجلا خرج عن قومه إلى غيرهم لكرم حلف لخرجت عن قومي إلى حلف الفضول\nقال الواقدي قد اختلف فيه لم سمي حلف الفضول فقيل إنه سمي بذلك لأنهم قالوا لا ندع لأحد عند أحد فضلا إلا أخذناه منه وقيل بل سمع بهذا بعض من لم يدخل فيه فقال هذا فضول من الأمر وقال الواقدي والصحيح أن قوما من جرهم يقال لهم فضل وفضالة وفضال\nومفضل تحالفوا على مثل هذا في أيامهم فلما تحالفت قريش هذا الحلف سموا بذلك","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":6,"spl":"أهل الحلف موضع ثقة","tags":["السفر والحج"],"loc":3095},
{"id":"b225-10","bab":"الجزء 17","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج17 ص301","text":"\n(يا للرجال لمظلوم بضاعته ... ببطن مكة نائي الدار والنفر)\n(إن الحرام لمن تمت حرامته ... ولا حرام لثوبي لابس الغدر)\nناه ابن عائشة ثقيل أول بالبنصر عن حبش أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا المدائني عن ابن أبي سبرة عن لقيط بن نصر المحاربي قال كان يزيد بن معاوية أول من سن الملاهي في الإسلام من الخلفاء وآوى المغنين وأظهر الفتك وشرب الخمر وكان ينادم عليها سرجون النصراني مولاه والأخطل وكان يأتيه من المغنين سائب خاثر فيقيم عنده فيخلع عليه ويصله فغناه يوما\n(يا للرجال لمظلوم بضاعته ... ببطن مكة نائي الأهل والنفر)\nاعترته أريحية فرقص حتى سقط ثم قال اخلعوا عليه خلعا يغيب فيها حتى لا يرى منه شيء فطرحت عليه الثياب والجباب والمطارف والخز حتى غاب فيها\n(اشرب هنيئا عليك التاج مرتفقا ... في رأس غمدان دارا منك محلالا)\n(تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nروضه من البسيط المرتفق المتكىء على مرفقه وغمدان اسم قصر كان لسيف بن ذي يزن باليمن والمحلال الدار التي يحل فيها أي يقيم فيها وشيبا معناه خلطا والشوب الخلط يقال شاب كذا بكذا إذا خلطهما الشعر لأمية بن أبي الصلت الثقفي\nوقيل بل هو للنابغة الجعدي وهذا خطأ من قائله وإنما أدخل النابغة البيت الثاني من هذه الأبيات في قصيدة له على جهة التضمين والغناء لسائب خاثر خفيف رمل بالوسطى من رواية حماد عن أبيه وفيه لطويس لحن من كتاب يونس الكاتب غير مجنس","topic":"أخبار نبيه ونسبه","topicNo":225,"sp":7,"spl":"نسبة ما في هذا الخبر من الغناء","tags":[],"song":2,"loc":3096},
{"id":"b226-2","bab":"الجزء 17","sec":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر — خبر أرياط","page":"ج17 ص303 – ج17 ص304","text":"أبو الصلت عبد الله بن أبي ربيعة بن عمرو بن عقدة بن عنزة بن عوف بن قسي وهو ثقيف شاعر من شعراء الجاهلية قديم وهذا الشعر يقوله في سيف بن ذي يزن لما ظفر بالحبشة يهنيه بذلك ويمدحه وكان السبب في قدوم الحبشة اليمن وغلبتهم عليها وخروج سيف بن ذي يزن إلى كسرى يستنجد عليهم أن ملكا من ملوك اليمن يقال له ذو نواس غزا\nأهل نجران وكانوا نصارى فحصرهم ثم إنه ظفر بهم فخدد لهم الأخاديد وعرضهم على اليهودية فامتنعوا من ذلك فحرقهم بالنار وحرق الإنجيل وهدم بيعتهم ثم انصرف إلى اليمن وأفلت منه رجل يقال له دوس ذو ثعلبان على فرس فركضه حتى أعجزهم في الرمل ومضى دوس إلى قيصر ملك الروم يستغيثه ويخبره بما صنع ذو نواس بنجران ومن قتل من النصارى وأنه خرب كنائسهم وبقر النساء وهدم الكنائس فما فيها ناقوس يضرب به فقال له قيصر بعدت بلادي من بلادكم ولكن أبعث إلى قوم من أهل ديني أهل مملكته قريب منكم فينصرونكم\nقال دوس ذو ثعلبان فذاك إذا قال قيصر إن هذا الذي أصنعه بكم أذل للعرب أن يطأها سودان ليس ألوانهم على ألوانهم ولا ألسنتهم على ألسنتهم فقال الملك أنظر لأهل دينه إنما هم خوله فكتب إلى ملك الحبشة أن أنصر هذا الرجل الذي جاء يستنصرني واغضب للنصرانية فأوطىء بلادهم الحبشة\nفخرج دوس ذو ثعلبان بكتاب قيصر إلى ملك الحبشة فلما قرأ كتابه أمر أرياط - وكان عظيما من عظمائهم - أن يخرج معه فينصره فخرج أرياط في سبعين ألفا من الحبشة وقود على جنده قوادا من رؤسائهم وأقبل بفيله وكان معه أبرهة بن الصباح وكان في عهد ملك الحبشة إلى أرياط إذا دخلت اليمن فاقتل ثلث رجالها وخرب ثلث بلادها وابعث إلي بثلث نسائها فخرج أرياط في الجنود فحملهم في السفن في البحر وعبر بهم حتى ورد اليمن وقد قدم مقدمات الحبشة فرأى أهل اليمن جندا كثيرا فلما تلاحقوا قام\nأرياط في جنده خطيبا فقال يا معشر الحبشة قد علمتم أنكم لن ترجعوا إلى بلادكم أبدا هذا البحر بين أيديكم إن دخلتموه غرقتم وإن سلتكم البر هلكتم واتخذتم العرب عبيدا وليس لكم إلا الصبر حتى تموتوا أو تقتلوا عدوكم فجمع ذو نواس جمعا كثيرا ثم سار إليهم فاقتتلوا قتالا شديدا فكانت الدولة للحبشة فظفر أرياط وقتل أصحاب ذي نواس وانهزموا في كل وجه فلما تخوف ذو نواس أن سيؤسر ركض فرسه واستعرض به البحر\nوقال الموت بالبحر أحسن من إسار أسود ثم أقحم فرسه لجة البحر فمضى به فرسه وكان آخر العهد به ثم خرج إليهم ذو جدن الهمداني في قومه فناوشهم وتفرقت عنه همدان فلما تخوف على نفسه\nقال ما الأمر إلا ما صنع ذو نواس فأقحم فرسه البحر فكان آخر العهد به ودخل أرياط اليمن فقتل ثلثا وبعث ثلث السبي إلى ملك الحبشة وخرب ثلثا وملك اليمن وقتل أهلها وهدم حصونها وكانت تلك الحصون بنتها الشياطين في عهد سليمان لبلقيس واسمها بلقمة وكان مما خرب من حصونهم سلحون وبينون وغمدان حصونا لم ير مثلها فقال\nالحميري وهو يذكر ما دخل على حمير من الذل\n(هونك أين ترد العين ما فاتا ... لا تهلكن أسفا في إثر من فاتا)\n(أبعد بينون لا عين ولا أثر ... وبعد سلحون يبني الناس أبياتا)\nال فلما ظفر أرياط أخذ الأموال وأظهر العطاء في أهل الشرف فغضبت الحبشة حين أعطى أشرافهم وترك أهل الفقر منهم واستذلهم وأجاعهم وأعراهم وأتعبهم في العمل وكلفهم ما لا يطيقون فجزع من ذلك الفقراء وشكا ذلك بعضهم إلى بعض وقالوا ما نرانا إلا أذلة أشقياء أينما كنا إن كان قتال قدمنا في نحور العدو وإن كان قتل قتلنا وإن كان عمل فعلينا والبلايا علينا والعطايا لغيرنا مع ما يقصينا ويجفونا","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":0,"spl":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر — خبر أرياط","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3097},
{"id":"b226-3","bab":"الجزء 17","sec":"أبرهة وأرياط","page":"ج17 ص306","text":"فقال لهم عند ذلك رجل من الحبشة يقال له أبرهة من قواد أرياط لو أن رجلا غضب لغضبكم إذا لأسلمتموه حتى يذبح كما تذبح الشاة قالوا لا والمسيح ما كنا نسلمه أبدا فواثقوه بالإنجيل ألا يسلموه حتى يموتوا عن آخرهم\nفنادى منادي فيهم فاجتمعوا إليه فبلغ ذلك أرياط أن أبا أصحم أبرهة جمع لك الجموع ودعا الناس إلى قتالك قال أوقد فعل ذلك أبرهة وهو ممن لا بيت له في الحبشة وغضب أرياط غضبا شديدا\nوقال هو أدنى من ذلك نفسا وبيتا هذا باطل قالوا فأرسل إليه فإن أتاك فهو باطل وإن لم يأتك فاعلم أنه كما يقال فأرسل إليه أجب الملك أرياط فجثا أبرهة على ركبتيه وخر لوجهه وأخذ عودا من الأرض فجعله في فيه\nوقال للرسول اذهب إلى الملك فأخبره بما رأيت مني أنا أخلعه أنا أشد تعظيما له من ذلك وأنا آتيه على أربع قوائم بحساب البهيمة فرجع الرسول إلى الملك فأخبره بالخبر فقال ألم أقل لكم قالوا الملك أعقل وأعلم منا فلما ولى الرسول من عند أبرهة وتوارى عنه صاح أبرهة في الفقراء من الحبشة فاجتمعوا إليه معهم السلاح والآلة التي كانوا يعملون بها ويهدمون بها مدن اليمن المعاول والكرازين والمساحي ثم صفوا صفا وصفوا خلفه آخر بإزائه فلما أبطأ أبرهة على الملك وهو يرى أنه يأتيه على أربع قوائم كما\nقال وأتى الرسول أرياط فأخبره بما صنع أبرهة ركب في الملوك ومن تبعه من أتباعهم فلبسوا السلاح وجاؤوا بالفيلة وكان معه سبعة فيلة حتى إذا دنا بعضهم من بعض برز أبرهة بين الصفين فنادى بأعلى صوته يا معشر الحبشة الله ربنا والإنجيل كتابنا وعيسى نبينا والنجاشي ملكنا علام يقتل بعضنا بعضا في مذهب النصرانية هذا رجل وأنا رجل فخلوا بيني وبينه فإن قتلني عاد الملك إلى ما كان عليه من أثرة الأغنياء وهلاك الفقراء وإن قتلته سلمتم وعملت فيكم بالإنصاف بينكم ما بقيت\nفقال الملوك لأرياط قد أخبرناك أنه صنع ما قد ترى وقد أبيت إلا حسن الرأي فيه وقد أنصفك وكان أرياط قد عرف بالشجاعة والنجدة وكان جميلا وكان أبرهة قصيرا دميما قبيحا منكر الجمة فاستحيا أرياط من الملوك أن يجبن فبرز بين الصفين ومشى أحدهما إلى صاحبه وحمل عليه أرياط فضرب أبرهة ضربة وقع منها حاجباه وعامة أنفه ووقع بين رجلي أرياط فعمد أبرهة إلى عمامته فشد بها وجهه فسكن الدم والتأم الجرح وأخذ عودا وجعله في فيه\nوقال أيها الملك إنما أنا شاة فاصنع ما أردت فقد أبصرت أمري ففرح أرياط بما صنع وكان أبرهة قد سم خنجرا وجعله في بطن فخذه كأنه خافية نسر","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":1,"spl":"أبرهة وأرياط — أبرهة يقتل أرياط","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3098},
{"id":"b226-4","bab":"الجزء 17","sec":"أبرهة يقتل أرياط","page":"ج17 ص307","text":"فلما رأى أبرهة أن أرياط قد أفلت عنه وهو ينظر يمينا وشمالا لئلا تراه ملوك الحبشة استل خنجره فطعنه في فرج درعه فأثبته وخر أرياط على قفاه وقعد أبرهة على صدره فأجهز عليه فسمي أبرهة الأشرم بتلك الضربة التي شرمت وجهه وأنفه فملك أبرهة عشرين سنة ثم ملك بعد أبرهة ابنه يكسوم ثم أخوه مسروق بن أبرهة وأمه ريحانة امرأة ذي يزن أم سيف بن يزن الحميري","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":1,"spl":"أبرهة وأرياط — أبرهة يقتل أرياط","tags":["أمية بن أبي الصلت","الحب والغزل","الجواري والنساء"],"loc":3099},
{"id":"b226-5","bab":"الجزء 17","sec":"تحرك سيف بن ذي يزن","page":"ج17 ص308","text":"فلما طال على أهل اليمن البلاء مشوا إلى سيف بن ذي يزن الحميري فكلموه في الخروج وقالوا إنا نجد فيما روت حمير عن خبر لسطيح أنه يوشك أن هذا البلاء يفرج بيد رجل من أهل بيتك ابن ذي يزن وقد رجونا أن ندرك بثأرنا فأنعم لهم فخرج إلى قيصر ملك الروم فكلمه أن ينصره على الحبشة فأبى\nوقال الحبشة على ديني ودين أهل مملكتي وأنتم على دين يهود فخرج من عنده يائسا فخرج عامدا إلى كسرى فانتهى إلى النعمان بن المنذر بالحيرة فدخل عليه فأخبره بما لقي قومه من الحبشة فقال أقم فإن لي على الملك كسرى إذنا في كل سنة وقد حان ذلك فلما خرج أخرج معه سيف بن ذي يزن فأدخله على كسرى فقال غلبنا على بلادنا وغلب الأحابيش علينا وأنا أقرب إليك منهم لأني أبيض وأنت أبيض وهم سودان فقال بلادك بلاد بعيدة ولا أبعث معك جيشا في غير منفعة ولا أمر أخافه على ملكي فلما أيأسه من النصر أمر له بعشرة آلاف درهم واف وكساه كسا فلما خرج بها من باب كسرى نثرها بين الصبيان والعبيد فرأى ذلك أصحاب كسرى فقالوا ذلك له فأرسل إليه لم صنعت بجائزة الملك تنثرها للصبيان والناس فقال سيف وما أعطاني الملك جبال أرضي ذهب وفضة جئت إلى الملك ليمنعني من الظلم ولم آته ليعطيني الدراهم ولو أردت الدراهم كان ذلك في بلدي كثيرا فقال كسرى أنظر في أمرك فخرج سيف على طمع وأقام عنده فجعل سيف كلما ركب كسرى عرض له فجمع له كسرى مرازبته\nوقال ما ترون في هذا العربي وقد رأيته رجلا جلدا فقال قائل منهم إن في السجون قوما قد سجنهم الملك في موجدة عليهم فلو بعثهم الملك معه فإن قتلوا استراح منهم وإن ظفروا بما يريد هذا العربي فهو زيادة في ملك الملك فقال كسرى هذا الرأي وأمر بهم كسرى فأحضروا فوجد ثمانمائة رجل فولى أمرهم رجلا\nمعهم يقال له وهرز وكان راميا شجاعا مع مكانة في الفرس وجهزهم وأعطاهم سلاحا وحملهم في البحر في ثماني سفن فغرقت سفينتان وبقي من بقي وهم ستمائة رجل فأرسوا إلى ساحل عدن فلما أرسوا قال وهرز لسيف ما عندك فقد جئنا بلادك فقال ما شئت من رجل عربي وفرس عربي ثم اجعل رجلي مع رجلك حتى نموت جميعا أو نظفر جميعا","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":2,"spl":"تحرك سيف بن ذي يزن — وهرز يقتل مسروق بن أبرهة ويملك اليمن","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3100},
{"id":"b226-6","bab":"الجزء 17","sec":"وهرز يقتل مسروق بن أبرهة ويملك اليمن","page":"ج17 ص310","text":"قال وهرز أنصفت فاستجلب سيف من استطاع من اليمن ثم زحفوا إلى مسروق بن أبرهة وقد سمع بهم مسروق وبتعبيتهم فجمع إليه جنده من الحبشة وسار إليهم والتقى العسكران وجعلت أمداد اليمن تثوب إلى سيف وبعث وهرز ابنا له كان معه على جريدة خيل فقال ناوشوهم القتال حتى ننظر قتالهم فناوشهم ابنه وناوشوه شيئا من قتال ثم تورط ابنه في هلكة لم يستطع التخلص منها فاشتملوا عليه فقتلوه فازداد وهرز عليهم حنقا وسيء العرب وفرحت الحبشة فأظهروا الصليب فوتر وهرز قوسه وكان لا يقدر أن يوترها غيرها\nوقال وهرز والناس في صفوفهم انظروا أين ترون ملكهم قال سيف أرى رجلا قاعدا على فيل تاجه على رأسه بين عينيه ياقوتة حمراء قال ذلك ملكهم\nوقال وهرز اتركوه ثم وقف طويلا ثم قال انظروا هل تحول قالوا قد تحول على فرس قال هذا منه اختلاط ثم وقف طويلا وقال انظروا هل تحول قالوا قد تحول على بغلة فقال ابنة الحمار ذل الأسود وذل ملكه ثم\nقال لأصحابه نقتله في هذه الرمية تأملوا النشابة وأخذ النشابة وجعل فوقها في الوتر ثم نزع فيها حتى ملأها وكان أيدا ثم أرسلها فصكت الياقوتة التي بين عيني ملكهم مسروق فتغلغلت النشابة في رأسه حتى خرجت من قفاه وحملت عليهم الفرس فانهزمت الحبشة في كل وجه وجعلت حمير تقتل من\nأدركوا منهم وتجهز على جريحهم وأقبل وهرز يريد أن يدخل صنعاء وكان موضعهم الذي التقوا فيه خارج صنعاء وكان اسم صنعاء أزال فلما قدمت الحبشة بنوها وأحكموها فقالت صنعة فسميت صنعاء وكانت صنعاء مدينة لها باب صغير يدخل منه فلما دنا وهرز من باب المدينة رآه صغيرا فقال لا تدخل رايتي منكسة اهدموا الباب فهدم باب صنعاء ودخل ناصبا رايته وسير بها بين يديه فقال سيف بن ذي يزن ذهب ملك حمير آخر الدهر لا يرجع إليهم أبدا فملك وهرز اليمن وقهر الحبشة وكتب إلى كسرى يخبره إني قد ملكت للملك اليمن وهي أرض العرب القديمة التي تكون فيها ملوكهم وبعث بجوهر وعنبر ومال وعود وزباد وهو جلود لها رائحة طيبة","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":2,"spl":"تحرك سيف بن ذي يزن — وهرز يقتل مسروق بن أبرهة ويملك اليمن","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3101},
{"id":"b226-8","bab":"الجزء 17","sec":"كسرى يملك سيفا اليمن والحبشة يغتالونه — أمية يمدح سيفا","page":"ج17 ص311 – ج17 ص312","text":"فكتب كسرى يأمره أن يملك سيفا ويقدم وهرز إلى كسرى فخلف على اليمن سيفا فلما خلا سيف باليمن وملكها عدا على الحبشة فجعل يقتل رجالها ويبقر نساءها عما في بطونها حتى أفناها إلا بقايا منها أهل ذلة وقلة فاتخذهم خولا واتخذ منهم جمازين بحرابهم بين يديه فمكث كذلك غير كثير وركب يوما وتلك الحبشة معه ومعهم حرابهم يسعون بها بين يديه حتى إذا كان وسطا منهم مالوا عليه بحرابهم فطعنوه حتى قتلوه وكان سيف قد آلى ألا يشرب الخمر ولا يمس امرأة حتى يدرك ثأره من\nالحبشة فجعلت له حلتان واسعتان فأتزر بواحدة وارتدى الأخرى وجلس على رأس غمدان يشرب وبرت يمينه وخرج بعد ذلك يتصيد فقتلته الحبشة وكان ملك أرياط عشرين سنة وملك أبرهة ثلاثا وعشرين سنة وملك يكسوم تسع عشرة سنة وملك مسروق اثنتي عشرة سنة فهذه أربع وسبعون سنة وكان قدوم أهل فارس اليمن مع وهرز بعد الفجار بعشر سنين وقبل بنيان قريش البيت بخمس سنين ورسول الله وآله ابن ثلاثين سنة أو نحوها لأن رسول الله ولد بعد قدوم الفيل بخمس وخمسين ليلة ونسخت خبر مديحه سيفا بهذا الشعر من كتاب عبد الأعلى بن حسان\nقال حدثنا الكلبي عن أبي صالح عن ابن عباس وحدثني به محمد بن عمران المؤدب بإسناد لست أحفظ الاتصال بينه وبين الكلبي فيه فاعتمدت هذه الرواية\nقال لما ظفر سيف بن ذي يزن بالحبشة وذلك بعد مولد النبي بسنتين أتته وفود العرب وأشرافها لتهنيه وتمدحه وتذكر ما كان من بلائه وطلبه بثأر قومه فأتته وفود العرب من قريش فيهم عبد المطلب بن هاشم وأمية بن عبد شمس وخويلد بن أسد في ناس من وجوه قريش فأتوه بصنعاء وهو في رأس قصر\nله يقال له غمدان فأخبره الآذن بمكانهم فأذن لهم فدخلوا عليه وهو على شرابه وعلى رأسه غلام واقف ينثر في مفرقه المسك وعن يمينه ويساره الملوك والمقاول وبين يديه أمية بن أبي الصلت الثقفي ينشده قوله في هذه الأبيات\n(لا يطلب الثأر إلا كابن ذي يزن ... في البحر خيم للأعداء أحوالا)\n(أتى هرقل وقد شالت نعامته ... فلم يجد عنده النصر الذي سالا)\n(ثم انتحى نحو كسرى بعد عاشرة ... من السنين يهين النفس والمالا)\n(حتى أتى ببني الأحرار يقدمهم ... تخالهم فوق متن الأرض أجبالا)\n(لله درهم من فتية صبروا ... ما إن رأيت لهم في الناس أمثالا)\n(بيض مرازبة غلب أساورة ... أسد تربت في الغيضات أشبالا)\n(فالتط من المسك إذ شالت نعامتهم ... وأسبل اليوم في برديك إسبالا)\n(واشرب هنيئا عليك التاج مرتفقا ... في رأس غمدان دارا منك محلالا)\n(تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nبنو الأحرار الذين عناهم أمية في شعره هم الفرس الذين قدموا مع سيف بن ذي يزن وهم إلى الآن يسمون بني الأحرار بصنعاء ويسمون باليمن الأبناء وبالكوفة الأحامرة وبالبصرة الأساورة وبالجزيرة الخضارمة وبالشام الجراجمة","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":3,"spl":"كسرى يملك سيفا اليمن والحبشة يغتالونه — أمية يمدح سيفا","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3102},
{"id":"b226-9","bab":"الجزء 17","sec":"عبد المطلب يهنىء سيفا وسيف يسر إليه بأمارات ظهور النبي","page":"ج17 ص313","text":"فبدأ عبد المطلب فاستأذن في الكلام فقال له سيف بن ذي يزن إن كنت ممن يتكلم بين يدي الملوك فقد أذنا لك فقال عبد المطلب إن الله قد أحلك أيها الملك محلا رفيعا صعبا منيعا شامخا باذخا وأنبتك منبتا طابت أرومته وعزت جرثومته في أكرم موطن وأطيب معدن فأنت - أبيت اللعن - ملك\nالعرب وربيعها الذي به تخصب وأنت أيها الملك رأس العرب الذي له تنقاد وعمودها الذي عليه العماد ومعقلها الذي إليه يلجأ العباد فسلفك لنا خير سلف وأنت لنا منهم خير خلف فلم يخمل من أنت خلفه ولن يهلك من أنت سلفه نحن أهل حرم الله وسدنة بيته أشخصنا إليك الذي أبهجنا لكشفك الكرب الذي فدحنا فنحن وفود التهنية لا وفود المرزية\nقال وأيهم أنت المتكلم قال أنا عبد المطلب بن هاشم قال ابن أختنا قال نعم فأدناه حتى أجلسه إلى جنبه ثم أقبل على القوم وعليه فقال مرحبا وأهلا وناقة ورحلا ومستناخا سهلا وملكا ربحلا يعطي عطاء جزلا قد سمع الملك مقالتكم وعرف قرابتكم وقبل وسيلتكم وأنتم أهل الشرف والنباهة ولكم الكرامة ما أقمتم والحباء إذا ظعنتم ثم استنهضوا إلى دار الضيافة والوفود فأقاموا فيها شهرا لا يصلون إليه ولا يؤذن لهم في الانصراف وأجرى لهم الأنزال ثم انتبه لهم انتباهة فأرسل إلى عبد المطلب فأدناه وأخلى مجلسه ثم\nقال يا عبد المطلب إني مفوض إليك من سر علمي أمرا لو يكون غيرك لم أبح به إليه ولكني رأيتك موضعه فأطلعتك طلعه فليكن عندك مطويا حتى يأذن الله فيه فإن الله بالغ أمره إني أجد في الكتاب المكنون والعلم المخزون الذي اخترناه لأنفسنا واحتجناه دون غيرنا خبرا عظيما وخطرا جسيما فيه شرف الحياة وفضيلة الوفاء للناس عامة ولرهطك كافة ولك خاصة قال عبد المطلب مثلك أيها الملك من سر وبر فما هو فداك أهل الوبر زمرا بعد زمر قال ابن ذي يزن إذا ولد غلام بتهامة بين كتفيه شامة\nكانت له الإمامة ولكم به الزعامة إلى يوم القيامة قال عبد المطلب أيها الملك لقد أبت بخير ما آب بمثله وافد ولولا هيبة الملك وإكرامه وإعظامه لسألته أن يزيدني في البشارة ما أزداد به سرورا\nقال ابن ذي يزن هذا حينه الذي يولد فيه أو قد ولد اسمه محمد يموت أبوه وأمه ويكفله جده وعمه قد ولدناه مرارا والله باعثه جهارا وجاعل له منا أنصارا يعز بهم أولياءه ويذل بهم أعداءه يضرب بهم الناس عن عرض ويستبيح بهم كرائم الأرض يخمد النيران ويدحر الشيطان ويكسر الأوثان ويعبد الرحمن قوله فصل وحكمه عدل يأمر بالمعروف ويفعله وينهى عن المنكر ويبطله فقال عبد المطلب أيها الملك عز جدك وعلا كعبك ودام ملكك وطال عمرك فهل الملك مخبري بإفصاح فقد أوضح لي بعض الإيضاح فقال ابن ذي يزن والبيت ذي الحجب والعلامات على النصب إنك يا عبد المطلب لجده غير الكذب","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":4,"spl":"عبد المطلب يهنىء سيفا وسيف يسر إليه بأمارات ظهور النبي","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3103},
{"id":"b226-11","bab":"الجزء 17","sec":"سيف يطلب كتم أمر محمد والحذر من اليهود — سيف يكرم بعثة عبد المطلب ويجزلها العطاء","page":"ج17 ص315 – ج17 ص316","text":"فخر عبد المطلب ساجدا فقال له ارفع رأسك ثلج صدرك وعلا أمرك فهل أحسست شيئا مما ذكرته لك فقال عبد المطلب أيها الملك كان لي ابن وكنت به معجبا وعليه رفيقا زوجته كريمة من كرائم قومي اسمها آمنة بنت وهب فجاءت بغلام سميته محمدا مات أبوه وأمه وكفلته أنا وعمه\nقال الأمر ما قلت لك فاحتفظ بابنك واحذر عليه من اليهود فإنهم له أعداء ولن يجعل الله لهم عليه سبيلا واطو ما ذكرت لك عن هؤلاء الرهط الذين معك فإني لا آمن أن تدخلهم النفاسة من أن تكون له الرياسة فينصبون له الحبائل ويطلبون له الغوائل وهم فاعلون وأبناؤهم وبطيء ما يجيبه قومه وسيلقى منهم عنتا والله مبلج حجته ومظهر دعوته وناصر شيعته ولولا أني أعلم أن الموت مجتاحي قبل مبعثه لسرت بخيلي ورجلي حتى أصير يثرب دار ملكي فإني أجد\nفي الكتاب المكنون أن بيثرب استحكام أمره وأهل نصرته وموضع قبره ولولا أني أتوقى عليه الآفات وأحذر عليه العاهات لأعلنت على حداثة سنه أمره ولكني صارف ذلك إليك من غير تقصير مني بمن معك\nقال ثم أمر لكل رجل بعشرة أعبد وعشر إماء ومائة من الإبل وحلتين برودا وخمسة أرطال ذهبا وعشرة أرطال فضة وكرش مملوءة عنبرا ثم أمر لعبد المطلب بعشرة أضعاف ذلك\nوقال يا عبد المطلب إذا حال الحول فائتني فمات ابن ذي يزن قبل أن يحول الحول وكان عبد المطلب كثيرا ما يقول يا معشر قريش لا يغبطني رجل منكم بجزيل عطاء الملك وإن كثر فإنه إلى نفاد ولكن ليغبطني بما بقي لي شرفه وذكره إلى يوم القيامة فإذا قيل له وما ذاك قال ستعلمون نبأ ما أقول ولو بعد حين وفي ذلك يقول أمية بن عبد شمس\n(جلبنا النصح تحمله المطايا ... الى أكوار أجمال ونوق)\n(مغلغلة مرافقها ثقالا ... الى صنعاء من فج عميق)\n(تؤم بنا ابن ذي يزن ونهدي ... مخاليها إلى أمم الطريق)\n(فلما وافقت صنعاء صارت ... بدار الملك والحسب العريق)\nخبرني علي بن عبد العزيز قال حدثني عبد الله بن عبد الله بن خرداذبة قال\nكان أحمد بن سعيد بن قادم المعروف بالمالكي أحد القواد مع طاهر بن الحسين بن عبد الله بن طاهر فكان معه بالري وكان مع محله من خدمة السلطان مغنيا حسن الغناء وله صنعة فحضر مجلس طاهر بن عبد الله وهو متنزه بظاهر الري بموضع يعرف بشاذمهر وقيل بل حضره بقصره بالشاذياخ فغنى هذا الصوت\n(اشرب هنيئا عليك التاج مرتفقا ... في رأس غمدان . . . . . البيت)\nقال ابن عباد الرازي في وقته من الشعر مثل ذلك المعنى وصنع فيه وغنى فيه أحمد بن سعيد لحنا من خفيف الرمل وهو\n(اشرب هنيئا عليك التاج مرتفقا ... بالشاذياخ ودع غمدان لليمن)\n(فأنت أولى بتاج الملك تلبسه ... من هوذة بن علي وابن ذي يزن)\nطرب طاهر فاستعاده مرات وشرب عليه حتى سكر وأسنى لأحمد بن سعيد الجائزة\nأما ذكره هوذة بن علي ولبسه التاج فإن السبب في ذلك أن كسرى توج هوذة بن علي الحنفي وضم إليه جيشا من الأساورة فأوقع ببني تميم","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":5,"spl":"سيف يطلب كتم أمر محمد والحذر من اليهود — سيف يكرم بعثة عبد المطلب ويجزلها العطاء","tags":["أمية بن أبي الصلت"],"song":1,"loc":3104},
{"id":"b226-12","bab":"الجزء 17","sec":"يوم الصفقة","page":"ج17 ص318","text":"يوم الصفقة أخبرني بالسبب في ذلك علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال حدثنا ابن حبيب ودماذ عن أبي عبيدة قال ابن حبيب\nقال أبو سعيد وأخبرنا إبراهيم بن سعدان عن أبيه عن أبي عبيدة قال ابن حبيب وأخبرني ابن الأعرابي عن المفضل قال أبو سعيد قالوا جميعا كان من حديث يوم الصفقة أن باذام عامل كسرى باليمن بعث إلى كسرى عيرا تحمل ثيابا من ثياب اليمن ومسكا وعنبرا وخرجين فيهما مناطق محلاة وخفراء تلك العير فيما يزعم بعض الناس بنو الجعيد المراديون فساروا من اليمن لا يعرض لهم أحد حتى إذا كان بحمض من بلاد بني حنظلة بن يربوع وغيرهم أغاروا عليها فقتلوا من فيها من بني جعيد والأساورة واقتسموها وكان فيمن فعل ذلك ناجية بن عقال وعتبة بن الحارث بن شهاب وقعنب بن عتاب وجزء بن سعد وأبو مليل عبد الله بن الحارث والنطف بن جبير وأسيد بن جنادة فبلغ ذلك الأساورة الذين بهجر مع كزارجر المكعبر فساروا إلى بني حنظلة بن يربوع فصادفوهم على حوض فقاتلوهم قتالا شديدا فهزمت الأساورة وقتلوا قتلا شديدا ذريعا ويومئذ أخذ النطف الخرجين اللذين يضرب بهما المثل\nفلما بلغ ذلك كسرى استشاط غضبا وأمر بالطعام فادخر بالمشقر ومدينة اليمامة وقد أصابت الناس سنة شديدة ثم قال من دخلها من العرب فأميروه ما شاء فبلغ ذلك الناس\nقال وكان أعظم من أتاها بنو سعد فنادى منادي الأساورة لا يدخلها عربي بسلاح فأقيم بوابون على باب المشقر فإذا جاء الرجل ليدخل قالوا ضع سلاحك وامتر واخرج من الباب الآخر فيذهب به إلى رأس الأساورة فيقتله فيزعمون أنا خيبري بن عبادة بن النوال بن مرة بن عبيد - وهو مقاعس -\nقال يا بني تميم ما بعد السلب إلا القتل وأرى قوما يدخلون ولا يخرجون فانصرف منهم من انصرف من بقيتهم فقتلوا بعضهم وتركوا بعضا محتبسين عندهم هذا حديث المفضل وأما ما وجد عن ابن الكلبي في كتاب حماد الراوية فإن كسرى بعث إلى عامله باليمن بعير وكان باذام على الجيش الذي بعثه كسرى إلى اليمن وكانت العير تحمل نبعا فكانت تبذرق من المدائن حتى تدفع إلى النعمان ويبذرقها النعمان بخفراء من بني ربيعة ومضر حتى يدفعها إلى هوذة بن علي الحنفي فيبذرقها حتى يخرجها من أرض بني حنيفة ثم تدفع إلى سعد وتجعل لهم جعالة فتسير فيها فيدفعونها إلى عمال باذام باليمن\nفلما بعث كسرى بهذه العير قال هوذة للأساورة انظروا الذي تجعلونه لبني تميم فأعطونيه فأنا أكفيكم أمرهم وأسير فيها معكم حتى تبلغوا مأمنكم فخرج هوذة والأساورة والعير معهم من هجر حتى إذا كانوا بنطاع بلغ بني سعد ما صنع هوذة فساروا إليهم وأخذوا ما كان معهم واقتسموه وقتلوا عامة الأساورة وسلبوهم وأسروا هوذة بن علي فاشترى هوذة نفسه بثلاثمائة بعير فساروا معه إلى هجر فأخذوا منه فداءه ففي ذلك يقول شاعر بني سعد\n(ومنا رئيس القوم ليلة أدلجوا ... بهوذة مقرون اليدين إلى النحر)\n(وردنا به نخل اليمامة عانيا ... عليه وثاق القد والحلق السمر)\nعمد هوذة عند ذلك إلى الأساورة الذين أطلقهم بنو سعد وكانوا قد سلبوا فكساهم وحملهم ثم انطلق معهم إلى كسرى وكان هوذة رجلا جميلا شجاعا لبيبا فدخل عليه فقص أمر بني تميم وما صنعوا فدعا كسرى بكأس من ذهب فسقاه فيها وأعطاه إياها وكساه قباء ديباج منسوجا بالذهب واللؤلؤ وقلنسوة قيمتها ثلاثون ألف درهم وهو قول الأعشى\n(له أكاليل بالياقوت فصلها ... صواغها لا ترى عيبا ولا طبعا)\nذكر أن كسرى سأل هوذة عن ماله ومعيشته فأخبره أنه في عيش رغد وأنه يغزو المغازي فيصيب فقال له كسرى في ذلك كم ولدك قال عشرة قال فأيهم أحب إليك قال غائبهم حتى يقدم وصغيرهم حتى يكبر ومريضهم حتى يبرأ قال كسرى الذي أخرج منك هذا العقل حملك على أن طلبت مني الوسيلة وقال\nكسرى لهوذة رأيت هؤلاء الذين قتلوا أساورتي وأخذوا مالي أبينك وبينهم صلح قال هوذة أيها الملك بيني وبينهم حساء الموت وهم قتلوا أبي فقال كسرى قد أدركت ثأرك فكيف لي بهم","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":6,"spl":"يوم الصفقة","tags":["أمية بن أبي الصلت"],"loc":3105},
{"id":"b226-13","bab":"الجزء 17","sec":"يوم الصفقة","page":"ج17 ص318","text":"قال هوذة إن أرضهم لا تطيقها أساورتك وهم يمتنعون بها ولكن احبس عنهم الميرة فإذا فعلت ذلك بهم سنة أرسلت معي جندا من أساورتك فأقيم لهم السوق فإنهم يأتونها فتصيبهم عند ذلك خيلك ففعل كسرى ذلك وحبس عنهم الأسواق في سنة مجدبة ثم سرح إلى هوذة فأتاه فقال ائت هؤلاء فاشفني منهم واشتف وسرح معهم جوار بودار ورجلا من أردشير خره فقال لهوذة سر مع رسولي هذا فسار في ألف أسوار حتى نزلوا المشقر من أرض البحرين وهو حصن هجر وبعث هوذة إلى بني حنيفة فأتوه فدنوا من حيطان المشقر ثم نودي إن كسرى قد بلغه الذي أصابكم في هذه السنة وقد أمر لكم بميرة فتعالوا فامتاروا فانصب عليهم الناس وكان أعظم من أتاهم بنو سعد فجعلوا إذا جاؤوا إلى باب المشقر أدخلوا رجلا رجلا حتى يذهب به إلى المكعبر فتضرب عنقه وقد وضع سلاحه قبل أن يدخل فيقال له ادخل من هذا الباب واخرج من الباب الآخر فإذا مر رجل من بني سعد بينه وبين هوذة إخاء أو رجل يرجوه قال للمكعبر هذا من قومي فيخليه له فنظر خيبري بن عبادة إلى قومه يدخلون ولا يخرجون وتؤخذ أسلحتهم\nوجاء ليمتار فلما رأى ما رأى قال ويلكم أين عقولكم فوالله ما بعد السلب إلا القتل وتناول سيفا من رجل من بني سعد يقال له مصاد وعلى باب المشقر سلسلة ورجل من الأساورة قابض عليها فضربها فقطعها ويد الأسوار فانفتح الباب فإذا الناس يقتلون فثارت بنو تميم ويقال إن الذي فعل هذا رجل من بني عبس يقال له عبيد بن وهب فلما علم هوذة أن القوم قد نذروا به أمر المكعبر فأطلق منهم مائة من خيارهم وخرج هاربا من الباب الأول هو والأساورة فتبعتهم بنو سعد والرباب فقتل بعضهم وأفلت من أفلت\n(إذا سلكت حوران من رمل عالج ... فقولا لها ليس الطريق هنالك)\n(دعوا فلجات الشام قد حيل دونها ... بضرب كأفواه العشار الأوارك)\nروضه من الطويل الشعر لحسان بن ثابت والغناء لابن محرز ولحنه من القدر الأوسط من الثقيل الأول مطلق في مجرى البنصر وهذا الشعر يقوله حسان بن ثابت لقريش حين تركت الطريق الذي كانت تسلكه إلى الشام بعد غزوة بدر واستأجرت فرات بن حيان العجلي دليلا فأخذ\nبهم غيرها وبلغ النبي الخبر فأرسل زيد بن حارثة في سرية إلى العير فظفر بها وأعجزه القوم","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":7,"spl":"يوم الصفقة","tags":["أمية بن أبي الصلت"],"song":1,"loc":3106},
{"id":"b226-14","bab":"الجزء 17","sec":"ذكر الخبر في سرية زيد بن حارثة","page":"ج17 ص324","text":"أخبرني الحسن بن علي الخفاف قال حدثنا الحارث بن أبي أسامة قال حدثنا محمد بن سعد عن الواقدي قال كان سبب هذه الغزوة أن قريشا قالت قد عور علينا محمد متجرنا وهو على طريقنا\nوقال أبو سفيان وصفوان بن أمية إن أقمنا بمكة أكلنا رؤوس أموالنا فقال زمعة بن الأسود وأنا أدلكم على رجل يسلك بكم النجدة ولو سلكها مغمض العين لاهتدى فقال صفوان من هو\nقال فرات بن حيان العجلي فاستأجراه فخرج بهم في الشتاء فسلك بهم ذات عرق ثم سلك بهم على غمرة فانتهى إلى النبي خبر العير فخرج وفيها مال كثير وآنية\nمن فضة حملها صفوان بن أمية فخرج زيد بن حارثة فاعترضها فظفر بالعير وأفلت أعيان القوم وكان الخمس عشرين ألفا فأخذه رسول الله فقسم الأربعة الأخماس على السرية وأتي بفرات بن حيان العجلي أسيرا فقيل له إن أسلمت لم يقتلك رسول الله فلما دعا به رسول الله أسلم فأرسله\nحدثنا محمد بن جرير الطبري قال حدثنا محمد بن حميد قال حدثنا سلمة عن محمد بن إسحاق في خبر هذه السرية بمثل رواية الواقدي وزاد فيها فيما رواه إن قريشا لما خافت طريقها إلى الشام أخذت على طريق العراق\nوذكر أن الوقعة كانت على القردة ماء من مياه نجد أخبرني حرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني يعقوب بن محمد الزهري قال كتب إبراهيم بن هشام إلى هشام بن عبد الملك إن رأى أمير المؤمنين إذا فرغ من دعوة أعمامه بني عبد مناف أن يبدأ بدعوة أخواله بني مخزوم فكتب إن رضي بذلك آل الزبير فافعل فلما فرغ من إعطاء بني عبد مناف نادى مناديه ببني مخزوم فناداه عثمان بن عروة وقال\n(إذا هبطت حوران من أرض عالج ... فقولا لها ليس الطريق هنالك)\nأمر مناديه فنادى بني أسد بن عبد العزى ثم مضى على الدعوة أخبرني محمد بن عبد الله الحضرمي إجازة قال حدثنا ضرار بن صرد\nقال حدثنا علي بن هشام عن عمار بن زريق عن أبي إسحاق عن عدي بن حاتم أن النبي أتي بفرات بن حيان فقال إني مسلم فقال لعلي صلوات الله عليه إن منكم من أكله إلى إيمانه منهم فرات بن حيان وأقطعه أرضا بالبحرين تغل ألفا ومائتين\nحدثني أحمد بن يوسف بن سعيد قال حدثنا محمد بن عبيد الله بن عتبة قال حدثنا موسى بن زياد الزيات قال حدثنا عبد الرحمن بن سليمان الأشل عن زكريا بن أبي زائدة عن أبي إسحاق عن جارية بن مضرب عن أمير المؤمنين علي صلوات الله عليه\nقال أتى النبي بفرات بن حيان يوم الخندق وكان عينا للمشركين فأمر بقتله فقال إني مسلم فقال إن منكم من أتألفه على الإسلام وأكله إلى إيمانه منهم فرات بن حيان\n(إذا المرء لم يطلب معاشا لنفسه ... شكى الفقر أو لام الصديق فأكثرا)\n(وصار على الأدنين كلا وأوشكت ... صلات ذوي القربى له أن تنكرا)\n(فسر في بلاد الله والتمس الغنى ... تعش ذا يسار أو تموت فتعذرا)\n(ولا ترض من عيش بدون ولا تنم ... وكيف ينام الليل من كان معسرا)\nروضه من الطويل الشعر لأبي عطاء السندي والغناء لإبراهيم خفيف ثقيل بالوسطى من نسخة عمرو الثانية","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":8,"spl":"ذكر الخبر في سرية زيد بن حارثة","tags":["أمية بن أبي الصلت"],"song":1,"loc":3107},
{"id":"b226-16","bab":"الجزء 17","sec":"ذكر أبي عطاء السندي — نماذج من شعره","page":"ج17 ص326 – ج17 ص327","text":"أبو عطاء اسمه أفلح بن يسار مولى بني أسد ثم مولى عنبر بن سماك ابن حصين الأسدي منشؤه الكوفة وهو من مخضرمي الدولتين مدح بني أمية وبني هاشم وكان أبوه يسار سنديا أعجميا لا يفصح وكان في لسان أبي عطاء لكنة شديدة ولثغة فكان لا يفصح وكان له غلام فصيح سماه عطاء وتكنى به وقال قد جعلتك ابني وسميتك بكنيتي فكان يرويه شعره فإذا مدح من يجتديه أو ينتجعه أمره بإنشاده ما قاله وكان ابن كناسة يذكر أنه كاتب مواليه وأنهم لم يعتقوه\nأخبرني بذلك محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن ابن كناسة قال كثر مال أبي عطاء السندي بعد أن أعتق فأعنته مواليه وطمعوا فيه وادعوا رقه فشكا ذلك إلى إخوانه فقالوا له كاتبهم فكاتبوه على أربعة آلاف وسعى له أهل الأدب والشعر فيها فتركهم وأتى الحر بن عبد الله القرشي وهو حليف لقريش لا من أنفسهم فقال فيه\n(أتيتك لا من قربة هي بيننا ... ولا نعمة قدمتها أستثيبها)\n(ولكن مع الراجين أن كنت موردا ... إليه بغاة الدين تهفو قلوبها)\n(أغثني بسجل من نداك يكفني ... وقاك الردى مرد الرجال وشيبها)\n(تسمى ابن عبدالله حرا لوصفه ... وتلك العلا يعنى بها من يصيبها)\nأعطاه أربعة آلاف درهم فأداها في مكاتبته وعتق أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه قال كان أبو عطاء السندي يجمع بين لثغة ولكنة وكان لا يكاد يفهم كلامه فأتى سليمان ابن سليم فأنشده\n(أعوزتني الرواة يابن سليم ... وأبى أن يقيم شعري لساني)\n(وغلى بالذي أجمجم صدري ... وجفاني بعجمتي سلطاني)\n(وازدرتني العيون إذ كان لوني ... حالكا مجتوى من الألوان)\n(فضربت الأمور ظهرا لبطن ... كيف أحتال حيلة للساني)\n(وتمنيت أنني كنت بالشعر ... فصيحا وبان بعض بناني)\n(ثم أصبحت قد أنخت ركابي ... عند رحب الفناء والأعطان)\n(فاكفني ما يضيق عنه رواتي ... بفصيح من صالح الغلمان)\n(يفهم الناس ما أقول من الشعر ... فإن البيان قد أعياني)\n(فاعتمدني بالشكر يابن سليم ... في بلادي وسائر البلدان)\n(ستوافيهم قصائد غر ... فيك سباقة لكل لسان)\n(فقديما جعلت شكري جزاء ... كل ذي نعمة بما أولاني)\n(لم تزل تشتري المحامد قدما ... بالربيح الغالي من الأثمان)\nأمر له بوصيف بربري فصيح فسماه عطاء وتكنى به ورواه شعره فكان إذا أراد إنشاد مديح لمن يجتديه أو مذاكرة لشعره أنشده","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":9,"spl":"ذكر أبي عطاء السندي — نماذج من شعره — أبو عطاء يهجو عنبر الأسدي","tags":["أمية بن أبي الصلت","المديح"],"loc":3108},
{"id":"b226-17","bab":"الجزء 17","sec":"أبو عطاء يهجو عنبر الأسدي","page":"ج17 ص329","text":"أخبرني علي بن سليمان الأخفش قال حدثنا ثعلب عن أبي العالية الحر بن مالك الشامي قال لما أثرى أبو عطاء أعنته مولاه عنبر بن سماك الأسدي حتى ابتاع نفسه منه فقال يهجوه\n(إذا ما كنت متخذا خليلا ... فلا تثقن بكل أخي إخاء)\n(وإن خيرت بينهم فألصق ... بأهل العقل منهم والحياء)\n(فإن العقل ليس له إذا ما ... تذوكرت الفضائل من كفاء)\n(وإن النوك للأحساب غول ... به تأوي إلى داء عياء)\n(فلا تثقن من النوكى بشيء ... ولو كانوا بني ماء السماء)\n(كعنبر الوثيق بناء بيت ... ولكن عقله مثل الهباء)\n(وليس بقابل أدبا فدعه ... وكن منه بمنقطع الرجاء)\nال وكان أبو عطاء من شعراء بني أمية ومداحهم والمنصبي الهوى إليهم\nوأدرك دولة بني العباس فلم تكن له فيها نباهة فهجاهم وفي آخر أيام المنصور مات وكان مع ذلك من أحسن الناس بديهة وأشدهم عارضة وتقدما وشهد أبو عطاء حرب بني أمية وبني العباس فأبلى وقتل غلامه عطاء مع ابن هبيرة وانهزم هو\nوقيل بل كان أبو عطاء المقتول معه لا غلامه أخبرني الحسن بن علي عن أحمد بن الحارث عن المدائني قال كان أبو عطاء يقاتل المسودة وقدامه رجل من بني مرة يكنى أبا يزيد وقد عقر فرسه فقال لأبي عطاء أعطني فرسك حتى أقاتل عني وعنك وقد كانا أيقنا بالهلاك فأعطاه أبو عطاء فرسه فركبه المري ثم مضى وترك أبا عطاء فقال أبو عطاء في ذلك\n(لعمرك إنني وأبا يزيد ... لكالساعي إلى وضح السراب)\n(رأيت مخيلة فطمعت فيها ... وفي الطمع المذلة للرقاب)\n(فما أعياك من طلب ورزق ... كما يعييك في سرق الدواب)\n(وأشهد أن مرة حي صدق ... ولكن لست منهم في النصاب)\nخبرني الحسن عن أحمد بن الحارث عن المدائني\nأن يحيى بن زياد الحارثي وحمادا الراوية كان بينهما وبين معلى بن هبيرة ما يكون مثله بين الشعراء والرواة من النفاسة وكان معلى بن هبيرة يحب أن يطرح حمادا في لسان شاعر يهجوه","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":9,"spl":"ذكر أبي عطاء السندي — نماذج من شعره — أبو عطاء يهجو عنبر الأسدي","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3109},
{"id":"b226-18","bab":"الجزء 17","sec":"أبو عطاء وحماد الراوية","page":"ج17 ص331","text":"قال حماد الراوية فقال لي يوما بحضرة يحيى بن زياد أتقول لأبي عطاء السندي أن يقول في زج وجرادة ومسجد بني شيطان قال فقلت له فما تجعله لي على ذلك\nقال بغلتي بسرجها ولجامها قلت فعدلها على يدي يحيى ابن زياد ففعل وأخذت عليه موثقا بالوفاء وجاء أبو عطاء السندي فجلس إلينا وقال مرهبا مرهبا هياكم الله فرحبت به وعرضت عليه العشاء فقال لا هاجة لي به فقال أعندكم نبيذ فأتيناه بنبيذ كان عندنا فشرب حتى احمرت عيناه واسترخت علابيه ثم\nقلت يا أبا عطاء إن إنسانا طرح علينا أبياتا فيها لغز ولست أقدر على إجابته البتة ومنذ أمس إلى الآن ما يستوي لي منها شيء ففرج عني قال هات فقلت\n(أبن لي إن سئلت أبا عطاء ... يقينا كيف علمك بالمعاني)\nقال\n(خبير عالم فاسأل تجدني ... بها طبا وآيات المثاني)\nفقلت\n(فما اسم حديدة في رأس رمح ... دوين الكعب ليست بالسنان)\nقال أبو عطاء\n(هو الزز الذي إن بات ضيفا ... لصدرك لم تزل لك عولتان)\nلت فرج الله عنك تعني الزج وقلت\n(فما صفراء تدعى أم عوف ... كأن رجيلتيها منجلان)\nقال\n(أردت زرادة وأزن زنا ... بأنك ما أردت سوى لساني)\nلت فرج الله عنك وأطال بقاءك تريد جرادة وأظن ظنا وقلت\n(أتعرف مسجدا لبني تميم ... فويق الميل دون بني أبان)\nقال\n(بنو سيطان دون بني أبان ... كقرب أبيك من عبد المدان)\nال حماد فرأيت عينيه قد احمرتا وعرفت الغضب في وجهه وتخوفته فقلت يا أبا عطاء هذا مقام المستجير بك ولك النصف مما أخذته قال فاصدقني قال فأخبرته فقال لي أولى لك قد سلمت وسلم لك جعلك خذه بورك لك فيه ولا حاجة لي فيه فأخذته وانقلب يهجو معلى بن هبيرة","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":10,"spl":"أبو عطاء وحماد الراوية","tags":["أمية بن أبي الصلت","الرواية والكتابة"],"loc":3110},
{"id":"b226-19","bab":"الجزء 17","sec":"مدح أبا جعفر فلم يثبه فهجاه","page":"ج17 ص332","text":"أخبرني الحسن قال حدثنا أحمد بن الحارث عن المدائني\nأن أبا عطاء مدح أبا جعفر فلم يثبه فأظهر الانحراف عنه لعلمه بمذهبه في بني أمية فعاوده بالمدح فقال له يا ماص كذا من أمه ألست القائل في عدو الله الفاجر نصر بن سيار ترثيه\n(فاضت دموعي على نصر وما ظلمت ... عين تفيض على نصر بن سيار)\n(يا نصر من للقاء الحرب إن لقحت ... يا نصر بعدك أو للضيف والجار)\n(الخندفي الذي يحمي حقيقته ... في كل يوم مخوف الشر والعار)\n(والقائد الخيل قبا في أعنتها ... بالقوم حتى تلف القار بالقار)\n(من كل أبيض كالمصباح من مضر ... يجلو بسنته الظلماء للساري)\n(ماض على الهول مقدام إذا اعترضت ... سمر الرماح وولى كل فرار)\n(إن قال قولا وفى بالقول موعده ... إن الكناني واف غير غدار)\nالله لا أعطيك بعد هذا شيئا أبدا قال فخرج من عنده وقال عدة قصائد يذمه فيها منها\n(فليت جور بني مروان عاد لنا ... وليت عدل بني العباس في النار)\nقال أيضا\n(أليس الله يعلم أن قلبي ... يحب بني أمية ما استطاعا)\n(وما بي أن يكونوا أهل عدل ... ولكني رأيت الأمر ضاعا)\nخبرني الحسن قال حدثني الخراز عن المدائني قال كان أبو عطاء مع ابن هبيرة وهو يبني مدينته التي على شاطىء الفرات فأعطى ناسا كثيرا صلات ولم يعطه شيئا فقال\n(قصائد حكتهن ليوم فخر ... رجعن إلي صفرا خاليات)\n(رجعن وما أفأن علي شيئا ... سوى أني وعدت الترهات)\n(أقام على الفرات يزيد حولا ... فقال الناس أيهما الفراتي)\n(فيا عجبا لبحر بات يسقي ... جميع الخلق لم يبلل لهاتي)\nقال له يزيد بن عمر بن هبيرة وكم يبل لهاتك يا أبا عطاء قال عشرة آلاف درهم فأمر ابنه بدفعها إليه فقال يمدح ابنه\n(أما أبوك فعين الجود تعرفه ... وأنت أشبه خلق الله بالجود)\n(ولولا يزيد ولولا قبله عمر ... ألقت إليك معد بالمقاليد)\n(ما ينبت العود إلا في أرومته ... ولا يكون الجني إلا من العود)\nخبرني الحسن قال حدثنا أحمد عن المدائني قال وهب نصر بن سيار لأبي عطاء جارية فلما أصبح غدا على نصر فقال ما فعلت أنت وهي فقال قد كان شيء مني منعني من بعض حاجتي - يعني النوم - فقال وهل قلت في ذلك شعرا قال نعم وأنشد\n(إن النكاح وإن هرمت لصالح ... خلف لعينك من لذيذ المرقد)\nفقال نصر\n(ذاك الشقاء فلا تظنن غيره ... ليس المشاهد مثل من لم يشهد)\nقال أصلحك الله إني قد امتدحتك فائذن لي أن أنشدك قال إني لفي شغل ولكن ائت تميما فأتاه فأنشده فحمله على برذون أبلق فقال له نصر من الغد ما فعل بك تميم فقال\n(لئن كان أغلق باب الندى ... فقد فتح الباب بالأبلق)\nم أنشده قوله\n(وهيكل يقال في جلاله ... تقصر أيدي الناس عن قذاله)\n(جعلت أوصالي على أوصاله ... إنك حمال على أمثاله)\nخبرني الحسن قال حدثنا أحمد بن الحارث عن المدائني قال لما أمر أبو جعفر الناس بلبس السواد لبسه أبو عطاء فقال\n(كسيت ولم أكفر من الله نعمة ... سوادا إلى لوني ودنا ملهوجا)\n(وبايعت كرها بيعة بعد بيعة ... مبهرجة إن كان أمر مبهرجا)\nخبرني الحسن قال حدثنا أحمد عن المدائني قال بعث إبراهيم بن الأشتر إلى أبي عطاء ببيتين من شعر وسأله أن يضيف إليهما بيتين من رويهما وقافيتهما وهما\n(وبلدة يزدهي الجنان طارقها ... قطعتها بكناز اللحم معتاطه)\n(وهنا وقد حلق النسران أو كربا ... وكانت الدلو بالجوزاء منتاطه)\nقال أبو عطاء\n(فانجاب عنها قميص الليل فابتكرت ... تسير كالفحل تحت الكور لطاطه)\n(في أينق كلما حث الحداة لها ... بدت مناسمها هوجاء حطاطه)\nخبرني الحسن قال حدثنا أحمد عن المدائني قال كان سبب هجاء أبي دلامة بغلته أن أبا عطاء السندي هجاها فخاف أبو دلامة أن تشتهر بذلك وتعره فباعها وهجاها بقصيدته المشهورة قال وأبيات أبي عطاء فيها\n(أبغل أبي دلامة مت هزلا ... عليه بالسخاء تعولينا)\n(دواب الناس تقضم ملمخالي ... وأنت مهانة لا تقضمينا)\n(سليه البيع واستعدي عليه ... فإنك إن تباعي تسمنينا)\nخبرني الحسن قال حدثنا أحمد عن المدائني قال كان أبو عطاء منقطعا في طريق مكة وخباؤه مطروح فمر به نهيك بن معبد العطاردي فقال لمن هذا الخباء الملقى فقيل لأبي عطاء السندي فبعث غلمانا له فضربوا له خباء وبعث إليه بألطاف وكسوة فقال من صنع هذا قالوا نهيك بن معبد فنادى بأعلى صوته يقول\n(إذا كنت مرتاد الرجال لنفعهم ... فناد بصوت يا نهيك بن معبد)","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":11,"spl":"مدح أبا جعفر فلم يثبه فهجاه","tags":["أمية بن أبي الصلت","الهجاء"],"loc":3111},
{"id":"b226-20","bab":"الجزء 17","sec":"مدح أبا جعفر فلم يثبه فهجاه","page":"ج17 ص332","text":"بعث إليه نهيك لا زدنا يا أبا عطاء فقال أبو عطاء إنما أعطيناك على قدر ما أعطيتنا فإن زدتنا زدناك والله أعلم نسخت من كتاب ابن الطحان قال الهيثم بن عدي أخبرنا حماد الراوية قال أنشدت أبا عطاء السندي في أثناء حديث هذا البيت\n(إذا كنت في حاجة مرسلا ... فأرسل حكيما ولا توصه)\nقال أبو عطاء بئس ما قال فقلت كيف تقول أنت قال أقول\n(إذا أرسلت في أمر رسولا ... فأفهمه وأرسله أديبا)\n(وإن ضيعت ذاك فلا تلمه ... على أن لم يكن علم الغيوبا)","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":12,"spl":"مدح أبا جعفر فلم يثبه فهجاه — شعره في مدح سليمان بن سليم","tags":["أمية بن أبي الصلت","المديح","الرواية والكتابة"],"loc":3112},
{"id":"b226-21","bab":"الجزء 17","sec":"شعره في مدح سليمان بن سليم","page":"ج17 ص337","text":"نسخت من كتاب عبيد الله بن محمد اليزيدي قال الهيثم بن عدي عن حماد بن سلمة الكلبي قال دخل أبو عطاء السندي على سليمان بن سليم بن بشار فقال له\n(أعوزتني الرواة يابن سليم ... وأبى أن يقيم شعري لساني)\n(وغلا بالذي أجمجم صدري ... وشكاني من عجمتي شيطاني)\n(وعدتني العيون أن كان لوني ... حالكا مظلما من الألوان)\n(وضربت الأمور ظهرا لبطن ... كيف أحتال حيلة لبياني)\n(فتمنيت أنني كنت بالشعر ... فصيحا وبان بعض بناني)\n(ثم أصبحت قد أنخت ركابي ... عند رحب الفناء والأعطان)\n(فإلى من سواك يابن سليم ... أشتكي كربتي وما قد عناني)\n(فاكفني ما يضيق عنه ذراعي ... بفصيح من صالحي الغلمان)\n(يفهم الناس ما أقول من الشعر ... فإن البيان قد أعياني)\n(ثم خذني بالشكر يابن سليم ... حيث كانت داري من البلدان)\nأمر له بوصيف فصيح كان حسن الإنشاد فقال أبو عطاء أيضا\n(فأقبلوا نحوي معا بالقنا ... وكلهم يسأل ما شأني)\n(فقلت شأني كله أنني ... في تعب من لفظ جرداني)\n(يابن سليم أنت لي عصمة ... من حدث أفزع جيراني)\n(فقد رماني الدهر عن فقره ... بسهم فقر غير لغبان)\n(صاد فؤادي بعدما قد سلا ... فصرت كالمقتبل العاني)\n(فانعش فدتك النفس مني ومن ... أطاعني من جل إخواني)\n(وهب فدتك النفس لي طفلة ... يقمع حرها رأس شيطاني)\n(فإن أيري قد عتا واعتدى ... وصار يبغي بغية الزاني)\n(فالله ثم الله في قمعه ... من قبل أن أمنى بسلطان)\n(يتركني أضحوكة بعدما ... أضرب في سر وإعلان)\nفأمر له بجارية قندهارية فارهة فقال\n(أحصنني الله بكفي فتى ... مهذب من سر قحطان)\n(من حمير أهل السدى والندى ... وةعصمة الخائف والجاني)\n(يا خير خلق الله أنت الذي ... أيأست من فسقي شيطاني)\nخبرني أحمد بن عبد العزيز قال حدثنا علي بن محمد النوفلي عن أبيه قال كنت جالسا مع سليمان بن مجالد وعنده أبو عطاء السندي إذ قام راوية أبي عطاء ينشد سليمان مديحا لأبي عطاء وأبو عطاء جالس لا يتكلم إذ قال الراوية في إنشاده\n(فما فضلت يمينك من يمين ... ولا فضلت شمالك عن شمال)\nكذا بالرفع فغضب أبو عطاء وقال ويلك فما مدهته إذا إنما هزوته يريد فما مدحته إنما هجوته ثم أنشده أبو عطاء\n(فما فدلت يمينك من يمين ... ولا فدلت شمالك عن شمال)\nكدت أضحك ولم أجسر لأني رأيت القوم جميعا بهم مثل ما بي وهم لا يضحكون خوفا منه حدثنا وكيع قال أخبرنا أحمد بن زهير قال حدثنا سليمان بن منصور قال حدثني صالح بن سليمان قال\nأبو عطاء السندي على نصر بن سيار فأنشده\n(قالت تريكة بيتي وهي عاتبة ... إن المقام على الإفلاس تعذيب)\n(ما بال هم دخيل بات محتضرا ... رأس الفؤاد فنوم العين توجيب)\n(إني دعاني إليك الخير من بلدي ... والخير عند ذوي الأحساب مطلوب)\nفأمر له بأربعين ألف درهم أخبرني محمد بن خلف وكيع والحسن بن علي قالا حدثنا عبد الله بن أبي سعد قال حدثني سليمان بن أبي شيخ عن صالح بن سليمان قال دخل إلى أبي عطاء السندي ضيف فأتاه بطعام فأكل وأتاه بشراب وجلسا يشربان فنظر أبو عطاء إلى الرجل يلاحظ جاريته فأنشأ يقول\n(كل هنيئا وما شربت مريئا ... ثم قم صاغرا وأنت ذميم)\n(لا أحب النديم يومض بالطرف ... إذا ما خلا لعرس النديم)\n\n(تجول خلاخيل النساء ولا أرى ... لرملة خلخالا يجول ولا قلبا)\n(أحب بني العوام طرا لحبها ... ومن أجلها أحببت أخوالها كلبا)\n(فإن تسلمي نسلم وإن تتنصري ... تخط رجال بين أعينهم صلبا)\nعروضه من الطويل الشعر لخالد بن يزيد بن معاوية يقوله في زوجته رملة بنت الزبير والغناء ليحيى المكي ثاني ثقيل أول بالوسطى من رواية ابنه وأبي العبيس وفيه لعبيد الله بن أبي غسان رمل وفيه لسعيد بن جابر خفيف رمل بالبنصر عن حبش","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":12,"spl":"مدح أبا جعفر فلم يثبه فهجاه — شعره في مدح سليمان بن سليم","tags":["أمية بن أبي الصلت"],"song":1,"loc":3113},
{"id":"b226-22","bab":"الجزء 17","sec":"ذكر خالد ورملة وأحبارهما وأنسابهما","page":"ج17 ص342","text":"خالد بن يزيد بن معاوية بن أبي سفيان بن حرب بن أمية بن عبد شمس بن عبد مناف وكان من رجالات قريش سخاء وعارضة وفصاحة وكان قد شغل نفسه بطلب الكيمياء فأفنى بذلك عمره وأسقط نفسه وأم خالد بن يزيد أم هاشم بنت هاشم بن عتبة بن ربيعة بن عبد شمس بن عبد مناف\nأخبرني الطوسي وحرمي قالا حدثنا الزبير قال حدثني عمي مصعب قال كان خالد بن يزيد بن معاوية يوصف بالعلم ويقول الشعر وزعموا أنه هو الذي وضع خبر السفياني وكبره وأراد أن يكون للناس فيه طمع حين غلبه مروان بن الحكم على الملك وتزوج أمه أم هاشم وهذا وهم من مصعب فإن السفياني قد رواه غير واحد وتتابعت فيه رواية الخاصة والعامة وذكر خبر\nأمره أبو جعفر محمد بن علي بن الحسين عليهم السلام وغيره من أهل البيت صلوات الله عليهم حدثني أبو عبد الله الصيرفي قال حدثنا محمد بن علي بن خلف العطار\nقال حدثنا الحسن بن صالح عن أبي الأسود قال حدثنا صالح بن أبي الأسود يعني أباه عن عبد الجبار بن العباس الهمداني عن عمار الدهني قال قال أبو جعفر محمد بن علي عليهما السلام كم تعدون بقاء السفياني فيكم\nقلت حمل امرأة تسعة أشهر قال ما أعلمكم يا أهل الكوفة حدثني أبو عبد الله قال حدثنا محمد بن علي قال حدثنا الحسن بن صالح قال حدثنا منصور بن الأسود\nقال أتيت جابرا الجعفي أنا والأسود أخي فقلنا له إنا قوم نضرب في هذه التجارات وقد بلغنا أن الرايات قد قطع بها الفرات فماذا تشير علينا وماذا تأمرنا\nقال اذهبوا حيث شئتم من أرض الله تعالى حتى إذا خرج السفياني فأقبلوا عودكم على بدئكم أخبرني الطوسي وحرمي قالا حدثنا الزبير بن بكار عن عمه قال لما ولدت أم هاشم خالد بن يزيد بن معاوية تركت كنيتها واكتنت بخالد وقال فيها يزيد بن معاوية\n(وما نحن يومن استعبرت أم خالد ... بمرضى ذوي داء ولا بصحاح)\nلها يقول وقد قدم من المدينة وقد تزوج أم مسكين بنت عمر بن عاصم\nابن عمر بن الخطاب فحملت إليه بالشام فأعجب بها وجفا أم خالد ودخل عليها وهي تبكي فقال\n(مالك أمض خالد تبكين ... من قدر حل بكم تضجين)\n(باعت على بيعك أم مسكين ... ميمونة من نسوة ميامين)\n(حلت محلك الذي تحلين ... زارتك من يثرب في جوارين)\n(في منزل كنت به تكونين ... )\nأخبرني الطوسي وحرمي قالا حدثنا الزبير بن بكار عن عمه أن رملة بنت الزبير كانت أخت مصعب بن الزبير لأمه كانت أمهما أم الرباب بنت أنيف بن عبيد بن مصاد بن كعب بن عليم بن عتاب بن ذهل من كلب وإنما كانت قبل خالد بن يزيد عند عثمان بن عبد الله بن حكيم بن حزام بن خويلد بن أسد بن عبد العزى فولدت له عبد الله بن عثمان وهو زوج سكينة بنت الحسين بن علي عليهما السلام","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":13,"spl":"ذكر خالد ورملة وأحبارهما وأنسابهما","tags":["أمية بن أبي الصلت"],"loc":3114,"partial":1},
{"id":"b226-24","bab":"الجزء 17","sec":"معاتبة الحجاج له — شعره في رملة","page":"ج17 ص344 – ج17 ص345","text":"قال الزبير فحدثني رجل عن عمر بن عبد العزيز وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال لما قتل ابن الزبير حج خالد بن يزيد بن معاوية فخطب رملة بنت الزبير بن العوام فأرسل إليه الحجاج حاجبه عبيد الله بن موهب\nوقال له ما كنت أراك تخطب إلى آل الزبير حتى تشاورني وكيف خطبت إلى قوم ليسوا لك بأكفاء وكذلك قال جدك معاوية وهم الذين قارعوا أباك على الخلافة ورموه بكل قبيحة وشهدوا عليه وعلى جدك بالضلالة فنظر إليه خالد طويلا ثم قال له لولا أنك رسول والرسول لا يعاقب\nلقطعتك إربا إربا ثم طرحتك على باب صاحبك قل له ما كنت أرى أن الأمور بلغت بك إلى أن أشاورك في خطبة النساء وأما قولك لي قارعوا أباك وشهدوا عليه بكل قببح فإنها قريش يقارع بعضها بعضا فإذا أقر الله عز و جل الحق قراره كان تقاطعهم وتراحمهم على قدر أحلامهم وفضلهم وأما قولك إنهم ليسوا بأكفاء فقاتلك الله يا حجاج ما أقل علمك بأنساب قريش أيكون العوام كفؤا لعبد المطلب بن هاشم بتزوجه صفية وبتزوج رسول الله خديجة بنت خويلد ولا تراهم أهلا لأبي سفيان فرجع الحاجب إليه فأعلمه\nقال وقال عمر بن شبة في خبره قال خالد بن يزيد بن معاوية فيها\n(أليس يزيد السير في كل ليلة ... وفي كل يوم من أحبتنا قربا)\n(أحن إلى بنت الزبير وقد علت ... بنا العيس خرقا من تهامة أو نقبا)\n(إذا نزلت أرضا تحبب أهلها ... إلينا وإن كانت منازلها خربا)\n(وإن نزلت ماء وإن كان قبلها ... مليحا وجدنا ماءه باردا عذبا)\n(تجول خلاخيل النساء ولا أرى ... لرملة خلخالا يجول ولا قلبا)\n(أقلوا علي اللوم فيها فإنني ... تخيرتها منهم زبيرية قلبا)\n(أحب بني العوام طرا لحبها ... ومن حبها أحببت أخوالها كلبا)\nال أبو زيد وزادوا في الأبيات\n(فإن تسلمي نسلم وإن تتنصري ... تخط رجال بين أعينهم صلبا)\nقال له عبد الملك تنصرت يا خالد قال وما ذاك فأنشده هذا البيت فقال له خالد على من قاله ومن نحلنيه لعنة الله أخبرني أحمد بن عبد العزيز الجوهري\nقال حدثني عمر بن شبة قال حدثني موسى بن سعيد بن سلم قال قدم الحجاج على عبد الملك فمر بخالد بن يزيد بن معاوية ومعه بعض أهل الشام فقال الشامي لخالد من هذا فقال خالد كالمستهزئ هذا عمرو بن العاص فعدل إليه الحجاج فقال إني والله ما أنا بعمرو بن العاصي ولا ولدت عمرا ولا ولدني ولكني ابن الغطاريف من ثقيف والعقائل من قريش ولقد ضربت بسيفي هذا أكثر من مائة ألف كلهم يشهد أنك وأباك من أهل النار ثم لم أجد لذلك عندك أجرا ولا شكرا وانصرف عنه وهو يقول عمرو بن العاصي عمرو بن العاصي\nأخبرني محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني قال حدثنا عبد الله بن مسلم القرشي عن مطر مولى يزيد بن عبد الملك\nأن محمد بن عمرو بن سعيد بن العاصي قدم الشام غازيا فأتى عمته أمية بنت سعيد وهي عند خالد بن يزيد بن معاوية فدخل خالد فرآه فقال ما يقدم علينا أحد من أهل الحجاز إلا اختار المقام عندنا على المدينة فظن محمد أنه يعرض به فقال له وما يمنعهم من ذلك وقد قدم قوم من أهل المدينة على النواضح فنكحوا أمك وسلبوك ملكك وفرغوك لطلب الحديث وقراءة الكتب وعمل الكيميا الذي لا تقدر عليه انتهى","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":14,"spl":"معاتبة الحجاج له — شعره في رملة","tags":["أمية بن أبي الصلت"],"loc":3115},
{"id":"b226-25","bab":"الجزء 17","sec":"أمه تقتل زوجها مروان بن الحكم","page":"ج17 ص347","text":"أخبرني محمد بن العباس اليزيدي قال حدثنا الخراز عن المدائني عن أبي أيوب القرشي عن يزيد بن حصين بن نمير أن مروان بن الحكم تزوج أم خالد بن يزيد بن معاوية فناظر خالدا يوما وأراد أن يضع منه في شيء جرى بينهما فقال له يابن الرطبة فقال له خالد إنك لأمي مختبر وأنت بهذا أعلم ثم أتى أمه فأخبرها\nوقال أنت صنعت بي هذا فقالت له دعه فإنه لا يقولها لك بعد اليوم فدخل مروان عليهما فقال لها هل أخبرك خالد بشيء فقالت يا أمير المؤمنين خالد أشد تعظيما لك من أن يذكر لي خبرا جرى بينك وبينه فلما أمسى وضعت مرفقة على وجهه وقعدت عليها وهي وجواريها حتى مات\nوأراد عبد الملك قتلها وبلغها ذلك فقالت أما إنه اشد عليك أن يعلم الناس أن أباك قتلته امرأة فكف عنها أخبرني محمد قال حدثني الخراز عن المدائني\nقال وأخبرني الطوسي عن الزبير عن المدائني عن جويرية قال نشزت سكينة بنت الحسين بن علي عليهما السلام على زوجها عبد الله ابن عثمان - وأمه رملة بنت الزبير - فدخلت رملة على عبد الملك بن مروان وهو عند خالد بن يزيد بن معاوية فقالت يا أمير المؤمنين لولا أن يبتز أمرنا ما كانت لنا رغبة فيمن لا يرغب فينا سكينة بنت الحسين عليه السلام قد نشزت على ابني\nقال يا رملة إنها سكينة قالت وإن كانت سكينة فوالله لقد ولدنا خيرهم ونكحنا خيرهم وأنكحنا خيرهم تعني بمن ولدوا فاطمة بنت رسول الله ومن نكحوا صفية بنت عبد المطلب ومن أنكحوا النبي فقال يا رملة غرني منك عروة بن الزبير فقالت ما غرك ولكن نصح لك لأنك قتلت أخي مصعبا فلم يأمني عليك أخبرني الطوسي قال حدثني عمي مصعب قال تزوج خالد بن يزيد بنت عبد الله بن جعفر بن أبي طالب عليه السلام فقال فيها\n(جاءت بها دهم البغال وشهبها ... مقنعة في جوف حدج مخدر)\n(مقابلة بين النبي محمد ... وبين علي والحواري وجعفر)\n(منافية جادت بخالص ودها ... لعبد منافي أغر مشهر)\nقال مصعب ومن الناس من ينكر تزويجه إياها ومما يثبته قول شديد بن شداد بن عامر بن لقيط بن جابر بن وهيب بن ضباب بن حجير بن عبد بن معيص بن عامر بن لؤي لعبد الملك بن مروان هذا يعيره بخالد في تزويجه بنت الزبير وبنت عبد الله بن جعفر قال\n(لا يستوي الحبلان حبل تلبست ... قواه وحبل قد أمر شديد)\n(عليك أمير المؤمنين بخالد ... ففي خالد عما تريد صدود)\n(إذا ما نظرنا في مناكح خالد ... عرفنا الذي يهوى وحيث يريد)","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":15,"spl":"أمه تقتل زوجها مروان بن الحكم","tags":["أمية بن أبي الصلت","الحب والغزل"],"loc":3116},
{"id":"b226-27","bab":"الجزء 17","sec":"خالد يشكو الوليد إلى أبيه عبد الملك — ضعف معاوية بن مروان","page":"ج17 ص349 – ج17 ص350","text":"أخبرنا الطوسي قال حدثنا الزبير قال حدثني مصعب بن عثمان قال دخل عبد الله بن بزيد بن معاوية على أخيه خالد فقال لقد هممت اليوم بقتل الوليد بن عبد الملك فقال له خالد بئس ما هممت به في ابن أمير المؤمنين وولي عهد المسلمين\nقال إنه لقي خيلي فنفرها وتلاعب بها فقال له خالد أنا أكفيكه إن شاء الله فدخل خالد على عبد الملك وعنده الوليد فقال له يا أمير المؤمنين إن ولي عهد المسلمين الوليد ابن أمير المؤمنين لقي خيل ابن عمه عبد الله بن يزيد فنفرها وتلعب بها فشق ذلك على عبد الله فنكس عبد الملك رأسه وقرع الأرض بقضيب في يده ثم رفع رأسه إليه فقال ( إن الملوك إذا دخلوا قرية أفسدوها وجعلوا أعزة أهلها أذلة وكذلك يفعلون\nفقال له خالد ( وإذا أردنا أن نهلك قرية أمرنا مترفيها ففسقوا فيها فحق عليها القول فدمرناها تدميرا\nفقال له عبد الملك أتكلمني فيه وقد دخل علي لا يقيم لسانه لحنا فقال له خالد يا أمير المؤمنين أفعلى الوليد تعول في اللحن فقال\nعبد الملك إن يكن الوليد لحانا فأخوه سليمان قال خالد وإن يكن عبد الله لحانا فأخوه خالد قال الوليد لخالد أتكلمني ولست في عير ولا نفير\nقال ألا تسمع يا أمير المؤمنين ما يقول هذا أنا والله ابن العير والنفير سيد العير جدي أبو سفيان وسيد النفير جدي عتبة بن ربيعة ولكن لو\nقلت حبيلات - يعني حبلة العنب - وغنيمات والطائف لقلنا صدقت ورحم الله عثمان هذا آخر الحديث قال مؤلف هذا الكتاب يعيره بأم مروان وأنها من الطائف ويعيره بالحكم وأن رسول الله طرده إلى الطائف وترحم على عثمان لرده إياه\nحدثني محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز عن المدائني عن إسحاق بن أيوب أن معاوية بن مروان كان ضعيفا فقال له خالد بن يزيد يا أبا المغيرة ما الذي هونك على أخيك فلا يوليك ولاية قال لو أردت لفعل قال كلا قال بلى والله قال فسله أن يوليك بيت لهيا قال نعم فغدا على عبد الملك فقال له معاوية يا أمير المؤمنين ألست أخاك قال بلى والله إنك لأخي وشقيقي قال فولني بيت لهيا قال متى عهدك\nبخالد قال عشية أمس قال إياك أن تكلمه ودخل خالد فقال له كيف أصبحت يا أبا المغيرة قال قد نهانا هذا عن كلامك فغلب على عبد الملك الضحك فقام وتفرق الناس\nقال وأفلت لمعاوية هذا باز فصاح أغلقوا أبواب المدينة لا يخرج قال وقال له رجل أنت الشريف ابن أمير المؤمنين وأخو أمير المؤمنين وابن عم أمير المؤمنين عثمان وأمك عائشة بنت معاوية\nقال فأنا إذا مردد في بن اللخناء تردادا أخبرني الطوسي عن الزبير عن عمه قال كان خالد بن يزيد يتعصب لكلب على قيس في الحرب التي كانت بينهم لأن كلبا أخوال أبيه يزيد وأخوال زوجته فقال شاعر قيس\n(يا خالد بن أبي سفيان قد قرحت ... منا القلوب وضاق السهل والجبل)\n(أأنت تأمر كلبا أن تقاتلنا ... جهلا وتمنعهم منا إذا قتلوا)\n(ها إن ذا لا يقر الطير ساكنة ... ولا تبرك من نكرائه الإبل)\n\n(خمس دسسن إلي في لطف ... حور العيون نواعم زهر)\n(فطرقتهن مع الجري وقد ... نام الرقيب وحلق النسر)\nروضه من الكامل الشعر للأحوص والغناء لمعبد رمل بالسبابة في مجرى البنصر عن إسحاق","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":16,"spl":"خالد يشكو الوليد إلى أبيه عبد الملك — ضعف معاوية بن مروان","tags":["أمية بن أبي الصلت"],"song":1,"loc":3117},
{"id":"b226-28","bab":"الجزء 17","sec":"خبر للأحوص","page":"ج17 ص352","text":"أخبرني حرمي بن أبي العلاء قال حدثني الزبير بن بكار قال أخبرني إبراهيم بن عبد الرحمن قال حدثني إسماعيل بن محمد المخزومي قال اجتمع نسوة عند امرأة من أهل المدينة فقلن أرسلي إلي الأحوص فإنا نحب أن نتحدث معه ونسمع من شعره فقالت لهن إذا لا يزيدكن على أن يخرج إذا عرفكن فيشهركن وينظم الشعر فيكن فلم يزلن بها حتى أرسلت إليه رسولا يذكر له أمرهن ولا يسميهن ويقول له أن يأتيهن مخمر الرأس ففعل وتحدث معهن وأنشدهن فلما أراد الخروج وضع يده في تور بين أيديهن في خلوق فغطى رأسه وخرج ووضع يده على الباب ثم تفقد الموضع الذي كان فيه فغدا إليه وطاف حتى وجد أثر يده في الباب فقال\n(خمس دسسن إلي في لطف ... حور العيون نواعم زهر)\n(فطرقتهن مع الجري وقد ... نام الرقيب وحلق النسر)\n(مستبطنا للحي إذ قرعوا ... عضبا يلوح بمتنه أثر)\n(فعكفن ليلتهن ناعمة ... ثم استفقن وقد بدا الفجر)\n(بأشم معسول فكاهته ... غض الشباب رداؤه غمر)\n(رزن بعيد الصوت مشتهر ... جيبت له جوب الرحى عمرو)\n(قامت تخاصره لكلتها ... تمشي تأود غادة بكر)\n(فتنازعا من دون نسوتها ... كلما يسر كأنه سحر)\n(كل يرى أن الشباب له ... في كل غاية صبوة عذ)\n(سيفانة أمر الشباب بها ... رقراقة لم يبلها الدهر)\n(حتى إذا أبدى هواه لها ... وبدا هواها ماله ستر)\n(سفرت وما سفرت لمعرفة ... وجها أغر كأنه البدر)\nقال إسماعيل بن محمد فخرجت وأنا شاب ومعي شباب نريد مسجد رسول الله فذكرنا حديث الأحوص وشعره وقدامنا عجوز عليها بقايا من الجمال فلما بلغنا المسجد وقفت علينا والتفتت إلينا وقالت يا فتيان أنا والله إحدى الخمس كذب ورب هذا القبر والمنبر ما خلت معه واحدة منا ولا راجعته دون نسوتها كلاما قال الزبير وحدثني غير إبراهيم بن عبد الرحمن أن نسوة من أهل المدينة نذرن مشيا إلى قباء وصلاة فيه فخرجن ليلا\nفطال عليهن الليل فنمن فجاءهن الأحوص متكئا على عرجون ابن طاب فتحدث معهن حتى أصبح ثم انصرف وانصرفن فقال قصيدته\n(خمس دسسن إلي في لطف ... حور العيون نواعم زهر)\nحدثني عمي عن أبيه قال قال حبيب بن ثابت صدرت إلى العقيق فخلا لي الطريق فأنشدت أبيات الأحوص هذه وعجوز سوداء قاعدة ناحية تسمع ما أقول ولا أشعر بها فقالت كذب والله يا سيدي إن سيفه ليلتئذ لعرجون ابن طاب يتخصر به وإني لرسولهن إليه قال الزبير وحدثني عمي عن أبيه عن الزبير بن حبيب قال كنت أنشد قول الأحوص\n(خمس دسسن إلي في لطف ... )\nال فإذا نسوة فيهن عجوز سوداء فأقبلن على العجوز فقلن لها لمن هذا الشعر قالت للأحوص فقلت للأحوص لعمري فقالت لهن أنا والله الجري خرج نسوة يصلين في مسجد قباء ثم تحدثن في رحبة المسجد في ليلة مقمرة فقلن لو كان عندنا الأحوص فخرجت حتى أتيتهن به وهو متخصر\nبعرجون ابن طاب فتحدث معهن حتى دنا الصبح فقلن له لا تذكر خبرنا ولا تذكر إلا خيرا قال قد فعلت وأنشدهن تلك الساعة من الليلة تلك الأبيات ثم استمرت بأفواه الناس تغنى\n(خمس دسسن إلي في لطف ... )\nلأبيات كلها والله ما قامت معه امرأة ولا كان بينه وبين واحدة منهن سر\n(يابنة الجودي قلبي كئيب ... مستهام عندها ما ينيب)\n(ولقد قالوا فقلت دعوها ... إن من تنهون عنه حبيب)\n(إنما أبلى عظامي وجسمي ... حبها والحب شيء عجيب)\nروضه من الرمل الشعر لعبد الرحمن بن أبي بكر الصديق رضي الله عنه والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لمالك خفيف ثقيل أول بالخنصر في مجرى البنصر عن إسحاق وفيه رمل بالسبابة في مجرى الوسطى لم ينسبه إسحاق إلى أحد وذكر أحمد بن يحيى المكي أنه لأبيه يحيى والله أعلم","topic":"نسب أمية بن أبي الصلت وخبره في قوله هذا الشعر","topicNo":226,"sp":17,"spl":"خبر للأحوص","tags":["أمية بن أبي الصلت"],"song":1,"loc":3118,"partialRef":{"sid":"b226-27","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b227-2","bab":"الجزء 17","sec":"ذكر عبد الرحمن بن أبي بكر وخبره وقصة بنت الجودي — صحبته بالنبي","page":"ج17 ص355 – ج17 ص356","text":"عبد الرحمن بن أبي بكر واسم أبي بكر رضي الله عنه عبدالله - وكان اسمه في الجاهلية عتيقا فسماه رسول الله عبد الله - بن عثمان بن عامر بن عمرو بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب بن فهر بن مالك بن النضر بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وكان اسم عبد الرحمن عبد العزى فسماه رسول الله عبد الرحمن وأمه وأم عائشة أم رومان بنت عامر بن عويمر بن عبد شمس بن عتاب بن أذينة بن سبيع بن دهمان بن الحارث بن غنم بن مالك بن كنانة بن خزيمة هذا قول الزبير وعمه وحكى إبراهيم بن موسى أنها بنت عويمر بن عتاب بن دهمان بن الحارث ابن غنم\nوروي عن محمد بن عبد الرحمن المرواني أنها بنت عامر بن عويمر بن أذينة بن سبيع بن الحارث بن دهمان بن غنم بن مالك بن كنانة ولعبد الرحمن بن أبي بكر رضي الله عنه صحبة بالنبي ولم يهاجر مع\nأبيه صغرا عن ذلك فبقي بمكانه ثم خرج قبل الفتح مع فتية من قريش وقيل بل كان إسلامه في يوم الفتح وإسلام معاوية بن أبي سفيان في وقت واحد غير مدفوع انتهى\nأخبرني الطوسي وحرمي بن أبي العلاء قالا حدثنا الزبير قال حدثني إبراهيم بن حمزة عن سفيان بن عيينة عن علي بن زيد بن جدعان أن عبد الرحمن بن أبي بكر خرج في فتية من قريش مهاجرا إلى النبي قبل الفتح\nقال وأحسبه قال إن معاوية كان معهم قال الزبير وحدثني عمي مصعب قال وقف محكم اليمامة على ثلمة فحماها فلم يجز عليه أحد فرماه عبد الرحمن بن أبي بكر فقتله وكان أحد الرماة فدخل المسلمون من تلك الثلمة وهو المخاطب لمروان يوم دعا إلى بيعة يزيد والقائل إنما تريدون أن تجعلوها كسروية أو هرقلية كلما هلك كسرى أو هرقل ملك كسرى أو هرقل فقال مروان أيها الناس هذا الذي\nقال لوالديه أف لكما أتعدانني أن أخرج وقد خلت القرون من قبلي فصاحت به عائشة ألعبد الرحمن تقول هذا كذبت والله ما هو به ولو شئت أن أسمي من أنزلت فيه لسميته ولكن أشهد أن رسول الله لعن أباك وأنت في صلبه فأنت فضض من لعنة الله\nحدثنا بذلك أحمد بن الجعد قال حدثنا أحمد بن زهير قال حدثني أبي قال حدثنا وهب بن جرير عن جويرية بن أسماء وفي غير رواية أن عائشة قالت له يا مروان أفينا تتأول القرآن وإلينا تسوق اللعن والله لأقومن يوم\nالجمعة بك مقاما تود أني لم أقمه فأرسل إليها بعد ذلك وترضاها واستعفاها وحلف ألا يصلي بالناس أو تؤمنه ففعلت","topic":"ذكر عبد الرحمن بن أبي بكر وخبره وقصة بنت الجودي","topicNo":227,"sp":0,"spl":"ذكر عبد الرحمن بن أبي بكر وخبره وقصة بنت الجودي — صحبته بالنبي","tags":["الجواري والنساء"],"loc":3119},
{"id":"b227-3","bab":"الجزء 17","sec":"هيامه بليلى بنت الجودي وشعره فيها","page":"ج17 ص358","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا محمد بن يحيى قال حدثنا عبد العزيز بن عمران عن عبد الله بن أبي الزناد عن هشام بن عروة عن أبيه عن عائشة وأخبرني الطوسي قال حدثنا الزبير قال حدثنا محمد بن الضحاك عن أبيه عن عبد الرحمن بن أبي الزناد عن هشام بن عروة عن أبيه قال استهيم عبد الرحمن بن أبي بكر بليلى بنت الجودي بن عدي بن عمرو بن أبي عمرو الغساني فقال فيها\n(تذكرت ليلى والسماوة دونها ... وما لابنة الجودي ليلى وما ليا)\n(وأنى تعاطي قلبه حارثية ... تحل ببصرى أو تحل الجوابيا)\n(وكيف يلاقيها بلى ولعلها ... إذا الناس حجوا قابلا أن تلاقيا)\nال أبو زيد وقال فيها\n(يابنة الجودي قلبي كئيب ... مستهام عندها ما ينيب)\n(جاورت أخوالها حي عك ... فلعك من فؤادي نصيب)\nقد ذكرنا باقي الأبيات فيما تقدم قال الزبير في خبره وكان قدم في تجارة فرآها هناك على طنفسة حولها ولائد فأعجبته وقال أبو زيد في خبره فقال له عمر ما لك ولها يا عبد الرحمن فقال والله ما رأيتها قط إلا ليلة في بيت المقدس في جوار ونساء يتهادين فإذا عثرت إحداهن قالت بابنة الجودي فإذا حلفت إحداهن حلفت بابنة الجودي فكتب عمر إلى صاحب الثغر الذي هي به إذا فتح الله عليكم دمشق فقد غنمت عبد الرحمن بن أبي بكر ليلى بنت الجودي فلما فتح الله عليهم غنموه إياها قالت عائشة فكنت أكلمه فيما يصنع بها فيقول يا أخيه دعيني فوالله لكأني أرشف من ثناياها حب الرمان ثم ملها وهانت عليه فكنت أكلمه فيما يسيء إليها كما كنت أكلمه في الإحسان إليها فكان إحسانه أن ردها إلى أهلها\nقال الشيخ في خبره فقالت له عائشة يا عبد الرحمن لقد أحببت ليلى فأفرطت وأبغضت ليلى فأفرطت فإما أن تنصفها وإما أن تجهزها إلى أهلها فجهزها إلى أهلها\nقال الزبير وحدثني عبد الله بن نافع الصائغ عن هشام بن عروة عن أبيه أن عمر بن الخطاب نفل عبد الرحمن بن أبي بكر بنت الجودي حين فتح دمشق وكانت بنت ملك دمشق\nأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا الصلت بن مسعود قال حدثنا محمد بن شيرويه عن سليمان بن صالح قال قرأت على عبد الله بن المبارك عن مصعب بن ثابت عن عبد\nالله بن الزبير عن عائشة بنت مصعب عن عروة بن الزبير قال كانت ليلى بنت الجودي بنت ملك من ملوك الشام فشبب بها عبد الرحمن بن أبي بكر وكان قد رآها فيما تقدم بالشام فلما فتح الله عز و جل على المسلمين وقتلوا أباها أصابوها فقال المسلمون لأبي بكر يا خليفة رسول الله أعط هذه الجارية عبد الرحمن فقد سلمناها له\nقال أبو بكر أكلكم على هذا قالوا نعم فأعطاه وكان لها بساط في بلدها لا تذهب إلى الكنيف ولا إلى الحاجة إلا بسط لها ورمي بين يديها برمانتين من ذهب تتلهى بهما في طريقها فكان عبد الرحمن إذا خرج من عندها ثم رجع إليها رأى في عينيها أثر البكاء فيقول ما يبكيك اختاري خصالا أيها شئت فعلت بك إما أن أعتقك وأنكحك فتقول لا أشتهيه وإن شئت رددتك على قومك قالت ولا أريد وإن أحببت رددتك على المسلمين قالت لا اريد\nقال فأخبريني ما يبكيك قالت أبكي الملك من يوم البؤس أخبرني أحمد قال حدثني أبو زيد قال حدثني هارون بن إبراهيم بن معروف قال حدثني حمزة بن ربيعة عن العلاء بن هارون عن عبد الله بن عون عن يحيى بن يحيى الغساني أن عبد الرحمن قدم على يعلى بن منية وهو على اليمن فوجدها في السبي فسأله أن يدفعها إليه\nأخبرني أحمد قال حدثنا عمر قال كتب إلي محمد بن زياد بن عبيد الله يذكر أن عبد الرحمن قال فيها\n(فإما تصبحي بعد اقتراب ... بسلع أو ثنيات الوداع)\n(فلم ألفظك من شبع ولكن ... لأقضي حاجة النفس الشعاع)\n(كأن جوانح الأضلاع مني ... بعيد النوم مبطنة اليراع)","topic":"ذكر عبد الرحمن بن أبي بكر وخبره وقصة بنت الجودي","topicNo":227,"sp":1,"spl":"هيامه بليلى بنت الجودي وشعره فيها","tags":["الجواري والنساء"],"loc":3120},
{"id":"b227-4","bab":"الجزء 17","sec":"موته ورثاء عائشة له","page":"ج17 ص361","text":"أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أبو أحمد الزبيري قال حدثنا عبد الله بن لاحق عن أبي مليكة قال مات عبد الرحمن بن أبي بكر رضي الله عنه بالحبشي جبل من مكة على أميال فحمل فدفن بمكة فقدمت عائشة فوقفت على قبره ثم قالت\n(وكنا كندماني جذيمة حقبة ... من الدهر حتى قيل لن يتصدعا)\n(فلما تفرقنا كأني ومالكا ... لطول اجتماع لم نبت ليلة معا)\nأما والله لو حضرتك لدفنتك حيث مت ولو شهدتك لزرتك\n(أماوي إن المال غاد ورائح ... ويبقى من المال الأحاديث والذكر)\n(وقد علم الأقوام لو أن حاتما ... أراد ثراء المال أمسى له وفر)\n(أماوي إن يصبح صداي بقفرة ... من الأرض لا ماء لدي ولا خمر)\n(ترى أن ما أنفقت لم يك ضائري ... وأن يدي مما بخلت به صفر)\nروضه من الطويل الثراء الكثرة في المال وفي عدد القوم أيضا والوفر الغنى ووفور المال والصدى ها هنا كان أهل الجاهلية يذكرون أن طائرا يخرج من جسم الإنسان أو من رأسه فإذا قتل أقبل يصوت على قبره حتى يدرك بثأره والصفر الخالي والصدى العطش والصدى ما يجيب إذا صوت في المكان الخالي وصدأ الحديد مهموز الشعر لحاتم الطائي والغناء لإسحاق رمل بالسبابة في مجرى البنصر\nوذكر الهشامي أن فيه ثقيلا أول ولمالك خفيفا وذكر حبش أن فيه لابن سريج ثاني ثقيل بالوسطى وذكر عمرو بن بانة أن فيه لابن جامع خفيف رمل بالوسطى","topic":"ذكر عبد الرحمن بن أبي بكر وخبره وقصة بنت الجودي","topicNo":227,"sp":2,"spl":"موته ورثاء عائشة له","tags":["الحب والغزل"],"song":1,"loc":3121},
{"id":"b228-2","bab":"الجزء 17","sec":"أخبار حاتم ونسبه — سخاء أم حاتم","page":"ج17 ص363 – ج17 ص365","text":"ذكر ابن الأعرابي عن المفضل والأثرم عن أبي عمرو الشيباني وابن الكلبي عن أبيه والسكري عن يعقوب بن السكيت أنه حاتم بن عبد الله بن سعد بن الحشرج بن امرئ القيس بن عدي بن أخزم بن أبي أخزم واسمه هزومه بن ربيعة بن جرول بن ثعل بن عمرو بن الغوث بن طيىء\nوقال يعقوب بن السكيت إنما سمي هزومة لأنه شج أو شج وإنما سمي طيىء طيئا - واسمه جلهمة - لأنه أول من طوى المناهل وهو ابن أدد بن زيد بن يشجب بن يعرب بن قحطان ويكنى حاتم أبا سفانة وأبا عدي كني بذلك بابنته سفانة وهي أكبر ولده وبابنه عدي بن حاتم وقد أدركت سفانة وعدي الإسلام فأسلما وأتى بسفانة النبي في أسرى طيىء فمن عليها أخبرني بذلك أحمد بن عبيد الله بن عمار قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثني سليمان بن الربيع بن هشام الكوفي - ووجدته\nفي بعض نسخ الكوفيين عن سليمان بن الربيع - أتم من هذا فنسخته وجمعتهما قال حدثنا عبد الحميد بن صالح الموصلي البرجمي قال حدثنا زكريا بن عبد الله بن يزيد الصهباني عن أبيه عن كميل بن زياد النخعي عن علي عليه السلام\nقال يا سبحان الله ما أزهد كثيرا من الناس في الخير عجبت لرجل يجيئه أخوه في حاجة فلا يرى نفسه للخير أهلا فلو كنا لا نرجو جنة ولا نخاف نارا ولا ننتظر ثوابا ولا نخشى عقابا لكان ينبغي لنا أن نطلب مكارم الأخلاق فإنها تدل على سبيل النجاة فقام رجل فقال فداك أبي وأمي يا أمير المؤمنين أسمعته من رسول الله\nقال نعم وما هو خير منه لما أتينا بسبايا طيىء كانت في النساء جارية حماء حوراء العينين لعساء لمياء عيطاء شماء الأنف معتدلة القامة درماء الكعبين خدلجة الساقين لفاء الفخذين خميصة الخصر ضامرة الكشحين مصقولة المتنين\nفلما رأيتها أعجبت بها فقلت لأطلبنها إلى رسول الله ليجعلها من فيئي فلما تكلمت أنسيت جمالها لما سمعت من فصاحتها فقالت يا محمد هلك الوالد وغاب الوافد فإن رأيت أن تخلي عني فلا تشمت بي أحياء العرب فإني بنت سيد قومي كان أبي يفك العاني ويحمي الذمار ويقري الضيف ويشبع الجائع ويفرج عن المكروب ويطعم الطعام ويفشي السلام ولم يرد طالب حاجة قط أنا بنت حاتم طيىء فقال لها رسول الله يا جارية هذه صفة المؤمن لو كان أبوك إسلاميا لترحمنا عليه خلوا عنها فإن أباها كان يحب مكارم الأخلاق والله يحب مكارم الأخلاق وأم حاتم عتبة بنت عفيف بن عمرو بن امرئ القيس بن عدي بن أخزم وكانت في الجود بمنزلة حاتم لا تدخر شيئا ولا يسألها أحد شيئا فتمنعه\nأخبرني محمد بن الحسن بن دريد قال أخبرنا الحرمازي عن العباس ابن هشام عن أبيه قال كانت عتبة بنت عفيف وهي أم حاتم ذات يسار وكانت من أسخى الناس وأقراهم للضيف وكانت لا تليق شيئا تملكه فلما رأى إخوتها إتلافها حجروا عليها ومنعوها مالها فمكثت دهرا لا يدفع إليها شيء منه حتى إذا ظنوا أنها قد وجدت ألم ذلك أعطوها صرمة من إبلها فجاءتها امرأة من هوازن كانت تأتيها في كل سنة تسألها فقالت لها دونك هذه الصرمة فخذيها فوالله لقد عضني من الجوع ما لا أمنع معه سائلا أبدا ثم أنشأت تقول\n(لعمري لقدما عضني الجوع عضة ... فآليت ألا أمنع الدهر جائعا)\n(فقولا لهذا اللائمي اليوم أعفني ... فإن أنت لم تفعل فعض الأصابعا)\n(فماذا عساكم أن تقولوا لأختكم ... سوى عذلكم أو عذل من كان مانعا)\n(وماذا ترون اليوم إلا طبيعة ... فكيف بتركي يابن أم الطبائعا)\nال ابن الكلبي وحدثني أبو مسكين قال كانت سفانة بنت حاتم من أجود نساء العرب وكان أبوها يعطيها الصرمة بعد الصرمة من إبله فتنهبها وتعطيها الناس فقال لها حاتم يا بنية إن القرينين إذا اجتمعا في المال أتلفاه فإما أن أعطي وتمسكي أو أمسك وتعطي فإنه لا يبقى على هذا شيء","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":0,"spl":"أخبار حاتم ونسبه — سخاء أم حاتم","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3122},
{"id":"b228-3","bab":"الجزء 17","sec":"أخبار في كرم حاتم","page":"ج17 ص366","text":"قال ابن الأعرابي كان حاتم من شعراء العرب وكان جوادا يشبه شعره جوده ويصدق قوله فعله وكان حيثما نزل عرف منزله وكان مظفرا إذا قاتل غلب وإذا غنم أنهب وإذا سئل وهب وإذا ضرب بالقداح فاز وإذا سابق سبق وإذا أسر أطلق وكان يقسم بالله ألا يقتل واحد أمه وكان إذا أهل الشهر الأصم الذي كانت مضر تعظمه في الجاهلية ينحر في كل يوم عشرا من الإبل فأطعم الناس واجتمعوا إليه فكان ممن يأتيه من الشعراء الحطيئة وبشر بن أبي خازم\nفذكروا أن أم حاتم أوتيت وهي حبلى في المنام فقيل لها أغلام سمح يقال له حاتم أحب إليك أم عشرة غلمة كالناس ليوث ساعة البأس ليسوا بأوغال ولا أنكاس فقالت بل حاتم فولدت حاتما فلما ترعرع جعل يخرج طعامه فإن وجد من يأكله معه أكل وإن لم يجد طرحه فلما رأى أبوه أنه يهلك طعامه\nقال له الحق بالإبل فخرج إليها ووهب له جارية وفرسا وفلوها فلما أتى الإبل طفق يبغي الناس فلا يجدهم ويأتي الطريق فلا يجد عليه أحدا فبينا هو كذلك إذ بصر بركب على الطريق فأتاهم فقالوا يا فتى هل من قرى فقال تسألوني عن القرى وقد ترون الإبل وكان الذين بصر بهم عبيد بن الأبرص وبشر بن أبي خازم والنابغة الذبياني وكانوا يريدون النعمان فنحر لهم ثلاثة من الإبل فقال عبيد إنما أردنا بالقرى اللبن وكانت تكفينا ببكرة إذا كنت لا بد متكلفا لنا شيئا فقال حاتم قد عرفت ولكني رأيت وجوها مختلفة وألوانا متفرقة فظننت أن البلدان غير واحدة فأردت أن يذكر كل واحد منكم ما رأى إذا أتى قومه فقالوا فيه أشعارا امتدحوه بها وذكروا فضله فقال حاتم أردت أن أحسن إليكم فكان لكم الفضل علي وأنا أعاهد الله أن أضرب عراقيب إبلي عن آخرها أو تقدموا إليها فتقتسموها ففعلوا فأصاب الرجل تسعة وتسعين بعيرا ومضوا على سفرهم إلى النعمان\nوإن أبا حاتم سمع بما فعل فأتاه فقال له أين الإبل فقال يا أبت طوقتك بها طوق الحمامة مجد الدهر وكرما لا يزال الرجل يحمل بيت شعر أثني به علينا عوضا من إبلك فلما سمع أبوه ذلك قال أبإبلي فعلت ذلك قال نعم قال والله لا أساكنك أبدا فخرج أبوه بأهله وترك حاتما ومعه جاريته وفرسه وفلوها فقال يذكر تحول أبيه عنه\n(وإني لعف الفقر مشترك الغنى ... وتارك شكل لا يوافقه شكلي)\n(وشكلي شكل لا يقوم لمثله ... من الناس إلا كل ذي نيقة مثلي)\n(وأجعل مالي دون عرضي جنة ... لنفسي وأستغني بما كان من فضلي)\n(وما ضرني أن سار سعد بأهله ... وأفردني في الدار ليس معي أهلي)\n(سيكفي ابتنائي المجد سعد بن حشرج ... وأحمل عنكم كل ما ضاع من ثقل)\n(ولي مع بذل المال في المجد صولة ... إذا الحرب أبدت عن نواجذها العصل)\nهذا شعر يدل على أن جده صاحب هذه القصة معه لا أنها قصة أبيه وهكذا ذكر يعقوب بن السكيت ووصف أن أبا حاتم هلك وحاتم صغير فكان في حجر جده سعد بن الحشرج فلما فتح يده بالعطاء وأنهب ماله ضيق عليه جده ورحل عنه بأهله وخلفه في دار فقال يعقوب خاصة فبينا حاتم يوما بعد أن أنهب ماله وهو نائم إذ انتبه وإذا حوله مائتا بعير أو نحوها تجول ويحطم بعضها بعضا فساقها إلى قومه فقالوا يا حاتم أبق على نفسك فقد رزقت مالا ولا تعودن إلى ما كنت عليه من الإسراف قال فإنها نهبى بينكم فانتهبت فأنشأ حاتم يقول\n(تداركني مجدي بسفح متالع ... فلا ييأسن ذو نومة أن يغنما)\nال ولم يزل حاتم على حاله في إطعام الطعام وإنهاب ماله حتى مضى لسبيله","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":1,"spl":"أخبار في كرم حاتم","tags":[],"loc":3123},
{"id":"b228-4","bab":"الجزء 17","sec":"حاتم وبنو لأم","page":"ج17 ص369","text":"قال ابن الأعرابي ويعقوب بن السكيت وسائر من ذكرنا من الرواة خرج الحكم بن أبي العاصي بن أمية بن عبد شمس ومعه عطر يريد الحيرة وكان بالحيرة سوق يجتمع إليه الناس كل سنة وكان النعمان بن المنذر قد جعل لبني لأم بن عمرو بن طريف بن عمرو بن ثمامة بن مالك بن جدعان بن ذهل بن رومان بن حبيب بن خارجة بن سعد بن قطنة بن طيىء ربع الطريق طعمة لهم وذلك لأن بنت سعد بن حارثة بن لأم كانت عند النعمان وكانوا أصهاره فمر الحكم بن أبي العاصي بحاتم بن عبد الله فسأله الجوار في أرض طيىء حتى يصير إلى الحيرة فأجاره ثم أمر حاتم بجزور فنحرت وطبخت أعضاء فأكلوا ومع حاتم ملحان بن حارثة بن سعد بن الحشرج وهو ابن عمه فلما فرغوا من الطعام طيبهم الحكم من طيبة ذلك فمر حاتم بسعد بن حارثة بن لأم وليس مع حاتم من بني أبيه غير ملحان وحاتم على راحلته وفرسه تقاد فأتاه بنو لأم فوضع حاتم سفرته\nوقال أطعموا حياكم الله فقالوا من هؤلاء معك يا حاتم قال هؤلاء جيراني قال له سعد فأنت تجير علينا في بلادنا قال له أنا ابن عمكم وأحق من\nلم تخفروا ذمته فقالوا لست هناك وأرادوا أن يفضحوه كما فضح عامر بن جوين قبله فوثبوا إليه فتناول سعد بن حارثة بن لأم حاتما فأهوى له حاتم بالسيف فأطار أرنبة أنفه ووقع الشر حتى تحاجزوا فقال حاتم في ذلك\n(وددت وبيت الله لو أن أنفه ... هواء فما مت المخاط عن العظم)\n(ولكنما لاقاه سيف ابن عمه ... فآب ومر السيف منه على الخطم)\nقالوا لحاتم بيننا وبينك سوق الحيرة فنماجدك ونضع الرهن ففعلوا ووضعوا تسعة أفراس هنا على يدي رجل من كلب يقال له امرؤ القيس بن عدي ابن أوس بن جابر بن كعب بن عليم بن جناب وهو جد سكينة بنت الحسين بن علي بن أبي طالب صلوات الله عليهما ووضع حاتم فرسه ثم خرجوا حتى انتهوا إلى الحيرة وسمع بذلك إياس بن قبيصة الطائي فخاف أن يعينهم النعمان بن المنذر يقويهم بماله وسلطانه للصهر الذي بينهم وبينه فجمع إياس رهطه من بني حية\nوقال يا بني حية إن هؤلاء القوم قد أرادوا أن يفضحوا ابن عمكم في مجاده أي مماجدته فقال رجل من بني حية عندي مائة ناقة سوداء ومائة ناقة حمراء أدماء وقام آخر فقال عندي عشرة حصن على كل حصان منها فارس\nمدجج لا يرى منه إلا عيناه وقال حسان بن جبلة الخير قد علمتم أن أبي قد مات وترك كلأ كثيرا فعلي كل خمر أو لحم أو طعام ما أقاموا في سوق الحيرة ثم قام إياس فقال علي مثل جميع ما أعطيتم كلكم قال وحاتم لا يعلم بشيء مما فعلوا وذهب حاتم إلى مالك بن جبار ابن عم له بالحيرة كان كثير المال فقال يابن عم أعني على مخايلتي قال والمخايلة المفاخرة ثم أنشد\n(يا مال إحدى خطوب الدهر قد طرقت ... يا مال ما أنتم عنها بزحزاح)\n(يا مال جاءت حياض الموت واردة ... من بين غمر فخضناه وضحضاح)\nقال له مالك ما كنت لأحرب نفسي ولا عيالي وأعطيك مالي فانصرف عنه وقال مالك في ذلك قوله\n(إنا بنو عمكم لا أن نباعلكم ... ولا نجاوركم إلا على ناح)\n(وقد بلوتك إذ نلت الثراء فلم ... ألقك بالمال إلا غير مرتاح)\nال أبو عمرو الشيباني في خبره ثم أتى حاتم ابن عم له يقال له وهم بن عمرو وكان حاتم يومئذ مصارما له لا يكلمه فقالت له امرأته أي وهم هذا والله أبو سفانة حاتم قد طلع فقال ما لنا ولحاتم أثبتي النظر فقالت ها هو\nقال ويحك هو لا يكلمني فما جاء به إلي فنزل حتى سلم عليه ورد سلامه وحياه ثم قال له ما جاء بك يا حاتم قال خاطرت على حسبك وحسبي قال في الرحب والسعة هذا مالي - قال وعدته يومئذ تسعمائة بعير - فخذها مائة مائة حتى تذهب الإبل أو تصيب ما تريد فقالت امرأته يا حاتم أنت تخرجنا من\nمالنا وتفضح صاحبنا - تعني زوجها - فقال اذهبي عنك فوالله ما كان الذي غمك ليردني عما قبلي وقال حاتم\n(ألا أبلغا وهم بن عمرو رسالة ... فإنك أنت المرء بالخير أجدر)\n(رأيتك أدنى الناس منا قرابة ... وغيرك منهم كنت أحبو وأنصر)\n(إذا ما أتى يوم يفرق بيننا ... بموت فكن يا وهم ذو يتأخر)","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":2,"spl":"حاتم وبنو لأم","tags":["الجواري والنساء","السفر والحج"],"loc":3124},
{"id":"b228-5","bab":"الجزء 17","sec":"حاتم وبنو لأم","page":"ج17 ص369","text":"و في لغة طيىء الذي قالوا ثم قال إياس بن قبيصة احملوني إلى الملك وكان به نقرس فحمل حتى أدخل عليه فقال أنعم صباحا أبيت اللعن فقال النعمان وحياك إلهك فقال إياس أتمد أختانك بالمال والخيل وجعلت بني ثعل في قعر الكنانة أظن أختانك أن يصنعوا بحاتم كما صنعوا بعامر بن جوين ولم يشعروا أن بني حية بالبلد فإن شئت والله ناجزناك حتى يسفح الوادي دما فليحضروا مجادهم غدا بمجمع العرب فعرف النعمان الغضب في وجهه وكلامه فقال له النعمان يا أحلمنا لا تغضب فإني سأكفيك وأرسل النعمان إلى سعد بن حارثة وإلى أصحابه انظروا ابن عمكم حاتما فأرضوه فوالله ما أنا بالذي أعطيكم مالي تبذرونه وما أطيق بني حية فخرج بنو لأم إلى حاتم فقالوا له أعرض عن هذا المجاد ندع أرش أنف ابن عمنا قال لا والله لا أفعل حتى تتركوا أفراسكم ويغلب مجادكم فتركوا\nأرش أنف صاحبهم وأفراسهم وقالوا قبحها الله وأبعدها فإنما هي مقارف فعمد إليها حاتم وأطعمها الناس وسقاهم الخمر وقال حاتم في ذلك\n(أبلغ بني لأم فإن خيولهم ... عقرى وإن مجادهم لم يمجد)\n(ها إنما مطرت سماؤكم دما ... ورفعت رأسك مثل رأس الأصيد)\n(ليكون جيراني أكالا بينكم ... نحلا لكندي وسبي مزبد)\n(وابن النجود إذا غدا متلاطما ... وابن الغدور ذي العجان الأبرد)\n(ولثابت عيني جذ متماوت ... وللعمظ أوس قد عوى لمقلد)\n(أبلغ بني ثعل بأني لم أكن ... أبدا لأفعلها طوال المسند)\n(لا جئتهم فلا وأترك صحبتي ... نهبا ولم تغدر بقائمه يدي)\nخرج حاتم في نفر من أصحابه في حاجة لهم فسقطوا على عمرو بن أوس بن طريف بن المثنى بن عبد الله بن يشجب بن عبد ود في فضاء من الأرض فقال لهم أوس بن حارثة بن لأم لا تعجلوا بقتله فإن أصبحتم وقد أحدق الناس بكم استجرتموه وإن لم تروا أحدا قتلتموه فأصبحوا وقد أحدق الناس بهم فاستجاروه فأجارهم فقال حاتم\n(عمرو بن أوس إذا أشياعه غضبوا ... فأحرزوه بلا غرم ولا عار)\n(إن بني عبد ود كلما وقعت ... إحدى الهنات أتوها غير أغمار)","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":3,"spl":"حاتم وبنو لأم — أبو الخيبري وقبر حاتم","tags":["الخمر"],"loc":3125},
{"id":"b228-6","bab":"الجزء 17","sec":"أبو الخيبري وقبر حاتم","page":"ج17 ص373","text":"أخبرني أحمد بن محمد البزار الأطروش عن علي بن حرب عن هشام\nابن محمد عن أبي مسكين جعفر بن المحرز بن الوليد عن أبيه قال قال الوليد جده وهو مولى لأبي هريرة سمعت محرز بن أبي هريرة يتحدث قال كان رجل يقال له أبو الخيبري مر في نفر من قومه بقبر حاتم وحوله أنصاب متقابلات من حجارة كأنهن نساء نوائح\nقال فنزلوا به فبات أبو الخيبري ليلته كلها ينادي أبا جعفر اقر أضيافك قال فيقال له مهلا ما تكلم من رمة بالية فقال إن طيئا يزعمون أنه لم ينزل به أحد إلا قراه\nقال فلما كان من آخر الليل نام أبو الخيبري حتى إذا كان في السحر وثب فجعل يصيح واراحلتاه فقال له أصحابه ويلك مالك قال خرج والله حاتم بالسيف وأنا أنظر إليه حتى عقر ناقتي قالوا كذبت\nقال بلى فنظروا إلى راحلته فإذا هي منخزلة لا تنبعث فقالوا قد والله قراك فظلوا يأكلون من لحمها ثم أردفوه فانطلقوا فساروا ما شاء الله ثم نظروا إلى راكب فإذا هو عدي بن حاتم راكبا قارنا جملا أسود فلحقهم فقال أيكم أبو الخيبري فقالوا هو هذا فقال جاءني أبي في النوم فذكر لي شتمك إياه وأنه قرى راحلتك لأصحابك وقد قال في ذلك أبياتا ورددها حتى حفظتها وهي\n(أبا خيبري وأنت امرؤ ... ظلوم العشيرة شتامها)\n(فماذا أردت إلى رمة ... ببادية صخب هامها)\n(تبغي أذاها وإعسارها ... وحولك غوث وأنعامها)\n(وإنا لنطعم أضيافنا ... من الكوم بالسيف نعتامها)\nقد أمرني أن أحملك على جمل فدونكه فأخذه وركبه وذهبوا","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":3,"spl":"حاتم وبنو لأم — أبو الخيبري وقبر حاتم","tags":["الوصف والطبيعة"],"loc":3126},
{"id":"b228-7","bab":"الجزء 17","sec":"الحارث بن عمر يأسر قوم حاتم وحاتم يطلقهم","page":"ج17 ص375","text":"أغارت طيىء على إبل للنعمان بن الحارث بن أبي شمر الجفني ويقال هو الحارث بن عمرو رجل من بني جفنة وقتلوا ابنا له وكان الحارث إذا غضب حلف ليقتلن وليسبين الذراري فحلف ليقتلن من بني الغوث أهل بيت على دم واحد فخرج يريد طيئا فأصاب من بني عدي بن أخزم سبعين رجلا وهم ابن عمرو من رهط حاتم - وحاتم يومئذ بالحيرة عند النعمان - فأصابتهم مقدمات خيله فلما قدم حاتم الجبلين جعلت المرأة تأتيه بالصبي من ولدها فتقول يا حاتم أسر أبو هذا فلم يلبث إلا ليلة حتى سار إلى النعمان ومعه ملحان بن حارثة وكان لا يسافر إلا وهو معه فقال حاتم\n(ألا إنني قد هاجني الليلة الذكر ... وما ذاك من حب النساء ولا الأشر)\n(ولكنه مما أصاب عشيرتي ... وقومي بأقران حواليهم الصير)\nالأقران الحبال والصير الحظائر واحدها صيرة\n(ليالي نمشي بين جو ومسطح ... نشاوى لنا من كل سائمة جزر)\n(فيا ليت خبر الناس حيا وميتا ... يقول لنا خيرا ويمضي الذي ائتمر)\n(فإن كان شرا فالعزاء فإننا ... على وقعات الدهر من قبلها صبر)\n(سقى الله رب الناس سحا وديمة ... جنوب السراة من مآب إلى زغر)\n(بلاد امرىء لا يعرف الذم بيته ... له المشرب الصافي ولا يطعم الكدر)\n(تذكرت من وهم بن عمرو جلادة ... وجرأة مغزاه إذا صارخ بكر)\n(فأبشر وقر العين منك فإنني ... أحيي كريما لا ضعيفا ولا حصر)\nدخل حاتم على النعمان فأنشده فأعجب به واستوهبهم منه فوهب له بني امرىء القيس بن عدي ثم أنزله فأتي بالطعام والخمر فقال له ملحان أتشرب الخمر وقومك في الأغلال قم إليه فسله إياهم فدخل عليه فأنشده\n(إن امرأ القيس أضحت من صنيعتكم ... وعبد شمس - أبيت اللعن - فاصطنعوا)\n(إن عديا إذا ملكت جانبها ... من أمر غوث على مرأى ومستمع)\n(أتبع بني عبد شمس أمر صاحبهم ... أهلي فداؤك إن ضروا وإن نفعوا)\n(لا تجعلنا - أبيت اللعن - ضاحية ... كمعشر صلموا الآذان أو جدعوا)\n(أو كالجناح إذا سلت قوادمه ... صار الجناح لفضل الريش يتبع)\nأطلق له بني عبد شمس بن عدي بن أخزم وبقي قيس بن جحدر بن ثعلبة ابن عبد رضي بن مالك بن ذبيان بن عمرو بن ربيعة بن جرول الأجئي وهو من لخم وأمه من بني عدي وهو جد الطرماح بن حكيم بن نفر بن قيس بن جحدر فقال له النعمان أفبقي أحد من أصحابك فقال حاتم\n(فككت عديا كلها من إسارها ... فافضل وشفعني بقيس بن جحدر)\n(أبوه أبي والأمهات أمهاتنا ... فأنعم فدتك اليوم نفسي ومعشري)\nقال هو لك يا حاتم فقال حاتم\n(أبلغ الحارث بن عمرو بأني ... حافظ الود مرصد للثواب)\n(ومجيب دعاءه إن دعاني ... عجلا واحدا وذا أصحاب)\n(إنما بيننا وبينك فاعلم ... سير تسع للعاجل المنتاب)\n(فثلاث من السراة إلى الحلة ... للخيل جاهدا والركاب)\n(وثلاث يوردن تيماء رهوا ... وثلاث يقربن بالأعجاب)\n(فإذا ما مررن في مسبطر ... فاجمح الخيل مثل جمح الكعاب)\nجمح ارم بهم كما يرمى بالكعاب ويقال إذا انتصب لك أمر فقد جمح\n(بينما ذاك أصبحت وهي عضدى ... من سبي مجموعة ونهاب)\nضدى مكسورة الأعضاد\n(ليت شعري متى أرى قبة ذات ... قلاع للحارث الحراب)\n(بيفاع وذاك منها تحل ... فوق ملك يدين بالأحساب)\n(أيها الموعدي فإن لبوني ... بين حقل وبين هضب دباب)\n(حيث لا أرهب الجرأة وحولي ... ثعليون كالليوث الغضاب)\nقال حاتم أيضا\n(لم تنسني أطلال ماوية يأسي ... ولا الزمن الماضي الذي مثله ينسي)\n(إذا غربت شمس النهار وردتها ... كما يرد الظمآن آتية الخمس)","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":4,"spl":"الحارث بن عمر يأسر قوم حاتم وحاتم يطلقهم","tags":["الحب والغزل","الوصف والطبيعة"],"loc":3127},
{"id":"b228-8","bab":"الجزء 17","sec":"حاتم وماوية بنت عفزر","page":"ج17 ص379","text":"قال وكنا عند معاوية فتذاكرنا ملوك العرب حتى ذكرنا الزباء وابنة عفزر فقال معاوية إني لأحب أن أسمع حديث ماوية وحاتم وماوية بنت عفزر فقال رجل من القوم أفلا أحدثك يا أمير المؤمنين فقال بلى فقال إن ماوية بنت عفزر كانت ملكة وكانت تتزوج من أرادت وإنها بعثت غلمانا لها وأمرتهم أن يأتوها بأوسم من يجدونه بالحيرة فجاؤوها بحاتم فقالت له استقدم إلى الفراش فقال حتى أخبرك وقعد على الباب\nوقال إني أنتظر صاحبين لي فقالت دونك أستدخل المجمر فقال استي لم تعود المجمر فأرسلها مثلا فارتابت منه وسقته خمرا ليسكر فجعل يهريقه بالباب فلا تراه تحت الليل ثم\nقال ما أنا بذائق قرى ولا قار حتى أنظر ما فعل صاحباي فقالت إنا سنرسل إليهما بقرى فقال حاتم ليس بنافعي شيئا أو آتيهما قال فأتاهما فقال أفتكونان عبدين لابنة غفزر ترعيان غنمها أحب إليكما أم تقتلكما فقالا كل شيء يشبه بعضه بعضا وبعض الشر أهون من بعض فقال حاتم الرحيل والنجاة وقال يذكر ابنة عفزر وأنه ليس بصاحب ريبة\n(حننت إلى الأجبال أجبال طيىء ... وحنت قلوصي أن رأت سوط أحمرا)\n(فقلت لها إن الطريق أمامنا ... وإنا ملحيو ربعنا إن تيسرا)\n(فيا راكبي عليا جديلة إنما ... تسامان ضيما مستبينا فتنظرا)\n(فما نكراه غير أن ابن ملقط ... أراه وقد أعطى الظلامة أوجرا)\n(وإني لمزج للمطي على الوجا ... وما أنا من خلانك ابنة عفزرا)\n(وما زلت أسعى بين ناب ودارة ... بلحيان حتى خفت أن أتنضرا)\n(وحتى حسبت الليل والصبح إذ بدا ... حصانين سيالين جونا وأشقرا)\n(لشعب من الريان أملك بابه ... أنادي به آل الكبير وجعفرا)\n(أحب إلي من خطيب رأيته ... إذا قلت معروفا تبدل منكرا)\n(تنادي إلى جاراتها إن حاتما ... أراه لعمري بعدنا قد تغيرا)\n(تغيرت إني غير آت لريبة ... ولا قائل يوما لذي العرف منكرا)\n(فلا تسأليني واسألي أي فارس ... إذا بادر القوم الكنيف المسترا)\n(ولا تسأليني واسألي أي فارس ... إذا الخيل جالت في قنا قد تكسرا)\n(فلا هي ما ترعى جميعا عشارها ... ويصبح ضيفي ساهم الوجه أغبرا)\n(متى ترني أمشي بسيفي وسطها ... تخفني وتضمر بينها أن تجزرا)\n(وإني ليغشى أبعد الحي جفتني ... إذا ورق الطلح الطوال تحسرا)\n(فلا تسأليني واسألي بي صحبتي ... إذا ما المطي بالفلاة تضورا)\n(وإني لوهاب قطوعي وناقتي ... إذا ما انتشيت والكميت المصدرا)\n(وإني كأشلاء اللجام ولن تري ... أخا الحرب إلا ساهم الوجه أغبرا)\n(أخو الحرب إن عضت به الحرب عضها ... وإن شمرت عن ساقها الحرب شمرا)\n(وإني إذا ما الموت لم يك دونه ... قدى الشبر أحمى الأنف أن أتأخرا)\n(متى تبغ ودا من جديلة تلقه ... مع الشنء منه باقيا متأثرا)\n(فإلا يفادونا جهارا نلاقهم ... لأعدائنا ردءا دليلا ومنذرا)\n(إذا حال دوني من سلامان رملة ... وجدت توالي الوصل عندي ابترا)\nذكروا أن حاتما دعته نفسه إليها بعد انصرافه من عندها فأتاها يخطبها فوجد عندها النابغة ورجلا من الأنصار من النبيت فقالت لهم انقلبوا إلى رحالكم وليقل كل واحد منكم شعرا يذكر فيه فعاله ومنصبه فإني أتزوج أكرمكم وأشعركم فانصرفوا ونحر كل واحد منهم جزورا ولبس ماوية ثيابا لأمة لها وبتعتهم فأتت النبيتي فاستطعمته من جزوره فأطعمها ثيل جمله فأخذته ثم أتت نابغة بني ذبيان فاستطعمته فأطعمها ذنب جزوره فأخذته ثم أتت حاتما وقد نصب قدره فاستطعمته فقال لها قفي حتى أعطيك ما تنتفعين به إذا صار إليك فانتظرت فأطعمها قطعا من العجز والسنام ومثلها من المخدش وهو عند\nالحارك ثم انصرفت وأرسل كل واحد منهم إليها ظهر جمله وأهدى حاتم إلى جاراتها مثل ما أسل إليها ولم يكن يترك جاراته إلا بهدية وصبحوها فاستنشدتهم فأنشدها النبيتي\n(هلا سألت النبيتيين ما حسبي ... عند الشتاء إذا ما هبت الريح)\n(ورد جازرهم حرفا مصرمة ... في الرأس منها وفي الأصلاء تمليح)\n(وقال رائدهم سيان مالهم ... مثلان مثل لمن يرعى وتسريح)\n(إذا اللقاح غدت ملقى أصرتها ... ولا كريم من الولدان مصبوح)\nقالت له لقد ذكرت مجهدة ثم استنشدت النابغة فأنشدها يقول\n(هلا سألت بني ذبيان ما حسبي ... إذا الدخان تغشى الأشمط البرما)\n(وهبت الريح من تلقاء ذي أرل ... تزجي مع الليل من صرادها الصرما)\n(إني أتمم أيساري وأمنحهم ... مثنى الأيادي وأكسو الجفنة الأدما)","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":5,"spl":"حاتم وماوية بنت عفزر","tags":["الجواري والنساء"],"loc":3128},
{"id":"b228-9","bab":"الجزء 17","sec":"حاتم وماوية بنت عفزر","page":"ج17 ص379","text":"لما أنشدها قالت ما ينفك الناس بخير ما ائتدموا\nثم قالت يا أخا طيئ أنشدني فأنشدها\n(أماوي قد طال التجنب والهجر ... وقد عذرتني في طلابكم العذر)\n(أماوي إن المال غاد ورائح ... ويبقى من المال الأحاديث والذكر)\n(أماوي إني لا أقول لسائل ... إذا جاء يوما حل في مالنا النذر)\n(أماوي إما مانع فمبين ... وإما عطاء لا ينهنهه الزجر)\n(أماوي ما يغني الثراء عن الفتى ... إذا حشرجت يوما وضاق بها الصدر)\n(إذا أنا دلاني الذين أحبهم ... بملحودة زلج جوانبها غبر)\n(وراحوا سراعا ينفضون أكفهم ... يقولون قد دمى أناملنا الحفر)\n(أماوي إن يصبح صداي بقفزة ... من الأرض لا ماء لدي ولا خمر)\n(ترى أن ما أنفقت لم يك ضرني ... وأن يدي مما بخلت به صفر)\n(أماوي إني رب واحد أمه ... أخذت فلا قتل عليه ولا أسر)\n(وقد علم الأقوام لو أن حاتما ... أراد ثراء المال كان له وفر)\n(فإني لا آلو بمالي صنيعة ... فأوله زاد وآخره ذخر)\n(يفك به العاني ويؤكل طيبا ... وما إن تعرته القداح ولا الخمر)\n(ولا أظلم ابن العم إن كان إخوتي ... شهودا وقد أودى بإخوته الدهر)\n(غنينا زمانا بالتصعلك والغنى ... وكلا سقاناه بكأسهما العصر)\n(فما زادنا بغيا على ذي قرابة ... غنانا ولا أزرى بأحسابنا الفقر)\n(وما ضر جارا يابنة القوم فاعلمي ... يجاورني ألا يكون له ستر)\n(بعيني عن جارات قومي غفلة ... وفي السمع مني عن حديثهم وقر)\nلما فرغ حاتم من إنشاده دعت بالغداء وكانت قد أمرت إماءها أن يقدمن إلى كل رجل منهم ما كان أطعمها فقدمن إليهم ما كانت أمرتهن أن يقدمنه إليهم فنكس النبيتي رأسه والنابغة فلما نظر حاتم إلى ذلك رمى بالذي قدم إليهما وأطعمهما مما قدم إليه فتسللا لواذا وقالت إن حاتما أكرمكم وأشعركم فلما خرج النبيتي والنابغة قالت لحاتم خل سبيل امرأتك فأبى فزودته وردته فلما انصرف دعته نفسه إليها وماتت امرأته فخطبها فتزوجنه فولدت عديا","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":6,"spl":"حاتم وماوية بنت عفزر","tags":["الخمر"],"loc":3129},
{"id":"b228-10","bab":"الجزء 17","sec":"إسلام عدي بن حاتم","page":"ج17 ص384","text":"وقد كان عدي أسلم وحسن إسلامه فبلغنا أن النبي قال له وقد سأله عدي يا رسول الله أن أبي كان يعطي ويحمل ويوفي بالذمة ويأمر بمكارم الأخلاق فقال له رسول الله إن أباك خشبة من خشبات جهنم فكأن النبي رأى الكآبة في وجهه فقال له يا عدي إن أباك وأبي وأبا إبراهيم في النار وكانت ماوية عنده زمانا وإن ابن عم لحاتم كان يقال له مالك\nقال لها ما تصنعين بحاتم فوالله لئن وجد شيئا ليتلفنه وإن لمن يجد ليتكلفن وإن مات ليتركن ولده عيالا على قومك فقالت ماوية صدقت إنه كذلك\nوكان النساء - أو بعضهن - يطلقن الرجال في الجاهلية وكان طلاقهن أنهن إن كن في بيت من شعر حولن الخباء فإن كان بابه قبل المشرق حولنه قبل المغرب وإن كان بابه قبل اليمن حولنه قبل الشام فإذا رأى ذلك الرجل علم أنها قد طلقته فلم يأتها وإن ابن عم حاتم\nقال لماوية - وكانت أحسن نساء الناس - طلقي حاتما وأنا أنكحك وأنا خير لك منه وأكثر مالا وأنا أمسك عليك وعلى ولدك فلم يزل بها حتى طلقت حاتما فأتاها حاتم وقد حولت باب الخباء فقال يا عدي ما ترى أمك عدي عليها\nقال لا أدري غير أنها قد غيرت باب الخباء وكأنه لم يلحن لما قال فدعاه فهبط به بطن واد وجاء قوم فنزلوا على باب الخباء كما كانوا ينزلون فتوافوا خمسين رجلا فضاقت بهم ماوية ذرعا وقالت لجاريتها اذهبي إلى مالك فقولي له إن أضيافا لحاتم قد نزلوا بنا خمسين رجلا فأرسل بناب نقرهم ولبن نغبقهم وقالت لجاريتها انظري إلى جبينه وفمه فإن شافهك بالمعروف فاقبلي منه وإن ضرب بلحيته على زوره وأدخل يده في رأسه فاقفلي ودعيه وإنها لما أتت مالكا وجدته متوسدا وطبا من لبن وتحت بطنه آخر فأيقظته فأدخل يده في رأسه وضرب بلحيته على زوره فأبلغته ما أرسلتها به ماوية وقالت إنما هي الليلة حتى يعلم الناس مكانه فقال لها اقرئي عليها السلام وقولي لها هذا الذي أمرتك أن تطلقي حاتما فيه فما عندي من كبيرة قد تركت العمل وما كنت لأنحر صفية غزيرة بشحم كلاها وما عندي لبن يكفي أضياف حاتم\nفرجعت الجارية فأخبرتها بما رأت منه وما قال فقالت ائت حاتما فقولي إن أضيافك قد نزلوا الليلة بنا ولم يعلموا بمكانك فأرسل إلينا بناب ننحرها ونقرهم وبلبن نسقهم فإنما هي الليلة حتى يعرفوا مكانك فأتت الجارية حاتما فصرخت به فقال حاتم لبيك قريبا دعوت فقالت إن ماوية تقرأ عليك السلام وتقول لك إن أضيافك قد نزلوا بنا الليلة فأرسل إليهم بناب ننحرها ولبن نسقهم فقال نعم وأبي ثم قام إلى الإبل فأطلق ثنيتين من عقالهما ثم صاح بهما حتى أتى الخباء فضرب عراقيبهما فطفقت ماوية تصبح وتقول هذا الذي طلقتك فيه تترك ولدك وليس لهم شيء فقال حاتم\n(هل الدهر إلا اليوم أو أمس أو غد ... كذاك الزمان بيننا يتردد)\n(يرد علينا ليلة بعد يومها ... فلا نحن ما نبقى ولا الدهر ينفد)\n(لنا أجل إما تناهى أمامه ... فنحن على آثاره نتورد)\n(بنو ثعل قومي فما أنا مدع ... سواهم إلى قوم وما أنا مسند)\n(بدرئهم أغشى دروء معاشر ... ويحنف عني الأبلخ المتعمد)\n(فمهلا فداك اليوم أمي وخالتي ... فلا يأمرني بالدنية أسود)\n(على حين أن ذكيت واشتد جانبي ... أسام التي أعييت إذ أنا أمرد)\n(فهل تركت قبلي حضور مكانها ... وهل من أتى ضيما وخسفا مخلد)\n(ومعتسف بالرمح دون صحابه ... تعسفته بالسيف والقوم شهد)\n(فخر على حر الجبين وذاده ... الى الموت مطرور الوقيعة مذود)\n(فما رمته حتى أزحت عويصه ... وحتى علاه حالك اللون أسود)\n(فأقسمت لا أمشي على سرجارتي ... يد الدهر ما دام الحمام يغرد)\n(ولا أشتري مالا بغدر علمته ... ألا كل مال خالط الغدر أنكد)\n(إذا كان بعض المال ربا لأهله ... فإني بحمد الله مالي معبد)\n(يفك به العاني ويؤكل طيبا ... ويعطى إذا ضن البخيل المصرد)\n(إذا ما البخيل الخب أخمد ناره ... أقول لمن يصلى بناري أوقدوا)\n(توسع قليلا أو يكن ثم حسبنا ... وموقدها البادي أعف وأحمد)\n(كذاك أمور الناس راض دنية ... وسام إلى فرع العلا متورد)\n(فمنهم جواد قد تلفت حوله ... ومنهم لئيم دائم الطرف أقود)\n(وداع دعاني دعوة فأجبته ... وهل يدع الداعين إلا اليلندد)","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":7,"spl":"إسلام عدي بن حاتم","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":3130},
{"id":"b228-11","bab":"الجزء 17","sec":"إسلام عدي بن حاتم","page":"ج17 ص384","text":"سرت عنزة حاتما فجعل نساء عنزة يدارئن بعيرا ليفصدنه فضعفن عنه فقلن يا حاتم أفاصده أنت إن أطلقنا يديك قال نعم فأطلقن إحدى يديه فوجأ لبته فاستدمينه ثم إن البعير عضد أي لوى عنقه أي خر فقلن ما صنعت قال هكذا فصادتي فجرت مثلا قال فلطمته إحداهن فقال ما أنتن نساء عنزة بكرام ولا ذوات أحلام وإن امرأة منهن يقال لها عاجزة أعجبت به فأطلقته ولم ينقموا عليه ما فعل فقال حاتم يذكر البعير الذي فصده\n(كذلك فصدي إن سألت مطيتي ... دم الجوف إذ كل الفصاد وخيم)\nقبل ركب من بني أسد من قيس يريدون النعمان فلقوا حاتما فقالوا له إنا تركنا قومنا يثنون عليك خيرا وقد أرسلوا إليك رسولا برسالة قال وما هي فأنشده الأسديون شعرا لعبيد ولبشر يمدحانه\nوأنشد القيسيون شعرا للنابغة فلما أنشدوه قالوا إنا نستحي أن نسألك شيئا وإن لنا لحاجة قال وما هي قالوا صاحب لنا قد أرجل فقال حاتم خذوا فرسي هذه فاحملوا عليها صاحبكم فأخذوها وربطت الجارية فلوها بثوبها فأفلت فاتبعته الجارية فقال حاتم ما تبعكم من شيء فهو لكم فذهبوا بالفرس والفلو والجارية وإنهم وردوا على أبي حاتم فعرف الفرس والفلو فقال ما هذا معكم فقالوا مررنا بغلام كريم فسألناه فأعطى الجسيم\nقال وكنا عند معاوية فتذاكرنا الجود فقال رجل من القوم أجود الناس حيا وميتا حاتم فقال معاوية وكيف ذلك فإن الرجل من قريش ليعطي في المجلس ما لم يملكه حاتم قط ولا قومه فقال أخبرك يا أمير المؤمنين أن نفرا من بني أسد مروا بقبر حاتم فقالوا لنبخلنه ولنخبرن العرب أنا نزلنا بحاتم فلم يقرنا فجعلوا ينادون يا حاتم ألا تقري أضيافك وكان رئيس القوم رجل يقال له أبا الخيبري فإذا هو بصوت ينادي في جوف الليل\n(أبا خيبري وأنت امرؤ ... ظلوم العشيرة شتامها)\nلى آخرها فذهبوا ينظرون فإذا ناقة أحدهم تكوس على ثلاثة أرجل عقيرا قال فعجب القوم من ذلك جميعا","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":8,"spl":"إسلام عدي بن حاتم — حاتم وأوس بن سعد","tags":["المديح","الجواري والنساء"],"loc":3131},
{"id":"b228-12","bab":"الجزء 17","sec":"حاتم وأوس بن سعد","page":"ج17 ص389","text":"وكان أوس بن سعد قال للنعمان بن المنذر أنا أدخلك بين جبلي طيئ حتى يدين لك أهلهما فبلغ ذلك حاتما فقال\n(ولقد بغى بخلاد أوس قومه ... ذلا وقد علمت بذلك سنبس)\n(حاشا بني عمرو بن سنبس إنهم ... منعوا ذمار أبيهم أن يدنسوا)\n(وتواعدوا ورد القرية غدوة ... وحلفت بالله العزيز لنحبس)\n(والله يعلم لو أتى بسلافهم ... طرف الجريض لظل يوم مشكس)\n(كالنار والشمس التي قالت لها ... بيد اللويمس عالما ما يلمس)\n(لا تطعمن الماء إن أوردتهم ... لتمام ظمئكم ففوزوا واحلسوا)\n(أو ذو الحصين وفارس ذو مرة ... بكتيبة من يدركوه يفرس)\n(وموطأ الأكناف غير ملعن ... في الحي مشاء إليه المجلس)\nال وجاور في بني بدر زمن احتربت جديلة وثعل وكان ذلك زمن الفساد فقال يمدح بني بدر\n(إن كنت كارهة معيشتنا ... هاتي فحلي في بني بدر)\n(جاورتهم زمن الفساد فنعم ... الحي في العوصاء واليسر)\n(فسقيت بالماء النمير ولم ... ينظر إلي بأعين خزر)\n(الضاربين لدى أعنتهم ... والطاعنين وخيلهم تجري)\n(الخالطين نحيتهم بنضارهم ... وذوي الغنى منهم بذي الفقر)\nزعموا أن حاتما خرج في الشهر الحرام يطلب حاجة فلما كان بأرض عنزة ناداه أسير لهم يا أبا سفانة أكلني الإسار والقمل قال ويلك والله ما أنا في بلاد قومي وما معي شيء وقد أسأت بي إذ نوهت باسمي ومالك مترك فساوم به العنزيين فاشتراه منهم فقال خلوا عنه وأنا أقيم مكانه في قيده حتى أؤدي فداءه ففعلوا فأتي بفدائه","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":8,"spl":"إسلام عدي بن حاتم — حاتم وأوس بن سعد","tags":["المديح"],"loc":3132},
{"id":"b228-14","bab":"الجزء 17","sec":"حديث ماوية عن كرم حاتم — حاتم والمحرق عمرو بن هند","page":"ج17 ص390 – ج17 ص391","text":"وحدث الهيثم بن عدي عمن حدثه عن ملحان ابن أخي ماوية امرأة حاتم قال قلت لماوية ياعمة حدثيني بعض عجائب حاتم فقالت كل أمره عجب فعن أيه تسأل\nقال قلت حدثينى ما شئت قالت أصابت الناس سنة فأذهبت الخف والظلف فإني وإياه ليلة قد أسهرنا الجوع قالت فأخذ عديا وأخذت سفانة وجعلنا نعللهما حتى ناما حتى أقبل علي يحدثني ويعللني بالحديث كي أنام فرققت له لما به من الجهد فأمسكت عن كلامه لينام فقال لي أنمت مرارا فلم أجب فسكت فنظر في فتق الخباء فإذا شيء قد أقبل فرفع رأسه فإذا امرأة فقال ما هذا قالت يا أبا سفانة أتيتك من عند صبية\nيتعاوون كالذئاب جوعا فقال أحضريني صبيانك فوالله لأشبعنهم قالت فقمت سريعا فقلت بماذا يا حاتم فوالله ما نام صبيانك من الجوع إلا بالتعليل فقال والله لأشبعن صبيانك مع صبيانها فلما جاءت قام إلى فرسه فذبحها ثم قدح نارا ثم أججها ثم دفع إليها شفرة فقال اشتوي وكلي ثم\nقال أيقظي صبيانك قالت فأيقظتهم ثم قال والله إن هذا للؤم تأكلون وأهل الصوم حالهم مثل حالكم فجعل يأتي الصرم بيتا بيتا فيقول انهضوا عليكم بالنار\nقال فاجتمعوا حول تلك الفرس وتقنع بكسائه فجلس ناحية فما أصبحوا ومن الفرس على الأرض قليل ولا كثير إلا عظم وحافر وإنه لأشد جوعا منهم وما ذاقه\nأتى حاتم محرقا فقال له محرق بايعني فقال له إن لي أخوين ورائي فإن يأذنا لي أبايعك وإلا فلا قال فاذهب إليهما فإن أطاعاك فأتني بهما وإن أبيا فأذن بحرب فلما خرج حاتم قال\n(أتاني من الريان أمس رسالة ... وعدوى وغي ما يقول مواسل)\n(هما سألاني ما فعلت وإنني ... كذلك عما أحدثا أنا سائل)\n(فقلت ألا كيف الزمان عليكما ... فقالا بخير كل أرضك سائل)\nقال محرق ما أخواه قال طرفا الجبل فقال ومحلوفه لأجللن مواسلا\nالريط مصبوغات بالزيت ثم لأشعلنه بالنار فقال رجل من الناس جهل مرتقى بين مداخل سبلات فلما بلغ ذلك محرقا قال لأقدمن عليك قريتك ثم إنه أتاه رجل فقال له إنك إن تقدم القرية تهلك فانصرف ولم يقدم غزت فزارة طيئا وعليهم حصين بن حذيفة وخرجت طيىء في طلب القوم فلحق حاتم رجلا من بدر فطعنه ثم مضى فقال إن مر بك أحد فقل له أنا أسير حاتم فمر به أبو حنبل فقال من أنت\nقال أنا أسير حاتم فقال له إنه يقتلك فإن زعمت لحاتم أو لمن سألك أني أسرتك ثم صرت في يدي خليت سبيلك فلما رجعوا قال حاتم يا أبا حنبل خل سبيل أسيري فقال أبو حنبل أنا أسرته فقال حاتم قد رضيت بقوله فقال أسرني أبو حنبل فقال حاتم\n(إن أباك الجون لم يك غادرا ... ألا من بني بدر أتتك الغوائل)\n\n(وهاجرة من دون مية لم تقل ... قلوصي بها والجندب الجون يرمح)\n(بتيهاء مقفار يكاد ارتكاضها ... بآل الضحى والهجر بالطرف يمصح)\nلهجر ها هنا مرفوع بفعله كأنه قال يكاد ارتكاضها بالآل يمصح بالطرف هو والهجر ويمصح يذهب بالطرف\n(كأن الفرند المحض معصوبة به ... ذرا قورها ينقد عنها وينصح)\n(إذا ارفض أطراف السياط وهللت ... جروم المهاري عد منهن صيدح)\nعروضه من الطويل الهاجرة تكون وقت الزوال والجندب الجرادة والجون الأسود والجون الأبيض أيضا وهو من الأضداد وقوله يرمح أي ينزو من شدة الحر لا يكاد يستقر على الأرض والتيهاء من الأرض التي يتاه فيها والمقفار التي لا أحد فيها ولا ساكن بها\nذكر ذلك أبو نصر عن الأصمعي وارتكاضها يعني ارتكاض هذه التيهاء وهو نزولها بالآل والآل السراب والهجر والهاجرة واحد وقوله الهجر بالطرف يمصح رفع الهجر بفعله كأنه\nقال يكاد ارتكاضها بالآل يمصح بالطرف هو والهجر يمصح يذهب بالطرف والفرند الحرير الأبيض والمحض الخالص يقول كأن هذا السراب حرير أبيض وقد عصبت به ذرى قورها وهي الجبال الصغار والواحدة قارة فتارة يغطيها وتارة ينجاب عنها وينكشف فكأنه إذا انكشف عنها ينقد عنها وكأنه إذا غطاها ينصح عنها أي يخاط ويقال نصحت الثوب إذا خطته والناصح الخياط والنصاح الخيط وقوله ارفض أطراف السياط يعني أنها انفتحت أطرافها من طول السفر وأصل الأرفضاض التفرق والجروم الأبدان واحدها جرم بالكسر وقوله هللت جروم المطايا يعني أنها صارت كالأهلة في الدقة وصيدح اسم ناقته الشعر لذي الرمة والغناء لإبراهيم الموصلي ماخوري بالوسطى تم الجزء السابع عشر من كتاب الأغاني ويليه الجزء الثامن عشر وأوله ذكر ذي الرمة وخبره","topic":"أخبار حاتم ونسبه","topicNo":228,"sp":9,"spl":"حديث ماوية عن كرم حاتم — حاتم والمحرق عمرو بن هند","tags":[],"song":1,"loc":3133},
{"id":"b229-1","bab":"الجزء 18","sec":"ذكر ذي الرمة وخبره","page":"ج18 ص5","text":"اسمه غيلان بن عقبة بن مسعود بن حارثة بن عمرو بن ربيعة بن ملكان بن عدي بن عبد مناة بن أد بن طابخة بن إلياس بن مضر وقال ابن سلام هو غيلان بن عقبة بن بهيش بن مسعود بن حارثة بن عمرو بن ملكان ويكنى أبا الحارث وذو الرمة لقب يقال لقبته به مية وكان اجتاز بخبائها وهي جالسة إلى جنب أمها فاستسقاها ماء فقالت لها أمها قومي فاسقيه\nوقيل بل خرق إداوته لما رآها وقال لها اخرزي لي هذه فقالت والله ما أحسن ذلك فإني لخرقاء قال والخرقاء التي لا تعمل بيدها شيئا لكرامتها على قومها فقال لأمها مريها أن تسقيني ماء فقالت لها قومي يا خرقاء فاسقيه ماء فقامت فأتته بماء وكانت على كتفه رمة وهي قطعة من حبل فقالت اشرب يا ذا الرمة فلقب بذلك وحكى ابن قتيبة أن هذه القصة جرت بينه وبين خرقاء العامرية وقال ابن حبيب لقب ذا الرمة لقوله\n(أشعث باقي رمة التقليد ... )\nوقيل بل كان يصيبه في صغره فزع فكتبت له تميمة فعلقها بحبل فلقب بذلك ذا الرمة ونسخت من كتاب محمد بن داود بن الجراح حدثني هارون بن محمد بن عبد الملك الزيات عن محمد بن صالح العدوي عن أبيه\nوعن أشياخه وعدة من أهل البادية من بني عدي منهم زرعة بن أذبول وابنه سليمان وأبو قيس وتميم وغيرهم من علمائهم أن أم ذي الرمة جاءت إلى الحصين بن عبدة بن نعيم العدوي وهو يقرىء الأعراب بالبادية احتسابا بما يقيم لهم صلاتهم فقالت له يا أبا الخليل إن ابني هذا يروع بالليل فاكتب لي معاذة أعلقها على عنقه فقال لها ائتيني برق أكتب فيه قالت فإن لم يكن فهل يستقيم في غير رق أن يكتب له\nقال فجيئيني بجلد فأتته بقطعة جلد غليظ فكتب له معاذة فيه فعلقته في عنقه فمكث دهرا ثم إنها مرت مع ابنها لبعض حوائجها بالحصين وهو جالس في ملأ من أصحابه ومواليه فدنت منه فسلمت عليه وقالت يا أبا الخليل ألا تسمع قول غيلان وشعره\nقال بلى فتقدم فأنشده وكانت المعاذة مشدودة على يساره في حبل أسود فقال الحصين أحسن ذو الرمة فغلبت عليه وقال الأصمعي أم ذي الرمة امرأة من بني أسد يقال لها ظبية وكان له إخوة لأبيه وأمه شعراء منهم مسعود وهو الذي يقول يرثي أخاه ذا الرمة ويذكر ليلى بنته\n(إلى الله أشكو لا إلى الناس أنني ... وليلى كلانا موجع مات وافده)\nولمسعود يقول ذو الرمة\n(أقول لمسعود بجرعاء مالك ... وقد هم دمعي أن تسح أوائله)\n(ألا هل ترى الأظعان جاوزن مشرفا ... من الرمل أو سالت بهن سلاسله)\nنى فيه يحيى بن المكي ثاني ثقيل بالوسطى على مذهب إسحاق من رواية عمرو ومسعود الذي يقول يرثي أخاه أيضا ذا الرمة ويرثي أوفى بن دلهم ابن عمه وأوفى هذا أحد من يروى عنه الحديث\nوقال هارون بن الزيات أخبرني ابن حبيب عن ابن الأعرابي قال كان لذي الرمة إخوة ثلاثة مسعود وجرفاس وهشام كلهم شعراء وكان الواحد منهم يقول الأبيات فيبني عليها ذو الرمة أبياتا أخر فينشدها الناس فيغلب عليها لشهرته وتنسب إليه\n(نعى الركب أوفى حين آبت ركابهم ... لعمري لقد جاؤوا بشر فأوجعوا)\n(نعوا باسق الأخلاق لا يخلفونه ... تكاد الجبال الصم منه تصدع)\n(خوى المسجد المعمور بعدد ابن دلهم ... فأضحى بأوفى قومه قد تضعضعوا)\n(تعزيت عن أوفى بغيلان بعد ... عزاء وجفن العين ملآن مترع)\n(ولم تنسني أوفى المصيبات بعده ... ولكن نكاء القرح بالقرح أوجع)\nأخوه الآخر هشام وهو رباه وكان شاعرا ولذي الرمة يقول\n(أغيلان إن ترجع قوى الود بيننا ... فكل الذي ولى من العيش راجع)\n(فكن مثل أقصى الناس عندي فإنني ... بطول التنائي من أخي السوء قانع)\nوقال ذو الرمة لهشام أخيه\n(أغر هشاما من أخيه ابن أمه ... قوادم ضأن أقبلت وربيع)\n(وهل تخلف الضأن الغزار أخا الندى ... إذا حل أمر في الصدور فظيع)\nأجابه هشام فقال\n(إذا بان مالي من سوامك لم يكن ... إليك ورب العالمين رجوع)\n(فأنت الفتى ما اهتز في الزهر الندي ... وأنت إذا اشتد الزمان منوع)\nذكر المهلبي عن أبي كريمة النحوي قال\nخرج ذو الرمة يسير مع أخيه مسعود بأرض الدهناء فسنحت لهما ظبية فقال ذو الرمة\n(أقول لدهناوية عوهج جرت ... لنا بين أعلى برقة بالصرائم)\n(أيا ظبية الوعساء بين جلاجل ... وبين النقا آأنت أم أم سالم)\nقال مسعود\n(فلو تحسن التشبيه والنعت لم تقل ... لشاة النقا آأنت أم أم سالم)\n(جعلت لها قرنين فوق قصاصها ... وظلفين مسودين تحت القوائم)","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":0,"spl":"ذكر ذي الرمة وخبره","tags":["الجواري والنساء","الوصف والطبيعة"],"song":1,"loc":3134,"partial":1},
{"id":"b229-2","bab":"الجزء 18","sec":"ذكر ذي الرمة وخبره","page":"ج18 ص5","text":"قال ذو الرمة\n(هي الشبه لولا مذرواها وأذنها ... سواء ولولا مشقة في القوائم)\nوكان ذو الرمة كثيرا ما يأتي الحضر فيقيم بالكوفة والبصرة وكان طفيليا أخبرني أحمد بن عبد العزيز قال حدثني الحسن بن علي قال حدثني ابن سعيد الكندي قال سمعت ابن عياش يقول حدثني من رأى ذا الرمة طفيليا يأتي العرسات","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":1,"spl":"ذكر ذي الرمة وخبره — بعض صفاته","tags":[],"loc":3135},
{"id":"b229-3","bab":"الجزء 18","sec":"بعض صفاته","page":"ج18 ص10","text":"نسخت من كتاب محمد بن داود الجراح حدثني هارون بن الزيات قال أخبرني محمد بن صالح العدوي قال قال زرعة بن أذبول كان ذو الرمة مدور الوجه حسن الشعرة جعدها أقنى أنزع خفيف العارضين أكحل حسن الضحك مفوها إذا كلمك كلمك أبلغ الناس يضع لسانه حيث يشاء\nوقال حماد بن إسحاق حدثني إدريس بن سليمان بن يحيى بن أبي حفصة عن عمته عافية وغيرها من أهله أنهم رأوا ذا الرمة باليمامة عند المهاجر بن عبد الله شيخا أجنأ سناطا متساقطا\nوقال هارون بن الزيات حدثني علي بن أحمد الباهلي قال حدثني ربيح النميري قال اجتمع الناس مرة وتحلقوا عن ذي الرمة وهو ينشدهم فجاءت أمه فاطلعت من بينهم فإذا رجل قاعد وهو ذو الرمة وكان دميما شختا أجنأ\nفقالت أمه استمعوا إلى شعره ولا تنظروا إلى وجهه قال هارون وأخبرني يعقوب بن السكيت عن أبي عدنان قال أخبرني أسيد الغنوي قال سمعت بباديتنا من قوم هضبوا في الحديث أن ذا الرمة كان ترعية وكان كناز اللحم مربوعا قصيرا وكان أنفه ليس بالحسن\nأخبرني ابن عمار عن سليمان بن أبي شيخ عن أبيه عن صالح بن سليمان قال كان الفرزدق وجرير يحسدان ذا الرمة وأهل البادية يعجبهم شعره قالو كان صالح بن سليمان راوية لشعر ذي الرمة فأنشد يوما قصيدة له وأعرابي من بني عدي يسمع فقال أشهد عنك - أي أنك - لفقيه تحسن ما تتلوه وكان يحسبه قرآنا نسخت من كتاب محمد بن داود وحدثني هارون بن الزيات عن محمد بن صالح العدوي قال قال حماد الراوية قال الكميت حين سمع قول ذي الرمة\n(أعاذل قد أكثرت من قول قائل ... وعيب على ذي الود لوم العواذل)\nذا والله ملهم وما علم بدوي بدقائق الفطنة وذخائر كنز العقل المعد لذوي الألباب أحسن ثم أحسن قال محمد بن صالح وحدثني محمد بن كناسة بذلك عن الكميت وقال لما أنشد قوله في هذه القصيدة\n(دعاني وما داعي الهوى من بلادها ... إذا ما نأت خرقاء عني بغافل)\nقال الكميت لله بلاد هذا الغلام ما أحسن قوله وما أجود وصفه ولقد شفع البيت الأول بمثله في جودة الفهم والفطنة وقال قول مستسلم قال ابن كناسة وقال لي حماد الراوية ما أخر القوم ذكره إلا لحداثة سنه وأنهم حسدوه","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":1,"spl":"ذكر ذي الرمة وخبره — بعض صفاته","tags":["الحب والغزل","اللهو والمزاح"],"loc":3136},
{"id":"b229-4","bab":"الجزء 18","sec":"آراء في شعره","page":"ج18 ص12","text":"قال محمد بن صالح وقال لي خالد بن كلثوم وأبو عمرو قال أبو حزام وأبو المطرف لم يكن أحد من القوم في زمانه أبلغ من ذي الرمة ولا أحسن جوابا كان كلامه أكثر من شعره وقال الأصمعي ما أعلم أحدا من العشاق الحضريين وغيرهم شكا حبا أحسن من شكوى ذي الرمة مع عفة وعقل رصين قال وقال أبو عبيدة ذو الرمة يخبر فيحسن الخبر ثم يرد على نفسه الحجة من صاحبه فيحسن الرد ثم يعتذر فيحسن التخلص مع حسن إنصاف وعفاف في الحكم\nأخبرني الحسن بن علي قال حدثنا أبو أيوب المديني قال حدثنا الفضل بن إسحاق الهاشمي عن مولى لجده قال رأيت ذو الرمة بسوق المربد وقد عارضه رجل يهزأ به فقال له يا أعرابي أتشهد بما لم تر\nقال نعم قال بماذا قال أشهد أن أباك ناك أمك أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن ابن حبيب عن عمارة بن عقيل قال كان جرير عند بعض الخلفاء فسأله عن ذي الرمة فقال أخذ من طريف الشعر وحسنه ما لم يسبقه إليه أحد غيره\nأخبرني وكيع عن حماد بن إسحاق قال قال حماد الراوية قدم علينا ذو الرمة الكوفة فلم أر أفصح ولا أعلم بغريب منه نسخت من كتاب ابن النطاح حدثني أبو عبيدة عن أبي عمرو\nقال ختم الشعر بذي الرمة وختم الرجز برؤبة قال فما تقول في هؤلاء الذين يقولون قال كل على غيرهم إن قالوا حسنا فقد سبقوا إليه وإن قالوا قبيحا فمن عندهم\nأخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني عن بعض أصحابه عن حماد الراوية قال أحسن الجاهلية تشبيها امرؤ القيس وذو الرمة أحسن أهل الإسلام تشبيها\nأخبرني محمد بن العباس اليزيدي عن عمه عبيد الله عن ابن حبيب عن عمارة بن عقيل أن جريرا والفرزدق اتفقا عند خليفة من خلفاء بني أمية فسأل كل واحد منهما على انفراد عن ذي الرمة فكلاهما\nقال أخذ من طريف الشعر وحسنه ما لم يسبقه إليه غيره فقال الخليفة أشهد لاتفاقكما فيه أنه أشعر منكما جميعا أخبرني جحظة عن حماد بن إسحاق\nقال حدثني أبي قال أنشد الصيقل شعر ذي الرمة فاستحسنه وقال ماله قاتله الله ما كان إلا ربيقة هلا عاش قليلا وقال هارون بن محمد أخبرني علي بن أحمد الباهلي قال حدثني محمد بن إسحاق البلخي عن سفيان بن عيينة عن ابن شبرمة قال سمعت ذا الرمة يقول إذا قلت كأنه ثم لم أجد مخرجا فقطع الله لساني\nقال هارون وحدثني العباس بن ميمون طائع قال قال الأصمعي كان ذو الرمة أشعر الناس إذا شبه ولم يكن بالمفلق وحدثني أبو خليفة عن محمد بن سلام قال كان لذي الرمة حظ في حسن التشبيه لم يكن لأحد من الإسلاميين كان علماؤنا يقولون أحسن الجاهلية تشبيها امرؤ القيس وأحسن أهل الإسلام تشبيها ذو الرمة","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":2,"spl":"آراء في شعره","tags":["اللهو والمزاح"],"loc":3137},
{"id":"b229-5","bab":"الجزء 18","sec":"ذو الرمة ومية المنقرية","page":"ج18 ص15","text":"أخبرني محمد بن يزيد قال حدثنا حماد عن أبيه عن أبي عقيل عمارة بن عقيل عن عمته أم القاسم ابنة بلال بن جرير عن جارية كانت لأم مي قالت كنا نازلين بأسفل الدهناء وكان رهط ذي الرمة مجاورين لنا فجلست مية - وهي حينئذ فتاة حين نهد ثدياها أحسن من رأيته - تغسل ثيابا لها ولأمها في بيت منفرد وكان بيتا رثا قد أخلق ففيه خروق فلما فرغت ولبست ثيابها جاءت فجلست عند أمها فأقبل ذو الرمة حتى دخل إلينا ثم سلم ونشد ضالة وجلس ساعة ثم خرج فقالت مية إني لأرى هذا العدوي قد رآني منكشفة واطلع علي من حيث لا أدري فإن بني عدي أخبث قوم في الأرض فاذهبي فقصي أثره فخرجت فوجدته ما يثبت مقامه فقصصت أثره ثانية حتى رأيته وقد تردد أكثر من ثلاثين طرقة كل ذلك يدنو فيطلع إليها ثم يرجع على عقبيه ثم يعود فيطلع إليها فأخبرتها بذلك ثم لم ننشب أن جاءنا شعره فيها من كل وجه ومكان\nوذكر علي بن سعيد بن بشر الرازي أن هارون بن مسلم بن سعد حدثه عن حسين بن براق الأسدي عن عمارة بن ثقيف قال حدثني ذو الرمة أن أول ما قاد المودة بينه وبين مية أنه خرج هو وأخوه وابن عمه في بغاء إبل لهم\nقال بينا نحن نسير إذ وردنا على ماء وقد أجهدنا العطش فعدلنا إلى حواء عظيم فقال لي أخي وابن عمي ائت الحواء فاستسق لنا فأتيته وبين يديه في رواقه عجوز جالسة قال فاستسقيت فالتفتت وراءها فقالت يا مي اسقي هذا الغلام فدخلت عليها فإذا هي تنسج علقة لها وهي تقول\n(يا من يرى برقا يمر حينا ... زمزم رعدا وانتحى يمينا)\n(كأن في حافاته حنينا ... أو صوت خيل ضمر يردينا)\nال ثم قامت تصب في شكوتي ماء وعليها شوذب لها فلما انحطت على القربة رأيت مولى لم أر أحسن منه قال فلهوت بالنظر إليها وأقبلت تصب الماء في شكوتي والماء يذهب يمينا وشمالا قال فأقبلت علي العجوز وقالت يا بني ألهتك مي عما بعثك أهلك له أما ترى الماء يذهب يمينا وشمالا فقلت أما والله ليطولن هيامي بها قال وملأت شكوتي وأتيت أخي وابن عمي ولففت رأسي فانتبذت\nناحية وقد كانت مي قالت لقد كلفك أهلك السفر على ما أرى من صغرك وحداثة سنك فأنشأت أقول\n(قد سخرت أخت بني لبيد ... مني ومن سلم ومن وليد)\n(رأت غلامي سفر بعيد ... يدرعان الليل ذا السدود)\n(مثل ادراع اليملق الجديد ... )\nقال وهي أول قصيدة قلتها ثم أتممتها\n(هل تعرف المنزل بالوحيد ... )\nم مكثت أهيم بها في ديارها عشرين سنة","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":3,"spl":"ذو الرمة ومية المنقرية","tags":[],"loc":3138,"partial":1},
{"id":"b229-6","bab":"الجزء 18","sec":"ذو الرمة وزوج مي","page":"ج18 ص17","text":"أخبرني أحمد بن عبد العزيز الجوهري عن النوفلي قال سمعت أبي يقول ضاف ذو الرمة زوج مي في ليلة ظلماء وهو طامع في ألا يعرفه زوجها فيدخله بيته فيراها ويكلمها ففطن له الزوج وعرفه فلم يدخله وأخرج إليه قراه وتركه بالعراء وقد عرفته مية فلما كان في جوف الليل تغني غناء الركبان قال\n(أراجعة يا مي أيامنا الألى ... بذي الأثل أم لا ما لهن رجوع)\nفغضب زوجها وقال قومي فصيحي به يابن الزانية وأي أيام كانت لي معك بذي الأثل فقالت يا سبحان الله ضيف والشاعر يقول فانتضى السيف وقال والله لأضربنك به حتى آتي عليك أو تقولي فصاحت به كما أمرها زوجها فنهض على راحلته فركبها وانصرف عنها مغضبا يريد أن يصرف مودته عنها إلى غيرها فمر بفلج في ركب وبعض أصحابه يريد أن يرقع خفه فإذا هو بجوار خارجات من بيت يردن آخر وإذا خرقاء فيهن - وهي امرأة من بني عامر - فإذا جارية حلوة شهلاء فوقعت عين ذي الرمة عليها فقال لها يا جارية أترقعين لهذا الرجل خفه فقالت تهزأ به أنا خرقاء لا أحسن أن أعمل فسماها خرقاء وترك\nذكر مي يريد أن يغيظ بذلك ميا فقال فيها قصيدتين أو ثلاثا ثم لم يلبث أن مات أخبرني الحسين بن يحيى عن حماد عن الأصمعي عن عمارة بن عقيل قال قال جرير خرجت مع المهاجر بن عبد الله إلى حجة فلقينا ذا الرمة فاستنشده المهاجر فأنشده\n(ومن حاجتي لولا التنائي وربما ... منحت الهوى من ليس بالمتقارب)\n(عطابيل بيض من ربيعة عامر ... عذاب الثنايا مثقلات الحقائب)\n(يقظن الحمى والرمل منهن محضر ... ويشربن ألبان الهجان النجائب)\nفالتفت إلي المهاجر وقال أتراه مجنونا أخبرني أبو خليفة عن محمد بن سلام قال أخبرنا أبو البيداء الرياحي قال قال جرير قاتل الله ذا الرمة حيث يقول\n(ومنتزع من بين نسعيه جرة ... نشيج الشجا جاءت إلى ضرسه نزرا)\nما والله لو قال ما بين جنبيه لما كان عليه من سبيل أخبرني الطوسي وحبيب المهلبي عن ابن شبة عن أبي غزالة عن هشام بن محمد الكلبي عن رجل من كندة قال سئل جرير عن شعر ذي الرمة فقال بعر ظباء ونقط عروس يضمحل عن قليل أخبرني أبو خليفة عن ابن سلام قال كان أبو عمرو بن العلاء يقول إنما شعر ذي الرمة نقط عروس يضمحل عن قليل وأبعار لها مشم في أول شمة ثم تعود إلى أرواح البعر","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":4,"spl":"ذو الرمة وزوج مي","tags":["الحب والغزل","الهجاء"],"loc":3139},
{"id":"b229-7","bab":"الجزء 18","sec":"الفرزدق لا يعده من الفحول","page":"ج18 ص20","text":"قال أبو زيد بن شبة قال أبو عبيدة وقف الفرزدق على ذي الرمة وهو ينشد قصيدته الحائية التي يقول فيها\n(إذا ارفض أطراف السياط وهللت ... جروم المطايا عدبتهن صيدح)\nقال ذو الرمة كيف تسمع يا أبا فراس قال أسمع حسنا قال فمالي لا أعد في الفحول من الشعراء قال يمنعك من ذلك ويباعدك ذكرك الأبعار وبكاؤك الديار ثم قال\n(ودوية لو ذو الرميمة رامها ... لقصر عنها ذو الرميم وصيدح)\n(قطعت إلى معروفها منكراتها ... إذا اشتد آل الأمعز المتوضح)\nوقال عمر بن شبة في هذا الخبر فقام إليه ذو الرمة فقال أنشدك الله أبا فراس أن تزيد عليهما شيئا فقال إنهما بيتان ولن أزيد عليهما شيئا قال وكان عمر بن شبة يقول عمن أخبره عن أبي عمرو إنما شعره نقط عروس تضمحل عما قليل وأبعار ظباء لها مشم في أول شمها ثم تعود إلى أرواح الأبعار وكان هوى ذي الرمة مع الفرزدق على جرير وذلك لما كان بين جرير وابن لجأ التيمي وتيم وعدي اخوان من الرباب وعكل أخوهم ولذلك يقول جرير لعكل\n(فلا يضغمن الليث عكلا بغرة ... وعكل يشمون الفريس المنيبا)\nلفريس ها هنا ابن لجأ وكذلك يفعل السبع إذا ضغم شاة ثم طرد عنها أو سبقته أقبلت الغنم تشم موضع الضغم فيفترسها السبع وهي تشم ولذلك قال جرير لبني عدي\n(وقلت نضاحة لبني عدي ... ثيابكم ونضح دم القتيل)\nحذر عديا ما لقي ابن لجأ أخبرني أبو خليفة عن ابن سلام أن أبا يحيى الضبي قال قال ذو الرمة يوما لقد قلت أبياتا إن لها لعروضا وإن لها لمرادا ومعنى بعيدا قال له الفرزدق ما هي قال قلت\n(أحين أعاذت بي تميم نساءها ... وجردت تجريد اليماني من الغمد)\n(ومدت بضبعي الرباب ومالك ... وعمرو وشالت من ورائي بنو سعد)\n(ومن آل يربوع زهاء كأنه ... زها الليل محمود النكاية والرفد)\nقال له الفرزدق لا تعودن فيها فأنا أحق بها منك قال والله لا أعود ولا أنشدها أبدا إلا لك فهي قصيدة الفرزدق التي يقول فيها\n(وكنا إذا القيسي نب عتوده ... ضربناه فوق الأنثيين على الكرد)\n- الأنثيان الأذنان والكرد العنق - وروى هذا الخبر حماد عن أبيه عن أبي عبيدة عن الضحاك الفقيمي قال بينا أنا بكاظمة وذو الرمة ينشد قصيدته التي يقول فيها\n(أحين أعاذت بي تميم نساءها ... )\nذا راكبان قد تدليا من نقب كاظمة مقنعان فوقفا فلما فرغ ذو الرمة حسر الفرزدق عن وجهه وقال لراويته يا عبيد اضمم إليك هذه الأبيات قال له ذو الرمة نشدتك الله يا أبا فراس فقال له أنا أحق بها منك وانتحل منها هذه الأربعة الأبيات","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":5,"spl":"الفرزدق لا يعده من الفحول","tags":["الوصف والطبيعة","الرواية والكتابة"],"loc":3140,"partialRef":{"sid":"b112-30","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b229-8","bab":"الجزء 18","sec":"ذو الرمة وهشام المرئي","page":"ج18 ص22","text":"حدثنا محمد قال حدثنا أبو الغراف قال مر ذو الرمة بمنزل لامرىء القيس بن زيد مناة يقال له مرأة به نخل فلم ينزلوه ولم يقروه فقال\n(نزلنا وقد طال النهار وأوقدت ... علينا حصى المعزاء شمس تنالها)\n(أنخنا نظللنا بأبراد يمنة ... عتاق وأسياف قديم صقالها)\n(فلما رآنا أهل مرأة أغلقوا ... مخادع لم ترفع لخير ظلالها)\n(وقد سميت باسم امرىء القيس قرية ... كرام صواديها لئام رجالها)\nفلج الهجاء بين ذي الرمة وبين هشام المرئي فمر الفرزدق بذي الرمة وهو ينشد\n(وقفت على ربع لمية ناقتي ... فما زلت أبكي عنده وأخاطبه)\n(وأسقيه حتى كاد مما أبثه ... تكلمني أحجاره وملاعبه)\nنى فيه إبراهيم ثاني ثقيل مطلق في مجرى البنصر وسيأتي خبره بعد لئلا ينقطع هذا الخبر فقال له الفرزدق ألهاك البكاء في الديار والعبد يرتجز بك في المقابر يعني هشاما وكان ذو الرمة مستعليا هشاما حتى لقي جرير هشاما فقال غلبك العبد يعني ذا الرمة قال فما أصنع يا أبا حزرة وأنا راجز وهو يقصد والرجز لا يقوم للقصيد في الهجاء ولو رفدتني فقال جرير - لتهمته ذا الرمة بالميل إلى الفرزدق - قل له\n(غضبت لرجل من عدي تشمسوا ... وفي أي يوم لم تشمس رجالها)\n(وفيم عدي عند تيم من العلا ... وأيامنا اللاتي تعد فعالها)\n(وضبة عمي يابن جل فلا ترم ... مساعي قوم ليس منك سجالها)\n(يماشي عديا لؤمها لا تجنه ... من الناس ما مست عديا ظلالها)\n(فقل لعدي تستعن بنسائها ... علي فقد أعيا عديا رجالها)\n(إذا الرم قد قلدت قومك رمة ... بطيئا بأمر المطلقين انحلالها)\nقال أبو عبد الله فحدثني أبو الغراف قال لما بلغت الأبيات ذا الرمة قال والله ما هذا بكلام هشام ولكنه كلام ابن الأتان أخبرنا أبو خليفة\nقال حدثنا ابن سلام قال وحدثني أبو البيداء قال لما سمعها قال هو والله ينتمي شعر حنظلي عذري وغلب هشام على ذي الرمة بها نسخت من كتاب ابن النطاح\nحدثني أبو عبيدة قال حدثني فلان المرئي قال أتانا جرير على حمار وأنا لا أعرفه فأتي بنبيذ فشرب فلما أخذ فيه قال أين هشام فدعي فقال له أنشدني ما\nقلت في ذي الرمة فأنشده فجعل كلما أنشده قصيدة قال لم تصنع شيئا ثم قال له قد دنا رواحي فاردد هذه الأبيات ومر شبانكم بروايتها وذكر الأبيات التي اولها قوله\n(غضبت لرجل من تميم تشمسوا ... )\nو الرمة يعاتب جريرا قال فغلبه هشام بها فلما كان بعد ذلك لقي ذو الرمة جريرا فقال تعصبت على خالك للمرئي فقال جرير حيث فعلت ماذا قال حين تقول للمرئي كذا وكذا فقال جرير لأنك ألهاك البكاء في دار مية حتى استقبحته محارمك قال وقول ذي الرمة تعصبت على خالك أن النوار بنت جل أم حنظلة بن مالك وهي من رهط ذي الرمة وكذلك عنى جرير بقوله\n(ولولا أن تقول بنو عدي ... ألم تك أم حنظلة النوار)\n(أتتكم يا بني ملكان مني ... قصائد لا تعاورها البحار)\nقال ذو الرمة لا ولكن اتهمتني بالميل مع الفرزدق عليك قال كذلك هو قال فوالله ما فعلت وحلف له بما يرضيه قال فأنشدني ما هجوت به المرئي فأنشده قوله\n(نبت عيناك عن طلل بحزوى ... عفته الريح وامتضح القطارا)\nأطال جدا فقال له جرير ما صنعت شيئا أفأرفدك قال نعم قال قل\n(يعد الناسبون إلى تميم ... بيوت المجد أربعة كبارا)\n(يعدون الرباب وآل سعد ... وعمرا ثم حنظلة الخيارا)\n(ويهلك بينها المرئي لغوا ... كما ألفيت في الدية الحوارا)\nيروى ويذهب بينها فغلبه ذو الرمة بها قال حدثني محمد بن عمر الجرجاني قال حدثني جماعة من أهل العلم أن ذا الرمة مر بالفرزدق فقال له أنشدني أحدث ما قلت في المرئي فأنشده هذه الأبيات فأطرق الفرزدق ساعة ثم قال أعد فأعاد فقال كذبت وايم الله ما هذا لك ولقد قاله أشد لحيين منك وما هذا إلا شعر ابن الأتان","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":6,"spl":"ذو الرمة وهشام المرئي","tags":["الهجاء"],"song":1,"loc":3141,"partial":1},
{"id":"b229-9","bab":"الجزء 18","sec":"ذو الرمة وهشام المرئي","page":"ج18 ص22","text":"فلما سمعها المرئي جعل يلطم رأسه ويصرخ ويدعو بويله ويقول قتلني جرير قتله الله هذا والله شعره الذي لو نقطت منه نقطة في البحر لكدرته قتلني وفضحني فلما استعلى ذو الرمة على هشام أتى هشام وقومه جريرا فقالوا يا أبا حزرة عادتك الحسنى فقال هيهات ظلمت أخوالي قد أتاني ذو الرمة فاعتذر إلي وحلف فلست أعين عليهم فلما يئسوا من عنده أتوا لهذا المكاتب وقد طلع بمكاتبته فأعطوه عشرة أعنز وأعانوه على مكاتبته فقال أبياتا عينية يفضل فيها بني امرئ القيس على بني عدي وهشاما على ذي الرمة ومات ذو الرمة في تلك الأيام فقال الناس غلبه هشام\nقال ابن النطاح إنما مات ذو الرمة بعقب إرفاد جرير إياه على المرئي فقال الناس غلبه ولم يغلبه إنما مات قبل الجواب أخبرني اليزيدي عن محمد بن الحسن الأحول عن بعض أصحابه عن الشبو بن قسيم العذري\nقال سمعت ذا الرمة يقول من شهري ما طاوعني فيه القول وساعدني ومنه ما أجهدت نفسي فيه ومنه ما جننت به جنونا فأما ما طاوعني القول فيه فقولي\n(خليلي عوجا من صدور الرواحل ... )\nوأما ما أجهدت نفسي فيه فقولي\n(أأن توسمت من خرقاء منزلة ... )\nما ما جننت به جنونا فقولي\n(ما بال عينك منها الدمع ينسكب ... )\nأخبرني علي بن سليمان عن محمد بن يزيد عن عمارة بن عقيل قال كان جرير يقول ما أحببت أن ينسب إلي من شعر ذي الرمة إلا قوله\n(ما بال عينك منها الماء ينسكب ... )\nإن شيطانه كان له فيها ناصحا أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال حماد الراوية ما تمم ذو الرمة قصيدته التي يقول فيها\n(ما بال عينك منها الماء ينسكب ... )\nتى مات كان يزيد فيها منذ قالها حتى توفي","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":7,"spl":"ذو الرمة وهشام المرئي","tags":[],"loc":3142,"partialRef":{"sid":"b129-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b229-10","bab":"الجزء 18","sec":"ذو الرمة في سوق المربد","page":"ج18 ص27","text":"أخبرني الحسين بن يحيى عن حماد عن أبي عدنان قال أخبرنا جابر بن عبد الله بن جامع بن جرموز الباهلي عن كثير بن ناجية قال بينا ذو الرمة ينشد بالمربد والناس مجتمعون إليه إذا هو بخياط يطالعه ويقول يا غيلان\n(أأنت الذي تستنطق الدار واقفا ... من الجهل هل كانت بكن حلول)\nفقال ذو الرمة وفكر زمانا ثم عاد فقعد في المربد ينشد فإذا الخياط قد وقف عليه ثم قال\n(أأنت الذي شبهت عنزا بقفرة ... لها ذنب فوق استها أم سالم)\n(وقرنان إما يلزقا بك يتركا ... بجنبيك يا غيلان مثل المواسم)\n(جعلت لها قرنين فوق شواتها ... ورابك منها مشقة في القوائم)\nقام ذو الرمة فذهب ولم ينشد بعدها في المربد حتى مات الخياط قال وأراد الخياط بقوله هذا قول ذي الرمة\n(أقول لدهناوية عوهج جرت ... لنا بين أعلى برقة في الصرائم)\n(أيا ظبية الوعساء بين جلاجل ... وبين النقا آأنت أم أم سالم)\n(هي الشبه لولا مدرياها وأذنها ... سواء وإلا مشقة في القوائم)\nانتبه ذو الرمة لذلك فقال\n(أقول بذي الأرطى عشية أرشقت ... الى الركب أعناق الظباء الخواذل)\n(لأدماء من آرام بين سويقة ... وبين الجبال العفر ذات السلاسل)\n(أرى فيك من خرقاء يا ظبية اللوى ... مشابه جنبت اعتلاق الحبائل)\n(فعيناك عيناها وجيدك جيدها ... ولونك لولا أنها غير عاطل)\nفي البيتين الأخيرين من هذه الأبيات رمل بالوسطى لإبراهيم أخبرني علي بن سليمان الأخفش عن أبي سعيد السكري عن يعقوب ابن السكيت عن محمد بن سلام عن أبي الغراف قال قال ذو الرمة لرؤبة ما عنى الراعي بقوله\n(أناخا بأسوا الظن ثمت عرسا ... قليلا وقد أبقى سهيل فعردا)\nجعل رؤبة يقول هي كذا هي كذا لأشياء لا يقبلها ذو الرمة فقال له رؤبة فمه ويحك قال هي الأرض بين المكلئة وبين المجدبة أخبرني الحسين بن يحيى عن حماد عن أبي عدنان عن إبراهيم بن نافع أن الفرزدق دخل على الوليد بن عبد الملك أو غيره فقال له من أشعر الناس قال أنا قال أفتعلم أحدا أشعر منك قال لا إلا أن غلاما من بني عدي بن كعب يركب أعجاز الإبل وينعت الفلوات ثم أتاه جرير\nفسأله فقال له مثل ذلك ثم أتاه ذو الرمة فقال له ويحك أنت أشعر الناس قال لا ولكن غلام من بني عقيل يقال له مزاحم يسكن الروضات يقول وحشيا من الشعر لا نقدر على أن نقول مثله وقال وكان ذو الرمة يتشبب بمي بنت طلبة بن قيس بن عاصم المنقري وكانت كثيرة أمة مولدة لآل قيس بن عاصم وهي أم سهم بن بردة اللص الذي قتله سنان بن مخيس القشيري أيام محمد بن سليمان فقالت كثيرة\n(على وجه مي مسحة من ملاحة ... وتحت الثياب الخزي لو كان باديا)\n(ألم تر أن الماء يخبث طعمه ... ولو كان لون الماء في العين صافيا)\nنحلتها ذا الرمة فامتعض من ذلك وحلف بجهد إيمانه ما قالها قال وكيف أقول هذا وقد قطعت دهري وأفنيت شبابي أشبب بها وأمدحها ثم أقول هذا ثم اطلع على أن كثيرة قالتهما ونحلتهما إياه","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":8,"spl":"ذو الرمة في سوق المربد","tags":["الحب والغزل"],"loc":3143},
{"id":"b229-11","bab":"الجزء 18","sec":"أخباره مع مية","page":"ج18 ص30","text":"وقال هارون بن محمد حدثني عبد الرحمن بن عبد الله قال حدثني هارون بن سعيد قال حدثني أبو المسافر الفقعسي عن أبي بكر بن جبلة الفقعسي قال وقف ذو الرمة في ركب معه على مية فسلموا عليها فقالت وعليكم\nإلا ذا الرمة فأحفظه ذلك وغمه ما سمع منها بحضرة القوم فغضب وانصرف وهو يقول\n(أيا مي قد أشمت بي ويحك العدا ... وقطعت حبلا كان يا مي باقيا)\n(فيا مي لا مرجوع للوصل بيننا ... ولكن هجرا بيننا وتقاليا)\n(ألم تر أن الماء يخبث طعمه ... وإن كان لون الماء في العين صافيا)\nخبرني الحسن بن علي الأدمي عن ابن مهرويه عن ابن النطاح عن محمد بن الحجاج الأسيدي من بني أسيد بن عمرو بن تميم قال مررت على مية وقد أسنت فوقفت عليها وأنا يومئذ شاب فقلت يا مية ما أرى ذا الرمة إلا قد ضيع فيك قوله حيث يقول\n(أما أنت عن ذكراك مية مقصر ... ولا أنت ناسي العهد منها فتذكر)\n(تهيم بها ما تستفيق ودونها ... حجاب وأبواب وستر مستر)\nال فضحكت وقالت رأيتني يا بن أخي وقد وليت وذهبت محاسني ويرحم الله غيلان فلقد قال هذا في وأنا أحسن من النار الموقدة في الليلة القرة في عين المقرور ولن تبرح حتى أقيم عندك عذره ثم صاحت يا أسماء اخرجي فخرجت جارية كالمهاة ما رأيت مثلها فقالت أما لمن شبب بهذه وهويها عذر فقلت بلى فقالت والله لقد كنت أزمان كنت مثلها أحسن منها ولو رأيتني يومئذ لا زدريت هذه ازدراءك إياي اليوم انصرف راشدا في هذين البيتين لإبراهيم ثاني ثقيل بالوسطى\nأخبرني أبو خليفة قال قال محمد بن سلام قال أبو سوار الغنوي رأيت مية وإذا معها بنون لها صغار فقلت صفها لي فقال مسنونة الوجه طويلة الخد شماء الأنف عليها وسم جمال فقالت ما تلقيت بأحد من بني هؤلاء إلا في الإبل\nقلت أفكانت تنشدك شيئا مما قاله ذو الرمة فيها قال نعم كانت تسح سحا ما رأى أبوك مثله فأما ابن قتيبة فقال في خبره مكثت مية زمانا لا ترى ذا الرمة وهي تسمع مع ذلك شعره فجعلت لله عليها أن تنحر بدنة يوم تراه فلما رأته رجلا دميما أسود وكانت من أجمل الناس قالت واسوأتاه وابؤساه واضيعة بدنتاه فقال ذو الرمة\n(على وجه مي مسحة من ملاحة ... وتحت الثياب الشين لو كان باديا)\nال فكشفت ثوبها عن جسدها ثم قالت أشينا ترى لا أم لك فقال\n(ألم تر أن الماء يخبث طعمه ... وإن كان لون الماء أبيض صافيا)\nقالت أما ما تحت الثياب فقد رأيته وعلمت أن لا شين فيه ولم يبق إلا أن أقول لك هلم حتى تذوق ما وراءه ووالله لا ذقت ذاك أبدا فقال\n(فيا ضيعة الشعر الذي لج فانقضى ... بمي ولم أملك ضلال فؤاديا)\nال ثم صلح الأمر بينهما بعد ذلك فعاد لما كان عليه من حبها وذكر محمد بن علي بن حفص الجبيري الحنفي - من ولد أبي جبيرة - أن النوار بنت عاصم المنقرية - وأمها مية صاحبة ذي الرمة - أخبرته وقد ذكر عندها ذا الرمة وأنشدها قوله في أمها\n(هي البرء والأسقام والهم والمنى ... وموت الهوى في القلب مني المبرح)\n(وكان الهوى بالنأي يمحى فيمحي ... وحبك عندي يستجد ويربح)\nربح أي يزيد الربح هكذا ذكره الأصمعي\n(إذا غير النأي المحبين لم أجد ... رسيس الهوى من حب مية يبرح)\nلما سمعت قوله\n(إذا غير النأي المحبين . . ... .)\nقالت قبحه الله هو الذي يقول أيضا\n(على وجه مي مسحة من ملاحة ... وتحت الثياب الشين لو كان باديا)\nقلت لها أكانت مية جدتك قالت لا بل أمي فقلت لها كم تعدين قالت ستين سنة أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن محمد بن سلام قال كانت مي صاحبة ذي الرمة من ولد طلبة بن قيس بن عاصم المنقري وكانت لها بنت عم من ولد قيس يقال لها كثيرة أم سلهمة فقالت على لسان ذي الرمة\n(على وجه مي سسحة من ملاحة ... )\nلأبيات فكان ذو الرمة إذا ذكر له ذلك يمتعض منه ويحلف أنه ما قالها قط\nأخبرني بهذا الخبر أبو خليفة عن محمد بن سلام عن أبي الغراف الضبي بمثله وقال فيه إن كثيرة مولاة لهم وهي أم سلهمة اللص الذي قتله خيل محمد بن سليمان والله أعلم أخبرنا أحمد بن عبد العزيز وحبيب المهلبي عن ابن شبة عن المدائني عن سلمة عن محارب\nقال كان ذو الرمة يقرأ ويكتب ويكتم ذلك فقيل له كيف تقول عزير ابن الله أو عزير بن الله فقال أكثرهما حروفا أخبرني إبراهيم بن أيوب عن عبد الله بن مسلم","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":9,"spl":"أخباره مع مية","tags":["الحب والغزل"],"song":1,"loc":3144,"partial":1},
{"id":"b229-12","bab":"الجزء 18","sec":"أخباره مع مية","page":"ج18 ص30","text":"قال قال عيسى بن عمر قال لي ذو الرمة ارفع هذا الحرف فقلت له أتكتب فقال بيده على فيه اكتم علي فإنه عندنا عيب أخبرني ابن دريد عن أبي حاتم عن الأصمعي عن محمد بن أبي بكر المخزومي قال قال رؤبة كلما قلت شعرا سرقه ذو الرمة فقيل له وما ذاك قال قلت\n(حي الشهيق ميت الأنفاس ... )\nفقال هو\n(يطرحن بالمهارق الأغفال ... كل جهيض لثق السربال)\n(حي الشهيق ميت الأوصال ... )\nقلت له فقوله والله أجود من قولك وإن كان سرقة منك فقال ذلك أغم لي أخبرني ابن عبد العزيز عن ابن شبة قال قيل لذي الرمة إنما أنت راوية الراعي فقال أما والله لئن\nقيل ذاك ما مثلي ومثله إلا شاب صحب شيخا فسلك به طرقا ثم فارقه فسلك الشاب بعده شعابا وأودية لم يسلكها الشيخ قط أخبرني محمد بن أحمد بن الطلاس عن الخراز عن المدائني\nوأخبرني به إبراهيم بن أيوب عن عبد الله بن مسلم عن ابن أخي الأصمعي عن عمه دخل حديث بعضهم في حديث بعض قال إنما وضع من ذي الرمة أنه كان لا يحسن أن يهجو ولا يمدح وقد مدح بلال بن أبي بردة فقال\n(رأيت الناس ينتجعون غيثا ... فقلت لصيدح انتجعي بلالا)\nلما أنشده قال له أو لم ينتجعني غير صيدح يا غلام أعطه حبل\n(قلت ... )\nلصيدح فأخجله أخبرني أبو خليفة عن ابن سلام قال حدثني أبو الغراف قال عاب الحكم بن عوانة الكلبي ذا الرمة في بعض قوله فقال فيه\n(فلو كنت من كلب صميما هجوتكم ... جميعا ولكن لا إخالك من كلب)\n(ولكنما أخبرت أنك ملصق ... كما ألصقت من غيرها ثلمة القعب)\n(تدهدى فخرت ثلمة من صميمه ... فكيف بأخرى بالغراء وبالشعب)","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":10,"spl":"أخباره مع مية","tags":["المديح","الرواية والكتابة"],"loc":3145,"partial":1},
{"id":"b229-13","bab":"الجزء 18","sec":"اخباره مع بلال بن أبي بردة","page":"ج18 ص36","text":"أخبرني أبو خليفة عن ابن سلام قال وحدثني أبو الغراف قال دخل ذو الرمة على بلال بن أبي بردة وكان بلال راوية فصيحا أديبا فأنشده بلال أبيات حاتم طيىء قال\n(لحا الله صعلوكا مناه وهمه ... من العيش أن يلقى لبوسا ومطعما)\n(يرى الخمس تعذيبا وإن نال شبعة ... يبت قلبه من شدة الهم مبهما)\nهكذا أنشد بلال فقال ذو الرمة يرى الخمص تعذيبا وإنما الخمس للإبل وإنما هو خمص البطن فمحك بلال - وكان محكا - وقال هكذا أنشدنيه رواة طيىء فرد عليه ذو الرمة فضحك ودخل أبو عمرو بن العلاء فقال له بلال كيف تنشدهما وعرف أبو عمرو الذي به\nفقال كلا الوجهين جائز فقال أتأخذون عن ذي الرمة فقال إنه لفصيح وإنا لنأخذ عنه بتمريض وخرجا من عنده فقال ذو الرمة لأبي عمرو والله لولا أني أعلم أنك حطبت في حبله وملت مع هواه لهجوتك هجاء لا يقعد إليك اثنان بعده نسخت من كتاب محمد بن داود بن الجراح حدثني هارون بن محمد الزيات قال حدثني حماد بن إسحاق عن عمارة بن عقيل قال قيل لبلال بن جرير أي شعر ذي الرمة أجود فقال\n(هل حبل خرقاء بعد اليوم مرموم ... )\nنها مدينة الشعر حدثنا أبو خليفة عن ابن سلام قال كان ذو الرمة من جرير والفرزدق بمنزلة قتادة من الحسن وابن\nسيرين كان يروي عنهما ويروي عن الصحابة وكذلك ذو الرمة هو دونهما ويساويهما في بعض شعره أخبرني الجوهري قال حدثنا ابن شبة عن ابن معاوية قال قال حماد الراوية قدم علينا ذو الرمة الكوفة فلم نر أحسن ولا أفصح ولا أعلم بغريب منه فغم ذلك كثيرا من أهل المدينة فصنعوا له أبياتا وهي قوله\n(رأى جملا يوما ولم يك قبلها ... من الدهر يدري كيف خلق الأباعر)\n(فقال شظايا مع ظبايا ألا لنا ... وأجفل إجفال الظلم المبادر)\n(فقلت له لا ذهل ملكيل بعد ما ... ملا نيفق التبان منه بعاذر)\nال فاستعادها مرتين وثلاثا ثم قال ما أحسب هذا من كلام العرب أخبرني أبو الحسن الأسدي عن العباس بن ميمون طائع قال حدثنا أبو عثمان المازني عن الأصمعي عن عنبسة النحوي قال قلت لذي الرمة وسمعته ينشد ويقول\n(وعينان قال الله كونا فكانتا ... فعولين بالألباب ما تفعل الخمر)\nقال فقلت له فهلا قلت فعولان فقال لو قلت سبحان الله والحمد لله ولا إله إلا الله والله أكبر كان خيرا لك أي أنك أردت القدر وأراد ذو الرمة كونا فعولين بالألباب وأراد عنبسة وعينان فعولان\nوروى هذا الخبر ابن الزيات عن محمد بن عبادة عن الأصمعي عن العلاء بن أسلم فذكر مثله وحكي أن إسحاق بن سويد المعارض له قال وأخبرني الأخفش\nقال حدثني محمد بن يزيد النحوي قال حدثني عبد الصمد بن المعذل قال حدثني أبي عن أبيه قال قدم ذو الرمة الكوفة فوقف ينشد الناس بالكناسة قصيدته الحائية حتى أتى على قوله\n(إذا غير النأي المحبين لم يكد ... رسيس الهوى من حب مية يبرح)\nناداه ابن شبرمة يا غيلان أراه قد برح فشنق ناقته وجعل يتأخر بها ويفكر ثم عاد فأنشد قوله\n(إذا غير النأي المحبين لم أجد ... )\nال فلما انصرفت حدثت أبي فقال أخطأ ابن شبرمة حين أنكر على ذي الرمة ما أنشد وأخطأ ذو الرمة حين غير شعره لقول ابن شبرمة إنما هذا مثل قول الله عز و جل ( ظلمات بعضها فوق بعض إذا أخرج يده لم يكد يراها\nوإنما معناه لم يرها ولم يكد\nأخبرني الجوهري عن ابن شبرمة عن يحيى بن نجيم قال قال رؤبة لبلال بن أبي بردة علام تعطي ذا الرمة فوالله إنه ليعمد إلى مقطعاتنا فيصلها فيمدحك بها فقال والله لو لم أعطه إلا على تأليفه لأعطيته وأمر له بعشرة آلاف درهم أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة حدثنا إسحاق الموصلي عن الأصمعي قال قال رجل رأيت ذا الرمة بمربد البصرة وعليه جماعة مجتمعة وهو قائم وعليه برد قيمته مائتا دينار وهو ينشد ودموعه تجري على لحيته\n(ما بال عينك منها الماء ينسكب ... )\nلما انتهى إلى قوله\n(تصغي إذا شدها بالكور جانحة ... حتى إذا ما استوى في غرزها تثب)\nلت يا أخا بني تميم ما هكذا قال عمك قال وأي أعمامي يرحمك الله قلت الراعي قال وما قال قال قلت قوله\n(ولا تعجل المرء قبل الوروك ... وهي بركبته أبصر)\n(وهي إذا قام في غرزها ... كمثل السفينة إذ توقر)\n(ومصغية خدها بالزمام ... فالرأس منها له أصعر)\n(حتى إذا ما استوى طبقت ... كما طبق المسحل الأغبر)","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":11,"spl":"اخباره مع بلال بن أبي بردة","tags":["الحب والغزل","الهجاء"],"loc":3146,"partialRef":{"sid":"b129-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b229-15","bab":"الجزء 18","sec":"اخباره مع بلال بن أبي بردة — أخباره مع خرقاء","page":"ج18 ص36 – ج18 ص41","text":"ال فأرتج عليه ساعة ثم قال إنه نعت ناقة ملك ونعت ناقة سوقة فخرج منها على رؤوس الناس\nفأما السبب بين ذي الرمة وخرقاء فقد اختلف فيه الرواة فقيل إنه كان يهواها وقيل بل كاد بها مية وقيل بل كانت كحالة فداوت عينه فشبب بها\nأخبرني أحمد بن عبد العزيز الجوهري عن النوفلي عن أبيه أن زوج مية أمرها أن تسب ذا الرمة غيرة عليها فامتنعت فتوعدها بالقتل فسبته فغضب وشبب بخرقاء العامرية يكيد مية بذلك فما\nقال فيها إلا قصيدتين أو ثلاثا حتى مات أخبرني حبيب بن نصر عن ابن شبة عن العتبي عن هارون بن عتبة قال شبب ذو الرمة بخرقاء العامرية بغير هوى وإنما كانت كحالة فداوت عينه من رمد كان بها فزال فقال لها ما تحبين حتى أعطيك فقالت عشرة أبيات تشبب بي ليرغب الناس في إذا سمعوا أن في بقية للتشبيب ففعل أخبرنا أبو خليفة عن ابن سلام قال كان ذو الرمة شبب بخرقاء إحدى نساء بني عامر بن ربيعة وكانت تحل\nفلجا ويمر بها الحاج فتقعد لهم وتحادثهم وتهاديهم وكانت تجلس معها فاطمة بنتها فحدثني من رآهما فلم تكن فاطمة مثلها وكانت تقول أنا منسك من مناسك الحج لقول ذي الرمة فيها\n(تمام الحج أن تقف المطايا ... على خرقاء واضعة اللثام)\nال ابن سلام في خبره وأرسلت خرقاء إلى القحيف العقيلي تسأله أن يشبب بها فقال\n(لقد أرسلت خرقاء نحوي جريها ... لتجعلني خرقاء فيمن أضلت)\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)\nدثني حبيب بن نصر عن الزبير عن موهوب بن رشيد عمن حدثه قال نزل ركب بأبي خرقاء العامرية فأمر لهم بلبن فسقوه وقصر عن شاب منهم فأعطته خرقاء صبوحها وهي لا تعرفه فشربه ومضوا فركبوا فقال لها أبوها أتعرفين الرجل الذي سقيته صبوحك قالت لا والله قال هو ذو\nالرمة القائل فيك الأقاويل فوضعت يدها على رأسها وقالت واسوأتاه وابؤساه ودخلت بيتها فما رآها أبوها ثلاثا حدثني إبراهيم بن أيوب عن ابن قتيبة\nقال قال الضبي كنت أنزل على بعض الأعراب إذا حججت فقال لي يوما هل لك إلى أن أريك خرقاء صاحبة ذي الرمة فقلت إن فعلت بررت فتوجهنا جميعا نريدها فعدل بي عن الطريق قدر ميل ثم أتينا أبيات شعر فاستفتح بيتا ففتح له وخرجت امرأة طويلة حسنة بها قوة فسلمت وجلست فتحدثنا ساعة ثم قالت لي هل حججت قط قلت غير مرة قالت فما منعك من زيارتي أما علمت أني منسك من مناسك الحج قلت وكيف ذاك قلت أما سمعت قول ذي الرمة\n(تمام الحج أن تقف المطايا ... على خرقاء واضعة اللثام)\nخبرني وكيع عن أبي أيوب المدائني عن مصعب الزبيري قال شبب ذو الرمة بخرقاء ولها ثمانون سنة قال هارون بن الزيات حدثني عبد الرحمن بن عبد الله بن إبراهيم عن محمد بن يعقوب عن أبيه\nقال رأيت خرقاء بالبصرة وقد ذهبت أسنانها وإن في ديباجة وجهها لبقية فقلت أخبريني عن السبب بينك وبين ذي الرمة فقالت اجتاز بنا في ركب ونحن عدة جوار على بعض المياه فقال أسفرن فسفرن غيري فقال لئن لم تسفري لأفضحنك فسفرت فلم يزل يقول حتى أزبد ثم لم أره بعد ذلك\nأخبرني الحرمي ابن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني موهوب بن رشيد قال حدثني جدي قال كنت مع خرقاء ذي الرمة إذ نزل بابها ركب من بني تميم فأمر لهم بلبن فسقوه وقصر اللبن عن شاب منهم فأمرت له خرقاء بغبوقها فلما أن رحل عنهم الركب\nقال لها أبوها يا خرقاء أتعرفين من سقيت غبوقك اليوم قالت لا والله ما أعرفه قال ذاك ذو الرمة فوضعت يدها على رأسها وقالت واسوأتاه ودخلت خدرها\nقال الزبير وحدثني عبد الله بن إبراهيم الجمحي قال حدثنا أبو الشبل المعدي قال كانت خرقاء البكائية أصبح من القبس وبقيت بقاء طويلا حتى شبب بها القحيف العقيلي أخبرنا أبو الحسن الأسدي عن أحمد بن سليمان عن أبي شيخ عن أبيه عن علي بن صالح بن سليمان عن صباح بن الهذيل أخي زفر بن الهذيل\nقال خرجت أريد الحج فمررت بالمنزل الذي تنزله خرقاء فأتيتها فإذا امرأة جزلة عندها سماطان من الأعراب تحدثهم وتناشدهم فسلمت فردت ونسبتني فانتسبت لها وهي تنزلني حتى انتسبت إلى أبي فقالت حسبك أكرمت ما شئت ما اسمك قلت صباح قالت وأبو من قلت أبو\nالمغلس قالت أخذت أول الليل وآخره قال فما كان لي همة إلا الذهاب عنها نسخت من كتاب محمد بن صالح بن النطاح حدثني محمد بن الحجاج الأسدي التميمي - وما رأيت تميميا أعلم منه -","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":12,"spl":"اخباره مع بلال بن أبي بردة — أخباره مع خرقاء","tags":["الجواري والنساء"],"song":1,"loc":3147},
{"id":"b229-16","bab":"الجزء 18","sec":"أخباره مع خرقاء","page":"ج18 ص41","text":"قال حججت فلما صرت بمران منصرفا فإذا أنا بغلام أشعث الذؤابة قد أورد غنيمات له فجئته فاستنشدته فقال لي إليك عني فإني مشغول عنك وألححت عليه فقال أرشدك إلى بعض ما تحب انظر إلى ذلك البيت الذي يلقاك فإن فيه حاجتك هذا بيت خرقاء ذي الرمة فمضيت نحوه فطوحت بالسلام من بعيد فقالت ادنه فدنوت فقالت إنك لحضري فمن أنت\nقلت من بني تميم - وأنا أحسب أنها لا معرفة لها بالناس - قالت من أي تميم فأعلمتها فلم تزل تنزلني حتى انتسبت إلى أبي فقالت الحجاج بن عمير بن يزيد\nقلت نعم قالت رحم الله أبا المثنى قد كنا نرجو أن يكون خلفا من عمير بن يزيد قلت نعم فعاجلته المنية شابا قالت حياك الله يا بني وقربك من أين أقبلت\nقلت من الحج قالت فما لك لم تمر بي وأنا أحد مناسك الحج إن حجك ناقص فأقم حتى تحج أو تكفر بعتق قلت وكيف ذلك قالت أما سمعت قول غيلان عمك\n(تمام الحج أن تقف المطايا ... على خرقاء واضعة اللثام)\nال وكانت هي قاعدة بفناء البيت كأنها قائمة من طولها بيضاء شهلاء فخمة الوجه قال فسألتها عن سنها فقالت لا أدري إلا أني كنت\nأذكر شمر بن ذي الجوشن حين قتل الحسين عليه السلام مر بنا وأنا جارية ومعه كسوة فقسمها في قومه قالت وكان أبي قد أدرك الجاهلية وحمل فيها حمالات قال ولما أنشدتني خرقاء بيت ذي الرمة فيها قلت هيهات يا عمة قد ذهب ذلك منك قالت لا تقل يا بني أما سمعت قول قحيف في\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)\nم قالت رحم الله ذا الرمة فقد كان رقيق البشرة عذب المنطق حسن الوصف مقارب الرصف عفيف الطرف فقلت لها لقد أحسنت الوصف فقالت هيهات أن يدركه وصف رحمه الله ورحم من سماه اسمه فقلت ومن سماه قالت سيد بني عدي الحصين بن عبدة بن نعيم ثم أنشدتني لنفسها في ذي الرمة\n(لقد أصبحت في فرعي معد ... مكان النجم في فلك السماء)\n(إذا ذكرت محاسنه تدرت ... بحار الجود من نحو السماء)\n(حصين شاد باسمك غير شك ... فأنت غياث محل بالفناء)\n(إذا ضنت سحابة ماء مزن ... تثج بحار جودك بارتواء)\n(لقد نصرت باسمك أرض قحط ... كما نثرت عدي بالثراء)\nفقلت أحسنت يا خرقاء فهل سمع ذلك منك ذو الرمة قالت إي وربي قلت فماذا قال قالت قال شكر الله لك يا خرقاء نعمة ربيت شكرها من ذكرها فقالت أثقلنا حقها ثم قالت اللهم غفرا هذا في اللفظ ونحتاج إلى العمل\nأخبرني جحظة عن حماد بن إسحاق عن أبيه عن ابن كناسة عن خيثم بن حجية العجلي قال حدثني رجل من بني النجار قال خرجت أمشي في ناحية البادية فمررت على فتاة قائمة على باب بيت فقمت أكلمها فنادتني عجوز من ناحية الخباء ما يقيمك على هذا الغزال النجدي فوالله ما تنال خيرا منه ولا ينفعك قال وتقول هي دعيه يا أماه يكن كما قال ذو الرمة\n(وإن لم يكن إلا معرس ساعة ... قليلا فإني نافع لي قليلها)\nسألت عنهما فقيل لي العجوز خرقاء ذي الرمة والفتاة بنتها","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":13,"spl":"أخباره مع خرقاء","tags":["الجواري والنساء"],"loc":3148},
{"id":"b229-17","bab":"الجزء 18","sec":"روايات في وفاته","page":"ج18 ص47","text":"وتوفي ذو الرمة في خلافة هشام بن عبد الملك وله أربعون سنة\nوقد اختلفت الرواة في سبب وفاته أخبرني علي بن سليمان الأخفش عن أبي سعيد السكري عن يعقوب بن السكيت أنه بلغ أربعين سنة وفيها توفي وهو خارج إلى هشام بن عبد الملك ودفن بحزوى وهي الرملة التي كان يذكرها في شعره أخبرني أبو خليفة عن محمد بن سلام قال حدثني ابن أبي عدي قال قال ذو الرمة بلغت نصف الهرم وأنا ابن أربعين سنة قال ابن سلام وحدثني أبو الغراف أنه مات وهو يريد هشاما وقال في طريقه في ذلك\n(بلاد بها أهلون لست ابن أهلها ... وأخرى بها أهلون ليس بها أهل)\nقال هارون بن محمد بن عبد الملك حدثني القاسم بن محمد الأسدي قال حدثني جبر بن رياط قال أنشد ذو الرمة الناس شعرا له وصف فيه الفلاة بالثعلبية فقال له حلبس الأسدي إنك لتنعت الفلاة نعتا لا تكون منيتك إلا بها قال وصدر ذو الرمة على أحد جفري بني تميم وهما على طريق الحاج من البصرة فلما أشرف على البصرة قال\n(وإني لعاليها وإني لخائف ... لما قال يوم الثعلبية حلبس)\nال ويقال إن هذا آخر شعر قاله فلما توسط الفلاة نزل عن راحلته فنفرت منه ولم تكن تنفر منه وعليها شرابه وطعامه فلما دنا منها نفرت حتى مات فيقال إنه قال عند ذلك\n(ألا أبلغ الفتيان عني رسالة ... أهينوا المطايا هن أهل هوان)\n(فقد تركتني صيدح بمضلة ... لساني ملتاث من الطلوان)\nال هارون وأخبرني أحمد بن محمد الكلابي بهذه القصة وذكر أن ناقته وردت على أهله في مياههم فركبها أخوه وقص أثره حتى وجده ميتا وعليه خلع الخليفة ووجد هذين البيتين مكتوبين على قوسه أخبرني أحمد بن عبد العزيز عن الرياشي عن الأصمعي عن أبي الوجيه قال دخلت على ذي الرمة وهو يجود بنفسه فقلت له كيف تجدك قال أجدني والله أجد ما لا أجد أيام أزعم أني أجد ما لم أجد حيث أقول\n(كأني غداة الزرق يا مي مدنف ... يجود بنفس قد أحم حمامها)\n(حذار اجتذام البين أقران نية ... مصاب ولوعات الفؤاد انجذامها)\nال وكان آخره ما قاله\n(يا رب قد أشرفت نفسي وقد علمت ... علما يقينا لقد أحصيت آثاري)\n(يا مخرج الروح من جسمي إذا احتضرت ... وفارج الكرب زحزحني عن النار)\nال أبو الوجيه وكانت منيته هذه في الجدري وفي ذلك يقول\n(ألم يأتها أني تلبست بعدها ... مفوقة صواغها غير أخرق)\nسخت من كتاب هارون بن الزيات حدثني عبد الوهاب بن إبراهيم الأزدي قال حدثني جهم بن مسعدة قال حدثني محمد بن الحجاج الأسدي عن أبيه قال وردت حجرا وذو الرمة به فاشتكى شكايته التي كانت منها منيته وكرهت أن أخرج حتى أعلم بما يكون في شكاته وكنت أتعهده وأعوده في اليوم واليومين فأتيته يوما وقد ثقل فقلت يا غيلان كيف تجدك فقال أجدني والله يا أبا المثنى اليوم في الموت لا غداة أقول\n(كأني غداة الزرق يا مي مدنف ... يكيد بنفس قد أحم حمامها)\nأنا والله الغداة في ذلك لا تلك الغداة قال هارون بن الزيات حدثني موسى بن عيسى الجعفري قال أخبرني أبي قال أخبرني رجل من بني تميم قال كانت ميتة ذي الرمة أنه اشتكى النوطة فوجعها دهرا فقال في ذلك\n(ألفت كلاب الحي حتى عرفنني ... ومدت نساج العنكبوت على رحلي)\nال ثم قال لمسعود أخيه يا مسعود قد أجدني تماثلت وخفت الأشياء عندنا واحتجنا إلى زيارة بني مروان فهل لك بنا فيهم فقال نعم فأرسله إلى إبله يأتيه منها بلبن يتزوده وواعده مكانا وركب ذو الرمة ناقته فقمصت به وكانت قد أعفيت من الركوب وانفجرت النوطة التي كانت\nبه قال وبلغ موعد صاحبه وجهد وقال أردنا شيئا وأراد الله شيئا وإن العلة التي كانت بي انفجرت فأرسل إلى أهله فصلوا عليه ودفن برأس حزوى وهي الرملة التي كان يذكرها في شعره","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":14,"spl":"روايات في وفاته","tags":["السفر والحج","الوصف والطبيعة"],"loc":3149},
{"id":"b229-18","bab":"الجزء 18","sec":"قبره بالدهناء","page":"ج18 ص51","text":"نسخت من كتاب عبيد الله بن محمد اليزيدي قال أبو عبيدة وذكر هارون بن الزيات عن محمد بن علي بن المغيرة عن أبيه وعن أبي عبيدة عن المنتجع بن نبهان\nقال لما احتضر ذو الرمة قال إني لست ممن يدفن في الغموض والوهاد قالوا فكيف نصنع بك ونحن في رمال الدهناء قال فأين أنتم من كثبان حزوى -\nقال وهما رملتان مشرفتان على ما حولهما من الرمال - قالوا فكيف نحفر لك في الرمل وهو هائل قال فأين الشجر والمدر والأعواد قال فصلينا عليه في بطن الماء ثم حملنا له الشجر والمدر على الكباش وهي أقوى على الصعود في الرمل من الإبل فجعلوا قبره هناك وزبروه بذلك الشجر والمدر ودلوه في قبره فأنت إذا عرفت موضع قبره رأيته قبل أن تدخل الدهناء وأنت بالدو على مسيرة ثلاث قال هارون وحدثني محمد بن صالح العدوي قال ذكر أبو عمرو المرادي\nإن قبر ذي الرمة بأطراف عناق من وسط الدهناء مقابل الأواعس وهي أجبل شوارع يقابلن الصريمة صريمة النعام وهذا الموضع لبني سعد ويختلط معهم الرباب قال هارون وحدثني هارون بن مسلم عن الزيادي عن العلاء بن برد قال ما كان شيء أحب إلى ذي الرمة إذا ما ورد ماء من أن يطوي ولا يسقي فأخبرني مخبر أنه مر بالجفر وقد جهده العطش قال فسمعته يقول\n(يا مخرج الروح من جسمي إذا احتضرت ... وفارج الكرب زحزحني عن النار)\nم قضى أخبرني محمد بن الحسن بن دريد عن عبد الرحمن ابن أخي الأصمعي عن عمه عن عيسى بن عمر قال كان ذو الرمة ينشد الشعر فإذا فرغ قال والله لأكسعنك بشيء ليس في حسابك سبحان الله والحمد لله ولا إله إلا الله والله أكبر أخبرني الحسن بن علي ووكيع عن أبي أيوب قال حدثني أبو معاوية الغلابي قال كان ذو الرمة حسن الصلاة حسن الخشوع فقيل له ما أحسن صلاتك فقال إن العبد إذا قام بين يدي الله لحقيق أن يخشع\nنسخت من كتاب عبيد الله اليزيدي قال حدثني عبد الرحمن عن عمه عن أبي عمرو بن العلاء قال كان مسعود أخو ذي الرمة يمشي معي كثيرا إلى منزلي فقال لي يوما وقد بلغ قريبا من منزلي أنا الذي أقول في أخي ذي الرمة\n(إلى الله أشكو لا إلى الناس إنني ... وليلى كلانا موجع مات وافده)\nقلت له من ليلى فقال بنت أخي ذي الرمة","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":15,"spl":"قبره بالدهناء — ذكر خبر إبراهيم في هذه الأصوات الماخورية","tags":["الجواري والنساء"],"loc":3150},
{"id":"b229-19","bab":"الجزء 18","sec":"ذكر خبر إبراهيم في هذه الأصوات الماخورية","page":"ج18 ص53","text":"أخبرني أحمد بن عبد العزيز عن ابن شبة عن إسحاق الموصلي عن أبيه قال صنعت لحنا فأعجبني وجعلت أطلب له شعرا فعسر ذلك علي فأريت في المنام كأن رجلا لقيني فقال لي يا إبراهيم أوقد أعياك شعر لغنائك هذا الذي تعجب به قلت نعم قال فأين أنت من قول ذي الرمة\n(ألا يا اسلمي يا دار مي على البلى ... ولا زال منهلا بجرعائك القطر)\nال فانتبهت فرحا بالشعر فدعوت من ضرب علي فغنيته فإذا هو أوفق ما خلق الله فلما علمت هذا الغناء في شعر ذي الرمة نبهت عليه وعلى شعره فصنعت فيه ألحانا ماخورية منها\n(أمنزلتي مي سلام عليكما ... هل الأزمن اللائي مضين رواجع)\nوغنيت بها الهادي فاستحسنها وكاد يطير فرحا وأمر لكل صوت بألف دينار","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":15,"spl":"قبره بالدهناء — ذكر خبر إبراهيم في هذه الأصوات الماخورية","tags":[],"loc":3151},
{"id":"b229-20","bab":"الجزء 18","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج18 ص54","text":"\n(ألا يا اسلمي يا دار مي على البلى ... ولا زال منهلا بجرعائك القطر)\n(ولو لم تكوني غير شام بقفرة ... تجر بها الأذيال صيفية كدر)\nروضه من الطويل وقوله يا اسلمي ها هنا نداء كأنه قال يا دار مي اسلمي ويا هذه اسلمي يدعو لها بالسلامة ومثله قول الله عز و جل ( ألا يسجدوا لله الذي يخرج الخبء في السموات والأرض\nفسره أهل اللغة هكذا كأنه قال يا قوم اسجدوا لله ومي ترخيم مية إلا أنه أقامه ها هنا مقام الاسم الذي لم يرخم فنونه وقوله على البلى أي اسلمي وإن كنت قد بليت والمنهل الجاري يقال انهل المطر انهلالا إذا سال والجرعاء والأجرع من الرمل الكثير الممتد والشام موضع يخالف لون الأرض وهو جمع واجدته شامة والقفر ما لم يكن فيه نبات ولا ماء تجر بها الأذيال صيفية يعني الرياح الصيفية الحارة وأذيالها مآخيرها التي تسفي التراب على وجه الأرض شبهها بذيل المرأة وعني بها أوائلها والكدر التي فيها الغبرة\nمن القتام والفجاج فهي تعفي الآثار وتدفنها غناه إبراهيم الموصلي ماخوريا بالوسطى ومنها\n(أمنزلتي مي سلام عليكما ... هل الأزمن اللائي مضين رواجع)\n(وهل يرجع التسليم أو يكشف العمى ... ثلاث الأثافي والديار البلاقع)\n(توهمتها يوما فقلت لصاحبي ... وليس لها إلا الظباء الخواضع)\n(وموشية سحم الصياصي كأنها ... مجللة حو عليها البراقع)\nروضه من الطويل غناه إبراهيم ماخوريا بالوسطى والأزمن والأزمان جمع زمان والعمى الجهالة والأثافي الثلاث هي الحجارة التي تنصب عليها القدر واحدتها أثفية والخواضع من الظباء اللاتي قد طأطأت رؤوسها والموشية يعني البقر والصياصي القرون واحدتها صيصية والمجللة التي كأن عليها جلالا سودا والحوة حمرة في سواد ومما يغنى فيه من هذه القصيدة قوله\n(قف العنس ننظر نظرة في ديارها ... وهل ذاك من داء الصبابة نافع)\n(فقال أما تغشى لمية منزلا ... من الأرض إلا قلت هل أنا رابع)\n(وقل لأطلال لمي تحية ... تحيا بها أو أن ترش المدامع)\nالعنس الناقة والرابع المقيم وقل لأطلال أي ما أقل لهذه الأطلال مما أفعله وترش المدامع أي تكثر نضحها الدموع غناه إبراهيم الموصلي ماخوريا\nوذكر ابن الزيات عن محمد بن صالح العذري عن الحرمازي قال مر الفرزدق على ذي الرمة وهو ينشد\n(أمنزلتي مي سلام عليكما ... )\nلما فرغ قال له يا أبا فراس كيف ترى قال أراك شاعرا قال فما أقعدني عن غاية الشعراء قال بكاؤك على الدمن ووصفك القطا وأبوال الإبل حدثني ابن عمار والجوهري وحبيب المهلبي عن ابن شبة عن إسحاق الموصلي عن مسعود بن قند\nقال تذاكرنا ذا الرمة يوما فقال عصمة بن مالك إياي فاسألوا عنه قال كان حلو العينين حسن النغمة إذا حدث لم تسأم حديثه وإذا أنشدك بربر وجش صوته جمعني وإياه مربع مرة فقال لي هيا عصمة إن مية من منقر ومنقر أخبث حي وأقفاه لأثر وأثبته في نظر وأعلمه بشر وقد عرفوا آثار إبلي فهل عندك من ناقة نزدار عليها مية\nقلت إي والله عندي الجؤذر بنت يمانية الجدلي قال فعلي بها فأتيته بها فركب وردفته فأتينا محلة مية والقوم خلوف والنساء في الرحال فلما رأين ذا الرمة اجتمعن إلى مي وأنخنا قريبا وأتيناهن فجلسن إليهن فقالت ظريفة منهن أنشدنا يا ذا الرمة فقال لي أنشدهن يا عصمة فأنشدت قصيدته التي يقول فيها\n(نظرت إلى أظعان مي كأنها ... ذرا النخل أو أثل تميل ذوائبه)\n(فأسبلت العينان والقلب كاتم ... بمغرورق نمت عليه سواكبه)\n(بكاء فتى خاف الفراق ولم تجل ... حوائلها أسراره ومعاتبه)\nالت الظريفة فالآن فلتجل ثم أنشدت حتى أتيت على قوله\n(وقد حلفت بالله مية ما الذي ... أحدثها إلا الذي أنا كاذبه)\n(إذا فرماني الله من حيث لا أرى ... ولا زال في أرضي عدو أحاربه)\nقالت مية ويحك يا ذا الرمة خف الله وعواقبه ثم أنشدت حتى أتيت على قوله\n(إذا سرحت من حب مي سوارح ... على القلب أبته جميعا عوازبه)\nقالت الظريفة قتلته قتلك الله فقالت مية ما أصحه وهنيئا له فتنفس ذو الرمة تنفيسة كاد حرها يطير بلحيتي ثم أنشدت حتى أتيت على قوله\n(إذا نازعتك القول مية أو بدا ... لك الوجه منها أو نضا الدرع سالبه)\n(فما شئت من خد أسيل ومنطق ... رخيم ومن خلق تعلل جادبه)","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":16,"spl":"نسبة ما في هذا الخبر من الغناء","tags":["الحب والغزل"],"song":3,"loc":3152,"partialRef":{"sid":"b52-44","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b229-21","bab":"الجزء 18","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج18 ص54","text":"قالت الظريفة فقد بدا لك الوجه وتنوزع القول فمن لنا بأن ينضو الدرع سالبه فقالت لها مية قاتلك الله فماذا تأتين به فتضاحكت الظريفة وقالت إن لهذين لشأنا فقوموا بنا عنهما فقامت وقمن معها وقمت فخرجت وكنت قريبا حيث أراهما وأسمع ما ارتفع من كلاميهما فوالله ما رأيته تحرك من مكانه الذي خلفته فيه حتى ثاب أوائل الرجال فأتيته فقلت انهض بنا فقد ثاب القوم فودعها فركب وردفته وانصرفنا ومنها\n\n(إذا هبت الأرواح من أي جانب ... به أهل مي هاج قلبي هبوبها)\n(هوى تذرف العينان منه وإنما ... هوى كل نفس حيث كان حبيبها)\nلغناء لابراهيم ماخوري بالوسطى عن الهشامي\n(إني تذكرني الزبير حمامة ... تدعو بمجمع نخلتين هديلا)\n(أفتى الندى وفتى الطعان قتلتم ... وفتى الرياح إذا تهب بليلا)\n(لو كنت حرا يابن قين مجاشع ... شيعت ضيفك فرسخا أو ميلا)\nفي أخرى فرسخين وميلا\n(قالت قريش ما أذل مجاشعا ... جارا وأكرم ذا القتيل قتيلا)\nالشعر لجرير يهجو الفرزدق ويعيره بقتل عشيرته الزبير بن العوام يوم الجمل والغناء للغريض ثاني ثقيل بالبنصر عن عمرو","topic":"ذكر ذي الرمة وخبره","topicNo":229,"sp":17,"spl":"نسبة ما في هذا الخبر من الغناء","tags":[],"song":2,"loc":3153},
{"id":"b230-1","bab":"الجزء 18","sec":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","page":"ج18 ص59","text":"حدثنا أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز عن ابن شبة قالا حدثنا المدائني عن أبي بكر الهذلي عن قتادة قال سار أمير المؤمنين علي بن أبي طالب صلوات الله عليه من الزاوية يريد طلحة والزبير وعائشة وصاروا من الفرضة يريدونه فالتقوا عند قصر عبيد الله بن زياد يوم الخميس النصف من جمادى الآخرة سنة ست وثلاثين فلما تراءى الجمعان خرج الزبير على فرس وعليه سلاحه فقيل لعلي صلوات الله عليه هذا الزبير فقال أما والله إنه أحرى الرجلين إن ذكر\nبالله أن يذكره وخرج طلحة وخرج علي عليه السلام إليهما فدنا منهما حتى اختلفت أعناق دوابهم فقال لهما لعمري لقد أعددتما خيلا ورجالا إن كنتما أعددتما عند الله عذرا فاتقيا الله ولا تكونا ( كالتي نقضت غزلها من بعد قوة أنكاثا\nألم أكن أخاكما في دينكما تحرمان دمي وأحرم دماءكما فهل من حدث أحل لكما دمي فقال له طلحة ألبت الناس على عثمان فقال يا طلحة أتطلبني بدم عثمان فلعن الله قتلة عثمان يا زبير أتذكر يوم مررت مع رسول الله وآله في بني غنم فنظر إلي وضحك وضحكت إليه فقلت لا يدع ابن أبي طالب زهوه فقال مه ليس بمزهو ولتقاتلنه وأنت له ظالم فقال اللهم نعم ولو ذكرت ما سرت مسيري هذا والله لا أقاتلك أبدا وانصرف علي صلوات الله عليه إلى أصحابه\nوقال أما الزبير فقد أعطى الله عهدا ألا يقاتلني قال ورجع الزبير إلى عائشة فقال لها ما كنت في موطن مذ عقلت إلا وأنا أعرف فيه أمري غير موطني هذا قالت وما تريد أن تصنع\nقال أدعهم وأذهب فقال له ابنه عبد الله أجمعت بين هذين الغارين حتى إذا حدد بعضهم لبعض أردت أن تذهب وتتركهم أخشيت رايات ابن أبي طالب وعلمت أنها تحملها فتية أنجاد فأحفظه فقال إني حلفت ألا أقاتله قال كفر عن يمينك وقاتله فدعا غلاما له يدعى مكحولا فأعتقه فقال عبد الرحمن بن سليمان التيمي\n(لم أر كاليوم أخا إخوان ... أعجب من مكفر الأيمان)\n(بالعتق في معصية الرحمن ... )\nقال بعض شعرائهم\n(يعتق مكحولا لصون دينه ... كفارة لله عن يمينه)\n(والنكث قد لاح على جبينه ... )\nدثني ابن عمار والجوهري قال حدثنا ابن شبة عن علي بن محمد النوفلي عن الهذلي عن قتادة قال وقف الزبير على مسجد بني مجاشع فسأل عن عياض بن حماد فقال له النعمان بن زمام هو بوادي السباع فمضى يريده\nحدثني ابن عمار والجوهري عن عمر قال حدثني المدائني عن أبي مخنف عمن حدثه عن الشعبي قال خرج النعمان مع الزبير حتى بلغ النجيب ثم رجع قال\nوحدثنا عن مسلمة بن محارب عن عوف وعن أبي اليقظان قالا مر الزبير ببني حماد فدعوه إلى أنفسهم فقال اكفوني خيركم وشركم فوالله ما كفوه خيرهم وشرهم ومضى ابن فرتنى إلى الأحنف وهو بعرق سويقة فقال هذا الزبير قد مر فقال الأحنف ما أصنع به جمع بين غارين من المسلمين فقتل بعضهم بعضا ثم مر يريد أن يلحق بأهله فقام عمرو بن جرموز وفضالة بن حابس ونفيع بن كعب أحد بني عوف - ويقال نفيع بن عمير - فلحقوه بالعرق فقتل قبل أن ينتهي إلى عياض قتله عمرو بن جرموز حدثني أحمد بن عيسى بن أبي موسى العجلي الكوفي وجعفر بن محمد بن الحسن العلوي الحسني والعباس بن علي بن العباس وأبو عبيد\nالصيرفي قالوا حدثنا محمد بن علي بن خلف العطار قال حدثنا عمرو بن عبد الغفار عن سفيان الثوري عن جعفر بن محمد عن أبيه عن علي بن الحسين عليه السلام\nقال حدثني ابن عباس قال قال لي علي صلوات الله عليه ائت الزبير فقل له يقول لك علي بن أبي طالب نشدتك الله ألست قد بايعتني طائعا غير مكره فما الذي أحدثت فاستحللت به قتالي\nوقال أحمد بن يحيى في حديثه قل لهما إن أخاكما يقرأ عليكما السلام ويقول هل نقمتما علي جورا في حكم أو استئثارا بفيء فقالا لا ولا واحدة منهما ولكن الخوف وشدة الطمع\nوقال محمد بن خلف في خبره فقال الزبير مع الخوف شدة المطامع فأتيت عليا عليه السلام فأخبرته بما قال الزبير فدعا بالبغلة فركبها وركبت معه فدنوا حتى اختلفت أعناق دابتيهما فسمعت عليا صلوات الله عليه يقول نشدتك الله يا زبير أتعلم أني كنت أنا وأنت في سقيفة بني فلان تعالجني وأعالجك فمر بي - يعني النبي فقال كأنك تحبه فقلت وما يمنعني","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":0,"spl":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","tags":["اللهو والمزاح"],"loc":3154,"partial":1},
{"id":"b230-2","bab":"الجزء 18","sec":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","page":"ج18 ص59","text":"قال أما إنه ليقاتلنك وهو لك ظالم فقال الزبير اللهم نعم ذكرتني ما نسيت وولى راجعا ونادى منادي علي ألا لا تقاتلوا القوم حتى يستشهدوا منكم رجلا فما لبث أن أتي برجل يتشحط في دمه فقال علي عليه السلام اللهم اشهد اللهم اشهد اللهم اشهد وأمر الناس فشدوا عليهم وأمر الصراخ فصرخوا لا تذففوا على جريح ولا تتبعوا مدبرا ولا تقتلوا أسيرا\nحدثنا إبراهيم بن عبد الله بن محمد بن أيوب المخزومي عن سعيد بن محمد الجرمي عن أبي الأحوص عن عاصم بن بهدلة عن زر بن حبيش ولا أحسبه إلا قال كنت قاعدا عند علي عليه السلام فأتاه آت فقال هذا ابن جرموز قاتل الزبير بن العوام يستأذن على الباب قال ليدخلن قاتل ابن صفية النار إني سمعت رسول الله يقول ( إن لكل نبي حواري وإن حواري الزبير\nخبرني الطوسي وحرمي عن الزبير عن علي بن صالح عن سالم بن عبد الله بن عروة عن أبيه أن عمرا أو عويمر بن جرموز قاتل الزبير أتى مصعبا حتى وضع يده في يده فقذفه في السجن وكتب إلى عبد الله بن الزبير يذكر له أمره فكتب إليه عبد الله بئس ما صنعت أظننت أني أقتل أعرابيا من بني تميم بالزبير خل سبيله فخلاه","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":1,"spl":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","tags":["الرواية والكتابة"],"loc":3155},
{"id":"b230-3","bab":"الجزء 18","sec":"عاتكة ترثي الزبير","page":"ج18 ص63","text":"أخبرني الطوسي والحرمي عن الزبير عن عمه قال قتل الزبير وهو ابن سبع وستين أو ست وستين سنة فقالت عاتكة بنت زيد بن عمرو بن نفيل ترثيه\n(غدر ابن جرموز بفارس بهمة ... يوم اللقاء وكان غير معرد)\n(يا عمرو لو نبهته لوجدته ... لا طائشا رعش اللسان ولا اليد)\n(شلت يمينك إن قتلت لمسلما ... حلت عليك عقوبة المستشهد)\n(إن الزبير لذو بلاء صادق ... سمح سجيته كريم المشهد)\n(كم غمرة قد خاضها لم يثنه ... عنها طرادك يابن فقع القردد)\n(فاذهب فما ظفرت يداك بمثله ... فيمن مضى ممن يروح ويغتدي)\nكانت عاتكة قبل الزبير عند عمر وقبل عمر عند عبد الله بن أبي بكر أخبرني بخبرها محمد بن خلف وكيع عن أحمد بن عمرو بن بكر قال حدثنا أبي\nقال حدثنا الهيثم بن عدي عن محمد بن عمرو عن أبي سلمة بن عبد الرحمن وأخبرنا وكيع قال حدثني إسماعيل بن مجمع عن المدائني وأخبرني الطوسي والحرمي قالا\nحدثنا الزبير عن عمه عن أبيه وأخبرني اليزيدي عن الخليل بن أسد عن عمرو بن سعيد عن الوليد بن هشام بن يحيى الغساني وأخبرني الجوهري عن ابن شبة\nقال حدثنا محمد بن موسى الهذلي وكل واحد منهم يزيد في الرواية وينقص منها وقد جمعت رواياتهم قالوا تزوج عبد الله بن أبي بكر الصديق عاتكة بنت زيد بن عمرو بن نفيل وكانت امرأة لها جمال وكمال وتمام في عقلها ومنظرها وجزالة رأيها وكانت قد غلبته على رأيه فمر عليه أبو بكر أبوه وهو في علية يناغيها في يوم جمعة وأبو بكر متوجه إلى الجمعة ثم رجع وهو يناغيها فقال يا عبد الله\nأجمعت قال أوصلى الناس قال نعم - قال وقد كانت شغلته عن سوق وتجارة كان فيها - فقال له أبو بكر قد شغلتك عاتكة عن المعاش والتجارة وقد ألهتك عن فرائض الصلاة طلقها فطلقها تطليقة وتحولت إلى ناحية فبينا أبو بكر يصلي على سطح له في الليل إذ سمعه وهو يقول\n(أعاتك لا أنساك ما ذر شارق ... وما ناح قمري الحمام المطوق)\n(أعاتك قلبي كل يوم وليلة ... لديك بما تخفي النفوس معلق)\n(لها خلق جزل ورأي ومنطق ... وخلق مصون في حياء ومصدق)\n(فلم أر مثلي طلق اليوم مثلها ... ولا مثلها في غير شيء تطلق)\nسمع أبو بكر قوله فأشرف عليه وقد رق له فقال يا عبد الله راجع عاتكة فقال أشهدك أني قد راجعتها وأشرف على غلام له يقال له أيمن فقال له يا أيمن أنت حر لوجه الله تعالى أشهدك أني قد راجعت عاتكة ثم خرج إليها يجري إلى مؤخر الدار وهو يقول\n(أعاتك قد طلقت في غير ريبة ... وروجعت للأمر الذي هو كائن)\n(كذلك أمر الله غاد ورائح ... على الناس فيه ألفة وتباين)\n(وما زال قلبي للتفرق طائرا ... وقلبي لما قد قرب الله ساكن)\n(ليهنك أني لا أرى فيك سخطة ... وأنك قد تمت عليك المحاسن)\n(فإنك ممن زين الله وجهه ... وليس لوجه زانه الله شائن)\nال وأعطاها حديقة له حين راجعها على ألا تتزوج بعده فلما مات من السهم الذي أصابه بالطائف أنشأت تقول\n(فلله عينا من رأى مثله فتى ... أكر وأحمى في الهياج وأصبرا)\n(إذا شرعت فيه الأسنة خاضها ... الى الموت حتى يترك الرمح أحمرا)\n(فأقسمت لا تنفك عيني سخينة ... عليك ولا ينفك جلدي أغبرا)\n(مدى الدهر ما غنت حمامة أيكة ... وما طرد الليل الصباح المنورا)","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":2,"spl":"عاتكة ترثي الزبير","tags":["الجواري والنساء"],"loc":3156},
{"id":"b230-4","bab":"الجزء 18","sec":"عمر بن الخطاب وعاتكة","page":"ج18 ص66","text":"فخطبها عمر بن الخطاب فقالت قد كان أعطاني حديقة على ألا أتزوج بعده قال فاستفتي فاستفتت علي بن أبي طالب عليه السلام فقال ردي الحديقة على أهله وتزوجي فتزوجت عمر فسرح عمر إلى عدة من أصحاب رسول الله فيهم علي بن أبي طالب صلوات الله عليه - يعني دعاهم - لما بنى بها فقال له علي إن لي إلى عاتكة حاجة أريد أن أذكرها إياها فقل لها تستتر حتى أكلمها فقال لها عمر استتري يا عاتكة فإن ابن أبي طالب يريد أن يكلمك فأخذت عليها مرطها فلم يظهر منها إلا ما بدا من براجمها فقال يا عاتكة\n(فأقسمت لا تنفك عيني سخينة ... عليك ولا ينفك جلدي أغبرا)\nقال له عمر ما أردت إلى هذا فقال وما أرادت إلى أن تقول ما لا تفعل وقد قال الله تعالى ( كبر مقتا عند الله أن تقولوا ما لا تفعلون\nوهذا شيء كان في نفسي أحببت والله أن يخرج فقال عمر ما حسن الله فهو حسن فلما قتل عمر قالت ترثيه\n(عين جودي بعبرة ونحيب ... لا تملي على الإمام النجيب)\n(فجعتنا المنون بالفارس المعلم ... يوم الهياج والتلبيب)\n(عصمة الله والمعين على الدهر ... غياث المنتاب والمحروب)\n(قل لأهل الضراء والبؤس موتوا ... قد سقته المنون كأس شعوب)\nالت ترثيه أيضا\n(منع الرقاد فعاد عيني عيد ... مما تضمن قلبي المعمود)\n(يا ليلة حبست علي نجومها ... فسهرتها والشامتون هجود)\n(قد كان يسهرني حذارك مرة ... فاليوم حق لعيني التسهيد)\n(أبكي أمير المؤمنين ودونه ... للزائرين صفائح وصعيد)\nنى فيه طويس خفيف رمل عن حماد والهشامي فلما انقضت عدتها خطبها الزبير بن العوام فتزوجها فلما ملكها قال يا عاتكة لا تخرجي إلى المسجد وكانت امرأة عجراء بادنة فقالت يا ابن العوام أتريد أن أدع لغيرتك مصلى صليت مع رسول الله وأبي بكر وعمر فيه\nقال فإني لا أمنعك فلما سمع النداء لصلاة الصبح توضأ وخرج فقام لها في سقيفة بني ساعدة فلما مرت به ضرب بيده على عجيزتها فقالت مالك قطع الله يدك ورجعت فلما رجع من المسجد\nقال يا عاتكة ما لي لم أرك في مصلاك قالت يرحمك الله أبا عبد الله فسد الناس بعدك الصلاة اليوم في القيطون أفضل منها في البيت وفي البيت أفضل منها في الحجرة فلما قتل عنها الزبير بوادي السباع رثته فقالت\n(غدر ابن جرموز بفارس بهمة ... يوم اللقاء وكان غير معرد)\n(يا عمرو لو نبهته لوجدته ... لا طائشا رعش اللسان ولا اليد)\n(هبلتك أمك إن قتلت لمسلما ... حلت عليك عقوبة المتعمد)\nلما انقضت عدتها تزوجها الحسين بن علي بن أبي طالب عليهما السلام فكانت أول من رفع خده من التراب - صلى الله عليه وآله ولعن قاتله والراضي به يوم قتل - وقالت ترثيه\n(وحسينا فلا نسيت حسينا ... أقصدته أسنة الأعداء)\n(غادروه بكربلاء صريعا ... جادت المزن في ذرى كربلاء)\nم تأيمت بعده فكان عبد الله بن عمر يقول من أراد الشهادة فليتزوج بعاتكة ويقال إن مروان خطبها بعد الحسين عليه السلام فامتنعت عليه وقالت ما كنت لأتخذ حما بعد رسول الله أخبرنا محمد بن العباس اليزيدي\nقال حدثنا الخليل بن أسد قال حدثني العمري قال حدثنا أسامة بن زيد عن القاسم بن محمد قال لم يزل السهم الذي أصاب عبد الله بن أبي بكر عند ابي بكر حتى قدم وفد ثقيف فأخرجه إليهم فقال من يعرف هذا منكم فقال سعيد بن عبيد من بني علاج هذا سهمي وأنا بريته وأنا رشته وأنا عقبته وأنا رميت به يوم الطائف فقال أبو بكر فهذا السهم الذي قتل عبد الله والحمد لله الذي أكرمه بيدك ولم يهنك بيده","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":3,"spl":"عمر بن الخطاب وعاتكة","tags":["الجواري والنساء"],"song":1,"loc":3157},
{"id":"b230-5","bab":"الجزء 18","sec":"طويس يغني شعرا لعاتكة","page":"ج18 ص69","text":"أخبرني اليزيدي عن الزبير عن أحمد بن عبيد الله بن عاصم بن المنذر بن الزبير قال لما قتل الزبير وخلت عاتكة بنت زيد خطبها علي بن أبي طالب عليه السلام فقالت له إني لأضن بك على القتل يابن عم رسول الله\nأخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن سلام قال حدثني أبي قال بينا فتية من قريش ببطن محسر يتذاكرون الأحاديث ويتناشدون الأشعار إذ أقبل طويس وعليه قميص قوهي وحبرة قد ارتدى بها وهو يخطر في مشيته فسلم ثم جلس فقال له القوم يا أبا عبد الله غننا شعرا مليحا له حديث ظريف فغناهم بشعر عاتكة بنت زيد ترثي عمر بن الخطاب\n(منع الرقاد فعاد عيني عيد ... مما تضمن قلبي المعمود)\nلأبيات فقال القوم لمن هذه الأبيات يا طويس قال لأجمل خلق الله وأشأمهم فقالوا بأنفسنا أنت من هذه قال هي والله من لا يجهل نسبها ولا يدفع شرفها تزوجت بابن خليفة نبي الله وثنت بخليفة خليفة نبي الله وثلثت بحواري نبي الله وربعت بابن نبي الله وكلا قتلت قالوا جميعا\nجعلنا فداك إن أمر هذه لعجيب بآبائنا أنت من هذه قال عاتكة بنت زيد بن عمرو بن نفيل فقالوا نعم هي على ما وصفت قوموا بنا لا يدرك مجلسنا شؤمها قال طويس إن شؤمها قد مات معها قالوا أنت والله أعلم منا\n(يا دنانير قد تنكر عقلي ... وتحيرت بين وعد ومطل)\n(شغفي شافعي إليك وإلا ... فاقتليني إن كنت تهوين قتلي)\nلشعر والغناء لعقيد مولى صالح بن الرشيد خفيف ثقيل وفيه لعريب رمل بالوسطى وهذا الشعر يقوله في دنانير مولاة البرامكة وكان خطبها فلم تجبه وقيل بل قاله أحد اليزيديين ونحله إياه","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":4,"spl":"طويس يغني شعرا لعاتكة","tags":[],"song":1,"loc":3158},
{"id":"b230-6","bab":"الجزء 18","sec":"ذكر أخبار دنانير وأخبار عقيد","page":"ج18 ص70","text":"كانت دنانير مولاة يحيى بن خالد البرمكي وكانت صفراء مولدة وكانت من أحسن الناس وجها وأظرفهن وأكملهن أدبا وأكثرهن رواية للغناء والشعر\nوكان الرشيد لشغفه بها يكثر مصيره إلى مولاها ويقيم عندها ويبرها ويفرط حتى شكته زبيدة إلى أهله وعمومته فعاتبوه على ذلك ولها كتاب مجرد في الأغاني مشهور وكان اعتمادها في غنائها على ما أخذته من بذل وهي خرجتها وقد أخذت أيضا عن الأكابر الذين أخذت بذل عنهم مثل فليح وإبراهيم وابن جامع وإسحاق ونظرائهم\nأخبرني جحظة قال حدثني المكي عن أبيه قال كنت أنا وابن جامع نعايي دنانير جارية البرامكة فكثيرا ما كانت تغلبنا أخبرني إسماعيل بن يونس الشيعي عن ابن شبة\nقال حدثني إسحاق الموصلي قال قال لي أبي قال لي يحيى بن خالد إن ابنتك دنانير قد عملت صوتا اختارته وأعجبت به فقلت لها لا يشتد إعجابك حتى تعرضيه على شيخك فإن رضيه فارضيه لنفسك وإن كرهه فاكرهيه فامض حتى يتعرضه عليك\nقال فقال لي أبي فقلت له أيها الوزير فكيف إعجابك أنت به فإنك والله ثاقب الفطنة صحيح التمييز قال أكره أن أقول لك أعجبني فيكون عندك غير معجب إذ كنت عندي رئيس صناعتك تعرف منها ما لا أعرف وتقف من لطائفها على ما لا أقف وأكره أن أقول لك لا يعجبني وقد بلغ من قلبي مبلغا محمودا وإنما يتم السرور به إذا صادف ذلك منك استجادة وتصويبا قال فمضيت إليها وقد تقدم إلى خدمه\nيعلمهم أنه سيرسل بي إلى داره وقال لدنانير إذا جاءك إبراهيم فاعرضي عليه الصوت الذي صنعته واستحسنته فإن قال لك أصبت سررتني بذلك وإن كرهه فلا تعلميني لئلا يزول سروري بما صنعت\nقال إسحاق قال أبي فحضرت الباب فأدخلت وإذا الستارة قد نصبت فسلمت على الجارية من وراء الستارة فردت السلام وقالت يا أبت أعرض عليك صوتا قد تقدم لا شك إليك خبره وقد سمعت الوزير يقول إن الناس يفتنون بغنائهم فيعجبهم منه ما لا يعجب غيرهم وكذلك يفتنون بأولادهم فيحسن في أعينهم منهم ما ليس يحسن وقد خشيت على الصوت أن يكون كذلك فقلت هات فأخذت عودها وتغنت تقول\n(نفسي أكنت عليك مدعيا ... أم حين أزمع بينهم خنت)\n(إن كنت مولعة بذكرهم ... فعلى فراقهم ألا مت)\nال فأعجبني والله غاية العجب واستخفني الطرب حتى قلت لها أعيديه فأعادته وأنا أطلب لها فيه موضعا أصلحه وأغيره عليها لتأخذه عني فلا والله ما قدرت على ذلك ثم\nقلت لها أعيديه الثالثة فأعادته فإذا هو كالذهب المصفى فقلت أحسنت يا بنية وأصبت وقد قطعت عليك بحسن إحسانك وجودة إصابتك أنك قائدة للمعلمين إذ قد صرت تحسنين الاختيار وتجيدين الصنعة\nقال ثم خرج فلقيه يحيى بن خالد فقال كيف رأيت صنعة ابنتك دنانير قال أعز الله الوزير والله ما يحسن كثير من حذاق المغنين مثل هذه الصنعة ولقد\nقلت لها أعيديه وأعادته علي مرات كل ذلك أريد إعناتها لأجتلب لنفسي مدخلا يؤخذ عني وينسب إلي فلا والله ما وجدته فقال لي يحيى وصفك لها يقوم مقام تعليمك إياها وقد - والله - سررتني وسأسرك فوجه إليه بمال عظيم","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":5,"spl":"ذكر أخبار دنانير وأخبار عقيد","tags":[],"song":1,"loc":3159},
{"id":"b230-7","bab":"الجزء 18","sec":"يحيى بن خالد يشتريها والرشيد يعجب بها","page":"ج18 ص73","text":"وذكر محمد بن الحسن الكاتب قال حدثني ابن المكي قال كانت دنانير لرجل من أهل المدينة وكان خرجها وأدبها وكانت أروى الناس للغناء القديم وكانت صفراء صادقة الملاحة فلما رآها يحيى وقعت بقلبه فاشتراها وكان الرشيد يسير إلى منزله فيسمعها حتى ألفها واشتد عجبه بها فوهب لها هبات سنية منها أنه وهب لها في ليلة عيد عقدا قيمته ثلاثون ألف دينار فرد عليه في مصادرة البرامكة بعد ذلك وعلمت أم جعفر خبره فشكته إلى عمومته فصاروا جميعا إليه فعاتبوه فقال ما لي في هذه الجارية من أرب في نفسها وإنما أربي في غنائها فاسمعوها فإن استحقت أن يؤلف غناؤها وإلا فقولوا ما شئتم فأقاموا عنده ونقلهم إلى يحيى حتى سمعوها عنده فعذروه وعادوا إلى أم جعفر فأشاروا عليها ألا تلح في أمرها فقبلت ذلك وأهدت إلى الرشيد عشر جوار منهن ماردة أم المعتصم ومراجل أم المأمون وفاردة أم صالح\nوقال هارون بن محمد بن عبد الملك الزيات أخبرني محمد بن عبد الله الخزاعي قال حدثني عباد البشري قال مررت بمنزل من منازل طريق مكة يقال لها النباج فإذا كتاب على حائط في المنزل فقرأته فإذا هو النيك أربعة\nفالأول شهوة والثاني لذة والثالث شفاء والرابع داء وحر إلى أيرين أحوج من أير إلى حرين وكتبت دنانير مولاة البرامكة بخطها أخبرني إسماعيل بن يونس عن ابن شبة أن دنانير أخذت عن إبراهيم الموصلي حتى كانت تغني غناءه فتحكيه فيه حتى لا يكون بينهما فرق وكان إبراهيم يقول ليحيى متى فقدتني ودنانير باقية فما فقدتني\nقال وأصابتها العلة الكلبية فكانت لا تصبر عن الأكل ساعة واحدة فكان يحيى يتصدق عنها في كل يوم من شهر رمضان بألف دينار لأنها كانت تلا تصومه وبقيت عند البرامكة مدة طويلة","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":6,"spl":"يحيى بن خالد يشتريها والرشيد يعجب بها","tags":["الجواري والنساء","السفر والحج"],"loc":3160},
{"id":"b230-8","bab":"الجزء 18","sec":"الرشيد يأمر بصفعها بسبب رفضها الغناء","page":"ج18 ص74","text":"أخبرني ابن عمار وابن عبد العزيز وابن يونس عن ابن شبة عن إسحاق وأخبرني جحظة عن أحمد بن الطيب أن الرشيد دعا بدنانير البرمكية بعد قتله إياهم فأمرها أن تغني فقالت يا أمير المؤمنين إني آليت ألا أغني بعد سيدي أبدا فغضب وأمر بصفعها فصفعت وأقيمت على رجليها وأعطيت العود وأخذته وهي تبكي أحر بكاء واندفعت فغنت\n(يا دار سلمى بنازح السند ... بين الثنايا ومسقط اللبد)\n(لما رأيت الديار قد درست ... أيقنت أن النعيم لم يعد)\nالغناء للهذلي خفيف ثقيل أول مطلق في مجرى الوسطى وذكر علي بن يحيى المنجم وعمرو أنه لسياط في هذه الطريقة قال فرق لها الرشيد وأمر بإطلاقها وانصرفت ثم التفت إلى إبراهيم بن المهدي فقال له كيف رأيتها\nقال رأيتها تختله برفق وتقهره بحذق قال علي بن محمد الهشامي حدثني أبو عبد الله بن حمدون أن عقيدا مولى صالح بن الرشيد خطب دنانير البرمكية وكان هويها وشغف بذكرها فردته واستشفع عليها مولاه صالح بن الرشيد وبذل والحسين بن محرز فلم تجبه وأقامت على الوفاء لمولاها فكتب إليها عقيد قوله\n(يا دنانير قد تنكر عقلي ... وتحيرت بين وعد ومطل)\n(شفعي شافعي إليك وإلا ... فاقتليني إن كنت تهوين قتلي)\n(أنا بالله والأمير وما آمل ... من موعد الحسين وبذل)\n(ما أحب الحياة يا حب إن لم ... يجمع الله عاجلا بك شملي)\nلم يعطفها ذلك على ما يحب ولم تزل على حالها إلى أن ماتت وكان عقيد حسن الغناء والضرب قليل الصنعة ما سمعنا منه بكبير صنعة ولكنه كان بموضع من الحذق والتقدم قال محمد بن الحسن حدثني أبو حارثة عن أخيه أبي معاوية قال شهدت إسحاق يوما وعقيد يغنيه\n(هلا سألت ابنة العبسي ما حسبي ... عند الطعان إذا ما احمرت الحدق)\n(وجالت الخيل بالأبطال عابسة ... شعث النواصي عليها البيض تأتلق)\nلشعر يقال إنه لعنترة ولم يصح له والغناء لابن محرز خفيف ثقيل أول بالوسطى قال فجعل إسحاق يستعيده ويشرب ويصفق حتى والى بين أربعة أرطال وسأله بعض من حضر من أحسن الناس غناء قال من سقاني أربعة أرطال وفي دنانير يقول أبو حفص الشطرنجي\n\n(أشبهك المسك وأشبهته ... قائمة في لونه قاعده)\n(لا شك إذ لونكما واحد ... أنكما من طينة واحدة)\nناه ابن جامع هزجا بالبنصر وقيل إنه لأبي فارة وذكر هارون بن محمد بن عبد الملك الزيات عن علي بن محمد النوفلي عن مولاة ابن جامع أن مولاها كان يهوى جارية صفراء فقال فيها هذا الشعر وغنى فيه وأظن هذا وهما لأنا لم نسمع لابن جامع بشعر قط ولعله غناه في شعر أبي حفص الشطرنجي فظننته له ومما غناه عقيد في دنانير والشعر للموصلي إلا البيت الأول فليس له\n(هذي دنانير تنساني فأذكرها ... وكيف تنسى محبا ليس ينساها)\n(والله والله لو كانت إذا برزت ... نفس المتيم في كفيه ألقاها)\nالشعر والغناء لعقيد ولحنه من الرمل المطلق في مجرى الوسطى وفيه هزج خفيف محدث قال أحمد بن أبي طاهر حدثني علي بن محمد قال حدثني جابر بن مصعب عن مخارق قال مرت بي ليلة ما مر بي قط مثلها جاءني رسول محمد الأمين وهو\nخليفة فأخذني وركض بي إليه ركضا فحين وافيت أتي بإبراهيم بن المهدي على مثل حالي فنزلنا وإذا هو في صحن لم أر مثله قد مليء شمعا من شمع محمد الأمين الكبار وإذا به واقف ثم دخل في الكرح والدار مملوءة بالوصائف يغنين على الطبول والسرنايات ومحمد في وسطهن يرتكض في الكرح فجاءنا رسوله فقال قوما في هذا الباب مما يلي الصحن فارفعا أصواتكما مع السرناي أين بلغ وإياكما أن أسمع في أصواتكما تقصيرا عنه قال فأصغينا فإذا الجواري والمخنثون يزمرون ويضربون\n(هذي دنانير تنساني وأذكرها ... وكيف تنسى محبا ليس ينساها)\n(أعوذ بالله من هجران جارية ... أصبحت من حبها أهذي بذكراها)\n(قد أكمل الحسن في تركيب صورتها ... فارتج أسفلها واهتز أعلاها)\n(قامت تمشى فليت الله صيرني ... ذاك التراب الذي مسته رجلاها)\n(والله والله لو كانت إذا برزت ... نفس المتيم في كفيه ألقاها)\nما زلنا نشق حلوقنا مع السرناي ونتبعه حذرا من أن نخرج عن طبقته أو نقصر عنه إلى الغداة ومحمد يجول في الكرح ما يسأمه يدنو إلينا مرة في جولانه ويتباعد مرة وتحول الجواري بيننا وبينه حتى أصبحنا\n(ألا طرقت أسماء لا حين مطرق ... وأنى إذا حلت بنجران نلتقي)\n(بوج وما بالي بوج وبالها ... ومن يلق يوما جدة الحب يخلق)","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":7,"spl":"الرشيد يأمر بصفعها بسبب رفضها الغناء","tags":["الحب والغزل"],"song":5,"loc":3161},
{"id":"b230-9","bab":"الجزء 18","sec":"الرشيد يأمر بصفعها بسبب رفضها الغناء","page":"ج18 ص74","text":"روضه من الطويل الشعر لخفاف بن ندبة والغناء لابن محرز خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن سريج ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق أيضا وذكر عمرو بن بانة أن فيه لحنا لمعبد ثاني ثقيل بالوسطى وفيه لعلوية خفيف رمل بالوسطى وفيه\nللقاسم بن زرزور خفيف رمل آخر صحيح في غنائه وفيه لابن مسجح ثقيل أول عن إبراهيم ويحيى المكي والهشامي وفيه لمخارق رمل بالبنصر","topic":"ذكر مقتل الزبير وخبره الزبير وعلي بن أبي طالب","topicNo":230,"sp":8,"spl":"الرشيد يأمر بصفعها بسبب رفضها الغناء","tags":[],"loc":3162},
{"id":"b231-2","bab":"الجزء 18","sec":"أخبار خفاف ونسبه — كان أحد أغربة العرب","page":"ج18 ص80 – ج18 ص81","text":"هو خفاف بن عمير بن الحارث بن الشريد بن رياح بن يقظة بن عصية بن خفاف بن امرىء القيس بن بهثة بن سليم بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر بن نزار وندبة أمه وهي أمة سوداء وكان خفاف أسود أيضا وهو شاعر من شعراء الجاهلية وفارس من فرسانهم وجعله ابن سلام في الطبقة الخامسة من الفرسان مع مالك بن نويرة ومع ابني عمه صخر ومعاوية ابني عمرو بن الشريد ومالك بن حمار الشمخي\nأخبرني أبو خليفة إجازة عن محمد بن سلام قال كان خفاف بن ندبة - وهي أمه - فارسا شجاعا شاعرا وهو أحد أغربة العرب وكان هو ومعاوية بن الحارث بن الشريد أغار على بني ذبيان يوم حوزة فلما قتلوا معاوية بن عمرو قال خفاف والله لا أريم اليوم أو أقيد به سيدهم فحمل على مالك بن حمار وهو يومئذ فارس بني فزارة وسيدهم\nفطعنه فقتله وقال\n(فإن تك خيلي قد أصيب صميمها ... فعمدا على عيني تيممت مالكا)\n(رفعت له ما جر إذ جر موته ... لأبني مجدا أو لأثأر هالكا)\n(أقول له والرمح يأطر متنه ... تأمل خفافا إنني أنا ذلكا)\nال ابن سلام وهو الذي يقول\n(يا هند يا أخت بني الصارد ... ما أنا بالباقي ولا الخالد)\n(إن أمس لا أملك شيئا فقد ... أملك أمر المنسر الحارد)\nي هذين البيتين لعبيد الله بن أبي غسان خفيف ثقيل أول بالبنصر عن الهشامي","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":0,"spl":"أخبار خفاف ونسبه — كان أحد أغربة العرب","tags":["اللهو والمزاح"],"loc":3163},
{"id":"b231-3","bab":"الجزء 18","sec":"خفاف والعباس بن مرداس","page":"ج18 ص82","text":"أخبرني عمي عن عبد الله بن أبي سعد عن أحمد بن عمر عن عمر بن خالد بن عاصم بن عمرو بن عثمان بن عفان رضي الله عنه عن الحجاج السلمي قال كان بدء ما كان بين خفاف بن ندبة والعباس بن مرداس أن خفافا\nكان في ملأ من بني سليم فقال لهم إن عباس بن مرداس يريد أن يبلغ فينا ما بلغ عباس بن أنس ويأبى ذلك عليه خصال قعدن به فقال له فتى من رهط العباس وما تلك الخصال يا خفاف\nقال اتقاؤه بخيله عند الموت واستهانته بسبايا العرب وقتله الأسرى ومكالبته للصعاليك على الأسلاب ولقد طالت حياته حتى تمنينا موته فانطلق الفتى إلى العباس فأخبره الخبر فقال العباس يا بن أخي إن لم أكن كالأصم في فضله فلست كخفاف في جهله وقد مضى الأصم بما في أمس وخلفني بما في غد فلما أمسى تغنى وقال\n(خفاف ما تزال تجر ذيلا ... الى الأمر المفارق للرشاد)\n(إذا ما عاينتك بنو سليم ... ثنيت لهم بداهية نآد)\n(وقد علم المعاشر من سليم ... بأني فيهم حسن الأيادي)\n(فأورد يا خفاف فقد بليتم ... بني عوف بحية بطن وادي)\nال ثم أصبح فأتى خفافا وهو في ملأ من بني سليم فقال قد\nبلغني مقالتك يا خفاف والله لا أشتم عرضك ولا أسب أباك وأمك ولكني رام سوادك بما فيك وإنك لتعلم أني أحمي المصاف وأتكرم على السلب وأطلق الأسير وأصون السبية وأما زعمك أني أتقي بخيلي الموت فهات من قومك رجلا اتقيت به وأما استهانتي بسبايا العرب فإني أحذو القوم في نسائهم بفعالهم في نسائنا وأما قتلى الأسرى فإني قتلت الزبيدي بخالك إذ عجزت عن ثأرك وأما مكالبتي الصعاليك على الأسلاب فوالله ما أتيت على مسلوب قط إلا لمت سالبه وأما تمنيك موتي فإن مت قبلك فأغن غنائي وإن سليما لتعلم أني أخف عليهم مؤونة وأثقل على عدوهم وطأة منك وإنك لتعلم أني أبحث حمى بني زبيد وكسرت قرني الحارث وأطفأت جمرة خثعم وقلدت بني كنانة قلائد العار ثم انصرف فقال خفاف أبياتا لم يحفظ الشيخ منها إلا قوله\n(ولم تقتل أسيرك من زبيد ... بخالي بل غدرت بمستقاد)\n(فزندك في سليم شر زند ... وزادك في سليم شر زاد)\nأجابه العباس بقوله\n(ألا من مبلغ عني خفافا ... فإني لا أحاشي من خفاف)\n(نكحت وليدة ورضعت أخرى ... وكان أبوك تحمله قطاف)\n(فلست لحاصن إن لم نزرها ... تثير النقع من ظهر النعاف)\n(سراعا قد طواها الأين دهما ... وكمتا لونها كالورس صاف)\nال ثم كف العباس وخفاف حتى أتى ابن عم للعباس يكنى أبا عمرو بن بدر وكان غائبا فقال يا عباس ما نقول فيك إلا خيرا إلا وهو\nباطل قال وكيف ذلك ويحك قال أخبرني عنك أكل الذي أقررت به من خفاف في نفيه أباك وتهجينه عرضك ليأس من نصر قومك أو ضعف من نفسك قال لا ولا واحدة منهما ولكني أحببت البقيا قال فاسمع ما قلته قال هات فأنشأ يقول\n(أرى العباس ينفض مذرويه ... دهين الرأس تقليه النساء)\n(وقد أزرى بوالده خفاف ... ويحسب مثله الداء العياء)\n(فلا تهد السباب إلى خفاف ... فإن السب تحسنه الإماء)\n(ولا تكذب وأهد إليه حربا ... معجلة فإن الحرب داء)\n(أذل الله شركما قبيلا ... ولا سقت له رسما سماء)\nال العباس قد آذنت خفافا بحرب ثم أصبحا فالتقيا بقومهما فاقتتلوا قتالا شديدا يوما إلى الليل وكان الفضل للعباس على خفاف فركب إليه مالك بن عوف ودريد بن الصمة الجشمي في وجوه هوازن فقام دريد خطيبا فقال يا معشر بني سليم إنه أعجلني إليكم صدر واد ورأى جامع وقد ركب صاحباكم شر مطية وأوضعا إلى أصعب غاية فالآن قبل أن يندم الغالب ويذل المغلوب ثم جلس فقال مالك بن عوف فقال يا معشر بني سليم إنكم نزلتم منزلا بعدت فيه هوازن وشبعت منكم فيه بنو تميم وصالت عليكم فيه بكر بن وائل ونالت فيه منكم بنو كنانة فانزعوا وفيكم\nبقية قبل أن تلقوا عدوكم بقرن أعضب وكف جذماء قال فلما أمسينا تغنى دريد بن الصمة فقال\n(سليم بن منصور ألما تخبروا ... بما كان من حربي كليب وداحس)\n(وما كان في حرب اليحابر من دم ... مباح وجدع مؤلم للمعاطس)\n(وما كان في حربي سليم وقبلهم ... بحرب بعاث من هلاك الفوارس)\n(تسافهت الأحلام فيها جهالة ... وأضرم فيها كل رطب ويابس)\n(فكفوا خفافا عن سفاهة رأيه ... وصاحبه العباس قبل الدهارس)\n(وإلا فأنتم مثل من كان قبلكم ... ومن يعقل الأمثال غير الأكايس)\nقال مالك بن عوف النصري\n(سليم بن منصور دعوا الحرب إنما ... هي الهلك للأقصين أو للأقارب)","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":1,"spl":"خفاف والعباس بن مرداس","tags":[],"loc":3164},
{"id":"b231-4","bab":"الجزء 18","sec":"خفاف والعباس بن مرداس","page":"ج18 ص82","text":"(ألم تعلموا ما كان في حرب وائل ... وحرب مراد أو لؤي بن غالب)\n(تفرقت الأحياء منهم لجاجة ... وهم بين مغلوب ذليل وغالب)\n(فما لسليم ناصر من هوازن ... ولو نصروا لم تغن نصرة غائب)\nال ثم أصبحنا فاجتمعت بنو سليم وجاء العباس وخفاف فقال لهما دريد بن الصمة ولمن حضر من قومهما يا هؤلاء إن أولكم كان خير أول وكل حي سلف خير من الخلف فكفوا صاحبيكم عن لجاج الحرب\nوتهاجي الشعر قال فاستحيا العباس فقال فإنا نكف عن الحرب ونتهادى الشعر قال فقال دريد فإن كنتما لا بد فاعلين فاذكرا ما شئتما ودعا الشتم فإن الشتم طريق الحرب فانصرفا على ذلك فقال العباس بن مرداس\n(فأبلغ لديك بني مالك ... فأنتم بأنبائنا أخبر)\n(فأما النخيل فليست لنا ... نخيل تسقى ولا تؤبر)\n(ولكن جمعا كجذل الحكاك ... فيه المقنع والحسر)\n(مغاوير تحمل أبطالنا ... الى الموت ساهمة ضمر)\n(وأعددت للحرب خيفانة ... تديم الجراء إذا تخطر)\n(صنيعا كقارورة الزعفران ... مما تصان ولا تؤثر)\nيقال صبيغا قال فأجابه خفاف فقال\n(أعباس إن استعار القصيد ... في غير معشره منكر)\n(علام تناول ما لا تنال ... فتقطع نفسك أو تخسر)\n(فإن الرهان إذا ما أريد ... فصاحبه الشامخ المخطر)\n(تخاوص لم تستطع عدة ... كأنك من بغضنا أعور)\n(فقصرك مأثورة إن بقيت ... أصحو بها لك أو أسكر)\n(لساني وسيفي معا فانظرن ... الى تلك أيهما تبدر)\nقال فلما طال الأمر بينهما من الحرب والتهاجي قال عباس إني والله ما رأيت لخفاف مثلا إلا شبام بني زبيد فإنه كان يلقى من ابن عمه ثروان بن مرة من الشتم والأذى ما ألقى من خفاف فلما لج في شتمه تركه وما هو فيه فقال\n(وهبت لثروان بن مرة نفسه ... وقد أمكنتني من ذؤابته يدي)\n(وأحمل ما في اليوم من سوء رأيه ... رجاء التي يأتي بها الله في غد)\nقال خفاف إني والله ما وجدت لعباس مثلا إلا ثروان بني زبيد فإنه كان يلقى من شبام ما ألقى من العباس من الأذى فقال ثروان\n(رأيت شباما لا يزال يعيبني ... فلله ما بالي وبال شبام)\n(فقصرك مني ضربة مازنية ... بكف فتى في القوم غير كهام)\n(فتقصر عني يا شبام بن مالك ... وما عض سيفي شاتمي بحرام)\nفقال عباس جزاك الله عني يا خفاف شرا فقد كنت أخف بني سليم من دمائها ظهرا وأخمصها بطنا فأصبحت العرب تعيرني بما كنت أعيب عليها من الاحتمال وأكل الأموال وصرت ثقيل الظهر من دمائها منفضج البطن من أموالها وأنشأ يقول\n(ألم تر أني تركت الحروب ... وأني ندمت على ما مضى)\n(ندامة زار على نفسه ... لتلك التي عارها يتقى)\n(فلم أوقد الحرب حتى رمى ... خفاف بأسهمه من رمى)\n(فإن تعطف القوم أحلامهم ... فيرجع من ودهم ما نأى)\n(فلست فقيرا إلى حربهم ... وما بي عن سلمهم من غنى)\nقال خفاف\n(أعباس إما كرهت الحروب ... فقد ذقت من عضها ما كفى)\n(أألقحت حربا لها شدة ... زمانا تسعرها باللظى)\n(فلما ترقيت في غيها ... دحضت وزل بك المرتقى)\n(فلا زلت تبكي على زلة ... وماذا يرد عليك البكا)\n(فإن كنت أخطأت في حربنا ... فلسنا نقيلك هذا الخطا)\n(وإن كنت تطمع في سلمنا ... فزاول ثبيرا وركني حرا)\nخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني مسعود بن عيسى العبدي عن يحيى بن عبد الله بن الفضل الفزاري وكان علامة بأمر قيس\nقال كان خفاف بن ندبة في جماعة من قومه فقال إن عباس بن مرداس ليريد أن يبلغ فينا مبلغ عباس بن أنس وتأبى عليه خصال قعدن به عن ذلك فقال فتى من رهط عباس ما تلك الخصال يا خفاف فقال اتقاؤه بخيله عند الموت ومكالبة الصعاليك على الأسلاب وقتله الأسرى واستهانته بسبايا العرب وايم الله لقد طالت حياته حتى تمنينا موته فانطلق الفتى إلى العباس فحدثه الحديث فقال العباس يابن أخي إلا أكن كالأصم في فضله فلست كخفاف في جهله وقد مضى الأصم بما في أمس وخلفني لما في غد فلما أمسى تغنى فقال\n(خفاف أما تزال تجر ذيلا ... الى الأمر المقرب للفساد)\n(وقد علم المعاشر من سليم ... بأني فيهم حسن الأيادي)\n(وأني يوم جمع بني عطيف ... حملت بحالك وهج المرادي)\n(وأني لا أعير في سليم ... برد الخيل سالمة الهوادي)\n(وأني في ملمة كل يوم ... أقي صحبي وفي خيلي تعادي)\n(ولم أسلب بحمد الله كبشا ... سلاحا بين مختلف الصعاد)\n(ولم أحلل لمحصنة نطاقا ... ولم أر عتقها إلا مرادي)","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":2,"spl":"خفاف والعباس بن مرداس","tags":[],"loc":3165},
{"id":"b231-5","bab":"الجزء 18","sec":"خفاف والعباس بن مرداس","page":"ج18 ص82","text":"(فأورد يا خفاف فقد منيتم ... بني عوف بحية بطن وادي)\nفلما أصبح أتى خفافا وهو في ملأ من قومه فقال قد بلغني مقالك يا خفاف وايم الله إنك لتعلم أني أحمي المصاف وأكره السلب وأطلق الأسير وأصون السبية فأما زعمك أني أتقي بخيلي عند الموت فهات لي من قومك رجلا اتقيت به وأما قتلي الأسرى فإني قتلت الزبيدي بخالك وأما سلبي الأسير فوالله ما أتيت على مسلوب قط إلا لمت سالبه وأما استهانتي بالسبايا فإني أحذو القوم في سباياهم فعالهم في سبايانا وأما تمنيك موتي فإن مت قبلك فأغن غنائي ثم انصرف فقال خفاف مجيبا للعباس عن قوله\n(لعمر أبيك يا عباس إني ... لمنقطع الرشاء من الأعادي)\n(وإني قد تعاتبني سليم ... على جر الذيول إلى الفساد)\n(أكل الدهر لا تنفك تجري ... إلى الأمر المفارق للسداد)\n(إذا ما عاينتك بنو سليم ... تبيت لهم بداهية نآد)\n(فزندك في سليم شر زند ... وزادك في المعاشر شر زاد)\n(ألا لله درك من رئيس ... إذا عاديت فانظر من تعادي)\n(جريت مبرزا وجريت تكبو ... على تعب فهل لك من معاد)\n(ولم تقتل أسيرك من زبيد ... بخالي بل غدرت بمستقاد)\nومستقاد الزبيدي وإن رهط خفاف لاموه وقالوا اكفف عن الرجل فقال كيف أكف عن رجل يريد أن يترنا أمرنا بغير فضل وقال رهط العباس له أيها الرجل اكفف فقال قولا جميلا وقال العباس عند ذلك\n(هل تعرف الطلل القديم كأنه ... وشم بأسفل ذي الخيام مرجع)\n(بقيت معارفه على مر الصبا ... بعد الجميع كأنه قد يمرع)\n(دار التي صادت فؤادك بعدما ... شمل المفارق منك شيب أروع)\n(وزعمت أنك لا تراح إلى الصبا ... وعلتك منه شبيبة لا ترجع)\n(يا أيها المرء السفيه ألا ترى ... أني أضر إذا هويت وأنفع)\n(وأعيش ما قدر الإله على القلى ... وأعف نفسي عن مطامع تطمع)\n(كرما على الخطر اليسير ولا ترى ... نفسي إلى الأمر الدني تطلع)\n(وأرد ذا الضغن اللئيم برأيه ... حتى يموت وليس فينا مطمع)\n(لله درك لا تمن مماتنا ... فالموت ويحك قصرنا والمرجع)\n(لو كان يهلك من تمنى موته ... حلت عليك دهية لا ترقع)\n(ومكثت في دار الهوان موطأ ... بالذل ليس لداركم من يمنع)\nقال خفاف مجيبا له\n(عجبت أمامة إذ رأتني شاحبا ... خلق القميص وأنض رأسي أصلع)\n(وتنفست صعدا فقلت لها اقصري ... إني امرؤ فيما أضر وأنفع)\n(مهلا أبا أنس فإني للذي ... خلى عليك دهية لا ترفع)\n(وضربت أم شؤون رأسك ضربة ... فاستك منها في اللقاء المسمع)\n(نعلى حذو نعالها ولربما ... أحذو العدا ولكل عاد مصرع)\n(لا تفخرن فإن عودي نبعة ... أعيت أبا كرب وعودك خروع)\n(ولقد أقود إلى العدو مقلصا ... سلس القياد له تليل أتلع)\n(نهد المراكل والدسيع يزينه ... شنج النسا وأباجل لا تقطع)\n(وعلي سابغة كأن قتيرها ... حدق الجنادب ليس فيها مطمع)\n(زغف مضاعفة تخير سردها ... ذو فائش وبنو المرار وتبع)\n(في فتية بيض الوجوه كأنهم ... أسد على لحم ببيشة طلع)\n(لا ينكلون إذا لقوا أعداءهم ... إن الحمام هو الطريق المهيع)\nان خفاف قد كف عن العباس حتى أتاه غلام من قومه فقال أبي العباس إلا جرأة عليك وعيبا لك فغضب خفاف ثم قال ما يدعوه إلى ذلك فوالله إن أباه لرابط السهم وإن أمه لخفية الشخص ولئن طلب مسعاي ليعلمن أنه قصير الخطوة أجذم الكف وما ذنبنا إليه إلا أنا استنقذنا أباه من عصي بني حزام وكافحنا دونه يوم بني فراس ونصرنا أباه على حرب بن أمية وقال خفاف في ذلك\n(لن يترك الدهر عباس تقحمه ... حتى يذوق وبال البغي عباس)\n(أمسكت عن رميه حولا ومقتله ... باد لتعذرني في حربه الناس)\n(عمدا أجر له ثوبي لأخدعه ... عن رأيه ورجائي عنده ياس)\n(فالآن إذ صرحت منه حقيقته ... ظلما فليس بشتمي شاتمي باس)\n(أجد يوما بقولي كل مبتدىء ... كما يجد بكف الجازر الفاس)\n(تأبى سليم إذا عدت مساعيها ... أن يحرز السبق عباس ومرداس)\n(أودى أبو عامر عباس معترفا ... أنا إذا ما سليم حصلت راس)","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":3,"spl":"خفاف والعباس بن مرداس","tags":["اللهو والمزاح","الموت"],"loc":3166},
{"id":"b231-6","bab":"الجزء 18","sec":"خفاف والعباس بن مرداس","page":"ج18 ص82","text":"بلغ العباس أمر خفاف فأتاه فالتقيا عند أسماء بن عروة بن الصلت بن حزام بن عبد الله بن حازم بن الصلت وكان مأمونا في بني سليم فقال العباس قد بلغني قولك يا خفاف ولعمري لا أشتم أباك ولا أمك ولكني رام سوادك بما فيك والله ما كنت إلى ذمك بالهيمان ولا إلى لحمك بالقرم وإن سليما لتعلم أني أبحت حمي بني زبيد وأطفأت جمرة خثعم وكسرت قرني بني الحارث بن كعب وقلدت بني كنانة قلائد العار وإني يا خفاف لأخف منك على بني سليم مؤونة وأثقل منك على عدوهم وطأة وقال مجيبا له\n(إني رأيت خفافا ليس يهنئه ... شيء سوى شتم عباس بن مرداس)\n(مهلا خفاف فإن الحق معضبة ... والحمق ليس له في الناس من آسي)\n(سائل سليما إذا ما غارة لحقت ... منها فوارس حشد غير أنكاس)\n(من خثعم وزبيد أو بني قطن ... أو رهط فروة دهرا أو شحا الناس)\n(ينبوا من الفارس الحامي حقيقته ... إذا أتوك بحام غير عباس)\n(لا يحسب الناس قول الحق معترفا ... فانظر خفاف فما في الحق من باس)\n(من زار خيل بني سعد مسومة ... يهدي لأولها لأي بن شماس)\n(يوم اعترضت أبا بدر بجائفة ... تعوي بعرق من الأحشاء قلاس)\n(أدعى الرئيس إذا ما حربكم كشفت ... عن ساقها لكم والأمر للراس)\n(حتى إذا انكشفت عنكم عمايتها ... أنشأت تضرب أخماسا لأسداس)\nوسعى أهل الفساد إلى خفاف فقالوا إن عباسا قد فضحك فقال خفاف\n(ألا أيها المهدي لي الشتم ظالما ... ولست بأهل حين أذكر للشتم)\n(أبى الشتم أني سيد وابن سادة ... مطاعين في الهيجا مطاعيم للحم)\n(هم منحوا نصرا أباك وطاعنوا ... وذلك إذ ترمى ذليلا ولا ترمي)\n(كمستلحم في ظلمة الليل بعد ما ... رأى الموت صرفا والسيوف بها تهمي)\n(أدب على أنماط بيضاء حرة ... مقابلة الجدين ماجدة العم)\n(وأنت لحنفاء اليدين لو انها ... تباع لما جاءت بزند ولا سهم)\n(وإني على ما كان أول أول ... عليه كذاك القرم ينتج للقرم)\n(وأكرم نفسي عن أمور دنيئة ... أصون بها عرضي واسو بها كلمي)\n(وأصفح عمن لو أشاء جزيته ... فيمنعني رشدي ويدركني حلمي)\n(وأغفر للمولى وإن ذو عظيمة ... على البغي منها لا يضيق بها حزمي)\n(فهذي فعالي ما بقيت وإنني ... لموص به عقبي إذا كنت في رجمي)\nقال له قومه لو كان أول قولك كآخره يا خفاف لأطفأت النائرة وأذهبت سخائم النمائم فقال العباس مجيبا له\n(ألا أيها المهدي لي الشتم ظالما ... تبين إذا راميت هضبة من ترمي)\n(أبي الذم عرضي إن عرضي طاهر ... وإني أبي من أباة ذوي غشم)\n(وإني من القوم الذين دماؤهم ... شفاء لطلاب التراث من الوغم)\nوقال أيضا\n(إن تلقني تلق ليثا في عرينته ... من أسد خفان في أرساغه فدع)\n(لا يبرح الدهر صيدا قد تقنصه ... من الرجال على أشداقه القمع)\nكان العباس وخفاف قد هما بالصلح وكرهت بنو سليم الحرب فجاء غوي من رهط العباس فقال للعباس إن خفافا قد أنحى عليك وعلى والديك فغضب العباس ثم قال قد والله هجاني فكان أعظم ما عابني به أصغر عيب فيه ثم هجا والدي فما ضرهما ولا نفعه ثم برزت له فأخفى شخصه واتقاني بغيره ولو شئت لشتمت أباه وثلبت عرضه ولكني وإياه كما قال شبام بن زبيد لابن عم له يقال له ثروان بن مرة كان أشبه الناس بخفاف\n(وهبت لثروان بن مرة نفسه ... وقد أمكنتني من ذؤابته يدي)\n(وأحمل ما في اليوم من سوء رأيه ... رجاء الذي يأتي به الله في غد)\n(ولست عليه في السفاه كنفسه ... ولست إذا لم أهجه بموعد)\nوقال\n(أراني كلما قاربت قومي ... نأوا عني وقطعهم شديد)\n(سئمت عتابهم فصفحت عنهم ... وقلت لعل حلمهم يعود)\n(وعل الله يمكن من خفاف ... فأسقيه التي عنها يحيد)\n(بما اكتسبت يداه وجر فينا ... من الشحنا التي ليست تبيد)\n(وأنى لي يؤدبني خفاف ... وعوف والقلوب لها وقود)\n(وإني لا أزال أريد خيرا ... وعند الله من نعم مزيد)\n(فضاقت بي صدورهم وغصت ... حلوق ما يبض لها وريد)\n(متى أبعد فشرهم قريب ... وإن أقرب فودهم بعيد)\n(أقول لهم وقد لهجوا بشتمي ... ترقوا يا بني عوف وزيدوا)\n(فما شتمي بنافع حي عوف ... أينقصني الهبوط أم الصعود)\n(أتجعلني سراة بني سليم ... ككلب لا يهر ولا يصيد)\n(كأني لم أقد خيلا عتاقا ... شوازب ما لها في الأرض عود)\n(أجشمها مهامه طامسات ... كأن رمال صحصحها قعود)\n(عليها من سراة بني سليم ... فوارس نجدة في الحرب صيد)\n(فأوطي من تريد بني سليم ... بكلكلها ومن ليست تريد)","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":4,"spl":"خفاف والعباس بن مرداس","tags":["الهجاء"],"loc":3167},
{"id":"b231-7","bab":"الجزء 18","sec":"خفاف والعباس بن مرداس","page":"ج18 ص82","text":"فلما بلغ خفافا قول العباس قال والله ما عبت العباس إلا بما فيه وإني لسليم العود صحيح الأديم ولقد أدنيت سوادي من سواده فلم أحجم ولا نكصت عنه وإني وإياه كما قال ثروان لشبام بني زبيد وكان يلقى منه ما لقي من العباس قال\n(رأيت شباما لا يزال يعيبني ... فلله ما بالي وبال شبام)\n(فقصرك مني ضربة مازنية ... بكف امرىء في الحرب غير كهام)\n(من اليوم أو من شيعه بمهند ... خصوم لهامات الرجال حسام)\n(فتقصر عني يا شبام بن مالك ... وما عض سيفي شاتمي بحرام)\nقال خفاف\n(أرى العباس ينقص كل يوم ... ويزعم أنه جهلا يزيد)\n(فلو نقضت عزائمه وزادت ... سلامته لكان كما يريد)\n(ولكن المعالم أفسدته ... وخلق في عشيرته زهيد)\n(فعباس بن مرداس بن عمرو ... وكذب المرء أقبح ما يفيد)\n(حلفت برب مكة والمصلى ... وأشياخ محلقة تنود)\n(بأنك من مودتنا قريب ... وأنت من الذي تهوى بعيد)\n(فأبشر أن بقيت بيوم سوء ... يشيب له من الخوف الوليد)\n(كيومك إذ خرجت تفوق ركضا ... وطار القلب وانتفخ الوريد)\n(فدع قول السفاهة لا تقله ... فقد طال التهدد والوعيد)\n(رأينا من نحاربه شقيا ... ومن ذا في بني عوف سعيد)\nوقال خفاف أيضا\n(أعباس إنا وما بيننا ... كصدع الزجاجة لا يجبر)\n(فلست بكفء لأعراضنا ... وأنت بشتمكنا أجدر)\n(ولسنا بأهل لما قلتم ... ونحن بشتمكم أعذر)\n(أراك بصيرا بتلك التي ... تريد وعن غيرها أعور)\n(فقصرك مني رقيق الذباب ... عضب كريهته مبتر)\n(وأزرق في رأس خطية ... إذا هز أكعبها تخطر)\n(يلوح السنان على متنها ... كنار على مرقب تسعر)\n(وزغف دلاص حباها العزيز ... توارثها قبله حمير)\n(فتلك وجرداء خيفانة ... إذا زجر الخيل لا تزجر)\n(إذا ألقت الخيل أذيالها ... فأنت على جريها أقدر)\n(متى يبلل الماء أعطافها ... تبذ الجياد وما تبهر)\n(أنهنه بالسوط من غربها ... وأقدمها حيث لا ينكر)\n(وأرحضها غير مذمومة ... بلباتها العلق الأحمر)\n(أقول وقد شك أقرابها ... غدرت ومثلي لا يغدر)\n(وأشهدها غمرات الحروب ... فسيان تسلم أو تعقر)\nوقال العباس\n(خفاف ألم تر ما بيننا ... يزيد استعارا إذا يسعر)\n(ألم تر أنا نهين التلاد ... للسائلين وما نعذر)\n(لأنا نكلف فوق التي ... يكلفها الناس لو تخبر)\n(لنا شيم غير مجهولة ... توارثها الأكبر الأكبر)\n(وخيل تكدس بالدارعين ... تنحر في الروع أو تعقر)\n(عليها فوارس مخبورة ... كجن مساكنها عبقر)\n(ورجراجة مثل لون النجوم ... لا العزل فيها ولا الحسر)\n(وبيض سوابغ مسرودة ... مواريث ما أورثت حمير)\n(فقد يعلم الحي عند الصياح ... بأن العقيلة بي تستر)\n(وقد يعلم الحي عند الرهان ... أني أنا الشامخ المخطر)\n(وقد يعلم الحي عند السؤال ... أني أجود وأستمطر)\n(فأنى تعيرني بالفخار ... فها أنا هذا هو المنكر)\n\n(ألا لا أبالي بعد ريا أوافقت ... نوانا نوى الجيران أم لم توافق)\n(هجان المحيا حرة الوجه سربلت ... من الحسن سربالا عتيق البنائق)\nلشعر لجبهاء الأشجعي والغناء لإسحاق رمل بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"أخبار خفاف ونسبه","topicNo":231,"sp":5,"spl":"خفاف والعباس بن مرداس","tags":["الهجاء"],"song":1,"loc":3168},
{"id":"b232-2","bab":"الجزء 18","sec":"أخبار جبهاء ونسبه — جبهاء والفرزدق","page":"ج18 ص99 – ج18 ص100","text":"جبهاء لقب غلب عليه يقال جبهاء وجبيهاء جميعا واسمه يزيد بن عبيد ويقال يزيد بن حميمة بن عبيد بن عقيلة بن قيس بن رويبة بن سحيم بن عبيد بن هلال بن زبيد بن بكر بن أشجع شاعر بدوي من مخاليف الحجاز نشأ وتوفي في أيام بني أمية وليس ممن انتجع الخلفاء بشعره ومدحهم فاشتهر وهو مقل وليس من معدودي الفحول ومن الناس من يروي هذه الأبيات لأبي ربيس الثعلبي وليس ذلك بصحيح وهي في شعر جبهاء موجودة\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي وأخبرني علي بن سليمان الأخفش قال حدثنا أبو الحسن الأحول عن الطوسي عن أبي عمرو الشيباني قال قدم جبيهاء الأشجعي البصرة بجلوبة له يريد بيعها فلقيه الفرزدق بالمربد فقال ممن الرجل قال من أشجع قال أتعرف شاعرا منكم يقال له جبهاء أو جبيهاء قال نعم قال أفتروي قوله\n(أمن الجميع بذي البقاع ربوع ... هاجت فؤادك والربوع تروع)\nال نعم قال فأنشدنيها فأنشده قوله منها\n(من بعد ما نكرت وغير آيها ... قطر ومسبلة الدموع خريع)\n(يا صاحبي ألا ارفعا لي آية ... تشفي الصداع فيذهل المرفوع)\n(ألواح ناجية كأن تليلها ... جذع تطيف به الرقاة منيع)\nتى أتى على آخرها فقال الفرزدق فأقسم بالله إنك لجبهاء أو إنك لشيطانه قال الأخفش في خبره عن أصحابه الخريع الذاهبة العقل شبه السحابة بها لأنها لا تتمالك من المطر\nأخبرني الحسن بن علي قال حدثنا أحمد بن عبيد المكتب قال حدثني علي بن الصباح عن ابن الكلبي قال قدم جبيهاء الأشجعي المدينة بجلوبة له فبينا هو يبيعها والفرزدق يومئذ بالمدينة إذ مر به فقال له ممن أنت قال من أشجع قال أتعرف شاعرا منكم يقال له جبهاء أو جبيهاء قال نعم قال أتروي قصيدته\n(ألا لا أبالي بعد ريا أوافقت ... نوانا نوى الجيران أم لم توافق)\nال نعم قال أنشدنيها فأنشده إياها فقال الفرزدق أقسم بالله إنك لجبيهاء أو إنك لشيطانه","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":0,"spl":"أخبار جبهاء ونسبه — جبهاء والفرزدق — جبهاء يهاجر إلى المدينة ويجاور بني تميم","tags":["المديح"],"loc":3169},
{"id":"b232-3","bab":"الجزء 18","sec":"جبهاء يهاجر إلى المدينة ويجاور بني تميم","page":"ج18 ص101","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي عن سليمان بن عياش قال\nقالت زوجة جبهاء الأشجعي له لو هاجرت بنا إلى المدينة وبعت إبلك وافترضت في العطاء كان خيرا لك قال أفعل فأقبل بها وبإبله حتى إذا كان بحرة واقم من شرقي المدينة شرعها بحوض واقم ليسقيها فحنت ناقة منها ثم نزعت وتبعتها الإبل وطلبها ففاتته فقال لزوجته هذه إبل لا تعقل تحن إلى أوطانها ونحن أحق بالحنين منها أنت طالق إن لم ترجعي وفعل الله بك وفعل وردها وقال\n(قالت أنيسة دع بلادك والتمس ... دارا بطيبة ربة الآطام)\n(تكتب عيالك في العطاء وتفترض ... وكذاك يفعل حازم الأقوام)\n(فهممت ثم ذكرت ليل لقاحنا ... بلوى عنيزة أو بقف بشام)\n(إذ هن عن حسبي مذاود كلما ... نزل الظلام بعصبة أغتام)\n(إن المدينة لا مدينة فالزمي ... حقف السناد وقبة الأرجام)\n(يحلب لك اللبن الغريض وينتزع ... بالعيس من يمن إليك وشام)\n(وتجاوري النفر الذين بنبلهم ... أرمي العدو إذا نهضت أرامي)\n(الباذلين إذا طلبت تلادهم ... والمانعي ظهري من الغرام)\nخبرني محمد بن خلف وكيع قال حدثني أحمد بن زهير قال حدثني مصعب قال جاور جبهاء الأشجعي في بني تيم بطن من أشجع فاستمنحه مولى لهم عنزا فمنحه إياها فأمسكها دهرا فلما طال على جبهاء ألا يردها قال جبهاء\n(أمولى بني تيم ألست مؤديا ... منيحتنا فيما ترد المنائح)\n(لها شعر صاف وجيد مقلص ... وجسم زخاري وضرس مجالح)\nأرسل إليه التيمي يقول\n(بلى سنؤديها إليك ذميمة ... للتنكحها إن أعوزتك المناكح)\nعمد به جبهاء فنزل وقال\n(لو كنت شيخا من سواة نكحتها ... نكاح يسار عنزه وهي سارح)\nال وهم يعيرون بنكاح العنز","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":0,"spl":"أخبار جبهاء ونسبه — جبهاء والفرزدق — جبهاء يهاجر إلى المدينة ويجاور بني تميم","tags":["السفر والحج","الرواية والكتابة"],"loc":3170},
{"id":"b232-4","bab":"الجزء 18","sec":"جبهاء وموسى بن زياد","page":"ج18 ص103","text":"أخبرني وكيع قال حدثني أبو أيوب المديني عن مصعب قال استطرق جبهاء الأشجعي موسى بن زياد الأشجعي كبشا فوعده ثم مطله فقال جبهاء\n(واعدني الكبش موسى ثم أخلفني ... وما لمثلي تعتل الأكاذيب)\n(يا ليت كبشك يا موسى يصادفه ... بين الكراع وبين الوجنة الذيب)\n(أمسى بذي الغصر أو أمسى بذي سلم ... فقحمته إلى أبياتك اللوب)\n(فجاء والحي أيقاظ فطاف بهم ... طوفين ثم أقرته الأحاليب)\n(فبات ينظره حران منطويا ... كأنه طالب للوتر مكروب)\n(وقام يشتد حتى نال غرته ... طاوي الحشا ذرب الأنياب مذبوب)\n(بغفلة من زريق فاستمر به ... ودونه آكم الحقف الغرابيب)\n(سل عنه أرخمة بيضا وأغربة ... سودا لهن حنى أطمى سلاهيب)\n(يردين ردي العذارى حول دمنته ... كما يطوف على الحوض المعاقيب)\n(فجاء يحمل قرنيه ويندبه ... فكل حي إذا ما مات مندوب)\n\n(ولها ولا ذنب لها ... حب كأطراف الرماح)\n(في القلب يجرح والحشا ... فالقلب مجروح النواحي)\nلشعر لوالبة بن الحباب والغناء ليزيد رمل بالوسطى عن الهشامي وعمرو وفيه لسبك الزامر لحن عن ابن خرداذبة","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":1,"spl":"جبهاء وموسى بن زياد — أخبار والبة بن الحباب","tags":["الحب والغزل"],"song":1,"loc":3171},
{"id":"b232-5","bab":"الجزء 18","sec":"أخبار والبة بن الحباب","page":"ج18 ص105","text":"والبة بن الحباب أسدي صليبة كوفي شاعر من شعراء الدولة العباسية يكنى أبا أسامة وهو أستاذ أبي نواس وكان ظريفا شاعرا غزلا وصافا للشراب والغلمان المرد وشعره في غير ذلك مقارب ليس بالجيد وقد هاجى بشارا وأبا العتاهية فلم يصنع شيئا وفضحاه فعاد إلى الكوفة كالهارب وخمل ذكره بعد\nأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق قال حدثني أبي وأخبرني محمد بن القاسم الأنباري والحسن بن علي الأدمي جميعا عن القاسم بن محمد الأنباري\nقال حدثنا يعقوب بن عمر قال حدثني أحمد بن سلمان قال حدثني أبو عدنان السلمي الشاعر قال قال المهدي لعمارة بن حمزة من أرق الناس شعرا قال\nوالبة بن الحباب الأسدي وهو الذي يقول\n(ولها ولا ذنب لها ... حب كأطراف الرماح)\n(في القلب يقدح والحشا ... فالقلب مجروح النواحي)\nال صدقت والله قال فما يمنعك عن منادمته يا أمير المؤمنين قال يمنعني قوله\n(قلت لساقينا على خلوة ... أدن كذا رأسك من راسي)\n(ونم على صدرك لي ساعة ... إني امرؤ أنكح جلاسي)\nأفتريد أن نكون من جلاسه على هذه الشريطة أخبرني الحسين بن القاسم الكوكبي إجازة حدثني عبد الله بن مسلم بن قتيبة ووجدته في بعض الكتب عن ابن قتيبة وروايته أتم فجمعتهما قال حدثني الدعجلي غلام أبي نواس قال أنشدت يوما بين يدي أبي نواس قوله\n(يا شقيق النفس من حكم ... نمت عن ليلي ولم أنم)\nكان قد سكر فقال أخبرك بشيء على أن تكتمه قلت نعم قال أتدري من المعني بقوله يا شقيق النفس من حكم قلت لا قال أنا والله المعني بذلك والشعر لوالبة بن الحباب قال وما علم بذلك غيرك وأنت أعلم فما حدثت بهذا حتى مات قال وقال الجاحظ كان والبة بن الحباب ومطيع بن إياس ومنقذ بن عبد الرحمن الهلالي وحفص بن أبي وردة وابن المقفع ويونس بن أبي فروة وحماد عجرد وعلي بن الخليل وحماد بن أبي ليلى الراوية وابن\nالزبرقان وعمارة بن حمزة ويزيد بن الفيض وجميل بن محفوظ وبشار المرعث وأبان اللاحقي ندماء يجتمعون على الشراب وقول الشعر ولا يكادون يفترقون ويهجو بعضهم بعضا هزلا وعمدا وكلهم متهم في دينه","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":1,"spl":"جبهاء وموسى بن زياد — أخبار والبة بن الحباب","tags":["الحب والغزل"],"loc":3172},
{"id":"b232-6","bab":"الجزء 18","sec":"والبة وأبو العتاهية يتهاجيان","page":"ج18 ص107","text":"أخبرني محمد بن يحيى الصولي قال حدثنا محمد بن موسى بن حماد قال حدثني محمد بن القاسم قال حدثني إسحاق بن إبراهيم بن محمد السالمي الكوفي التيمي\nقال حدثني محمد بن عمر الجرجاني قال رأيت أبا العتاهية جاء إلى أبي فقال له إن والبة بن الحباب قد هجاني ومن أنا منه أنا جرار مسكين وجعل يرفع من والبة ويضع من نفسه فأحب أن تكلمه أن يمسك عني\nقال فكلم أبي والبة وعرفه أن أبا العتاهية جاءه وسأله ذلك فلم يقبل وجعل يشتم أبا العتاهية فتركه ثم جاء أبو العتاهية فسأله عما عمل في حاجته فأخبره بما رد عليه والبة فقال لأبي لي الآن إليك حاجة قال وما هي قال لا تكلمني في أمره قال قلت له هذا أول ما يجب لك قال فقال أبو العتاهية يهجوه\n(أوالب أنت في العرب ... كمثل الشيص في الرطب)\n(هلم إلى الموالي الصيد ... في سعة وفي رحب)\n(فأنت بنا لعمر الله ... أشبه منك بالعرب)\n(غضبت عليك ثم رأيت ... وجهك فانجلى غضبي)\n(لما ذكرتني من لون أجدادي ... ولون أبي)\n(فقل ما شئت أقبله ... وإن أطنبت في الكذب)\n(لقد أخبرت عنك وعن ... أبيك الخالص العربي)\n(فقال العارفون به ... مصاص غير مؤتشب)\n(أتانا من بلاد الروم ... معتجرا على قتب)\n(خفيف الحاذ كالصمصام ... أطلس غير ذي نشب)\n(أوالب ما دهاك وأنت ... في الأعراب ذو نسب)\n(أراك ولدت بالمريخ ... يابن سبائك الذهب)\n(فجئت أقيشر الخدين ... أزرق عارم الذنب)\n(لقد أخطأت في شتمي ... فخبرني ألم أصب)\nقال في والبة أيضا\n(نطقت بنو أسد ولم تجهر ... وتكلمت خفيا ولم تظهر)\n(وأما ورب البيت لو نطقت ... لتركتها وصباحها أغبر)\n(أيروم شتمي منهم رجل ... في وجهه عبر لمن فكر)\n(وابن الحباب صليبة زعموا ... ومن المحال صليبة أشقر)\n(ما بال من آباؤه عرب الألوان ... يحسب من بني قيصر)\n(أترون أهل البدو قد مسخوا ... شقرا أما هذا من المنكر)\nال وأول هذه القصيدة\n(صرح بما قد قلته واجهر ... لابن الحباب وقل ولا تحصر)\n(ما لي رأيت أباك أسواد غربيب ... القذال كأنه زرزر)\n(وكأن وجهك حمرة رئة ... وكأن رأسك طائر أصفر)\nال وبلغ الشعر والبة فجاء إلى أبي فقال قد كلمتني في أبي العتاهية وقد رغبت في الصلح قال له أبي هيهات إنه قد أكد علي إن لم تقبل ما طلب أن أخلي بينك وبينه وقد فعلت فقال له والبة فما الرأي عندك فإنه فضحني قال تنحدر إلى الكوفة فركب زورقا ومضى من بغداد إلى الكوفة وأجود ما قاله والبة في أبي العتاهية قوله\n(كان فينا يكنى أبا إسحاق ... وبها الركب سار في الآفاق)\n(فتكنى معتوهنا بعتاه ... يا لها كنية أتت باتفاق)\n(خلق الله لحية لك لا تنفك ... معقودة لدى الحلاق)\nله فيه وهو ضعيف سخيف من شعره\n(قل لابن بائعة القصار ... وابن الدوارق والجرار)\n(تهوى عتيبة ظاهرا ... وهواك في أير الحمار)\n(تهجو مواليك الألى ... فكوك من ذل الإسار)","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":2,"spl":"والبة وأبو العتاهية يتهاجيان","tags":["الحب والغزل","الهجاء"],"loc":3173},
{"id":"b232-7","bab":"الجزء 18","sec":"والبة وعلي بن ثابت","page":"ج18 ص109","text":"أخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني ابن أبي فنن قال كان والبة بن الحباب خليلا لعلي بن ثابت وصديقا ودودا وفيه يقول\n(حي بها والبة المصطفى ... حي كريما وابن حر هجان)\n(وقاسما نفسي فدت قاسما ... من حدث الموت وريب الزمان)\nال ولما مات والبة رثاه فقال\n(بكت البرية قاطبه ... جزعا لمصرع والبه)\n(قامت لموت أبي أسامة ... في الرفاق النادبه)\nال وكان والبة أستاذ أبي نواس وعنه أخذ ومنه اقتبس قال وكان والبة قد قصد أبا بجير الأسدي وهو يتولى للمنصور الأهواز فمدحه وأقام عنده فألفى أبا نواس هناك وهو أمرد فصحبه وكان حسن الوجه فلم يزل معه فيقال إنه كشف ثوبه ليلة فرأى حمرة أليتيه وبياضهما فقبلهما فضرط عليه أبو نواس فقال له لم فعلت هذا ويلك\nقال لئلا يضيع قول القائل ما جزاء من يقبل الاست إلا ضرطة أخبرني محمد بن العباس اليزيدي قال حدثني عمي الفضل قال حدثني أبو سلهب الشاعر\nقال كان والبة بن الحباب صديقي وكان ماجنا طبعا خفيف الروح خبيث الدين وكنا ذات يوم نشرب بغمى فانتبه يوما من سكره فقال لي يا أبا سلهب اسمع ثم أنشدني قال\n(شربت وفاتك مثلي جموح ... بغمى بالكؤوس وبالبواطي)\n(يعاطيني الزجاجة أريحي ... رخيم الدل بورك من معاطي)\n(أقول له على طرب ألطني ... ولو بمؤاجر علج نباطي)\n(فما خير الشراب بغير فسق ... يتابع بالزناء وباللواط)\n(جعلت الحج في غمى وبنا ... وفي قطربل أبدا رباطي)\n(فقل للخمس آخر ملتقانا ... إذا ما كان ذاك على الصراط)\nعني الصلوات قال وحدثني أنه كان ليلة نائما وأبو نواس غلامه إلى جانبه نائم إذ أتاه آت في منامه فقال له أتدري من هذا النائم إلى جانبك قال لا قال هذا أشعر منك وأشعر من الجن والإنس أما والله لأفتنن بشعره الثقلين ولأغرين به أهل المشرق والمغرب قال فعلمت أنه إبليس فقلت له فما عندك قال عصيت ربي في سجدة فأهلكني ولو أمرني أن أسجد له ألفا لسجدت","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":3,"spl":"والبة وعلي بن ثابت — حكم الوادي يغني شعره","tags":["الحب والغزل","الهجاء"],"loc":3174},
{"id":"b232-8","bab":"الجزء 18","sec":"حكم الوادي يغني شعره","page":"ج18 ص111","text":"أخبرني الحسين بن يحيى قال حدثنا حماد بن إسحاق قال قرأت على أبي عن أبيه أن حكم الوادي أخبره أنه دخل على\nمحمد بن العباس يوما بالبصرة وهو يتململ خمارا وبيده كأس وهو يجتهد في شربها فلا يطيقه وندماؤه بين يديه في أيديهم أقداحهم وكان يوم نيروز فقال لي يا حكم غنني فإن أطربتني فلك كل ما أهدي إلي اليوم قال وبين يديه من الهدايا أمر عظيم فاندفعت أغني في شعر والبة بن الحباب\n(قد قابلتنا الكؤوس ... ودابرتنا النحوس)\n(واليوم هرمزروز ... قد عظمته المجوس)\n(لم نخطه في حساب ... وذاك مما نسوس)\nطرب واستعاد فأعدته ثلاث مرات فشمرت قدحه واستمر في شربه وأمر بحمل كل ما كان بين يديه إلي فكانت قيمته ثلاثين ألف درهم لحن حكم الوادي في هذا الشعر هزج بالبنصر عن الهشامي وإبراهيم وغيرهما\n(لقد زاد الحياة إلي حبا ... بناتي إنهن من الضعاف)\n(مخافة أن يذقن البؤس بعدي ... وأن يشربن رنقا بعد صاف)\n(وأن يعرين إن كسي الجواري ... فيبدي الصر عن هزل عجاف)\n(ولولاهن قد سومت مهري ... وفي الرحمان للضعفاء كاف)\nلشعر لعمران بن حطان فيما ذكر أبو عمرو الشيباني وذكر المدائني أنه لعيسى الحبطي وكلاهما من الشراة والغناء لمحمد بن الأشعث الكوفي خفيف رمل بالوسطى من رواية عمرو بن بانة","topic":"أخبار جبهاء ونسبه","topicNo":232,"sp":3,"spl":"والبة وعلي بن ثابت — حكم الوادي يغني شعره","tags":["الحب والغزل"],"song":2,"loc":3175},
{"id":"b233-1","bab":"الجزء 18","sec":"أخبار عمران بن حطان ونسبه","page":"ج18 ص114","text":"هو عمران بن حطان بن ظبيان بن لوذان بن عمرو بن الحارث بن سدوس بن شيبان بن ذهل بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل وقال ابن الكلبي هو عمران بن حطان بن ظبيان بن معاوية بن الحارث ابن سدوس ويكنى أبا شهاب شاعر فصيح من شعراء الشراة ودعاتهم والمقدمين في مذهبهم وكان من القعدة لأن عمره طال فضعف عن الحرب وحضورها فاقتصر على الدعوة والتحريض بلسانه وكان قبل أن يفتن بالشراة مشتهرا بطلب العلم والحديث ثم بلي بذلك المذهب فضل وهلك لعنه الله وقد أدرك صدرا من الصحابة وروي عنهم\nوروى عنه أصحاب الحديث فما روي عنه ما أخبرنا به محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا أبو الوليد الطيالسي عن أبي عمرو بن العلاء عن أبي صالح بن سرح اليشكري عن عمران بن حطان\nقال كنت عند عائشة فتذاكروا القضاة فقالت قال رسول الله ( يؤتى بالقاضي العدل فلا يزال به ما يرى من شدة الحساب حتى يتمنى أنه لم يقض بين اثنين في تمرة\nوكان أصله من البصرة فلما اشتهر بهذا المذهب طلبه الحجاج فهرب إلى الشام فطلبه عبد الملك فهرب إلى عمان وكان يتنقل إلى أن مات في تواريه أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا منيع بن أحمد السدوسي عن أبيه عن جده قال كان عمران بن حطان من أهل السنة والعلم فتزوج امرأة من الشراة من عشيرته وقال أردها عن مذهبها إلى الحق فأضلته وذهبت به","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":0,"spl":"أخبار عمران بن حطان ونسبه","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3176},
{"id":"b233-2","bab":"الجزء 18","sec":"الحجاج يطلبه فيهرب إلى الشام","page":"ج18 ص115","text":"وأخبرني بخبره في هربه من الحجاج عمر بن عبد الله بن جميل العتكي ومحمد بن العباس اليزيدي قالا حدثنا الرياشي قال حدثنا الحكم بن مروان\nقال حدثنا الهيثم بن عدي قال طلب الحجاج عمران بن حطان السدوسي وكان من قعدة الخوارج فكتب فيه إلى عماله وإلى عبد الملك وأخبرني بهذا الخبر أيضا الحسن بن علي الخفاف ومحمد بن عمران الصيرفي قالا حدثنا العنزي قال حدثنا محمد بن عبد الرحمن بن عبد الصمد الدارع قال حدثنا أبو عبيدة معمر بن المثنى عن أخيه يزيد بن\nالمثنى أن عمران بن حطان خرج هاربا من الحجاج فطلبه وكتب فيه إلى عماله وإلى عبد الملك فهرب ولم يزل يتنقل في أحياء العرب وقال في ذلك\n(حللنا في بني كعب بن عمرو ... وفي رعل وعامر عوثبان)\n(وفي جرم وفي عمرو بن مر ... وفي زيد وحي بني الغدان)\nم لحق بالشام فنزل بروح بن زنباع الجذامي فقال له روح ممن أنت قال من الأزد أزد السراة قال وكان روح يسمر عند عبد الملك فقال له ليلة يا أمير المؤمنين إن في أضيافنا رجلا ما سمعت منك حديثا قط إلا\nحدثني به وزاد فيما ليس عندي قال ممن هو قال من الأزد قال إني لأسمعك تصف صفة عمران بن حطان لأنني سمعتك تذكر لغة نزارية وصلاة وزهدا ورواية وحفظا وهذه صفته فقال روح وما أنا وعمران ثم دعا بكتاب الحجاج فإذا فيه أما بعد فإن رجلا من أهل الشقاق والنفاق قد كان أفسد علي أهل العراق وحببهم بالشراية ثم إني طلبته فلما ضاق عليه عملي تحول إلى الشام فهو ينتقل في مدائنها وهو رجل ضرب طوال أفوه أروق\nقال قال روح هذه والله صفة الرجل الذي عندي ثم أنشد عبد الملك يوما قول عمران يمدح عبد الرحمن بن ملجم - لعنه الله - بقتله علي بن أبي طالب\nصلوات الله عليه\n(يا ضربة من كريم ما أراد بها ... إلا ليبلغ من ذي العرش رضوانا)\n(إني لأفكر فيه ثم أحسبه ... أوفى البرية عند الله ميزانا)\nم قال عبد الملك من يعرف منكم قائلها فسكت القوم جميعا فقال لروح سل ضيفك عن قائلها قال نعم أنا سائله وما أراه يخفي على ضيفي ولا سألته عن شيء قط فلم أجده إلا عالما به وراح روح إلى أضيافه فقال إن أمير المؤمنين سألنا الذي يقول\n(يا ضربة من كريم ما أراد بها ... . . . . . . . . . . . . . . .)\nم ذكر الشعر وسألهم عن قائله فلم يكن عند أحد علم فقال له عمران هذا قول عمران بن حطان في ابن ملجم قاتل علي بن أبي طالب قال فهل فيها غير هذين البيتين تفيدنيه قال نعم\n(لله در المرادي الذي سفكت ... كفاه مهجة شر الخلق إنسانا)\n(أمسى عشية غشاه بضربته ... مما جناه من الآثام عريانا)\nصلوات الله على أمير المؤمنين ولعن الله عمران بن حطان وابن ملجم - فغدا روح فأخبر عبد الملك فقال من أخبرك بذلك فقال ضيفي قال أظنه عمران بن حطان فأعلمه أني قد أمرتك أن تأتيني به\nقال أفعل فراح روح إلى أضيافه فأقبل على عمران فقال له إني ذكرتك لعبد الملك فأمرني أن آتيه بك قال كنت أحب ذلك منك وما منعني من ذكره إلا الحياء منك وأنا متبعك فانطلق فدخل روح على عبد الملك فقال له أين أجد صاحبك فقال\nقال لي أنا متبعك قال أظنك والله سترجع فلا تجده فلما رجع روح إلى منزله إذا عمران قد مضى وإذا هو قد خلف رقعة في كوة عند فراشه وإذا فيها يقول\n(يا روح كم من أخي مثوى نزلت به ... قد ظن ظنك من لخم وغسان)\n(حتى إذا خفته فارقت منزله ... من بعد ما قيل عمران بن حطان)\n(قد كنت ضيفك حولا لا تروعني ... فيه الطوارق من إنس ولا جان)\n(حتى أردت بي العظمى فأوحشني ... ما أوحش الناس من خوف ابن مروان)\n(فاعذر أخاك ابن زنباع فإن له ... في الحادثات هنات ذات ألوان)\n(يوما يمان إذا لاقيت ذا يمن ... وإن لقيت معديا فعدناني)\n(لو كنت مستغفرا يوما لطاغية ... كنت المقدم في سري وإعلاني)\n(لكن أبت ذاك آيات مطهرة ... عند التلاوة في طه وعمران)","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":1,"spl":"الحجاج يطلبه فيهرب إلى الشام","tags":["المديح"],"loc":3177},
{"id":"b233-3","bab":"الجزء 18","sec":"عمران ينزل بزفر بن الحارث بقرقيسيا","page":"ج18 ص118","text":"قال ثم أتى عمران بن حطان الجزيرة فنزل بزفر بن الحارث الكلابي بقرقيسيا فجعل شباب بني عامر يتعجبون من صلاته وطولها وانتسب لزفر أوزاعيا فقدم على زفر رجل من أهل الشام قد كان رأى عمران بن حطان بالشام عند روح بن زنباع فصافحه وسلم عليه فقال زفر للشامي أتعرفه قال نعم هذا شيخ من الأزد فقال له زفر أزدي مرة وأوزاعي أخرى إن كنت خائفا آمناك وإن كنت عائلا أغنيناك فقال إن الله هو المغني وخرج من عنده وهو يقول\n(إن التي أصبحت يعيا بها زفر ... أعيت عياء على روح بن زنباع)\n(أمسي يسائلني حولا لأخبره ... والناس من بين مخدوع وخداع)\n(حتى إذا انجذمت مني حبائله ... كف السؤال ولم يولع بإهلاعي)\n(فاكفف كما كف روح إنني رجل ... إما صريح وإما فقعة القاع)\n(أما الصلاة فإني غير تاركها ... كل امرىء للذي يعنى به ساعي)\n(فاكفف لسانك عن هزي ومسألتي ... ماذا تريد إلى شيخ لأوزاع)\n(أكرم بروح بن زنباع وأسرته ... قوما دعا أوليهم للعلا داعي)\n(جاورتهم سنة فيما دعوت به ... عرضي صحيح ونومي غير تهجاع)\n(فاعمل فإنك منعي بحاذثة ... حسب اللبيب بهذا الشيب من ناعي)","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":2,"spl":"عمران ينزل بزفر بن الحارث بقرقيسيا — وصوله إلى روذميسان ووفاته بها","tags":["الهجاء"],"loc":3178},
{"id":"b233-4","bab":"الجزء 18","sec":"وصوله إلى روذميسان ووفاته بها","page":"ج18 ص119","text":"ثم خرج فنزل بعمان بقوم يكثرون ذكر أبي بلال مرداس بن أدية ويثنون عليه ويذكرون فضله فأظهر فضله ويسر أمره عندهم وبلغ الحجاج مكانه فطلبه فهرب فنزل في روذميسان - طسوج من طساسيج السواد إلى جانب الكوفة - فلم يزل به حتى مات وقد كان نازلا هناك على رجل من الأزد فقال في ذلك\n(نزلت بحمد الله في خير أسرة ... أسر بما فيهم من الإنس والخفر)\n(نزلت بقوم يجمع الله شملهم ... وما لهم عود سوى المجد يعتصر)\n(ومن الأزد إن الأزد أكرم أسرة ... يمانية قربوا إذا نسب البشر)\nال اليزيدي الإنس بالكسر الاستئناس وقال الرياشي أراد قربوا\nفخفف قال\n(وأصبحت فيهم آمنا لا كمعشر ... بدوني فقالوا من ربيعة أو مضر)\n(أو الحي قحطان وتلك سفاهة ... كما قال لي روح وصاحبه زفر)\n(وما منهم إلا يسر بنسبة ... تقربني منهم وإن كان ذا نفر)\n(فنحن بنو الإسلام والله واحد ... وأولى عباد الله بالله من شكر)\nخبرنا اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي عن المعتمر بن سليمان قال كان عمران بن حطان رجلا من اهل السنة فقدم عليه غلام من عمان كأنه نصل فقلبه عن مذهبه في مجلس واحد\nأخبرني اليزيدي قال حدثنا الرياشي قال حدثنا مسدد بن مسرهد قال حدثنا بشر بن المفضل عن سلمة بن علقمة عن محمد بن سيرين وأخبرني الحسن بن علي\nقال حدثنا الحسن بن عليل العنزي قال حدثنا عمرو بن علي القلاس وعباس العنبري ومحمد بن عبد الله المخزومي قالوا حدثنا عبد الرحمن بن مهدي عن بشر بن المفضل عن سلمة بن علقمة عن محمد بن سيرين\nقال تزوج عمران بن حطان امرأة من الخوارج فقيل له فيها فقال أردها عن مذهبها فذهبت هي به نسخت عن بعض الكتب حدثنا المدائني عن جويرية قال كتب عيسى الحبطي إلى رجل منهم يقال له أبو خالد كان تخلف عن الخروج مع قطري أو غيره منهم\n(أبا خالد انفر فلست بخالد ... وما ترك الفرقان عذرا لقاعد)\n(أتزعم أنا الخارجون على الهدى ... وأنت مقيم بين لص وجاحد)\nكتب إليه ما منعني عن الخروج إلا بناتي والحدب عليهن حين سمعت عمران بن حطان يقول\n(لقد زاد الحياة إلي حبا ... بناتي إنهن من الضعاف)\n(ولولا ذاك قد سومت مهري ... وفي الرحمن للضعفاء كاف)\nال فجلس عيسى يقرأ الأبيات ويبكي ويقول صدق أخي إن في ذلك لعذرا له وإن في الرحمن للضعفاء كافيا","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":2,"spl":"عمران ينزل بزفر بن الحارث بقرقيسيا — وصوله إلى روذميسان ووفاته بها","tags":["الحب والغزل"],"loc":3179},
{"id":"b233-5","bab":"الجزء 18","sec":"الأخطل يقول عمران أشعر الشعراء","page":"ج18 ص121","text":"وقال هارون أخذت من خط أبي عدنان أخبرني أبو ثروان الخارجي قال سمعت أشياخ الحي يقولون اجتمعت الشعراء عند عبد الملك بن مروان فقال لهم أبقي أحد أشعر منهم قالوا لا فقال الأخطل كذبوا يا أمير المؤمنين قد بقي من هو أشعر منهم\nقال ومن هو قال عمران بن حطان قال وكيف صار أشعر منهم قال لأنه قال وهو صادق ففاقهم فكيف لو كذب كما كذبوا أخبرنا الحسن بن علي قال حدثنا ابن مهرويه عن ابن أبي سعد عن أحمد بن محمد بن علي بن حمزة الخراساني عن محمد بن يعقوب بن عبد الوهاب عن يحيى بن عباد بن عبد الله بن الزبير عن أبي الأسود محمد بن عبد الرحمن القارئ عن الزهري عن أبيه أن غزالة الحرورية لما دخلت على الحجاج هي وشبيب الكوفة\nتحصن منها وأغلق عليه قصره فكتب إليه عمران بن حطان وقد كان الحجاج لج في طلبه قال\n(أسد علي وفي الحروب نعامة ... ربداء تجفل من صفير الصافر)\n(هلا برزت إلى غزالة في الوغى ... بل كان قلبك في جناحي طائر)\n(صدعت غزالة قلبه بفوارس ... تركت مدابره كأمس الدابر)\nثم لحق بالشام فنزل على روح بن زنباع أخبرنا محمد بن العباس اليزيدي قال حدثنا محمد بن خالد أبو حرب قال حدثنا محمد بن عباد المهلبي قال\nحدثنا جرير بن حازم قال كان عمران بن حطان أشد الناس خصومة للحرورية حتى لقيه أعرابي حروري فخاصمه فصار عمران حروريا ورجع عن رأيه قال جرير بن حازم كان الفرزدق يقول لقد أحسن بنا ابن حطان حيث لم يأخذ فيما أخذنا فيه ولو أخذ فيما أخذنا فيه لأسقطنا يعني لجودة شعره نسخت من كتاب ابن سعد\nقال أخبرني الحسن بن عليل العنزي قال أخبرني أحمد بن عبد الله بن سويد بن منجوف السدوسي قال أخبرني أحمد بن مؤرج عن أبيه قال حدثني به تميم بن سوادة وهو ابن أخت مؤرج\nقال حدثني أبو العوام السدوسي قال كان مالك المذموم رجلا من بني عامر بن ذهل وكان من الخوارج وكان الحجاج يطلبه قال أبو العوام فدخلت عليه يوما وهو في تواريه فأنشدني يقول\n(ألم يان لي يا قلب أن أترك الصبا ... وأن أزجر النفس اللجوج عن الهوى)\n(وما عذر من يعمى وقد شاب رأسه ... ويبصر أبواب الضلالة والهدى)\n(ولو قسم الذنب الذي قد أصبته ... على الناس خاف الناس كلهم الردى)\n(فإن جن ليل كنت بالليل نائما ... وأصبح بطال العشيات والضحى)\nال فلما فرغ من إنشادها قال سيغلبني عليها صاحبكم يعني عمران بن حطان فكان كذلك لما شاعت رواها الناس لعمران وكان لا يقول أحد من الشعراء شعرا إلا نسب إليه لشهرته إلا من كان مثله في الشهرة مثل قطري وعمرو القنا وذويهما قال ثم هرب إلى اليمامة من الحجاج فنزل بحجر فأتاه آل حكام الحنفيون فقال\n(طيروني من البلاد وقالوا ... مالك النصف من بني حكام)\n(ناق سيري قد جد حقا بنا السير ... وكوني جوالة في الزمام)\n(فمتى تعلقي يد الملك الأسود ... تستيقني بألا تضامي)\n(قد أراني ولي من الحاكم النصف ... بحد السنان أو بالحسام)\nال والملك الأسود إبراهيم بن عربي والي اليمامة لعبد الملك وكان ابن حكام على شرطته قال\n(ومنينا بطمطم حبشي ... حالك الوجنتين من آل حام)\n(لا يبالي إذا تضلع خمرا ... أبحل زماك أم بحرام)\nال العنزي فأخبرني محمد بن إدريس بن سليمان بن أبي حفصة عن أبيه قال كان مالك المذموم من أحسن الناس قراءة للقرآن فقرأ ذات ليلة فسمعت قراءته امرأة من آل حكام فرمت بنفسها من فوق سطح كانت عليه\nفسمع الصوت أهلها فأتوه فضربوه ضربات فاستعدى عليهم إبراهيم بن عربي وكان عبد الله بن حكام على شرطته فلم يعده عليهم فهجاه بالأبيات الماضية وهجاه بقصيدته التي أولها\n(دار سلمى بالجزع ذي الآطام ... خبرينا سقيت صوب الغمام)\nهي طويلة ينسبونها أيضا إلى عمران بن حطان","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":3,"spl":"الأخطل يقول عمران أشعر الشعراء","tags":["الحب والغزل"],"loc":3180},
{"id":"b233-6","bab":"الجزء 18","sec":"الفرزدق يعترف بتفوقه","page":"ج18 ص124","text":"أخبرني أحمد بن الحسين الأصبهاني ابن عمي قال حدثني أبو جعفر بن رستم الطبري النحوي قال حدثنا أبو عثمان المازني قال حدثنا عمرو بن مرة قال مر عمران بن حطان على الفرزدق وهو ينشد والناس حوله فوقف عليه ثم قال\n(أيها المادح العباد ليعطى ... إن لله ما بأيدي العباد)\n(فاسأل الله ما طلبت إليهم ... وارج فضل المقسم العواد)\n(لا تقل في الجواد ما ليس فيه ... وتسمي البخيل باسم الجواد)\nقال الفرزدق لولا أن الله عز و جل شغل عنا هذا برأيه للقينا منه شرا وقال هارون بن الزيات أخبرني عبد الرحمن بن موسى الرقي قال حدثنا أحمد بن محمد بن حميد بن سليمان بن حفص بن عبد الله بن أبي جهم بن حذيفة بن غانم العدوي قال حدثنا يزيد بن مرة عن أبي عبيدة معمر بن المثنى عن عيسى بن يزيد بن بكر المدني قال\nاجتمع عند مسلمة بن عبد الملك ناس من سماره فيهم عبد الله بن عبد الأعلى الشاعر فقال مسلمة أي بيت قالته العرب أوعظ وأحكم فقال له عبد الله قوله\n(صبا ما صبا حتى علا الشيب رأسه ... فلما علاه قال للباطل أبعد)\nقال مسلمة إنه والله ما وعظني شعر قط كما وعظني شعر ابن حطان حيث يقول\n(فيوشك يوم أن يقارن ليلة ... يسوقان حتفا راح نحوك أو غدا)\nقال بعض من حضر والله لقد سمعته أجل الموت ثم أفناه وما صنع هذا غيره فقال مسلمة وكيف ذاك قال قال\n(لا يعجز الموت شيء دون خالقه ... والموت فان إذا ما ناله الأجل)\n(وكل كرب أمام الموت متضع ... للموت والموت فيما بعده جلل)\nبكى مسملة حتى اخضلت لحيته ثم قال رددهما علي فرددهما عليه حتى حفظهما أخبرني الحسن بن علي قال حدثنا الحسن بن عليل العنزي قال حدثنا منيع بن أحمد بن مؤرج السدوسي عن ابيه عن جده قال تزوج عمران بن حطان حمزة بنت عمه ليردها عن مذهب الشراية فذهبت به إلى رأيهم فجعل يقول فيها الشعر فمما قال فيها\n(يا حمز إني على ما كان من خلقي ... مثن بخلات صدق كلها فيك)\n(الله يعلم أني لم أقل كذبا ... فيما علمت وأني لا أزكيك)\nخبرني الحسن قال حدثنا محمد بن موسى وحدثني بعض أصحابنا عن العمري عن الهيثم بن عدي أن امرأة عمران بن حطان قالت له ألم تزعم أنك لا تكذب في شعرك قال بلى قالت أفرأيت قولك\n(وكذاك مجزأة بن ثور ... كان أشجع من أسامه)\nأيكون رجل أشجع من الأسد قال نعم إن مجزأة بن ثور فتح مدينة كذا والأسد لا يقدر على فتح مدينة\n(نديمي قد خف الشراب ولم أجد ... له سورة في عظم رأسي ولا جلدي)\n(نديمي هذي غبهم فاشربا بها ... ولا خير في شرب يكون على صرد)\nلشعر لعمارة بن الوليد بن المغيرة المخزومي والغناء لابن سريج خفيف ثقيل","topic":"أخبار عمران بن حطان ونسبه","topicNo":233,"sp":4,"spl":"الفرزدق يعترف بتفوقه","tags":[],"song":1,"loc":3181},
{"id":"b234-1","bab":"الجزء 18","sec":"أخبار عمارة بن الوليد ونسبه","page":"ج18 ص127","text":"عمارة بن الوليد بن المغيرة بن عبد الله بن مخزوم بن يقظة بن مرة بن كعب بن لؤي بن غالب وهو أحد أزواد الركب ويقال له الوحيد وكان أزواد الركب لا يمر عليهم أحد إلا قروه وأحسنوا ضيافته وزودوه ما يحتاج إليه لسفره وكان عمارة بن الوليد فخورا معنا متعرضا لكل ذي عارضة من قريش فأخبرني عمي قال حدثنا عبد الله بن شبيب قال حدثنا الزبير بن بكار عن الحزامي قال مر عمارة بن الوليد بمسافر بن عمرو فوقف عليه وهو منتش فقال\n(خلق البيض الحسان لنا ... وجياد الريط والأزر)\n(كابرا كنا أحق به ... حين صيغ الشمس والقمر)\nأجابه مسافر بن عمرو بن أمية فقال\n(أعمار بن الوليد لقد ... يذكر الشاعر من ذكره)\n(هل أخو كأس مخففها ... وموق صحبه سكره)\n(ومحييهم إذا شربوا ... ومقل فيهم هذره)\n(خلق البيض الحسان لنا ... وجياد الريط والحبره)\n(كابرا كنا أحق به ... كل حي تابع أثره)\nخبرنا عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي عن حماد الراوية أن عمارة بن الوليد خطب امرأة من قومه فقالت لا أتزوجك أو تترك الشراب والزنا\nقال أما الزنا فأتركه وأما الشراب فلا أتركه ولا أستطيع ثم اشتد وجده بها فحلف ألا يشرب فتزوجها ومكث حينا لا يشرب ثم إنه لبس ذات يوم حلته وركب ناقته وخرج يسير فمر بخمار وعنده شرب يشربون فدعوه فدخل عليهم وقد أنفدوا ما عندهم فقال للخمار أطعمهم ويلك فقال ليس عندي شيء فنحر لهم ناقته فأكلوا منها فقال اسقهم ولم يكن معهم شيء يشربون به فسقاهم ببردته ومكثوا أياما ذوات عدد ثم خرج فأتى أهله فلما رأته امرأته قالت له ألم تحلف ألا ترشب ولامته فقال\n(ولسنا بشرب أم عمرو إذا انتشوا ... ثياب الندامى عندهم كالغنائم)\n(ولكننا يا أم عمرو نديمنا ... بمنزلة الريان ليس بعائم)\n(أسرك لما صرع القوم نشوة ... أن اخرج منها سالما غير غارم)\n(خليا كأني لم أكن كنت فيهم ... وليس الخداع مرتضى في التنادم)","topic":"أخبار عمارة بن الوليد ونسبه","topicNo":234,"sp":0,"spl":"أخبار عمارة بن الوليد ونسبه","tags":["الحب والغزل","الجواري والنساء"],"loc":3182},
{"id":"b234-2","bab":"الجزء 18","sec":"عمارة وعمرو بن العاص","page":"ج18 ص128","text":"أخبرني جعفر بن قدامة قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد بن قادم مولى بني هاشم قال حدثني عمي أحمد بن جعفر عن ابن دأب قال\nقدم رجل من تجار الروم بحلة من لباس قيصر على أهل مكة فأتى بها عمارة بن الوليد بن المغيرة المخزومي فعرضها عليه بمائة حق من الإبل فاستغلاها فأتى بها عمرو بن العاص فقال له هل أتيت بها أحدا قال نعم عمارة بن الوليد فاستغلاها وقال لن تعدم لها غويا من بني سهم قال قد أخذتها فاشتراها بمائة حق يعني مائة بعير ثم أقبل يخطر فيها حتى أتى بني مخزوم فناداه عمارة أتبيع الحلة يا عمرو فغضب والتفت إلى عمارة فقال\n(عليك بجز رأس أبيك إنا ... كفيناك المسهمة الرقاقا)\n(زووها عنكم وغلت عليكم ... وأعطينا بها مائة حقاقا)\n(وقلتم لا نطيق ثياب سهم ... وكل سوف يلبس ما أطاقا)\nال فغضب عمارة وقال يا عمرو ما هذا التهور إنك لست بعتبة بن ربيعة ولا بأبي سفيان بن حرب ولا الوليد بن المغيرة ولا سهيل بن عمر ولا أبي بن خلف فقال عمرو إلا أكن بعضهم فإن كل واحد منهم خير ما فيه في من عتبه حلمه ومن أبي سفيان رأيه ومن سهيل جوده ومن أبي بن خلف نجدته وأما الوليد فوالله ما أحب أن في كل ما فيه من خير وشر ولكنك والله مالك عقل الوليد ولا بأس الحارث بن هشام وخالد بن الوليد ولا لسان أبي الحكم يعني أبا جهل وانصر فأمر عمارة بجزور فنحرت على طريق عمرو وأقبل عمرو فقال لمن هذه الجزور قيل لعمارة فقال له أطعمنا منها يا عمارة فضحك منه ثم قال\n(عليك بجزر أير أبيك إنا ... كفيناك المشاشة والعراقا)\n(ومنسبة الأطايب من قريش ... ولم تر كأسنا إلا دهاقا)\n(ونلبس في الحوادث كل زغف ... وعند الأمن أبرادا رقاقا)\nوقع الشر بينهم فقال عمرو\n(لعمر أبيك والأخبار تنمي ... لقد هيجتني يا بن الوليد)\n(فلا تعجل عمارة إن سهما ... لمخزوم بن يقظة في العديد)\n(وأورد يا عمارة إن عودي ... من اعواد الأباطح خير عود)\nفأجابه عمارة فقال\n(ألا يا عمرو هل لك في قريش ... أب مثل المغيرة والوليد)\n(وجد مثل عبد الله ينمي ... الى عمرو بن مخزوم بعود)\n(إذا ما عدت الأعواد نبعا ... فمالي في الأباطح من نديد)\n(وقد علمت سراة بني لؤي ... بأني غير مؤتشب زهيد)\n(وإني للمنابذ من قريش ... شجا في الحلق من دون الوريد)\n(أحوط ذمارهم وأكف عنهم ... وأصبر في وغى اليوم الشديد)\n(وأبذل ما يضن به رجال ... وتطمعني المروءة في المزيد)\n(وإنك من بني سهم بن عمرو ... مكان الردف من عجز القعود)\n(وكان أبوك جزارا . . وكانت ... له فأس وقدر من حديد)\nأخبرني عمي قال حدثنا الكراني عن العمري عن أبي عوانة عن عبد الملك بن عمير أن عمر بن الخطاب قسم برودا في المهاجرين قال العمري هكذا ذكر أبو عوانة وقد\nحدثني الهيثم عن أبي يعقوب الثقفي عن عبد الملك بن عمير قال أخبرني من شهد ذلك أن عبد الله بن أبي ربيعة المخزومي بعث إلى عمر بن الخطاب بحلل من اليمن فقال عمر علي بالمحمدين فأتي بمحمد بن أبي بكر ومحمد بن جعفر بن أبي طالب ومحمد بن طلحة بن عبيد الله ومحمد بن عمرو بن حزم ومحمد بن حاطب بن أبي بلتعة ومحمد بن حطاب أخي حاطب وكلهم سماه النبي محمدا فأقبلوا فاطلع محمد بن حطاب فيها فقال له عمر يا شيبة معمر - يعني عما له قتل يوم بدر - اكفف وكان زيد بن ثابت الأنصاري عنده فقال له عمر أعطهم حلة حلة فنظر إلى أفضلها وكانت أم أحدهم عنده فقال عمر ما هذا فقال هذه لفلان الذي هو ربيبه فقال عمر اردده وتمثل بقول عمارة بن الوليد\n(أسرك لما صرع القوم نشوة ... أن اخرج منها سالما غير غارم)\n(خليا كأني لم أكن فيهم ... وليس الخداع مرتضى في التنادم)\nقال أبو عوانة . . . . من تصافي التنادم ثم أمر بالبرود فغطيت بثوب ثم خلطها ثم قال ليدخل كل امرىء يده فليأخذ حلته وما قسم له\n\n(قد يجمع المال غير آكله ... ويأكل المال غير من جمعه)\n(فاقبل من الدهر ما أتاك به ... من قر عينا بعيشه نفعه)\n(لكل هم من الهموم سعه ... والصبح والمسي لا فلاح معه)\nلشعر للأضبط بن قريع والغناء لأحمد بن يحيى المكي ثقيل أول بالسبابة في مجرى البنصر من روايته وسمعناه يغني في طريقة خفيف رمل فسألت عنه ذكاء وجه الرزة فذكر أنه سمعه من محمد بن يحيى المكي في هذه الطريقة ولم يعرف صانعه ولا سأل عنه","topic":"أخبار عمارة بن الوليد ونسبه","topicNo":234,"sp":1,"spl":"عمارة وعمرو بن العاص","tags":["اللهو والمزاح"],"song":1,"loc":3183},
{"id":"b235-1","bab":"الجزء 18","sec":"أخبار الأضبط ونسبه","page":"ج18 ص133","text":"أخبرني جعفر بن قدامة قال حدثني عبد الله بن طاهر قال قال أبو محلم أخبرني ضرار بن عيينة أحد بني عبد شمس قال كان الأضبط بن قريع مفركا وكان إذا لقي في الحرب تقدم أمام الصف ثم قال\n(أنا الذي تفركه حلائله ... ألا فتى معشق أنازله)\nال فاجتمع نساؤه ذات ليلة يسمرن فتعاقدن على أن يصدقن الخبر عن فرك الأضبط فأجمعن أن ذلك لأنه بارد الكمرة فقالت لإحداهن خالتها أتعجز إحداكن إذا كانت ليلته منها أن تسخن كمرته بشيء من دهن فلما سمع قولها صاح يا آل عوف يا آل عوف فثار الناس وظنوا أنه قد أتي فقال أوصيكم بأن تسخنوا الكمرة فإنه لا حظوة لبارد الكمرة فانصرفوا يضحكون وقالوا تبا لك ألهذا دعوتنا قال أبو محلم كانت أم الأضبط عجيبة بنت دارم بن مالك بن حنظلة وخالته الطموح بنت دارم أم جشم وعبد شمس ابني كعب بن سعد فحارب بنو\nالطموح قوما من بني سعد فجعل الأضبط يدس إليهم الخيل والسلاح ولا يصرح بنصرتهم خوفا من أن يتحزب قومه حزبين معه وعليه وكان يشير عليهم بالرأي فإذا أبرمه نقضوه وخالفوا عليه وأروه مع ذلك أنهم على رأيه فقال في ذلك\n(لكل هم من الهموم سعه ... والمسي والصبح لا فلاح معه)\n(لا تحقرن الفقير علك أن ... تركع يوما والدهر قد رفعه)\n(وصل حبال البعيد إن وصل الحبل ... واقص القريب إن قطعه)\n(قد يجمع المال غير آكله ... ويأكل المال غير من جمعه)\n(ما بال من غيه مصيبك لا ... يملك شيئا من أمره وزعه)\n(حتى إذا ما انجلت غوايته ... أقبل يلحي وغيه فجعه)\n(أذود عن نفسي ويخدعني ... يا قوم من عاذري من الخدعه)\n(فأقبل من الدهر ما أتاك به ... من قر عينا بعيشه نفعه)\nخبرني الحسن بن علي قال حدثنا الخراز عن المدائني قال كان الأضبط بن قريع قد تزوج امرأة على مال ووصيفة فنشزت عليه ففارقها ولم يعطها ما كان ضمن لها فلما احتملت أنشأ يقول\n(ألم ترها بانت بغير وصيفة ... إذا ما الغواني صاحبتها الوصائف)\n(ولكنها بانت شموس بزية ... منعمة الأخلاق حدباء شارف)\n(لو أن رسول اللهو سلم واقفا ... عليها لرامت وصله وهو واقف)\nخبرنا وكيع قال حدثنا ابن أبي سعد قال\nحدثنا الجماز قال أنشدت أبا عبيدة وخلفا الأحمر شعر الأضبط وصل حبال البعيد إن وصل الحبل وأقص القريب إن قطعه فما عرفا منه إلا بيتا وعجز بيت فالبيت الذي عرفاه فاقبل من الدهر ما أتاك به والعجز\n(يا قوم من عاذري من الخدعه ... )\nالخدعة قوم من بني سعد بن زيد مناة بن تميم\n(وما أنا في أمري ولا في خصومتي ... بمهتضم حقي ولا قارع سني)\n(ولا مسلم مولاي عند جناية ... ولا خائف مولاي من شر ما أجني)\nلشعر لأعشى بني ربيعة والغناء لإبراهيم ثاني ثقيل بالوسطى عن عمرو","topic":"أخبار الأضبط ونسبه","topicNo":235,"sp":0,"spl":"أخبار الأضبط ونسبه","tags":["الحب والغزل","الجواري والنساء"],"song":1,"loc":3184,"partial":1}]);
window.__BOOK__['p09'].push([{"id":"b236-2","bab":"الجزء 18","sec":"أخبار الأعشى ونسبه — الأعشى وعبد الملك بن مروان","page":"ج18 ص135 – ج18 ص136","text":"الأعشى اسمه عبد الله بن خارجة بن حبيب بن قيس بن عمرو بن حارثة بن أبي ربيعة بن ذهل بن شيبان بن ثعلبة الحصين بن عكابة بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار شاعر إسلامي من ساكني الكوفة وكان مرواني المذهب شديد التعصب لبني أمية\nأخبرني محمد بن العباس اليزيدي قال حدثنا عمي محمد بن عبيد الله عن محمد بن حبيب وأخبرني محمد بن الحسن بن دريد عن عمه العباس بن هشام عن أبيه قالا قدم أعشى بني ربيعة على عبد الملك بن مروان فقال له عبد الملك ما الذي بقي منك قال أنا الذي أقول\n(وما أنا في أمري ولا في خصومتي ... بمهتضم حقي ولا قارع سني)\n(ولا مسلم مولاي عند جناية ... ولا خائف مولاي من شر ما أجني)\n(وإن فؤادي بين جنبي عالم ... بما أبصرت عيني وما سمعت أذني)\n(وفضلني في الشعر واللب أنني ... أقول على علم وأعرف من أعني)\n(فأصبحت إذ فضلت مروان وابنه ... على الناس قد فضلت خير أب وابن)\nفقال عبد الملك من يلومني على هذا وأمر له بعشرة آلاف درهم وعشرة تخوت ثياب وعشر فرائض من الإبل وأقطعه ألف جريب وقال له امض إلى زيد الكاتب يكتب لك بها وأجرى له على ثلاثين عيلا فأتى زيدا فقال له ائتني غدا فأتاه فجعل يردده فقال له\n(يا زيد يا فداك كل كاتب ... في الناس بين حاضر وغائب)\n(هل لك في حق عليك واجب ... في مثله يرغب كل راغب)\n(وأنت عف طيب المكاسب ... مبرأ من عيب كل عائب)\n(ولست - إن كفيتني وصاحبي ... طول غدو ورواح دائب)\n(وسدة الباب وعنف الحاجب ... - من نعمة أسديتها بخائب)\nأبطأ عليه زيد فأتى سفيان بن الأبرد الكبي فكلمه سفيان فأبطأ عليه فعاد إلى سفيان فقال له\n(عد إذ بدأت أبا يحيى فأنت لها ... ولا تكن حين هاب الناس هيابا)\n(واشفع شفاعة أنف لم يكن ذنبا ... فإن من شفعاء الناس أذنابا)\nفأتى سفيان زيدا الكاتب فلم يفارقه حتى قضى حاجته قال محمد بن حبيب دخل أعشى بني أبي ربيعة على عبد الملك وهو يتردد في الخروج لمحاربة ابن الزبير ولا يجد فقال له يا أمير المؤمنين ما لي أراك متلوما ينهضك الحزم ويقعدك العزم وتهم بالإقدام وتجنح إلى الإحجام انقد لبصيرتك وأمض رأيك وتوجه إلى عدوك فجدك مقبل\nوجده مدبر وأصحابه له ماقتون ونحن لك محبون وكلمتهم مفترقة وكلمتنا عليك مجتمعة والله ما تؤتى من ضعف جنان ولا قلة أعوان ولا يثبطك عنه ناصح ولا يحرضك عليه غاش وقد قلت في ذلك أبياتا فقال هاتها فإنك تنطق بلسان ودود وقلب ناصح فقال\n(آل الزبير من الخلافة كالتي ... عجل النتاج بحملها فأحالها)\n(أو كالضعاف من الحمولة حملت ... ما لا تطيق فضيعت أحمالها)\n(قوموا إليهم لا تناموا عنهم ... كم للغواة أطلتمو إمهالها)\n(إن الخلافة فيكم لا فيهم ... ما زلتم أركانها وثمالها)\n(أمسوا على الخيرات قفلا مغلقا ... فانهض بيمنك فافتتح أقفالها)\nضحك عبد الملك وقال صدقت يا أبا عبد الله إن أبا خبيب لقفل دون كل خير ولا نتأخر عن مناجزته إن شاء الله ونستعين الله عليه وهو حسبنا ونعم الوكيل وأمر له بصلة سنية","topic":"أخبار الأعشى ونسبه","topicNo":236,"sp":0,"spl":"أخبار الأعشى ونسبه — الأعشى وعبد الملك بن مروان","tags":["اللهو والمزاح"],"loc":3185},
{"id":"b236-3","bab":"الجزء 18","sec":"الأعشى والحجاج","page":"ج18 ص138","text":"قال ابن حبيب كان الحجاج قد جفا الأعشى واطرحه لحالة كانت عند بشر بن مروان فلما فرغ الحجاج من حرب الجماجم ذكر فتنة ابن الأشعث وجعل يوبخ أهل العراق ويؤنبهم فقال من حضر من أهل\nالبصرة إن الريب والفتنة بدآ من أهل الكوفة وهم أول من خلع الطاعة وجاهر بالمعصية فقال أهل الكوفة لا بل أهل البصرة أول من أظهر المعصية مع جرير بن هميان السدوسي إذ جاء مخالفا من السند وأكثروا من ذلك فقام أعشى بني أبي ربيعة فقال أصلح الله الأمير لا براءة من ذنب ولا ادعاء الله في عصمة لأحد من المصرين قد والله اجتهدوا جميعا في قتالك فأبى الله إلا نصرك وذلك أنهم جزعوا وصبرت وكفروا وشكرت وغفرت إذ قدرت فوسعهم عفو الله وعفوك فنجوا فلولا ذلك لبادوا وهلكوا فسر الحجاج بكلامه\nوقال له جميلا وقال تهيأ للوفادة إلى أمير المؤمنين حتى يسمع هذا منك شفاها انتهى أخبرني محمد بن خلف وكيع قال حدثني حماد بن إسحاق عن أبيه قال بلغ الحجاج أن أعشى بني أبي ربيعة رثى عبد الله بن الجارود فغضب عليه فقال يعتذر إليه\n(أبيت كأني من حذار ابن يوسف ... طريد دم ضاقت عليه المسالك)\n(ولو غير حجاج أراد ظلامتي ... حمتني من الضيم السيوف الفواتك)\n(وفتيان صدق من ربيعة قصرة ... إذا اختلفت يوم اللقاء النيازك)\n(يحامون عن أحسابهم بسيوفهم ... وأرماحهم واليوم أسود حالك)\nخبرني أبو الحسن الأسدي قال حدثني أحمد بن عبد الله بن علي بن\nسويد بن منجوف عن ابن مؤرج عن أبيه قال دخل أعشى بني أبي ربيعة على عبد الملك بن مروان فأنشده قوله\n(رأيتك أمس خير بني معد ... وأنت اليوم خير منك أمس)\n(وأنت غدا تزيد الضعف ضعفا ... كذاك تزيد سادة عبد شمس)\nقال له من أي بني أبي ربيعة أنت قال فقلت له من بني أمامة قال فإن أمامة ولد رجلين قيسا وحارثة فأحدهما نجم والآخر خمل فمن أيهما أنت قال قلت أنا من ولد حارثة وهو الذي كانت بكر بن وائل توجته قال فقام بمخصرة في يده فغمز بها في بطني ثم قال يا أخا بني أبي ربيعة هموا ولم يفعلوا فإذا حدثتني فلا تكذبني فجعلت له عهدا ألا أحدث قرشيا بكذب أبدا","topic":"أخبار الأعشى ونسبه","topicNo":236,"sp":1,"spl":"الأعشى والحجاج — الأعشى يمدح أسماء بن خارجة","tags":["السفر والحج"],"loc":3186},
{"id":"b236-4","bab":"الجزء 18","sec":"الأعشى يمدح أسماء بن خارجة","page":"ج18 ص140","text":"أخبرني عمي قال حدثنا ابن أبي سعد قال حدثني أحمد بن الهيثم السلمي قال حدثني أبو فراس محمد بن فراس عن الكلبي قال أتى أعشى بني أبي ربيعة أسماء بن خارجة فامتدحه فأعطاه وكساه فقال\n(لأسماء بن خارجة بن حصن ... على عبء النوائب والغرامه)\n(أقل تعللا يوما وبخلا ... على السؤال من كعب بن مامه)\n(ومصقلة الذي يبتاع بيعا ... ربيحا فوق ناجية بن سامه)\nال الكلبي جعل ناجية رجلا وهي امرأة لضرورة الشعر قال أبو فراس فحدثني الكلبي عن خداش قال دخل أعشى بني أبي ربيعة على سليمان بن عبد الملك وهو ولي عهد فقال\n(أتينا سليمان الأمير نزوره ... وكان امرأ يحبى ويكرم زائره)\n(إذا كنت في النجوى به متفردا ... فلا الجود مخليه ولا البخل حاضره)\n(كلا شافعي سؤاله من ضميره ... على البخل ناهيه وبالجود آمره)\nفأعطاه وأكرمه وأمر كل من كان بحضرته من قومه ومواليه بصلته فوصلوه فخرج وقد ملأ يديه\n(نأتك أمامة إلا سؤالا ... وإلا خيالا يوافي خيالا)\n(يوافي مع الليل ميعادها ... ويأبى مع الصبح إلا زيالا)\n(فذلك يبذل من ودها ... ولو شهدت لم توات النوالا)\n(فقد ريع قلبي إذ أعلنوا ... وقيل أجد الخليط احتمالا)\nالشعر لعمرو بن قميئة والغناء لحنين خفيف رمل بالوسطى من رواية احمد بن يحيى المكي وذكر الهشامي وغيره أنه من منحول يحيى إلى حنين","topic":"أخبار الأعشى ونسبه","topicNo":236,"sp":1,"spl":"الأعشى والحجاج — الأعشى يمدح أسماء بن خارجة","tags":["الجواري والنساء"],"song":1,"loc":3187},
{"id":"b237-2","bab":"الجزء 18","sec":"أخبار عمرو بن قميئة ونسبه — هروبه من عمه مرثد إلى الحيرة","page":"ج18 ص143 – ج18 ص145","text":"هو فيما ذكر أبو عمرو الشيباني عن أبي برزة عمرو بن قميئة بن ذريح بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار\nقال ابن الكلبي ليس من العرب من له ولد كل واحد منهم قبيلة مفردة قائمة بنفسها غير ثعلبة بن عكابة فإنه ولد أربعة كل واحد منهم قبيلة شيبان بن ثعلبة وهو أبو قبيلة وقيس بن ثعلبة وهو أبو قبيلة وذهل بن ثعلبة وهو أبو قبيلة وتيم الله بن ثعلبة وهو أبو قبيلة\nوكان عمرو بن قميئة من قدماء الشعراء في الجاهلية ويقال إنه أول من قال الشعر من نزار وهو أقدم من امرئ القيس ولقيه امرؤ القيس في آخر عمره فأخرجه معه إلى قيصر لما توجه إليه فمات معه في طريقه وسمته العرب عمرا الضائع لموته في غربة وفي غير أرب ولا مطلب نسخت خبره من روايتي أبي عمرو الشيباني ومؤرج\nوأخبرني ببعضه الحسن بن علي عن أبيه عن ابن أبي سعد عن ابن الكلبي فذكرت ذلك في مواضعه ونسبته إلى رواته قالوا جميعا كان عمرو بن قميئة شاعرا فحلا متقدما وكان شابا جميلا حسن الوجه مديد القامة حسن الشعر ومات أبوه وخلفه صغيرا فكفله عمه مرثد بن سعد وكانت سبابتا قدميه ووسطياهما ملتصقتين وكان عمه محبا له معجبا به رقيقا عليه\nوأخبرني عمي قال حدثنا الكراني قال حدثنا أبو عمر العمري عن لقيط وذكر مثل ذلك سائر الرواة أن مرثد بن سعد بن مالك عم عمرو بن قميئة كانت عنده امرأة ذات جمال فهويت عمرا وشغفت به ولم تظهر له ذلك فغاب مرثد لبعض أمره\nوقال لقيط في خبره مضى يضري بالقداح فبعثت امرأته إلى عمرو تدعوه على لسان عمه وقالت للرسول ائتني به من وراء البيوت ففعل فلما دخل أنكر شأنها فوقف ساعة ثم راودته عن نفسه فقال لقد جئت بأمر عظيم وما كان مثلي ليدعى لمثل هذا والله لو لم أمتنع من ذلك وفاء لأمتنعن منه خوف الدناءة والذكر القبيح الشائع عني في العرب قالت والله لتفعلن أو لأسوأنك قال إلى المساءة تدعينني ثم قام فخرج من عندها\nوخافت أن يخبر عمه بما جرى فأمرت بجفنة فكفئت على أثر عمرو فلما رجع عمه وجدها متغضبة فقال لها مالك قالت إن رجلا من قومك قريب القرابة جاء يستامني نفسي ويريد فراشك منذ خرجت قال من هو قالت أما أنا فلا أسميه ولكن قم فافتقد أثره تحت الجفنة فلما رأى الأثر عرفه\nقال مؤرج في خبره فحدثني أبو برزة وعلقمة بن سعد وغيرهما من بني قيس بن ثعلبة قالوا وكان لمرثد سيف يسمى ذا الفقار فأتى ليضربه به فهرب فأتى الحيرة فكان عند اللخميين ولم يكن يقوى على بني مرثد لكثرتهم\nوقال لعمرو بن هند أنا القوم اطردوني فقال له ما فعلوا إلا وقد أجرمت وأنا أفحص عن أمرك فإن كنت مجرما رددتك إلى قومك فغضب وهم بهجائه وهجاء مرثد ثم أعرض عن ذلك ومدح عمه واعتذر إليه انتهى وأما أبو عمرو فإنه قال لما سمع مرثد بذلك هجر عمرا وأعرض عنه ولم يعاقبه لموضعه من قلبه فقال عمرو ويعتذر إلى عمه\n(خليلي لا تستعجلا أن تزودا ... وأن تجمعا شملي وتنتظرا غدا)\n(فما لبثي يوما بسائق مغنم ... ولا سرعتي يوما بسائقة الردى)\n(وإن تنظراني اليوم أقض لبانة ... وتستوجبا منا علي وتحمدا)\n(لعمرك ما نفس بجد رشيدة ... تؤامرني سوءا لأصرم مرثدا)\n(وإن ظهرت مني قوارص جمة ... وأفرع من لومي مرارا وأصعدا)\n(على غير جرم أن أكون جنيته ... سوى قول باغ كادني فتجهدا)\n(لعمري لنعم المرء تدعو بخيله ... إذا ما المنادي في المقامة نددا)\n(عظيم رماد القدر لا متعبس ... ولا مؤيس منها إذا هو أوقدا)\n(وإن صرحت كحل وهبت عرية ... من الريح لم تترك من المال مرفدا)\n(صبرت على وطء الموالي وخطبهم ... إذا ضن ذو القربى عليهم وأخمدا)\nعني أخمد ناره بخلا وروى أجمدا المجمد البخيل\n(ولم يحم فرج الحي إلا محافظ ... كريم المحيا ماجد غير أجردا)\nالأجرد الجعد اليد البخيل","topic":"أخبار عمرو بن قميئة ونسبه","topicNo":237,"sp":0,"spl":"أخبار عمرو بن قميئة ونسبه — هروبه من عمه مرثد إلى الحيرة","tags":["الهجاء","المديح"],"loc":3188},
{"id":"b237-3","bab":"الجزء 18","sec":"حماد الراوية يرى أنه أشعر الناس","page":"ج18 ص146","text":"أخبرني محمد بن العباس اليزيدي قال حدثني عمي الفضل بن إسحاق عن الهيثم بن عدي قال سأل رجل حمادا الراوية بالبصرة وهو عند بلال بن أبي بردة من أشعر الناس قال الذي يقول\n(رمتني بنات الدهر من حيث لا أرى ... فما بال من يرمى وليس برام)\nال والشعر لعمرو بن قميئة قال علي بن الصباح في خبره عن ابن الكلبي وعمر ابن قميئة تسعين سنة فقال لما بلغها\n(كأني وقد جاوزت تسعين حجة ... خلعت بها عني عنان لجامي)\n(على الراحتين مرة وعلى العصا ... أنوء ثلاثا بعدهن قيامي)\n(رمتني بنات الدهر من حيث لا أرى ... فما بال من يرمى وليس برام)\n(فلو أن ما أرمى بنبل رميتها ... ولكنما أرمى بغير سهام)\n(إذا ما رآني الناس قالوا ألم يكن ... حديثا جديد البري غير كهام)\n(وأفنى وما أفني من الدهر ليلة ... ولم يفن ما أفنيت سلك نظام)\n(وأهلكني تأميل يوم وليلة ... وتأميل عام بعد ذاك وعام)\nأخبرني الحسين بن يحيى قال قال حماد بن إسحاق قرأت على أبي حدثنا الهيثم بن عدي عن مجالد عن الشعبي قال دخلت على عبد الملك بن مروان في علته التي مات فيها فقلت كيف تجدك يا أمير المؤمنين فقال أصبحت كما قال عمرو بن قميئة\n(كأني وقد جاوزت تسعين حجة ... خلعت بها عني عنان لجام)\n(رمتني بنات الدهر من حيث لا أرى ... فكيف بمن يرمى وليس برام)\n(فلو أنها نبل إذا لاتقيتها ... ولكنما أرمى بغير سهام)\n(وأهلكني تأميل يوم وليلة ... وتأميل عام بعد ذاك وعام)\nقلت لست كذلك يا أمير المؤمنين ولكنك كما قال لبيد\n(قامت تشكى إلي الموت مجهشة ... وقد حملتك سبعا بعد سبعينا)\n(فإن تزادي ثلاثا تبلغي أملا ... وفي الثلاث وفاء للثمانينا)\nفعاش حتى بلغ التسعين فقال\n(كأني وقد جاوزت تسعين حجة ... خلعت بها عن منكبي ردائيا)\nعاش حتى بلغ عشرا ومائة سنة فقال\n(أليس في مائة قد عاشها رجل ... وفي تكامل عشر بعدها عبر)\nعاش والله حتى بلغ مائة وعشرين سنة فقال\n(وغنيت سبتا قبل مجرى داحس ... لو كان للنفس اللجوج خلود)\nيروى دهرا قبل مجرى داحس فعاش حتى بلغ مائة وأربعين سنة فقال\n(ولقد سئمت من الحياة وطولها ... وسؤال هذا الناس كيف لبيد)\nتبسم عبد الملك وقال لقد قويت من نفسي بقولك يا عامر وإني لأجد خفا وما بي من بأس وأمر لي بصلة وقال لي اجلس يا شعمي فحدثني ما بينك وبين الليل فجلست فحدثته حتى أمسيت وخرجت من عنده فما أصبحت حتى سمعت الواعية في داره","topic":"أخبار عمرو بن قميئة ونسبه","topicNo":237,"sp":1,"spl":"حماد الراوية يرى أنه أشعر الناس — خروجه إلى قيصر","tags":["اللهو والمزاح"],"loc":3189},
{"id":"b237-4","bab":"الجزء 18","sec":"خروجه إلى قيصر","page":"ج18 ص148","text":"أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن طهمان السلمي عن إسحاق بن مرار الشيباني قال نزل امرؤ القيس بن حجر ببكر بن وائل وضرب قبته وجلس إليه وجوه بكر بن وائل فقال لهم هل فيكم أحد يقول الشعر فقالوا ما فينا شاعر إلا شيخ قد خلا من عمره وكبر قال فأتوني به فأتوه بعمرو بن قميئة وهو شيخ فأنشده فأعجب به فخرج به معه إلى قيصر وإياه عني امرؤ القيس بقوله\n(بكى صاحبي لما رأى الدرب دونه ... وأيقن أنا لاحقان بقيصرا)\n(فقلت له لا تبك عينك إنما ... تحاول ملكا أو نموت فتعذرا)\nوقال مؤرج في هذا الخبر إن امرأ القيس قال لعمرو بن قميئة في سفره ألا تركب إلى الصيد فقال عمرو\n(شكوت إليه أنني ذو جلالة ... وأني كبير ذو عيال مجنب)\n(فقال لنا أهلا وسهلا ومرحبا ... إذا سركم لحم من الوحش فاركبوا)\n\n(يا آح من حر الهوى إنما ... يعرف حر الحب من جربا)\n(أصبحت للحب أسيرا فقد ... صعدني الحب وقد صوبا)\n(لا شك أني ميت حسرة ... إن لم أزر قبل غد زينبا)\n(تلك التي إن نلتها لم أبل ... من شرق الدهر أو غربا)\nالشعر للمؤمل بن جميل بن يحيى بن أبي حفصة بن عمرو بن مروان بن أبي حفصة والغناء لابن جامع رمل بالوسطى عن إبراهيم والهشامي","topic":"أخبار عمرو بن قميئة ونسبه","topicNo":237,"sp":1,"spl":"حماد الراوية يرى أنه أشعر الناس — خروجه إلى قيصر","tags":["الحب والغزل"],"song":1,"loc":3190},
{"id":"b237-5","bab":"الجزء 18","sec":"أخبار المؤمل بن جميل","page":"ج18 ص150","text":"قد مضى نسب أبي حفصة في أخبار مروان وكان يحيى بن أبي حفصة يكنى أبا جميل والمؤمل بن جميل يكنى أبا جميل وأم جميل أميرة بنت زياد بن هوذة بن شماس بن لؤي من بني أنف الناقة الذين يمدحهم الحطيئة وأم المؤمل شريفة بنت المذلق بن الوليد بن طلبة بن قيس بن عاصم المنقري وكان جميل يلقب قتيل الهوى ولقب بذلك لقوله\n(قلن من ذا فقلت هذا اليماني ... قتيل الهوى أبو الخطاب)\n(قلن بالله أنت ذاك يقينا ... لا تقل قول مازح لعاب)\n(إن تكن أنت هو فأنت منانا ... خاليا كنت أو مع الأصحاب)\nأخبرني بذلك يحيى بن علي إجازة عن محمد بن إدريس بن سليمان عن أبيه وحكى أبو أحمد - رحمه الله - عن محمد بهذا الإسناد أن أبا جميل اشترى غلاما مدنيا مغنيا مجلوبا من مولدي السند\nعلى البراءة من كل عيب يقال له المطرز فدعا أصحابا له ذات يوم ودعا شيخين من أهل اليمامة مغنيين يقال لأحدهما السائب وللآخر شعبة فلما أخذ القوم مجلسهم ومعهم المطرز اندفع الشيخان فغنيا فقال المطرز لأبي جميل مولاه ويلك يا أبا جميل يابن الزانية أتدري ما فعلت ومن عندك فقال له ويلك أجننت مالك\nقال أما أنا فأشهد أنك تأمن مكر الله حين أدخلت منزلك هذين قال وبعثه يوما يدعو أصدقاء له فوجدهم عند رجل من أهل اليمامة يقال له بهلول وهو في بستان له فقال لهم مولاي أبو جميل قد أرسلني أدعوكم وقد بلغتكم رسالته وإن شاورتموني أشرت عليكم فقالوا أشر علينا\nقال أرى ألا تذهبوا إليه فمجلسكم والله أنزه من مجلسه وأحسن فقالوا قد أطعناك قال وأخرى قالوا وما هي قال تحلفون علي ألا أبرح ففعلوا فأقام عندهم وغضب عليه أبو جميل يوما فبطحه يضربه وهو يقول ويلك أبا جميل اتق الله في الله الله في أمري أما علمت ويلك خبري قبل أن تشتريني\nقال وكان يبعثه إلى بئر لهم عذبة في بستان له يستقي منها لهم ماء فكان يستقيه ثم يصبه لجيران لهم في حيهم ثم يستقي مكانه من بئر لهم غليظة فإذا أنكر مولاه\nقال له سل الغلمان إذا أتيت البستان هل استقيت منه فيسألهم فيجده صادقا حدثنا يحيى بن محمد بن إدريس عن أبيه أن يحيى بن أبي حفصة زوج ابنه جميلا شريفة بنت المذلق بن الوليد بن طلبة بن قيس بن عاصم فولدت له المؤمل بن جميل وكان شاعرا ظريفا غزلا وكان منقطعا إلى جعفر بن سليمان بالمدينة ثم قدم العراق فكان مع عبد الله بن مالك وذكره للمهدي فحظي عنده وهو الذي يقول في شكاة اشتكاها عبد الله بن مالك\n(ظلت علي الأرض مظلمة ... إذ قيل عبد الله قد وعكا)\n(يا ليت ما بك بي وإن تلفت ... نفسي لذاك وقل ذاك لكا)\nهو الذي يقول\n(يا آح من حر الهوى إنما ... يعرف حر الحب من جربا)\nذكر الأبيات التي تقدم ذكرها والغناء فيها\n(إني وهبت لظالمي ظلمي ... وغفرت ذاك له على علم)\n(ما زال يظلمني وأرحمه ... حتى رثيت له من الظلم)\nلشعر لمساور الوراق والغناء لإبراهيم بن أبي العبيس ثاني ثقيل بالوسطى أخبرني بذلك ذكاء وغيره","topic":"أخبار عمرو بن قميئة ونسبه","topicNo":237,"sp":2,"spl":"أخبار المؤمل بن جميل","tags":["الحب والغزل"],"song":1,"loc":3191},
{"id":"b238-1","bab":"الجزء 18","sec":"أخبار مساور ونسبه","page":"ج18 ص153","text":"هو مساور بن سوار بن عبد الحميد من آل قيس بن عيلان بن مضر ويقال إنه مولى خويلد من عدوان كوفي قليل الشعر من أصحاب الحديث ورواته وقد\nروى عن صدر من التابعين وروى عنه وجوه أصحاب الحديث أخبرني علي بن طيفور بن غالب النسائي قال حدثنا يعقوب بن حميد بن كاسب قال حدثنا حماد بن أسامة عن مساور الوراق\nقال حدثني جعفر بن عمرو بن حريث عن أبيه قال كأني أنظر إلى النبي وهو على ناقته يخطب وعليه عمامة سوداء قد أرخاها بين كتفيه أخبرني محمد بن الحسن بن دريد قال أخبرنا الأشنانداني عن الأصمعي قال كان قوم يجلسون إلى ابن أبي ليلى فكتب قوما منهم لعيسى بن\nموسى وأشار عليه أن يشغلهم ويصلهم فأتى مساور الوراق فكلمه أن يجعله فيهم فلم يفعل فأنشأ يقول\n(أراك تشير بأهل الصلاح ... فهل لك في الشاعر المسلم)\n(كثير العيال قليل السؤال ... عف مطاعمه معدم)\n(يقيم الصلاة ويؤتي الزكاة ... وقد حلق العام بالموسم)\n(وأصبح والله في قومه ... وأمسى وليس بذي درهم)\nال فقال ابن أبي ليلى لا حاجة لنا فيه فقال فيه مساور أبياتا قال أبو بكر بن دريد كرهنا ذكرها صيانة لابن أبي ليلى أخبرني محمد قال حدثني التوزي قال كان مساور الوراق وحماد عحرد وحفص بن أبي بردة مجتمعين فجعل حفص يعيب شعر المرقش الأكبر فأقبل عليه مساور فقال\n(لقد كان في عينيك يا حفص شاغل ... وأنف كثيل العود عما تتبع)\n(تتبعت لحنا في كلام مرقش ... ووجهك مبني على اللحن أجمع)\nفقام حفص من المجلس خجلا وهاجر مدة","topic":"أخبار مساور ونسبه","topicNo":238,"sp":0,"spl":"أخبار مساور ونسبه","tags":["الرواية والكتابة"],"loc":3192},
{"id":"b238-2","bab":"الجزء 18","sec":"وصية مساور لابنه","page":"ج18 ص155","text":"نسخت من كتاب عبيد الله اليزيدي بخطه حدثنا سليمان بن أبي شيخ قال كان مساور الوراق من جديلة قيس ثم من عدوان مولى لهم فقال لابنه يوصيه\n(شمر ثيابك واستعد لقائل ... واحكك جبينك للعهود بثوم)\n(إن العهود صفت لكل مشمر ... دبر الجبين مصفر موسوم)\n(أحسن وصاحب كل قار ناسك ... حسن التعهد للصلاة صؤوم)\n(من ضرب حماد هناك ومسعر ... وسماك العتكي وابن حكيم)\n(وعليك بالغنوي فاجلس عنده ... حتى تصيب وديعة ليتيم)\n(تغنيك عن طلب البيوع نسيئة ... وتكف عنك لسان كل غريم)\n(وإذا دخلت على الربيع مسلما ... فاخصص شبابة منك بالتسليم)\nال ففعل ما أوصاه به أبوه فلم يلبث مساور أن ولاه عيسى بن موسى عملا ودفع إليه عهده فانكسر عليه الخراج فدفع إلى بطين صاحب عذاب عيسى يستأديه فقال مساور\n(وجدت دواهر البقال أهنى ... من الفرني والجدي السمين)\n(وخيرا في العواقب حين تبلى ... إذا كان المرد إلى بطين)\n(فكن يا ذا المطيف بقاضيينا ... غدا من علم ذاك على يقين)\n(وقل لهما إذا عرضا بعهد ... برئت إلى عرينة من عرين)\n(فإنك طالما بهرجت فيها ... بمثل الخنفساء على الجبين)\nأخبرني الحسن بن علي قال حدثنا محمد بن موسى بن حماد قال مر مساور الوراق بمقبرة حميد الطوسي وكان له صديقا فوقف عليها مستعبرا وأنشأ يقول\n(أبا غانم أما ذراك فواسع ... وقبرك معمور الجوانب محكم)\n(وما ينفع المقبور عمران قبره ... إذا كان فيه جسمه يتهدم)\nخبرني إسماعيل بن يونس الشيعي قال حدثنا الرياشي قال حدثنا محمد بن الصباح عن سفيان بن عيينة ونسخت هذا الخبر أيضا من بعض الكتب أن حامد بن يحيى البلخي حدث عن سفيان بن عيينة وهذه الرواية أتم وقال لما سمع مساور الوراق لغط أصحاب أبي حنيفة وصياحهم أنشأ يقول\n(كنا من الدين قبل اليوم في سعة ... حتى بلينا بأصحاب المقاييس)\n(قوم إذا اجتمعوا ضجوا كأنهم ... ثعالب ضبحت بين النواويس)\nبلغ ذلك أبا حنيفة وأصحابه فشق عليهم وتوعدوه فقال أبياتا ترضيهم وهي وهي\n(إذا ما الناس يوما قايسونا ... بآبدة من الفتيا ظريفه)\n(أتيناهم بمقياس ظريف ... مصيب من قياس أبي حنيفه)\n(إذا سمع الفقيه بها وعاها ... وأثبتها بحبر في صحيفه)\nبلغ أبا حنيفة فرضي قال مساور ثم دعينا إلى وليمة بالكوفة في يوم شديد الحر فدخلت فلم أجد لرجلي موضعا من الزحام وإذا أبو حنيفة في صدر البيت فلما رآني\nقال إلي مساور فجئت فإذا مكان واسع وقال لي اجلس فجلست فقلت في نفسي نفعتني أبياتي اليوم قال وكان إذا رآني بعد ذلك يقول لي ها هنا ها هنا ويوسع لي إلى جنبه ويقول إن هذا من أهل الأدب والفهم انتهى\nأخبرني محمد بن الحسن بن دريد قال حدثنا أبو المعمر عبد الأول بن مزيد أحد بني أنف الناقة قال كان مساور الوراق لا يضيع حقا لجار له فماتت بنته فلم يشهدها من جيرانه إلا نفر يسير فقال مساور في ذلك\n(تغيب عني كل جاف ضرورة ... وكل طفيلي من القوم عاجز)\n(سريع إذا يدعى ليوم وليمة ... بطيء إذا ما كان حمل الجنائز)\nخبرني محمد بن الحسن قال حدثنا عبد الأول قال قدم جار لمساور الوراق من سفر فجاءه يسلم عليه فقال يا جارية هاتي لأبي القاسم غداء فجاءت برغيف فوضعته على الخوان فمد يده يأكل مع مساور وقال له يا أبا القاسم كل من هذا الخبز فما أكلت خبزا أطيب منه فقال مساور في ذلك\n(ما كنت أحسب أن الخبز فاكهة ... حتى رأيتك يا وجه الطبرزين)\n(كأن لحيته في وجهه ذنب ... أو شعرة فوق بظر غير مختون)\nخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال دخل مساور الوراق على أبي العيص الجرمي يعوده وكان صديقه فكلمه فلم يجبه فبكى مساور جزعا عليه وأدنى رأسه منه يكلمه فقال أبو العيص\n(أفي كل عام مرضة بعد نقهة ... وتنعى ولا تنعى متى ذا إلى متى)\n(سيوشك يوم أن يجيء وليلة ... يسوقان حتفا راح نحوك أو غدا)\n(فتمسي صريعا لا تجيب لدعوة ... ولا تسمع الداعي وإن جد في الدعا)\nم لم يلبث أن مات رحمه الله\n(تنامين عن ليلي وأسهره وحدي ... وأنهى جفوني أن تبثك ما عندي)\n(فإن كنت ما تدرين ما قد فعلته ... بنا فانظري ماذا على قاتل العمد)\nلشعر لسعيد بن حميد الكاتب والغناء لعريب خفيف ثقيل مطلق بالسبابة في مجرى الوسطى","topic":"أخبار مساور ونسبه","topicNo":238,"sp":1,"spl":"وصية مساور لابنه","tags":[],"song":1,"loc":3193},
{"id":"b239-1","bab":"الجزء 18","sec":"أخبار سعيد بن حميد ونسبه","page":"ج18 ص159","text":"سعيد بن حميد بن سعيد بن حميد بن بحر يكنى أبا عثمان من أولاد الدهاقين وأصله من النهروان الأوسط وكان هو يقول إنه مولى بني سامة بن لؤي من أهل بغداد بها ولد ونشأ ثم كان يتنقل في السكنى بينها وبين سر من رأى كاتب شاعر مترسل حسن الكلام فصيح وكان أبوه وجها من وجوه المعتزلة فخالف أحمد بن أبي دواد في بعض مذهبه فأغرى به المعتصم وقال إنه شعوبي زنديق فحبسه مدة طويلة ثم بانت براءته له أو للواثق بعده فخلى سبيله وكان شاعرا أيضا فكان يهجو أحمد بن\nأبي دواد وأنشدنيها جماعة من أصحابنا قال\n(لقد أصبحت تنسب في إياد ... بأن يكنى أبوك أبا دواد)\n(فلو كان اسمه عمرو بن معدي ... دعيت إلى زبيد أو مراد)\n(لئن أفسدت بالتخويف عيشي ... لما أصلحت أصلك في إياد)\n(وإن تك قد أصبت طريف مال ... فبخلك باليسير من التلاد)\nذكر محمد بن موسى أن أبا يوسف بن الدقاق اللغوي أخبره أن حميد بن سعيد بن حميد دفع إليه ابنه سعيدا وهو صبي فقال له امض به معك إلى مجلس ابن الأعرابي\nقال فحضرناه ذات يوم فأنشدنا أرجوزه لبعض العرب فاستحسنتها ولم تكن معنا محبرة نكتبها منها فلما انصرفنا قلت له فاتتنا هذه الآرجوزه فقال لم تفتك أتحب أن أنشدكها\nقلت نعم فأنشدنيها وهي نيف وعشرون بيتا قد حفظها عنه وإنما سمعها مرة واحدة فلقيت أباه من غد فقال لي كيف رأيت سعيدا قلت له إنك أوصيتني به وأنا أسألك الآن أن توصيه بي فضحك وسألني عن الخبر فأعلمته فسر به","topic":"أخبار سعيد بن حميد ونسبه","topicNo":239,"sp":0,"spl":"أخبار سعيد بن حميد ونسبه — خبره مع أبي العباس بن ثوابة","tags":["اللهو والمزاح"],"loc":3194},
{"id":"b239-2","bab":"الجزء 18","sec":"خبره مع أبي العباس بن ثوابة","page":"ج18 ص160","text":"أخبرني علي بن العباس بن أبي طلحة قال حدثني ابن أبي المدور قال دخل سعيد بن حميد يوما على أبي العباس بن ثوابة وكان أبو العباس يعاتبه على الشغف بالغلمان المرد فرأى على رأسه غلاما أمرد حسن\nالوجه عليه منطقة وثياب حسان فقال له يا أبا العباس\n(أزعمت أنك لا تلوط فقل لنا ... هذا المقرطق قائما ما يصنع)\n(شهدت ملاحته عليك بريبة ... وعلى المريب شواهد لا تدفع)\nضحك أبو العباس وقال خذه لا بورك لك فيه حتى نستريح من عتبك أخبرني عمي رحمه الله قال قال لي محمد بن موسى بن الحسن بن الفرات الكاتب كان سعيد بن حميد يهوى غلاما له من أولاد الموالي فغاب عنه مدة ثم جاءه مسلما فقال له غبت عني هذه المدة ثم تجيئني فلا تقيم عندي فقال له قد أمسينا فقال تبيت\nقال لا والله لا أقدر ولم يزل به حتى اتفقا على أنه إذا سمع أذان العتمة انصرف فقال له قد رضيت ووضع النبيذ فجعل سعيد يحث السقي بالأرطال فلما قرب وقت العتمة أخذ رقعة فكتب فيها إلى إمام المسجد وهو مؤذنه قوله\n(قل لداعي الفراق أخر قليلا ... قد قضينا حق الصلاة طويلا)\n(أخر الوقت في الأذان وقدم ... بعدها الوقت بكرة وأصيلا)\n(ليس في ساعة تؤخرها وزر ... فنحيا بها وتأتي جميلا)\n(فتراعي حق الفتوة فينا ... وتعافى من أن تكون ثقيلا)\nلما قرأ المؤذن الرقعة ضحك وكتب إليه يحلف أنه لا يؤذن ليلته تلك العتمة وجعل الفتى ينتظر الأذان حتى أمسى وسمع صوت الحارس فعلم أنها حيلة وقعت عليه وبات في موضعه وقال سعيد في ذلك\n(عرضت بالحب له وعرضا ... حتى طوى قلبي على جمر الغضى)\n(وأظهرت نفسي عن الدهر الرضا ... ثم جفاني وتولى معرضا)\n(لم ينقض الحب بلى صبري انقضى ... فداك من ذاق الكرى أو غمضا)\n(حتى طرقت فنسيت ما مضى ... سألته حويجة فأعرضا)\n(وقال لا قول مجيب برضا ... فكان ما كان وكابرنا القضا)\nي هذه الأبيات هزج لأحمد بن صدقة أخبرني بذلك ذكاء وجه الرزة وجدت في بعض الكتب حدثني أحمد بن سليمان بن وهب أنه كان في مجلس فيه سعيد بن حميد فلما سكروا قام سعيد قومة بعد العصر فلم نشعر إلا وقد أخذ ثيابه فلبسها وأخذ بعضدتي الباب وأنشأ يقول\n(سلام عليكم حالت الراح بيننا ... وألوت بنا عن كل مرأى ومسمع)\n(ولم يبق إلا أن يميل بنا الكرى ... ويجمع نوم بين جنب ومضجع)\nقام له أهل المجلس وقالوا يا سيدنا اذهب في حفظ الله وفي ستره فانصرف وودعهم","topic":"أخبار سعيد بن حميد ونسبه","topicNo":239,"sp":0,"spl":"أخبار سعيد بن حميد ونسبه — خبره مع أبي العباس بن ثوابة","tags":["الحب والغزل","اللهو والمزاح"],"loc":3195},
{"id":"b239-3","bab":"الجزء 18","sec":"اعتذاره لفضل الشاعرة وإخباره معها","page":"ج18 ص162","text":"حدثني محمد بن الطلاس أبو الطيب قال حدثني عبد الله بن طالب الكاتب قال قرأت رقعة بخط سعيد بن حميد إلى فضل الشاعرة يعتذر إليها من تغير ظنته به وفي آخرها\n(تظنون أني قد تبدلت بعدكم ... بديلا وبعض الظن إثم ومنكر)\n(إذا كان قلبي في يديك رهينة ... فكيف بلا قلب أصافي وأهجر)\nي هذين البيتين لابن القصار الطنبوري رمل وفيهما لمحمد قريض خفيف رمل أخبرني علي بن العباس بن أبي طلحة الكاتب قال حدثني أبو علي المادراني أنه كان في مجلس فيه كعب جارية أبي عكل المقين وكان بعض اهل المجلس يهواها قال فدخل إلينا سعيد بن حميد فقام إليه أهل المجلس جميعا سوى الجارية والفتى فأخذ سعيد الدواة فكتب رقعة وألقاها في حجرها فإذا فيها قوله\n(ما على أحسن خلق ... الله أن يحسن فعله)\n(بأبي أنت وأمي ... من مليك قل عدله)\n(وبخيل بالهوى لو ... كان يسلى عنه بخله)\n(أكثر العاذل في حبك ... لو ينفع عذله)\n(فهو مشغول بعذلي ... وفؤادي بك شغله)\n(أكثر الشكوى وأستعدي ... على من قل بذله)\nوثبت الجارية فقبلت رأسه وجلست إلى جنبه فقال الرجل الذي كان يهواها هذا والله كلام الشياطين ورقية الزنا وبهذا يتم الأمر أما أنا فإني\nأشهدكم لا قرأت اليوم في صلاتي غير هذه الأبيات لعلها تنفعني فضحك سعيد وقال بحياتي قومي فارجعي إليه حتى تكون الأبيات قد نفعته قبل أن يقرأها في صلاته وسريني بذلك فقامت فرجعت إلى موضعها\nقال علي بن العباس وحدثني أبو علي المادراني أنه كان عنده يوما فدخلت إليه جارية - كان يهواها - غفلة على غير وعد فسر بذلك وقال لها قد كنت على عتابك فأما الآن فلا فقالت أما العتاب فلا طاقة لي به ووالله ما جئتك إلا عند غفلة البواب فقال سعيد في ذلك\n(زارك زور على ارتقاب ... مغتنما غفلة الحجاب)\n(مستترا بالنقاب يبدو ... ضياء خديه في النقاب)\n(كالشمس تبدو وقد طواها ... دونك ستر من السحاب)\n(قد كان في النفس منك عتب ... يدعو إلى شدة اجتناب)\n(فملت بالعتب عن حبيب ... يضعف عن موقف العتاب)\n(والذنب منه وأنت تخشى ... في هجره صولة العقاب)\nخبرني عمي قال حدثني ابن أبي سعد قال حدثني محمد بن عبد الله بن داود قال كان أبي يستحسن قول سعيد بن حميد\n(تظنون أني قد تبدلت بعدكم ... بديلا وبعض الظن إثم ومنكر)\n(إذا كان قلبي في يديك رهينة ... فكيف بلا قلب أصافي وأهجر)\nيقول لئن عاش هذا الغلام ليكونن له في الشعر شأن في هذين البيتين غناء من خفيف الرمل وذكر قريض أنه له أخبرني ابن أبي طلحة قال حدثني إسحاق بن مسافر أنه كان عند سعيد بن حميد يوما إذ دخلت عليه فضل الشاعرة على غفلة فوثب إليها وسلم\nعليها وسألها أن تقيم عنده فقالت قد جاءني وحياتك رسول من القصر فليس يمكنني الجلوس وكرهت أن أمر ببابك ولا أراك فقال سعيد من وقته على البديهة\n(قربت ولا نرجو اللقاء ولا نرى ... لنا حيلة يدنيك منا احتيالها)\n(فأصبحت كالشمس المنيرة ضوءها ... قريب ولكن أين منا منالها)\n(كظاعنة ضنت بها غربة النوى ... علينا ولكن قد يلم خيالها)\n(تقربها الآمال ثم تعوقها ... مماطلة الدنيا بها واعتلالها)\n(ولكنها أمنية فلعلها ... يجود بها صرف النوى وانتقالها)\nأخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن يعقوب بن داود قال تغاضب سعيد بن حميد وفضل الشاعرة أياما ثم كتب إليها\n(تعالي نجدد عهد الرضا ... ونصفح في الحب عما مضى)\n(ونجري على سنة العاشقين ... ونضمن عني وعنك الرضا)\n(ويبذل هذا لهذا هواه ... ويصبر في حبه للقضا)\n(ونخضع ذلا خضوع العبيد ... لمولى عزيز إذا أعرضا)\n(فإني مذ لج هذا العتاب ... كأني أبطنت جمر الغضى)\nصارت إليه وصالحته في هذه الأبيات لهاشم بن سليمان ثقيل أول بالوسطى وفيها لابن القصار خفيف رمل أخبرني ابن أبي طلحة قال حدثنا أبو العباس بن أبي المدور قال بات سعيد بن حميد عند أبي الفضل بن أحمد بن إسرائيل واصطبحا\nعلى غناء حسن كان عندهما فجاءه رسول الحسن بن مخلد وقد أمر ألا يفارقه لأمر مهم فقام فلبس ثيابه وأنشأ يقول\n(يا ليلة بات النحوس بعيدة ... عنها على رغم الرقيب الراصد)\n(تدع العواذل لا يقمن لحاجة ... وتقوم بهجتها بعذر الحاسد)\n(ضن الزمان بها فلما نلتها ... ورد الفراق فكان أقبح وارد)\n(والدمع ينطق للضمير مصدقا ... قول المقر مكذبا للجاحد)","topic":"أخبار سعيد بن حميد ونسبه","topicNo":239,"sp":1,"spl":"اعتذاره لفضل الشاعرة وإخباره معها","tags":["الحب والغزل","الجواري والنساء"],"loc":3196},
{"id":"b239-4","bab":"الجزء 18","sec":"اعتذاره لفضل الشاعرة وإخباره معها","page":"ج18 ص162","text":"أخبرني ابن أبي طلحة قال حدثني أبو العباس بن أبي المدور قال كان سعيد بن حميد صديقا لأبي العباس بن ثوابة فدعاه يوما وجاءه رسول فضل الشاعرة يسأله المصير إليها فمضى معه وتأخر عن أبي العباس فكتب إليه رقعة يعاتبه فيها معاتبة فيها بعض الغلظة فكتب إليه سعيد\n(أقلل عتابك فالبقاء قليل ... والدهر يعدل تارة ويميل)\n(لم أبك من زمن ذممت صروفه ... إلا بكيت عليه حين يزول)\n(ولكل نائبة المت مدة ... ولكل حال أقبلت تحويل)\n(والمنتمون إلى الإخاء جماعة ... إن حصلوا أفناهم التحصيل)\n(ولعل أحداث الليالي والردى ... يوما ستصدع بيننا وتحول)\n(فلئن سبقت لتبكين بحسرة ... وليكثرن علي منك عويل)\n(ولتفجعن بمخلص لك وامق ... حبل الوفاء بحبله موصول)\n(وليذهبن جمال كل مروءة ... وليعفون فناؤها المأهول)\n(ولئن سبقت ولا سبقت ليمضين ... من لا يشاكله لدي عديل)\n(وأراك تكلف بالعتاب وودنا ... باق عليه من الوفاء دليل)\n(ود بدا لذوي الإخاء جميله ... وبدت عليه بهجة وقبول)\n(ولعل أيام الحياة قصيرة ... فعلام يكثر عتبنا ويطول)\nخبرني الطلحي قال حدثني أبو علي بن أبي الرعد أن سعيد بن حميد كان يهوى مظلومة جارية الدقيقي فبلغه أنها تواصل بعض أعدائه فهجرها مدة فكتبت إليه تعاتبه وتتشوقه فكتب إليها\n(أمري وأمرك شيء غير متفق ... والهجر أفضل من وصل على ملق)\n(لا أكذب الله ما نفسي بسالية ... ولا خليقة أهل الغدر من خلقي)\n(فإن وثقت بود كنت أبذله ... فعاودي سوء ظن بي ولا تثقي)\nذكر اليوسفي الكاتب أنه حضر سعيدا في منزل بعض إخوانه وعندهم هبة المغنية وكان سعيد يتعشقها ويهيم بها فغضبت عليه يوما لبعض الكلام على النبيذ ودخلت بعد ذلك وهو في القوم فسلمت عليهم سواه فقالوا لها أتهجرين أبا عثمان فقالت أحب أن تسألوه ألا يكلمني فقال سعيد\n(اليوم أيقنت أن الهجر متلفة ... وأن صاحبه منه على خطر)\n(كيف الحياة لمن أمسى على شرف ... من المنية بين الخوف والحذر)\n(يلوم عينيه أحيانا بذنبهما ... ويحمل الذنب أحيانا على القدر)\n(تنأون عنه وينأى قلبه معكم ... فقلبه أبدا منه على سفر)\nوثبت إليه وقبلت رأسه وقالت لا أهجرك والله أبدا ما حييت أخبرني جحظة قال حدثني ميمون بن هارون قال\nغضبت فضل الشاعرة على سعيد بن حميد فكتب إليها\n(يا أيها الظالم ما لي ولك ... أهكذا تهجر من واصلك)\n(لا تصرف الرحمة عن أهلها ... قد يعطف المولى على من ملك)\n(ظلمت نفسا فيك علقتها ... فدار بالظلم علي الفلك)\n(تبارك الله فما أعلم الله ... بما ألقى وما أغفلك)\nراجعت وصله وصارت إليه جوابا للرقعة في هذه الأبيات لعريب ثاني ثقيل وهزج عن ابن المعتز وأخبرني ذكاء وجه الرزة أن الثقيل لأحمد بن أبي العلاء أخبرني الطوسي الطلحي قال حدثنا محمد بن السري أن سعيد بن حميد كان في مجلس الحسن بن مخلد إذ جاءه الغلام برقعة فضل الشاعرة تشكو فيها شدة شوقها فقرأها وضحك فقال له الحسن بن مخلد بحياتي عليك أقرئنيها فدفعها إليه فقرأها وضحك وقال له قد وحياتي ملحت فأجب فكتب إليها\n(يا واصف الشوق عندي من شواهده ... قلب يهيم وعين دمعها يكف)\n(والنفس شاهدة بالود عارفة ... وأنفس الناس بالأهواء تأتلف)\n(فكن على ثقة مني وبينة ... إني على ثقة من كل ما تصف)\nخبرني جحظة قال حدثني ميمون بن هارون قال\nلما عشقت فضل الشاعرة بنان بن عمرو المغني وعدلت عن سعيد بن حميد إليه أسف عليها وأظهر تجلدا ثم قال فيها\n(قالوا تعز وقد بانوا فقلت لهم ... بان العزاء على آثار من بانا)\n(وكيف يملك سلوانا لحبهم ... من لم يطق للهوى سترا وكتمانا)\n(كانت عزائم صبري أستعين بها ... صارت علي بحمد الله أعوانا)\n(لا خير في الحب لا تبدو شواكله ... ولا ترى منه في العينين عنوانا)\nال أبو الحسن جحظة وغنى فيه بعض المحدثين لحنا حسنا وأظنه عنى نفسه أخبرني الطلحي قال حدثني أبو عيسى الكاتب أن أبا هفان بلغه عن سعيد بن حميد كلام فيه جفاء وطعن على شعره فتوعد بالهجاء وكان الحاكي عن ذلك كاذبا فبلغ سعيدا ما جرى فكتب إلى أبي هفان\n(أمسى يخوفني العبدي صولته ... وكيف آمن بأس الضيغم الهصر)\n(من ليس يحرزني من سيفه أجلي ... وليس يمنعني من كيده حذري)\n(ولا أبارزه بالأمر يكرهه ... ولو أعنت بأنصار من الغير)\n(له سهام بلا ريش ولا عقب ... وقوسه أبدا عطل من الوتر)","topic":"أخبار سعيد بن حميد ونسبه","topicNo":239,"sp":2,"spl":"اعتذاره لفضل الشاعرة وإخباره معها","tags":["الحب والغزل"],"loc":3197},
{"id":"b239-5","bab":"الجزء 18","sec":"اعتذاره لفضل الشاعرة وإخباره معها","page":"ج18 ص162","text":"(وكيف آمن من نحري له غرض ... وسهمه صائب يخفى عن البصر)\nخبرني الطلحي قال حدثني محمد بن السري أنه سار إلى سعيد بن\nحميد وهو في دار الحسن بن مخلد في حاجة له قال فإني عنده إذ جاءته رقعة فضل الشاعرة وفيها هذان البيتان\n(الصبر ينقص والسقام يزيد ... والدار دانية وأنت بعيد)\n(أشكوك أم أشكو إليك فإنه ... لا يستطيع سواهما المجهود)\nأنا يا أبا عثمان في حال التلف ولم تعدني ولا سألت عن خبري فأخذ بيدي فمضينا إلينا فسأل عن خبرها فقالت هو ذا أموت وتستريح مني فأنشأ يقول\n(لا مت قبلي بل أحيا وأنت معا ... ولا أعيش إلى يوم تموتينا)\n(لكن نعيش بما نهوى ونأمله ... ويرغم الله فينا أنف واشينا)\n(حتى إذا قدر الرحمن ميتتنا ... وحان من أمرنا ما ليس يعدونا)\n(متنا جميعا كغصني بانة ذبلا ... من بعد ما نضرا واستوسقا حينا)\n(ثم السلام علينا في مضاجعنا ... حتى نعود إلى ميزان منشينا)\nخبرني إبراهيم بن القاسم بن زرزور قال قال لي أبي كانت فضل الشاعرة تتعشق سعيد بن حميد مدة طويلة ثم تعشقت بنانا وعدلت عنه فقال فيها قصيدته الدالية التي يقول فيها\n(تنامين عن ليلي وأسهره وحدي ... )\nلم تتعطف عليه وبلغها بعد ذلك أنه قد عشق جارية من جواري القيان فكتبت إليه\n(يا عالي السن سيء الأدب ... شبت وأنت الغلام في الطرب)\n(ويحك إن القيان كالشرك المنصوب ... بين الغرور والعطب)\n(لا تصدين للفقير ولا ... يطلبن إلا معادن الذهب)\n(بينا تشكى هواك إذ عدلت ... عن زفرات الشكوى إلى الطلب)\n(تلحظ هذا وذاك وذا ... لحظ محب وفعل مكتسب)\nأخبرني إبراهيم قال وحدثني أبي قال افتصد سعيد بن حميد فسألتني فضل الشاعرة وسألت عريب أن نمضي إليه ففعلنا وأهدت إليه هدايا فكان منها ألف جدى وحمل وألف دجاجة فائقة وألف طبق ريحان وفاكهة ومع ذلك طيب كثير وشراب وتحف حسان فكتب إليها سعيد إن سروري لا يتم إلا بحضورك فجاءته في آخر النهار وجلسنا نشرب فاستأذن غلامه بنان فأذن له فدخل إلينا وهو يومئذ شاب طرير حسن الوجه حسن الغناء نظيف الثياب شكل فذهب بها كل مذهب وأقبلت عليه بحديثها ونظرها فتشمز سعيد واستطير غضبا وتبين بنان القصة فانصرف وأقبل عليها سعيد يعذلها ويؤنبها ساعة ثم أمسك فكتبت إليه\n(يا من أطلت تفرسي ... في وجهه وتنفسي)\n(أفديك من متدلل ... يزهى بقتل الأنفس)\n(هبني أسأت وما أسأت ... بلى أقر أنا المسي)\n(أحلفتني ألا أسارق ... نظرة في مجلسي)\n(فنظرت نظرة مخطىء ... أتبعتها بتفرس)\n(ونسيت أني قد حلفت ... فما عقوبة من نسي)\nقام سعيد فقبل رأسها وقال لا عقوبة عليه بل نحتمل هفوته ونتجافى عن إساءته وغنت عريب في هذا الشعر هزجا فشربنا عليه بقية يومنا ثم افترقنا وأثر بنان في قلبها وعلقت به فلم تزل حتى واصلته وقطعت سعيدا وجدت في بعض الكتب عن عبد الله بن المعتز\nقال قال لي إبراهيم بن المهدي كانت فضل الشاعرة من أحسن خلق الله خطا وأفصحهم كلاما وأبلغهم في مخاطبة وأثبتهم في محاورة فقلت يوما لسعيد بن حميد أظنك يا أبا عثمان تكتب لفضل رقاعها وتقيدها وتخرجها فقد أخذت نحوك في الكلام وسلكت سبيلك فقال لي وهو يضحك ما أخيب ظنك ليتها تسلم مني ولا آخذ كلامها ورسائلها والله يا أخي لو أخذ أفاضل الكتاب وأماثلهم عنها لما استغنوا عن ذلك\n(كل حي لاقي الحمام فمودي ... ما لحي مؤمل من خلود)\n(لا تهاب المنون شيئا ولا تبقي ... على والد ولا مولود)\nلشعر لابن مناذر والغناء لبنان ثقيل أول بالسبابة في مجرى الوسطى من كتابه الذي جمع فيه صنعته وفيه لساجي جارية عبيد الله بن عبد الله بن طاهر ثقيل أول أيضا على مذهب النوح ابتداؤه نشيد","topic":"أخبار سعيد بن حميد ونسبه","topicNo":239,"sp":3,"spl":"اعتذاره لفضل الشاعرة وإخباره معها","tags":[],"song":2,"loc":3198,"partialRef":{"sid":"b238-2","gi":8,"vi":0,"side":0},"partial":1},
{"id":"b240-1","bab":"الجزء 18","sec":"أخبار ابن مناذر ونسبه","page":"ج18 ص173","text":"هو محمد بن مناذر مولى بني صبير بن يربوع ويكنى ابا جعفر وقيل إنه كان يكنى أبا عبد الله ووجدت في بعض الكتب رواية عن ابن حبيب أنه كان يكنى أبا ذريح وقد كان له ابن يسمى ذريحا فمات وهو صغير وإياه عني بقوله\n(كأنك للمنايا يا ... ذريح الله صوركا)\n(فناط بوجهك الشعرى ... وبالإكليل قلدكا)\nلعله اكنتى به قبل وفاته وقال الجاحظ كان محمد بن مناذر مولى سليمان القهرمان وكان سليمان مولى عبيد الله بن أبي بكرة مولى رسول الله وكان أبو بكرة\nعبدا لثقيف ثم ادعى عبيد الله بن أبي بكرة أنه ثقفي وادعى سليمان القهرمان أنه تميمي وادعى ابن مناذر أنه صليبة من بني صبير بن يربوع فابن مناذر مولى مولى مولى وهو دعي مولى دعي وهذا ما لا يجتمع في غيره قط ممن عرفناه وبلغنا خبره","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":0,"spl":"أخبار ابن مناذر ونسبه","tags":["الموت"],"loc":3199},
{"id":"b240-2","bab":"الجزء 18","sec":"كان فصيحا مقدما في العلم باللغة","page":"ج18 ص174","text":"ومحمد بن مناذر شاعر فصيح مقدم في العلم باللغة وإمام فيها وقد أخذ عنه أكابر أهلها وكان في أول أمره يتأله ثم عدل عن ذلك فهجا الناس وتهتك وخلع وقذف أعراض أهل البصرة حتى نفي عنها إلى الحجاز فمات هناك وهذه الأبيات يرثي بها ابن مناذر عبد المجيد بن عبد الوهاب الثقفي وكان عبد الوهاب محدثا جليلا وقد\nروى عنه وجوه المحدثين وكبراء الرواة وكان ابن مناذر يهوى عبد المجيد هذا فكان في أيام حياته مستورا متألها جميل الأمر فلما مات عبد المجيد حال عن جميع ما كان عليه وأخبارهما تذكر في مواضعها\nأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي قال كان ابن مناذر مولى صبير بن يربوع وكان إماما في علم اللغة وكلام العرب وكان في أول أمره ناسكا ملازما للمسجد كثير النوافل جميل الأمر إلى أن فتن بعبد المجيد بن عبد الوهاب الثقفي فتهتك بعد ستره وفتك بعد نسكه ثم ترامى به الأمر بعد موت عبد المجيد بن عبد الوهاب الثقفي إلى أن شتم الأعراض وأظهر البذاء وقذف المحصنات ووجبت عليه حدود فهرب إلى مكة وبقي بها حتى مات\nوكان يجالس سفيان بن عيينة فيسأله سفيان عن معاني حديث النبي فيخبره بها ويقول له كذا وكذا مأخوذ من كذا فيقول سفيان كلام العرب بعضه يأخذ برقاب بعض\nقال وأدرك المهدي ومدحه ومات في أيام المأمون أخبرني علي بن سليمان قال حدثني محمد بن يزيد وغيره أن محمد بن مناذر كان إذا قيل له ابن مناذر بفتح الميم يغضب ثم يقول أمناذر الصغرى أم مناذر الكبرى وهما كورتان من كور الأهواز إنما هو مناذر على وزن مفاعل من ناذر فهو مناذر مثل ضارب فهو مضارب وقاتل فهو مقاتل\nقال محمد بن يزيد ولما عدل محمد بن مناذر عما كان عليه من النسك والتأله وعظته المعتزلة فلم يتعظ وأوعدته بالمكروه فلم يزدجر ومنعوه من دخول المسجد فنابذهم وطعن عليهم وهجاهم وكان يأخذ المداد بالليل فيطرحه في مطاهرهم فإذا توضؤوا به سود وجوههم وثيابهم وقال في توعد المعتزلة إياه\n(أبلغ لديك بني تميم مألكا ... عني وعرج في بني يربوع)\n(أني أخ لكم بدار مضيعة ... بوم وغربان عليه وقوع)\n(يا للقبائل من تميم ما لكم ... روبى ولحم أخيكم بمصيع)\n(هبوا له فلقد أراه بنصركم ... يأوي إلى جبل أشم منيع)\n(وإذا تحزبت القبائل كنتم ... ثقتي لكل ملمة وفظيع)\n(إن أنتم لن تثأروا لأخيكم ... حتى يباء بوتره المتبوع)\n(فخذوا المغازل بالأكف وأيقنوا ... ما عشتم بمذلة وخضوع)\n(إن كنتم حدبا على أحسابكم ... سمعا فقد أسمعت كل سميع)\n(أين الصبيريون لم أر مثلهم ... في النائبات وأين رهط وكيع)\nال ثم استحيا من قوله أين الصبيريون لقلة عددهم فقال أين الرياحيون أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني الحسن بن علي قال حدثني مسعود بن بشر قال قال لي ابن مناذر ولع بي قوم من المعتزلة ففرقت منهم قال وكان مولى صبير بن يربوع فقلت بنو صبير نفسان ونصف فمن أدعو منهم فقلت ليس إلا إخوتهم بنو رياح فقلت أبياتا حرضتهم فيها وحضضت بنو رياح فقلت\n(أين الرياحيون لم أر مثلهم ... في النائبات وأين رهط وكيع)\nال فجاء خمسون شيخا من بني رياح فطردوهم عني\nأخبرني علي بن سليمان قال حدثني محمد بن يزيد قال حدثني الجاحظ عن مسعود بن بشر عن أبي عبيدة قال ما زادت بنو صبير بن يربوع قط على سبعة نفر كلما ولد منهم مولود مات منهم ميت\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن نعيم قال حدثني إسحاق بن محمد النخعي قال حدثني أبو عثمان المازني قال كان ابن مناذر من أهل عدن وإنما صار إلى البصرة في طلب الأدب لتوافر العلماء فيها فأقام فيها مدة ثم شغل بعبد المجيد بن عبد الوهاب الثقفي فتطاول أمره إلى أن خرج عنها وكان مقيما بمكة فلما مات عبد المجيد نسك وقوم يقولون إنه كان دهريا","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":1,"spl":"كان فصيحا مقدما في العلم باللغة","tags":["الهجاء","المديح"],"loc":3200},
{"id":"b240-3","bab":"الجزء 18","sec":"خلاعته وكره الناس له","page":"ج18 ص177","text":"وذكر أبو دعامة عن عطاء الملط قال كان ابن مناذر يؤم الناس في المسجد الذي في قبيلته فما أظهر ما أظهره من الخلاعة والمجون كرهوا أن يصلي بهم وأن يأتموا به فقالوا شعرا وذكروا ذلك فيه وهجوه وألقوا الرقعة في المحراب فلما قضى صلاته قرأها ثم قلبها وكتب فيها يقول\n(نبئت قافية قيلت تناشدها ... قوم سأترك في أعراضهم ندبا)\n(ناك الذين رووها أم قائلها ... وناك قائلها أم الذي كتبا)\nم رمى بهم إليهم ولم يعد إلى الصلاة بهم\nأخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا أبو الفضل بن عبدان بن ابي حرب الصفار قال حدثني الفضل بن موسى مولى بني هاشم قال دخل ابن مناذر المسجد الجامع بالبصرة فوقعت عينه على غلام مستند ألى سارية فخرج والتمس غلاما ورقعة ودواة فكتب أبياتا مدحه بها وسأل الغلام الذي التمسه أن يوصل الرقعة إلى الفتى المستند إلى السارية فذهب بها إلى الغلام فلما قرأها قلبها وكتب على ظهرها يقول\n(مثل امتداحك لي بلا ورق ... مثل الجدار بني على خص)\n(وألذ عندي من مديحك لي ... سود النعال ولين القمص)\n(فإذا عزمت فهي لي ورقا ... فإذا فعلت فلست أستعصي)\nلما قرأها ابن مناذر قام إليه فقال له ويلك أأنت أبو نواس قال نعم فسلم عليه وتعانقا وكان ذلك أول المودة بينهما أخبرني محمد بن الحسن بن دريد\nقال حدثني أبو حاتم قال اجتمع أبو العتاهية ومحمد بن مناذر فقال له أبو العتاهية يا ابا عبد الله كيف أنت في الشعر قال أقول في الليلة إذا سنح القول لي واتسعت القوافي عشرة أبيات إلى خمسة عشر فقال له أبو العتاهية لكنى لو شئت أن أقول في الليلة ألف بيت لقلت فقال ابن مناذر أجل والله إذا أردت أن أقول مثل قولك\n(ألا يا عتبة الساعة ... أموت الساعة الساعة)\nلت ولكني لا أعود نفسي مثل هذا الكلام الساقط ولا أسمح لها به فخجل أبو العتاهية وقام يجر رجله أخبرني به الحسن بن علي قال حدثنا ابن مهرويه\nقال حدثني سهل بن محمد أبو حاتم وأحمد بن يعقوب بن المنير ابن أخت أبي بكر الأصم قال ابن مهرويه وحدثني به يحيى بن الحسن الربيعي عن غسان بن المفضل\nقال اجتمع أبو العتاهية وابن مناذر فاجتمع الناس إليهما وقالوا هذان شيخا الشعراء فقال أبو العتاهية لابن المناذر يا أبا عبد الله كم تقول في اليوم من الشعر\nوذكر باقي الخبر مثل المتقدم سواء أخبرني أبو دلف هاشم بن محمد الخزاعي قال حدثنا العباس بن ميمون طائع قال سمعت الأصمعي يقول حضرنا مأدبة ومعنا أبو محرز خلف الأحمر وحضرها ابن مناذر فقال لخلف الأحمر يا أبا محرز إن يكن النابغة وامرؤ القيس وزهير قد ماتوا فهذه أشعارهم مخلدة فقس شعري إلى شعرهم واحكم فيها بالحق فغضب خلف ثم أخذ صحفة مملوءة مرقا فرمى بها عليه فملأه فقام ابن مناذر مغضبا وأظنه هجاه بعد ذلك أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا خلاد الأرقط قال لقيني ابن مناذر بمكة فأنشدني قصيدته\n(كل حي لاقي الحمام فمودي ... )\nثم قال لي أقرىء أبا عبيدة السلام وقل له يقول لك ابن مناذر اتق الله واحكم بين شعري وشعر عدي بن زيد ولا تقل ذلك جاهلي وهذا إسلامي وذاك قديم وهذا محدث فتحكم بين العصرين ولكن حكم بين الشعرين ودع العصبية\nقال وكان ابن مناذر ينحو نحو عدي بن زيد في شعره ويميل إليه ويقدمه أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني محمد بن عثمان الكزبري\nقال أخبرني محمد بن الحجاج الجراداني قال قلت لابن مناذر من أشعر الناس قال من كنت في شعره فقلت له ومن ذاك فقال عدي بن زيد وكان ينحو نحوه في شعره ويقدمه ويتخذه إماما والأبيات التي فيها الغناء أول قصيدة لمحمد بن مناذر رثى بها عبد المجيد بن عبد الوهاب بن عبد المجيد الثقفي وكان يهواه وكان عبد المجيد هذا فيما يقال من أحسن الناس وجها وأدبا ولباسا وأكملهم في كل حال وكان على غاية المحبة لابن مناذر والمساعدة له والشغف به وكان يبلغ خبره أباه على جلالته وسنه وموضعه في العلم فلا ينكر ذلك لأنه لم تكن تبلغه عنه ريبة وكان ابن مناذر حينئذ حميد الأمر حسن المروءة عفيفا فحدثني الحسن بن علي قال حدثنا أحمد بن حدان قال حدثني قدامة بن نوح قال","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":2,"spl":"خلاعته وكره الناس له","tags":["الهجاء"],"loc":3201,"partialRef":{"sid":"b239-5","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b240-4","bab":"الجزء 18","sec":"خلاعته وكره الناس له","page":"ج18 ص177","text":"قيل لعبد الوهاب بن عبد المجيد الثقفي إن ابن مناذر قد أفسد ابنك وذكره في شعره وشبب به فقال عبد الوهاب أولا يرضى ابني أن يصحبه مثل ابن مناذر ويذكره في شعره\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد بن سليمان النوفلي قال أم عبد المجيد بن عبد الوهاب الثقفي الذي كان يشبب به ابن مناذر بانة بنت أبي العاصي وهي مولاة جنان التي يشبب بها أبو نواس\nقال فحدثني من رأى محمد بن مناذر يوم ثالث بانة هذه وقد خرج جواريها إلى قبرها فخرج معهن نحو الجبانة بالبصرة قال فقلت له يا أبا عبد الله أين تريد فقال\n(اليوم يوم الثلاثا ... ويوم ثالث بانه)\n(اليوم تكثر فيه الظباء ... في الجبانه)\nال أبو الحسن ولدت بانة من عبد الوهاب بن عبد المجيد أولاده عبد المجيد وأبا العاصي وزيادا وزياد الذي عناه أبو نواس في قوله يشبب بجنان\n(جفن عيني قد كاد يسقط ... من طول ما اختلج)\n(وفؤادي من حر حبك ... قد كاد أو نضج)\n(خبريني فدتك نفسي ... وأهلي متى الفرج)\n(كان ميعادنا خروج ... زياد فقد خرج)\nقال ابن عمار قال لي النوفلي في هذه الأبيات غناء حلو مليح لو سمعته لشربت عليه أربعة أرطال\nقال النوفلي وكان لعبد الوهاب ابن يقال له محمد كان أسن ولده ويقال إنه كان يتعشق بانة ابنة أبي العاصي هذه امرأة ابيه وإن زياد بن عبد الوهاب منه وكان أشبه الناس به\nحدثني ابن عمار قال حدثنا عمر بن شبة قال حدثني أبي قال خرج ابن مناذر يوما من صلاة التراويح وهو في المسجد بالبصرة وخرج عبد المجيد بن عبد الوهاب خلفه فلم يزل يحدثه إلى الصبح وهما قائمان إذا انصرف عبد المجيد شيعة ابن مناذر إلى منزله فإذا بلغه وانصرف ابن مناذر شيعة عبد المجيد لا يطيب أحدهما نفسا بفراق صاحبه حتى أصبحا فقيل لعبد الوهاب بن عبد المجيد ابن مناذر قد أفسد ابنك فقال أو ما يرضي ابني أن يرضى بما يرضى به ابن مناذر","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":3,"spl":"خلاعته وكره الناس له","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3202},
{"id":"b240-5","bab":"الجزء 18","sec":"ابن مناذر وعبد المجيد بن عبد الوهاب","page":"ج18 ص182","text":"وفي عبد المجيد يقول ابن مناذر يمدحه وهو من مختار ما قاله فيه أنشدنيها علي بن سليمان الأخفش عن محمد بن زيد من قصيدة أولها\n(شيب ريب الزمان رأسي ... لهفي على ريب ذا الزضمان)\n(يقدح في الصم من شرورى ... ويحدر الصم من أبان)\nقول فيها يمدح عبد المجيد\n(مني إلي الماجد المرجى ... عبد المجيد الفتى الهجان)\n(خير ثقيف أبا ونفسا ... إذا التقت حلقتا البطان)\n(نفسي فداء له وأهلي ... وكل ما تملك اليدان)\n(كأن شمس الضحى وبدر الدجى ... عليه معلقان)\n(نيطا معا فوق حاجبيه ... والبدر والشمس يضحكان)\n(مشمر همه المتعالي ... ليس برث ولا بواني)\n(بنى له عزة ومجدا ... في أول الدهر بانيان)\n(بان تلقاه من ثقيف ... ومن ذرا الأزد خير باني)\n(فاسأله مما حوت يداه ... يهتز كالصارم اليماني)\nخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة صالح بن محمد قال مرض عبد المجيد بن عبد الوهاب الثقفي مرضا شديدا بالبصرة وكان ابن مناذر ملازما له يمرضه ويخدمه ويتولى أمره بنفسه لا يكله إلى أحد فحدثني بعض أهلهم\nقال حضرت يوما عنده وقد أسخن له ماء حار ليشربه واشتد به الأمر فجعل يقول آه بصوت ضعيف فغمس ابن مناذر يده في الماء الحار وجعل يتأوه مع عبد المجيد ويده تحترق حتى كادت يده تسقط فجذبناها وأخرجناها من الماء وقلنا له أمجنون أنت أي شيء هذا أينتفع به ذاك فقال أساعده وهذا جهد من مقل ثم استقل من علته تلك وعوفي مدة طويلة ثم تردى من سطح فمات فجزع عليه جزعا شديدا حتى كاد يفضل أهله وإخوته في البكاء والعويل وظهر منه من الجزع ما عجب الناس له ورثاه بعد ذلك بقصيدته المشهورة فرواها أهل البصرة ونيح بها على عبد المجيد وكان الناس يعجبون بها ويستحسنونها أخبرني الحسن بن علي قال حدثنا محمد بن القاسم النوشجاني قال سمعت أبي يقول\nحضرت سفيان بن عيينة يقول لابن مناذر أنشدني ما قلت في عبد المجيد فأنشده قصيدته الطويلة الدالية قال سفيان بارك الله فيك فلقد تفردت بمراثي أهل العراق فأخبرني عمي\nقال حدثني أبو هفان قال قال الجماز تزوج عبد المجيد امرأة من أهله فأولم عليها شهرا يجتمع عنده في كل يوم وجوه أهل البصرة وأدباؤها وشعراؤها فصعد ذات يوم إلى السطح فرأى طنبا من أطناب الستارة قد انحل فأكب عليه ليشده فتردى على رأسه ومات من سقطته فما رأيت مصيبة قط كانت أعظم منها ولا أنكأ للقلوب\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني الحسن بن عليل العنزي قال حدثني العباس بن عبد الواحد بن جعفر بن سليمان قال حدثني محمد بن عمر الخراز\nقال قال لي ابن مناذر ويحك لست أرى نساء ثقيف ينحن على عبد المجيد نياحة على استواء قلت فما تحب قال تخرج معي حتى أطارحك فطارحني القصيدة التي يقول فيها\n(إن عبد المجيد يوم تولى ... هد ركنا ما كان بالمهدود)\n(هد عبد المجيد ركني وقد كنت ... بركن أبوء منه شديد)\nقال فما زلت حتى حفظتها ووعيتها ووضعنا فيها لحنا فلما كان في الليلة التي يناح بها على عبد المجيد فيها صلينا العشاء الآخره في المسجد الجامع ثم خرجنا إلى دارهم وقد صعد النساء على السطح ينحن عليه فسكتن سكتة لهن فاندفعنا أنا وهو ننوح عليه فلما سمعننا أقبلن يلطمن\nويصحن حتى كدن ينقلبن من السطح إلى أسفل من شدة تشرفهن علينا وإعجابهن بما سمعنه منا وأصبح أهل المسجد ليس لهم حديث غيرنا وشاع الخبر بالبصرة وتحدث به الناس حتى نقل من مجلس إلى مجلس وأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال لي حدثني موسى بن حماد بن عبد الله القرشي قال حدثني محمد بن النعمان بن جبلة الباهلي قال لما قال ابن مناذر\n(لأقيمن مأتما كنجوم الليل ... زهرا يلطمن حر الخدود)\n(موجعات يبكين للكبد ... الحرى عليه وللفؤاد العميد)\nالت أم عبد المجيد والله لأبرن قسمه فأقامت مع أخوات عبد المجيد وجواربه مأتما عليه وقامت تصيح عليه واي ويه واي ويه فيقال إنها أول من فعل ذلك وقاله في الإسلام وأخبرني بهذا الخبر ابن عمار عن علي بن محمد النوفلي عن عمه أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد عن محمد بن عامر النخعي قال أنشدني محمد بن مناذر لنفسه يرثي عبد المجيد بن عبد الوهاب يقول\n(يا عين حق لك البكاء ... لحادث الرزء الجليل)\n(فابكي على عبد المجيد ... وأعولي كل العويل)","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":4,"spl":"ابن مناذر وعبد المجيد بن عبد الوهاب","tags":[],"loc":3203},
{"id":"b240-6","bab":"الجزء 18","sec":"ابن مناذر وعبد المجيد بن عبد الوهاب","page":"ج18 ص182","text":"(لا يبعد الله الفتى الله الفياض ... ذا الباع الطويل)\n(عجل الحمام به فود ... عنا وآذن بالرحيل)\n(لهفي على الشعر المعفر ... منك والخد الأسيل)\n(كسفت لفقدك شمسنا ... والبدر آذن بالأفول)\nحدثني عمي قال حدثنا الكراني قال حدثني النضر بن عمرو عن المازني قال حدثنا حيان أن ابن مناذر دفع قصيدته الدالية إليه وقال اعرضها على ابي عبيدة فأتيته وهو على باب أبي عمرو بن العلاء فقرأت عليه منها خمسة أبيات فلم تعجبه وقال دعني من هذا فإني قد تشاغلت بحفظ القرآن عنه وعن مثله قال وكان أبو عبيدة يبغضه ويعاديه لأنه هجاه أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال قال ابن مناذر قلت\n(يقدح الدهر في شماريخ رضوى ... )\nم مكثت حولا لا أدري بن أتممه فسمعت قائلا يقول هبود قلت وما هبود فقال لي جبيل في بلادنا فقلت\n(ويحط الصخور من هبود ... )\nال إسحاق وسمع أعرابي هذا البيت فقال ما أجهل قائله بهبود والله إنها لأكيمة ما توارى الخارىء فكيف يحط منها الصخور أخبرني عمي قال حدثنا الكراني قال حدثني أبو حاتم قال سمعت أبا مالك عمرو بن كركرة يقول أنشدني ابن مناذر قصيدته الدالية التي رثى فيها عبد المجيد فلما بلغ إلى قوله\n(يقدح الدهر في شماريخ رضوى ... ويحط الصخور من هبود)\nقلت له هبود أي شيء هو فقال جبل فقلت سخنت عينك هبود والله بئر باليمامة ماؤها ملح لا يشرب منه شيء خلقه الله وقد والله خريت فيها مرات فلما كان بعد مدة وقفت عليه في مسجد البصرة وهو ينشدها فلما بلغ هذا البيت أنشدها\n(ويحط الصخور من عبود ... )\nقلت له عبود أي شيء هو ذا فقال جبل بالشام فلعلك يا بن الزانية خريت عليه أيضا فضحكت ثم قلت لا ما خريت عليه ولا رأيته وانصرفت عنه وأنا أضحك أخبرني عمي قال حدثني الكراني عن العمري عن الهيثم بن عدي قال كان يحيى بن زياد يرمى بالزندقة وكان من أظرف الناس وأنظفهم فكان يقال أظرف من الزنديق وكان الحاركي واسمه محمد بن زياد يظهر الزندقة تظارفا فقال فيه ابن مناذر\n(يا بن زياد يا أبا جعفر ... أظهرت دينا غير ما تخفي)\n(مزندق الظاهر باللفظ في ... باطن إسلام فتى عف)\n(لست بزنديق ولكنما ... أردت أن توسم بالظرف)\nوقال فيه أيضا\n(يا أبا جعفر كأنك قد صرت ... على أجرد طويل الجران)\n(من مطايا ضوامر ليس يصهلن ... إذا ما ركبن يوم رهان)\n(لم يذللن بالسروج ولا أقرح ... أشداقهن جذب العنان)\n(قائمات مسومات لدى الجسر ... لأمثالكم من الفتيان)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل تينة عن ابن عائشة قال كان عتبة النحوي من أصحاب سيبويه وكان صاحب نحو فهما بما يشرحه ويفسره على مذاهب أصحابه وكان ابن مناذر يتعاطى ذلك ويجلس إليه قوم يأخذونه عنه فجلس عتبة قريبا من حلقته فتقوض الناس إليه وتركوا ابن مناذر فلما كان في يوم الجمعة الأخرى قام ابن مناذر من حلقته فوقف على عتبة ثم أنشأ يقول\n(قوموا بنا جميعا ... لحلقة العذاري)\n(تجمعن للشقاء ... إلى عتبة الخسار)\n(ما لي وما لعتبة ... إذ يبتغي ضراري)\nال فقام عتبة إليه فناشده ألا يزيد ومنع من كان يجلس إلى ابن مناذر من حضور حلقته وجلس هو بعيدا من ابن مناذر بعد ذلك حدثني عمي قال حدثنا الكراني قال حدثنا عيسى بن إسماعيل تينة قال كان لابن مناذر جار يقال له ابن عمير من المعتزلة فكان يسعى بابن\nمناذر إليهم ويسبه ويذكره بالفسق ويغريهم به فقال يهجوه\n(بنو عمير مجدهم دارهم ... وكل قوم فلهم مجد)\n(كأنهم فقع بدوية ... وليس لهم قبل ولا بعد)\n(بث عمير لؤمه فيهم ... فكلهم من لؤمه جعد)\nأخبرني بهذا الخبر الحسن بن علي عن ابن مهرويه عن النوفلي بمثله وزاد فيه وعبد الله بن عمير - أبو هؤلاء الذين هجاهم - أخو عبد الله بن عامر لأمه أمهما دجاجة بنت إسماعيل بن الصلت السلمي أخبرني هاشم بن محمد قال حدثنا الخليل بن أسد قال كان ابن مناذر من أحضر الناس جوابا قال له رجل ما شانك قال عظم في أنفي قال وسأله رجل يوما ما الجرباء فأومأ بيده إلى الأرض قال هذه يهزأ به وإنما الجرباء السماء","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":5,"spl":"ابن مناذر وعبد المجيد بن عبد الوهاب","tags":["الهجاء"],"loc":3204,"partial":1},
{"id":"b240-7","bab":"الجزء 18","sec":"ابن مناذر والخليل بن أحمد","page":"ج18 ص189","text":"أخبرني أحمد بن العباس العسكري المؤدب قال حدثنا الحسن بن عليل العنزي قال حدثني جعفر بن محمد عن دماذ قال دار بين الخليل بن أحمد وبين ابن مناذر كلام فقال له الخليل\nإنما أنتم معشر الشعراء تبع لي وأنا سكان السفينة إن قرظتكم ورضيت قولكم نفقتم وإلا كسدتم فقال ابن مناذر والله لأقولن في الخليفة قصيدة أمتدحه بها ولا أحتاج إليك فيها عنده ولا إلى غيرك فقال في الرشيد قصيدته التي أولها\n(ما هيج الشوق من مطوقة ... أوفت على بانة تغنينا)\nقول فيها\n(ولو سألنا بحسن وجهك يا ... هارون صوب الغمام أسقينا)\nال وأراد أن يفد بها إلى الرشيد فلم يلبث أن قدم الرشيد البصرة حاجا ليأخذ على طريق النباج وكان الطريق قديما فدخلها وعديله إبراهيم الحراني فتحمل عليه ابن مناذر بعثمان بن الحكم الثقفي وأبي بكر السلمي حتى أوصلاه إلى الرشيد فأنشده إياها فلما بلغ آخرها كان فيها بيت يفتخر فيه وهو\n(قومي تميم عند السماك لهم ... مجد وعز فما ينالونا)\nلما أنشده هذا البيت تعصب عليه قوم من الجلساء فقال له بعضهم يا جاهل أتفخر في قصيدة مدحت بها أمير المؤمنين وقال آخر هذه حماقة بصرية فكفهم عنه الرشيد ووهب له عشرين ألف درهم","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":6,"spl":"ابن مناذر والخليل بن أحمد","tags":["المديح"],"loc":3205},
{"id":"b240-8","bab":"الجزء 18","sec":"الرشيد يبعث له بجائزة وهو بالحجاز","page":"ج18 ص190","text":"أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال حدثني سهيل السلمي أن الرشيد استسقى في سنة قحط فسقي الناس فسر\nبذلك وقال لله در ابن مناذر حيث يقول\n(ولو سألنا بحسن وجهك يا ... هارون صوب الغمام أسقينا)\nسأل عن خبره فأخبر أنه بالحجاز فبعث إليه بجائزة أخبرني هاشم بن محمد الخزاعي عن محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثنا نصر بن علي الجهضمي قال حدثني محمد بن عباد المهلبي قال شهد بكر بن بكار عند عبيد الله بن الحسن بن الحصين بن الحر العنزي بشهادة فتبسم ثم قال له يا بكر مالك ولابن مناذر حيث يقول\n(أعوذ بالله من النار ... ومنك يا بكر بن بكار)\nفقال أصلح الله القاضي ذاك رجل ماجن خليع لا يبالي ما قال فقال له صدقت وزاد تبسمه وقبل شهادته وقام بكر وقد تشور وخجل قال العنزي فحدثني أبو غسان دماذ قال أنشدني ابن مناذر هذا الشعر الذي قاله في بكر بن بكار وهو\n(أعوذ بالله من النار ... ومنك يا بكر بن بكار)\n(يا رجلا ما كان فيما مضى ... لآل حمران بزوار)\n(ما منزل أحدثته رابعا ... معتزلا عن عرصة الدار)\n(ما تبرح الدهر على سوأة ... تطرح حبا للخشنشار)\n(يا معشر الأحداث يا ويحكم ... تعوذوا بالخالق الباري)\n(من حربة نيطت على حقوه ... يسعى بها كالبطل الشاري)\n(يوم تمنى أن في كفه ... أير أبي الخضر بدينار)\nال ابن مهرويه في خبره والخشنشار هو معاوية الزيادي المحدث ويكنى أبا الخضر وكان جميل الوجه وقال العنزي في حديثه حدثني إسحاق بن عبد الله الحمراني وقد سألته عن معنى هذا الشعر فقال الخشنشار غلام أمرد جميل الوجه كان في محلتنا وهذا لقبه وكان بكر بن بكار يتعشقه فكان يجيء إلى أبي فيذاكره الحديث ويجالسه وينظر إلى الخشنشار\nقال العنزي حدثني عمر بن شبة قال بلغني أن عبيد الله بن الحسن لقي ابن مناذر فقال له ويحك ما أردت إلى بكر بن بكار ففضحته وقلت فيه قولا لعلك لم تتحققه فبدأ ابن مناذر يحلف له بيمين ما سمعت قط أغلظ منها أن الذي قاله في بكر شيء يقوله معه كل من يعرف بكرا ويعرف الخشنشار ويجمع عليه ولا يخالفه فيه فانصرف عبيد الله مغموما بذلك قد بان فيه فلما بعد عنا\nقلت لابن مناذر برىء الله منك ويلك ما أكذبك أكل من يعرف بكر بن بكار يقول فيه مثل قولك حتى حلفت بهذه اليمين فقال سخنت عينك فإذا كنت أعمى القلب أي شيء أصنع أفتراني كنت أكذب نفسي عند القاضي إنما موهت عليه وحلفت له أن كل من يعرفها يقول مثل قولي وعنيت ما ابتدأت به من الشعر\nوهو قولي\n(أعوذ بالله من النار ... )\nفتعرف أنت أحدا يعرفهما أو يجهلهما إلا يقول كما قلت أعوذ بالله من النار إنما موهت على القاضي وأردت تحقيق قولي عنده قال مؤلف هذا الكتاب وبكر بن بكار رجل محدث قد روى عن ورقاء عن ابن أبي نجيح تفسير مجاهد وروى حديثا صالحا أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا بكر بن بكار عن عبد الله بن المحرز عن قتادة عن أنس أن النبي قال ( زينوا القرآن بأصواتكم\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني الأحوص بن الفضل البصري قال حدثنا ابن معاوية الزيادي وأبوه الخشنشار الذي يقول فيه ابن مناذر\n(تطرح حبا للخشنشار ... )\nال حدثني من لقي ابن مناذر بمكة فقال ألا تشتاق إلى البصرة فقال له أخبرني عن شمس الوزانين أعلى حالها قال نعم قال وثيق بن يوسف الثقفي حي قال نعم قال فغسان بن الفضل الغلابي حي قال نعم قال لا والله لا دخلتها ما بقي فيها واحد من الثلاثة قال وشمس الوزانين في طرف المربد بحضرة مسجد الأنصار في موضع حيطانه قصار\nلا تكاد الشمس تفارقه أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال كان محمد بن عبد الوهاب الثقفي أخو عبد المجيد يعادي محمد بن مناذر بسبب ميله إلى أخيه عبد المجيد وكان ابن مناذر يهجوه ويسبه ويقطعه وكل واحد منهما يطلب لصاحبه المكروه ويسعى عليه فلقي محمد بن عبد الوهاب ابن مناذر في مسجد البصرة ومعه دفتر فيه كتاب العروض بدوائره ولم يكن محمد بن عبد الوهاب يعرف العروض فجعل يلحظ الكتاب ويقرؤه فلا يفهمه وابن مناذر متغافل عن فعله ثم","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":7,"spl":"الرشيد يبعث له بجائزة وهو بالحجاز","tags":["السفر والحج"],"loc":3206,"partial":1},
{"id":"b240-9","bab":"الجزء 18","sec":"الرشيد يبعث له بجائزة وهو بالحجاز","page":"ج18 ص190","text":"قال له ما في كتابك هذا فخبأه في كمه وقال وأي شيء عليك مما فيه فتعلق به ولببه فقال له ابن مناذر يا أبا الصلت الله الله في دمي فطمع فيه وصاح يا زنديق في كمك الزندقة فاجتمع الناس إليه فأخرج الدفتر من كمه وأراهم إياه فعرفوا براءته مما قذفه به ووثبوا على محمد بن عبد الوهاب واستخفوا به وانصرف بخزي وقال ابن مناذر يهجوه\n(إذا أنت تعلقت ... بحبل من أبي الصلت)\n(تعلقت بحبل واهن ... القوة منبت)\n(إذا ما بلغ المجد ... ذوو الأحساب بالمت)\n(تقاصرت عن المجد ... بأمر رائب شخت)\n(فلا تسمو إلى المجد ... فما أمرك بالثبت)\n(فلا فرعك في العيدان ... عود ناضر النبت)\n(وما يبقي لكم ياقوم ... من أثلتكم نحتي)\n(فها فاسمع قريضا من ... رقيق حسن النعت)\n(يقول الحق إن قال ... ولا يرميك بالبهت)\n(وفي نعت لوجعاء ... قد استرخت من الفت)\n(فعندي لك يا مأبون ... مثل الفالج البختي)\n(عتل يعمل الكوم ... من السبت إلى السبت)\n(له فيشلة إن أد ... خلت واسعة الخرت)\n(وإلإ فاطل وجعاءك ... بالخضخاض والزفت)\n(ألم يبلغك تسآلي ... لدى العلامة المرت)\n(فقال الشيخ سرجويه ... داء المرء من تحت)\n(فخذ من ورق الدفلى ... وخذ من ورق القت)\n(وخذ من جعر كيسان ... ومن أظفار نسخت)\n(فغرغره به واسعط ... بذا في دائه أفتي)\nال ونسخت لقب أبي عبيدة وهو اسم من أسماء اليهود لقب به تعريضا بأن جده كان يهوديا وكان أبو عبيدة وسخا طويل الأظفار أبدا والشعر وكان يغضب من هذا اللقب\nفأخبرني الحسن بن علي عن ابن مهرويه عن علي بن محمد النوفلي قال لما قال ابن مناذر هذه الأبيات\n(إذا أنت تعلقت ... بحبل من أبي الصلت)\n(تعلقت بحبل واهن ... القوة منبت)\n(وقال الشيخ سرجويه ... داء المرء من تحت)\nبلغ ذلك سرجويه فجاء إلى محمد بن عبد الوهاب فوقف عليه في مجلسه وعنده جماعة من أهله وإخوانه وجيرانه فسلم عليه وكان أعجميا لا يفصح ثم\nقال له بركست كمن كفتم أن كسر مناذر كفت داء المرء من تحت فكاد القوم أن يفتضحوا من الضحك وصاح به محمد اعزب قبحك الله فظن أنه لم يقبل عذره فأقبل يحلف له مجتهدا ما\nقال ذاك ومحمد يصيح به ويلك اعزب عني وهو في الموت منه وكلما زاده من الصياح إليه زاده في العذر واجتهد في الأيمان وضحك الناس حتى غلبوا وقام محمد خجلا فدخل منزله وتفرقوا قال أبو الحسن النوفلي ثم مضى لذلك زمان وهجا أبو نعامة أبا عبد الله هريسة الكاتب فقال فيه\n(وروى شيخ تميم ... خالد أن هريسه)\n(يدخل الأصلع ذا الخرجين ... في جوف الكنيسه)\nلقي خالد بن الصباح هذا هريسة وكان يعاديه وأراد أن يخجله فحلف له مجتهدا أنه لم يقل فيه ما قاله أبو نعامة فقال هريسة يا بارد لم\nترد أن تعتذر إنما أردت أن تتشبه بابن مناذر ومحمد بن عبد الوهاب وبأبي الشمقمق وأحمد بن المعذل ولست من هؤلاء في شيء قرأت في بعض الكتب عن ابن أبي سعد قال حدثني أبو الخطاب الحسن بن محمد عن محمد بن إسحاق البلخي قال دخلت على ابن مناذر يوما وعنده رجل ضرير جالس عن يمينه ورجل بصير جالس عن شماله ساكت لا ينطق قال فقلت له ما خبرك فقال\n(بين أعمى وأخرس أخرس الله ... لسان الأعمى وأعمى البصيرا)\nال فوثبا فخرجا من عنده وهما يشتمانه","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":8,"spl":"الرشيد يبعث له بجائزة وهو بالحجاز","tags":["الهجاء","اللهو والمزاح"],"loc":3207},
{"id":"b240-10","bab":"الجزء 18","sec":"اخباره مع سفيان بن عيينة","page":"ج18 ص197","text":"ونسخت من كتاب ابن أبي الدنيا حدثني أبو محمد التميمي قال حدثني إبراهيم بن عبد الله عن الحسن بن علي قال كنا عند باب سفيان بن عيينة وقد هرب منا وعنده الحسن بن علي التختاخ ورجل من الحجبة ورجل من أصحاب الرشيد فدخل بهم وليس يأذن لنا فجاء ابن مناذر فقرب من الباب ثم رفع صوته فقال\n(بعمرو وبالزهري والسلف الألى ... بهم ثبتت رجلاك عند المقاوم)\n(جعلت طوال الدهر يوما لصالح ... ويوما لصباح ويوما لحاتم)\n(وللحسن التختاخ يوما ودونهم ... خصصت حسينا دون أهل المواسم)\n(نظرت وطال الفكر فيك فلم أجد ... رحاك جرت إلا لأخذ الدراهم)\nخرج سفيان وفي يده عصا وصاح خذوا الفاسق فهرب ابن مناذر منه وأذن لنا فدخلنا أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو بكر المؤدب قال حدثني محمد بن قدامة قال سمعت سفيان بن عيينة يقول لابن مناذر يا أبا عبد الله ما بقي أحد أخافه غيرك وكأني بك قد مت فرثيتني فلما مات سفيان بن عيينة قال ابن مناذر يرثيه\n(راحوا بسفيان على نعشه ... والعلم مكسوين أكفانا)\n(إن الذي غودر بالمنحنى ... هد من الإسلام أركانا)\n(لا يبعدنك الله من ميت ... ورثنا علما وأحزانا)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ قال حدثني شيخ من أهل الكوفة يقال له عوام قال سمعت سفيان بن عيينة وقد تكلم بكلام استحسن فسأله محمد بن مناذر أن يمليه عليه فتبسم سفيان وقال له هذا كلام سمعتك تتكلم به فاستحسنته فكتبته عنك قال وعلى ذلك أحب أن تمليه علي فإني إذا رويته عنك كان أنفق له من أن أنسبه إلى نفسي قال عوام وأنشدني ابن عائشة لابن مناذر يرثي سفيان بن عيينة بقوله\n(يجني من الحكمة نوارها ... ما تشتهي الأنفس ألوانا)\n(يا واحد الأمة في علمه ... لقيت من ذي العرش غفرانا)\n(راحوا بسفيان على نعشه ... والعلم مكسوين أكفانا)\nأخبرني علي بن سليمان قال حدثنا محمد بن يزيد عن محمد بن عامر الحنفي قال لما مات عبد المجيد بن عبد الوهاب خرج ابن مناذر إلى مكة وترك النسك وعاد للمجون والخلع وقال في هذا المعنى شعرا كثيرا حتى إذا مدح أو فخر لم يجعل افتتاح شعره ومباديه إلا المجون وحتى قال في مدحه للرشيد\n(هل عندكم رخصة عن الحسن البصري ... في العشق وابن سيرينا)\n(إن سفاها بذي الجلالة والشيبة ... ألا يزال مفتونا)\nقال أيضا في هذا المعنى\n(ألا يا قمر المسجد ... هل عندك تنويل)\n(شفائي منك - إن ... نولتني - شم وتقبيل)\n(سلا كل فؤاد و ... فؤادي بك مشغول)\n(لقد حملت من حبيك ... مالا يحمل الفيل)\nخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثنا العباس بن الفضل الربعي قال حدثني التوزي قال قال ابن مناذر ليونس النحوي يعرض به أخبرني عن جبل\nأتنصرف أم لا وكان يونس من أهلها فقال له قد عرفت ما أردت يا بن الزانية فانصرف ابن مناذر فأعد شهودا يشهدون عليه بذلك وصار إليه وسأله هل تنصرف جبل وعلم يونس ما أراد فقال له الجواب ما سمعته أمس","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":9,"spl":"اخباره مع سفيان بن عيينة","tags":["الحب والغزل","المديح"],"loc":3208},
{"id":"b240-11","bab":"الجزء 18","sec":"اخباره مع حجاج الصواف","page":"ج18 ص200","text":"أخبرني الحسن بن علي قال حدثنا يعقوب بن إسرائيل قال حدثني إسحاق بن محمد النخعي قال حدثني إسحاق بن عمرو السعدي قال حدثني الحجاج الصواف\nوأخبرني الحسن بن علي أيضا قال حدثني ابن مهرويه قال حدثني إسحاق بن محمد قال حدثني أمية بن أبي مروان قال حدثني حجاج الصواف الأعور قال خرجت إلى مكة فكان هجيراي في الطريق ابن مناذر وكان لي إلف وخدنا وصديقا فدخلت مكة فسألت عنه فقالوا لا يبرح المسجد فدخلت المسجد فالتمسته فوجدته بفناء زمزم وعنده أصحاب الأخبار والشعراء يكتبون عنه فسلمت وأنا أقدر أن يكون عنده من الشوق إلي مثل ما عندي فرفع رأسه فرد السلام ردا ضعيفا ثم رجع إلى القوم يحدثهم ولم يحفل بي فقلت في نفسي أتراه ذهبت عنه معرفتي فبينا أنا أفكر إذ طلع أبو الصلت بن عبد الوهاب الثقفي من باب بني شيبة داخلا المسجد فرفع رأسه فنظر إليه ثم أقبل علي فقال أتعرف هذا فقلت نعم هذا الذي يقول فيه من قطع الله لسانه\n(إذا أنت تعلقت ... بحبل من أبي الصلت)\n(تعلقت بحبل واهن ... القوة منبت)\nقال فتغافل عني وأقبل عليهم ساعة ثم أقبل علي فقال من أي البلاد أنت قلت من أهل البصرة فقال وأين تنزل منها قلت بحضرة بني عائش الصوافين قال أتعرف هناك ابن زانية يقال له حجاج الصواف قلت نعم تركته ينيك أم ابن زانية يقال له ابن مناذر فضحك وقام إلي فعانقني قال مؤلف هذا الكتاب ولابن مناذر هجاء في حجاج الصواف على سبيل العبث وهو قوله\n(إن ادعاء الحجاج في العرب ... عند ثقيف من أعجب العجب)\n(وهو ابن زان لألف زانية ... وألف علج معلهج النسب)\n(ولو دعاه داع فقال له ... يا ألأم الناس كلهم أجب)\n(إذا لقال الحجاج لبيك من ... داع دعاني بالحق لا الكذب)\n(ولو دعاه داع فقال له ... من المعلى في اللؤم قال أبي)\n(أبوه زان والأم زانية ... بنت زناة مهتوكة الحجب)\n(تقول عجل أدخل لنائكها ... اتركه في استي إن شئت أو ركبي)\n(من ناكني فيهما فأوسعني ... رهزا دراكا أعطيته سلبي)\n(هم حري النيك فابتغوا لحري ... أير حمار أقضي به أربي)\n(أحب أير الحمار وا بأبي ... فيشة أير الحمار وابأبي)\n(إذا رأته قالت فديتك يا ... قرة عيني ومنتهى طلبي)\n(إذا سمعت النهيق هاج حري ... شوقا إليه وهاج لي طربي)\n(يأخذني في أسافلي وحري ... مثل اضطرام الحريق في الحطب)\n(شكت إلى نسوة فقلن لها ... وهي تنادي بالويل والحرب)\n(كفي قليلا قالت وكيف وبي ... في جوف صدعي كحكة الجرب)\n(أرى أيور الرجال من عصب ... ليت أيور الرجال من خشب)\nخبرني الحسن بن علي قال حدثني أحمد بن محمد الرازي أبو عبد الله قال حدثني أبو بجير قال كان ابن مناذر يجلس إلى إسكاف بالبصرة فلا يزال يهجوه بالأبيات فيصيح من ذلك ويقول له أنا صديقك فاتق الله وأبق على الصداقة وابن مناذر يلح فقال الإسكاف فإني أستعين الله عليك وأتعاطى الشعر فلما أصبح غدا عليه ابن مناذر كما كان يفعل فأخذ يعبث به ويهجوه فقال الإسكاف\n(كثرت أبوته وقل عديده ... ورمى القضاء به فراش مناذر)\n(عبد الصبيريين لم تك شاعرا ... كيف ادعيت اليوم نسبة شاعر)\nشاع هذان البيتان بالبصرة ورواهما أعداؤه وجعلوا يتناشدونهما إذا رأوه فخرج من البصرة إلى مكة وجاور بها فكان هذا سبب هربه من البصرة أخبرني عمي قال حدثنا الكراني عن أبي حاتم قال قال ابن مناذر ما مر بي شيء قط أشد علي مما مر بي من قول أبي العسعاس في\n(كثرت أبوته وقل عديده ... ورمى القضاء به فراش مناذر)\nانظر بكم صنف قد هجاني في هذا البيت قبحه الله ثم منعني من مكافأته أنى لم أجد له نباهة فأغضها ولا شرفا فأهدمه ولا قدرا فأضعه أخبرني عمي قال حدثني الكراني قال حدثني بشر بن دحية الزيادي أبو معاوية قال سمعت ابن مناذر يقول إن الشعر ليسهل علي حتى لو شئت ألا أتكلم إلا بشعر لفعلت أخبرني هاشم بن محمد الخزاعي قال حدثنا العباس بن ميمون طايع قال حدثني بعض أصحابنا قال رأيت ابن مناذر بمكة وهو يتوكأ على رجل يمشي معه وينشد\n(إذا ما كدت أشكوها ... إلى قلبي لها شفعا)\n(ففرق بيننا دهر ... يفرق بين ما اجتمعا)\nقلت إن هذا لا يشبه شعرك فقال إن شعري برد بعدك أخبرني عيسى بن الحسين الوراق قال حدثنا أبو أيوب المديني قال حدثنا بعض أصحابنا أن محمد بن عبد الوهاب الثقفي تزوج امرأة من ثقيف يقال لها عمارة وكان ابن مناذر يعاديه فقال في ذلك","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":10,"spl":"اخباره مع حجاج الصواف","tags":["الهجاء"],"loc":3209},
{"id":"b240-12","bab":"الجزء 18","sec":"اخباره مع حجاج الصواف","page":"ج18 ص200","text":"(لما رأيت القصف والشاره ... والبز قد ضاقت به الحاره)\n(والآس والريحان يرمى به ... من فوق ذي الدارة والداره)\n(قلت لمن ذا قيل أعجوبة ... محمد زوج عماره)\n(لا عمر الله بها ربعه ... فإن عمارة بد كاره)\n(ويحك فري واعصبي فاك لي ... فهذه أختك فراره)\nال فوالله ما لبثت عنده إلا مديدة حتى هربت وكانت لها أخت قبلها متزوجة إلى بعض أهل البصرة ففركته وهربت منه فكانوا يعجبون من موافقة فعلها قول ابن مناذر قال أبو أيوب وحدثت أن أبا امية واسمه خالد - وهو الذي يقول فيه أبو نواس\n(أيها المقبلان من حكمان ... كيف خلفتما أبا عثمان)\n(وأبا أمية المهذب والماجد ... والمرتجى لريب الزمان)\nكان خطب امرأة من ثقيف ثم من ولد عثمان بن أبي العاصي فرد عنها وتصدى للقاضي أن يضمنه مالا من اموال اليتامى فلم يجبه إلى ذلك ولم يثق به فقال فيه ابن مناذر\n(أبا أمية لا تغضب علي فما ... جزاء ما كان فيما بيننا الغضب)\n(إن كان ردك قوم عن فتاتهم ... ففي كثير من الخطاب قد رغبوا)\n(قالوا عليك ديور ما تقوم بها ... في كل عام بها تستحدث الكتب)\n(وقد تقحم من خمسين غايتها ... مع أنه ذو عيال بعد ما انشعبوا)\n(وفي التي فعل القاضي فلا تجدن ... فليس في تلك لي ذنب ولا ذنب)\n(أردت أموال أيتام تضمنها ... وما يضمن إلا من له نشب)","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":11,"spl":"اخباره مع حجاج الصواف","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":3210},
{"id":"b240-13","bab":"الجزء 18","sec":"نماذج من شعره في الرثاء والهجاء والمدح","page":"ج18 ص205","text":"أخبرني محمد بن خلف وكيع قال حدثني أحمد بن زهير قال سمعت إبراهيم بن المنذر الخزامي يقول بلغ ابن مناذر عن ابن دأب قول قبيح قال فدعاني وقال اكتب\n(فمن يبغ الوصاة فإن عندي ... وصاة للكهول وللشباب)\n(خذوا عن مالك وعن ابن عون ... ولا ترووا أحاديث ابن داب)\n(ترى الغاوين يتبعون منها ... ملاهي من احاديث كذاب)\n(إذا التمست منافعها اضمحلت ... كما يرفض رقراق السحاب)\nال فرويت وافتضح بها ابن دأب قال الحزامي فلما قدمت العراق وجدتهم قد جعلوها\n(خذوا عن يونس وعن ابن عون ... )\nخبرني عمي قال حدثنا الكراني قال حدثنا أبو حاتم قال كان الرشيد قد وصل ابن مناذر مرات صلات سنية فلما مات الرشيد رثاه ابن مناذر فقال\n(من كان يبكي للعلا ... ملكا وللهمم الشريفه)\n(فليبك هارون الخليفة ... للخليفة والخليفة)\nخبرني محمد بن خلف وكيع قال حدثنا أحمد بن أبي خيثمة عن محمد بن سلام قال كان محمد بن طليق وسائر بني طليق أصدقاء لابن مناذر فلما ولي المهدي الخلافة استقضى خالد بن طليق وعزل عبيد الله بن الحسن بن الحر فقال ابن مناذر يهجو خالدا مجونا وخبثا منه\n(أصبح الحاكم يا للناس ... من آل طليق)\n(جالسا يحكم في النا ... س بحكم الجاثليق)\n(يدع القصد ويهوي ... في بنيات الطريق)\n(يا أبا الهيثم ما كنت ... لهذا بخليق)\n(لا ولا كنت لما حملت ... منه بمطيق)\n(حبله حبل غرور ... عنده غير وثيق)\nال ابن سلام فقلت لابن مناذر ويحك إذا بلغ إخوانك وأصدقاءك من آل طليق أنك هجوتهم ما يقولون لك وبأي شيء تعتذر إليهم فقال لا يصدقون إذا بلغهم أني هجوتهم بذلك لأنهم يثقون بي أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني الحسن بن عليل عن مسعود بن بشر قال حدثنا محمد بن مناذر قال كنت بمكة فاشتكيت فلم يعدني من قريش إلا بنو مخزوم وحدهم فقلت أمدحهم\n(جاءت قريش تعودني زمرا ... فقد وعى أجرها لها الحفظه)\n(ولم تعدني تيم وإخوتها ... وزارني الغر من بني يقظه)\n(لن يبرح العز منهم أبدا ... حتى تزول الجبال من قرظه)\nخبرني الحسن عن ابن مهرويه عن إسحاق بن محمد النخعي قال كنا عند ابن عائشة فقال لعبد الرحمن ابنه أنشدني مرثية ابن مناذر عبد المجيد فجعل ينشدها فكلما أتى على بيت استحسنه حتى أتى على هذا البيت\n(لأقيمن مأتما كنجوم الليل ... زهرا يخمشن حر الخدود)\nقال ابن عائشة هذا كلام لين كأنه من كلام المخنثين فلما أتى على هذا البيت\n(كنت لي عصمة وكنت سماء ... بك تحيا أرضي ويخضر عودي)\nفقال هذا بيتها ثم أنشد\n(إن عبد المجيد يوم تولى ... هد ركنا ما كان بالمهدود)\n(ما درى نعشه ولا حاملوه ... ما على النعش من عفاف وجود)\n(وأرانا كالزرع يحصدنا الدهر ... فمن بين قائم وحصيد)\nقال ابن عائشة أحصلنا زرعا يحصدنا الله فليس هذا من كلام المسلمين ألا ترى إلى قوله إنه يقول\n(يحكم الله ما يشاء فيمضي ... ليس حكم الإله بالمردود)\nخبرني محمد بن يحيى الصولي قال حدثني محمد بن موسى ولم يتجاوزه بالإسناد\nونسخت هذا الخبر من كتاب ابن أبي مريم الحاسب حدثني ابن القداح وعبد الله بن إبراهيم بن قدامة الجمحي قالا حدثنا ابن مناذر قال حج الرشيد بعد إيقاعه بالبرامكة وحج معه الفضل بن الربيع وكنت مضيقا مملقا فهيأت فيه قولا أجدت تنميقه وتنوقت فيه فدخلت إليه في يوم التروية وإذا هو يسأل عني ويطلبني فبدرني الفضل بن الربيع قبل أن أتكلم فقال يا أمير المؤمنين هذا شاعر البرامكة وما دحهم وقد كان البشر ظهر لي في وجهه لما دخلت فتنكر وعبس في وجهي فقال الفضل مره يا أمير المؤمنين أن ينشدك قوله فيهم\n(أتانا بنو الأملاك من آل برمك ... )\nقال لي أنشد فأبيت فتوعدني واكرهني فأنشدته\n(أتانا بنو الأملاك من آل برمك ... فيا طيب أخبار ويا حسن منظر)\n(إذا وردوا بطحاء مكة أشرقت ... بيحيى وبالفضل بن يحيى وجعفر)\n(فتظلم بغداد ويجلو لنا الدجى ... بمكة ما حجوا ثلاثة أقمر)\n(فما صلحت إلا لجود أكفهم ... وأرجلهم إلا لأعواد منبر)\n(إذا راض يحيى الأمر ذلت صعابه ... وحسبك من راع له ومدبر)\n(ترى الناس إجلالا له وكأنهم ... غرانيق ماء تحت باز مصرصر)","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":12,"spl":"نماذج من شعره في الرثاء والهجاء والمدح","tags":["المديح","اللهو والمزاح"],"loc":3211,"partial":1},
{"id":"b240-14","bab":"الجزء 18","sec":"نماذج من شعره في الرثاء والهجاء والمدح","page":"ج18 ص205","text":"ثم أتبعت ذلك بأن قلت كانوا أولياءك يا أمير المؤمنين أيام مدحتهم وفي طاعتك لم يلحقهم سخطك ولم تحلل بهم نقمتك ولم أكن في ذلك مبتدعا ولا خلا أحد من نظرائي من مدحهم وكانوا قوما قد أظلني فضلهم وأغناني رفدهم فأثنيت بما أولوا فقال يا غلام الطم وجهه فلطمت والله حتى سدرت وأظلم ما كان بيني وبين أهل المجلس ثم\nقال اسحبوه على وجهه ثم قال والله لأحرمنك ولا تركت أحدا يعطيك شيئا في هذا العام فسحبت حتى أخرجت وانصرفت وأنا أسوأ الناس حالا في نفسي وحالي وما جرى علي ولا والله ما عندي ما يقيم يومئذ قوت عيالي لعيدهم فإذا بشاب قد وقف علي ثم\nقال أعزز علي والله يا كبيرنا بما جرى عليك ودفع إلي صرة وقال تبلغ بما في هذه فظننتها دراهم فإذا هي مائة دينار - قال الصولي في خبره فإذا هي ثلاثمائة دينار - فقلت له من أنت جعلني الله فداءك\nقال أنا أخوك أبو نواس فاستعن بهذه الدنانير واعذرني فقبلتها وقلت وصلك الله يا أخي وأحسن جزاءك أخبرني الحسن بن علي قال حدثنا ابن مهرويه\nقال حدثنا يحيى بن الحسن الربيعي قال حدثنا أبو معاوية الغلابي قال قال سفيان بن عيينة كلمني ابن مناذر في أن أكلم له جعفر بن يحيى فكلمته له وقد كان ابن مناذر ترك الشعر فقال إن أحب أن يعود إلى الشعر أعطيته خمسين ألفا وإن أحب أن أعطيه على القراءة أعطيته عشرة آلاف فذكرت ذلك له فقال لي خذ لي على القراءة فإني لا آخذ على الشعر وقد تركته أخبرني عمي عن الكراني عن الرياشي قال قال العتبي جاءت قصيدة لا يدرى من قائلها فقال ابن مناذر\n(هذه الدهماء تجري فيكم ... أرسلت عمدا تجر الرسنا)\nقال الكراني وحدثني الرياشي قال سمعت خلف بن خليفة يقول قال لي ابن مناذر قال لي جعفر بن يحيى قل في وفي الرشيد شعرا تصف فيه الألفة بيننا فقلت\n(قد تقطع الرحم القريب وتكفر ... النعمى ولا كتقارب القلبين)\n(يدني الهوى هذا ويدني ذا الهوى ... فإذا هما نفس ترى نفسين)\nال مؤلف هذا الكتاب هذا أخذه من كلام رسول الله نقلا فإن ابن عيينة روى عن إبراهيم بن ميسرة عن طاوس عن ابن عباس أن النبي قال ( إن الرحم تقطع وإن النعم تكفر ولن ترى مثل تقارب القلوب\nخبرني هاشم بن محمد قال حدثنا العباس بن ميمون قال حدثنا سليمان الشاذكوني قال كنا عند سفيان بن عيينة فحدث عن ابن أبي نجيح عن مجاهد في قوله عز و جل ( قالوا سلاما\nقالوا سدادا قال فقال ابن مناذر وهو إلى جنبي التنزيل أبين من التفسير","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":13,"spl":"نماذج من شعره في الرثاء والهجاء والمدح","tags":["الحب والغزل","المديح"],"loc":3212},
{"id":"b240-15","bab":"الجزء 18","sec":"ابن مناذر وخبره مع أبي حية النميري","page":"ج18 ص210","text":"أخبرني عمي قال حدثنا الكراني عن أبي حاتم عن العتبي عن أبي معبد قال\nمر بنا أبو حية النميري ونحن عند ابن مناذر فقال لنا علام اجتمعتم فقلنا هذا شاعر المصر فقال له أنشدني فأنشده ابن مناذر فلما فرغ قال له أبو حية ألم أقل لك أنشدني فقالوا له أنشدنا أنت يا أبا حية فأنشدهم قوله\n(ألا حي من أجل الحبيب المغانيا ... لبسن البلى مما لبسن اللياليا)\n(إذا ما تقاضى المرء يوم وليلة ... تقاضاه شيء لا يمل التقاضيا)\nلما فرغ قال له ابن مناذر ما أرى في شعرك شيئا يستحسن فقال له ما في شعري شيء يعاب إلا استماعك إياه فكادا أن يتواثبا ثم افترقا أخبرني عمي قال حدثني الكراني عن ابن عائشة قال ولي خالد بن طليق القضاء بالبصرة وعيسى بن سليمان الإمارة بها فقال محمد بن مناذر يهجوهما بقوله\n(الحمد لله على ما أرى ... خالد القاضي وعيسى أمير)\n(لكن عيسى نوكه ساعة ... ونوك هذا منجنون يدور)\nقال في شيرويه الزيادي وشيرويه لقب واسمه أحمد وسأله حاجة فأبى أن يقضيها إلا على أن يمدحه\n(يا سمي النبي بالعربيه ... وسمي الليوث بالفارسيه)\n(إن غضبنا فأنت عبد ثقيف ... أو رضينا فأنت عبد أميه)\nغضب شيرويه وجعل يشتمه وشاع الشعر بالبصرة فكان بعد ذلك إذا قيل لشيرويه ابن مناذر عليك غضبان أو عنك راض يشتم من يقول له ذلك أخبرني الحسن بن القاسم الكوكبي قال حدثنا ابن أبي الدنيا قال سمعت محمد بن قدامة الجوهري يقول سمعت سفيان بن عيينة يقول لمحمد بن مناذر كأنك بي قد مت فرثيتني فلما مات قال ابن مناذر يرثيه\n(إن الذي غودر بالمنحنى ... هد من الإسلام أركانا)\n(راحوا بسفيان على نعشه ... والعلم مكسوين أكفانا)\n(لا يبعدنك الله من هالك ... ورثتنا علما وأحزانا)\nخبرنا عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا عبد الله بن مروان بن معاوية الفزاري قال حدثنا سفيان قال سمعت أعرابية تقول من يشتري مني الحزاة فقلت لها وما الحزاة قالت تشتريها النساء للطشة والخافية والإقلات قال عبد الله بن مروان فسألت ابن مناذر عن تفسير ذلك فقال الطشة وجع يصيب الصبيان في رؤوسهم كالزكام والخافية ما خفي من العلل المنسوبة إلى أذى الجن والإقلات قلة الولد وأنشدني ابن مناذر بعقب ذلك\n(بغاث الطير أكثرها فراخا ... وأم الصقر مقلات نزور)\nي قليلة الفراخ أخبرني محمد بن الحسن بن دريد قال حدثني أبو حاتم قال سمعت محمد بن مناذر يقول العذراء البتول والبتور والبتيل واحد\nوهي المنقطعة إلى ربها قال وسأله - يعني ابن مناذر - أبو هريرة الصيرفي بحضرتي فقال كيف تقول أما لا أو إمالا فقال له مستهزئا به أمالا ثم التفت إلي فقال أسمعت أعجب من هذه المسألة\nأخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني العباس بن الفضل الربعي قال حدثنا التوزي قال سألت أبا عبيدة عن اليوم الثاني من النحر ما كانت العرب تسميه\nقال ليس عندي من ذلك علم فلقيت ابن مناذر بمكة فأخبرته بذلك فعجب وقال أيسقط هذا عن مثل أبي عبيدة هي أربعة أيام متواليات كلها على الراء أولها يوم النحر والثاني يوم القر والثالث يوم النفر والرابع يوم الصدر فحدثته - يعني أبا عبيدة - فكتبه عن ابن مناذر وقد روى ابن مناذر الحديث المسند ونقله عنه المحدثون","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":14,"spl":"ابن مناذر وخبره مع أبي حية النميري","tags":["الحب والغزل","المديح"],"loc":3213},
{"id":"b240-16","bab":"الجزء 18","sec":"بعض روايات له","page":"ج18 ص213","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا الخليل بن أسد عن محمد بن مسعدة الدراع أبي الجهجاه قال حدثني محمد بن مناذر الشاعر قال حدثني سفيان الثوري عن الأغر عن وهب بن منبه قال كان يقال الحياء من الإيمان والمذى مكسور الميم مقصور من النفاق فقلت إن الناس يقولون المذاء فقال هو كما أخبرتك فقلت له وما المذا قال اللين في أمر النساء ومنه درع ماذي وعسل ماذي أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني\nإبراهيم بن عبد الله بن الجنيد قال حدثني حامد بن يحيى البلخي قال حدثني محمد بن مناذر الشاعر قال حدثني يحيى بن عبد الله بن مجالد عن الشعبي عن مسروق عن عبد الله قال لما نظر رسول الله يوم بدر إلى القتلى وهم مصرعون قال لأبي بكر لو أن أبا طالب حي لعلم أن أسيافنا قد أخذت بالأماثل يعني قول أبي طالب\n(كذبتم وبيت الله إن جد ما أرى ... لتلتبسن أسيافنا بالأماثل)\nخبرني محمد بن خلف قال حدثني إسحاق بن محمد النخعي قال حدثنا ابن مناذر حدثنا سفيان بن عيينة عن إسماعيل بن أبي خالد عن قيس بن أبي حازم\nقال قال علي عليه السلام ما قام بي من النساء إلا الحارقة أسماء قال ابن مناذر الحارقة التي تجامع على جنب أخبرني محمد بن عمران الصيرفي\nقال حدثنا الحسن بن عليل العنزي عن العباس بن عبد الواحد عن محمد بن عمرو عن محمد بن مناذر عن سفيان بن عيينة عن عمرو بن دينار عن طاوس عن أبي هريرة\nقال جاء الشيطان إلى عيسى قال ألست تزعم أنك صادق قال بلى قال فأوف على هذه الشاهقة فألق نفسك منها فقال ويلك ألم يقل الله يا بن آدم لا تبلني بهلاكك فإني أفعل ما أشاء\nأخبرني عيسى بن الحسين الوراق عن حماد بن إسحاق عن أبيه قال نظر محمد بن مناذر إلى غلام حسن الوجه في مسجد البصرة فكتب إليه بهذه الأبيات\n(وجدت في الآثار في بعض ما ... حدثنا الأشياخ في المسند)\n(مما روى الأعمش عن جابر ... وعامر الشعبي والأسود)\n(وما روى شعبة عن عاصم ... وقاله حماد عن فرقد)\n(وصية جاءت إلى كل ذي ... خد خلا من شعر أسود)\n(أن يقبلوا الراغب في وصلهم ... فاقبل فإني فيك لم أزهد)\n(نول فكم من جمرة ضمها ... قلبي من حبيك لم تبرد)\nلما قرأها الفتى ضحك وقلب الرقعة وكتب في ظهرها لست شاعرا فأجيبك ولا فاتكا فأساعدك وأنا أعوذ بالله ربك من شرك أخبرني محمد بن عمران الصيرفي\nقال حدثنا الحسن بن عليل العنزي قال حدثنا محمد بن عبد الله العبدي قال حدثنا علي بن المبارك الأحمر قال لقي أبو العتاهية ابن مناذر بمكة فجعل يمازحه ويضاحكه ثم دخل على الرشيد فقال يا أمير المؤمنين هذا ابن مناذر شاعر البصرة يقول قصيدة في سنة وأنا أقول في سنة مائتي قصيدة فقال الرشيد أدخله إلي فأدخله إليه وقدر أنه يضعه عنده فدخل فسلم ودعا فقال ما هذا الذي يحكيه عنك أبو العتاهية فقال ابن مناذر وما ذاك يا أمير المؤمنين قال زعم أنك تقول قصيدة في سنة وأنه يقول كذا وكذا قصيدة في السنة فقال يا أمير المؤمنين لو كنت أقول كما يقول\n(ألا يا عتبة الساعة ... أموت الساعة الساعة)\nقلت منه كثيرا ولكني الذي أقول\n(إن عبد المجيد يوم تولى ... هد ركنا ما كان بالمهدود)\n(ما درى نعشه ولا حاملوه ... ما على النعش من عفاف وجود)\nقال له الرشيد هاتها فأنشدنيها فأنشده فقال الرشيد ما كان ينبغي\nأن تكون هذه القصيدة إلا في خليفة أو ولي عهد ما لها عيب إلا أنك قلتها في سوقة وأمر له بعشرة آلاف درهم فكاد أبو العتاهية يموت غما وأسفا أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا إبراهيم بن الجنيد قال سألت يحيى بن معين عن محمد بن مناذر الشاعر فقال لم يكن بثقة ولا مأمون رجل سوء نفي من البصرة ووصفه بالمجنون والخلاعة فقلت إنما تكتب شعره وحكايات عن الخليل بن أحمد فقال هذا نعم وأما الحديث فلست أراه موضعا له","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":15,"spl":"بعض روايات له","tags":["الهجاء"],"loc":3214},
{"id":"b240-17","bab":"الجزء 18","sec":"خبر وفاته","page":"ج18 ص216","text":"أخبرني الحسن قال حدثني ابن مهرويه قال حدثني علي بن محمد النوفلي قال رأيت ابن مناذر في الحج سنة ثمان وتسعين ومائة قد كف بصره وتقوده جويرية حرة وهو واقف يشتري ماء قربة فرأيته وسخ الثوب والبدن فلما صرنا إلى البصرة أتتنا وفاته في تلك الأيام\nأخبرني عيسى بن الحسين الوراق قال حدثنا خلاد الأرقط قال تذاكرنا ابن مناذر في حلقة يونس فقدح فيه أكثر أهل الحلقة حتى نسبوه إلى الزندقة فلما صرت في السقيفة التي في مقدم المسجد سمعت قراءة قريبة من حائط القبلة فدنوت فإذا ابن مناذر قائم يصلي فرجعت إلى الحلقة فقلت لأهلها قلتم في الرجل ما قلتم وها هو ذا قائم يصلي حيث لا يراه إلا الله عز و جل أخبرني محمد بن جعفر الصيدلاني النحوي قال حدثنا أحمد بن القاسم البرقي قال حدثنا أحمد بن يعقوب قال حدثني أحمد بن يحيى\nالهذلي التمار عن عبد الله بن عبد الصمد الضبي قال كنا يوما جلوسا في حلقة هبيرة بن جرير الضبي إذ أقبل محمد بن مناذر في برد قد كسته إياه بانة بنت أبي العاصي فسلم علي وحدي ولم يعرف منهم أحدا ثم قام فجلس إلى أبي خيرة فخاطبه مخاطبة خفيفة وقام مغضبا فقال لي هبيرة من هذا فقلت محمد بن مناذر فقال إنا لله قوموا بنا فقام إلى أبي خيرة فقال له ماذا\nقال لك ابن مناذر قال سألني عن شيء وكنت مشغولا عنه فقال يا أبا خيرة إن العشائر تغبطنا لعلمك وما جعل الله عندك فنشدناك الله أن تكون لنا كما كان عرادة لبني نمير فإنه تعرض لجرير فهجاه فعمهم فقال\n(عرادة من بقية قوم لوط ... ألا تبا لما فعلوا تبابا)\nتدري من كان عندك آنفا قال لا قال ابن مناذر وما تعرض لأعراض قوم قط إلا هتكها وهتكهم فإذا جاءك يسألك عن شيء فأجبه ولا تعتل عليه بالبول ولا تطلب منه شيئا وكل ما أردت من جهته ففي مالي\nقال أفعل قال وكان أبوه خيرة إذا سأله إنسان عن شيء ولم يعطه شيئا يعتل عليه بالبول فما شعرنا من غد إلا بابن مناذر وقد أقبل فعلمنا أنه قصد أبا خيرة فأتيناه فلما رأى جمعنا استحيا منا وسلم علينا وتبسم ثم\nقال يا أبا خيرة قد قلت شعرا وقبيح بمثلي أن يسأل عنه فلا يدري ما فيه وإني ذكرت فيه إنسانا فشبهته بالأفار فأي شيء هو فاحمر وجه أبي خيرة واضطرب\nوقال هو التيس الوثاب الذي ينزو وقضيبه رخو فلا يصل فقال جزيت خيرا ووثب وهو يضحك فقمنا إليه وقلنا قد علمنا أنك عنيت هذا الشيخ فإن رأيت أن تهبه لنا فافعل فإنه شيخنا قال والله ما عنيت غيره وقد وهبته لكم وكرامة والله لا يسمع مني أحد ما قلت فيه ولا أذكره إلا بخير أبدا وإن كان قد أساء العشرة أمس\n\n(لا زلت تنشر أعيادا وتطويها ... تمضي بها لك أيام وتمضيها)\n(ولا تقضت بك الدنيا ولا برحت ... تطوي لك الدهر أياما وتفنيها)\nلشعر لأشجع السلمي والغناء لإبراهيم الموصلي ثاني ثقيل مطلق في مجرى البنصر وفيه لمحمد قريض لحن من الثقيل الأول وهو من مشهور غنائه ومختاره","topic":"أخبار ابن مناذر ونسبه","topicNo":240,"sp":16,"spl":"خبر وفاته","tags":["الهجاء","الجواري والنساء"],"song":1,"loc":3215},
{"id":"b241-1","bab":"الجزء 18","sec":"نسب أشجع وأخباره","page":"ج18 ص218","text":"أخبرني محمد بن عمران الصيرفي والحسن بن علي قالا حدثنا الحسن بن عليل العنزي قال حدثني علي بن الفضل السلمي قال كان أشجع بن عمرو السلمي يكنى أبا الوليد من ولد الشريد بن مطرود السلمي تزوج أبوه امرأة من أهل اليمامة فشخص معها إلى بلدها فولدت له هناك أشجع ونشأ باليمامة ثم مات أبوه فقدمت به أمه البصرة تطلب ميراث أبيه وكان له هناك مال فماتت بها وربي أشجع ونشأ بالبصرة فكان من لا يعرفه يدفع نسبه ثم كبر\nوقال الشعر وأجاد وعد في الفحول وكان الشعر يومئذ في ربيعة واليمن ولم يكن لقيس شاعر معدود فلما نجم أشجع وقال الشعر افتخرت به قيس وأثبتت نسبه وكان له أخوان أحمد وحريث ابنا عمرو وكان أحمد شاعرا ولم يكن يقارب أشجع ولم يكن لحريث شعر ثم خرج أشجع إلى الرقة والرشيد بها فنزل على بني سليم فتقبلوه وأكرموه ومدح البرامكة وانقطع إلى جعفر خاصة وأصفاه مدحه فأعجب به ووصله إلى الرشيد ومدحه فأعجب به أيضا فأثرى وحسنت حاله في أيامه وتقدم عنده","topic":"نسب أشجع وأخباره","topicNo":241,"sp":0,"spl":"نسب أشجع وأخباره","tags":["المديح"],"loc":3216},
{"id":"b241-2","bab":"الجزء 18","sec":"أخباره مع الرشيد","page":"ج18 ص219","text":"أخبرني محمد بن عمران قال حدثني العنزي قال حدثني\nصخر بن أسد السلمي قال حدثني أبي أسد بن جديلة قال حدثني أشجع السلمي قال شخصت من البصرة إلى الرقة فوجدت الرشيد غازيا ونالتني خلة فخرجت حتى لقيته منصرفا من الغزو وكنت قد اتصلت ببعض أهل داره فصاح صائح ببابه من كان ها هنا من الشعراء فليحضر يوم الخميس فحضرنا سبعة وأنا ثامنهم وأمرنا بالبكور في يوم الجمعة فبكرنا وأدخلنا وقدم واحد منا ينشد على الأسنان وكنت أحدث القوم سنا وأرثهم حالا فما بلغ إلي حتى كادت الصلاة أن تجب فقدمت والرشيد على كرسي وأصحاب الأعمدة بين يديه سماطان فقال لي أنشدني فخفت أن أبتدىء من أول قصيدتي بالتشبيب فتجب الصلاة ويفوتني ما أردت فتركت التشبيب وأنشدته من موضع المديح في قصيدتي التي أولها\n(تذكر عهد البيض وهو لها ترب ... وأيام يصبي الغانيات ولا يصبو)\nابتدأت قولي في المديح\n(إلى ملك يستغرق المال جوده ... مكارمه نثر ومعروفه سكب)\n(وما زال هارون الرضا بن محمد ... له من مياه النصر مشربها العذب)\n(متى تبلغ العيس المراسيل بابه ... بنا فهناك الرحب والمنزل الرحب)\n(لقد جمعت فيك الظنون ولم يكن ... بغيرك ظن يستريح له القلب)\n(جمعت ذوي الأهواء حتى كأنهم ... على منهج بعد افتراقهم ركب)\n(بثثت على الأعداء أبناء دربة ... فلم يقهم منهم حصون ولا درب)\n(وما زلت ترميهم بهم متفردا ... أنيساك حزم الرأي والصارم العضب)\n(جهدت فلم أبلغ علاك بمدحة ... وليس على من كان مجتهدا عتب)\nفضحك الرشيد وقال لي خفت أن يفوت وقت الصلاة فينقطع المديح عليك فبدأت به وتركت التشبيب وأمرني بأن أنشده التشبيب فأنشدته إياه فأمر لكل واحد من الشعراء بعشرة آلاف درهم وأمر لي بضعفها\nأخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثني أحمد بن سيار الجرجاني وكان راوية شاعرا مداحا ليزيد بن مزيد قال دخلت أنا وأشجع والتيمي وابن رزين الخراساني على الرشيد في قصر له بالرقة وكان قد ضرب أعناق قوم في تلك الساعة فجعلنا نتخلل الدماء حتى وصلنا إليه فأنشده أبو محمد التيمي قصيدة له يذكر فيها نقفور ووقعته ببلاد الروم فنثر عليه مثل الدر من جودة شعره وأنشده أشجع قوله\n(قصر عليه تحية وسلام ... ألقت عليه جمالها الأيام)\n(قصرت سقوف المزن دون سقوفه ... فيه لأعلام الهدى أعلام)\n(تثني على أيامك الأيام ... والشاهدان الحل والإحرام)\n(أدنتك من ظل النبي وصية ... وقرابة وشجت بها الأرحام)\n(برقت سماؤك في العدو وأمطرت ... هاما لها ظل السيوف غمام)\n(وإذا سيوفك صافحت هام العدى ... طارت لهن عن الرؤوس الهام)\n(وعلى عدوك يابن عم محمد ... رصدان ضوء الصبح والإظلام)\n(فإذا تنبه رعته وإذا غفا ... سلت عليه سيوفك الأحلام)\nأنشدته أنا قولي\n(زمن بأعلى الرقمتين قصير ... )\nتى انتهيت إلى قولي\n(لا تبعد الأيام إذ ورق الصبا ... خضل وإذ غض الشباب نضير)\nاستحسن هذا البيت ومضيت في القصيدة حتى أتممتها فوجه إلي الفضل بن الربيع أنفذ إلي قصيدتك فإني أريد أن أنشدها الجواري من استحسانه إياها\nقال وركب الرشيد يوما قبة وسعيد بن سالم معه في القبة فقال أين محمد البيذق وكان رجلا حسن الصوت ينشد الشعر فيطرب بحسن صوته أشد من إطراب الغناء فحضر فقال أنشدني قصيدة الجرجاني فأنشده فقال الشعر في ربيعة سائر اليوم فقال له سعيد بن سالم يا أمير المؤمنين استنشده قصيدة أشجع بن عمرو فأبى فلم يزل به حتى أجاب إلى استماعها فلما أنشده هذين البيتين\n(وعلى عدوك يابن عم محمد ... )\nالذي بعده قال له سعيد بن سالم والله يا أمير المؤمنين لو خرس بعد هذين لكان أشعر الناس أخبرني الحسن بن علي الخفاف قال حدثني محمد بن القاسم بن\nمهرويه قال حدثني أبي قال بلغني أن أشجع لما أنشد الرشيد هذين البيتين\n(وعلى عدوك يابن عم محمد ... )\nوالذي بعده طرب الرشيد وكان متكئا فاستوى جالسا وقال أحسن والله هكذا تمدح الملوك أخبرني أحمد بن إسحاق العسكري والحسن بن علي قالا حدثنا أحمد بن سعيد بن سالم الباهلي عن أبيه قال كنت عند الرشيد فدخل إليه أشجع ومنصور النمري فأنشده أشجع قوله\n(وعلى عدوك يابن عم محمد ... رصدان ضوء الصبح والإظلام)\n(فإذا تنبه رعته وإذا غفا ... سلت عليه سيوفك الأحلام)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":1,"spl":"أخباره مع الرشيد","tags":["المديح"],"loc":3217,"partial":1},
{"id":"b241-3","bab":"الجزء 18","sec":"أخباره مع الرشيد","page":"ج18 ص219","text":"استحسن ذلك الرشيد وأومأت إلى أشجع أن يقطع الشعر وعلمت أنه لا يأتي بمثلهما فلم يفعل ولما أنشده ما بعدهما فتر الرشيد وضرب بمخصرة كانت بيده الأرض واستنشد منصورا النمري فأنشده قوله\n(ما تنقضي حسرة مني ولا جزع ... إذا ذكرت شبابا ليس يرتجع)\nفمر والله في قصيدة قل ما تقول العرب لها فجعل الرشيد يضرب بمخصرته الأرض ويقول الشعر في ربيعة سائر اليوم فلما خرجنا قلت لأشجع غمزتك أن تقطع فلم تفعل ويلك ولم تأت بشيء فهلا مت بعد البيتين أو خرست فكنت تكون أشعر الناس","topic":"نسب أشجع وأخباره","topicNo":241,"sp":2,"spl":"أخباره مع الرشيد — أخباره مع جعفر بن يحيى","tags":[],"loc":3218},
{"id":"b241-4","bab":"الجزء 18","sec":"أخباره مع جعفر بن يحيى","page":"ج18 ص224","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثني موسى بن عيسى قال اشترى جعفر بن يحيى المرغاب من آل الرشيد بعشرين ألف ألف درهم ورده على أصحابه فقال أشجع السلمي يمدحه بذلك ويقول\n(رد السباخ ندى يديه وأهلها ... منها بمنزلة السماك الأعزل)\n(قد أيقنوا بذهابها وهلاكهم ... والدهر يوعدهم بيوم أعضل)\n(فافتكها لهم وهم من دهرهم ... بين الجران وبين حد الكلكل)\n(ما كان يرجى غيره لفكاكها ... يرجى الكريم لكل خطب معضل)\nأخبرني الحسن بن علي قال حدثني أحمد بن محمد حران عن قدامة بن نوح قال جلس جعفر بن يحيى بالصالحية يشرب على مستشرف له فجاءه\nأعرابي من بني هلال فاشتكى واستماح بكلام فصيح ولفظ مثله يعطف المسؤول فقال له جعفر بن يحيى أتقول الشعر يا هلالي فقال قد كنت أقوله وأنا حدث أتملح به ثم تركته لما صرت شيخا قال فأنشدنا لشاعركم حميد بن ثور فانشده قوله\n(لمن الديار بجانب الحمس ... كمحط ذي الحاجات بالنفس)\nتى أتى على آخرها فاندفع أشجع فأنشده مديحا له فيه قاله لوقته على وزنها وقافيتها فقال\n(ذهبت مكارم جعفر وفعاله ... في الناس مثل مذاهب الشمس)\n(ملك تسوس له المعالي نفسه ... والعقل خير سياسة النفس)\n(فإذا تراءته الملوك تراجعوا ... جهر الكلام بمنطق همس)\n(ساد البرامك جعفر وهم الألى ... بعد الخلائف سادة الإنس)\n(ما ضر من قصد ابن يحيى راغبا ... بالسعد حل به أم النحس)\nقال له جعفر صف موضعنا هذا فقال\n(قصور الصالحية كالعذارى ... لبسن ثيابهن ليوم عرس)\n(مطلات على بطن كسته ... أيادي الماء وشيا نسج غرس)\n(إذا ما الطل أثر في ثراه ... تنفس نوره من غير نفس)\n(فتغبقه السماء بصبغ ورس ... وتصبحه بأكؤس عين شمس)\nقال جعفر للأعرابي كيف ترى صاحبنا يا هلالي فقال أرى خاطره طوع لسانه وبيان الناس تحت بيانه وقد جعلت له ما تصلني به قال بل نقرك يا أعرابي ونرضيه وأمر للأعرابي بمائة دينار ولأشجع بمائتين\nأخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني أبو دعامة قال حدثني أشجع السلمي قال كنت ذات يوم في مجلس بعض إخواني أتحدث وأنشد إذ دخل عليهم أنس بن أبي شيخ النصري صاحب جعفر بن يحيى فقام له جميع القوم غيري ولم أعرفه فأقوم له فنظر إلي\nوقال من هذا الرجل قالوا أشجع السلمي الشاعر قال أنشدني بعض قولك فأنشدته فقال إنك لشاعر فما يمنعك من جعفر بن يحيى فقلت ومن لي بجعفر بن يحيى فقال أنا فقل أبياتا ولا تطل فإنه يمل الإطالة فقلت لست بصاحب إطالة فقلت أبياتا على نحو ما رسم لي وصرت إلى أنس فقال تقدمني إلى الباب فتقدمت فلم يلبث أن جاء فدخل وخرج أبو رمح الهمذاني حاجب جعفر بن يحيى فقال أشجع فقمت فقال ادخل فدخلت فاستنشدني فأنشدته أقول\n(وترى الملوك إذا رأيتهم ... كل بعيد الصوت والجرس)\n(فإذا بدا لهم ابن يحيى جعفر ... رجعوا الكلام بمنطق همس)\n(ذهبت مكارم جعفر وفعاله ... في الناس مثل مذاهب الشمس)\nقال فأمر له بعشرة آلاف درهم قال وكان أشجع يحب الثياب وكان يكتري الخلعة كل يوم بدرهمين فيلبسها أياما ثم يكتري غيرها فيفعل بها مثل ذلك قال فابتعت أثوابا كثيرة بباب الكرخ فكسوت عيالي وعيال إخوتي حتى أنفقتها","topic":"نسب أشجع وأخباره","topicNo":241,"sp":2,"spl":"أخباره مع الرشيد — أخباره مع جعفر بن يحيى","tags":["المديح"],"loc":3219},
{"id":"b241-5","bab":"الجزء 18","sec":"أشجع والفضل بن يحيى","page":"ج18 ص227","text":"ثم لقيت المبارك مؤدب الفضل بن يحيى بعد أيام فقال لي أنشدني ما قلته في جعفر فأنشدته فقال ما يمنعك من الفضل فقلت ومن لي بالفضل فقال أنا لك به فأدخلني عليه فأنشدته\n(وما قدم الفضل بن يحيى مكانه ... على غيره بل قدمته المكارم)\n(لقد أرهب الأعداء حتى كأنما ... على كل ثغر بالمنية قائم)\nقال لي كم أعطاك جعفر فقلت عشرة آلاف درهم فقال أعطوه عشرين ألفا أخبرني علي بن صالح قال حدثني أحمد بن أبي فنن قال حدثني داود بن مهلهل قال لما خرج جعفر بن يحيى ليصلح أمر الشام نزل في مضربه وأمر بإطعام الناس فقام أشجع فأنشده قوله\n(فئتان باغية وطاغية ... جلت أمورهما عن الخطب)\n(قد جاءكم بالخيل شازبة ... ينقلن نحوكم رحى الحرب)\n(لم يبق إلا أن تدور بكم ... قد قام هاديها على القطب)\nال فأمر له بصلة ليست بالسنية وقال له دائم القليل خير من\nمنقطع الكثير فقال له ونزره أكثر من جزيل غيره فأمر له بمثلها قال وكان يجري عليه في كل جمعة مائة دينار مدة مقامه ببابه أخبرني محمد بن النحوي صهر المبرد\nقال حدثني الفضل بن محمد اليزيدي قال حدثنا إسحاق الموصلي قال دخلت إلى الرشيد يوما وهو يخاطب جعفر بن يحيى بشيء لم أسمع ابتداءه وقد علا صوته فلما رآني مقبلا\nقال لجعفر بن يحيى أترضى بإسحاق قال جعفر والله ما في علمه مطعن إن أنصف فقال لي أي شيء تروي للشعراء المحدثين في الخمر أنشدني من أفضل ما عندك وأشده تقدما فعلمت أنهما كانا يتماريان في تقديم أبي نواس فعدلت عنه إلى غيره لئلا أخالف أحدهما فقلت لقد أحسن أشجع في قوله\n(ولقد طعنت الليل في أعجازه ... بالكأس بين غطارف كالأنجم)\n(يتمايلون على النعيم كأنهم ... قضب من الهندي لم تتثلم)\n(وسعى بها الظبي الغرير يزيدها ... طيبا ويغشمها إذا لم تغشم)\n(والليل منتقب بفضل ردائه ... قد كاد يحسر عن أغر أرثم)\n(فإذا أدارتها الأكف رأيتها ... تثني الفصيح إلى لسان الأعجم)\n(وعلى بنان مديرها عقيانة ... من سكبها وعلى فضول المعصم)\n(تغلي إذا ما الشعريان تلظيا ... صيفا وتسكن في قلوع المرزم)\n(ولقد فضضناها بخاتم ربها ... بكرا وليس البكر مثل الأيم)\n(ولها سكون في الإناء وخلفها ... شغب يطوح بالكمي المعلم)\n(تعطي على الظلم الفتى بقيادها ... قسرا وتظلمه إذا لم يظلم)\nقال لي الرشيد قد عرفت تعصبك على أبي نواس وإنك عدلت عنه متعمدا ولقد أحسن أشجع ولكنه لا يقول أبدا مثل قول أبي نواس\n(يا شقيق النفس من حكم ... نمت عن ليلي ولم أنم)\nقلت له ما علمت ما كنت فيه يا أمير المؤمنين وإنما أنشدت ما حضرني فقال حسبك قد سمعت الجواب قال الفضل وكان في إسحاق تعصب على أبي نواس لشيء جرى بينهما","topic":"نسب أشجع وأخباره","topicNo":241,"sp":3,"spl":"أشجع والفضل بن يحيى","tags":["الوصف والطبيعة"],"loc":3220},
{"id":"b241-6","bab":"الجزء 18","sec":"شعر أشجع يطرب الواثق","page":"ج18 ص229","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال اصطبح الواثق في يوم مطير واتصل شربه وشربنا معه حتى سقطنا لجنوبنا صرعى وهو معنا على حالنا فما حرك أحد منا عن مضجعه وخدم الخاصة يطوفون علينا ويتفقدوننا وبذلك أمرهم\nوقال لا تحركوا أحدا عن موضعه فكان هو أول من أفاق منا فقام وأمر بإنباهنا فأنبهنا فقمنا فتوضأنا وأصلحنا من شأننا وجئت إليه وهو جالس وفي يده كأس وهو يروم شربها والخمار يمنعه فقال لي يا إسحاق أنشدني في هذا المعنى شيئا فأنشدته قول أشجع السلمي\n(ولقد طعنت الليل في أعجازه ... بالكأس بين غطارف كالأنجم)\n(يتمايلون على النعيم كأنهم ... قضب من الهندي لم تتثلم)\n(وسعى بها الظبي الغرير يزيدها ... طيبا ويغشمها إذا لم تغشم)\n(والليل منتقب بفضل ردائه ... قد كان يحسر عن أغر أرثم)\n(وإذا أدارتها الأكف رأيتها ... تثني الفصيح إلى لسان الأعجم)\n(وعلى بنان مديرها عقيانة ... من لونها وعلى فضول المعصم)\n(تغلي إذا ما الشعريان تلظيا ... صيفا وتسكن في طلوع المرزم)\n(ولقد فضضناها بخاتم ربها ... بكرا وليس البكر مثل الأيم)\n(ولها سكون في الإناء وخلفها ... شغب يطوح بالكمي المعلم)\n(تعطي على الظلم الفتى بقيادها ... قسرا وتظلمه إذا لم يظلم)\nطرب وقال أحسن والله أشجع وأحسنت يا أبا محمد بحياتي فأعدتها وشرب كأسه وأمر لي بألف دينار أخبرني جعفر بن قدامة قال حدثنا أبو هفان قال ذكر أبو دعامة أن أشجع دخل على الفضل بن الربيع وقد توفي ابنه العباس والناس يعزونه فعزاه فأحسن ثم استأذنه في إنشاد مرثية قالها فيه فأذن له فأنشده\n(لا تبكين بعين غير جائدة ... وكل ذي حزن يبكي كما يجد)\n(أي امريء كان عباس لنائبة ... إذا تقنع دون الوالد الولد)\n(لم يدنه طمع من دار مخزية ... ولم يعز له من نعمة بلد)\n(قد كنت ذا جلد في كل نائبة ... فبان مني عليك الصبر والجلد)\n(لما تسامت بك الآمال وابتهجت ... بك المروءة واعتدت بك العدد)\n(ولم يكن لفتى في نفسه أمل ... إلا إليك به من أرضه يفد)\n(وحين جئت أمام السابقين ولم ... يبلل عذارك ميدان ولا أمد)\n(وافاك يوم على نكراء مشتمل ... لم ينج من مثله عاد ولا لبد)\n(فما تكشف إلا عن مولولة ... حرى ومكتئب أحشاؤه تقد)\nال فبكى الفضل وبكى الناس معه وما انصرفوا يومئذ يتذاكرون غير أبيات أشجع أخبرني الحرمي بن أبي العلاء قال حدثنا الحسن بن محمد بن طالب الديناري قال حدثني علي بن الجهم قال دخل أشجع على الرشيد وقد مات ابن له والناس يعزونه فأنشده قوله\n(نقص من الدين ومن أهله ... نقص المنايا من بني هاشم)\n(قدمته - فاصبر على فقده - ... إلى أبيه وأبي القاسم)\nقال الرشيد ما عزاني اليوم أحد أحسن من تعزية أشجع وأمر له بصلة أخبرني الحسن بن علي قال حدثنا العنزي قال حدثني عبد الرحمن بن النعمان السلمي قال كنا بباب جعفر بن يحيى وهو عليل فقال لنا الحاجب إنه لا إذن عليه فكتب إليه أشجع\n(لما اشتكى جعفر بن يحيى ... فارقني النوم والقرار)\n(ومر عيشي علي حتى ... كأنما طعمه المرار)\n(خوفا على جعفر بن يحيى ... لا حقق الخوف والحذار)\n(إن يعفه الله لا نحاذر ... ما أحدث الليل والنهار)\nال فأوصل الحاجب رقعته ثم خرج فأمره بالوصول وحده وانصرف سائر الناس\nأخبرني الحسن قال حدثنا العنزي قال حدثني محمد بن الحسين عن عمرو بن علي أن أشجع السلمي كتب إلى الرشيد وقد أبطأ عنه شيء أمر له به\n(أبلغ أمير المؤمنين رسالة ... لها عنق بين الرواة فسيح)\n(بأن لسان الشعر ينطقه الندى ... ويخرسه الإبطاء وهو فصيح)\nضحك الرشيد وقال له لن يخرس لسان شعرك وأمر له بتعجيل صلته","topic":"نسب أشجع وأخباره","topicNo":241,"sp":4,"spl":"شعر أشجع يطرب الواثق","tags":[],"loc":3221},
{"id":"b241-7","bab":"الجزء 18","sec":"مدحه محمد بن منصور","page":"ج18 ص232","text":"أخبرني الحسن ومحمد بن يحيى الصولي قالا حدثنا العنزي قال حدثني أحمد بن محمد بن منصور بن زياد وكان يقال لأبيه فتى العسكر قال أقبل أشجع إلى باب أبي فرأى ازدحام الناس عليه فقال\n(على باب ابن منصور ... علامات من البذل)\n(جماعات وحسب الباب ... نبلا كثرة الأهل)\nفبلغ أبي بيتاه هذان فقال هما والله أحب مدائحه إلي أخبرني عمي والحسن بن علي قال حدثنا الفضل بن محمد اليزيدي قال حدثنا إسحاق بن إبراهيم الموصلي قال\nلما ولى الرشيد جعفر بن يحيى خراسان جلس للناس فدخلوا عليه يهنئونه ثم دخل الشعراء فأنشدوه فقام أشجع آخرهم فاستأذن في الإنشاد فأذن له فأنشده قوله\n(أتصبر للبين أم تجزع ... فإن الديار غدا بلقع)\n(غدا يتفرق أهل الهوى ... ويكثر باك ومسترجع)\nتى انتهى إلى قوله\n(ودوية بين أقطارها ... مقاطيع أرضين لا تقطع)\n(تجاوزتها فوق عيرانة ... من الريح في سيرها أسرع)\n(إلى جعفر نزعت رغبة ... وأي فتى نحوه تنزع)\n(فما دونه لامرىء مطمع ... ولا لامرىء غيره مقنع)\n(ولا يرفع الناس من حطه ... ولا يضعون الذي يرفع)\n(يريد الملوك مدى جعفر ... ولا يصنعون كما يصنع)\n(وليس بأوسعهم في الغنى ... ولكن معروفه أوسع)\n(تلوذ الملوك بآرائه ... إذا نالها الحدث الأفظع)\n(بديهته مثل تدبيره ... متى رمته فهو مستجمع)\n(وكم قائل إذ رأى ثروتي ... وما في فضول الغنى أصنع)\n(غدا في ظلال ندى جعفر ... يجر ثياب الغنى أشجع)\n(فقل لخراسان تحيا فقد ... أتاها ابن يحيى الفتى الأروع)\nأقبل عليه جعفر بن يحيى ضاحكا واستحسن شعره وجعل يخاطبه\nمخاطبة الأخ أخاه ثم أمر له بألف دينار قال ثم بدا للرشيد في ذلك التدبير فعزل جعفرا عن خراسان بعد أن أعطاه العهد والكتب وعقد له العقد وأمر ونهى فوجم لذلك جعفر فدخل عليه أشجع فأنشده يقول\n(أمست خراسان تعزى بما ... أخطأها من جعفر المرتجى)\n(كان الرشيد المعتلى أمره ... ولى عليها المشرق الأبلجا)\n(ثم أراه رأيه أنه ... أمسى إليه منهم أحوجا)\n(فكم به الرحمن من كربة ... في مدة تقصر قد فرجا)\nضحك جعفر ثم قال لقد هونت علي العزل وقمت لأمير المؤمنين بالعذر فسلني ما شئت فقال قد كفاني جودك ذلة السؤال فأمر له بألف دينار آخر","topic":"نسب أشجع وأخباره","topicNo":241,"sp":5,"spl":"مدحه محمد بن منصور","tags":["الحب والغزل"],"loc":3222},
{"id":"b241-8","bab":"الجزء 18","sec":"مدحه محمد الأمين وهو طفل","page":"ج18 ص234","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد عن أبي دعامة عن أشجع قال دخلت على محمد الأمين حين أجلس مجلس الأدب للتعليم وهو ابن أربع سنين وكان يجلس فيه ساعة ثم يقوم فأنشدته\n(ملك أبوه وأمه من نبعة ... منها سراج الأمة الوهاج)\n(شربت بمكة في ربا بطحائها ... ماء النبوة ليس فيه مزاج)\nيعني النبعة قال فأمرت له زبيدة بمائة ألف درهم قال ولم\nيملك الخلافة أحد أبوه وأمه من بني هاشم إلا أمير المؤمنين علي بن أبي طالب صلوات الله عليه ومحمد بن زبيدة أخبرني الحسن بن علي ومحمد بن يحيى الصولي قالا حدثنا الحسن بن عليل العنزي قال حدثنا المهزمي قال لما ولى إبراهيم بن عثمان بن نهيك الشرطة دخل عليه أشجع فأنشده قوله فيه\n(لمن المنازل مثل ظهر الأرقم ... قدمت وعهد أنيسها لم يقدم)\n(فتكت بها سنتان تعتورانها ... بالمعصفات وكل أسحم مرزم)\n(دمن إذا استثبت عينك عهدها ... كرت إليك بنطرة المتوهم)\n(ولقد طعنت الليل في أعجازه ... بالكأس بين غطارف كالأنجم)\n(يتمايلون على النعيم كأنهم ... قضب من الهندي لم تتثلم)\n(والليل مشتمل بفضل ردائه ... قد كاد يحسر عن أغر أرثم)\n(لبني نهيك طاعة لو أنها ... زحمت جونبها ببأس محطم)\n(في سيف إبراهيم خوف واقع ... لذوي النفاق وفيه أمن المسلم)\n(ويبيت يكلا - والعيون هواجع - ... مال المضيع ومهجة المستسلم)\n(ليل يواصله بضوء نهاره ... يقظان ليس يذوق نوم النوم)\n(شد الخطام بأنف كل مخالف ... حتى استقام له الذي لم يخطم)\n(لا يصلح السلطان إلا شدة ... تغشى البريء بفضل ذنب المجرم)\n(منعت مهابتك النفوس حديثها ... بالشيء تكرهه وإن لم تعلم)\n(ونهجت في سبل السياسة مسلكا ... ففهمت مذهبها الذي لم يفهم)\nوصله وحمله وخلع عليه أخبرني محمد بن يحيى الصولي قال حدثنا الغلابي قال حدثنا مهدي بن سابق قال أعطى جعفر بن يحيى مروان بن أبي حفصة - وقد مدحه - ثلاثين ألف درهم وأعطى أبا البصير عشرين ألفا وأعطى أشجع - وقد أنشده معهما - ثلاثة آلاف درهم وكان ذلك في أول اتصاله به فكتب إليه أشجع يقول\n(أعطيت مروان الثلاثين ... التي دلت رعاثه)\n(وأبا البصير وإنما ... أعطيتني منهم ثلاثه)\n(ما خانني حوك القريض ... ولا اتهمت سوى الحداثه)\nأمر له بعشرين ألف درهم أخرى حدثني علي بن صالح بن الهيثم الأنباري قال حدثني أبو هفان قال حدثني سعيد بن هريم وأبو دعامة قالا كان انقطاع أشجع إلى العباس بن محمد بن علي بن عبد الله بن\nالعباس فقال الرشيد للعباس يوما يا عم إن الشعراء قد أكثروا في مدح محمد بسببي وبسبب أم جعفر ولم يقل أحد منهم في المأمون شيئا وأنا أحب أن أقع على شاعر فطن ذكي يقول فيه فذكر العباس ذلك لأشجع وأمره أن يقول فيه فقال\n(بيعة المأمون آخذة ... بعنان الحق في أفقه)\n(أحكمت مراتها عقدا ... تمنع المختال في نفقه)\n(لن يفك المرء ربقتها ... أو يفك الدين من عنقه)\n(وله من وجه والده ... صورة تمت ومن خلقه)\nال فأتى بها العباس الرشيد وأنشده إياها فاستحسنها وسأله لمن هي فقال هي لي فقال قد سررتني مرتين بإصابتك ما في نفسي وبأنها لك وما كان لك فهو لي وأمر له بثلاثين ألف دينار فدفع إلى أشجع منها خمسة آلاف درهم وأخذ باقيها لنفسه أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا محمد بن عبد الله بن مالك الخزاعي قال وعد يحيى بن خالد أشجع السلمي وعدا فاخره عنه فقال له قوله\n(رأيتك لا تستلذ المطال ... وتوفي إذا غدر الخائن)\n(فماذا تؤخر من حاجتي ... وأنت لتعجيلها ضامن)\n(ألم تر أن احتباس النوال ... لمعروف صاحبه شائن)\nفلم يتعجل ما أراد فكتب إليه\n(رويدك إن عز الفقر أدنى ... إلي من الثراء مع الهوان)\n(وماذا تبلغ الأيام مني ... بريب صروفها ومعي لساني)\nبلغ قوله جعفرا فقال له ويلك يا أشجع هذا تهدد فلا تعد لمثله ثم كلم أباه فقضى حاجته فقال\n(كفاني صروف الدهر يحيى بن خالد ... فأصبحت لا أرتاع للحدثان)\n(كفاني - كفاه الله كل ملمة - ... طلاب فلان مرة وفلان)\n(فأصبحت في رغد من العيش واسع ... أقلب فيه ناظري ولساني)\nأخبرني محمد بن عمران الصيرفي قال حدثنا العنزي عن ابن النطاح قال ولى جعفر بن يحيى أشجع عملا فرفع إليه أهله رفائع كثيرة وتظلموا منه وشكوه فصرفه جعفر عنهم فلما رجع إليه من عمله مثل بين يديه ثم أنشأ يقول","topic":"نسب أشجع وأخباره","topicNo":241,"sp":6,"spl":"مدحه محمد الأمين وهو طفل","tags":["المديح"],"loc":3223},
{"id":"b241-9","bab":"الجزء 18","sec":"مدحه محمد الأمين وهو طفل","page":"ج18 ص234","text":"(أمفسدة سعاد علي ديني ... ولائمتي على طول الحنين)\n(وما تدري سعاد إذا تخلت ... من الأشجان كيف أخو الشجون)\n(تنام ولا أنام لطول حزني ... وأين أخو السرور من الحزين)\n(لقد راعتك عند قطين سعدى ... رواحل غاديات بالقطين)\n(كأن دموع عيني يوم بانوا ... عيانا سح مطرد معين)\n(لقد هزت سنان القول مني ... رجال رفيعة لم يعرفوني)\n(هم جازوا حجابك يا بن يحيى ... فقالوا بالذي يهوون دوني)\n(أطافوا بي لديك وغبت عنهم ... ولو أدنيتني لتجنبوني)\n(وقد شهدت عيونهم فمالت ... علي وغيبت عنهم عيوني)\n(ولما أن كتبت بما أرادوا ... تدرع كل ذي غمز دفين)\n(كففت عن المقاتل باديات ... وقد هيأت صخرة منجنون)\n(ولو أرسلتها دمغت رجالا ... وصالت في الأخشة والشؤون)\n(وكنت إذا هززت حسام قول ... قطعت بحجتي علق الوتين)\n(لعل الدهر يطلق من لساني ... لهم يوما ويبسط من يميني)\n(فأقضي دينهم بوفاء قول ... وأثقلهم لصدقي بالديون)\n(وقد علموا جميعا أن قولي ... قريب حين ادعوه يجيني)\n(وكنت إذا هجوت رئيس قوم ... وسمت على الذؤابة والجبين)\n(بخط مثل حرق النار باق ... يلوح على الحواجب والعيون)\n(أمائلة بودك يابن يحيى ... رجالات ذوو ضغن كمين)\n(يشيمون السيوف إذا رأوني ... فإن وليت سلت من جفون)\n(ولو كشفت سرائرنا جميعا ... علمت من البريء من الظنين)\n(علام - وأنت تعلم نصح جنبي ... وأخذي منك بالسبب المتين)\n(وعسفي كل مهمهة خلاء ... إليك بكل يعملة أمون)\n(وإحيائي الدجى لك بالقوافي ... أقيم صدورهن على المتون)\n(تقرب منك أعدائي وأنأى ... ويجلس مجلسي من لا يليني)\n(ولو عاتبت نفسك في مكاني ... إذا لنزلت عندك باليمين)\n(ولكن الشكوك نأين عني ... بودك والمصير إلى اليقين)\n(فإن أنصفتني أحرقت منهم ... بنضج الكي أثباج البطون)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":7,"spl":"مدحه محمد الأمين وهو طفل","tags":["الحب والغزل"],"loc":3224},
{"id":"b241-10","bab":"الجزء 18","sec":"اتصاله بجعفر بن المنصور","page":"ج18 ص240","text":"أخبرني محمد بن يحيى الصولي والحسن بن علي قالا حدثنا العنزي قال حدثنا علي بن الفضل السلمي قال أول ما نجم به أشجع أنه اتصل بجعفر بن المنصور وهو حدث وصله به أحمد بن يزيد السلمي وابنه عوف فقال أشجع في جعفر بن المنصور قوله\n(اذكروا حرمة العواتك منا ... يا بني هاشم بن عبد مناف)\n(قد ولدناكم ثلاث ولادات ... خلطن الأشراف بالأشراف)\n(مهدت هاشما نجوم قصى ... وبنو فالح حجور عفاف)\n(إن أرماح بهثة بن سليم ... لعجاف الأطراف غير عجاف)\n(ولأسيافهم فرى غير لذ ... راجع في مراجع الأكتاف)\n(معشر يطعمون من ذروة الشول ... ويسقون خمرة الأقحاف)\n(يضربون الجبار في أخدعيه ... ويسقونه نقيع الذعاف)\nشاع شعره وبلغ البصرة ولم يزل أمره يتراقى إلى أن وصلته زبيدة بعد وفاة أبيها بزوجها هارون الرشيد فأسنى جوائزه وألحقه بالطبقة العليا من الشعراء\nأخبرني عمي قال حدثني أحمد بن المرزبان قال حدثني شيبة بن أحمد بن هشام قال حدثني أحمد بن العباس الربيعي أن الذي أوصل أشجع السلمي إلى الرشيد جده الفضل بن الربيع وأنه أوصله له وقال له هو أشعر شعراء أهل هذا الزمان وقد اقتطعته عنك البرامكة فأمره بإحضاره وإيصاله مع الشعراء ففعل فلما وصل إليه أنشده قوله\n(قصر عليه تحية وسلام ... نثرت عليه جمالها الأيام)\n(فيه اجتلى الدنيا الخليفة والتقت ... للملك فيه سلامة وسلام)\n(قصر سقوف المزن دون سقوفه ... فيه لأعلام الهدى أعلام)\n(نشرت عليه الأرض كسوتها التي ... نسج الربيع وزخرف الإرهام)\n(أدنتك من ظل النبي وصية ... وقرابة وشجت بها الأرحام)\n(برقت سماؤك في العدو وأمطرت ... هاما لها ظل السيوف غمام)\n(وإذا سيوفك صافحت هام العدا ... طارت لهن عن الرؤوس الهام)\n(تثني على أيامك الأيام ... والشاهدان الحل والإحرام)\n(وعلى عدوك يابن عم محمد ... رصدان ضوء الصبح والإظلام)\n(فإذا تنبه رعته وإذا غفا ... سلت عليه سيوفك الأحلام)\nقال فاستحسنها الرشيد وأمر له بعشرين ألف درهم فمدح الفضل بن الربيع وشكر له إيصاله إياه إلى الرشيد فقال فيه قصيدته التي أولها\n(غلب الرقاد على جفون المسهد ... وغرقت في سهر وليل سرمد)\n(قد جد بي سهر فلم أرقد له ... والنوم يلعب في جفون الرقد)\n(ولطالما سهرت لحبي أعين ... أهدى السهاد لها ولما أسهد)\n(أيام أرعى في رياض بطالة ... ورد الصبا منها الذي لم يورد)\n(لهو يساعده الشباب ولم أجد ... بعد الشبيبة في الهوى من مسعد)\n(وخفيفة الأحشاء غير خفيفة ... مجدولة جدل العنان الأجرد)\n(غضبت على أعطافها أردافها ... فالحرب بين إزارها والمجسد)\n(خالفت فيه عاذلا لي ناصحا ... فرشدت حين عصيت قول المرشد)\n(أأقيم محتملا لضيم حوادث ... مع همة موصولة بالفرقد)\n(وأرى مخايل ليس يخلف نوؤها ... للفضل إن رعدت وإن لم ترعد)\n(للفضل أموال أطاف بها الندى ... حتى جهدن وجوده لم يجهد)\n(يابن الربيع حسرت شكري بالتي ... أوليتني في عود أمرك والبدي)\n(أوصلتني ورفدتني وكلاهما ... شرف فقأت به عيون الحسد)\n(ووصفتني عند الخليفة غائبا ... وأذنت لي فشهدت أفخر مشهد)\n(وكفيتني منن الرجال بنائل ... أغنى يدي عن أن تمد إلى يد)\nخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني صخر بن أحمد السلمي عن أبيه قال\nكنت أنا وأشجع بالرقة جلوسا فمر بنا غلام أمرد رومي جميل الوجه فكلمه أشجع وسأله هل يبيعه مالكه فقال نعم فقال أشجع يمدح جعفر بن يحيى وسأله ابتياعه له فقال\n(ومضطرب الوشاح لمقلتيه ... علائق ما لوصلتها انقطاع)\n(تعرض لي بنظرة ذي دلال ... يريع بمقلتيه ولا يراع)\n(لحاظ ليس تحجب عن قلوب ... وأمر في الذي يهوى مطاع)\n(ووسعي ضيق عنه ومالي ... وضيق الأمر يتبعه اتساع)\n(وتعويلي على مال ابن يحيى ... إليه حن شوقي والنزاع)\n(وثقت بجعفر في كل خطب ... فلا هلك يخاف ولا ضياع)\nفأمر له بخمسة آلاف درهم وقال اشتره بها فإن لم تكفك فازدد أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث قال كانت لأشجع جارية يقال لها ريم وكان يجد بها وجدا شديدا فكانت تحلف له إن بقيت بعده لم تعرض لغيره وكان يذكرها في شعره فمن ذلك قوله في قصيدته التي يرثي بها الرشيد\n(وليس لأحزان النساء تطاول ... ولكن أحزان الرجال تطول)\n(فلا تبخلي بالدمع عني فإن من ... يضن بدمع عن هوى لبخيل)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":8,"spl":"اتصاله بجعفر بن المنصور","tags":["الحب والغزل"],"loc":3225},
{"id":"b241-11","bab":"الجزء 18","sec":"اتصاله بجعفر بن المنصور","page":"ج18 ص240","text":"(فلا كنت ممن يتبع الريح طرفه ... دبورا إذا هبت له وقبول)\n(إذا دار فيء أتبع الفيء طرفه ... يميل مع الأيام حيث تميل)\nال وقال فيها أيضا\n(إذا غمضت فوقي جفون حفيرة ... من الأرض فابكيني بما كنت أصنع)\n(تعزك عني عند ذلك سلوة ... وأن ليس فيمن وارت الأرض مطمع)\n(إذا لم ترى شخصي وتغنيك ثروتي ... ولم تسمعي مني ولا منك أسمع)\n(فحينئذ تسلين عني وإن يكن ... بكاء فأقصى ما تبكين أربع)\n(قليل ورب البيت يا ريم ما أرى ... فتاة بمن ولى به الموت تقنع)\n(بمن تدفعين الحادثات إذا رمى ... عليك بها عام من الجدب يطلع)\n(فحينئذ تدرين من قد رزيته ... إذا جعلت أركان بينك تنزع)\nال فشكته ريم إلى أخيه أحمد بن عمرو فأجابه عنها بشعر نسبه إليها ومدح فيه الفضل أيضا فاختير شعره على شعر أخيه وهو\n(ذكرت فراقا والفراق يصدع ... وأي حياة بعد موتك تنفع)\n(إذا الزمن الغرار فرق بيننا ... فما لي في طيب من العيش مطمع)\n(ولا كان يوم يابن عمرو وليلة ... يبدد فيها شملنا ويصدع)\n(ولا كان يوم فيه تثوي رهينة ... فتروى بجسمي الحادثات وتشبع)\n(وألطم وجها كنت فيك أصونه ... وأخشع مما لم أكن منه أخشع)\n(ولو أنني غيبت في اللحد لم تبل ... ولم تزل الراؤون لي تتوجع)\n(وهل رجل أبصرته متوجعا ... على امرأة أو عينه الدهر تدمع)\n(ولكن إذا ولت يقول لها اذهبي ... فمثلك أخرى سوف أهوى وأتبع)\n(ولو أبصرت عيناك ما بي لأبصرت ... صبابة قلب غيمها ليس يقشع)\n(إلى الفضل فارحل بالمديح فإنه ... منيع الحمى معروفه ليس يمنع)\n(وزره تزر حلما وعلما وسوددا ... وبأسا به أنف الحوادث يجدع)\n(وأبدع إذا ما قلت في الفضل مدحة ... كما الفضل في بذل المواهب يبدع)\n(إذا ما حياض المجد قلت مياهها ... فحوض أبي العباس بالجود مترع)\n(وإن سنة ضنت بخصب على الورى ... ففي جوده مرعى خصيب ومشرع)\n(وما بعدت أرض بها الفضل نازل ... ولا خاب من في نائل الفضل يطمع)\n(فنعم المنادى الفضل عند ملمة ... لدفع خطوب مثلها ليس يدفع)\n(إليك أبا العباس سارت نجائب ... لها همم تسمو إليك وتنزع)\n(بذكرك نحدوها إذا ما تأخرت ... فتمضي على هول المضي وتسرع)\n(وما للسان المدح دونك مشرع ... ولا للمطايا دون بابك مفزع)\n(إليك أبا العباس أحمل مدحة ... مطيتها - حتى توافيك - أشجع)\n(فزعت إلى جدواك فيها وإنما ... الى مفزع الأملاك يلجا ويفزع)\nال فأنشدها أشجع الفضل وحدثه بالقصة فوصل أخاه وجاريته ووصله وقال أحمد بن الحارث فقيل لأحمد بن عمرو أخي أشجع مالك لا تمدح الملوك كما يمدحهم أخوك فقال إن أخي بلاء علي وإن كان فخرا لأني لا أمدح أحدا ممن يرضيه دون شعري ويثيب عليه بالكثير من الثواب إلا\nقال أين هذا من قول أشجع فقد امتنعت من مدح أحد لذلك قال أحمد بن الحارث وقال أحمد بن عمرو يهجو أخاه أشجع وقد كان أحمد مدح محمد بن جميل بشعر قاله فيه فسأل أخاه أشجع إيصاله ودفع القصيدة إليه فتوانى عن ذلك فقال يهجوه - أخبرني بذلك أحمد بن محمد بن جميل -\n(وسائلة لي ما أشجع ... فقلت يضر ولا ينفع)\n(قريب من الشر واع له ... أصم عن الخير ما يسمع)\n(بطيء عن الأمر أحظى به ... إلى كل ما ساءني مسرع)\n(شرود الوداد على قربه ... يفرق منه الذي أجمع)\n(أسب بأني شقيق له ... فأنفي به أبدا أجدع)\nأخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه قال دخلت على الفضل بن يحيى وقد بلغ الرشيد إطلاقه يحيى بن عبد الله بن حسن وقد كان أمره بقتله فلم يظهر له أنه بلغه إطلاقه فسأله عن خبره هل قتلته فقال لا فقال له فأين هو\nقال ولم قال لأنه سألني بحق الله وبحق رسوله وقرابته منه ومنك وحلف لي أنه لا يحدث حدثا وأنه يجيبني متى طلبته فأطرق ساعة ثم قال امض بنفسك في طلبه حتى تجيئني به واخرج الساعة فخرج قال فدخلت عليه مهنئا بالسلامة فقلت له ما رأيت أثبت من جنانك ولا أصح من رأيك فيما جرى وأنت والله كما قال أشجع\n(بديهته وفكرته سواء ... إذا ما نابه الخطب الكبير)\n(وأحزم ما يكون الدهر رأيا ... إذا عي المشاور والمشير)\n(وصدر فيه للهم اتساع ... إذا ضاقت بما تحوي الصدور)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":9,"spl":"اتصاله بجعفر بن المنصور","tags":["الحب والغزل"],"loc":3226},
{"id":"b241-12","bab":"الجزء 18","sec":"اتصاله بجعفر بن المنصور","page":"ج18 ص240","text":"قال الفضل انظروا كم أخذ أشجع على هذه القصيدة فاحملوا إلى أبي محمد مثله قال فوجده قد أخذ ثلاثين ألف درهم فحملت إلي أخبرني الحسين بن القاسم الكوكبي إجازة قال حدثني محمد بن عجلان قال حدثنا ابن خلاد عن حسين الجعفي قال كان أشجع إذا قدم بغداد ينزل على صديق له من أهلها فقدمها مرة فوجده قد مات والنوح والبكاء في داره فجزع لذلك وبكى وأنشأ يقول\n(ويحها هل درت على من تنوح ... أسقيم فؤادها أم صحيح)\n(قمر أطبقوا عليه ببغداد ... ضريحا ماذا أجن الضريح)\n(رحم الله صاحبي ونديمي ... رحمة تغتدي وأخرى تروح)\nهذه القصيدة التي فيها الأبيات المذكورة والغناء فيها من قصيدة يمدح بها أشجع الرشيد ويهنئه بفتح هرقلة وقد مدحه بذلك وهنأه جماعة من\nالشعراء وغنى في جميعها فذكرت خبر فتح هرقلة لذكر ذلك","topic":"نسب أشجع وأخباره","topicNo":241,"sp":10,"spl":"اتصاله بجعفر بن المنصور — سبب غزاه الرشيد هرقلة","tags":[],"loc":3227},
{"id":"b241-13","bab":"الجزء 18","sec":"سبب غزاه الرشيد هرقلة","page":"ج18 ص246","text":"أخبرني بخبره علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال كان من خبر غزاة الرشيد هرقلة أن الروم كانت قد ملكت امرأة لأنه لم يكن بقي في أهل زمانها من أهل بيتها - بيت المملكة - غيرها وكانت تكتب إلى المهدي والهادي والرشيد أول خلافته بالتعظيم والتبجيل وتدر عليه الهدايا حتى بلغ ابن لها فحاز الملك دونها وعاث وأفسد وفاسد الرشيد فخافت على ملك الروم أن يذهب وعلى بلادهم أن تعطب لعلمها بالرشيد وخوفها من سطوته فاحتالت لابنها فسملت عينه فبطل منه الملك وعاد إليها فاستنكر ذلك أهل المملكة وأبغضوها من أجله فخرج عليها نقفور وكان كاتبها فأعانوه وعضدوه وقام بأمر الملك وضبط أمر الروم فلما قوي على أمره وتمكن من ملكه كتب إلى الرشيد","topic":"نسب أشجع وأخباره","topicNo":241,"sp":10,"spl":"اتصاله بجعفر بن المنصور — سبب غزاه الرشيد هرقلة","tags":["الجواري والنساء","الرواية والكتابة"],"loc":3228},
{"id":"b241-14","bab":"الجزء 18","sec":"نقفور والرشيد","page":"ج18 ص247","text":"من نقفور ملك الروم إلى الرشيد ملك العرب أما بعد فإن هذه المرأة كانت وضعتك وأباك وأخاك موضع الملوك ووضعت نفسها موضع السوقة وإني واضعك بغير ذلك الموضع وعامل على من تطرق بلادك والهجوم على أمصارك أو تودي إلى ما كانت المرأة تودي إليك والسلام فلما ورد كتابه على الرشيد كتب إليه بسم الله الرحمن الرحيم - من عبد الله هارون أمير المؤمنين إلى نقفور كلب الروم أما بعد فقد فهمت كتابك وجوابك عندي ما تراه عيانا لا ما تسمعه ثم شخص من شهره ذلك يؤم بلاد الروم في جمع لم يسمع بمثله وقواد لا يجارون نجدة ورأيا فلما بلغ ذلك نقفور ضاقت عليه الأرض بما رحبت وشاور في أمره وجد الرشيد يتوغل في بلاد الروم فيقتل ويغنم ويسبي ويخرب الحصون ويعفي الآثار حتى صار إلى طرق متضايقة دون قسطنطينية فلما بلغها وجدها وقد أمر نقفور بالشجر فقطع ورمي به في تلك الطرق وألقيت فيه النار فكان أول من لبس ثياب النفاطين محمد بن يزيد بن مزيد فخاضها ثم أتبعه الناس فبعث إليه نقفور بالهدايا وخضع له أشد الخضوع وأدى إليه الجزية عن رأسه فضلا عن أصحابه فقال في ذلك أبو العتاهية\n(إمام الهدى أصحت بالدين معنيا ... وأصبحت تسقي كل مستمطر ريا)\n(لك اسمان شقا من رشاد ومن هدى ... فأنت الذي تدعى رشيدا ومهديا)\n(إذا ما سخطت الشيء كان مسخطا ... وإن ترض شيئا كان في الناس مرضيا)\n(بسطت لنا شرقا وغربا يد العلا ... فأوسعت شرقيا وأوسعت غربيا)\n(ووشيت وجه الأرض بالجود والندى ... فأصبح وجه الأرض بالجود موشيا)\n(وأنت - أمير المؤمنين - فتى التقى ... نشرت من الإحسان ما كان مطويا)\nوإني واضعك بغير ذلك الموضع وعامل على تطرق بلادك والهجوم على أمصارك أو تؤدي إلى ما كانت المرأة تودى إليك والسلام فلما ورد كتابه على الرشيد كتب إليه بسم الله الرحمن الرحيم - من عبد الله هارون أمير المؤمنين إلى نقفور كلب الروم أما بعد فقد فهمت كتابك وجوابك عندي ما تراه عيانا لا ما تسمعه ثم شخص من شهره ذلك يؤم بلاد الروم في جمع لم يسمع بمثله وقواد لا يجارون نجدة ورأيا فلما بلغ ذلك نقفور ضاقت عليه الأرض بما رحبت وشاور في أمره وجد الرشيد يتوغل في بلاد الروم فيقتل ويغنم ويسبي ويخرب الحصون ويعفي الآثار حتى صار إلى طرق متضايقة دون قسطنطينية فلما بلغها وجدها وقد أمر نقفور بالشجر فقطع ورمي به في تلك الطرق وألقيت فيه النار فكان أول من لبس ثياب النفاطين محمد بن يزيد بن مزيد فخاضها ثم أتبعه الناس فبعث إليه نقفور بالهدايا وخضع له أشد الخضوع وأدى إليه الجزية عن رأسه فضلا عن أصحابه فقال في ذلك أبو العتاهية\n(إمام الهدى أصبحت بالدين معنيا ... وأصبحت تسقي كل مستمطر ريا)\n(لك اسمان شقا من رشاد ومن هدى ... فأنت الذي تدعى رشيدا ومهديا)\n(إذا ما سخطت الشيء كان مسخطا ... وإن ترض شيئا كان في الناس مرضيا)\n(بسطت لنا شرقا وغربا يد العلا ... فأوسعت شرقيا وأوسعت غربيا)\n(ووشيت وجه الأرض بالجود والندى ... فأصبح وجه الأرض بالجود موشيا)\n(وأنت - أمير المؤمنين - فتى التقى ... نشرت من الإحسان ما كان مطويا)\n(قضى الله أن يبقى لهارون ملكه ... وكان قضاء الله في الخلق مقضيا)\n(تجللت الدنيا لهارون ذي الرضا ... وأصبح نقفور لهارون ذميا)\nرجع الرشيد - لما أعطاه نقفور ما أعطاه - إلى الرقة فلما سقط الثلج وأمن نقفور أن يغزى اغتر بالمهلة ونقض ما بينه وبين الرشيد ورجع إلى حالته الأولى فلم يجترىء يحيى بن خالد - فضلا عن غيره - على إخبار الرشيد بغدر نقفور فبذل هو وبنوه الأموال للشعراء على أن يقولوا أشعارا في إعلام الرشيد بذلك فكلهم كع وأشفق إلا شاعرا من أهل جدة كان يكنى أبا محمد وكان مجيدا قوي النفس قوي الشعر وكان ذو اليمينين اختصه في أيام المأمون ورفع قدره جدا فإنه أخذ من يحيى وبنيه مائة ألف درهم ودخل على الرشيد فأنشده\n(نقض الذي أعطاكه نقفور ... فعليه دائرة البوار تدور)\n(أبشر أمير المؤمنين فإنه ... فتح أتاك به الإله كبير)\n(فلقد تباشرت الرعية أن أتى ... بالنقض عنه وافد وبشير)\n(ورجت بيمنك أن تعجل غزوة ... تشفي النفوس نكالها مذكور)\n(أعطاك جزيته وطأطأ خده ... حذر الصوارم والردى محذور)\n(فأجرته من وقعها وكأنها ... بأكفنا شعل الضرام تطير)\n(وصرفت في طول العساكر قافلا ... عنه وجارك آمن مسرور)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":11,"spl":"نقفور والرشيد","tags":[],"loc":3229},
{"id":"b241-15","bab":"الجزء 18","sec":"نقفور والرشيد","page":"ج18 ص247","text":"(نقفور إنك حين تغدر أن نأى ... عنك الإمام لجاهل مغرور)\n(أظننت حين غدرت أنك مفلت ... هبلتك أمك ما ظننت غرور)\n(ألقاك حينك في زواخر بحره ... فطمت عليك من الإمام بحور)\n(إن الإمام على اقتسارك قادر ... قربت ديارك أو نأت بك دور)\n(ليس الإمام وإن غفلنا غافلا ... عما يسوس بحزمه ويدير)\n(ملك تجرد للجهاد بنفسه ... فعدوه أبدا به مقهور)\n(يا من يريد رضا الإله بسعيه ... والله لا يخفى عليه ضمير)\n(لا نصح ينفع من يغش إمامه ... والنصح من نصحائه مشكور)\n(نصح الإمام على الأنام فريضة ... ولأهله كفارة وطهور)","topic":"نسب أشجع وأخباره","topicNo":241,"sp":12,"spl":"نقفور والرشيد","tags":[],"loc":3230},
{"id":"b241-16","bab":"الجزء 18","sec":"فتح هرقلة","page":"ج18 ص250","text":"قال فلما أنشده قال الرشيد أو قد فعل وعلم أن الوزراء احتالوا في إعلامه ذلك فغزاه في بقية من الثلج فافتتح هرقلة في ذلك الوقت فقال أبو العتاهية في فتحه إياها\n(ألا نادت هرقلة بالخراب ... من الملك الموفق للصواب)\n(غدا هارون يرعد بالمنايا ... ويبرق بالمذكرة القضاب)\n(ورايات يحل النصر فيها ... تمر كأنها قطع السحاب)\n(أمير المؤمنين ظفرت فاسلم ... وأبشر بالغنيمة والإياب)\nال محمد وجعل الرشيد قبل وصوله إلى هرقلة يفتح المدن والحصون ويخربها حتى أناخ على هرقلة وهي أوثق حصن وأعزه جانبا وأمنعه ركنا\nفتحصن أهلها وكان بابها يطل على واد ولها خندق يطيف بها فحدثني شيخ من مشايخ المطوعة وملازمي الثغور يقال له علي بن عبد الله قال حدثني جماعة أن الرشيد لما حصر أهل هرقلة وغمهم وألح بالمجانيق والسهام والعرادات فتح الباب فاستشرف المسلمون لذلك فإذا برجل من أهلها كأكمل الرجال قد خرج في أكمل السلاح فنادى قد طالت مواقعتكم إيانا فليبرز إلي منكم رجلان ثم لم يزل يزيد حتى بلغ عشرين رجلا فلم يجبه أحد فدخل وأغلق باب الحصن وكان الرشيد نائما فلم يعلم بخبره إلا بعد انصرافه فغضب ولام خدمه وغلمانه على تركهم إنباهه وتأسف لفوته فقيل له إن امتناع الناس منه سيغويه ويطغيه وأحر به أن يخرج في غد فيطلب مثل ما طلب فطالت على الرشيد ليلته وأصبح كالمنتظر له ثم إذا هو بالباب قد فتح وخرج طالبا للمبارزة وذلك في يوم شديد الحر وجعل يدعو بأنه يثبت لعشرين منهم فقال الرشيد من له فابتدره جلة القواد كهرثمة ويزيد بن مزيد وعبد الله بن مالك وخزيمة بن حازم وأخيه عبد الله وداود بن يزيد وأخيه فعزم على إخراج بعضهم فضجت المطوعة حتى سمع ضجيجهم فأذن لعشرين منهم فاستأذنوه في المشورة فأذن لهم فقال قائلهم يا أمير المؤمنين قوادك مشهورون بالبأس والنجدة وعلو الصوت ومداوسة الحروب ومتى خرج واحد منهم فقتل هذا العلج لم يكبر ذلك وإن قتله العلج كانت وضيعة على العسكر عجيبة وثلمة لا تسد ونحن عامة لم يرتفع لأحد منا صوت إلا كما يصلح للعامة فإن رأى أمير\nالمؤمنين أن يخلينا نختار رجلا فنخرجه إليه فإن ظفر علم أهل الحصن أن أمير المؤمنين قد ظفر بأعزهم على يد رجل من العامة ومن أفناء الناس ليس ممن يوهن قتله ولا يؤثر وإن قتل الرجل فإنما استشهد رجل ولم يؤثر ذهابه في العسكر ولم يثلمه وخرج إليه رجل بعده مثله حتى يقضي الله ما شاء\nقال الرشيد قد استصوبت رأيكم هذا فاختاروا رجلا منهم يعرف بابن الجزري وكان معروفا في الثغر بالبأس والنجدة فقال الرشيد أتخرج قال نعم وأستعين الله فقال أعطوه فرسا ورمحا وسيفا وترسا فقال يا أمير المؤمنين أنا بفرسي أوثق ورمحي بيدي أشد ولكني قد قبلت السيف والترس فلبس سلاحه واستدناه الرشيد فوعده واستتبعه بالدعاء وخرج معه عشرون رجلا من المطوعة فلما انقض في الوادي\nقال لهم العلج وهو يعدهم واحدا واحدا إنما كان الشرط عشرين وقد زدتم رجلا ولكن لا بأس فنادوه ليس يخرج إليك منا إلا رجل واحد فلما فصل منهم ابن الجزري تأمله الرومي وقد أشرف أكثر الروم من الحصن يتأملون صاحبهم والقرن حتى ظنوا أنه لم يبق في الحصن أحد إلا أشرف فقال الرومي أتصدقني عما أستخبرك\nقال نعم فقال أنت بالله ابن الجزري قال اللهم نعم فكفر له ثم أخذا في شأنهما فاطعنا حتى طال الأمر بينهما وكاد الفرسان أن يقوما وليس يخدش واحد منهما صاحبه ثم تحاجزا بشيء فزج كل واحد منهما برمحه وأصلت سيفه فتجالدا مليا واشتد الحر عليهما وتبلد الفرسان وجعل ابن الجزري يضرب الرومي الضربة التي يرى أنه قد بلغ فيها فيتقيها الرومي وكان ترسه حديدا فيسمع لذلك صوت منكر ويضربه الرومي ضرب منذر لأن ترس ابن الجزري كان درقة فكان العلج يخاف أن يعض بالسيف فيعطب فلما يئس من وصول كل واحد منهما إلى صاحبه انهزم ابن الجزري فدخلت المسلمين كآبة لم يكتئب مثلها قط","topic":"نسب أشجع وأخباره","topicNo":241,"sp":13,"spl":"فتح هرقلة","tags":["الخمر"],"loc":3231},
{"id":"b241-17","bab":"الجزء 18","sec":"فتح هرقلة","page":"ج18 ص250","text":"وعطعط المشركون اختيالا وتطاولا وإنما كانت هزيمته حيلة منه فأتبعه العلج وتمكن منه ابن الجزري فرماه بوهق فوقع في عنقه وما أخطأه وركض فاستله عن فرسه ثم عطف عليه فما وصل إلى الأرض حيا حتى فارقه رأسه فكبر المسلمون أعلى تكبير وانخذل المشركون وبادروا الباب يغلقونه واتصل الخبر بالرشيد فصاح بالقواد اجعلوا النار في المجانيق وارموها فليس عند القوم دفع ففعلوا وجعلوا الكتان والنفط على الحجارة وأضرموا فيها النار ورموا بها السور فكانت النار تلصق به وتأخذ الحجارة وقد تصدع فتهافتت فلما أحاطت بها النيران فتحوا الباب مستأمنين ومستقبلين فقال الشاعر المكي الذي كان ينزل جدة\n(هوت هرقلة لما أن رأت عجبا ... حوائما ترتمي بالنفط والنار)\n(كأن نيراننا في جنب قلعتهم ... مصبغات على أرسان قصار)\nي هذين البيتين لابن جامع لحن من الثقيل الأول بالبنصر قال محمد بن يزيد وهذا كلام ضعيف لين ولكن قدره عظيم في ذلك الموضع والوقت وغنى فيه المغنون بعد ذلك وأعظم الرشيد الجائزة للجدي الشاعر وصبت الأموال على ابن الجزري وقود فلم يقبل التقويد إلا بغير رزق ولا عوض وسأل أن يعفى وينزل بمكانه من الثغر فلم يزل به طول عمره أخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن أبي سعد قال حدثنا أحمد بن علي بن أبي نعيم المروزي قال\nخرج الرشيد غازيا بلاد الروم فنزل بهرقلة فدخل عليه ابن جامع فغناه\n(هوت هرقلة لما أن رأت عجبا ... حوائما ترتمي بالنفط والنار)\nنظر الرشيد إلى ماشية قد جيء بها فظن أن الطاغية قد أتاه فخرج يركض على فرس له وفي يده الرمح وتبعه الناس فلما تبين له أنها ماشية رجعوا فغناه ابن جامع\n(رأى في السما رهجا فيممم نحوه ... يجر ردينيا وللرهج يستقري)\n(تناولت أطراف البلاد بقدرة ... كأنك فيها تقتفي أثر الخضر)\nلغناء لابن جامع ثاني ثقيل عن بذل وابن المكي","topic":"نسب أشجع وأخباره","topicNo":241,"sp":14,"spl":"فتح هرقلة","tags":["الهجاء"],"song":2,"loc":3232},
{"id":"b241-18","bab":"الجزء 18","sec":"أشجع يهنىء الرشيد بفتح هرقلة","page":"ج18 ص254","text":"أخبرني هاشم بن محمد أبو دلف الخزاعي قال حدثني الفضل بن محمد اليزيدي عن إسحاق الموصلي قال لما انصرف الرشيد من غزاة هرقلة قدم الرقة في آخر شهر رمضان فلما عيد جلس للشعراء فدخلوا عليه وفيهم أشجع فبدرهم وأنشأ يقول\n(لا زلت تنشر أعيادا وتطويها ... تمضي بها لك أيام وتثنيها)\n(مستقبلا زينة الدنيا وبهجتها ... أيامنا لك لا تفنى وتفنيها)\n(ولا تقضت بك الدنيا ولا برحت ... يطوي لك الدهر أياما وتطويها)\n(وليهنك الفتح والأيام مقبلة ... إليك بالنصر معقودا نواصيها)\n(أمست هرقلة تهوي من جوانبها ... وناصر الله والإسلام يرميها)\n(ملكتها وقتلت الناكثين بها ... بنصر من يملك الدنيا وما فيها)\n(ما روعي الدين والدنيا على قدم ... بمثل هارون راعيه وراعيها)\nال فأمر له بألف دينار وقال لا ينشدني أحد بعده فقال أشجع والله لأمره بألا ينشده أحد بعدي أحب إلي من صلته حدثني أحمد بن وصيف ومحمد بن يحيى الصولي قالا حدثنا محمد بن موسى بن حماد قال حدثني عبد الله بن عمرو الوراق قال حدثني أحمد بن محمد بن منصور بن زياد عن أبيه قال دخل أشجع على الرشيد ثاني يوم الفطر فأنشده\n(استقبل العيد بعمر جديد ... مدت لك الأيام حبل الخلود)\n(مصعدا في درجات العلا ... نجمك مقرون بسعد السعود)\n(واطو رداء الشمس ما أطلعت ... نورا جديدا كل يوم جديد)\n(تمضي لك الأيام ذا غبطة ... إذا أتى عيد طوى عمر عيد)\nوصله بعشرة آلاف درهم وأمر أن يغنى في هذه الأبيات أخبرني محمد بن جعفر النحوي قال حدثنا محمد بن موسى بن حماد قال حدثني أبو عبد الله النخعي قال دخل أشجع على الرشيد فأنشده قوله\n(أبت طبرستان غير الذي ... صدعت به بين أعضائها)\n(ضممت مناكبها ضمة ... رمتك بما بين أحشائها)\n(سموت إليها بمثل السماء ... تدلى الصواعق في مائها)\n(فلما نظرت إلى جرحها ... وضعت الدواء على دائها)\n(فرشت الجهاد ظهور الجياد ... بأبنائه وبأبنائها)\n(بنفسك ترميهم والخيول ... كرمي العقاب بأفلائها)\n(نظرت برأيك لما هممت ... دون الرجال وآرائها)\nال فأمر له بألف دينار أخبرني محمد بن جعفر قال حدثنا محمد بن موسى قال حدثني أبو عمرو الباهلي البصري قال دخل أشجع بن عمرو السلمي على هارون الرشيد حين قدم من الحج وقد مطر الناس يوم قدومه فأنشده يقول\n(إن يمن الإمام لما أتانا ... جلب الغيث من متون الغمام)\n(فابتسام النبات في أثر الغيث ... بنواره كسرج الظلام)\n(ملك من مخافة الله مغض ... وهو مغضى له من الإعظام)\n(ألف الحج والجهاد فما ينفك ... من سفرتين في كل عام)\n(سفر للجهاد نحو عدو ... والمطايا لسفرة الإحرام)\n(طلب الله فهو يسعى إليه ... بالمطايا وبالجياد السوامي)\n(فيداه يد بمكة تدعوه ... وأخرى في دعوة الإسلام)\nخبرني محمد بن جعفر قال حدثني محمد بن موسى بن حماد قال أخبرني أبو عبد الله النخعي قال أمر الرشيد بحفر نهر لبعض أهل السواد وقد كان خرب وبطل ما\nعليه فقال أشجع السلمي يمدحه\n(أجرى الإمام الرشيد نهرا ... عاش بعمرانه الموات)\n(جاد عليه بريق فيه ... وسر مكنونه الفرات)\n(ألقمه درة لقوحا ... يرضع أخلافها النبات)\nخبرني جحظة قال حدثني ميمون بن هارون قال رأى الرشيد فيما يرى النائم كأن امرأة وقفت عليه وأخذت كف تراب ثم قالت له هذه تربتك عن قليل فأصبح فزعا وقص رؤياه فقال له أصحابه وما هذا قد يرى الناس أكثر مما رأيت وأغلظ ثم لا يضر فركب\nوقال والله إني لأرى الأمر قد قرب فبينا هو يسير إذ نظر إلى امرأة واقفة من وراء شباك حديد تنظر إليه فقال هذه والله المرأة التي رأيتها ولو رأيتها بين ألف امرأة ما خفيت علي ثم أمرها أن تأخذ كف تراب فتدفعه إليه فضربت بيدها إلى الأرض التي كانت عليها فأعطته منها كف تراب فبكى ثم\nقال هذه والله التربة التي أريتها وهذه المرأة بعينها ثم مات بعد مدة فدفن في ذلك الموضع بعينه اشتري له ودفن فيه وأتى نعيه بغداد فقال أشجع يرثيه\n(غربت بالمشرق الشمس ... فقل للعين تدمع)\n(ما رأينا قط شمسا ... غربت من حيث تطلع)\nخبرني عمي قال حدثنا محمد بن موسى قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال كان حرب بن عمرو الثقفي نخاسا وكانت له جارية مغنية وكان الشعراء والكتاب وأهل الأدب ببغداد يختلفون إليها يسمعونها وينفقون في","topic":"نسب أشجع وأخباره","topicNo":241,"sp":15,"spl":"أشجع يهنىء الرشيد بفتح هرقلة","tags":[],"song":1,"loc":3233},
{"id":"b241-19","bab":"الجزء 18","sec":"أشجع يهنىء الرشيد بفتح هرقلة","page":"ج18 ص254","text":"منزله النفقات الواسعة ويبرونه ويهدون إليه فقال أشجع\n(جارية تهتز أردافها ... مشبعة الخلخال والقلب)\n(أشكو الذي لاقيت من حبها ... وبغض مولاها إلى الرب)\n(من بغض مولاها ومن حبها ... سقمت بين البغض والحب)\n(فاختلجا في الصدر حتى استوى ... أمرهما فاقتسما قلبي)\n(تعجل الله شفائي بها ... وعجل السقم إلى حرب)\nال مؤلف هذا الكتاب فأخذ هذا المعنى بعض المحدثين من أهل عصرنا فقال في مغنية تعرف بالشاة\n(بحب الشاة ذبت ضنى ... وطال لزوجها مقتي)\n(فلو أني ملكتهما ... لأسعد في الهوى بختي)\n(فأدخل في استها أيري ... ولحية زوجها في استي)\nخبرني أبو الحسن الأسدي قال حدثنا سليمان بن أبي شيخ قال حدثني صالح بن سليمان قال اعتل يحيى بن خالد ثم عوفي فدخل الناس يهنئونه بالسلامة ودخل أشجع فأنشد\n(لقد قرعت شكاة أبي علي ... قلوب معاشر كانوا صحاحا)\n(فإن يدفع لنا الرحمن عنه ... صروف الدهر والأجل المتاحا)\n(فقد أمسى صلاح أبي علي ... لأهل الدين والدنيا صلاحا)\n(إذا ما الموت أخطأ فلسنا ... نبالي الموت حيث غدا وراحا)\nقال فما أذن يومئذ لأحد سواه في الإنشاد لاختصاص البرامكة إياه\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا محمد بن عمران الضبي قال سمعت محمد بن أبي مالك الغنوي يقول دخل أشجع السلمي على علي بن شبرمة يعوده فأنشأ يقول\n(إذا مرض القاضي مرضنا بأسرنا ... وإن صح لم يسمع لنا بمريض)\n(فأصبحت - لما اعتل يوما - كطائر ... سما بجناح للنهوض مهيض)\nال فشكره ابن شبرمة وحمله على بغلة كانت له أخبرني الحسن قال حدثنا ابن مهرويه قال حدثني محمد بن عمران قال سمعت محمد بن أبي مالك يقول جاء أشجع ليدخل على أبان بن الوليد البجلي فمنعه حاجبه وانتهره غلمانه فقال فيه\n(ألا أيها المشلي علي كلابه ... ولي - غير أن لم أشلهن - كلاب)\n(رويدك لا تعجل علي فقد جرى ... بخزيك ظبي أعضب وغراب)\n(علام تسد الباب والسر قد فشا ... وقد كنت محجوبا ومالك باب)\n(فلو كنت ممن يشرب الخمر سادرا ... إذا لم يكن دوني عليك حجاب)\n(ولكنه يمضي لي الحول كاملا ... ومالي إلا الأبيضين شراب)\n(من الماء أو من شخب دهماء ثرة ... لها حالب لا يشتكي وحلاب)\nخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال حدثنا علي بن الجهم قال حدثني ابن أشجع السلمي قال لما مر أبي وعماي أحمد ويزيد - وقد شربوا حتى انتشوا - بقبر الوليد بن عقبة وإلى جانبه قبر أبي زبيد الطائي - وكان نصرانيا - والقبران مختلفان كل واحد منهما متجه إلى قبلة ملته وكان أبو زبيد أوصى لما احتضر أن يدفن إلى جنب الوليد بالبليخ قال فوقفوا على القبرين وجعلوا يتحدثون بأخبارهما ويتذاكرون أحاديثهما فأنشأ أبي يقول\n(مررت على عظام أبي زبيد ... وقد لاحت ببلقعة صلود)\n(وكان له الوليد نديم صدق ... فنادم قبره قبر الوليد)\n(أنيسا ألفة ذهبت فأمست ... عظامهما تآنس بالصعيد)\n(وما أدري بمن تبدا المنايا ... بأحمد أو بأشجع أو يزيد)\nقال فماتوا والله كما رتبهم في الشعر أولهم أحمد ثم أشجع ثم يزيد\n(حي ذا الزور وانهه أن يعودا ... إن بالباب حارسين قعودا)\n(من أساوير ما ينون قياما ... وخلاخيل تذهل المولودا)\n(لا ذعرت السوام في فلق الصبح ... مغيرا ولا دعيت يزيدا)\n(يوم أعطي مخافة الموت ضيما ... والمنايا يرصدنني أن أحيدا)\nلشعر ليزيد بن ربيعة بن مفرغ الحميري والغناء لسياط خفيف رمل بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر أحمد بن المكي أنه لأبيه يحيى وذكر الهشامي أنه لفليح قال ومن هذا الصوت سرق لحن\n(تلك عرسي تلومني في التصابي ... )","topic":"نسب أشجع وأخباره","topicNo":241,"sp":16,"spl":"أشجع يهنىء الرشيد بفتح هرقلة","tags":["الحب والغزل"],"song":1,"loc":3234,"partial":1},
{"id":"b242-1","bab":"الجزء 18","sec":"أخبار ابن مفرغ ونسبه","page":"ج18 ص262","text":"هو يزيد بن ربيعة بن مفرغ ولقب جده مفرغا لأنه راهن على سقاء لبن أن يشربه كله فشربه كله حتى فرغه فلقب مفرغا ويكنى أبا عثمان وهو من حمير فيما يزعم أهله\nوذكر ابن الكلبي وأبو عبيدة أن مفرغا كان شعابا بتبالة فادعى أنه من حمير وقال علي بن محمد النوفلي ليس أحد بالبصرة من حمير إلا آل الحجاج بن ناب الحميري وبيتا آخر ذكره ودفع بيت ابن مفرغ\nأخبرني محمد بن خلف بن المرزبان قال أخبرني أحمد بن الهيثم القرشي قال أخبرني العمري عن لقيط بن بكر المحاربي قال هو يزيد بن ربيعة بن مفرغ الحميري حليف قريش ثم حليف آل خالد بن أسيد بن أبي العيص بن أمية بن عبد شمس قال العمري وكان ابن المكي يقول كان مفرغ عبدا للضحاك بن عبد عوف الهلالي فأنعم عليه\nقال محمد بن خلف أخبرني محمد بن عبد الرحمن الأسدي عن محمد بن رزين قال قال الأخفش كان ربيعة بن مفرغ شعابا بالمدينة وكان ينسب إلى حمير وإنما سمي مفرغا لتفريغه العس وكان شاعرا غزلا محسنا والسيد من ولده\nأخبرني محمد بن خلف بن المرزبان قال حدثني أبو العيناء قال سئل الأصمعي عن شعر تبع وقصته ومن وضعهما فقال ابن مفرغ وذلك أن يزيد بن معاوية لما سيره إلى الشام وتخلصه من عباد بن زياد أنزله الجزيرة وكان مقيما برأس عين وزعم أنه من حمير ووضع سيرة تبع وأشعاره وكان النمر بن قاسط يدعي أنه منهم\nوقال الهيثم بن عدي هو يزيد بن زياد بن ربيعة بن مفرغ اليحصبي من حمير يحصب بن مالك بن زيد بن الغوث بن سعد بن عوف بن عدي بن مالك بن زيد بن سهل بن عمرو بن قيس بن معاوية بن جشم بن عبد شمس بن\nوائل بن الغوث بن الهميسع بن حمير بن سبأ بن يشجب بن يعرب بن قحطان أخبرني بخبره جماعة من مشايخنا منهم أحمد بن عبد العزيز الجوهري عن عمر بن شبة ومحمد بن خلف بن المرزبان عن جماعة من أصحابه وأحمد بن عبد العزيز الجوهري عن علي بن محمد النوفلي عن أبيه فما اتفقت رواياتهم من خبره جمعتها في ذكره وما اختلفت أفردت كل منفرد منهم بروايته","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":0,"spl":"أخبار ابن مفرغ ونسبه","tags":["السفر والحج"],"loc":3235},
{"id":"b242-2","bab":"الجزء 18","sec":"ابن مفرغ وعباد بن زياد","page":"ج18 ص264","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن مسلمة بن محارب وأخبرني الجوهري قال حدثنا عمر بن شبة وأخبرنا محمد بن العباس اليزيدي\nقال قرأت على محمد بن الحسن بن دريد عن ابن الأعرابي وأخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد ابن الهيثم قال حدثنا العمري عن لقيط بن بكير قالوا جميعا لما ولي سعيد بن عثمان بن عفان خراسان استصحب يزيد بن ربيعة ابن مفرغ واجتهد به أن يصحبه فأبى عليه وصحب عباد بن زياد فقال له سعيد بن عثمان أما إذ أبيت أن تصحبني وآثرت عبادا فاحفظ ما أوصيك به إن عبادا رجل لئيم فإياك والدالة عليه وإن دعاك إليها من نفسه فإنها خدعة منه لك عن نفسك وأقلل زيارته فإنه طرف ملول ولا تفاخره وإن فاخرك فإنه لا يحتمل لك ما كنت احتمله ثم دعا سعيد بمال فدفعه إلى ابن مفرغ\nوقال استعن به على سفرك فإن صلح لك مكانك من عباد وإلا فمكانك عندي ممهد فائتني ثم سار سعيد إلى خراسان وتخلف ابن مفرغ عنه وخرج مع عباد قال ابن دريد في خبره عن مسلمة بن محارب\nفلما بلغ عبيد الله بن زياد صحبه ابن مفرغ أخاه عبادا شق عليه فلما سار أخوه عباد شيعه وشيع الناس معه وجعلوا يودعونه ويودع الخارجون مع عباد عبيد الله بن زياد فلما أراد عبيد الله أن يودع أخاه دعا ابن مفرغ فقال له إنك سألت عبادا أن تصحبه وأجابك إلى ذلك وقد شق علي فقال له ابن مفرغ ولم أصلحك الله\nقال لأن الشاعر لا يقنعه من الناس ما يقنع بعضهم من بعض لأنه يظن فيجعل الظن يقينا ولا يعذر في موضع العذر وإن عبادا يقدم على أرض حرب فيشتغل بحروبه وخراجه عنك فلا تعذره أنت وتكسبنا شرا وعارا فقال له لست كما ظن الأمير وإن لمعروفه عندي لشكرا كثيرا وإن عندي - إن أغفل أمري - عذرا ممهدا\nقال لا ولكن تضمن لي إن أبطأ عنك ما تحبه ألا تعجل عليه حتى تكتب إلي قال قال نعم قال امض إذا على الطائر الميمون قال فقدم عباد خراسان واشتغل بحربه وخراجه فاستبطأه ابن مفرغ ولم يكتب إلى عبيد الله بن زياد يشكوه كما ضمن له ولكنه بسط لسانه فذمه وهجاه وكان عباد عظيم اللحية كأنها جوالق فسار يزيد بن مفرغ يوما مع عباد فدخلت الريح فنفشتها فضحك ابن مفرغ وقال لرجل من لخم كان إلى جنبه قوله\n(ألا ليت اللحى كانت حشيشا ... فنعلفها خيول المسلمينا)\nسعى به اللخمي إلى عباد فغضب من ذلك غضبا شديدا وقال لا يجمل بي عقوبته في هذه الساعة مع الصحبة لي وما أؤخرها إلا لأشفي نفسي منه لأنه كان يقوم فيشتم أبي في عدة مواطن وبلغ الخبر ابن مفرغ فقال إني لأجد ريح الموت من عباد ثم دخل عليه فقال له أيها الأمير إني كنت مع سعيد بن عثمان وقد بلغك رأيه في ورأيت جميل أثره علي وإني اخترتك عليه فلم أحظ منك بطائل وأريد أن تأذن لي في الرجوع فلا حاجة لي في صحبتك فقال له أما اختيارك إياي فإني اخترتك كما اخترتني واستصحبتك حين سألتني وقد أعجلتني عن بلوغ محبتي فيك وقد طلبت الإذن لترجع إلى قومك فتفضحني فيهم وأنت على الإذن قادر بعد أن أقضي حقك فأقام وبلغ عبادا أنه يسبه ويذكره وينال من عرضه وأجرى عباد الخيل فجاء سابقا فقال ابن مفرغ\n(سبق عباد وصلت لحيته ... )\nطلب عليه العلل ودس إلى قوم كان لهم عليه دين فأمرهم أن يقدموه إليه ففعلوا فحبسه وأضر به فبعث إليه أن بعني الأراكة وبردا وكانت الأراكة قينة لابن مفرغ ويرد غلامه رباهما وكان شديد الضن بهما فبعث إليه ابن مفرغ مع الرسول أيبيع المرء نفسه أو ولده فأضر به عباد حتى\nأخذهما منه هذه رواية مسلمة وأما لقيط وعمر بن شبة فإنهما ذكرا أنه باعهما عليه فاشتراهما رجل من أهل خراسان قال لقيط فلما دخلا منزله\nقال له برد وكان داهية أريبا أتدري ما اشتريت قال نعم اشتريتك وهذه الجارية قال لا والله ما اشتريت إلا العار والدمار والفضيحة أبدا ما حييت فجزع الرجل","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":1,"spl":"ابن مفرغ وعباد بن زياد","tags":["الهجاء"],"loc":3236,"partial":1},
{"id":"b242-3","bab":"الجزء 18","sec":"ابن مفرغ وعباد بن زياد","page":"ج18 ص264","text":"وقال له كيف ذلك ويلك قال نحن ليزيد بن ربيعة بن مفرغ والله ما أصاره إلى هذه الحال إلا لسانه وشره أفتراه يهجو ابن زياد وهو أمير خراسان وأخوه أمير العراقين وعمه الخليفة في أن استبطأه ويمسك عنك وقد ابتعتني وابتعت هذه الجارية وهي نفسه التي بين جنبيه والله ما أرى أحدا أدخل بيته أشأم على نفسه وأهله مما أدخلته منزلك فقال فاشهد أنك وإياها له فإن شئتما أن تمضيا إليه فامضيا على أني أخاف على نفسي إن بلغ ذلك ابن زياد وإن شئتما أن تكونا له عندي فافعلا\nقال فاكتب إليه بذلك فكتب الرجل إلى ابن مفرغ في الحبس بما فعله فكتب إليه يشكر فعله وسأله أن يكونا عنده حتى يفرج الله عنه قال وقال عباد لحاجبه ما أرى هذا يعني ابن مفرغ يبالي بالمقام في الحبس فبع فرسه وسلاحه وأثاثه واقسم ثمنها بين غرمائه ففعل ذلك وقسم الثمن بينهم وبقيت عليه بقية حبسه بها فقال ابن مفرغ يذكر غلامه بردا وجاريته الأراكة وبيعهما\n(شريت بردا ولو ملكت صفقته ... لما تطلبت في بيع له رشدا)\n(لولا الدعي ولولا ما تعرض لي ... من الحوادث ما فارقته أبدا)\n(يا برد ما مسنا برد أضر بنا ... من قبل هذا ولا بعنا له ولدا)\n(أما الأراك فكانت من محارمنا ... عيشا لذيذا وكانت جنة رغدا)\n(كانت لنا جنة كنا نعيش بها ... نفنى بها إن خشينا الأزل والنكدا)\n(يا ليتني قبل ما ناب الزمان به ... أهلي لقيت على عدوانه الأسدا)\n(قد خاننا زمن لم نخش عثرته ... من يأمن اليوم أم من ذا يعيش غدا)\n(لامتني النفس في برد فقلت لها ... لا تهلكي إثر برد هكذا كمدا)\n(كم من نعيم أصبنا من لذاذته ... قلنا له إذ تولى ليته خلدا)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":2,"spl":"ابن مفرغ وعباد بن زياد","tags":["الحب والغزل","الجواري والنساء"],"loc":3237},
{"id":"b242-4","bab":"الجزء 18","sec":"هربه إلى البصرة","page":"ج18 ص268","text":"قالوا وعلم ابن مفرغ أنه أقام على ذم عباد وهجائه وهو في محبسه زاد نفسه شرا فكان يقول للناس إذا سألوه عن حبسه ما سببه رجل أدبه أمير ليقوم من أوده أو يكف من غربه وهذا العمري خير من جر الأمير ذيله على مداهنة لصاحبه فلما بلغ عبادا قوله رق له وأخرجه من السجن فهرب حتى أتى البصرة ثم خرج منها إلى الشام وجعل ينتقل في مدنها هاربا ويهجو زيادا وولده وقال المدائني في خبره لما بلغ عباد بن زياد أن ابن المفرغ قال\n(سبق عباد وصلت لحيته ... )\nعا ابنه والمجلس حافل فقال له له أنشدني هجاء أبيك الذي هجي به فقال أيها الأمير ما كلف أحد قط ما كلفتني فأمر غلاما له أعجميا وقال له قم على رأسه فإن أنشد ما أمرته به وإلا فصب السوط على رأسه أبدا أو ينشده فأنشده أبياتا هجي بها أبوه أولها\n(قبح الأله ولا يقبح غيره ... وجه الحمار ربيعة بن مفرغ)\nوجعل عباد يتضاحك به فخرج ابن ابن مفرغ من عنده وهو يقول والله لا يذهب شتم شيخي باطلا وقال يهجوه بقوله\n(أصرمت حبلك من أمامه ... من بعد أيام برامه)\n(فالريح تبكي شجوها ... والبرق يضحك في الغمامه)\n(لهفي على الأمر الذي ... كانت عواقبه ندامه)\n(تركي سعيدا ذا الندى ... والبيت ترفعه الدعامه)\n(فتحت سمرقند له ... وبنى بعرصتها خيامه)\n(وتبعت عبد بني علاج ... تلك أشراط القيامه)\n(جاءت به حبشية ... سكاء تحسبها نعامه)\n(وشريت بردا ليتني ... من بعد برد كنت هامه)\n(أو بومة تدعو صدى ... بين المشقر واليمامه)\n(فالهول يركبه الفتى ... حذر المخازي والسآمه)\n(والعبد يقرع بالعصا ... والحر تكفيه الملامه)\nال ثم لج في هجاء بني زياد حتى تغنى أهل البصرة في أشعاره فطلبه عبيد الله طلبا شديدا حتى كاد يؤخذ فلحق بالشام واختلفت الرواة فيمن رده إلى ابن زياد فقال بعضهم معاوية وقال\nبعضهم يزيد والصحيح أنه يزيد لأن عباد بن زياد إنما ولي سجستان في أيام يزيد وقال بعضهم بل الذي ولاه معاوية وهو الذي ولى سعيد بن عثمان خراسان\nأخبرني محمد بن العباس اليزيدي وعبيد الله بن محمد الرازي قالا حدثنا أحمد بن الحارث عن المدائني قال دخل سعيد بن عثمان على معاوية بن أبي سفيان فقال علام جعلت يزيد ولي عهدك دوني فوالله لأبي خير من أبيه وأمي خير من أمه وأنا خير منه وقد وليناك فما عزلناك وبنا نلت ما نلت فقال له معاوية أما قولك إن أباك خير من أبيه فقد صدقت لعمر الله إن عثمان لخير مني وأما قولك إن أمك خير من أمه فحسب المرأة أن تكون في بيت قومها وأن يرضاها بعلها وأن ينجب ولدها وأما قولك إنك خير من يزيد فوالله يا بني ما يسرني أن لي بيزيد ملء الغوطة مثلك وأما قولك إنكم وليتموني فما عزلتموني فما وليتموني وإنما ولاني من هو خير منكم عمر فأقررتموني وما كنت بئس الوالي لكم لقد قمت بثأركم وقتلت قتلة أبيكم وجعلت الأمر فيكم وأغنيت فقيركم ورفعت الوضيع منكم فكلمه يزيد في أمره فولاه خراسان","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":3,"spl":"هربه إلى البصرة","tags":["الحب والغزل"],"loc":3238,"partialRef":{"sid":"b242-2","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b242-5","bab":"الجزء 18","sec":"رجع الحديث إلى سياقة أخبار ابن مفرغ هجاؤه بني زياد","page":"ج18 ص270","text":"قالوا فلم يزل ينتقل في قرى الشام ونواحيها ويهجو بني زياد وأشعاره فيهم ترد البصرة وتنتشر وتبلغهم فكتب عبيد الله بن زياد إلى معاوية وقال الآخرون إنه كتب إلى يزيد وهو الصحيح يقول له إن ابن مفرغ هجا زيادا وبني زياد بما هتكه في قبره وفضح بنيه طول الدهر وتعدى ذلك إلى أبي سفيان فقذفه بالزنا وسب ولده فهرب من خراسان إلى البصرة وطلبته حتى لفظته الأرض فلجأ إلى الشام يتمضغ لحومنا\nبها ويهتك أعراضنا وقد بعثت إليك بما هجانا به لتنتصف لنا منه ثم بعث بجميع ما قاله ابن مفرغ فيهم فأمر يزيد بطلبه فجعل ينتقل من بلد إلى بلد فإذا شاع خبره انتقل حتى لفظته الشام فأتى البصرة ونزل على الأحنف بن قيس فالتجأ به واستجار فقال له الأحنف إني لا أجير على ابن سمية فأعزل وإنما يجير الرجل على عشيرته فأما على سلطانه فلا فإن شئت أجرتك من بني سعد وشعرائهم فلا يريبك أحد منهم فقال له ابن مفرغ بأستاه بني سعد وما عساهم أن يقولوا في هذا ما لا حاجة لي فيه ثم أتى خالد بن عبد الله بن خالد بن أسيد فاستجار به فأبى أن يجيره فأتى عمر بن عبيد الله بن معمر فوعده وأتى طلحة الطلحات فوعده وأتى المنذر بن الجارود العبدي فأجاره وكانت بحرية بنت المنذر تحت عبيد الله وكان المنذر من أكرم الناس عليه فاغتر بذلك وأدل بموضعه منه وطلبه عبيد الله وقد بلغه وروده البصرة فقيل له أجاره المنذر بن الجارود فبعث\nعبيد الله إلى المنذر فأتاه فلما دخل عليه بعث عبيد الله بالشرط فكبسوا داره وأتوه بابن مفرغ فلم يشعر المنذر إلا بابن مفرغ قد أقيم على رأسه فقام المنذر إلى عبيد الله فكلمه فيه فقال أذكرك الله - أيها الأمير - أن تخفر جواري فإني قد أجرته فقال عبيد الله يا منذر ليمدحن أباك وليمدحنك ولقد هجاني وهجا أبي ثم تجيره علي لا ها الله لا يكون ذلك أبدا ولا أغفرها له فغضب بتطليق البتة فخرج المنذر من عنده وأقبل عبيد الله على ابن مفرغ فقال له بئسما صحبت به عبادا\nقال بئسما صحبني به عباد اخترته على سعيد وأنفقت على صحبته كل ما أفدته وكل ما أملكه وظننت أنه لا يخلو من عقل زياد وحلم معاوية وسماحة قريش فعدل عن ظني كله ثم عاملني بكل قبيح وتناولني بكل مكروه من حبس وغرم وشتم وضرب فكنت كمن شام برقا خلبا في سحاب جهام فأراق ماءه طمعا فيه فمات عطشا وما هربت من أخيك إلا لما خفت من أن يجري في إلى ما يندم عليه وقد صرت الآن في يدك فشأنك فاصنع بي ما أحببت فأمر بحبسه وكتب إلى يزيد بن معاوية يسأله أن يأذن له في قتله فكتب إليه إياك وقتله ولكن عاقبة بما ينكله ويشد سلطانك ولا تبلغ نفسه فإن له عشيرة هي جندي وبطانتي ولا ترضى بقتله مني ولا تقنع إلا بالقود منك فاحذر ذلك واعلم أنه الجد منهم ومني وأنك مرتهن بنفسه ولك في دون تلفها مندوحة تشفي من الغيظ فورد الكتاب على عبيد الله بن زياد فأمر بابن\nمفرغ فسقي نبيذا حلوا قد خلط معه الشبرم فأسهل بطنه وطيف به وهو في تلك الحال وقرن بهرة وخنزيرة فجعل يسلح والصبيان يتبعونه ويقولون له بالفارسية أين جيست فيقول آبست نبيذ است عصارات زبيبست سمية روسبيد است وجعل كلما جر الخنزيرة ضجت فجعل يقول\n(ضجت سمية لما لزها قرني ... لا تجزعي إن شر الشيمة الجزع)\nجعل يطاف به في أسواق البصرة والصبيان خلفه يصيحون به وألح عليه ما يخرج منه حتى أضعفه فسقط فعرف ابن زياد ذلك فقيل إنه لما به لا نأمن أن يموت فأمر به أن يغسل ففعلوا ذلك به فلما اغتسل قال\n(يغسل الماء ما فعلت وقولي ... راسخ منك في العظام البوالي)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":4,"spl":"رجع الحديث إلى سياقة أخبار ابن مفرغ هجاؤه بني زياد","tags":["الهجاء","المديح"],"loc":3239},
{"id":"b242-6","bab":"الجزء 18","sec":"عبيد الله يرده إلى الحبس","page":"ج18 ص273","text":"فرده عبيد الله إلى الحبس وأمره بأن يسلم محجما وقدموا له علوجا وأمر بأن يحجمهم فكان يأخذ المشارط فيقطع بها رقابهم فيتوارون منه فتركه ورده إلى محبسه وقامت الشرط على رأسه تصب عليه السياط ويقولون له احجمهم فقال\n(وما كنت حجاما ولكن أحلني ... بمنزلة الحجام نأيي عن الأهل)\nقال عمر بن شبة في خبره جمع عباد بن زياد كل شيء هجاه به ابن مفرغ وكتب به إلى أخيه عبيد الله وهو يومئذ وافد على معاوية فكان فيما\nكتب إليه قوله\n(إذا أودى معاوية بن حرب ... فبشر شعب قعبك بانصداع)\n(فأشهد أن أمك لم تباشر ... أبا سفيان واضعة القناع)\n(ولكن كان أمر فيه لبس ... على وجل شديد وامتناع)\nقوله\n(ألا أبلغ معاوية بن حرب ... مغلغلة من الرجل اليماني)\n(أتغضب أن يقال أبوك عف ... وترضى أن يقال أبوك زاني)\n(فأشهد أن رحمك من زياد ... كرحم الفيل من ولد الأتان)\n(وأشهد أنها ولدت زيادا ... وصخر من سمية غير داني)\nدخل عبيد الله بن زياد على معاوية فأنشده هذه الأشعار واستأذنه في قتله فلم يأذن له وقال أدبه أدبا وجيعا منكلا ولا تتجاوز ذلك إلى القتل وذكر باقي الحديث كما ذكره من تقدم قالوا جميعا وقال ابن مفرغ يذكر جوار المنذر بن الجارود إياه وأمانه\n(تركت قريشا أن أجاور فيهم ... وجاورت عبد القيس أهل المشقر)\n(أناس أجارونا فكان جوارهم ... أعاصير من قسو العراق المبذر)\n(فأصبح جاري من خزيمة قائما ... ولا يمنع الجيران غير المشمر)\nقال أيضا في ذلك\n(أصبحت لا من بني قيس فتنصرني ... قيس العراق ولم تغضب لنا مضر)\n(ولم تكلم قريش في حليفهم ... إذ غاب ناصره بالشام واحتضروا)\n(والله يعلم ما تخفي النفوس وما ... سرى أمية أو ما قال لي عمر)\n(وقال لي خالد قولا قنعت به ... لو كنت أعلم أنى يطلع القمر)\n(لو أنني شهدتني حمير غضبت ... دوني فكان لهم فيما رأوا عبر)\n(أو كنت جار بني هند تداركني ... عوف بن نعمان أو عمران أو مطر)\nقال أيضا يذكر ذلك وما فعل به ابن زياد\n(دار سلمى بالخبت ذي الأطلال ... كيف نوم الأسير في الأغلال)\n(أين مني السلام من بعد نأي ... فارجعي لي تحيتي وسؤالي)\n(أين مني نجائبي وجيادي ... وغزالي سقى الإله غزالي)\n(أين لا أين جنتي وسلاحي ... ومطايا سيرتها لارتحالي)\n(هدم الدهر عرشنا فتداعى ... فبلينا إذ كل عيش بالي)\n(إذ دعانا زواله فأجبنا ... كل دنيا ونعمة لزوال)\n(أم قضينا حاجاتنا فإلى الموت ... مصير الملوك والأقيال)\n(لا وصومي لربنا وزكاتي ... وصلاتي أدعو بها وابتهالي)\n(ما أتيت الغداة أمرا دنيا ... ولدى الله كابر الأعمال)\n(أيها المالك المرهب بالقتل ... بلغت النكال كل النكال)\n(فاخش نارا تشوي الوجوه ويوما ... يقذف الناس بالدواهي الثقال)\n(قد تعديت في القصاص وأدركت ... ذحولا لمعشر أقتال)\n(وكسرت السن الصحيحة مني ... لا تذلن فمنكر إذلالي)\n(وقرنتم مع الخنازير هرا ... ويميني مغلولة وشمالي)\n(وكلابا ينهشنني من ورائي ... عجب الناس ما لهن ومالي)\n(وأطلتم مع العقوبة سجنا ... فكم السجن أو متى إرسالي)\n(يغسل الماء ما صنعت وقولي ... راسخ منك في العظام البوالي)\n(لو قبلت الفداء أو رمت مالي ... قلت خذه فداء نفسي مالي)\n(لو بغيري من معشري لعب الدهر ... لما ذم نصرتي واحتيالي)\n(كم بكاني من صاحب وخليل ... حافظ الغيب حامد للخصال)\n(ليت أني كنت الحليف للخم ... وجذام أو طيىء الأجمال)\n(بدلا من عصابة من قريش ... أسلموني للخصم عند النضال)\n(البهاليل من بني عبد شمس ... فضلوا الناس بالعلا والفعال)\n(وبنو التيم تيم مرة لما ... لمع الموت في ظلال العوالي)\n(منعوا البيت بيت مكة ذا الحجر ... إذ الطير عكف في الظلال)\n(والبهاليل خالد وسعيد ... شمس دجن ووضح كالهلال)\n(في الأرومات والذرى من بني العيص ... قروم إذا تعد المعالي)\n(كنت منهم ما حرموا فحرام ... لم يراموا وحلهم من حلال)\n(وذوو المجد من خزاعة كانوا ... أهل ودي في الخصب والأمحال)\n(خذلوني وهم لذاك دعوني ... ليس حامي الذمار بالخذال)\n(لا تدعني فداك أهلي ومالي ... إن حبليك من متين الحبال)\n(حسرتا إذ أطعت أمر غواتي ... وعصيت النصيح ضل ضلالي)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":5,"spl":"عبيد الله يرده إلى الحبس","tags":["الحب والغزل","الهجاء"],"loc":3240},
{"id":"b242-7","bab":"الجزء 18","sec":"يهجو عبادا ويذكر سعيد بن عثمان","page":"ج18 ص277","text":"وقال يهجو عباد بن زياد ويذكر سعيد بن عثمان\n(أيها الشاتم جهلا سعيدا ... وسعيد في الحوادث ناب)\n(ما أبوكم مشبها لأبيه ... فاسألوا الناس بذاكم تجابوا)\n(ساد عباد وملك جيشا ... سبحت من ذاك صم صلاب)\n(إن عاما صرت فيه أميرا ... تملك الناس لعام عجاب)\nال واتصل هجاؤه زيادا وولده وهو في الحبس فرده عبيد الله إلى أخيه عباد بسجستان ووكل به رجالا ووجههم معه وكان لما هرب من عباد يهجوه ويكتب كل ما هجاه به على حيطان الخانات وأمر عبيد الله الموكلين به أن يأخذوه بمحو ما كتبه على الحيطان بأظافيره وأمرهم ألا يتركوه يصلي إلا إلى قبلة النصارى إلى المشرق فكانوا إذا دخلوا بعض الخانات التي نزلها فرأوا فيها شيئا مما كتبه من الهجاء أخذوه بأن يمحوه بأظافره فكان يفعل ذلك ويحكه حتى ذهبت أظافره فكان يمحوه بعظام أصابعه ودمه حتى سلموه إلى عباد فحبسه وضيق عليه قال عمر بن شبة في خبره فقال ابن مفرغ\n(سرت تحت أقطاع من الليل زينب ... سلام عليكم هل لما فات مطلب)\nويروى\n(ألا طرقتنا آخر الليل زينب ... )\n(أصاب عذابي اللون فاللون شاحب ... كما الرأس من هول المنية أشيب)\n(قرنت بخنزير وهر وكلبة ... زمانا وشان الجلد ضرب مشدب)\n(وجرعتها صهباء من غير لذة ... تصعد في الجثمان ثم تصوب)\n(وأطعمت ما إن لا يحل لآكل ... وصليت شرقا بيت مكة مغرب)\n(من الطف مجنونا إلى أرض كابل ... فملوا وما مل الأسير المعذب)\n(فلو أن لحمي إذ هوى لعبت به ... كرام الملوك أو أسود وأذؤب)\n(لهون وجدي أو لزادت بصيرتي ... ولكنما أودت بلحمي أكلب)\n(أعباد ما للؤم عنك محول ... ولا لك أم في قريش ولا أب)\n(سينصرني من ليس تنفع عنده ... رقاك وقرم من أمية مصعب)\n(وقل لعبيد الله مالك والد ... بحق ولا يدري امرؤ كيف تنسب)\nي أول هذا الشعر غناء نسبته\n(ألا طرقتنا آخر الليل زينب ... سلام عليكم هل لما فات مطلب)\n(وقالت تجنبنا ولا تقربننا ... فكيف وأنتم حاجتي أتجنب)\nلغناء لسياط ثاني ثقيل بالوسطى عن الهشامي وقالوا جميعا فلما طال مقام ابن مفرغ في السجن استأجر رسولا إلى دمشق وقال له إذا كان يوم الجمعة فقف على درج جامع دمشق ثم اقرأ هذين البيتين بأرفع ما يمكنك من صوتك وكتبهما في رقعة وهما\n(أبلغ لديك بني قحطان قاطبة ... عضت بأير أبيها سادة اليمن)\n(أضحى دعي زياد فقع قرقرة ... - يا للعجائب - يلهو بابن ذي يزن)\nفعل الرسول ما أمره به فحميت اليمانية وغضبوا له ودخلوا على معاوية فسألوه فيه فدفعهم عنه فقاموا غضابا وعرف معاوية ذلك في\nوجوههم فردهم ووهبه لهم ووجه رجلا من بني أسد يقال له خمخام ويقال جهنام بريدا إلى عباد وكتب له عهدا وأمره بأن يبدأ بالحبس فيخرج ابن مفرغ منه ويطلقه قبل أن يعلم عباد فيم قدم فيغتاله ففعل ذلك به فلما خرج من الحبس قربت إليه بغلة من بغال البريد فركبها فلما استوى على ظهرها قال\n(عدس ما لعباد عليك إمارة ... نجوت وهذا تحملين طليق)\n(فإن الذي نجى من الكرب بعدما ... تلاحم في درب عليك مضيق)\n(أتاك بخمخام فأنجاك فالحقي ... بأهلك لا تحبس عليك طريق)\n(لعمري لقد أنجاك من هوة الردى ... إمام وحبل للأنام وثيق)\n(سأشكر ما أوليت من حسن نعمة ... ومثلي بشكر المنعمين حقيق)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":6,"spl":"يهجو عبادا ويذكر سعيد بن عثمان","tags":["الحب والغزل","الهجاء"],"song":1,"loc":3241,"partial":1},
{"id":"b242-8","bab":"الجزء 18","sec":"معاوية يعفو عنه","page":"ج18 ص279","text":"قال عمر بن شبة في خبره ووافقه لقيط بن بكير فلما أدخل على معاوية بكى وقال ركب مني ما لم يركب من مسلم قط على غير حدث في الإسلام ولا خلع يد من طاعة ولا جرم فقال ألست القائل\n(ألا أبلغ معاوية بن حرب ... مغلغلة من الرجل اليماني)\n(أتغضب أن يقال أبوك عف ... وترضى أن يقال أبوك زان)\n(فأشهد أن رحمك من زياد ... كرحم الفيل من ولد الأتان)\n(وأشهد أنها ولدت زيادا ... وصخر من سمية غير دان)\nقال لا والذي عظم حقك يا أمير المؤمنين ما قلته ولقد بلغني أن عبد الرحمن بن الحكم قاله ونسبه إلي قال أفلم تقل\n(شهدت بأن أمك لم تباشر ... أبا سفيان واضعة القناع)\n(ولكن كان أمر فيه لبس ... على وجل شديد وارتياع)\nولست القائل\n(إن زيادا ونافعا وأبا ... بكرة عندي من أعجب العجب)\n(إن رجالا ثلاثة خلقوا ... في رحم أنثى ما كلهم لأب)\n(ذا قرشي كما يقول وذا ... مولى وهذا بزعمه عربي)\nي أشعار كثيرة قلتها في هجاء زياد وبنيه اذهب فقد عفوت عن جرمك ولو إيانا تعامل لم يكن شيء مما كان فاسكن أي أرض شئت فاختار الموصل فنزلها ثم ارتاح إلى البصرة فقدمها فدخل على عبيد الله ابن زياد واعتذر إليه وسأله الصفح والأمان فأمنه وأقام بها مدة ثم دخل عليه بعد أن أمنه فقال أصلح الله الأمير إني قد ظننت أن نفسك لا تطيب لي بخير أبدا ولي أعداء لا آمن سعيهم علي بالباطل وقد رأيت أن أتباعد فقال له إلى أين شئت فقال كرمان فكتب له إلى شريك بن الأعور وهو عليها بجائزة وقطيعة وكسوة فشخص فأقام بها حتى هرب عبيد الله من البصرة فعاد إليها هذه رواية عمر بن شبة\nوقال محمد بن خلف في روايته عن أحمد بن الهيثم عن المدائني وعن العمري عن لقيط أن ابن مفرغ لما طال حبسه وبلاؤه ركب طلحة الطلحات إلى الحجاز ولقي قريشا - وكان ابن مفرغ حليفا لبني أمية - فقال لهم طلحة يا معشر قريش إن أخاكم وحليفكم ابن مفرغ قد ابتلي بهذه الأعبد من بني زياد وهو عديدكم وحليفكم ورجل منكم ووالله ما أحب أن يجري الله عافيته على يدي دونكم ولا أفوز بالمكرمة في أمره وتخلوا منها فانهضوا\nمعي بجماعتكم إلى يزيد بن معاوية فإن أهل اليمن قد تحركوا بالشام فركب خالد بن عبد الله بن خالد بن أسيد وأمية بن عبد الله أخوه وعمر بن عبيد الله بن معمر ووجوه من خزاعة وكنانة وخرجوا إلى يزيد فبينا هم يسيرون ذات ليلة إذ سمعوا راكبا يتغنى في سواد الليل بقول ابن مفرغ ويقول\n(إن تركي ندى سعيد بن عثمان ... بن عفان ناصري وعديدي)\n(واتباعي أخا الضراعة واللؤم ... لنقص وفوت شأو بعيد)\n(قلت والليل مطبق بعراه ... ليتني مت قبل ترك سعيد)\n(ليتني مت قبل تركي أخا النجدة ... والحزم والفعال السديد)\n(عبشمي أبوه عبد مناف ... فاز منها بتاجها المعقود)\n(ثم جود لو قيل هل من مزيد ... قلت للسائلين ما من مزيد)\n(قل لقومي لدى الأباطح من آل ... لؤي بن غالب ذي الجود)\n(سامني بعدكم دعي زياد ... خطة الغادر اللئيم الزهيد)\n(كان ما كان في الأراكة واجتب ... ببرد سنام عيسي وجيدي)\n(أوغل العبد في العقوبة والشتم ... وأودى بطارفي وتليدي)\n(فارحلوا في حليفكم وأخيكم ... نحو غوث المستصرخين يزيد)\n(فاطلبوا النصف من دعي زياد ... وسلوني بما ادعيت شهودي)\nال فدعا القوم بالراكب فقالوا له ما هذا الذي سمعناه منك تغني به فقال هذا قول رجل والله إن أمره لعجب رجل ضائع بين قريش واليمن وهو رجل الناس قالوا ومن هو قال ابن مفرغ قالوا والله ما رحلنا إلا فيه وانتسبوا له فضحك وقال أفلا أسمعكم من قوله أيضا قالوا بلى فأنشدهم قوله\n(لعمري لو كان الأسير ابن معمر ... وصاحبه أو شكله ابن أسيد)\n(ولو أنهم نالوا أمية أرقلت ... براكبها الوجناء نحو يزيد)\n(فأبلغت عذرا في لؤي بن غالب ... وأتلفت فيهم طارفي وتليدي)\n(فإن لم يغيرها الإمام بحقها ... عدلت إلى شم شوامخ صيد)\n(فناديت فيهم دعوة يمنية ... كما كان آبائي دعوا وجدودي)\n(ودافعت حتى أبلغ الجهد عنهم ... دفاع امرىء في الخير غير زهيد)\n(فإن لم تكونوا عند ظني بنصركم ... فليس لها غير الأغر سعيد)\n(بنفسي وأهلي ذاك حيا وميتا ... نضار وعود المرء أكرم عود)\n(فكم من مقام في قريش كفيته ... ويوم يشيب الكاعبات شديد)\n(وخصم تحاماه لؤي بن غالب ... شببت له ناري فهاب وقودي)\n(وخير كثير قد أفأت عليكم ... وأنتم رقود أو شبيه رقود)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":7,"spl":"معاوية يعفو عنه","tags":["الهجاء"],"loc":3242},
{"id":"b242-10","bab":"الجزء 18","sec":"معاوية يعفو عنه — وفد اليمانية إلى يزيد بن معاوية","page":"ج18 ص279 – ج18 ص282","text":"ال فاسترجع القوم لقوله وقالوا والله لا نغسل رؤوسنا في العرب إن لم نغسلها بفكه فأغذ القوم السير حتى قدموا الشام\nوبعث ابن مفرغ رجلا من بني الحارث بن كعب فقام على سور\nحمص فنادى بأعلى صوته الحصين بن نمير - وكان والي حمص - بهذه الأبيات وكان عظيم الجبهة\n(أبلغ لديك بني قحطان قاطبة ... عضت بأير أبيها سادة اليمن)\n(أمسى دعي زياد فقع قرقرة ... - يا للعجائب - يلهو بابن ذي يزن)\n(والحميري طريح وسط مزبلة ... هذا لعمركم غبن من الغبن)\n(ولأجبه ابن نمير فوق مفرشه ... يدنو إلى أحور العينين ذي غنن)\n(قوموا فقولوا أمير المؤمنين لنا ... حق عليك ومن ليس كالمنن)\n(فاكفف دعي زياد عن أكارمنا ... ماذا يريد على الأحقاد والإحن)\nاجتمعت اليمانية إلى حصين فعيروه بما قاله ابن مفرغ فقال الحصين ليس لي رأي دون يزيد بن أسد ومخرمة بن شرحبيل فأرسل إليهما فاجتمعوا في منزل الحصين فقال لهما الحصين اسمعا ما أهدى إلي شاعركم وقاله لكم في أخيكم - يعني نفسه - وأنشدهم فقال يزيد بن\nأسد قد جئتكم بأعظم من هذا وهو قوله\n(وما كنت حجاما ولكن أحلني ... بمنزلة الحجام نأيي عن الأصل)\nقال الحصين والله لقد أساء إلينا أمير المؤمنين في صاحبنا مرتين إحداهما أنه هرب إليه فلم يجره وأخرى أنه أمر بعذابه غير مراقب لنا فيه\nوقال يزيد بن أسد إني لأظن أن طاعتنا ستفسد ويمحوها ما فعل بابن مفرغ ولقد تطلع من نفسي شيء للموت أحب إلي منه وقال مخرمة بن شرحبيل أيها الرجلان اعقلا فإنه لا معاوية لكما واعرفا أن صاحبكما لا تقدح فيه الغلظة فاقصدا التضرع فركب القوم إلى دمشق وقدموا على يزيد بن معاوية وقد سبقهم الرجل فنادى بذلك الشعر يوم الجمعة على درج مسجد دمشق فثارت اليمانية وتكلموا ومشى بعضهم إلى بعض وقدم وفد القرشيين في أمره مع طلحة الطلحات فسبقوا القرشيين ودخلوا على يزيد بن معاوية فتكلم الحصين بن نمير فذكر بلاءه وبلاء قومه وطاعتهم\nوقال يا أمير المؤمنين إن الذي أتاه ابن زياد إلى صاحبنا لا قرار عليه وقد سامنا عبيد الله وعباد خطة خسف وقلدانا قلادة عار فأنصف كريمنا من صاحبه فوالله لئن قدرنا لنعفون ولئن ظلمنا لننتصرن\nوقال يزيد بن أسد يا أمير المؤمنين إنا لو رضينا بمثلة ابن زياد بصاحبنا وعظيم ما انتهك منه لم يرض الله عز ذكره بذلك ولئن تقربنا إليك بما يسخط الله ليباعدننا الله منك وإن يمانيتك قد نفرت لصاحبها نفرة طار غرابها وما أدري متى يقع وكل نائرة تقدح في الملك وإن صغرت لم يؤمن أن تكبر وإطفاؤها خير من إضرامها لا سيما إذا كانت في أنف لا يجدع ويد لا تقطع فأنصفنا من ابني زياد وقال مخرمة بن شرحبيل وكان متألها عظيم الطاعة في أهل اليمن إنه\nلا يد تحجزك عن هواك ولو مثلت بأخينا وتوليت ذلك منه بنفسك لم يقم فيه قائم ولم يعاتبك فيه معاتب ولكن ابني زياد استخفانا بما يثقل عليك من حقنا وتهاونا بما تكرمه منا وأنت بيننا وبين الله ونحن بينك وبين الناس فأنصفنا من صاحبيك ولينفعنا بلاؤنا عندك فقال يزيد إن صاحبكم أتى عظيما نفي زيادا من أبي سفيان ونفى عبادا وعبيد الله من زياد وقلدهم طوق الحمامة وما شجعه على ذلك إلا نسبه فيكم وحلفه في قريش فأما إذ بلغ الأمر ما أرى وأشفى بكم على ما أشفى فهو لكم وعلي رضاكم","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":8,"spl":"معاوية يعفو عنه — وفد اليمانية إلى يزيد بن معاوية","tags":["السفر والحج"],"loc":3243},
{"id":"b242-11","bab":"الجزء 18","sec":"وفد القرشيين إلى يزيد","page":"ج18 ص285","text":"قال وانتهى القرشيون إلى الحاجب فاستأذن لهم وقال لليمانيين قد أتتكم برى الذهب من أهل العراق فدخلوا وسلموا والغضب يتبين في وجوههم فظن يزيد الظنون\nوقال لهم ما لكم انفتق فتق أو حدث حدث فيكم قالوا لا فسكن فقال طلحة الطلحات يا أمير المؤمنين أما كفى العرب ما لقيت من زياد حتى استعملت عليها ولده يستكثرون لك أحقادها ويبغضونك إليها إن عبيد الله وأخاه أتيا إلى ابن مفرغ ما قد بلغك فأنصفنا منهما إنصافا تعلم العرب أن لنا منك خلفا من أبيك فوالله لقد خبأ لك فعلهما خبئا عند أهل اليمن لا تحمده لك ولا تحمده لنفسك وتكلم خالد بن عبد الله بن خالد بن أسيد فقال يا أمير المؤمنين إن زيادا ربي في شر حجر ونشأ في أخبث نشء فأثبتم نصابه في قريش وحملتموه على رقاب الناس فوثب ابناه على أخينا وحليفنا وحليفك ففعلا به الأفاعيل التي بلغتك وقد غضبت له قريش\nالحجاز ويمن الشام ممن لا أجب والله لك غضبه فأنصفنا من ابني زياد وتكلم أخوه أمية بنحو مما تكلم أخوه وقال والله يا أمير المؤمنين لا أحط رحلي ولا أخلع ثياب سفري أو تنصفنا من ابني زياد أو تعلم العرب أنك قد قطعت أرحامنا ووصلت ابني زياد بقطعنا وحكمت بغير الحق لهما علينا\nوقال ابن معمر يا أمير المؤمنين إن ابن مفرغ طالما ناضل عن عرضك وعرض أبيك وأعراض قومك ورمى عن جمرة أهلك وقد أتى بنو زياد فهي ما لو كان معاوية حيا لم يرض به وهذا رجل له شرف في قومه وقد نفروا له نفرة لها ما بعدها فأعتبهم وأنصف الرجل ولا تؤثر مرضاة ابني زياد على مرضاة الله عز و جل","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":9,"spl":"وفد القرشيين إلى يزيد — اعتذاره لعبيد الله بن زياد","tags":["السفر والحج"],"loc":3244},
{"id":"b242-12","bab":"الجزء 18","sec":"يزيد يرحب بالوفدين","page":"ج18 ص286","text":"فقال يزيد مرحبا بكم وأهلا والله لو أصابه خالد ابني بما ذكرتم لأنصفته منه ولو رحلتم في جميع ما تحيط به العراق لوهبته لكم وما عندي إلا إنصاف المظلوم ولكن صاحبكم أسرف على القوم وكتب يزيد ببناء داره ورد ماله وتخلية سبيله وألا إمرة لأحد من بني زياد عليه\nوقال لولا أن في القود بعد ما جرى منه فسادا في الملك لأقدته من عباد وسرح يزيد رجلا من حمير يقال له خمخام وكتب معه إلى عباد بن زياد نفسك نفسك وإن تسقط من ابن مفرغ شعرة فأقيدك والله به ولا سلطان لك ولا لأخيك ولا لأحد غيري عليه فجاء خمخام حتى انتزعه جهارا من الحبس بمحضر الناس وأخرجه قالوا فلما دخل على يزيد قال له يا أمير المؤمنين اختر مني خصلة\nمن ثلاث خصال في كلها لي فرج إما أن تقيدني من ابن زياد وإما أن تخلي بيني وبينه وإما أن تقدمني فتضرب عنقي فقال له يزيد قبح الله ما اخترته وخيرتنيه أما القود من ابن زياد فما كنت لأقيدك من عامل كان عليك ظلمته وشتمت عرضه وعرضي معه وأما التخلية بينك وبينه فلا ولا كرامة ما كنت لأخلي بينك وبين أهلي تقطع أعراضهم وأما ضرب عنقك فما كنت لأضرب عنق مسلم من غير أن يستحق ذلك ولكني أفعل ما هو خير لك مما اخترته لنفسك أعطيك ديتك فإنهم قد عرضوك للقتل واكفف عن ولد زياد فلا يبلغني أنك ذكرتهم وانزل أي البلاد شئت وأمر له بعشرة آلاف درهم","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":9,"spl":"وفد القرشيين إلى يزيد — اعتذاره لعبيد الله بن زياد","tags":["الحب والغزل"],"loc":3245},
{"id":"b242-13","bab":"الجزء 18","sec":"اعتذاره لعبيد الله بن زياد","page":"ج18 ص287","text":"فخرج حتى أتى الموصل وأقام ما شاء الله ثم خرج ذات يوم يتصيد فلقي دهقانا على حمار له فقال من أين أقبلت قال من العراق قال من أيها قال من البصرة ثم من الأهواز\nقال فما فعل المسرقان قال على حاله قال أفتعرف أناهيد بنت أعنق قال نعم قال ما فعلت قال على أحسن ما عهدت قال فضرب برذونه وسار حتى أتى الأهواز ولم يعلم أهله ولا غيرهم بمسيره ثم أتى عبيد الله بن زياد فدخل عليه واعتذر إليه وسأله الأمان فأمنه ثم سأله أن يكتب له إلى شريك بن الأعور فكتب له ووصله","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":9,"spl":"وفد القرشيين إلى يزيد — اعتذاره لعبيد الله بن زياد","tags":["الجواري والنساء"],"loc":3246},
{"id":"b242-14","bab":"الجزء 18","sec":"هجاؤه بني زياد","page":"ج18 ص288","text":"وخرج فأقام بكرمان حتى غلب ابن الزبير على العراق وهرب ابن زياد وكان أهل البصرة قد أجمعوا على قتله فخرج عن البصرة هاربا فعاد ابن مفرغ إلى البصرة وعاود هجاء بني زياد فقال يذكر هرب عبيد الله وتركه أمه بقوله\n(أعبيد هلا كنت أول فارس ... يوم الهياج دعا بحتفك داع)\n(أسلمت أمك والرماح تنوشها ... يا ليتني لك ليلة الإفزاع)\n(إذ تستغيث وما لنفسك مانع ... عبد تردده بدار ضياع)\n(هلا عجوزك إذ تمد بثديها ... وتصيح ألا تنزعن قناعي)\n(أنقذت من أيدي العلوج كأنها ... ربداء مجفلة ببطن القاع)\n(فركبت رأسك ثم قلت أرى العدا ... كثروا وأخلف موعدي أشياعي)\n(فانجى بنفسك وابتغي نفقا فما ... لي طاقة بك والسلام وداعي)\n(ليس الكريم بمن يخلف أمه ... وفتاته في المنزل الجعجاع)\n(حذر المنية والرماح تنوشه ... لم يرم دون نسائه بكراع)\n(متأبطا سيفا عليه يلمق ... مثل الحمار أثرته بيفاع)\n(لا خير في هذر يهز لسانه ... بكلامه والقلب غير شجاع)\n(لابن الزبير غداة يذمر منذرا ... أولى بغاية كل يوم وقاع)\n(وأحق بالصبر الجميل من امرىء ... كز أنامله قصير الباع)\n(جعد اليدين عن السماحة والندى ... وعن الضريبة فاحش مناع)\n(كم يا عبيد الله عندك من دم ... يسعى ليدركه بقتلك ساع)\n(ومعاشر أنف أبحت حريمهم ... فرقتهم من بعد طول جماع)\n(اذكر حسينا وابن عروة هانئا ... وابني عقيل فارس المرباع)\nقال أيضا يذكر هربه\n(أقر بعيني أنه عق أمه ... دعته فولاها استه وهو يهرب)\n(وقال عليك الصبر كوني سبية ... كما كنت أو موتي فذلك أقرب)\n(وقد هتفت هند بماذا أمرتني ... أبن لي وحدثني إلى أين أذهب)\n(فقال اقصدي للأزد في عرصاتها ... وبكر فما إن عنهم متجنب)\n(أخاف تميما والمسالح دونها ... ونيران أعدائي علي تلهب)\n(وولى وماء العين يغسل وجهها ... كأن لم يكن والدهر بالناس قلب)\n(بما قدمت كفاك لا لك مهرب ... إلى أي قوم والدماء تصبب)\n(فكم من كريم قد جررت جريرة ... عليه فمقبور وعان يعذب)\n(ومن حرة زهراء قامت بسحرة ... تبكي قتيلا أو صدى يتأوب)\n(فصبرا عبيد بن العبيد فإنما ... يقاسي الأمور المستعد المجرب)\n(وذق كالذي قد ذاق منك معاشر ... لعبت بهم إذ أنت بالناس تلعب)\n(فلو كنت حرا أو حفظت وصية ... عطفت على هند وهند تسحب)\n(وقاتلت حتى لا تري لك مطمعا ... بسيفك في القوم الذين تحزبوا)\n(وقلت لأم العبد أمك إنني ... وإن كثر الأعداء حام مذبب)\n(ولكن أبى قلب أطيرت بناته ... وعرق لكم في آل ميسان يضرب)\nقال في ذلك أيضا\n(ألا أبلغ عبيد الله عني ... عبيد اللؤم عبد بني علاج)\n(علي لكم قلائد باقيات ... يثرن عليكم نقع العجاج)\n(تدعيت الخضارم من قريش ... فما في الدين بعدك من حجاج)\n(أبن لي هل بيثرب زند ورد ... قرى آبائك النبط العجاج)\nقال فيه أيضا\n(عبيد الله عبد بني علاج ... كذاك نسبته وكذاك كانا)\n(أعبد الحارث الكندي ألا ... جعلت لإست أمك ديدبانا)\n(فتستر عورة كانت قديما ... وتمنع أمك النبط البطانا)\nقال يهجو عبيد الله وعبادا أنشدناه جماعة منهم هاشم بن محمد الخزاعي عن دماذ عن أبي عبيدة وهذا من قصيدة له طويلة أولها\n(جرت أم الظباء ببين ليلى ... وكل وصال حبل لانقطاع)\nقول فيها\n(ولا لاقيت من أيام بؤس ... ولا أمر يضيق به ذراعي)\n(ولم تك شيمتي عجزا ولؤما ... ولم أك بالمضللل في المساعي)\n(سوى يوم الهجين ومن يصاحب ... لئام الناس يغض على القذاع)\n(حلفت برب مكة لو سلاحي ... بكفي إذ تنازعني متاعي)\n(لباشر أم رأسك مشرفي ... كذاك دواؤنا وجع الصداع)\n(أفي أحسابنا تزري علينا ... هبلت وأنت زائدة الكراع)\n(تبغيت الذنوب علي جهلا ... جنونا ما جننت ابن اللكاع)\n(فما أسفي على تركي سعيدا ... وإسحاق بن طلحة واتباعي)\n(ثنايا الوبر عبد بني علاج ... عبيدة فقع قرقرة بقاع)\n(إذا ما راية رفعت لمجد ... وودع أهلها خير الوداع)\n(فأير في است أمك من أمير ... كذاك يقال للحمق اليراع)\n(ولا بلت سماؤك من أمير ... فبئس معرس الركب الجياع)\n(ألم تر إذ تحالف حلف حرب ... عليك غدوت من سقط المتاع)\n(وكدت تموت أن صاح ابن آوى ... ومثلك مات من صوت السباع)\n(ويوم فتحت سيفك من بعيد ... أضعت وكل أمرك للضياع)\n(إذ أودى معاوية بن حرب ... فبشر شعب قعبك بانصداع)\n(فأشهد أن أمك لم تباشر ... أبا سفيان واضعة القناع)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":10,"spl":"هجاؤه بني زياد","tags":["الهجاء"],"loc":3247},
{"id":"b242-15","bab":"الجزء 18","sec":"هجاؤه بني زياد","page":"ج18 ص288","text":"(ولكن كان أمرا فيه لبس ... على عجل شديد وارتياع)\nقال وكان عباد في بعض حروبه ذات ليلة نائما في عسكره فصاحت بنات آوى فثارت الكلاب إليها ونفر بعض الدواب ففزع عباد وظنها كبسة من العدو فركب فرسه ودهش فقال افتحوا سيفي فعيره بذلك ابن مفرغ ومما قاله ابن مفرغ في هجاء بني زياد وغني فيه\n(كم بالدروب وأرض الهند من قدم ... ومن جماجم قتلى ما هم قبروا)\n(ومن سرابيل أبطال مضرجة ... ساروا إلى الموت ما خاموا ولا ذعروا)\n(بقندهار ومن تحتم منيته ... بقندهار يرجم دونه الخبر)\nغنى في هذه الأبيات ابن جامع\n(أجد أهلك لا يأتيهم خبر ... منا ولا منهم عين ولا أثر)\n(ولم تكلم قريش في حليفهم ... إذ غاب أنصاره بالشام واحتضروا)\n(لو أنني شهدتني حمير غضبت ... إذا فكان لها فيما جرى غير)\n(رهط الأغر شراحيل بن ذي كلع ... ورهط ذي فائش ما فوقهم بشر)\n(قولا لطلحة ما أغنت صحيفتكم ... وهل لجارك إذ أوردته صدر)\n(فمن لنا بشقيق أو بأسرته ... ومن لنا ببني ذهل إذا خطروا)\n(هم الذين سموا والخيل عابسة ... والناس عند زياد كلهم حذر)\n(لولاهم كان سلام بمنزلتي ... أولى لهم ثم أولى بعدما ظفروا)\nخبرني محمد بن خلف عن أبي بكر العامري عن إسحاق بن محمد عن القحذمي قال هجا سلام الرافعي مقاتل بن مسمع فقال فيه\n(أبى لك يا ذا المجد أن مقاتلا ... زنى واستحل الفارسي المشعشعا)\nفي أبيات هجاه بها فحبسه مقاتل بالعربة فركب شقيق بن ثور في جماعة من بني ذهل إلى الحبس فأخرجه فضرب به ابن مفرغ المثل في الشعر الماضي أخبرني محمد بن خلف بن المرزبان قال حدثني أبو عبد الله اليماني قال حدثنا الأصمعي عن عبد الرحمن بن أبي الزناد قال قال لي عبيد الله بن زياد ما هجيت بشيء أشد علي من قول ابن مفرغ\n(فكر ففي ذاك إن فكرت معتبر ... هل نلت مكرمة إلا بتأمير)\n(عاشت سمية ما تدري وقد عمرت ... أن ابنها من قريش في الجماهير)\nروى اليزيدي في روايته عن الأحول قال أبو عبيدة كان زياد يزعم أن أمه سمية بنت الأعور من بني عبد شمس بن زيد مناة بن تميم فقال ابن مفرغ يرد ذلك عليه\n(فأقسم ما زياد من قريش ... ولا كانت سمية من تميم)\n(ولكن نسل عبد من بغي ... عريق الأصل في النسب اللئيم)\nخبرني هاشم بن محمد قال حدثنا أبو غسان دماذ قال أنشدني أبو عبيدة لابن مفرغ يهجو ابن زياد ويرميه بالأبنة\n(أبلغ قريشا قضها وقضيضها ... أهل السماحة والحلوم الراجحه)\n(أني ابتليت بحية ساورته ... بيد لعمري لم تكن لي رابحه)\n(صفق المبخل صفقة ملعونة ... جرت عليه من البلايا فادحه)\n(شتان من بطحاء مكة داره ... وبنو المضاف إلى السباخ المالحه)\n(جعدت أنامله ولام نجاره ... وبذاك تخبرنا الظباء السانحه)\n(فإذا أمية صلصلت أحسابها فبنو زياد في الكلاب النابحه ... )\n(قالوا يناك فقلت في جوف استه ... وبذاك خبرني الصدوق الفاضحه)\n(لم يبق أير أسود أو أبيض ... إلا له استك في الخلاء مصافحه)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":11,"spl":"هجاؤه بني زياد","tags":["الحب والغزل"],"song":1,"loc":3248,"partial":1},
{"id":"b242-16","bab":"الجزء 18","sec":"مقتل عبيد الله بن زياد","page":"ج18 ص294","text":"وأخبرني إبراهيم بن السري بن يحيى قال حدثني أبي عن شعيب عن سيف قال\nلما قتل عبيد الله بن زياد يوم الزاب قتله أصحاب المختار بن أبي عبيد ويقال إن إبراهيم بن الأشتر حمل على كتيبته فانهزموا ولقي عبيد الله فضربه فقتله وجاءه إلى أصحابه فقال إني ضربت رجلا فقددته نصفين فشرقت يداه وغربت رجلاه وفاح منه المسك وأظنه ابن مرجانة وأومأ لهم إلى موضعه فجاؤوا إليه وفتشوا عليه فوجدوه كما ذكر وإذا هو ابن زياد فقال ابن مفرغ يهجوه\n(إن الذي عاش ختارا بذمته ... وعاش عبدا قتيل الله بالزاب)\n(العبد للعبد لا أصل ولا طرف ... ألوت به ذات أظفار وأنياب)\n(إن المنايا إذا ما زرن طاغية ... هتكن عنه ستورا بين أبواب)\n(هلا جموع نزار إذ لقيتهم ... كنت امرأ من نزار غير مرتاب)\n(لا أنت زاحمت عن ملك فتمنعه ... ولا مددت إلى قوم بأسباب)\n(ما شق جيب ولا ناحتك نائحة ... ولا بكتك جياد عند أسلاب)\n(لا يترك الله أنفا تعطسون بها ... بني العبيد شهودا غير غياب)\n(أقول بعدا وسحقا عند مصرعه ... لابن الخبيثة وابن الكودن الكابي)\nوالقصيدة المذكورة بها غناء فيه منها وقال\n(حي ذا الزور وانهه أن يعودا ... إن بالباب حارسين قعودا)\n(من أساوير ما ينون قياما ... وخلاخيل تذهل المولودا)\n(وطماطيم من مشايخ جون ... ألبسوني مع الصباح قيودا)\n(أي بلوى معيشة قد بلونا ... فنعمنا وما رجونا خلودا)\n(ودهور لقيننا موجعات ... وزمان يكسر الجلمودا)\n(فصبرنا على مواطن ضيق ... وخطوب تصير البيض سودا)\n(ظل فيها النصيح يرسل سرا ... لا تهالن إن سمعت الوعيدا)\n(أفإنس ما هكذا صبر إنس ... أم من الجن أم خلقت حديدا)\n(لا ذعرت السوام في فلق الصبح ... مغيرا ولا دعيت يزيدا)\n(يوم أعطي مخافة الموت ضيما ... والمنايا يرصدنني أن أحيدا)\nال وهي قصيدة طويلة وتمثل الحسين بن علي صلوات الله عليه بهذين البيتين لما خرج من المدينة إلى مكة عند بيعة يزيد\n(لا ذعرت السوام في فلق الصبح ... مغيرا ولا دعيت يزيدا)\n(يوم أعطي مخافة الموت ضيما ... والمنايا يرصدنني أن أحيدا)\nدثني أحمد بن عيسى أبو موسى العجلي العطار بالكوفة فقال حدثني الحسين بن نصر بن مزاحم المنقري قال حدثني أبي قال حدثنا عمر بن\nسعد عن أبي مخنف قال حدثني عبد الملك بن نوفل بن مساحق عن أبي سعيد المقبري قال والله لرأيت حسينا عليه السلام وهو يمشي بين رجلين يعتمد على هذا مرة وعلى هذا مرة حتى دخل المسجد وهو يقول لا ذعرت السوام البيتين قال فقلت عند ذلك إنه لا يلبث إلا قليلا حتى يخرج فما لبث أن خرج فلحق بمكة فلما خرج من المدينة قال ( فخرج منها خائفا أن يترقب قال رب نجني من القوم الظالمين\nولما توجه نحو مكة قال ( ولما توجه تلقاء مدين قال عسى ربي أن يهديني سواء السبيل","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":12,"spl":"مقتل عبيد الله بن زياد","tags":[],"loc":3249},
{"id":"b242-17","bab":"الجزء 18","sec":"ابن مفرغ ومروان بن الحكم","page":"ج18 ص297","text":"أخبرني جعفر بن قدامة قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الصباح عن ابن الكلبي قال لما قدم ابن مفرغ إلى معاوية مع خمخام الذي وجهه إليه فانتزعه من عباد بن زياد نزل على مروان بن الحكم وهو يومئذ عند معاوية فأعطاه وكساه وقام بأمره واسترفد له كل من قدر عليه من بني أبي العاص بن أمية فقال ابن مفرغ يمدحه من قصيدته\n(وأقمتم سوق الثناء ولم تكن ... سوق الثناء تقام في الأسواق)\n(فكأنما جعل الإله إليكم ... قبض النفوس وقسمة الأرزاق)\nأخبرني هشام بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان ابن مفرغ يهوى أناهيد بنت الأعنق وكان الأعنق دهقانا من الأهواز له ما بين الأهواز وسرق ومناذر والسوس وكان لها أخوات يقال لهن أسماء والجمانة وأخرى قد سقط اسمها عن دماذ فكان يذكرهن جميعا في شعره فمن ذلك قوله في صاحبته أناهيد من أبيات\n(سيري أناهيد بالعيرين آمنة ... قد سلم الله من قوم بهم طبع)\n(لا بارك الله فيهم معشرا جبنا ... ولا سقى دارهم قطرا ولا ربعوا)\n(السارقين إذا جاعوا نزيلهم ... والأخبثين بطونا كلما شبعوا)\n(لا تأمنن حزاميا نزلت به ... قوم لديهم تناهى اللؤم والصرع)\n(جاور بني خلف تحمد جوارهم ... الأعظمين دفاعا كلما دفعوا)\n(والمطعمين إذا ما شتوة أزمت ... فالناس شتى إلى أبوابهم شرع)\n(هم خير قومهم إن حدثوا صدقوا ... أو حاولوا النفع في أشياعهم نفعوا)\n(المانعين من المخزاة جارهم ... والرافعين من الأدنين ما صنعوا)\n(انزل بطلحة يوما إن منزله ... سهل المباءة بالعلياء مرتفع)\nفي أسماء أختها يقول\n(تعلق من أسماء ما قد تعلقا ... ومثل الذي لاقى من الحب أرقا)\n(وحسبك من أسماء نأي وأنها ... إذا ذكرت هاجت فؤادا معلقا)\n(سقى هزم الإرعاد منبجس العرى ... منازلها بالمسرقان فسرقا)\n(وتستر لا زالت خصيبا جنابها ... الى مدفع السلان من بطن دورقا)\n(إلى الكوثج الأعلى إلى رامهرمز ... الى قريات الشيح من فوق سفسقا)\nامهرمز بلد من أعمال الأهواز معروف\n(بلاد بنات الفارسية إنها ... سقتنا على لوح شرابا معتقا)\nخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي وأخبرنا هاشم بن محمد قال حدثنا دماذ أبو غسان عن أبي عبيدة قالا لما فصل ابن مفرغ من عند معاوية نزل بالموصل على أخواله من آل ذي العشراء من حمير\nقال الهيثم في روايته فزوجوه امرأة منهم ولم يذكر ذلك أبو عبيدة فلما كان اليوم الذي يكون البناء في ليلته خرج يتصيد ومعه غلامه برد فإذا هو بدهقان على حمار يبيع عطرا وأدهانا فقال له ابن مفرغ من أين أقبلت\nقال من الأهواز قال ويحك كيف خلفت المسرقان وبرد مائة قال على حاله قال ما فعلت دهقانة يقال لها أناهيد بنت أعنق قال أصديقه ابن مفرغ قال نعم\nقال ما تجف جفونها من البكاء عليه فقال لغلامه أي برد أما تسمع قال بلى قال هو بالرحمن كافر إن لم يكن هذا وجهي إليها فقال له برد أكرمك القوم وقاموا دونك وزوجوك كريمتهم ثم تصنع هذا بهم وتقدم على ابن زياد بعد\nخلاصك منه من غير أمره ولا عهد منه ولا عقد ابق أيها الرجل على نفسك وأقم بموضعك وابن بأهلك وانظر في أمرك فإن جد عزمك كنت حينئذ وما تختاره قال دع ذا عنك هو بالرحمن كافر إن عدل عن الأهواز ولا عرج على شيء غيرها ومضى لوجهه من غير أن يعلم أهله وقال قصيدته\n(سما برق الجمانة فاستطارا ... لعل البرق ذاك يحور نارا)\n(قعدت له العشاء فهاج شوقي ... وذكرني المنازل والديارا)\n(ديار للجمانة مقفرات ... بلين وهجن للقلب ادكارا)\n(فلم أملك دموع العين مني ... ولا النفس التي جاشت مرارا)\n(بسرق فالقرى من صهرتاج ... فدير الراهب الطلل القفارا)\n(فقلت لصاحبي عرج قليلا ... نذاكر شوقنا الدرس البوارا)\n(بآية ما غدوا وهم جميع ... فكاد الصب ينتحر انتحارا)\n(فقال بكوا لفقدك منذ حين ... زمانا ثم إن الحي سارا)\n(بدجلة فاستمر بهم سفين ... يشق صدورها اللجج الغمارا)\n(كأن لم أغن في العرصات منها ... ولم أذعر بقاعتها صوارا)\n(ولم أسمع غناء من خليل ... وصوت مقرطق خلع العذار)\nال فقدم البصرة فذكر لعبيد الله بن زياد مقدمه فلم يعرض له وأرسل إليه أن أقم آمنا فأقام بالبصرة أشهرا يختلف من البصرة إلى الأهواز فيزور أناهيد ويقيم عندها","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":13,"spl":"ابن مفرغ ومروان بن الحكم","tags":["الحب والغزل"],"loc":3250},
{"id":"b242-19","bab":"الجزء 18","sec":"ابن مفرغ ومروان بن الحكم — ابن مفرغ وعبيد الله بن أبي بكرة","page":"ج18 ص297 – ج18 ص301","text":"ثم أتى عبيد الله بن زياد فقال له إني امرؤ لي أعداء ولست آمن بعضهم أن يقول شيئا على لساني يحفظ الأمير علي وأحب أن يأذن لي أن أتنحى عنه فقال له حل حيث شئت فخرج حتى قدم على شريك بن الأعور الحارثي وهو يومئذ عامل عبيد الله بن زياد على فارس وكرمان فأعطاه ثلاثين ألف درهم فقدم بها الأهواز فأعطاها أناهيد\nأخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ قال حدثني محمد بن الحكم عن عوانة أن عبيد الله بن أبي بكرة كتب إلى يزيد بن مفرغ إني قد توجهت إلى سجستان فالحق بي فلعلك إن قدمت علي ألا تندم ولا يذم رأيك فتجهز ابن مفرغ وخرج حتى قدم سحستان ممسيا فدخل عليه فشغله بالحديث وأمر له بمنزل وفرش وخدم وجعل يطاوله حتى علم أنه قد استتم له ما أمر له به ثم صرفه إلى المنزل الذي قد هيىء له ثم دعا به في اليوم الثاني فقال له يابن مفرغ إنك فد تجشمت إلي شقة بعيدة واتسع لك الأمل فرحلت إلي لأقضي عنك دينك ولأغنيك عن الناس وقلت أبو حاتم بسجستان فمن لي بالغنى بعده فقال والله ما أخطأت أيها الأمير ما كان في نفسي فقال عبيد الله أما والله لأفعلن ولأقلن لبثك عندي ولأحسنن صلتك وأمر له بمائة ألف درهم ومائة وصيفة ومائة نجيبة وأمر له بما ينفقه إلى أن يبلغ بلده سوى المائة الألف وبمن يكفيه الخدمة من غلمانه وأعوانه وقال له إن من خفة السفر ألا تهتم بخف ولا حافر وكان مقامه عنده سبعة أيام\nثم ارتحل وشيعه عبيد الله إلى قرية على أربعة فراسخ يقال لها زالق ثم قال له يا بن مفرغ إنه ينبغي للمودع أن ينصرف وللمتكلم أن يسكت وأنا من قد عرفت فأبق على الأمل وحسن ظنك بي ورجائك في وإذا بدا لك أن تعود فعد والسلام\nقال وسار ابن مفرغ حتى أتى رامهرمز فنزل بقرية أبجر فنزلت إليه بنت الأبجر فقالت يا بن مفرغ لمن هذا المال قال لابنة أعنق دهقانة الأهواز وإذا رسولها في القافلة بكتابها إنك لو كنت على العهد الأول لتعجلت إلي ولم تساير ثقلك ولكن قد علمت أن المال الذي أعطاكه عبيد الله قد شغلك عني قال فأعطى رسولها مالا على أن يقول فيه خيرا وقد قال لابنة أبجر في جواب قولها له\n(حباني عبيد الله يابنة أبجر ... بهذا وهذا للجمانة أجمع)\n(يقر بعيني أن أراها وأهلها ... بأفضل حال ذاك مرأى ومسمع)\n(وخبرتها قالت لقد حال بعدنا ... فقد جعلت نفسي إليها تطلع)\n(وقلت لها لما أتاني رسولها ... وأي رسول لا يضر وينفع)\n(أحبك ما دامت بنجد وشيجة ... وما رفعت يوما إلى الله إصبع)\n(وإني ملء يا جمانة بالهوى ... وصدق الهوى إن كان ذلك يقنع)\nال فلما انتهت رسل عبيد الله بن أبي بكرة معه إلى الأهواز قالوا له\nقد بلغنا حيث أمرنا قال أجل ثم أمر ابنة أعنق أن تفتح الباب وقال لها كل ما دخل دارك فهو لك","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":14,"spl":"ابن مفرغ ومروان بن الحكم — ابن مفرغ وعبيد الله بن أبي بكرة","tags":["الحب والغزل"],"loc":3251},
{"id":"b242-20","bab":"الجزء 18","sec":"مدحه عبيد الله بن أبي بكرة","page":"ج18 ص303","text":"وأقام بالأهواز ودعا ندماء كانوا له من فتيان العرب فلم يبق طريف ولا مغن إلا أتاه واستماحه جماعة قصدوه من أهل البصرة والكوفة والشام فأعطاهم ولم يفارق أناهيد ومعه شيء من المال وجعل القوم يسألونه عن عبيد الله بن أبي بكرة وكيف هو وأخلاقه وجوده فقال\n(يسائلني أهل العراق عن الندى ... فقلت عبيد الله حلف المكارم)\n(فتى حاتمي في سجستان رحله ... وحسبك جودا أن يكون كحاتم)\n(سما لينال المكرمات فنالها ... بشدة ضرغام وبذل الدراهم)\n(وحلم إذا ما سورة الحقد أطلقت ... حبا القوم عند الفادح المتفاقم)\n(وإن له في كل حي صنيعة ... يحدثها الركبان أهل المواسم)\n(دعاني إليه جوده ووفاؤه ... ومن دون مسراه عداة الأعاجم)\n(فلم أبق إلا جمعة في جواره ... ويومين حلا من ألية آثم)\n(إلى أن دعاني زانه الله بالعلا ... فأنبت ريشي من صميم القوادم)\n(وقال إذا ما شئت يا بن مفرغ ... فعد عودة ليست كأضغاث حالم)\n(فقلت له - لا يبعد الله داره - ... أعود إذا ما جئتكم غير حاشم)\n(وأحمدت وردي إذ وردت حياضه ... وكل كريم نهزة للأكارم)\n(فأصبح لا يرجو العراق وأهله ... سواه لنفع أو لدفع العظائم)\n(وإن عبيد الله هنأ رفده ... سراحا وأعطى رفده غير غانم)\nقال الهيثم في خبره كان عمرو بن مفرغ عم يزيد بن ربيعة بن مفرغ رجلا له جاه وقدر عند السلطان وكان ذا مال وثروة وذا دين وفضل وصلاح فكان يعنف ابن أخيه في أمر أناهيد عشيقته ويعذله ويعيره بها فلما أكثر عليه أتاه يوما فقال له يا عم جعلت فداك إن لي بالأهوازحاجة ولي على قوم بها نحو من ثلاثين ألف درهم قد خفت أن تتوى علي فإن رأيت أن تتجشم العناء معي إليها حتى تطالب لي بحقي وتعينني بجاهك على غرمائي وكان عمرو بن مفرغ قد استخلفه ابن عباس عليها إذ كان عامل أمير المؤمنين علي بن أبي طالب صلوات الله عليه وعلى آله على البصرة وكان عامل الأهواز حين سأل ابن مفرغ عمه أن يخرج معه ميمون بن عامر أخو بني قيس بن ثعلبة الذي يقال لدراهمه اليوم اليمونية فلم يزل ابن مفرغ بعمه حتى أجابه إلى الخروج فاستأجر سفينة وتوجه إلى الأهواز وكتب إلى أناهيد أن تهيئي وتزيني بأحسن زينتك واخرجي إلي مع جواريك فإني موافيك ومنزلها يومئذ بين سرق ورامهرمز فلما نزلوا منزلها خرجت إليهم وجلست معهم في هيئتها وزيها وحليها وآلتها فلما رآها عمه\nقال له قبحك الله أفهلا إذ فعلت ما فعلت كنت علقت مثل هذه فقال يا عم أوقد أعجبتك فقال ومن لا تعجبه هذه قال ألجد هذا منك قال نعم والله\nقال فإنها والله هذه بعينها فقال يا خبيث إنما أشخصتني لهذا يا غلام ارحل بنا فانصرف عمه إلى البصرة وأقام هو معها ولم يزل يتررد كذلك حتى مات في الطاعون في أيام مصعب بن الزبير\nأخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا القحذمي قال لزم يزيد بن مفرغ غرماؤه بدين فقال لهم انطلقوا نجلس على باب الأمير عسى أن يخرج الأشراف من عنده فيروني فيقضوا عني فانطلقوا به فكان أول من خرج إما عمر بن عبيد الله بن معمر وإما طلحة الطلحات فلما رآه\nقال أبا عثمان ما أقعدك ها هنا قال غرمائي هؤلاء لزموي بدين لهم علي قال وكم هو قال سبعون ألفا قال علي منها عشرة آلاف درهم ثم خرج الآخر على الأثر فسأله كما سأل صاحبه فقال هل خرج أحد قبلي قالوا نعم فلان\nقال فما صنع قالوا ضمن عشرة آلاف درهم قال فعلي مثلها قال ثم جعل الناس يخرجون فمنهم من يضمن الألف إلى أكثر من ذلك حتى ضمنوا أربعين ألفا وكان يأمل عبيد الله بن أبي بكرة فلم يخرج حتى غربت الشمس فخرج مبادرا فلم يره حتى كاد يبلغ بيته فقيل له إنك مررت بابن مفرغ ملزوما وقد مر به الأشراف فضمنوا عنه فقال واسوأتاه إني أخاف أن يظن أني تغافلت عنه فكر راجعا فوجده قاعدا فقال له أبا عثمان ما يجلسك ها هنا قال غرمائي هؤلاء يلزمونني قال كم عليك قال سبعون ألفا قال وكم ضمن عنك قال أربعون ألفا قال فاستمتع بها وعلي\nدينك أجمع فقال فيه يخاطب نفسه\n(لو شئت لم تغني ولم تنصبي ... عشت بأسباب أبي حاتم)\n(عشت بأسباب الجواد الذي ... لا يختم الأموال بالخاتم)\n(من كف بهلول له عدة ... ما إن لمن عاداه من عاصم)\n(المطعم الناس إذا حاردت ... نكباؤها في الزمن العارم)\n(والفاصل الخطة يوم اللجا ... للأمر عند الكربة اللازم)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":15,"spl":"مدحه عبيد الله بن أبي بكرة","tags":["الجواري والنساء","السفر والحج"],"loc":3252},
{"id":"b242-21","bab":"الجزء 18","sec":"مدحه عبيد الله بن أبي بكرة","page":"ج18 ص303","text":"(جاورته حينا فأحمدته ... أثني وما الحامد كاللائم)\n(كم من عدو شامت كاشح ... أخزيته يوما ومن ظالم)\n(أذقته الموت على غرة ... بأبيض ذي رونق صارم)\nخبرني عمي قال حدثني أبو أيوب المديني قال حدثني حماد بن إسحاق عن أبيه قال قدم بديح الكوفة فغنى بها دهرا وأصاب مالا كثيرا ثم خرج إلى البصرة ثم أتى الأهواز ثم عاد إلى البصرة فصحب ابن مفرغ في سفينة حتى إذا كان في نهر معقل تغنى وهو لا يعرف ابن مفرغ بقوله\n(سما برق الجمانة فاستطارا ... لعل البرق ذاك يعود نارا)\nال فطرب ابن مفرغ وقال يا ملاح كر بنا إلى الأهواز فكر وهو يغنيه ثم كر راجعا إلى البصرة وكروا معه وهو يعيد هذا الصوت قال ووصل ابن مفرغ بديحا وكساه\n\n(رضيت الهوى إذ حل بي متخيرا ... نديما وما غيري له من ينادمه)\n(أعاطيه كأس الصبر بيني وبينه ... يقاسمنيها مرة وأقاسمه)\nقال إن الشعر لبشار والغناء للزبير بن دحمان هزج بالوسطى عن الهشامي وأحمد بن المكي","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":16,"spl":"مدحه عبيد الله بن أبي بكرة","tags":["الحب والغزل"],"song":1,"loc":3253},
{"id":"b242-22","bab":"الجزء 18","sec":"الزبير والرشيد","page":"ج18 ص308","text":"قد مضت أخبار أبيه ونسبه وولاؤه في متقدم الكتاب وكان الزبير أحد المحسنين المتقنين الرواة الضراب المتقدمين في الصنعة وقدم على الرشيد من الحجاز وكان المغنون في أيامة حزبين أحدهما في حزب إبراهيم الموصلي وابنه إسحاق والآخر في حزب ابن جامع وابن المهدي وكان إبراهيم بن المهدي أوكد أسباب هذا التحزب والتعصب لما كان بينه وبين إسحاق وكان الزبير بن دحمان في حزب إسحاق وأخوه عبيد الله في حزب إبراهيم بن المهدي فأخبرني محمد بن مزيد\nقال حدثني حماد بن إسحاق عن أبيه قال لما قدم الزبير بن دحمان على الرشيد من الحجاز قدم رجل ما شئت من رجل عقلا ونبلا ودينا وأدبا وسكونا ووقارا وكان أبوه قبله كذلك وقدم معه أخوه عبيد الله فلما وصلا إلى الرشيد وجلسا معنا تخيلت في الزبير الفضل فقلت لأبي يا أبت أخلق بالزبير أن يكون أفضل من أخيه فقال هذا لا يجيء بالظن والتخيل والجواد إنما يمتحن في الميدان فقلت له فالجواد عينه فراره فضحك وقال ننظر في فراستك فلما غنيا بان فضل الزبير وتقدمه فاصطفاه أبي واصطفيته لأنفسنا وقرظناه ووصفناه وصار\nفي حيزنا وغنى الرشيد غناء كثيرا من غناء المتقدمين فأجاد وأحسن وسأله الرشيد أن يغنيه شيئا من صنعته فالتوى بعض الإلتواء وقال قد سمع أمير المؤمنين غناء الحذاق من المتقدمين وغناء من بحضرته من خدمه ومن وفد عليه من الحجازيين وما عسى أن يأتي من صنعتي فأقسم عليه أن يغنيه شيئا من صنعته وجد به في ذلك فكان أول صوت غناه منها\n(ارحلا صاحبي حان الرحيل ... وابكياني فليس تبكي الطلول)\n(قد تولى النهار وانقضت الشمس ... يمينا وحان منها أفول)\nحن هذا الصوت خفيف ثقيل قال فسمعت والله صنعة حسنة متقنة لا مطعن عليها فطرب الرشيد واستعاده هذا الصوت ثلاث مرات وأمر له بثلاثين ألف درهم ولأخيه بعشرين ألف درهم ثم لم يزل زبير معنا كواحد منا وانحاز عبيد الله إلى جنبه إبراهيم بن المهدي فكان معه\nقال حماد فقلت لأبي كيف كانت صنعة عبيد الله قال أنا أجمل لك القول لو كان زبير مملوكا لاشتريته بعشرين ألف دينار ولو كان عبيد الله مملوكا ما طابت نفسي على أن أشتريه بأكثر من عشرين دينارا فقلت قد أجبتني بما يكفيني حدثني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي ومحمد بن الحارث بن\nبسخنر أن الرشيد كتب في إشخاص الزبير بن دحمان إلى مدينة السلام فوافاها واتفق قدومه في وقت خروج الرشيد إلى الري لمحاربة بندارهرمز أصبهذ طبرستان فأقام الزبير بمدينة السلام إلى أن دخل الرشيد فلما قدم دخل عليه بالخيزرانة وهو الموضع الذي يعرف بالشماسية فغناه في أول غنائه صوتا في شعر قاله هو أيضا في الرشيد مدحه به وذكر خروجه إلى طبرستان وهو\n(ألا إن حزب الله ليس بمعجز ... وأنصاره في منعة المتحرز)\n(أبى الله أن يعصى لهارون أمره ... وذلت له طوعا يد المتعزز)\n(إذا الراية السوداء راحت أو اغتدت ... إلى هارب فليس بمعجز)\n(لطاعت لهارون العداة لدى الوغى ... وكبر للإسلام بندار هرمز)\nم أجد هذا الصوت منسوبا في شيء من الكتب إلا في كتاب بذل وهو فيه غير مجنس وذكر إبراهيم بن المهدي أن الشعر للزبير بن دحمان وهذا خطأ الشعر لأبي العتاهية وهو موجود في شعره من قصيدة طويلة مدح بها الرشيد قال أبو إسحاق فاستحسن الرشيد الشعر والغناء وأمر له بألف دينار فدفعت إليه ومكث ساعة ثم غنى صوتا ثانيا وهو\n\n(وأحور كالغصن يشفي السقام ... ويحكي الغزال إذا ما رنا)\n(شربت المدام على وجهه ... وعاطيته الكأس حتى انثنى)\n(وقلت مديحا أرجي به ... من الأجر حظا ونيل الغنى)\n(وأعني بذاك الإمام الذي ... به الله أعطى العباد المنى)\nلحن هذا الصوت ثاني ثقيل مطلق قال فما فرغ من الصوت حتى أمر له بألف دينار آخر فقبضه وخف على قلبه واستظرفه فأغناه في مدة يسيرة من الأيام أخبرني عيسى بن الحسين الوراق قال حدثنا عبد الله بن أبي سعد قال حدثني أبو توبة عن القطراني عن محمد بن حبيب قال كان الرشيد بعد قتله البرامكة شديد الأسف عليهم والتندم على ما فعله بهم ففطن الزبير بن دحمان فكان يغنيه في هذا المعنى ويحركه فغناه يوما والشعر لامرأة من بني أسد\n(من للخصوم إذا جد الخصام بهم ... يوم النزال ومن للضمر القود)","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":17,"spl":"الزبير والرشيد","tags":[],"song":3,"loc":3254},
{"id":"b242-23","bab":"الجزء 18","sec":"الزبير والرشيد","page":"ج18 ص308","text":"(وموقف قد كفيت الناطقين به ... في مجمع من نواصي الناس مشهود)\n(فرجته بلسان غير ملتبس ... عند الحفاظ وقول غير مردود)\nقال له الرشيد أعد فأعاد فقال له ويحك كأن قائل هذا الشعر يصف به يحيى بن خالد وجعفر بن يحيى وبكى حتى جرت دموعه ووصل الزبير صلة سنية","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":18,"spl":"الزبير والرشيد — الزبير وإسحاق","tags":[],"loc":3255},
{"id":"b242-24","bab":"الجزء 18","sec":"الزبير وإسحاق","page":"ج18 ص312","text":"أخبرني الحسين بن يحيى عن حماد قال كان أبي يقول ما كان دحمان يساوي على الغناء أربعمائة درهم وأشبه خلق الله به غناء ابنه عبيد الله وكان يفضل الزبير بن دحمان على أبيه وأخيه تفضيلا بعيدا وفي الزبير يقول إسحاق وله فيه غناء وهو\n(أسعد بدمعك يا أبا العوام ... صبا صريع هوى ونضو سقام)\n(ذكر الأحبة فاستجن وهاجه ... للشوق نوح حمامة وحمام)\n(لم يبد ما في الصدر إلا أنه ... حيا العراق وأهله بسلام)\n(ودعاه داع للهوى فأجابه ... شوقا إليه وقاده بزمام)\nلشعر والغناء لإسحاق ثقيل أول بالوسطى عن عمرو وهذا الشعر قاله إسحاق وهو بالرقة مع الرشيد يتشوق إلى العراق أخبرني عمي قال حدثني علي بن محمد بن نصر قال حدثني جدي حمدون بن إسماعيل قال قال لي إسحاق كنا مع الرشيد بالرقة وخرج يوما إلى ظهرها يصيد وكنت في موكبه أساير الزبير بن دحمان فذكرني بغداد وطيبها وأهلي وإخواني وحرمي فتشوقت لذلك شوقا شديدا وعرض لي هم وفكر حتى أبكاني فقال لي الزبير مالك يا أبا محمد فشكوت إليه ما عرض وقلت\n(أسعد بدمعك يا أبا العوام ... صبا صريع هوى ونضو سقام)\nذكر باقي الأبيات وعلمت أن الخبر سينمي إلى الرشيد فصنعت في الأبيات لحنا فلما جلس الرشيد للشرب ابتدأت فغنيته إياه فقال لي\nتشوقت والله يا إسحاق وشوقت وبلغت ما أردت وأمر لي بثلاثين ألف درهم وللزبير بعشرين ألفا ورحل إلى بغداد بعد أيام أخبرني يحيى بن علي بن يحيى المنجم قال أخبرني أبي قال قال لي إسحاق وأخبرني به الحسن بن علي قال حدثنا عبد الله بن عمرو بن أبي سعد قال حدثني محمد بن عبد الله بن مالك عن إسحاق قال جاءني الزبير بن دحمان ذات يوم مسلما فاحتبسته فقال قد أمرني الفضل بن الربيع بأن أصير إليه فقلت\n(أقم يا أبا العوام ويحك نشرب ... ونلهو مع اللاهين يوما ونطرب)\n(إذا ما رأيت اليوم قد جاء خيره ... فخذه بشكر واترك الفضل يغضب)\nال فأقام عندي فشربنا باقي يومنا ثم سار الزبير إلى الفضل فسأله عن سبب تأخره عنه فحدثه بالحديث وأنشده الشعر فغضب وحول وجهه عني وأمر عونا حاجبه ألا يدخلني اليوم ولا يستأذن لي عليه ولا يوصل لي رقعة إليه قال فقلت\n(حرام علي الكأس ما دمت غضبانا ... وما لم يعد عني رضاك كما كانا)\n(فأحسن فإني قد أسأت ولم تزل ... تعودني عند الإساءة إحسانا)\nقال وأنشدته إياهما فضحك ورضي عني وعاد لي إلى ما كان عليه\nوأخبرني الحسين بن يحيى عن حماد عن أبيه بهذا الخبر فذكر نحو ما ذكره الآخران وزاد فيه وقلت في عون حاجبه\n(عون يا عون ليس مثلك عون ... أنت لي عدة إذا كان كون)\n(لك عندي والله إن رضي الفضل ... غلام يرضيك أو برذون)\nأتى عون الفضل بالشعرين جميعا فلما قرأهما ضحك وقال له ويلك إنما عرض لك بقوله غلام يرضيك بالسوأة فقال قد وعدني ما سمعت فإن شئت أن تحرمنيه فأنت أعلم فأمره أن يرسل إلي وأتاني رسوله فضرت إليه ورضي عني أخبرني الحسن بن علي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني إسحاق قال كان عندي الزبير بن دحمان يوما فغنيت لحن أبي\n(أشاقك من أرض العراق طلول ... تحمل منها جيرة وحمول)\nقال لي الزبير أنت الأستاذ وابن الأستاذ السيد وقد أخذت عن أبيك هذا الصوت وأنا أغنيه أحسن فقلت له والله إني لا أحب أن يكون ذلك كذلك فغضب\nوقال فأنا والله أحسن غناء منك وتلاحينا طويلا فقلت له هلم نخرج إلى صحراء الرقة فيكون اكلنا وشربنا هناك ونرضى في الحكم بأول من يطلع علينا\nقال أفعل فأخرجنا طعامنا وشرابنا وجلسنا نشرب على الفرات فأقبل حبشي يحفر الأرض بالبال فقلت له أترضى بهذا قال نعم فدعوناه فأطعمناه وسقيناه وبدرني الزبير بالغناء فغنى الصوت فطرب الحبشي وحرك رأسه حتى طمع الزبير في ثم أخذت العود فغنيته فتأملني\nالحبشي ساعة ثم صاح وأي شيطان هوه ومد بها صوته فما أذكر أني ضحكت مثل ضحكي يومئذ وانخذل الزبير","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":18,"spl":"الزبير والرشيد — الزبير وإسحاق","tags":["الحب والغزل"],"song":1,"loc":3256},
{"id":"b242-25","bab":"الجزء 18","sec":"نسبه هذا الصوت","page":"ج18 ص315","text":"\n(أشاقك من أرض العراق طلول ... تحمل منها جيرة وحمول)\n(وكيف ألذ العيش بعد معاشر ... بهم كنت عند النائبات أصول)\nلشعر لأبي العتاهية والغناء لإبراهيم ثقيل أول بالسبابة في مجرى البنصر عن أحمد بن المكي وفيه للحسين بن محرز ثقيل أول بالوسطى وهذا البيتان من قصيدة مدح بها أبو العتاهية الفضل بن الربيع قال أنشدنيها عبد الله بن الربيع الربيعي قال أنشدنيها أبو سويد عبد القوي بن محمد بن أبي العتاهية لجده يمدح الفضل بن الربيع وإنما ذكرت ذلك ها هنا لأن من الناس من ينسبهما إلى غيره فذكرت الأبيات الأول وفيها يقول في مدح الفضل بن الربيع\n(قبائل من أقصى وأدنى تجمعت ... فهن على آل الربيع كلول)\n(تمر ركاب السفر تثني عليهم ... عليها من الخير الكثير حمول)\n(إليك أبا العباس حنت بأهلها ... مغان وحنت ألسن وعقول)\n(وأنت جبين الملك بل أنت سمعه ... وأنت لسان الملك حين تقول)\n(وللملك ميزان يداك تقيمه ... يزول مع الإحسان حيث يزول)\nدثني الصولي قال حدثني المغيرة بن محمد المهلبي قال حدثنا الزبير قال حدثني رجل من ثقيف قال غضب الرشيد على أم جعفر ثم ترضاها فأبت أن ترضى عنه فأرق\nليله ثم قال افرشوا لي على دجلة ففعلوا فقعد ينظر إلى الماء وقد رأى زيادة عجيبة فسمع غناء في هذا الشعر\n(جرى السيل فاستبكاني السيل إذ جرى ... وفاضت له من مقلتي غروب)\n(وما ذاك إلا حين خيرت أنه ... يمر بواد أنت منه قريب)\n(يكون أجاجا ماؤه فإذا انتهى ... إليكم تلقى طيبكم فيطيب)\n(فيا ساكني شرقي دجلة كلكم ... الى القلب من أجل الحبيب حبيب)\nالشعر للعباس بن الأحنف والغناء للزبير بن دحمان خفيف رمل بالوسطى عن الهشامي فسأل عن الناحية التي فيها الغناء فقيل دار ابن المسيب فبعث إليه أن ابعث بالمغني فإذا هو الزبير بن دحمان فسأله عن الشعر فقال هو للعباس بن الأحنف فأحضر واستنشده فأنشده إياه وجعل الزبير يغنيه وعباس ينشده وهو يستعيدهما حتى أصبح وقام فدخل إلى أم جعفر فسألت عن سبب دخوله فعرفته فوجهت إلى العباس بألف دينار وإلى الزبير بألف دينار أخرى\nأخبرني عمي قال حدثني علي بن محمد عن جده حمدون قال تشوق الرشيد بغداد وهو بالرقة فانحدر إليها وأقام بها مدة وخلف هناك بعض جواريه وكانت حظية له فيهن خلفها لمغاضبة كانت بينه\nوبينها فتشوقها تشوقا شديدا وقال فيها\n(سلام على النازح المغترب ... تحية صب به مكتئب)\n(غزال مراتعه بالبليخ ... إلى دير زكى فجسر الخشب)\n(أيا من أعان على نفسه ... بتخليفه طائعا من أحب)\n(سأستر والستر من شيمتي ... هوى من أحب لمن لا أحب)\nجمع المغنين فحضر إبراهيم الموصلي وابن جامع وفليح وزبير بن دحمان والمعلى بن طريف وحسين بن محرز وسليم بن سلام ويحيى المكي وابنه وإسحاق وأبو زكار الأعمى وأعطاهم الشعر\nوقال ليعمل كل واحد منكم فيه لحنا قال فلقد عملوا فيه عشرين لحنا فما أعجب منها إلا بلحن الزبير وحده أعجب به إعجابا شديدا وأجازه خاصة دون الجماعة بجائزة سنية غنى إبراهيم في هذه الأبيات ولحنه ماخوري بالوسطى ولفليح فيها ثاني ثقيل بالوسطى ولابن جامع رمل بالبنصر ولابن المكي ثقيل أول بالوسطى وللزبير بن دحمان خفيف ثقيل بالسبابة في مجرى البنصر وللمعلى خفيف رمل بالوسطى ولإسحاق رمل بالوسطى وللحسين بن محرز هزج بالوسطى\n\n(يا ناعش الجد إذا الجد عثر ... وجابر العظم إذا العظم انكسر)\n(أنت ربيعي والربيع ينتظر ... وخير أنواء الربيع ما بكر)\nلشعر للعماني الراجز والغناء لشارية خفيف رمل من كتاب ابن المعتز وروايته","topic":"أخبار ابن مفرغ ونسبه","topicNo":242,"sp":19,"spl":"نسبه هذا الصوت","tags":["الحب والغزل"],"song":4,"loc":3257},
{"id":"b243-1","bab":"الجزء 18","sec":"نسب العماني وخبره","page":"ج18 ص318","text":"اسمه محمد بن ذويب بن محجن بن قدامة بن بلهية الحنظلي ثم الدارمي صليبة وقيل العماني وهو بصري لأنه كان شديد صفرة اللون وليس هو ولا أبوه من أهل عمان وكان شاعرا راجزا متوسطا من شعراء الدولة العباسية ليس من نظراء الشعراء الذين شاهدهم في عصره مثل أشجع وسلم ومروان ولكنه كان لطيفا داهيا مقبولا فأفاد بشعره أموالا جليلة","topic":"نسب العماني وخبره","topicNo":243,"sp":0,"spl":"نسب العماني وخبره","tags":["اللهو والمزاح"],"loc":3258},
{"id":"b243-2","bab":"الجزء 18","sec":"العماني والرشيد","page":"ج18 ص319","text":"أخبرني ابن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن جبر بن رياط الأسدي أن عبد الملك بن صالح أدخل العماني على الرشيد فأنشده\n(يا ناعش الجد إذا الجد عثر ... وجابر العظم إذا العظم انكسر)\n(أنت ربيعي والربيع ينتظر ... وخير أنواء الربيع ما بكر)\nقال له الرشيد إذا يبكر عليك ربيعنا يا فضل أعطه خمسة آلاف دينار وخمسين ثوبا قال إسحاق قال جبر لما دخل الرشيد الرقة استقبله العماني فلما\nبصر به ناداه\n(هارون يا بن الأكرمين منصبا ... لما ترحلت فصرت كثبا)\n(من أرض بغداد تؤم المغربا ... طابت لنا ريح الجنوب والصبا)\n(ونزل الغيث لنا حتى ربا ... ما كان من نشز وما تصوبا)\n(فمرحبا ومرحبا ومرحبا ... )\nقال له الرشيد وبك مرحبا يا عماني وأهلا وأجزل صلته أخبرني محمد بن جعفر النحوي صهر المبرد المعروف بابن الصيدلاني قال حدثنا محمد بن موسى عن حماد قال قال العتبي لما وجه الفضل بن يحيى الوفد من خراسان إلى الرشيد يحضونه على البيعة لابنه محمد قعد لهم الرشيد وتكلم القوم على مراتبهم وأظهروا السرور بما دعاهم إليه من البيعة لابنه وكان فيمن حضر محمد بن ذؤيب العماني فقام بين صفوف القواد ثم أنشأ يقول\n(لما أتانا خبر مشهر ... أغر لا يخفى على من يبصر)\n(جاء به الكوفي والمبصر ... والراكب المنجد والمغور)\n(يخبر الناس وما يستخبر ... قلت لأصحابي ووجهي مسفر)\n(وللذرجال حسبكم لا تكثروا ... فاز بها محمد فأقصروا)\n(قد كان هذا قبل هذا يذكر ... في كتب العلم التي تسطر)\n(فقل لمن كان قديما يتجر ... قد نشر العدل فبيعوا واشتروا)\n(وشرقوا وغربوا وبشروا ... فقد كفى الله الذي يستقدر)\n(بمنه أفعال ما قد يحذر ... والسيف عنا مغمد ما يشهر)\n(وقلد الأمر الأغر الأزهر ... نوء السماكين الذي يستمطر)\n(بوجهه إن كان عام أغبر ... سرت به أسرة ومنبر)\n(وابتهج الناس به واستبشروا ... وهللو لربهم وكبروا)\n(شكرا ومن حقهم أن يشكروا ... إذ ثبتت أوتاد ملك يعمر)\n(من هاشم في حيث طاب العنصر ... وطاح من كان عليها يزفر)\n(إن بني العباس لم يقصروا ... إذ نهضوا لملكهم فشمروا)\n(وعقدوا ونزعوا وأمروا ... ودبروا فأحكموا ما دبروا)\n(وأوردوا بالحزم ثم أصدروا ... والحزم رأي مثله لا ينكر)\n(إذا الرجال في الرجال خيروا ... يا أيها الخليفة المطهر)\n(والمؤمن المبارك الموقر ... والطيب الأغصان والمظفر)\n(ما الناس إلا غنم تنشر ... إن لم تداركهم براع يخطر)\n(على قواصي طرقها ويستر ... ويمنع الذئب فلا ينفر)\n(فامنن علينا بيد لا تكفر ... مشهورة ما دام زيت يعصر)\n(وانظر لنا وخل من لا ينظر ... واجسر كما كان أبوك يجسر)\n(لا خير في مجمجم لا يظهر ... ولا كتاب بيعة لا ينشر)\n(وقد تربصت فليس تعذر ... فليت شعري ما الذي تنتظر)\n(أأنت قائم به أم تسخر ... ما لك في محمد لا تعذر)\n(وليت شعري والحديث يؤثر ... أترقد الليل ونحن نسهر)\n(خوفا على أمورنا ونضجر ... والله والله الذي يستغفر)\n(لأن يموت معشر ومعشر ... خير لنا من فتنة تسعر)\n(يهلك فيها دينهم ويوزروا ... وقد وفى القوم الذين انتصروا)\n(لصاحب الروم وذاك أصغر ... منه وهذا البحر لا يكدر)\n(وذاكم العلج وهذا الجوهر ... ينمي به محمد وجعفر)\n(والخلفاء والنبي الأكبر ... ونبعة من هاشم وعنصر)\n(واعلم وأنت المرء لا يبصر ... والله يبقيك لنا وتجبر)\n(منا ذوي العسرة حتى يوسروا ... أن الرجال إن ولوها آثروا)\n(ذوي القرابات بها واستأثروا ... بها وضل أمرهم واستكبروا)\n(والملك لا رحم له فيأصر ... ذا رحم والناس قد تغيروا)\n(فأحكم الأمر وأنت تقدر ... فمثل هذا الأمر لا يؤخر)\nلما فرغ من أرجوزته قال له الرشيد أبشر يا عماني بولاية محمد العهد فقال إي والله يا أمير المؤمنين بشرى الأرض المجدبة بالغيث والمرأة النزور بالولد والمريض المدنف بالبرء قال ولم ذاك قال لأنه نسيج وحده وحامي مجده وموري زنده قال فما لك في عبد الله قال مرعى ولا كالسعدان فتبسم الرشيد وقال قاتله الله من أعرابي ما أعرفه\nبمواضع الرغبة وأسرعه إلى أهل البذل والعائدة وأبعده من أهل الحزم والعزم والذين لا يستمنح ما لديهم بالثناء أما والله إني لأعرف في عبد الله حزم المنصور ونسك المهدي وعز نفس الهادي ولو أشاء أن أنسبه إلى الرابعة لنسبته إليها","topic":"نسب العماني وخبره","topicNo":243,"sp":1,"spl":"العماني والرشيد","tags":["المديح","اللهو والمزاح"],"loc":3259,"partial":1},
{"id":"b243-3","bab":"الجزء 18","sec":"العماني والرشيد","page":"ج18 ص319","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا علي بن الحسن الشيباني وأخبرني به محمد بن جعفر عن محمد بن موسى عن حماد عن أبي محمد المطبخي عن علي بن الحسن الشيباني\nقال أخبرني أبو خالد الطائي عن جبير بن ضبينة الطائي قال أخبرني الفضل قال حضرت الرشيد يوما وجلس للشعراء فدخل عليه الفضل بن الربيع وخلفه العماني فأدناه الرشيد واستنشده فأنشده أرجوزة له فيه حتى انتهى إلى هذا الموضع\n(قل للإمام المقتدى بأمه ... ما قاسم دون مدى ابن أمه)\n(وقد رضيناه فقم فسمه ... )\nال فتبسم الرشيد ثم قال ويحك أما رضيت أن أوليه العهد وأنا جالس حتى أقوم على رجلي فقال له العماني ما أردت يا أمير المؤمنين قيامك على رجليك إنما أردت قيام العزم قال فإنا قد وليناه العهد وأمر بالقاسم أن يحضر ومر العماني في أرجوزته يهدر حتى أتى على آخرها\nوأقبل القاسم فأومأ إليه الرشيد فجلس مع أخويه فقال له يا قاسم عليك جائزة هذا الشيخ فقد سألنا أن نوليك العهد وقد فعلنا فقال حكمك يا أمير المؤمنين فقال وما أنا وهذا بل حكمك وأمر له الرشيد بجائزة وأمر له القاسم بجائزة أخرى مفردة أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال دخل محمد بن ذؤيب العماني على أبي الحر التميمي بالبصرة فأطعمه وسقاه وجلله بكساء فقال له\n(إن أبا الحر لعين الحر ... يدفع عنا سبرات القر)\n(باللحم والشحم وخبز البر ... ونطفة مكنونة في الجر)\n(يشربها أشياخنا في السر ... حتى نرى حديثنا كالدر)","topic":"نسب العماني وخبره","topicNo":243,"sp":2,"spl":"العماني والرشيد","tags":["الرواية والكتابة"],"loc":3260,"partial":1},
{"id":"b243-4","bab":"الجزء 18","sec":"العماني يمدح عبد الملك بن صالح","page":"ج18 ص324","text":"أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال قصد العماني عبد الملك بن صالح الهاشمي متوسلا به إلى الرشيد في الوصول إليه مع الشعراء ومدح عبد الملك بقصيدته التي يقول فيها\n(نمته العرانين من هاشم ... الى النسب الأوضح الأصرح)\n(إلى نبعة فرعها في السماء ... ومغرسها سرة الأبطح)\nأدخله عبد الملك إلى الرشيد بالرقة فأنشده\n(هارون يابن الأكرمين حسبا ... لما ترحلت فكنت كثبا)\n(من أرض بغداد تؤم المغربا ... طابت لنا ريح الجنوب والصبا)\n(ونزل الغيث لنا حتى ربا ... ما كان من نشز وما تصوبا)\n(فمرحبا ومرحبا ومرحبا ... )\nأعطاه خمسة آلاف دينار وخمسين ثوبا أخبرني عمي والحسين بن القاسم الكوكبي قالا حدثنا عبد الله بن أبي سعد قال حدثنا إسحاق بن عبد الله الأزدي عن محمد بن عبد الله العامري القرشي عن العماني الشاعر أنه تغدى مع محمد بن سليمان بن علي فكان أول ما قدم إليهم فرنية في لبن عليها سكر ثم تتابع الطعام فقال له قل فيما أكلت شعرا تصفه فقال\n(جاؤوا بفرني لهم ملبون ... بات يسقى خالص السمون)\n(مصومع أكوم ذي غصون ... قد حشيت بالسكر المطحون)\n(ولونوا ما شئت من تلوين ... من بارد الطعام والسخين)\n(ومن شراسيف ومن طردين ... ومن هلام ومصوص جون)\n(ومن إوز فائق سمين ... ومن دجاج قيت بالعجين)\n(فالشحم في الظهور والبطون ... وأتبعوا ذلك بالجوزين)\n(وبالخبيص الرطب واللوزين ... وفكهوا بعنب وتين)\n(والرطب الأزاذ والهيرون ... محمد يا سيد البنين)\n(وبكر بنت المصطفى الأمين ... الصادق المبارك الميمون)\n(وابن ولاة البيت والحجون ... اسمع لنعت غير ذي تفنين)\n(يخرج من فن إلى فنون ... إن الحديث فيك ذو شجون)\nخبرنا الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن أبي كامل قال حدثني أبو هاشم القيني قال كان محمد بن ذؤيب العماني الراجز من أهل البصرة ويكنى أبا عبد الله وإنما\nقيل له العماني لأنه أقبل يوما وقد خرج من علة ووجهه أصفر فقال له بعض أصحابنا يا أبا عبد الله قد خرجت من هذه العلة كأنك جمل عماني قال وكانت جمال عمان تحمل الورس من اليمن إلى عمان فتصفر\nقال وهو من بني تميم ثم من بني فقيم قال فقدم على عيسى بن موسى فلما وصل إليه أنشده مديحا له وفد إليه به فاستحسنه ووصله واقتطعه إليه وخصه وجعله في جلسائه فقال العماني فيه\n(ما كنت أدري ما رخاء العيش ... ولا لبست الوشي بعد الخيش)\n(حتى تمدحت فتى قريش ... عيسى وعيسى عند وقت الهيش)\n(حين يخف غيره للطيش ... زين المقيمين وعز الجيش)\n(راش جناحي وفوق الريش ... )\nأخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن علي بن أبي نعيم قال حدثنا موسى بن صبيح المروزي قال خرج الرشيد غازيا بلاد الروم فنزل بهرقلة ونصب الحرب عليها فدخل عليه العماني وهو يذكر بغداد وطيبها وما فيه أهلها من النعمة فأنشده العماني قصيدة له في هذا المعنى يذكر فيها طيب العيش ببغداد وسعة النعم وكثرة اللذات يقول فيها\n(ثم أتوهم بالدجاج الدجج ... بين قديد وشواء منضج)\n(وبعبيط ليس بالملهوج ... فدق دق الكودني الديرج)\n(حتى ملا أعفاج بطن نفج ... وقال للقينة صبي وامزجي)\nال فوهب له على القصيدة ثلاثين ألف درهم ثم دخل إليه ابن جامع وقد أمر الرشيد أن يوضع الكبريت والنفط الأبيض على الحجارة وتلف بالمشاقة وتوقد فيها النار ثم توضع في كفة المنجنيق ويرمى بها السور ففعلوا ذلك وكانت النار تثبت في السور وتصدعه حتى طلبوا الأمان حينئذ فغناه ابن جامع وقال\n(هوت هرقلة لما أن رأت عجبا ... حوائما ترتمي بالنفط والنار)\n(كأن نيراننا في جنب قلعتهم ... مصبغات على أرسان قصار)\nأمر له بثلاثين ألف درهم أخرى أخبرني جعفر بن قدامة قال حدثني أبو هفان قال حدثني أحمد بن سليمان قال قال يزيد بن عقال كنا وقوفا والمهدي قد أجرى الخيل فسبقها فرس له يقال له الغضبان فطلب الشعراء فلم يحضر أحد منهم إلا أبو دلامة فقال له قلده يا زند فلم يفهم ما أراد فقلده عمامته فقال له المهدي يابن اللخناء أنا أكثر عمائم منك إنما أردت أن تقلده شعرا ثم\nقال يا لهفي على العماني فلم يتكلم بها حتى أقبل العماني فقيل له ها هوذا قد أقبل الساعة يا أمير المؤمنين فقال قدموه فقدموه فقال قلد فرسي هذا فقال غير متوقف","topic":"نسب العماني وخبره","topicNo":243,"sp":3,"spl":"العماني يمدح عبد الملك بن صالح","tags":["الحب والغزل"],"loc":3261,"partialRef":{"sid":"b243-2","gi":1,"vi":3,"side":0},"partial":1},
{"id":"b243-5","bab":"الجزء 18","sec":"العماني يمدح عبد الملك بن صالح","page":"ج18 ص324","text":"(قد غضب الغضبان إذ جد الغضب ... وجاء يحمي حسبا فوق الحسب)\n(من إرث عباس بن عبد المطلب ... وجاءت الخيل به تشكو التعب)\n(له عليها ما لكم على العرب ... )\nقال له المهدي أحسنت والله وأمر له بعشر آلاف درهم\n\n(لقد علمت وما الإسراف من خلقي ... أن الذي هو رزقي سوف يأتيني)\n(أسعى له فيعنيني تطلبه ... ولو قعدت أتاني لا يعنيني)\nالشعر لعروة بن أذينة والغناء لمخارق ثقيل أول بالبنصر عن عمرو","topic":"نسب العماني وخبره","topicNo":243,"sp":4,"spl":"العماني يمدح عبد الملك بن صالح","tags":[],"song":1,"loc":3262,"partial":1},
{"id":"b244-1","bab":"الجزء 18","sec":"أخبار عروة بن أذينة ونسبه","page":"ج18 ص330","text":"هو عروة بن أذينة وأذينة لقبه واسمه يحيى بن مالك بن الحارث بن عمرو بن عبد الله بن زحل بن يعمر وهو الشداخ بن عوف بن كعب بن عامر بن ليث بن بكر بن عبد مناة بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وسمي يعمر بالشداخ لأنه تحمل ديات قتلى كانت بين قريش وخزاعة\nوقال قد شدخت هذه الدماء تحت قدمي فسمي الشداخ قال ابن الكلبي الشداخ بضم الشين ويكنى عروة بن أذينة أبا عامر وهو شاعر غزل مقدم من شعراء أهل المدينة وهو معدود في الفقهاء والمحدثين\nروى عنه مالك بن أنس وعبيد الله بن عمر العدوي أخبرني بذلك أحمد بن عبد العزيز الجوهري عن عمر بن شبة وروى جده مالك بن الحارث عن علي بن أبي طالب عليه السلام\nأخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثنا أحمد بن الحارث عن المدائني عن ابن دأب عن عروة بن أذينة عن أبيه قال حدثني أبي مالك بن الحارث\nقال خرج مع علي بن أبي طالب عليه السلام رجل من قومي كان مصطلما فخرجت في أثره وخشيت انقراض أهل بيته فأردت أن استأذن له من علي فأدركت عليا عليه السلام بالبصرة وقد هزم الناس ودخل البصرة فجئته فقال مرحبا بك يابن الفقيمة أبدا لك فينا بداء\nقلت والله إن نصرتك لحق وإني لعلى ما عهدت أحب العزلة ثم ذاكرته أمر ابن عمي ذلك فلم يبعد عنه فكنت آتية أتحدث إليه فركب يوما يطوف وركبت معه فإني لأسير إلى جانيه إذ مررنا بقبر طلحة فنظر إليه نظرا شديدا ثم أقبل علي فقال أمسى والله أبو محمد بهذا المكان غريبا ثم تمثل\n(وما تدري وإن أزمعت أمرا ... بأي الأرض يدركك المقيل)\nالله إني لأكره أن تكون قريش قتلى تحت بطون الكواكب قال فوقع العراقيون يشتمون طلحة وسكت علي وسكت حتى إذا فرغوا أقبل علي عليه السلام علي فقال إيه يا بن الفقيمة والله إنه وإن قالوا ما سمعت لكما قال أخو جعفي\n(فتى كان يدنيه الغنى من صديقه ... إذا ما هو استغنى ويبعده الفقر)\nم أردت أن أكلمه بشيء فقلت يا أمير المؤمنين فقال وما منعك أن\nتقول يا أبا الحسن فقلت آبيت فقال والله إنها لأحبهما إلي لولا الحمقى ولوددت أني خنقت بحبل حتى أموت قبل أن يفعل عثمان ما فعل وما أعتذر من قيام بحق ولكن العافية مما ترى كانت خيرا","topic":"أخبار عروة بن أذينة ونسبه","topicNo":244,"sp":0,"spl":"أخبار عروة بن أذينة ونسبه","tags":[],"loc":3263},
{"id":"b244-3","bab":"الجزء 18","sec":"عروة بن أذينة يرى حريق الكعبة — وفود على هشام بن عبد الملك","page":"ج18 ص331 – ج18 ص332","text":"حدثنا محمد بن خلف وكيع والحسن بن علي الخفاف قالا حدثنا الحارث بن أبي أسامة قال حدثنا محمد بن سعد عن الواقدي عن عبيد الله بن يزيد عن عروة بن أذينة\nقال قدمت مع أبي مكة يوم احترقت الكعبة فرأيت الخشب وقد خلصت إليه النار ورأيت الكعبة متجردة من الحريق ورأيت الركن قد اسود وتصدع من ثلاثة أمكنة فقلت ما أصاب الكعبة فأشاروا إلى رجل من أصحاب ابن الزبير فقالوا هذا احترقت بسببه أخذ قبسا في رأس رمح فطيرت الريح منه شيئا فضربت أستار الكعبة فيما بين اليماني إلى الأسود\nحدثني محمد بن جرير الطبري وحفظته وأخبرنا به أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة قال حدثني عمر بن مخروس الوراق بن أقيصر السلمي قال حدثنا يحيى بن عروة بن أذينة قال أتى أبي وجماعة من الشعراء هشام بن عبد الملك فنسبهم فلما عرف أبي قال له أنت القائل\n(لقد علمت وما الإسراف من خلقي ... أن الذي هو رزقي سوف يأتيني)\n(أسعى له فيعنيني تطلبه ... ولو جلست أتاني لا يعنيني)\nهذان البيتان فقط ذركهما المهلبي والجوهري وذكر محمد بن جرر في خبره الأبيات كلها\n(وأن حظ امرىء غيري سيبلغه ... لا بد لا بد أن يحتازه دوني)\n(لا خير في طمع يدني لمنقصة ... وغفة من قوام العيش تكفيني)\n(لا أركب الأمر تزري بي عواقبه ... ولا يعاب به عرضي ولا ديني)\n(كم من فقير غني النفس تعرفه ... ومن غني فقير النفس مسكين)\n(ومن عدو رماني لو قصدت له ... لم يأخذ النصف مني حين يرميني)\n(ومن أخ لي طوى كشحا فقلت له ... إن انطواءك عني سوف يطويني)\n(إني لأنطق فيما كان من أربي ... وأكثر الصمت فيما ليس يعنيني)\n(لا أبتغي وصل من يبغي مفارقتي ... ولا ألين لمن لا يشتهي ليني)\nقال له ابن أذينة نعم أنا قائلها قال أفلا قعدت في بيتك حتى يأتيك رزقك وغفل عنه هشام فخرج من وقته وركب راحلته ومضى منصرفا ثم افتقده هشام فعرف خبره فأتبعه بجائزة\nوقال للرسول قل له أردت أن تكذبنا وتصدق نفسك فمضى الرسول فلحقه وقد نزل على ماء يتغذى عليه فأبلغه رسالته ودفع الجائزة فقال قل له صدقني ربي وكذبك\nقال يحيى بن عروة وفرض له فريضتين فكنت أنا في إحداهما أخبرنا وكيع قال حدثنا هارون بن محمد بن عبد الملك قال حدثني الزبير بن بكار قال حدثني أبو غزية قال حدثني أنس بن حبيب قال\nخرج ابن أذينة إلى هشام بن عبد الملك في قوم من أهل المدينة وفدوا عليه وكان ابنه مسلمة بن هشام سنة حج أذن لهم في الوفود عليه فلما دخلوا على هشام انتسبوا له وسلموا عليه فقال ما جاء بك يا ابن أذينة فقال\n(أتينا نمت بأرحامنا ... وجئنا بإذن أبي شاكر)\n(فإن الذي سار معروفه ... بنجد وغار مع الغائر)\n(إلى خير خندف في ملكها ... لباد من الناس أو حاضر)\nقال له هشام ما اراك إلا قد أكذبت نفسك حيث تقول\n(لقد علمت وما الإسراف من خلقي ... أن الذي هو رزقي سوف يأتيني)\n(أسعى له فيعنيني تطلبه ... ولو جلست أتاني لا يعنيني)\nفقال له ابن أذينة ما أكذبت نفسي يا أمير المؤمنين ولكني صدقتها وهذا من ذاك ثم خرج من عنده فركب راحلته إلى المدينة فلما أمر لهم هشام بجوائزهم فقده فقال أين ابن أذينة فقالوا غضب من تقريعك له يا أمير المؤمنين فانصرف راجعا إلى المدينة فبعث إليه هشام بجائزته أخبرنا وكيع\nقال حدثنا هارون بن محمد قال حدثنا الزبير بن بكار قال حدثني عمي عن عروة بن عبيد الله قال كان عروة بن أذينة نازلا مع أبي في قصر عروة بالعقيق وخرج أبي يوما يمشي وأنا معه وابن أذينة ونظر إلى غنم كانت له في يدي راع يقال له\nكعب وهي مهملة وكعب نائم حجرة فجعل ابن أذينة ينزو حوله وهو يضربه ويقول\n(لو يعلم الذئب بنوم كعب ... إذا لأمسى عندنا ذا ذنب)\n(أضربه ولا يقول حسبي ... لا بد عند ضيعة من ضرب)","topic":"أخبار عروة بن أذينة ونسبه","topicNo":244,"sp":1,"spl":"عروة بن أذينة يرى حريق الكعبة — وفود على هشام بن عبد الملك","tags":["السفر والحج"],"loc":3264},
{"id":"b244-4","bab":"الجزء 18","sec":"ابن عائشة يغني بشعره","page":"ج18 ص335","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي وإسماعيل بن يونس الشيعي قالوا حدثنا عمر بن شبة قال حدثني أبو غسان محمد بن يحيى عن بعض أصحابه قال مر ابن عائشة المغني بعروة بن أذينة فقال له قل لي أبياتا هزجا أغني فيها فقال له اجلس فجلس فقال\n(سليمى أجمعت بيننا ... فأين تقولها أينا)\n(وقد قالت لأتراب ... لها زهر تلاقينا)\n(تعالين فقد طاب ... لنا العيش تعالينا)\n(وغاب البرم الليلة ... والعين فلا عينا)\n(فأقبلن إليها مسر ... عات يتهادينا)\n(إلى مثل مهاة الرم ... تكسو المجلس الزينا)\n(تمنين مناهن ... فكنا ما تمنينا)\nال أبو غسان فحدثت أن ابن عائشة رواها ثم ضحك لما سمع قوله\n(تمنين مناهن ... فكنا ما تمنينا)\nم قال يا ابا عامر تمنيتك لم اأقبل بخرك وأدبر ذكرك قال عمر بن شبة قال قال أبو غسان فحدثني حماد الحسيني قال ذكر ابن أذينة عند عمر بن عبد العزيز فقال نعم الرجل أبو عامر على أنه الذي يقول\n(وقد قالت لأتراب ... لها زهر تلاقينا)\nأخبرني بهذا الخبر وكيع قال حدثني هارون بن محمد بن عبد الملك الزيات عن الزبير عن محمد بن يحيى عن إسحاق بن إبراهيم عن قسطاس قال مر ابن عائشة بابن أذينة ثم\nذكر الخبر مثل الذي قبله أخبرني حبيب بن نصر المهلبي والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال حدثني أبو معاوية عبد الجبار بن سعيد المساحقي وأخبرنا به وكيع قال حدثنا أبو أيوب المدائني عن الحارث بن محمد العوفي قال وقفت سكينة بنت الحسين بن علي عليهما السلام على عروة بن\nأذينة في موكبها ومعها جواريها فقالت يا أبا عامر أنت الذي تزعم أن لك مروءة وأن غزلك من وراء عفة وأنك تقي قال نعم قالت أفأنت الذي تقول\n(قالت وأبثثتها وجدي فبحت به ... قد كنت عندي تحب الستر فاستتر)\n(ألست تبصر من حولي فقلت لها ... غطى هواك وما ألقى على بصري)\nال لها بلى قالت هن حرائر إن كان هذا خرج من قلب سليم أو قالت من قلب صحيح في هذين البيتين لعلويه رمل بالبنصر وفيهما لأسحاق هزج بالوسطى وفيهما لمخارق ثقيل أول بالبنصر عن الهشامي وعمر بن بانة وذكر حبش أن الثقيل الأول لمعبد اليقطيني وذكر علي بن محمد بن نصر البسامي أن خاله أبا عبد الله بن حمدون بن إسماعيل قال كنت جالسا بين يدي المتوكل وبين يديه المنتصر فأحضر\nالمعتز وهو صبي صغير فلعب فأفرط في اللعب والمنتصر يرمقه كالمنكر لفعله فنظر إليه المتوكل عدة دفعات ثم التفت إلى المنتصر فقال يا محمد\n(قالت وأبثثتها وجدي فبحت به ... قد كنت عندي تحب الستر فاستتر)\nال فاعتذر إليه المنتصر عذرا قبله وهو مقطب معرض قال وكان المنتصر أشد خلق الله بغضا للمعتز وطعنا عليه ولقد دخلت إليه يوما ودخل إليه أبو خالد المهلبي بعد قتل المتوكل وإفضاء الخلافة إليه ومع المهلبي درع كأنها فضة فقال يا أمير المؤمنين هذه درع المهلب فأخذها وقام فلبسها ورأى المعتز وعليه وشي مثقل وما أشبه ذلك فتمثل ببيت جرير\n(لبست سلاحي والفرزدق لعبة ... عليه وشاحا كرج وجلاجله)\nخبرني وكيع قال حدثني هارون بن محمد قال حدثني عبد الله بن شعيب الزبيري قال حدثني عبد العزيز بن أبي سلمة قال مرت امرأة بابن أذينة وهو بفناء داره فقالت له أأنت ابن أذينة قال نعم قالت أأنت الذي يقول الناس إنك امرؤ صالح وأنت الذي تقول\n(إذا وجدت أوار الحب في كبدي ... عمدت نحو سقاء القوم أبترد)\n(هبني بردت ببرد الماء ظاهره ... فمن لحر على الأحشاء يتقد)","topic":"أخبار عروة بن أذينة ونسبه","topicNo":244,"sp":2,"spl":"ابن عائشة يغني بشعره","tags":["الحب والغزل"],"song":2,"loc":3265},
{"id":"b244-5","bab":"الجزء 18","sec":"أبو السائب المخزومي يطلب سماع شعر عروة","page":"ج18 ص339","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي عن عروة بن عبد الله وأخبرنا به وكيع عن هارون بن الزيات عن الزبيري عن عمه عن عروة بن عبد الله وذكره حماد عن أبيه عن الزبيري عن عروة هذا قال كان عروة في أذينة نازلا في دار أبي بالعقيق فسمعه ينشد\n(إن التي زعمت فؤادك ملها ... جعلت هواك كما جعلت هوى لها)\n(فبك الذي زعمت بها وكلاكما ... يبدي لصاحبه الصبابة كلها)\n(ويبيت بين جوانحي حب لها ... لو كان تحت فراشها لأقلها)\n(ولعمرها لو كان حبك فوقها ... يوما وقد ضحيت إذا لأظلها)\n(وإذا وجدت لها وساوس سلوة ... شفع الفؤاد إلى الضمير فسلها)\n(بيضاء باكرها النعيم فصاغها ... بلباقة فأدقها وأجلها)\n(لما عرضت مسلما لي حاجة ... أرجو معونتها وأخشى دلها)\n(منعت تحيتها فقلت لصاحبي ... ما كان أكثرها لنا وأقلها)\n(فدنا فقال لعلها معذورة ... من أجل رقبتها فقلت لعلها)\nال فأتاني أبو السائب المخزومي وأنا في دار بالعقيق فقلت له بعد الترحيب هل بدت لك حاجة فقال نعم أبيات لعروة بن أذينة بلغني\nأنك سمعتها منه فقلت له وأية أبيات فقال وهل يخفى القمر قوله\n(إن التي زعمت فؤادك ملها ... )\nأنشدته إياها فلما بلغت إلى قوله فقلت لعلها قال أحسن والله هذا والله الدائم العهد الصادق الصبابة لا الذي يقول\n(إن كان أهلك يمنعونك رغبة ... عني فأهلي بي أضن وأرغب)\nذهب لاصحبك والله ولا وسع عليك يعني قائل هذا البيت لقد عدا الأعرابي طوره وإني لأرجو أن يغفر الله لصاحبك يعني عروة لحسن ظنه بها وطلبه العذر لها قال فعرضت عليه الطعام فقال لا والله ما كنت لآكل بهذه الأبيات طعاما إلى الليل وانصرف","topic":"أخبار عروة بن أذينة ونسبه","topicNo":244,"sp":3,"spl":"أبو السائب المخزومي يطلب سماع شعر عروة","tags":["الحب والغزل","الوصف والطبيعة"],"song":1,"loc":3266,"partial":1},
{"id":"b244-6","bab":"الجزء 18","sec":"ذكر ما في هذا الخبر من الغناء","page":"ج18 ص340","text":"في الشعر المذكور فيه لعروة في البيت الأول والرابع من الأبيات خفيف رمل بالوسطى نسبه ابن المكي إلى ابن مسجح وقيل إنه من منحوله إليه وفيهما وفي البيت الثالث من شعر ابن أذينة خفيف ثقيل لابن الهربذ والبيت\n(ويبيت بين جوانحي حب لها ... لو كان تحت فراشها لأقلها)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عمر بن أبي بكر المؤملي قال أخبرنا عبد الله بن أبي عبيدة قال قلت لأبي السائب المخزومي ما أحسن عروة بن أذينة حيث يقول\n(لبثوا ثلاث منى بمنزل غبطة ... وهم على غرض لعمرك ما هم)\n(متجاورين بغير دار إقامة ... لو قد أجد رحيلهم لم يندموا)\n(ولهن بالبيت العتيق لبانة ... والبيت يعرفهن لو يتكلم)\n(لو كان حيا قبلهن ظعائنا ... حيا الحطيم وجوههن وزمزم)\n(وكأنهن وقد حسرن لواغبا ... بيض بأكناف الحطيم مركم)\nفي هذه الأبيات الثلاثة لابن سريج ثاني ثقيل بالبنصر عن عمرو قال فقال لا والله ما أحسن ولا أجمل ولكنه أهجر وأخطل في صفتهن بهذه الصفة ثم لا يندم على رحيلهن أهكذا قال كثير حيث يقول\n(تفرق أهواء الحجيج على منى ... وصدعهم شعب النوى صبح أربع)\n(فريقان منهم سالك بطن نخلة ... وآخر منهم سالك بطن تضرع)\nي هذين البيتين للدلال ثاني ثقيل بالوسطى عن الهشامي وحبش\n(فلم أر دارا مثلها دار غبطة ... وملقى إذا التف الحجيج بمجمع)\n(أقل مقيما راضيا بمكانه ... وأكثر جارا ظاعنا لم يودع)\nنظر إليه كيف تقدمت شهادته علمه وكبا لسانه ببيانه هل يغتبط عاقل بمقام لا يرضى به ولكن مكره أخوك لا بطل والعرجي كان أوفى بالعهد\nمنهما وأولى بالصواب حين تعرض لها نافرة من منى فقال لها عاتبا مستكينا\n(عوجي علي فسلمي جبر ... فيم الصدود وأنتم سفر)\n(ما نلتقي إلا ثلاث منى ... حتى يفرق بيننا النفر)\nي هذين البيتين غناء قد تقدمت نسبته في أخبار ابن جامع في أول الكتاب أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني جعفر بن موسى اللهبي قال كان عبد الملك بن مروان إذا قدم مكة أذن للقرشيين في السلام عليه فإذا أراد الخروج لم يأذن لأحد منهم وقال أكذبنا إذا قول الملحي يعني كثيرا حيث يقول\n(تفرق أهواء الحجيج على منى ... وصدعهم شعب النوى صبح أربع)\nوذكر الأبيات الأربعة أخبرنا علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال حدث الزبيري عن خالد صامة وكان أحد المغنين قال\nقدمت على الوليد بن يزيد فدخلت إليه وهو في مجلس ناهيك به وهو على سرير وبين يديه معبد ومالك وابن عائشة وأبو كامل فجعلوا يغنون حتى بلغت النوبة إلي فغنيته\n(سرى همي وهم المرء يسري ... وغار النجم إلا قيس فتر)\n(أراقب في المجرة كل نجم ... تعرض للمجرة كيف يجري)\n(لهم ما أزال له مديما ... كأن القلب أضرم حر جمر)\n(على بكر أخي ولى حميدا ... وأي العيش يصفو بعد بكر)\nقال لي الوليد أعد يا صام ففعلت فقال لي من يقول هذا الشعر قلت عروة بن أذينة يرثي أخاه بكرا فقال لي وأي العيش لا يصفو بعده هذا العيش والله الذي نحن فيه على رغم أنفه والله لقد تحجر واسعا لابن سريج في هذه الأبيات ثاني ثقيل بالوسطى عن عمرو وابن المكي وغيرهما وفيها رمل ينسب إلى ابن عباد الكاتب وإلى حاجب الحزور وإلى مسكين بن صدقة\nحدثنا الأخفش عن محمد بن يزيد قال قال الزبيري حدثت أن سكينة بنت الحسين عليه السلام أنشدت هذا الشعر فقالت من بكر هذا أليس هو الأسود الدحداح الذي كان يمر بنا قالوا نعم فقالت لقد طاب كل شيء بعده حتى الخبز والزيت\nوأخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال حدثني عمي قال لقي ابن أبي عتيق عروة بن أذينة فأنشده قوله\n(لا بكر لي إذ دعوت بكرا ... ودون بكر ثرى وطين)\nتى فرغ منها ثم أنشده\n(سرى همي وهم المرء يسري ... )\nحتى بلغ إلى قوله\n(وأي العيش يصفو بعد بكر ... )\nقال له ابن أبي عتيق كل العيش والله يصلح بعده حتى الخبز والزيت فغضب عروة من قوله وقام عن مجلسه وحلف ألا يكلمه أبدا فماتا متهاجرين","topic":"أخبار عروة بن أذينة ونسبه","topicNo":244,"sp":4,"spl":"ذكر ما في هذا الخبر من الغناء","tags":[],"song":3,"loc":3267,"partialRef":{"sid":"b3-46","gi":0,"vi":3,"side":1},"partial":1},
{"id":"b245-1","bab":"الجزء 18","sec":"ذكر مخارق وأخباره","page":"ج18 ص345","text":"هو مخارق بن يحيى بن ناووس الجزار مولى الرشيد وقيل بل ناووس لقب أبيه يحيى ويكنى أبا المهنأ كناه الرشيد بذلك وكان قبله لعاتكة بنت شهدة وهي من المغنيات المحسنات المتقدمات في الضرب\nذكر ذلك مخارق واعترف به ونشأ بالمدينة وقيل بل كان منشؤه بالكوفة وكان أبوه جزارا مملوكا وكان مخارق وهو صبي ينادي على ما يبيعه أبوه من اللحم فلما بان طيب صوته علمته مولاته طرفا من الغناء ثم أرادت بيعه فاشتراه إبراهيم الموصلي منها وأهداه للفضل بن يحيى فأخذه الرشيد منه ثم أعتقه\nأخبرني الحسين بن يحيى قال قال حماد حدثني زكريا مولاهم وأخبرني محمد بن يحيى الصولي قال حدثني عبيد الله بن محمد بن عبد الملك قال حدثنا حماد بن إسحاق عن زكريا مولاهم قال","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":0,"spl":"ذكر مخارق وأخباره","tags":["الجواري والنساء"],"loc":3268},
{"id":"b245-2","bab":"الجزء 18","sec":"مخارق يصير إلى الرشيد","page":"ج18 ص346","text":"قدمت مولاة مخارق به من الكوفة فنزلت المخرم وصار إبراهيم\nإلى جدي الأصبع بن سنان المقين وسيرين بن طرخان النخاس فقالا له إن ها هنا امرأة من اهل الكوفة قد قدمت ومعها غلام يتغنى فأحب أن تنفعها فيه\nقال فوجهني مع مولاته لأحمله فوجدته متمرغا في رمل الجزيرة التي بإزاء المخرم وهو يلعب فحملته خلفي وأتيت به إبراهيم فتغنى بين يديه فقال لها من أملك فيه قالت عشرة آلاف درهم\nقال قد أخذته بها وهو خير منها فقالت أقلني قال قد فعلت فكم أملك فيه قالت عشرون ألفا قال قد أخذته بها وهو خير منها فقالت والله ما تطيب نفسي أن أمتنع من عشرين ألف درهم بكبد رطبة فهل لك في خصلة تعطيني به ثلاثين ألف درهم ولا أستقيلك بعدها فقال قد فعلت وهو خير منها فصفقت على يده وبايعته وأمر بالمال فأحضر وأمر بثلاثة آلاف درهم فزيدت عليه\nوقال تكون هذه لهدية تهدينها أو كسوة تكتسينها ولا تثلمين المال وراح إلى الفضل بن يحيى فقال له ما خبر غلام بلغني أنك اشتريته قال هو ما بلغك\nقال فأرنيه فأحضره فلما تغنى بين يدي الفضل قال له ما أرى فيه الذي رأيت قال أنت تريد أن يكون في الغناء مثلي في ساعة واحدة ولم يكن مثله في الدنيا ولا يكون أبدا فقال بكم تبيعه فقال اشتريته بثلاثة وثلاثين ألف درهم وهو حر لوجه الله تعالى إن بعته إلا بثلاثة وثلاثين ألف دينار فغضب الفضل وقال إنما أردت أن تمنعنيه أو تجعله سببا لأن تأخذ مني ثلاثة وثلاثين ألف دينار فقال له أصنع بك خصلة أبيعك نصفه بنصف هذا المال وأكون شريكك في نصفه وأعلمه\nفإن أعجبك إذا علمته أتممت لي باقي المال وإلا بعته بعد ذلك وكان الربح بيني وبينك فقال له الفضل إنما أردت أن تأخذ مني المال الذي قدمت ذكره فلما لم تقدر على ذلك أردت أن تأخذ نصفه وغضب فقال له إبراهيم فأنا أهبه لك على أنه يساوي ثلاثة وثلاثين ألف دينار\nقال قد قبلته قال قد وهبته لك وغدا إبراهيم على الرشيد فقال له يا إبراهيم ما غلام بلغني أنك وهبته للفضل قال فقلت غلام يا أمير المؤمنين لم تملك العرب ولا العجم مثله ولا يكون مثله أبدا\nقال فوجه إلى الفضل فأمره بإحضاره فوجه به إليه فتغنى بين يديه فقال لي كم يساوي قال قلت يساوي خراج مصر وضياعها فقال لي ويلك أتدري ما تقول مبلغ هذا المال كذا وكذا فقلت وما مقدار هذا المال في شيء لم يملك أحد مثله قط\nقال فالتفت إلى مسرور الكبير وقال قد عرفت يميني ألا أسأل أحدا من البرامكة شيئا بعد فنفنة فقال مسرور فأنا أمضي إلى الفضل فأستوهبه منه فإذا وهبه لي وكان عبدي فهو عبدك فقال له شأنك فمضى مسرور إلى الفضل فقال له قد عرفتم ما وقعتم فيه من أمر فنفنة وإن منعتموه هذا الغلام قامت القيامة واستوهبه منه فوهبه له فبلغ ما رأيت فكان علويه إذا غضب على مخارق يقول له حيث يقول أنا مولى أمير المؤمنين متى كنت كذلك إنما أنت عبد الفضل بن يحيى أو مولى مسرور أخبرني ابن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال كان مخارق بن ناووس الجزار وإنما لقب بناووس لأنه بايع رجلا أنه\nيمضي إلى ناووس الكوفة فيطبخ فيه قدرا بالليل حتى تنضج فطرح رهنه بذلك فدس الرجل الذي راهنه رجلا فألقى نفسه في الناووس بين الموتى فلما فرغ من الطبيخ مد الرجل يده من بين الموتى\nوقال له أطعمني فعرف ملء المغرفة من المرقة فصبها في يد الرجل فأحرقها وضربها بالمغرفة وقال له اصبر حتى نطعم الأحياء أولا ثم نتفرغ للموتى فلقب بناووس لذلك فنشأ ابنه مخارق وكان ينادي عليه إذا باع الجزور فخرج له صوت عجيب فاشتراه أبي وأهداه للرشيد فأمره بتعليمه فعلمه حتى بلغ المبلغ الذي بلغه","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":1,"spl":"مخارق يصير إلى الرشيد","tags":["الجواري والنساء"],"loc":3269},
{"id":"b245-3","bab":"الجزء 18","sec":"مخارق يغني للرشيد","page":"ج18 ص349","text":"وكان يقف بين يدي الرشيد مع الغلمان لا يجلس ويغني وهو واقف فغني ابن جامع ذات يوم بين يدي الرشيد\n(كأن نيراننا في جنب قلعتهم ... مصبغات على أرسان قصار)\n(هوت هرقلة لما أن رأت عجبا ... حوائما ترتمي بالنفط والنار)\nطرب الرشيد واستعاده عدة مرات وهو شعر مدح به الرشيد في فتح هرقلة وأقبل يومئذ على ابن جامع دون غيره فغمز مخارق إبراهيم بعينه وتقدمه إلى الخلاء فلما جاءه\nقال له مالي أراك منكسرا قال أما ترى إقبال أمير المؤمنين على ابن جامع بسبب هذا الصوت فقال قد والله أخذته فقال له ويحك إنه الرشيد وابن جامع من تعلم ولا يمكن معارضته إلا بما يزيد على غنائه وإلا فهو الموت\nقال دعني وخلاك ذم وعرفه أني أغني به فإن أحسنت فإليك ينسب وإن أسأت فإلي يعود فقال للرشيد يا أمير المؤمنين أراك متعجبا من هذا الصوت بغير ما يستحقه وأكثر مما يستوجبه\nفقال لقد أحسن ابن جامع ما شاء قال أو لابن جامع هو قال نعم كذا ذكر قال له فإن عبدك مخارقا يغنيه فنظر إلى مخارق فقال نعم يا أمير المؤمنين فقال هاته فغناه وتحفظ فيه فأتى بالعجائب فطرب الرشيد حتى كاد يطير فرحا وشرب ثم أقبل على ابن جامع فقال له ويلك ما هذا فابتدأ يحلف له بالطلاق وكل محرجة أنه لم يسمع ذلك الصوت قط إلا منه ولا صنعه غيره وأنها حيلة جرت عليه فأقبل على إبراهيم\nوقال اصدقني بحياتي فصدقه عن قصة مخارق فقال له أكذلك هو يا مخارق قال نعم يا مولاي فقال اجلس إذن مع أصحابك فقد تجاوزت مرتبة من يقوم وأعتقه ووصله بثلاثة آلاف دينار وأقطعه ضيعة ومنزلا\nأخبرني محمد بن خلف وكيع وحدثني محمد بن خلف بن المرزبان قال وكيع حدثني هارون بن مخارق وقال ابن المرزبان ذكر هارون ابن مخارق قال كان أبي إذا غنى هذا الصوت\n(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\n(ربع تبدل ممن كان يسكنه ... عفر الظباء وظلمانا به عصبا)\nبكي ويقول أنا مولى هذا الصوت فقلت له وكيف ذاك يا أبت فقال غنيته مولاي الرشيد فبكى وشرب عليه رطلا ثم قال أحسنت يا مخارق فسلني حاجتك فقلت أن تعتقني يا أمير المؤمنين أعتقك الله من النار فقال أنت حر لوجه الله فأعد الصوت فأعدته فبكى وضرب رطلا ثم قال أحسنت يا مخارق فسلني حاجتك فقلت ضيعة تقيمني غلتها قال قد أمرت لك بها أعد الصوت فأعدته فبكى وقال سل حاجتك فقلت يا\nأمير المؤمنين تأمر لي بمنزل وفرش وخادم قال ذلك لك أعد الصوت فأعدته فبكى وقال سل حاجتك فقبلت الأرض بين يديه وقلت حاجتي أن يطيل الله بقاءك ويديم عزك ويجعلني من كل سوء فداءك فأنا مولى هذا الصوت بعد مولاي","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":2,"spl":"مخارق يغني للرشيد","tags":["المديح"],"loc":3270},
{"id":"b245-4","bab":"الجزء 18","sec":"المأمون يسأل عن مخارق","page":"ج18 ص351","text":"وذكر محمد بن الحسن الكاتب أن أبان بن سعيد حدثه أن المأمون سأل إسحاق عن إبراهيم بن المهدي ومخارق فقال يا أمير المؤمنين إذا تغنى إبراهيم بن المهدي بعلمه فضل مخارقا وإذا تغنى مخارق بطبعه وفضل صوته فضل إبراهيم فقال له صدقت\nأخبرني علي بن سليمان الأخفش قال حدثنا المبرد بهذا الخبر فقال حدثني بعض حاشية السلطان أن إبراهيم الموصلي غنى الرشيد يوما هذا الصوت فأعجب به وطرب له واستعاده مرارا فقال له فكيف لو سمعته من عبدك مخارق فإنه أخذه عني وهو يفضل فيه الخلق جميعا ويفضلني فدعا بمخارق فأمره أن يغنيه\nوذكر باقي الخبر مثل الذي تقدم أخبرني الحسن بن علي قال حدثنا ابن أبي الدنيا عن إسحاق بن محمد النخعي عن الحسين بن الضحاك عن مخارق أن الرشيد قال يوما للمغنين وهو مصطبح من منكم يغني\n(يا ربع سلمى لقد هيجت لي طربا ... )\nقمت فقلت أنا أمير المؤمنين فقال هاته فغنيته فطرب وشرب\nثم قال علي بهرثمة بن أعين فقلت في نفسي ما يريد منه فجاؤوا بهرثمة فأدخل إليه وهو يجر سيفه فقال له يا هرثمة مخارق الشاري الذي قتلناه بناحية الموصل ما كانت كنيته فقال أبو المهنأ فقال انصرف فانصرف ثم أقبل علي\nوقال قد كنيتك أبا المهنأ لإحسانك وأمر لي بمائة ألف درهم فانصرفت بها وبالكنية أخبرني جعفر بن قدامة قال حدثني علي بن محمد بن نصر البسامي\nقال حدثني خالي أبو عبد الله بن حمدون قال رحنا إلى الواثق وأمه عليلة فلما صلى المغرب دخل إلى أمه وأمر بألا نبح وكان في الصحن حصر غير مفروشة فقال لي مخارق امض بنا حتى نفرش حصيرا من هذه الحصر فنجلس على بعضه ونتكىء على المدرج منه وكانت ليلة مقمرة فمضينا ففرشنا بعض تلك الحصر واستلقينا وتحدثنا وأبطأ الواثق عند أمه فاندفع مخارق فغنى\n(أيا بيت ليلى إن ليلى غريبة ... براذان لا خال لديها ولا ابن عم)\nاجتمع علينا الغلمان وخرج الواثق فصاح يا غلام فلم يجبه أحد ومشى من المجلس إلى أن توسط الدار فلما رأيته بادرت إليه فقال لي ويلك هل حدث في داري شيء فقلت لا يا سيدي فقال فمالي أصيح فلا أجاب فقلت مخارق يغني والغلمان قد اجتمعوا عليه فليس فيهم فضل لسماع غير ما يسمعونه منه فقال عذر والله لهم يا بن حمدون وأي عذر ثم جلس وجلسنا بين يديه إلى السحر\nوذكر هارون بن محمد بن عبد الملك أن مخارقا كان ينادي على اللحم الذي يبيعه أبوه فيسمع له صوت عجيب فاشترته عاتكة بنت شهدة وعلمته شيئا من الغناء ليس بالكثير ثم باعته من آل الزبير فأخذه منهم الرشيد وسلمه إلى إبراهيم الموصلي فأخذ عنه وكان إبراهيم يقدمه ويؤثره ويخصه بالتعليم لما تبينه منه ومن جودة طبعه","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":3,"spl":"المأمون يسأل عن مخارق","tags":[],"loc":3271,"partialRef":{"sid":"b19-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b245-5","bab":"الجزء 18","sec":"كان مملوكا لعاتكة بنت شهدة","page":"ج18 ص353","text":"أخبرني علي بن عبد العزيز الكاتب قال حدثني ابن خرداذبه قال كان مخارق بن يحيى بن ناووس الجرار وكان عبدا لعاتكة بنت شهدة وكانت عاتكة أحذق الناس بالغناء وكان ابن جامع يلوذ منها بالترجيع\nالكثير فتقول له أين يذهب بك هلم إلى معظم الغناء ودعني من جنونك قال فحدثني من حضرهما أن عاتكة أفرطت يوما في الرد على ابن جامع بحضرة الرشيد فقال لها أي أم العباس أنا يشهد الله أحب أن تحتك شعرتي بشعرتك فقالت له اسكت قطع الله لسانك ولم تعاود بعد ذلك أذيته\nقال وكانت شهدة أم عاتكة نائحة هكذا ذكر ابن خرداذبه وليس الأمر في ذلك كما ذكره حدثني محمد بن يحيى الصولي حدثنا الغلابي قال حدثني علي ابن محمد النوفلي عن عبد الله بن العباس الربيعي أنه كان هو وابن جامع وإبراهيم الموصلي وإسماعيل بن علي عند الرشيد ومعهم محمد بن داود بن علي فغنى المغنون جميعا ثم اندفع محمد بن داود فغناه\n(أم الوليد سلبتني حلمي ... وقتلتني فتحللي إثمي)\n(بالله يا أم الوليد أما ... تخشين في عواقب الظلم)\n(وتركتني أبغي الطبيب وما ... لطبيبنا بالداء من علم)\nال فاستحسنه الرشيد وكل من حضر وطربوا له فسأله الرشيد عمن أخذته فقال أخذته عن شهدة جارية الوليد بن يزيد قال عبد الله بن العباس هي أم عاتكة بنت شهدة الأبيات المذكورة التي فيها الغناء لعبيد الله بن قيس الرقيات\nوتمامها\n(لله درك في ابن عمك قد ... زودته سقما على سقم)\n(في وجهها ماء الشباب ولم ... تقبل بمكروه ولا جهم)\nالغناء فيه لابن محرز لحنان كلاهما له أحدهما ثقيل الأول بالخنصر في مجرى الوسطى عن إسحاق والآخر خفيف ثقيل الأول بالنصر عن عمرو بن بانة وفيه لمالك ثاني ثقيل عن الهشامي وحبش وفيه لسليمان خفيف رمل بالبنصر عنهما وثقيل أول للحسين بن محرز","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":4,"spl":"كان مملوكا لعاتكة بنت شهدة","tags":[],"song":1,"loc":3272},
{"id":"b245-7","bab":"الجزء 18","sec":"مخارق والواثق — مخارق وأبو العتاهية","page":"ج18 ص355 – ج18 ص356","text":"وقال هارون بن محمد بن عبد الملك الزيات قال أبي قال الواثق أمير المؤمنين خطأ مخارق كصواب علويه وخطأ إسحاق كصواب مخارق وما غناني مخارق قط إلا قدرت أنه من قلبي خلق ولا غناني إسحاق إلا ظننت أنه قد زيد في ملكي ملك آخر\nقال وكان يقول أتريدون أن تنظروا فضل مخارق على جميع أصحابه انظروا إلى هؤلاء الغلمان الذين يقفون في السماط فكانوا يتفقدونهم وهم وقوف فكلهم يسمع الغناء من المغنين جميعا وهو واقف مكانه ضابط لنفسه فإذا تغنى مخارق خرجوا عن صورهم فتحركت أرجلهم ومناكبهم وبانت أسباب الطرب فيهم وازدحموا على الحبل الذي يقفون من ورائه قال هارون وحدثت أنه خرج مرة إلى باب الكناسة بمدينة\nالسلام والناس يرتحلون للخروج إلى مكة فنظر إليهم واجتماعهم وازدحامهم فقال لأصحابه الذين خرجوا معه قد جاء في الخبر أن ابن سريج كان يتغنى في أيام الحج والناس بمنى فيستوقفهم بغنائه وسأستوقف لكم هؤلاء الناس وأستلهيهم جميعا لتعلموا أنه لم يكن ليفضلني إلا بصنعته دون صوته ثم اندفع يؤذن فاستوقف أولئك الخلق واستلهاهم حتى جعلت المحامل يغشى بعضها بعضا وهو كالأعمى عنها لما خامر قلبه من الطرب لحسن ما يسمع\nأخبرني أحمد بن جعفر جحظة قال حدثني ابن أخت الحاركي وأبو سعيد الرامهرمزي وأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد الأزدي عن أحمد بن عيسى الجلودي عن محمد بن سعيد الترمذي وكان إسحاق إذا\nذكر محمدا وصفه بحسن الصوت ثم قال قد أفلتنا منه فلو كان يغني لتقدمنا جميعا بصوته قالوا جاء أبو العتاهية إلى باب مخارق فطرقه واستفتح فإذا مخارق قد خرج إليه فقال له أبو العتاهية يا حسان هذا الأقليم يا حكيم أرض بابل أصبب في أذني شيئا يفرح به قلبي وتنعم به نفسي فقال انزلوا فنزلنا فغنانا\nقال محمد بن سعيد فكدت أسعى على وجهي طربا قال وجعل أبو العتاهية يبكي ثم قال له يا دواء المجانين لقد رققت حتى كدت أحسوك فلو كان الغناء طعاما لكان غناؤك أدما ولو كان شرابا لكان ماء الحياة نسخت من كتاب ابن أبي الدنيا حدثني بعض خدم السلطان قال\nقال رجل لأبي العتاهية وقد حضرته الوفاة هل في نفسك شيء تشتهيه قال أن يحضر مخارق الساعة فيغنيني\n(سيعرض عن ذكري وتنسى مودتي ... ويحدث بعدي للخليل خليل)\n(إذا ما انقضت عني من الدهر مدتي ... فإن غناء الباكيات قليل)\nخبرني عمي قال حدثنا محمد بن علي بن حمزة العلوي قال حدثنا علي بن الحسين بن الأعرابي قال لقى مخارق أبا العتاهية فقال له يا أبا إسحاق أأنت القائل\n(اصرف بطرفك حيث شئت ... فلن ترى إلا بخيلا)\nال له نعم قال بخلت الناس جميعا قال فاصرف بطرفك يا أبا المهنأ فانظر فإنك لن ترى إلا بخيلا وإلا فأكذبني بجواد واحد فالتفت مخارق يمينا وشمالا ثم أقبل عليه فقال صدقت يا أبا إسحاق فقال له أبو العتاهية فديتك لو كنت مما يشرب لذررت على الماء وشربت","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":5,"spl":"مخارق والواثق — مخارق وأبو العتاهية — عندما يغني مخارق يترك الناس أعمالهم","tags":["الحب والغزل"],"loc":3273},
{"id":"b245-8","bab":"الجزء 18","sec":"عندما يغني مخارق يترك الناس أعمالهم","page":"ج18 ص357","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني بعض آل نوبخت قال كان أبي وعبد الله بن أبي سهل وجماعة من آل نوبخت وغيرهم وقوفا بكناسة الدواب في الجانب الغربي من بغداد يتحدثون فإنهم لكذلك إذ أقبل مخارق على حمار أسود وعليه قميص رقيق ورداء مسهم قال فيم كنتم فأخبروه فقال دعوني من وسواسكم هذا أي شيء لي عليكم إن رميت بنفسي بين قبرين من هذه القبور وغطيت وجهي وغنيت صوتا فلم يبق\nبهذه الكناسة ولا في الطريق من مشتر ولا بائع ولا صادر ولا وارد إلا ترك عمله وقرب مني واتبع صوتي فقال له عبد الله إني لأحب أن أرى هذا فقل ما شئت فقال فرسك الأشقر الذي طلبته منك فمنعتنيه قال هو لك إن فعلت ما قلت ثم دخلها ورمى بنفسه بين قبرين وتغطى بردائه ثم اندفع يغني فغنى في شعر أبي العتاهية\n(نادت بوشك رحيلك الأيام ... أفلست تسمع أم بك استصمام)\nال فرأيت الناس يتقوضون إلى المقبرة أرسالا من بين راكب وراجل وصاحب شول وصاحب جدي ومار بالطريق حتى لم يبق بالطريق أحد ثم قال لنا من تحت ردائه هل بقي أحد قلنا لا وقد وجب الرهن فقام فركب حماره وعاد الناس إلى صنائعهم فقال لعبد الله أحضر الفرس فقال على أن تقيم اليوم عندي قال نعم فانصرفنا معهما وسلم الفرس إليه وبره وأحسن إليه وأحسن رفده","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":5,"spl":"مخارق والواثق — مخارق وأبو العتاهية — عندما يغني مخارق يترك الناس أعمالهم","tags":["اللهو والمزاح","الرواية والكتابة"],"loc":3274},
{"id":"b245-9","bab":"الجزء 18","sec":"نسبة هذا الصوت","page":"ج18 ص358","text":"\n(نادت بوشك رحيلك الأيام ... أفلست تسمع أم بك استصمام)\n(ومضى أمامك من رأيت وأنت للباقين ... حتى يلحقوك إمام)\n(مالي أراك كأن عينك لا ترى ... عبرا تمر كأنهن سهام)\n(تمضي الخطوب وأنت منتبه لها ... فإذا مضت فكأنها أحلام)\nالشعر لأبي العتاهية والغناء لإبراهيم ثقيل أول بالوسطى وفيه لمخارق هزج بالوسطى كلاهما عن عمرو وفيه رمل يقال إنه لعلويه ويقال إنه لمخارق عن الهشامي أخبرني جحظة قال ذكر ابن المكي المرتجل عن أبيه أن أبا العتاهية دخل يوما إلى صديق له وعنده جارية تغني فقال أبا إسحاق إن هذه الجارية تغني صوتا حسنا في شعر لك أفتنشط إلى سماعه قال هاتيه فغنته لحنا لعمرو بن بانة في قوله\n(نادت بوشك رحيلك الأيام ... )\nعبس وبسر وقال لا جزى الله خيرا من صنع هذه الصنعة في شعري قال فإنها تغني فيه لحنا لمخارق قال فلتغنه فغنته فأعجبه وطرب حتى بكى ثم قال جزى الله هذا عني خيرا وقام فانصرف وقد روى هذا الخبر هارون بن الزيات عن حماد بن إسحاق عن أبيه عن غزوان أنه كان وعبيد الله بن أبي غسان وأبو العتاهية ومحمد بن عمرو الرومي عند ابن أبي مريم ومعهم مغنية يقال لها بنت إبليس فغنى عبيد الله ابن أبي غسان في لحن مخارق\n(نادت بوشك رحيلك الأيام ... )\nلم يستحسنه أبو العتاهية ثم غنى فيه لحنا لإبراهيم بن المهدي فأطربه وقال جزى الله عني هذا خيرا أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال بلغني أن المتوكل دخل إلى جارية من جواريه وهي تغني\n\n(أمن قطر الندى نظمت ... ثغرك أم من البرد)\n(وريقك من سلاف الكرم ... أم من صفوة الشهد)\n(أيا من قد جرى مني ... كمجرى الروح في الجسد)\n(ضميرك شاهدي فيما ... أقاسيه من الكمد)\nالغناء لمخارق رمل فقال لها ويحك لمن هذا الغناء فقالت أخذته من مخارق قال فألقيه على الجواري جميعا ففعلت فلما أخذنه عنها أمر بإخراجهن إليه ودعا بالنبيذ وأمر بألا يغنينه غيره ثلاثة أيام متوالية وكان ذلك بعد وفاة مخارق وأخبرنا إسماعيل بن يونس الشيعي\nقال حدثنا عمر بن شبة قال قال عمر بن نوح بن جرير سألت أبا المضاء الأسدي أن ينشدني فقال أنشدك من شعري شيئا قلته لرجل لقيته على الجسر ببغداد فأعجبه مني ما يرى من دماثتي وأقبلت أحدثه وهو ينصت لي وأنشده وهو يحسن الإصغاء إلى أنشادي ويحدثني فيحسن الحديث حتى بلغنا منزله فأدخلني فغداني ثم لم يرم حتى كساني وسقاني فرواني ثم أسمعني والله شيئا ما طار في مسامعي شيء قط أحسن منه فلما خرجت سألت عنه فقال لي غلمانه هذا أبو المهنأ مخارق فقلت فيه\n(أعاد الله يوم أبي المهنا ... علينا إنه يوم نضير)\n(تغيب نحسه عنا وأرخى ... علينا وابل جود مطير)\nقال يا إسحاق هذا والله صاحب اللواء غدا إن مات أبوك أخبرني الحسن بن علي الخفاف قال حدثني محمد بن القاسم بن مهرويه قال حدثني هارون بن مخارق عن أبيه قال رأيت وأنا حدث كأن شيخا جالسا على سرير في روضة حسنة قد دعاني فقال لي غنني يا مخارق فقلت أصوتا تقترحه أم ما حضر فقال ما حضر فغنيته بصنعتي في\n(دعي القلب لا يزدد خبالا مع الذي ... به منك أو داوي جواه المكتما)\n(وليس بتزويق اللسان وصوغه ... ولكنه قد خالط اللحم والدما)\nلحن مخارق فيه ثقيل أول وفيه لابن سريج رمل قال فقال لي أحسنت يا مخارق ثم أخذ وترا من أوتار العود فلفه على المضراب ودفعه إلي فجعل المضراب يطول ويغلظ والوتر ينتشر ويعرض حتى صار المضراب كالرمح والوتر كالعذبة عليه وصار في يدي علما ثم انتبهت فحدثت برؤياي إبراهيم الموصلي فقال لي الشيخ بلا شك إبليس وقد عقد لك لواء صنعنك فأنت ما حييت رئيس أهلها قال مؤلف هذا الكتاب وأظن أن الشاعر الذي مدح مخارقا إنما عنى هذه الرؤيا بقوله\n(لقد عقد الشيخ الذي غر آدما ... وأخرجه من جنة وحدائق)\n(لواءي فنون للقريض وللغنا ... وأقسم لا يعطيها غير حاذق)\nوذكر محمد بن الحسن الكاتب أن هارون بن مخارق حدثه فقال كان الواثق شديد الشغف بأبي وكان قد اقتطعه عنا وأمر له بحجرة في قصره وجعل له يوما في الأسبوع لنوبته في منزله وكان جواريه يختلفن لذلك اليوم","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":6,"spl":"نسبة هذا الصوت","tags":["المديح"],"song":3,"loc":3275,"partialRef":{"sid":"b245-8","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b245-10","bab":"الجزء 18","sec":"نسبة هذا الصوت","page":"ج18 ص358","text":"قال فانصرف إلينا مرة في نوبته فصلى الغداة مع الفجر على أسرة في صحن الدار في يوم صائف وجلس يسبح فما راعنا إلا خدم بيض قد دخلوا فسلموا عليه وقالوا إن أمير المؤمنين قد دعا بنا في هذه الساعة فأعدنا عليه الصوت الذي طرحته علينا فلم يرضه من أحد منا وأمرنا بالمصير إليك لنصححه عليك\nقال فأمر غلمانه فطرحوا لهم عدة كراسي فجلسوا عليها ثم قال لهم ردوا الصوت فردوه فلم يرضه من أحد منهم فدعا بجاريته عميم فردته عليهم فلم يرضه منها\nقال فتحول إليهم ثم اندفع فرد الصوت على الخدم فخرج الوصائف من حجر جواريه حتى وقفن حوالى الأسرة ودخل غلام من غلمانه وكان يستقي الماء فهجم على الصحن بدلوه وجاءت جارية على كتفها جرة من جرار المزملات حتى وقفت بالقرب منه\nقال وسبقتني عيناي فما كففت دموعها حتى فاضت ثم قطع الصوت حين استوفاه فرجع الوصائف الأصاغر سعيا إلى حجر الجواري وخرج الغلام السقاء يشتد إلى بغلة ورجعت الجارية الحاملة الجرة المزملة شدا إلى الموضع الذي خرجت منه فتبسم أبي وقال ما شأنك يا هارون فقلت يا أبت جعلني الله فداءك ما ملكت عيني قال وأبوك أيضا لم يملك عينه","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":7,"spl":"نسبة هذا الصوت","tags":["الجواري والنساء"],"loc":3276},
{"id":"b245-11","bab":"الجزء 18","sec":"مخارق وإبراهيم بن المهدي","page":"ج18 ص363","text":"وذكر هارون بن الزيات عن أصحابه قال جمع إبراهيم بن المهدي المغنين ذات يوم في منزله فأقاموا فلما\nدخلوا في الليل ثمل مخارق وسكر سكرا شديدا فسألوه أن يغني صوتا فغني هذا البيت من شعر عمر بن أبي ربيعة المخزومي\n(قال ساروا وأمعنوا واستقلوا ... وبرغمي لو استطعت سبيلا)\nانتهى منه إلى قوله واستقلوا وانثنى نائما فقال إبراهيم بن المهدي مهدوه ولا تزعجوه فمهدوه ونام حتى مضى أكثر الليل ثم استقل من نومه فانتبه وهو يغني تمام البيت\n(وبرغمي لو استطعت سبيلا ... )\nهو تمام البيت من حيث قطعه وسكت عليه من صوته قال فجعل إبراهيم يتعجب منه ويعجب منه من حضره من جودة طبعه وذكائه وصحة فهمه حدثنا يحيى بن علي بن يحيى المنجم\nقال حدثنا حماد بن إسحاق قال قال محمد بن الحسن بن مصعب قلت لإسحاق يوما أسألك بالله إلا صدقتني في مخارق وإبراهيم بن المهدي أيهما أحذق وأحسن غناء فقال لي إسحاق أجاد أنت والله ما تقاربا قط والدليل على فضل مخارق عليه أن إبراهيم لا يؤدي صوتا قديما ثقيلا جيدا أبدا ولا يستوفيه وإنما يغني الأهزاج والغناء الخفيف وأما الذي فيه عمل شديد فلا يصيبه\nأخبرني يحيى قال حدثنا أبو أيوب المديني قال حدثني بعض ولد سعيد بن سلم قال دخل مخارق على سعيد بن سلم فسأله حاجة فلما خرج قيل له أما تعرف هذا هذا مخارق فقال ويحكم دخل ولم نعرفه وخرج ولم نعرفه\nردوه فردوه فقال له دخلت علينا ولم نعرفك فلما عرفناك أحببنا ألا تخرج حتى نسمعك فقال له أي شيء تشتهي أن أسمعك فقال\n(يا ريح ما تصنعين بالدمن ... كم لك من محو منظر حسن)\nغناه مخارق فلما خرج قال لبعض بنيه أبوكم هذا نكس يشتهى على مثلي\n(يا ريح ما تصنعين بالدمن ... )\nخبرنا يحيى بن علي قال حدثنا حماد بن إسحاق قال حدثني عمي محمد قال سمعت أبي يقول وقد غنى مخارق الفسيله نعم الفسيلة غرس إبليس في الأرض أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد قال سمع محمد بن سعيد القارىء مهدية جارية يعقوب بن الساحر تغني صوتا لمخارق بحضرته وقد كانت أخذته عنه وهو\n(ما لقلبي يزداد في اللهو غيا ... والليالي قد أنضجتني كيا)\n(سهلت بعدك الحوادث حتى ... لست أخشى ولا أحاذر شيا)\nأحسنت فيه ما شاءت وانصرف محمد بن سعيد وقرأ على لحنه ( يا يحيى خذ الكتاب بقوة\nحدثني عمي قال حدثنا عبد الله قال حدثني محمد قال كنت عند مخارق أنا وهارون بن أحمد بن هشام فلعب مع هارون بالنرد فقمره مخارق مائتي رطل باقلا طريا فقال مخارق وأنتم عندي أطعمكم من لحم جزور من الصناعة يعني من صناعة أبيه يحيى بن ناووس الجزار\nقال ومر بهارون بن أحمد فصيل ينادي عليه فاشتراه بأربعة دنانير ووجه به إلى مخارق وقال يكون ما تطعمنا من هذا الفصيل فاجتمعنا وطبخ مخارق بيده جزورية وعمل من سنامه وكبده ولحمه غضائر شويت في التنور وعمل من لحمه لونا يشبه الهريسة بشعير مقشر في نهاية الطيب فأكلنا وجلسنا نشرب فإذا نحن بامرأة تصيح من الشط يا أبا المهنا الله الله في حلف زوجي علي بالطلاق أن يسمع غناءك ويشرب عليه فقال اذهبي وجيئي به فجاء فجلس فقال له ما حملك على ما صنعت فقال له يا سيدي كنت سمعت صوتا من صنعتك فطربت عليه حتى استخفني الطرب فحلفت أن أسمعه منك ثقة بإيجابك حق زوجتي وكانت زوجته داية هارون بن مخارق فقال وما هو الصوت فقال\n(بكرت علي فهيجت وجدا ... هوج الرياح وأذكرت نجدا)\n(أتحن من شوق إذا ذكرت ... نجد وأنت تركتها عمدا)\nالشعر لحسين بن مطير والغناء لمخارق ثقيل أول وفيه لإسحاق ثقيل أول آخر فغناه إياه وسقاه رطلا وأمره بالانصراف ونهاه أن يعاود وخرج فما لبثنا أن عادت المرأة تصرخ الله الله في يا أبا المهنا قد أعاد زوجي المشؤوم اليمين أنك تغنيه صوتا آخر فقال لها أحضريه فأحضرته أيضا فقال له ويلك مالي ولك أي شيء قصتك فقال له يا سيدي أنا رجل طروب وكنت قد سمعت صوتا لك آخر فاستفزني الطرب إلى أن حلفت بالطلاق ثلاثا أني أسمعه منك قال وما هو قال لحنك\n(أبلغ سلامة أن البين قد أفدا ... وأن صحبك عنها رائحون غدا)\n(هذا الفراق يقينا إن صبرت له ... أو لا فإنك منها ميت كمدا)\n(لا شك أن الذي بي سوف يهلكني ... إن كان أهلك حب قبله أحدا)","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":8,"spl":"مخارق وإبراهيم بن المهدي","tags":[],"song":1,"loc":3277,"partialRef":{"sid":"b2-21","gi":0,"vi":2,"side":1},"partial":1},
{"id":"b245-12","bab":"الجزء 18","sec":"مخارق وإبراهيم بن المهدي","page":"ج18 ص363","text":"غناه إياه مخارق وسقاه رطلا وقال له احذر ويلك أن تعاود فأنصرف ولم تلبث أن عاودت الصياح تصرخ يا سيدي قد عاود اليمين ثلاثة الله الله في وفي أولادي قال هاتيه فأحضرته فقال لها انصرفي أنت فإن هذا كلما انصرف حلف وعاد فدعيه يقيم يومه كله فتركته وانصرفت فقال له مخارق ما قصتك أيضا قال قد عرفتك يا سيدي أنني رجل طروب وكنت سمعت صوتا من صنعتك فاستخفني الطرب له فحلفت أني أسمعه منك قال وما هو قال\n(ألف الظبي بعادي ... ونفى الهم رقادي)\n(وعدا الهجر على الوصل ... بأسياف حداد)\n(قل لمن زيف ودي ... لست أهلا لودادي)\nال فغناه إياه وسقاه رطلا ثم قال يا غلام مقارع فجىء بها فأمر به فبطح وأمر بضربه فضرب خمسين مقرعة وهو يستغيث فلا يكلمه ثم قال له احلف بالطلاق أنك لا تذكرني أبدا وإلا كان هذا دأبك إلى الليل فحلف الطلاق ثلاثا على ما أمره به ثم أقيم فأخرج عن الدار فجعلنا نضحك بقية يومنا من حمقه\nأخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا أحمد بن محمد قال حدثني إسحاق بن عمر بن بزيع قال أتيت مخارقا ذات يوم ومعي زرزور الكبير لنقيم عنده فوجدته قد أخرج رأسه من جناح له وهو مشرف على المقابر يغني هذا البيت ويبكي\n(أين الملوك التي كانت مسلطة ... )\nال فاستحسنا ما سمعناه منه استحسان من لم يسمع قط غناء غيره فقال لنا انصرفوا فليس في فضل اليوم بعد ما رأيتم قال محمد وكان والله مخارق ممن لو تنفس لأطرب من يسمعه استماع نفسه","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":9,"spl":"مخارق وإبراهيم بن المهدي — الظباء تصغي لغناء مخارق","tags":["اللهو والمزاح","الوصف والطبيعة"],"loc":3278,"partial":1},
{"id":"b245-13","bab":"الجزء 18","sec":"الظباء تصغي لغناء مخارق","page":"ج18 ص368","text":"وذكر محمد بن الحسن الكاتب أن محمد بن أحمد بن يحيى المكي حدثه عن أبيه قال خرج مخارق مع بعض إخوانه إلى بعض المتنزهات فنظر إلى قوس مذهبه مع أحد من خرج معه فسأله إياها فكأن المسؤول ضن بها قال وسنحت ظباء بالقرب منه فقال لصاحب القوس أرأيت إن تغنيت صوتا فعطفت عليك به خدود هذه الظباء أتدفع إلي هذه القوس قال نعم فاندفع يغني\n\n(ماذا تقول الظباء ... أفرقة أم لقاء)\n(أم عهدها بسليمى ... وفي البيان شفاء)\n(مرت بنا سانحات ... وقد دنا الإمساء)\n(فما أحارت جوابا ... وطال فيها العناء)\nي هذه الأبيات ليحيى المكي ثقيل أول بالوسطى قال فعطفت الظباء راجعة إليه حتى وقفت بالقرب منه مستشرفة تنظر إليه مصغية تسمع صوته فعجب من حضر من رجوعها ووقوفها وناوله الرجل القوس فأخذها وقطع الغناء فعاودت الظباء نفارها ومضت راجعة على سننها\nقال ابن المكي وحدثني رجل من أهل البصرة كان يألف مخارقا ويصحبه قال كنت معه مرة في طيار ليلا وهو سكران فلما توسط دجلة اندفع بأعلى صوته فغنى فما بقي أحد في الطيار من ملاح ولا غلام ولا خادم إلا بكى من رقة صوته ورأيت الشمع والسرج من جانبي دجلة في صحون القصور والدور يتساعون بين يدي أهلها يستمعون غناءه\nحدثني الصولي قال حدثني محمد بن عبد الله التميمي الحزنبل قال كنا في مجلس ابن الأعرابي إذ أقبل رجل من ولد سعيد بن سلم كان يلزم ابن الأعرابي وكان يحبه ويأنس به فقال له ما أخرك عني فاعتذر\nبأشياء منها أنه قال كنت مع مخارق عند بعض بني الرشيد فوهب له مائة ألف درهم على صوت غناه إياه فاستكثر ابن الأعرابي ذلك واستهوله وعجب منه وقال له بأي شيء غناه قال غناه بشعر العباس بن الأحنف\n(بكت عيني لأنواع ... من الحزن وأوجاع)\n(وإني كل يوم عندكم ... يحظى بي الساعي)\nفقال ابن الأعرابي أما الغناء فما أدري ما هو ولكن هذا والله كلام قريب مليح لحن مخارق في هذين البيتين ثقيل أول من جامع صنعته وفيهما لإبراهيم الموصلي ثاني ثقيل بالوسطى عن عمرو بن بانة\nوذكر حبش أن فيهما لإبراهيم بن المهدي لحنا ماخوريا أخبرني أحمد بن جعفر جحظة قال حدثني هبة الله بن إبراهيم بن المهدي قال غنت شارية يوما بحضرة أبي صوتا فأحد النظر إليها وصبر حتى قطعت نفسها ثم قال لها أمسكي فأمسكت فقال لها قد عرفت إلي أي شيء ذهبت أردت أن تتشبهي بمخارق في تزايده قالت نعم يا سيدي قال\nإياك ثم إياك أن تعودي فإن مخارقا خلقه الله وحده في طبعه وصوته ونفسه يتصرف في ذلك أجمع كيف أحب ولا يلحقه في ذلك أحد وقد أراد غيرك أن يتشبه به في هذه الحال فهلك وافتضح ولم يلحقه فلا أسمعنك تتعرضين لمثل هذا بعد وقتك هذا","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":9,"spl":"مخارق وإبراهيم بن المهدي — الظباء تصغي لغناء مخارق","tags":[],"song":2,"loc":3279},
{"id":"b245-15","bab":"الجزء 18","sec":"غلمان المعتصم يتركونه لدى سماعهم غناء مخارق — مخارق ومحمد الأمين","page":"ج18 ص370 – ج18 ص371","text":"أخبرني عمي قال حدثني علي بن محمد بن نصر البسامي قال حدثني خالي أبو عبد الله عن أبيه قال كنا بين يدي المعتصم ذات ليلة نشرب إلى أن سكرنا جميعا فقام فنام وتوسدنا أيدينا ونمنا في مواضعنا ثم انتبه فصاح فلم يجبه أحد وسمعنا صياحه فتبادرنا نسأل عن الغلمان فإذا مخارق قد انتبه قبلنا فخرج إلى الشط يتنسم الهواء واندفع يغني فتلاحق به الغلمان جميعا فجئت إلى المعتصم فأخبرته وقلت مخارق على الشط يغني والغلمان قد اجتمعوا عليه فليس فيهم فضل لشيء غير استماعه فقال لي يا بن حمدون عذر والله وأي عذر ثم جلس وجلسنا بين يديه إلى السحر\nوذكر محمد بن الحسن الكاتب أن أبان بن سعيد حدثه أن المأمون سأل إسحاق عن إبراهيم بن المهدي ومخارق فقال يا أمير المؤمنين إذا تغنى إبراهيم بعلمه فضل مخارقا وإذا تغنى مخارق بطبعه وفضل صوته فضل إبراهيم فقال له صدقت\nنسخت من كتاب هارون بن الزيات حدثني هارون بن مخارق عن أبيه قال دعاني محمد الأمين يوما وقد اصطبح فاقترح علي\n(استقبلت ورق الريحان تقطفه ... وعنبر الهند والوردية الجددا)\n(ألست تعرفني في الحي جارية ... ولم أخنك ولم ترفع إلي يدا)\nغنيته إياه فطرب طربا شديدا وشرب عليه ثلاثة أرطال ولاء وأمر لي بألف دينار وخلع علي جبة وشي كانت عليه مذهبه ودراعة مثلها وعمامة مثلها تكاد تعشي البصر من كثرة الذهب فلما لبست ذلك ورآه علي ندم وكان كثيرا ما يفعل ذلك فقال لبعض الخدم قل للطباخ يأتينا بمصلية معقودة الساعة فأتى بها فقال لي كل معي وكنت أعرف الناس بمذهبه وبكراهته لذلك فامتنعت فحلف أن آكل معه فحين أدخلت يدي في الغضارة رفع يده ثم\nقال أف نغصتها علي والله وقذرتها عندي بإدخالك يدك فيها ثم رفس القصعة رفسة فإذا هي في حجري وودكها يسيل على الخلعة حتى نفذ إلى جلدي فقمت مبادرا فنزعتها وبعثت بها إلى منزلي وغيرت ثيابي وعدت وأنا مغموم منها وهو يضحك فلما رجعت إلى منزلي جمعت كل صانع حاذق فجهدوا في إخراج ذلك الأثر منها فلم يخرج ولم أنتفع بها حتى أحرقتها فأخذت ذهبها وضرب الدهر بعد ذلك ضرباته","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":10,"spl":"غلمان المعتصم يتركونه لدى سماعهم غناء مخارق — مخارق ومحمد الأمين — مخارق والمأمون","tags":["الجواري والنساء"],"loc":3280},
{"id":"b245-16","bab":"الجزء 18","sec":"مخارق والمأمون","page":"ج18 ص372","text":"ثم دعاني المأمون يوما فدخلت إليه وهو جالس وبين يديه مائدة عليها رغيفان ودجاجتان فقال لي تعال فكل فامتنعت فقال لي تعال ويلك فساعدني فجلست فأكلت معه حتى استوفى ووضع النبيذ ودعا علوية\nفجلس وقال لي يا مخارق أتغني\n(أقول التماس العذر لما ظلمتني ... وحملتني ذنبا وما كنت مذنبا)\nقلت نعم يا سيدي قال غنه فغنيته فعبس في وجهي ثم قال قبحك الله أهكذا يغني هذا ثم أقبل علي علوية فقال أتغنيه قال نعم يا سيدي قال غنه فغناه فوالله ما قاربني فيه فقال أحسنت والله وشرب رطلا وأمر له بعشرة آلاف درهم واستعاده ثلاثا وشرب عليه ثلاثة أرطال يعطيه مع كل عشرة آلاف درهم ثم خذف بإصبعه\nوقال برق يمان وكان إذا أراد قطع الشرب فعل ذلك وقمنا فعلمت من أين أتيت فلما كان بعد أيام دعاني فدخلت إليه وهو جالس في ذلك الموضع بعينه يأكل هناك فقال لي تعال ويلك فساعدني فقلت الطلاق لي لازم إن فعلت فضحك ثم\nقال ويلك أتراني بخيلا على الطعام لا والله ولكنني أردت أن أؤدبك إن السادة لا ينبغي لعبيدها أن تؤاكلها أفهمت فقلت نعم قال فتعال الآن فكل على الأمان فقلت أكون إذا أول من أضاع تأديبك إياه واستحق العقوبة من قريب فضحك حتى استغرب ثم أمر لي بألف دينار ومضيت إلى حجرتي المرسومة لي للخدمة وأتيت هناك بطعام فأكلت ووضع النبيذ ودعاني وبعلوية فلما جلسنا قال له يا علي أتغني\n(ألم تقولي نعم قالت أرى وهما ... مني وهل يؤخذ الإنسان بالوهم)\nفقال نعم يا سيدي فقال هاته فغناه فعبس في وجه وبسر وقال قبحك الله أتغني هذا هكذا ثم أقبل علي فقال أتغنيه يا مخارق فقلت نعم يا سيدي وعلمت أنه أراد أن يستقيد لي من علويه ويرفع مني وإلا فما أتى علويه بما يعاب فيه فغنيته فطرب وشرب رطلا وأمر لي بعشرة آلاف درهم وفعل ذلك ثلاث مرات كما فعل به ثم أمر بالانصراف فانصرفنا وما عاودت بعد ذلك مؤاكلة خليفة إلى وقتنا هذا","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":10,"spl":"غلمان المعتصم يتركونه لدى سماعهم غناء مخارق — مخارق ومحمد الأمين — مخارق والمأمون","tags":["اللهو والمزاح"],"loc":3281},
{"id":"b245-17","bab":"الجزء 18","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج18 ص374","text":"\n(استقبلت ورق الريحان تقطفه ... وعنبر الهند والوردية الجددا)\n(ألست تعرفني في الحي جارية ... ولم أخنك ولم تمدد إلي يدا)\nلشعر فيما يقال لعمر بن أبي ربيعة والغناء للغريض خفيف رمل بالسبابة في مجرى الوسطى عن إسحاق وأصله يماني وفيه لابن جامع هزج\n(أقول التماس العذر لما ظلمتني ... وحملتني ذنبا وما كنت مذنبا)\n(هبيني امرأ إما بريئا ظلمته ... وإما مسيئا قد أناب وأعتبا)\nالشعر للأحوص والغناء لمالك خفيف رمل بالوسطى عن عمرو\n(ألم تقولي نعم قالت أرى وهما ... مني وهل يؤخذ الإنسان بالوهم)\n(قولي نعم إن لا - إن قلت - قاتلتي ... ماذا تريدين من قتلي بغير دم)\nلغناء لسياط خفيف رمل بالبنصر عن عمرو ولم يقع إلي لمن الشعر قال هارون وحدثني أبو معاوية الباهلي قال حضرت علويه ومخارقا مجتمعين في مجلس فغنى علويه صوتا فأحسن فيه وأجاده فأعاده مخارق وبرز عليه وزاد فرده علوية وتعمل فيه واجتهد فزاد على مخارق فجثا مخارق على ركبتيه وغناه وصاح فيه حتى اهتز منكباه فما ظننا إلا أن الأرض قد زلزلت بنا وغلب والله ما سمعنا على عقولنا ونظرت إلى لون علويه وقد امتقع وطار دمه فلما فرغ مخارق توقعنا أن يغني علويه فما فعل ولا غنى بقية يومه قال وكان مخارق إذا صاح قطع أصحاب النايات أخبرني وسواسة بن الموصلي وهو أحمد بن إسماعيل بن إبراهيم قال حدثنا حماد بن إسحاق قال\nقال لي مخارق دعاني يوما محمد المخلوع فدخلت عليه وعنده إبراهيم بن المهدي فقال غنني يا مخارق فغنيته أصواتا عديدة فلم يطرب لها وقال هذا كله معاد فغنني\n(لقد أزمعت للبين هند زيالها ... )\nقلت والله ما أحسنه فقال غنني\n(لا والذي نحرت له البدن ... )\nقلت لا والله ما أحسنه فقال غنني\n(يا دار سعدى سقى أطلالك الديما ... )\nقلت لا والله لا أحسنه فغضب وقال ويلك أسألك عن ثلاثة أصوات فلا تحسن منها واحدا فقال له إبراهيم بن المهدي ما ذنبه إسحاق أستاذه وعليه يعتمد وهو يضايقه في صوت يعلمه إياه فقلت قد والله صدق ما يعطيني شيئا ولا يعلمنيه\nقال فما دواؤه فقد والله أعياني فقال له إبراهيم توكل به من يصب على رأسه العذاب حتى يعلمه مائة صوت قال أما هذا فبعيد ولكن اذهب إليه عني فمره أن يعلمك هذه الثلاثة الأصوات فإن فعل وإلا فصب السوط على رأسه حتى يعلمك فدخلت إلى إسحاق فجلست بغير أمره وسلمت سلاما منكرا ثم أقبلت عليه فقلت يأمرك أمير المؤمنين أن تعلمني كذا وكذا قال ما أحسنه\nفقلت إني أنفذ فيك ما أمرني به فقال تنفذ في ما أمرت به ألا تستحي ويحك مني ومن تربيتي إياك قلت فلا بد من أن تعلمني ما أمرك به أمير المؤمنين\nقال فإني لست أحسنه ولكن فلانة تحسنه هاتوها فجاءت وجعلت تطارحني حتى أخذت الأصوات الثلاثة وجعل كل من جاء يومئذ لا يحجبه ليروني وجاريته تطارحني فلما أخذت الأصوات رجعت إلى محمد وأخبرته الخبر وحضر إسحاق فغنيته إياها فطرب وجعل إبراهيم بن المهدي يقول أحسن والله أحسن والله فلما فرغت\nقال إسحاق لا والله ما أحسن ولا أصاب هو ولا إبراهيم في استحسانه ولقد جهدت الجارية جهدها أن يأخذه عنها فلم يتوجه له ثم اندفع فغناها فكأني والله كنت ألعب عندما سمعت ثم أقبل على إبراهيم بن المهدي فقال له كم أقول لك ليس هذا من علمك ولا مما تحسنه وأنت تكابر وتدخل نفسك فيما لا تحسنه فقال ألا تراه يا أمير المؤمنين يصيرني مغنيا فقال له إسحاق ولم تجحد ذلك أو أسررت إلي منه شيئا لم تظهره للناس وتعلمهم إياه ومتى صرت تأنف من هذا وأنت تتبجح به فليتك تحسنه والله ما تفرق بين الخطأ والصواب فيه وإن شئت الآن ألقيت عليك ثلاثين مسألة من أي علم شئت فإن أجبت في واحدة منهن وإلا علمت أنك متكلف فقال يا أمير المؤمنين يستقبلني بهذا بين يديك\nقال وما هذا مما لا أستقبلك به فقال له محمد نعم اختر ما شئت حتى نسألك عنه فقال إنما يفعل هذا الصبيان وانكسر حتى رحمته فقلت لمحمد يا أمير المؤمنين لعلك ترى مع هذا القول أنه لا يحسن بلى والله إنه ليحسن كل شيء وما يقدر أحد أن يقول هذا غيري وإنه ليتقدم كثيرا من الناس في كل شيء فجعل محمد يضحك وهو يقول تشجه بيد وتدهنه بيد وتجرحه بيد وتأسوه بيد","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء","tags":[],"song":3,"loc":3282,"partial":1},
{"id":"b245-18","bab":"الجزء 18","sec":"نسبة هذه الأصوات","page":"ج18 ص378","text":"\n(لقد أزمعت للبين هند زيالها ... وزموا إلى أرض العراق جمالها)\n(فما ظبية أدماء واضحة القرا ... تنص إلى برد الظلال غزالها)\n(تحت بقرنيها برير أراكة ... وتعطو بظلفيها إذا الغصن طالها)\n(بأحسن منها مقلة ومقلدا ... وجيدا إذا دانت تنوط شكالها)\nالشعر لكثير والغناء لمعبد خفيف ثقيل أول بالوسطى عن عمرو وفيه لابن سريج في الثالث والثاني ثقيل أول بالسبابة في مجرى البنصر عن إسحاق ولإبراهيم ثقيل أول بالوسطى عن عمرو في الثاني ثم في الثالث وفي كتاب حكم لحكم فيه خفيف ثقيل وعن حبش لطويس فيه رمل بالوسطى وذكر أيضا أن لحن معبد ثاني ثقيل\n(يا دار سعدى سقى أطلالك الديما ... مسقي الروايا وإن هيجت لي سقما)\n(دار خلت وعفت منها معالمها ... إلا الثمام وإلا النؤي والحمما)\nلغناء لقفا النجار ثقيل أول بالوسطى عن عمرو والهشامي وإبراهيم\n(لا والذي نحرت له البدن ... وله بمكة قبل الركن)\n(ما زلت يا سكني أخا أرق ... متكنفا بي الهم والحزن)\n(أخشى عليك وبعضه شفق ... أن يفتنوك وأنت مفتتن)\nلغناء لابن سريج رمل بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر الهشامي أنه لسليمان الوادي أوله فيه لحن ونسبه إبراهيم إلى ابن عباد ولم يجنسه أخبرني عمي حدثنا أحمد بن أبي طاهر قال حدثني عبد الوهاب المؤذن قال انحدرنا مع المعتصم من السن ونحن في حراقته وحضر وقت الأذان فأذنت فلما فرغت من الأذان اندفع مخارق بعدي فأذن وهو جاث على ركبتيه فتمنيت والله أن دجلة أهرقت لي فغرقت فيها","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":12,"spl":"نسبة هذه الأصوات — مخارق والمعتصم","tags":["السفر والحج"],"song":3,"loc":3283},
{"id":"b245-19","bab":"الجزء 18","sec":"مخارق والمعتصم","page":"ج18 ص379","text":"أخبرني عمي قال حدثني عبد الله بن عبد الله بن حمدون قال حدثني أبي قال غضب المعتصم على مخارق فأمر به أن يجعل في المؤذنين ويلزمهم ففعل ذلك وأمهل حتى علم أن المعتصم يشرب وأذنت العصر فدخل هو إلى الستر حيث يقف المؤذن للسلام ثم رفع صوته جهده\nوقال السلام عليك يا أمير المؤمنين ورحمة الله وبركاته الصلاة يرحمك الله فبكى حتى جرت دموعه وبكى كل من حضره ثم قال أدخلوه إلي ثم أقبل علينا\nوقال سمعتم هكذا قط هذا الشيطان لا يترك أحدا يغضب عليه فأمر به فأدخل إليه فقبل الأرض بين يديه فدعاه المعتصم إليه وأعطاه يده فقبلها وأمره بإحضار عوده فأحضر فأعاده إلى مرتبته وجدت في بعض الكتب عن علي بن محمد البسامي عن جده حمدون بن إسماعيل قال غنى علويه يوما بين يدي إسحاق الموصلي\n(هجرتك إشفاقا عليك من الأذى ... وخوف الأعادي واتقاء النمائم)\nقال له إسحاق أحسنت يا أبا الحسن أحسنت واستعاده ثلاثا وشرب فقال له علويه يا أستاذ أين أنا الآن من صاحبي يعني مخارقا مع قولك هذا لي فقال لا ترد أن تعرف هذا قال بي والله إلى معرفته أعظم الحاجة فقال إذا غنيتما ملكا اختاره عليك وأعطاه الجائزة دونك فضجر علويه وقال لإسحاق أف من رضاك وغضبك","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":12,"spl":"نسبة هذه الأصوات — مخارق والمعتصم","tags":[],"loc":3284},
{"id":"b245-20","bab":"الجزء 18","sec":"نسبة هذا الصوت","page":"ج18 ص380","text":"\n(هجرتك إشفاقا عليك من الأذى ... وخوف الأعادي واتقاء النمائم)\n(وإني وذاك الهجر لو تعلمينه ... كسالية عن طفلها وهي رائم)\nلشعر لهلال بن عمر الأسدي والغناء لعلويه ثقيل أول بالوسطى عن عمرو وقال الجاحظ قال أبو يعقوب الخريمي ما رأيت كثلاثة رجال كانوا يأكلون الناس أكلا حتى إذا رأوا ثلاثة رجال ذابوا كما يذوب الرصاص على النار كان هشام بن الكلبي علامة نسابة ورواية للمثالب عيابة فإذا رأى الهيثم بن عدي ذاب كما يذوب الرصاص وكان علي بن الهيثم جونقا مفقعا نيا صاحب تقعر يستولي على كل كلام لا يحفل بخطيب ولا شاعر فإذا رأى موسى الضبي ذاب كما يذوب الرصاص وكان علويه واحد الناس في الغناء رواية وحكاية ودراية وصنعة وجودة ضرب وأضراب وحسن خلق فإذا رأى مخارقا ذاب كما يذوب الرصاص على النار\nأخبرني علي بن عبد العزيز الكاتب عن ابن خرداذبة قال هوي مخارق جارية لأم جعفر فحج في السنة التي حجت فيها أم جعفر بسبب الجارية فقال أحمد بن هشام فيه\n(يحج الناس من بر وتقوى ... وحج أبي المهنا للتصابي)\nقال وكان المعتصم قد وهب دار مخارق لما قدم بغداد ليونازة خليفة الأفشين فقال عيسى بن زينب في ذلك\n(يا دار غير رسمها يونازه ... وبقي مخارق قاعدا في فازه)\n(لا تجزعن أبا المهنا إنها ... دنيا تنال بذلة وعزازه)\nأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة وحدثني محمد بن يحيى الصولي قال وجدت بخط عبد الله بن الحسين حدثني الحسن بن إبراهيم بن رياح قالا كان مخارق يهوى جارية لأم جعفر يقال لها بهار ويستر ذلك عن أم جعفر حتى بلغها ذلك فأقصته ومنعته من المرور ببابها وكان بها كلفا\nقال الصولي في خبره فلما علم أن الخبر قد بلغ أم جعفر قطعها وتجافاها إجلالا لأم جعفر وطمعا في السلو عنها وضاق ذرعه بذلك فبينا هو ذات ليلة في زلال وقد انصرف من دار المأمون وأم جعفر تشرب على دجلة إذ حاذى دارها فرأى الشمع يزهر فيها فلا صار بمسمع منها ومرأى اندفع فغنى\n(إن تمنعوني ممري قرب دارهم ... فسوف أنظر من بعد إلى الدار)\n(سيما الهوى شهرت حتى عرفت بها ... أني محب وما بالحب من عار)\n(ما ضر جيرانكم - والله يصلحهم ... لولا شقائي - إقبالي وإدباري)\n(لا يقدرون على منعي ولو جهدوا ... إذا مررت وتسليمي بإضماري)\nلشعر للعباس بن الأحنف والغناء لمخارق رمل بالوسطى فقالت أم جعفر مخارق والله رده فصاحوا بملاحه قدم فقدم وأمره الخدم بالصعود فصعد وأمرت له أم جعفر بكرسي وصينية فيها نبيذ فشرب وخلعت عليه وأمرت الجواري فغنين ثم ضربن عليه فغنى فكان أول ما غنى\n(أغيب عنك بود ما يغيره ... نأي المحل ولا صرف من الزمن)\n(فإن أعش فلعل الدهر يجمعنا ... وإن أمت فقتيل الهم والحزن)\n(قد حسن الله في عيني ما صنعت ... حتى أرى حسنا ما ليس بالحسن)\nلشعر للعباس بن الأحنف والغناء لمخارق رمل قال فاندفعت بهار فغنت كأنها تباينه وإنما أجابته عن معنى ما عرض لها به\n(تعتل بالشغل عنا ما تلم بنا ... والشغل للقلب ليس الشغل للبدن)\nفطنت أم جعفر أنها خاطبته بما في نفسها فضحكت وقالت ما سمعنا بأملح مما صنعتما وقال إسماعيل بن يونس في خبره ووهبتها له وقال هارون بن الزيات حدثني هارون بن مخارق عن أبيه أن المأمون سأله لما قدم مكة عن أحدث صوت صنعه فغناه\n(أقبلت تحصب الجمار وأقبلت ... لرمي الجمار من عرفات)\n(ليتني كنت في الجمار أنا المحصوب ... من كف زينب حصيات)\nلشعر للنميري والغناء لمخارق خفيف رمل بالبنصر قال فضحك ثم قال لعمري إن هذا لأحدث ما صنعت ولقد قنعت بيسير وما أظن بهار كانت تبخل عليك بأن تحصبك بحصاة كما تحصب الجمار واستعاده الصوت مرات أخبرني جعفر بن قدامة قال حدثني هارون بن مخارق قال حدثني أبي قال كنا عند المأمون يوما فجاءه الخادم الحرمي فأسر إليه شيئا فوثب فدخل معه ثم أبطأ علينا ساعة\nوعاود وعينه تذرف فقال لنا دخلت الساعة إلى جارية لي كنت أتحظاها فوجدتها في الموت فسلمت عليها فلم تستطع رد السلام إلا إيماء بإصبعها فقلت هذين البيتين\n(سلام على من لم يطق عند بينه ... سلاما فأومى بالبنان المخضب)\n(فما اسطعت توديعا له بسوى البكا ... وذلك جهد المستهام المعذب)","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":13,"spl":"نسبة هذا الصوت","tags":["الحب والغزل","الجواري والنساء"],"song":4,"loc":3285}]);
window.__BOOK__['p09'].push([{"id":"b245-21","bab":"الجزء 18","sec":"نسبة هذا الصوت","page":"ج18 ص380","text":"م قال غن فيها يا مخارق ففعلت فما استعادني ذلك الغناء قط إلا بكى أخبرني الحسين بن القاسم الكوكبي إجازة قال حدثني أحمد بن أبي العلاء قال حدثني أبي قال حج رجل مع مخارق فلما قضيا الحج وعادا قال له الرجل في بعض طريقه بحقي عليك غنني صوتا فغناه\n(رحلنا فشرقنا وراحوا فغربوا ... ففاضت لروعات الفراق عيون)\nرفع الرجل يده إلى السماء وقال اللهم إني أشهدك أني قد وهبت حجتي له وتوفي مخارق في أول خلافة المتوكل وقيل بل في آخر خلافة الواثق وذكر ابن خرداذبة أن سبب وفاته أنه أكل قنبيطية باردة فقتلته من فوره\n(إذا مت فادفني إلى جنب كرمة ... تروي مشاشي بعد موتي عروقها)\n(ولا تدفنني بالفلاة فإنني ... أخاف إذا ما مت ألا أذوقها)\nعروضه من الطويل ويروى\n(إذا رحت مدفونا فلست أذوقها ... )\nالشعر لأبي محجن الثقفي والغناء لإبراهيم الموصلي ثقيل أول بالوسطى عن عمرو وفيه لحنين لحن ذكره إبراهيم ولم يجنسه إلى هنا انتهى الجزء الثامن عشر من كتاب الأغاني ويليه الجزء التاسع عشر وأوله ذكر أبي محجن ونسبه\nبسم الله الرحمن الرحيم","topic":"ذكر مخارق وأخباره","topicNo":245,"sp":14,"spl":"نسبة هذا الصوت","tags":[],"song":1,"loc":3286,"partial":1}]);